-- 경기도의회 행정사무감사 회의록(경기연구원 관련) 이관 데이터 (자동 생성: tools/import_audit.py)
-- 게시판 코드 audit. 여러 번 실행해도 중복되지 않습니다.
insert into public.boards (code,name,members_only,admin_only_write) values ('audit','행정사무감사',false,true) on conflict (code) do nothing;
create unique index if not exists posts_legacy_idx on public.posts ((attachments->>'legacy_id')) where attachments ? 'legacy_id';
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2013.11.15. 금요일] 경기개발연구원 — 기획재정위원회 2013년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제8대 경기도의회 기획재정위원회</b> · 2013년도 행정사무감사(2013. 11. 12. ~ 2013. 11. 25.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=7169" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2013년도 행정사무감사
</p>
<h4>기획재정위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일 시 : 2013년 11월 15일(금)
</p>
<p>장 소 : 경기개발연구원 회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시20분 감사개시)
</p>
<p><b>○ 위원장 김현삼 </b> 좌석을 정돈해 주시기 바랍니다. 우리 위원님들 연일 계속되는 행정사무감사에 수고 많으십니다. 그러면 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기개발연구원에 대한 2013년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획재정위원회 감사위원장 김현삼 위원입니다. 오늘은 우리 위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 
</p>
<p style="padding-left:1.2em">  여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2014년도 예산안 심사 자료 및 도정의 현실을 파악하여 도민의 삶의 질 향상에 기여하고자 함이 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 따라서 오늘은 경기도의 싱크탱크인 경기개발연구원의 운영 실태를 감사하는 것이니만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러서 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 실장, 부장, 센터장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하기 위해 먼저 선서를 하셔야 합니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2013년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다. 경기개발연구원 원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 경기개발연구원 부원장 나왔습니까? 
</p>
<p><b>○ 부원장 김대호 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 기획조정본부장 나왔습니까? 
</p>
<p><b>○ 기획조정본부장 강철구 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 사무처장 나왔습니까?
</p>
<p><b>○ 사무처장 김경희 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 전략연구센터장 나왔습니까? 
</p>
<p><b>○ 전략연구센터장 이정훈 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 미래비전연구실장 나왔습니까? 
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 자치경영연구실장 나왔습니까? 
</p>
<p><b>○ 자치경영연구실장 박충훈 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 도시ㆍ주택연구실장 나왔습니까?
</p>
<p><b>○ 도시ㆍ주택연구실장 이성룡 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 창조경제연구실장 나왔습니까?
</p>
<p><b>○ 창조경제연구실장 문미성 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 교통연구실장 나왔습니까? 
</p>
<p><b>○ 교통연구실장 류시균 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 환경연구실장 나왔습니까? 
</p>
<p><b>○ 환경연구실장 김동영 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 사회경제센터장 나왔습니까?
</p>
<p><b>○ 사회경제센터장 김희연 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 통일ㆍ동북아센터장 나왔습니까?
</p>
<p><b>○ 통일ㆍ동북아센터장 김동성 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 의정연구센터장 나왔습니까?
</p>
<p><b>○ 의정연구센터장 신원득 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인을 대표하여 경기개발연구원 원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에 서서 오른손만 들어주시기 바랍니다. 그러면 선서를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관업무에 대한 2013년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2013년 11월 15일 원장 홍순영. 
</p>
<p><b>○ 위원장 김현삼 </b> 모두 자리에 앉아주시기 바랍니다. 그러면 경기개발연구원 원장은 나오셔서 간부소개와 업무보고를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 안녕하십니까? 경기개발연구원장 홍순영입니다. 오늘 경기도의회 기획재정위원회 행정사무감사에 존경하는 김현삼 위원장님과 위원님들을 모시고 연구원의 주요업무를 보고드리게 되어 감사의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  우리 연구원은 동북아 미래를 선도하는 경기도의 싱크탱크로서 경기도민의 삶의 질 향상을 위해 경기도정 현안을 해결하고 경기도 미래비전을 제시하는 등 임직원 모두가 열정을 다해 정책개발을 추진해 가고 있습니다. 향후에도 연구원의 발전을 위하여 기획재정위원회 위원님들의 많은 관심과 성원을 부탁드립니다.
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 연구원의 주요 간부를 소개해 드리겠습니다. 먼저 김대호 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  강철구 기획조정본부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김경희 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정훈 전략연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 미래비전연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  박충훈 자치경영연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이성룡 도시ㆍ주택연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  문미성 창조경제연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  류시균 교통연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동영 환경연구실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김희연 사회경제센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 통일ㆍ동북아센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  신원득 의정연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 연구원의 주요업무를 보고드리겠습니다. 배부해 드린 보고자료의 목차를 봐주시기 바랍니다. 보고순서는 일반 및 재정운영 현황 그리고 2013년 주요성과 그리고 내년도 2014년 주요 연구사업계획 순입니다.
</p>
<p style="padding-left:1.2em">  먼저 일반 및 재정운영 현황입니다. 일반현황, 재정운영 현황 순으로 보고드리겠습니다. 3쪽을 봐주시기 바랍니다. 일반현황입니다. 저희 연구원은 1995년에 개원하여 경기도의 중장기 비전 제시와 정책개발 기능을 수행하고 있습니다. 부서별 주요기능은 자료를 참조하시기 바랍니다. 참고로 아시는 바와 같이 사회경제센터와 의정연구센터 2개의 센터를 올해 2월 1일 자로 신설한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 4쪽의 기구 및 인력에 대해 보고드리겠습니다. 우리 연구원은 현재 1본부 1처 6실 4센터 4부 3팀의 조직으로 구성되어 있습니다. 이 중 연구부서로는 전략연구센터, 미래비전연구실 등 10개의 실과 센터가 있습니다. 지난 2월 신설된 사회경제센터와 의정연구센터의 구체적인 사항은 제2장 2013년 주요성과 부분에서 보고드리도록 하겠습니다. 우리 원의 인력은 현재 원장 1명, 부원장 1명, 연구직 54명, 관리ㆍ정보ㆍ기능직 23명 등 79명의 정규직원과 계약직원 등 총 191명이 근무하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 재정운영 현황에 대해 보고드리겠습니다. 올해의 총 예산규모는 231억 원으로 일반회계 176억 원, 수탁용역사업 특별회계 55억 원입니다. 일반회계의 수입ㆍ지출내역을 말씀드리겠습니다. 수입항목은 경기도 출연금이 전체의 61%인 107억 7,000만 원으로 가장 많습니다. 지출항목으로는 인건비가 46%인 81억 원으로 가장 많으며 연구사업비가 69억 원으로 전체의 40%를 차지하고 있습니다. 재정난 극복을 위해 저희 연구원은 자체 수입을 확대하기 위한 부단한 노력을 기울이고 있으며 수탁과제 전출금 증액, 시장가격에 맞는 용역사업 수주 등 다각도에서 해결책을 모색하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 6쪽 기금입니다. 연구원의 기금은 총 197억 원으로 모두 안전한 금융기관에 예치하고 있습니다. 우리 원은 도 산하 공공기관으로서 위험한 투자는 가능한한 지양하고 있으며 안전성과 수익성을 함께 고려한 금융상품에 기금을 운용하고 있다는 것을 알려드립니다. 출연기관 및 예치기관별 현황은 자료를 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 2013년 주요성과에 대해 보고드리겠습니다. 보고자료 9쪽부터 34쪽이 되겠습니다. 먼저 9쪽의 2013년 연구사업 목표입니다. 우리 연구원은 동북아 미래를 선도하는 경기도의 싱크탱크라는 비전을 달성하기 위해 2013년 연구사업 목표를 새정부 출범에 따른 대 중앙정부 정책개발 강화, 민선5기 후반기 경기도의 정책대응방안 제시, 현장 밀착형 정책개발 이렇게 세 가지로 제시하였습니다. 그리고 이를 달성하기 위해 8개 분야의 중점사업과 3개의 추진전략을 설정한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 10쪽 2013년 주요성과에 대해 보고드리겠습니다. 2013년의 주요성과는 크게 중장기 비전수립, 정책개발, 도정현안대응, 신규 정책수요 대응, 대내외 소통강화 이렇게 다섯 가지로 구분할 수 있으며 분야별 세부사항은 다음과 같습니다. 
</p>
<p style="padding-left:1.2em">  먼저 경기도 중장기 비전수립 분야입니다. 첫 번째, 경기도 2020 주택종합계획을 수립하였습니다. 이는 주택법, 주택조례에 의거 2006년에 기 수립된 주택종합계획을 수정ㆍ보완하여 경기도의 주택정책의 중장기 비전을 제시하고 전략과제를 도출해 내기 위한 것입니다. 본 연구를 통해 경기도의 주택정책의 기본방향과 분야별 추진방안을 적절히 제시한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  두 번째, 메가수도권의 발전 비전과 전략구상입니다. 위원님들께서도 잘 아시는 바와 같이 최근에는 고용과 신성장동력산업 창출, 저발전지역 해소문제, 정부부처의 세종시 이전, 접경지역 활용가치 증대 등 여러 가지 사회적 이슈를 불러일으키는 요인들이 경기도에 많이 있습니다. 이에 따라 수도권이라는 서울ㆍ인천ㆍ경기의 한정된 공간이 아니라 그 인접지역까지 확대한 광역경제권의 적절한 비전과 전략을 구상하고 있습니다. 
</p>
<p style="padding-left:1.2em">  세 번째는 12쪽의 경기도 안전사회 실현을 위한 중점과제 연구입니다. 우리나라의 안전망은 아직 선진국에 비해 취약하고 안전에 대한 국민의식도 낮은 수준입니다. 이에 중앙정부와는 별도로 우리 경기도 차원에서 실천가능한 안전정책을 추진하기 위해 사회 여러 분야의 안전복지 서비스 개선, 안전한 환경의 조성, 소방업무와 시군 재난관리업무의 융합행정체계 구축 등 다각도에서 그 방법을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  네 번째는 경기도 가구산업 종합발전계획 수립입니다. 경기도 가구산업의 경쟁력 강화를 위해 필요한 정책수요를 파악하고 종합지원센터 및 공동전시판매장 건립 타당성을 면밀히 검토하여 실효성 있는 지원방안이 되도록 노력하고 있습니다. 
</p>
<p style="padding-left:1.2em">  다섯 번째는 어린이들이 그리는 미래사회와 경기도의 역할입니다. 위원님들도 우리 어린이들이 생각하는 우리의 미래가 어떤지 궁금하게 생각하신 적이 있을 겁니다. 본 연구는 시민의식 조사에서 일반적으로 고려되지 않은 어린이집단을 대상으로 의식조사를 했다는 점이 다소 새롭습니다. 어린이들이 바라는 미래사회의 모습을 우선순위부터 말씀드리면 1위가 폭력과 범죄가 없는 나라, 2위가 자연환경이 깨끗한 나라, 3위가 전쟁위험이 없는 나라였습니다. 이렇게 어린이들이 생각하는 밝은 미래사회를 구현하기 위해 본 연구는 경기도의 역할과 정책 방향을 제시하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 14페이지입니다. 경기도 중장기 비전수립에 대한 연구 중에서 시군이 중점이 되었던 과제들입니다. 파주시, 안산시, 가평군 각각의 발전전략과 미래비전을 제시하기 위한 파주시 중장기발전계획 수립연구 등 3건의 중장기발전계획을 수행하였습니다. 이밖에도 과천시 도시교통정비 중기계획과 부천시 어린이 안전관리 기본계획수립 연구를 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 15페이지입니다. 두 번째 주요성과로 고객의 Needs를 반영한 정책개발 연구입니다. 먼저 경기도 정책시뮬레이션 모형개발 연구를 통해 경기도의 정책을 체계적으로 수립할 수 있는 방법론을 제시하였고 조세정책, 복지정책 등의 파급효과 등을 분석할 수 있었으며 정책평가에 따른 정책방향을 도출하였습니다. 다음으로 2014년도 경기도 재정전망 및 대응전략을 제시하였습니다. 경제침체, 부동산시장 악화로 2013년 세입 결손, 2014년도에도 경기도 세입 결함 등 경기도 재정이 심각해 질 것으로 예상됩니다. 이에 대한 대안으로 도 재정문제 진단, 실현가능한 재정위기 극복 방안, 향후 경기도 재정운용 방안 등을 연구하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 16쪽입니다. 최근 IT/게임 관련 기업 수와 매출 증가로 전문인력 양성이 더욱 필요하게 되었습니다. 마침 2013년 판교테크노밸리 완공으로 경기도지역 전문인력의 수요가 대폭 증가할 전망입니다. 따라서 이와 관련된 인력양성 및 공급에 관한 경기도 지역맞춤형 정책대안을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  네 번째로는 과천지식정보타운 지식기반산업용지 사업화방안 연구입니다. 2011년 과천지식정보타운 보금자리주택지구가 지정 고시됨에 따라 이를 특별계획구역으로 반영하였습니다. 지구 내 지식기반산업용지의 개발계획을 구체화하고 용지의 개발방향 설정 및 개발 콘셉트를 도출하는 등의 사업화 방안을 수립하였습니다. 
</p>
<p style="padding-left:1.2em">  다섯 번째로 파주 헤이리 문화지구 운영성과 및 발전방안과 관련해서는 헤이리 문화지구 지정에 대한 성과 및 문제점을 분석한 후 향후 문화지구 관리운영방안 등을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  여섯 번째로 수원시ㆍ광명시 기후변화 적응대책 세부시행계획 수립과 관련해서는 수원시와 광명시의 기후변화 현황에 대해 충분히 파악한 후 기후변화 적응 비전과 전략을 제시하고 부문별 적응대책의 시행계획을 수립하는 등 대책을 마련하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 18페이지입니다. 마지막으로 경기도 지역발전지수 개발 분석 및 발전방안 연구입니다. 이 연구에서는 경기도 31개 시군의 지역발전지수 선정ㆍ분석, 낙후지역 및 도농 간 균형발전 기본방향 설정, 지역균형발전을 위한 특별회계 설치 방안 등을 검토하였습니다. 이 연구결과는 경기도 지역균형발전 지원 조례 제정의 근거자료로 활용되었습니다.
</p>
<p style="padding-left:1.2em">  다음은 19페이지입니다. 도의회 및 시군이 중점이 되었던 정책개발 사례입니다. GRI는 각 위원회에서 의뢰받은 도의회 정책개발 연구를 수행하였습니다. 특히 기획재정위원회 권오진 위원님과 윤희문 위원님께서 요청하신 경기 동부권지역 자원의 효율적 이용 및 관리비전 연구에서는 비전 및 4개의 중점과제를 제시하는 등 다양한 연구를 수행하였습니다. 시군 정책개발 연구에서는 신종철 위원님께서 요청하신 뉴타운 이후 구도시 개발방향 등 다수의 연구를 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 20페이지입니다. 세 번째 주요성과로 도 현안에 대한 선제적 대응입니다. 김현삼 위원장님께서 요청하신 고교평준화 시행에 따른 통학여건 개선방안 연구를 비롯하여 수도권 규제완화의 새로운 전략 연구 등 다양한 연구를 수행하였습니다. 
</p>
<p style="padding-left:1.2em">  먼저 고교평준화 시행에 따른 통학여건 개선방안 연구입니다. 고교평준화로 인한 통학여건 개선에 가장 효과적인 방안으로 맞춤형 등교버스의 도입을 제안하였습니다. 안산시의 경우 도의회, 안산시, 시의회, 학교, 학부모 등 관계자 협의체를 구성하여 사업시행을 협의 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 수도권 규제완화의 새로운 전략 연구를 통해서 수도권-지방 공동발전을 아젠다로 설정, 분권과 자율의 거버넌스 구축 등 수도권 규제완화의 4대 전략을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 중국인 전용 복합메디텔 조성을 통한 일자리 창출입니다. 올해 1분기 방한 중국인 관광객 수가 대폭 증가했습니다. 이들을 집중공략하기 위해 의료관광산업을 이용한 중국인 전용 복합리조트 조성을 제시하였으며 이를 통해 관광산업의 성장과 일자리 창출 효과까지 기대해 볼 수 있었습니다.
</p>
<p style="padding-left:1.2em">  다음은 22쪽 창조경제와 지역의 실천과제입니다. 대한민국의 신성장동력 및 일자리 창출의 원천으로 기대되는 창조경제는 가장 진화된 형태의 지식경제로서 경기도는 실천전략 마련이 필요합니다. 이에 실천과제로는 지역 고유의 유ㆍ무형 자산을 활용한 전략적 접근, 지역 차원의 창조생태계 조성 등의 정책방안을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  마지막으로 대ㆍ중소유통업 상생발전 방안 연구입니다. 본 연구에서는 대ㆍ중소유통업 간의 상생발전을 위한 현실과 문제점을 분석하여 합리적인 상생발전을 위한 정책방안과 경기지역 특성을 고려한 경기도 실행과제를 제안하였습니다. 
</p>
<p style="padding-left:1.2em">  다음은 23쪽입니다. 도 현안에 대한 선제적 대응연구와 관련하여 도의회 및 시군이 중점이 되었던 사례입니다. 현안으로 기획재정위원회에서 2건을 요청하였는데 연천군 관광네트워크 활성화 방안 연구의 경우 김광철 위원님께서 요청하신 과제로 연천군 372번 도로 주변 관광 활성화를 유도하고 인근 지역과의 협력 등 활성화 방안을 제시하는 등 도의회 현안에 적극 대응한 경우입니다. 시군 현안대응의 경우 임병택 위원님의 지역현안과 관련된 경우로서 시흥시에 입지한 한국가스안전공사 종전 부동산 활용방안 수립연구 등이 있으며 그 외에도 다수의 시군의 현안에 대응하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 24페이지입니다. 네 번째 주요성과로 신규 정책수요 대응을 위한 신설부서의 주요실적을 설명드리겠습니다. 저희 연구원은 신규 정책수요에 대응하기 위해 올해 2개의 센터를 신설하였습니다. 먼저 사회경제센터입니다. 사회경제센터는 경기도 사회적경제 실태와 정책방향 제시, 사각지대 해소를 위한 지역중심의 복지체계 구축 등 지역사회의 복지수요 해결 및 사회적경제 연구를 수행하고 있습니다. 첫 번째로 경기도 사회적경제 실태와 정책방향 연구에서는 사회적경제의 국내외 성공사례를 분석하여 경기도의 사회적경제 실태와 활성화를 위한 정책방향을 제시하였습니다. 다음으로 사각지대 해소를 위한 지역중심의 복지체계 구축 연구입니다. 이 연구에서는 사각지대 해소를 위한 지역중심의 복지체계를 구축하여 수요자 중심의 맞춤형 보편 복지 방안 등을 제시하였습니다. 세 번째로 복지혁신의 신전략에 관한 연구를 통해서는 사회복지제도의 외연 확대보다는 사회혁신으로서의 복지기술 발전전략을 제시하였습니다.
</p>
<p style="padding-left:1.2em">  마지막으로 26쪽입니다. 경기도는 31개 시군에 일자리센터가 설치ㆍ운영되고 있어 고용서비스의 선진화를 위한 중앙정부 고용센터와의 협업이 충분히 가능한 지역입니다. 따라서 주민들에게 수준 높은 고용서비스를 제공하기 위하여 고용센터와 일자리센터의 업무를 분석하고 두 기관의 공동업무 추진을 위한 구체적 실행방안을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  다음으로 27쪽 의정연구센터의 주요실적에 대해 보고드리겠습니다. 의정연구센터는 정책 및 입법자료 조사 등의 지원, 의정 콜로키엄 개최를 통한 의정활동의 질적 제고, 전문가 초청 간담회 및 토론회 지원을 통한 공감대 확산 등 다양한 활동을 수행하고 있는데 조례 등 입법지원 활동과 정책조사 등 의정활동 지원을 10월 기준으로 총 368건을 수행한 바 있습니다. 그리고 웹진 발송, 의정포럼, 시군 순회토론회 등 소통 정책교류 프로그램도 다양하게 추진한 바 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 28쪽 의정연구센터 주요성과의 대표사례입니다. 의정연구센터는 기획재정위원회의 경기도 정보화 조례 일부개정조례안, 경제과학기술위원회의 경기도 인구교육 및 정책 지원 등에 관한 조례 등 경기도의회의 조례안 지원을 위한 다양한 기초자료를 상임위원회에 제공하였습니다. 그 밖에 의정연구센터는 지방의회 발전을 위해 경기도 자치법규 사례의 입법영향분석 등 정책연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 29페이지입니다. 마지막 주요성과로 대내외 소통 강화와 높아진 GRI 위상입니다. 앞서 말씀드린 것과 같이 GRI는 정책교류 토론회, 의정 콜로키엄 등 GRI와 도의회 간의 소통을 강화하기 위한 정책교류에 노력하고 있습니다.
</p>
<p style="padding-left:1.2em">  30쪽입니다. GRI는 대외교류 활동, 지식의 확산을 위해 30쪽, 31쪽에 나와 있는 바와 같이 현장 중심의 신속한 대응, 지식 확산 노력을 지속적으로 추진하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 32쪽입니다. 앞서 설명한 이러한 노력들로 저희 연구원은 행정학분야 연구영향력 15위, 2013년 대한민국 SNS대상에서 2년 연속 최우수상 수상, 매경 2013년 대한민국 최우수 공공서비스 대상 수상, 공공기관 경영평가 8년 연속 우수기관 선정 등 GRI의 위상을 한층 높일 수 있었습니다.
</p>
<p style="padding-left:1.2em">  다음은 33쪽 2013년 정책반영 대표사례를 간단히 보고드리겠습니다. 첫 번째로 법정계획 수립 및 법률 개정 부문입니다. 대표적인 예로 경기도 2020 주택종합계획 연구를 비롯하여 4건이 있습니다. 두 번째로 중앙정부 정책에 반영된 대표사례를 살펴보면 주택거래 활성화를 위한 세 가지 제안연구 등 4건이 있습니다.
</p>
<p style="padding-left:1.2em">  34쪽입니다. 세 번째로 삶의 질 향상과 지역발전에 관련된 대표사례를 살펴보면 군 관련 현안사항 대응방안 마련 등 6건이 있습니다. 마지막으로 예산절감 및 재정 강화 부분의 정책반영 대표사례를 살펴보면 폐기물처리시설의 협잡물 에너지화 방안 연구 등 3건이 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 2014년 주요 연구사업 계획에 대해 보고드리겠습니다. 보고자료 37쪽부터 50쪽이 되겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 37쪽의 2014년 연구사업 목표에 대해 보고드리겠습니다. 저희 연구원은 2014년 연구사업 목표를 민선5기 핵심사업 성과 도출 및 민선6기 전략 수립, 재정건전성 강화 및 안정적 세수 확보방안 제시, 지역경제 활성화 및 분야별 삶의 질 향상방안 제시 등 세 가지로 설정하였습니다. 그리고 이를 달성하기 위하여 30개의 중점사업을 도출하였습니다. 보다 자세한 내용은 40쪽 주요 연구사업 계획에서 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 38쪽 연구사업 추진전략입니다. 우리 원은 선진도정 지향 및 고객 맞춤형 연구, 협업연구 활성화 및 수익구조의 내실화, 대내외 소통ㆍ교류 활성화를 3대 추진전략으로 설정하여 연구사업을 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음 39쪽 연구사업 추진체계는 내년도에도 올해와 동일하게 연구과제사업을 중심으로 연구부대사업, 연구지원사업 및 연구기반사업으로 구분하여 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 40쪽의 2014년 주요 연구사업 계획에 대해 보고드리겠습니다. 2014년에는 미래 먹거리 산업 발굴과 성장 잠재력 강화, 중앙ㆍ경기도ㆍ시군의 업무 및 기능 재조정, 저성장 시대의 부동산 정책 추진 등 민선6기 분야별 주요 어젠다를 발굴하여 적극적으로 추진할 예정입니다. 제시된 어젠다와 중점사업은 원내 부서간담회, 도 실국간담회, GRI 경영전략회의를 통해 검토된 바 있으며 11월 말 이사회를 거쳐 최종적으로 확정할 예정입니다. 
</p>
<p style="padding-left:1.2em">  분야별 연구사업 계획을 말씀드리겠습니다. 첫 번째로 전략연구 분야에서는 민선6기 현안 이슈를 발굴하고 이에 적시 대응하고자 합니다. 그리고 동향전망 분석을 구체화하여 손에 잡히는 엄밀한 예측과 전망을 제시하겠습니다. 한 발 앞서 현안 이슈를 예측하고 신속한 대응체계를 확립하여 적시성을 강화하는 데 노력을 기울일 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 42쪽 미래비전 분야입니다. 미래비전 분야는 중장기 경기도 및 도민의 꿈과 비전, 미래사회와 지역경제 전망, 안전사회ㆍ균형된 지역사회에 대한 정책과 시책사업 개발 등을 중점적으로 추진하고자 합니다. 이를 위해 2014년도에 추진할 과제는 표를 참고해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 자치경영 분야에 대해 보고드리겠습니다. 자치경영 분야에서는 민선6기 자치역량 강화를 위한 행정체계 및 조직진단 연구, 재정위기시대의 지방재원 확충 및 재정건전성 확보방안 연구, 지방정부ㆍ공공기관 경영성과 증진을 위한 연구ㆍ컨설팅 강화 등을 중점적으로 연구하고자 합니다. 
</p>
<p style="padding-left:1.2em">  44쪽입니다. 도시ㆍ주택 분야에서는 저성장시대의 성장관리형 지역&#8901;도시정책 추진, 주거정책 권한 지방화와 맞춤형 주거복지 실현 그리고 낙후지역 도시재생과 공동주택 리모델링 등 새로운 패러다임의 도시ㆍ주택 정책에 초점을 맞추고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 창조경제 분야에 대해 보고드리겠습니다. 창조경제 분야에서는 경기도의 산업구조 변화에 대한 중장기 전망 연구, 경기도 글로벌 중견기업 육성, 고부가가치 융복합서비스 육성 등에 대해 연구를 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 46쪽 교통 분야에 대해 보고드리겠습니다. 교통 분야에 있어서는 수요대응 신교통정책, 효율적 SOC 투자정책 수립, 대중교통서비스 표준화 및 고급화를 중심으로 연구할 계획입니다. 다음은 환경 분야입니다. 환경 분야에 있어서는 안전하고 쾌적한 생활공간 조성, 환경서비스 품질 제고, 자원 및 에너지 선순환 기반 마련 등 관련 연구를 중점적으로 수행하고자 합니다. 
</p>
<p style="padding-left:1.2em">  다음으로 48쪽입니다. 사회ㆍ경제 분야에 있어서는 새로운 4년의 복지 비전 및 정책 방향 수립, 보건-복지-일자리 전달체계 개편, 사회서비스 영역의 사회적 경제 비즈니스 모델화를 중심으로 연구를 추진할 계획입니다. 이와 관련된 연구과제는 표를 참조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 통일ㆍ동북아 분야에 대해 보고드리겠습니다. 통일ㆍ동북아 분야는 남북교류협력사업 발굴 및 통일시대 대비 남북지역 간 통합기반 구축, 중국ㆍ동남아ㆍ중앙아시아 등 신흥지역 교류협력 강화, 군 관련 현안의 상생적 해결방안 강구 등을 중심으로 연구를 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음으로 50쪽 의정 분야에 대해 보고드리겠습니다. 2014년 의정 분야에 있어서는 도의회 정책능력 향상 및 의정활성화 선도, 생산적 지방의정 기반 도정협력 체제 구축, 의정활동 뉴스의 도의원 근접성 및 시의성 확보 등을 중점으로 연구를 추진할 계획입니다. 금년과 같이 내년에도 의정연구센터가 의정발전에 크게 기여할 수 있도록 김현삼 위원장님을 비롯한 위원님들의 많은 지원과 격려를 부탁드립니다. 
</p>
<p style="padding-left:1.2em">  다음은 51쪽의 2014년도 연구사업계획 총괄에 대해 보고드리겠습니다. 2014년도에는 연구과제사업으로 기본연구과제 15개, 정책연구과제 92개 등 총 372개의 연구를 계획하고 있으며 11월 말 이사회에서 2014년 연구사업계획을 최종 확정할 예정입니다. 나머지 사업의 내용은 도표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 55쪽의 2013년 연구과제 목록과 65쪽의 2012년 행정사무감사 처리요구사항 조치결과는 허락해 주신다면 자료로 대신하겠습니다. 이상으로 연구원의 주요업무를 모두 마치겠습니다.
</p>
<p style="padding-left:1.2em">  한마디 더 추가해서 말씀드리자면 저희 연구원도 재정위기 상황에 대응하여 다양한 형태의 재정위기를 극복하려고 상당히 많은 노력을 지금 기울이고 있고 준비를 계획  중인데 특히 아까도 말씀드렸지만 저희가 쓴 예산 중에서 가장 많은 부분이 도에서 지원하는 도비입니다. 그래서 그 부분에 대해 가지고 위원 여러분께서 저희들을 많이 도와주시고 그러면 저희들도 한층 더 연구를 열심히 하고 그렇게 하도록 하는 많은 생각을 가지고 있다는 점을 특별히 말씀드립니다. 경청해 주셔서 대단히 감사하고 다시 한 번 1년 만에 또 여러분들 앞에서 우리 GRI의 연구성과를 보고드리게 된 이런 기회를 갖게 된 것을 저 개인적으로는 상당히 영광으로 생각하고 또 자부심 있게 느낍니다. 위원님 여러분들 경청해 주셔서 감사합니다.
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 김현삼 </b> 원장님 수고하셨습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위하여 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다. 우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 일단 5분을 드리도록 하겠습니다. 그리고 5분의 추가질문이 끝나면 감사 진행상황, 시간 등 제반여건을 감안해서 추가질문을 계속할지 여부를 결정하도록 하겠습니다. 원활한 감사 진행을 위해서 부득이 시간제한을 두게 된 점 널리 양해해 주시면 고맙겠습니다. 질문 순서는 배수문 위원님부터 해서 김광철 위원님, 권오진 위원님 그런 순서로 진행하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  아울러 질의에 앞서서 위원장으로서 한 가지 부탁의 말씀을 드리면 위원님들의 질의에 대하여 원장의 답변이 어려울 경우 업무담당 부장ㆍ센터장 등 실무자가 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나오셔서 소속과 직, 성명을 밝혀 주시고 답변해 주시기 바랍니다. 그러면 먼저 질의 첫 번째로 배수문 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 배수문 위원 </b> 원장님, 답변석에 나와 주시기 바랍니다. 과천 출신 배수문 위원입니다. 질의하도록 하겠습니다. 평소에도 자주 교감이 돼서 많은 내용을 알고 있지만 행감이라는 자리를 통해서 면밀히 원의 내용들을 짚어볼 수 있는 기회다라고 생각을 합니다. 가장 많이 이슈가 되고 있는 것에 대한 질의를 우선 하겠습니다. 산하기관 통합이 예산절감 차원에서 상당히 거론되고 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저도 지면을 통해서 지금 보고 있습니다. 
</p>
<p><b>○ 배수문 위원 </b> 원장님의 생각이 어떻습니까? 지금 여성가족연구원 특히 문제가 많기 때문에. 여성가족연구원 원장은 지금 시기가 맞지 않다라고 답변한 걸로 알고 있거든요. 그다음에 복지재단하고, 자리매김을 어떻게 할 건지 아니면 예산 차원에서 꼭 필요한 건지에 대한 답변해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저 개인적으로는 지금 언론지상에 나오는 연구원 통폐합에 대해서 어떤 관계기관이나 이런 쪽에서 얘기를 들은 바는 없습니다. 다만 신문지상을 통해서 제가 보고 있는데. 그래서 솔직한 얘기로, 올해 들어와 가지고는. 저는 그래서 여성가족연구원이라든지 다른 복지센터에 대한 통폐합은 상당히 신중을 기해야 된다고 생각을 합니다.
</p>
<p><b>○ 배수문 위원 </b> 어떤 면에서 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 왜냐하면 어떤 조직이라는 것도 그 조직 나름대로의, 몇 년간 생기고 그랬으면 그 나름대로의 존재이유가 있었기 때문에 생겼다고 생각을 합니다. 
</p>
<p><b>○ 배수문 위원 </b> 그러면 지금 원장님들끼리 모여서 회의한 적은 없는데…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 전혀 없습니다.
</p>
<p><b>○ 배수문 위원 </b> 원장님 의견은 지금 있는 대로 가는 게 좋겠다라는 게…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 가는 게 좋은 게 아니라 어떤 것은 연구를 좀 해봐야 되겠죠. 그래서 그…….
</p>
<p><b>○ 배수문 위원 </b> 직답을 피하시네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네?
</p>
<p><b>○ 배수문 위원 </b> 직답을 피하십니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니, 그러니까 이게 위원님께서도 아시겠지만 연구원을 통폐합한다는 것은 단순하게 기구만 통폐합하는 게 아니라 사람이 통폐합되는 거기 때문에 상당히 여러 가지 다른 이슈들도 있고 그리고 진짜 또 통폐합하는 것은 통폐합을 통해 가지고 시너지 효과를 통해서 보다 나은 도정에 대한 서비스를 하기 위해서 통폐합을 하는 걸로 저는 이해를 하고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 자, 도민들도 그렇고 예산절감 차원에서 꼭 필요하다라고 다 강조가 되고 있기 때문에, 지금 원장님들 모임이 있지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 원장들 모임이라기보다도…….
</p>
<p><b>○ 배수문 위원 </b> 1년에 서너 번 모이시는 걸로 알고 있는데 이거에 관련해서 지금 연구가 필요하다라고 얘기하시면 TF팀이라도 만들 의향이 있으십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 지금 제가 솔직히 말씀드리면 연구원장끼리 만나서 얘기를 나눠본 적은 없고요. 또 제가 최근에 도하고도 얘기를 한 적은 없고 신문에 나오는 이야기를 듣고 있는 그런 거고 그래서……. 
</p>
<p><b>○ 배수문 위원 </b> 알겠습니다. 이게 적절한 기회에 자주 나오는 얘기를 불식시키든 아니면 정말 예산절감 차원에서 필요하다고 생각하면 일정부분 각 연구원마다 역할을 다시 부여해서 예산절감이 가능한 부분이 있는지를 검토할 시기다라고 보여지거든요. 거기에는 동의하시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 배수문 위원 </b> 그래도 가장 먼저 생겼고 가장 많은 연구를 하고 있는 경기개발연구원이 이거의 적임자라고 저는 생각하거든요, 어렵지만. 그래서 그 부분은 좀 더 고민을 하고 진행이 돼야 될 거다라는 생각이 듭니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 다음 질의하겠습니다. 올해 조직개편이 있었죠, 올 초에?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 그거에 대한 성과를 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 의정연구센터하고, 저희들 조직개편은 큰 건 아니었고요. 부서 이름을 부에서 실로 바꿨고 그리고…….
</p>
<p><b>○ 배수문 위원 </b> 바꾸는 데에 대한 것, 그냥 바꾸는 게 아니거든요. 그래서 작년 행감 때 본 위원이 요청한 거는 모든 분야에 복지라는 이름이 붙으면서 연구가 진행돼야 되는 거고 예산도 30% 가까이가 복지예산이기 때문에 연구원의 방향도 정말 개발 쪽이 아니라 삶의 질 향상을 위한 연구로 많이 바뀌어야 된다. 그리고 요즘 연구의 논조를 보면 많이 그런 쪽으로 가고 있습니다, 맞죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 배수문 위원 </b> 그래서 지금 결원이 7명이죠, 박사 결원이? 연구원.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 올해 또 3명 충원해 가지고요, 7명 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 7명 맞죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 본 위원이 더 요청을 합니다. 어쨌든 복지와 관련된 내용 그리고 삶의 질을 높이는 것에 대한 연구를 교통이든 건설이든 각 분야에 다 녹여낼 수 있는 작업들을 올해도 지속적으로 해주셨는데 내년에는 더 많이 해주셔야 될 것 같다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 그것에 대한 당부를 좀 부탁드립니다. 그건 당연한 거거든요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 그거가 연구원이 처음에 생겼을 때의 목적과 좀 많이 달라졌고 상황이 바뀌었기 때문에, 그 연구원들이 계속 오고 있기 때문에 그 연구원 고유 연구분야에 대한 연구만 계속하고 있거든요. 자칫 잘못하면 미래를 보지 못하고 지금의 답보상태에 있지 않을까라는 생각을 하거든요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 그다음에 국제화 부분입니다. 제가 지난번 행감 때도 좀 얘기했던 것 같은데요. 경기개발연구원이 상을 많이 수상하셨어요. 그래서 대학들만 수상하는 것에도 다른 연구원 제치고 먼저 행정부분에서 15위로 또 등극이 됐고요. 이런 모든 것들을 축하드리면서 그와 걸맞게 한국 내에서의 정보교류 이런 것도 필요하지만 국제화 부분도 필요하지 않을까라는 생각이 들거든요. 국제화라는 얘기는 우리가 주기도 하지만 받을 수 있는 좋은 기회다라는 생각이거든요. 그것에 대한 비전, 계획 있으십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 상대적으로 저희가 국내의 이슈라든지, 아무래도 저희가 서울이라든지 전국을 생각할 때 따라가야 될 대상이 아직 있어서 상대적으로 국내에다 집중을 했는데…….
</p>
<p><b>○ 배수문 위원 </b> 맞죠. 자본력 투입돼 가지고 하고 있는 삼성경제연구원이라든가 LG경제연구소는 못 쫓아가지만 이쪽 분야의 특성이 있기 때문에 가능하다라고 보여지는 부분이 있거든요, 분명히.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> LG나 삼성보다는 저희가 못났다고 생각은 않고요. 국책연구원이나 이제…….
</p>
<p><b>○ 배수문 위원 </b> 그러니까 재정적인 여유 뭐 이런 거를 이야기하는 거고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 노력을 하겠습니다. 일단 지금 최근에 저희들이 먼저 1차적 목표는 국내에서 뛰어난 연구원이 되자라는 것 때문에 상대적으로 소홀한 측면이 있는데 위원님이 지적해 주신 대로 국제화로 갈 수 있도록 저희들이 적극 노력들을 앞으로 더 기울이겠습니다.
</p>
<p><b>○ 배수문 위원 </b> 본 위원이 홈페이지를 각 기관 확인했어요. 매년 하는 거지만 오기 전에 경기개발연구원 홈페이지, 부산발전연구원, 서울연구원, 인천연구원, 연구원 볼 수 있는 데까지 봤거든요. 애석하게도 경기개발연구원 홈피만 영어까지만 번역이 돼요. 서울연구원 같은 경우 몇 가지 언어로 번역되는지 아십니까, 홈피 자체가? 65개 언어로 번역이 가능해요. 국제화의 첫발이기도 하고요. 영어 한 가지, 지금 특히 중국어, 일본어는 기본으로 들어가 있는 사이트들이 상당히 많거든요. 경기도 홈피도 중국어 가능합니다. 일본어 가능하고요. 그런데 연구원 홈피 달랑 영어 하나 돼 있고요. 그 내용도 모든 내용을 담고 있지 못하고 있어요, 들어가 보시면 아시겠지만. 한 가지 더 지적하자면 홈피 보니까 공지사항이 1년에 4건밖에 없어요. 다른 연구원들은 한 달에 공지사항이 10건이 넘습니다. SNS로 소통하기 때문에 이거는 안 해도 되는 건가요?
</p>
