<p><b>○ 경기개발연구원장 홍순영 </b> 감사합니다. 
</p>
<p><b>○ 김광철 위원 </b> 연천 출신 김광철 위원입니다. 오늘 언론에 보도된 내용 중에 이 글은 제가 좀 읽고 넘어가야 될 글이 있어서 몇 가지만 말씀을 드리고자 합니다. 언론 보도자료에 의하면 아베 신조 일본 총리가 일본의 행정수반으로서 하지 못할 망언을 갖다가, 망언 뭐 여러 차례 일본이 늘 해오는데 이건 아주 결정적으로 치명타를 행정수반이 날렸던 것을 읽어드리겠습니다. “주간문춘 최근호는 아베 총리가 중국은 어처구니없는 국가지만 아직 이성적인 외교게임이 가능하다. 한편 한국은 단지 어리석은 국가라는 말을 했다고 밝혔다. 이게 한국의 급소를 찌른다는 특집기사에서 아베 총리 주변 소식통의 말을 인용해 이렇게 전했다. 또 일본과 대립각을 세우는 것은 옆에 간신이 있기 때문이고 그 필두는 외교부장관이라고 비난했다고 덧붙였다.” 또 그다음에 맨 밑에 보면 이런 얘기를 또 했네요. “정한론에 대해서 정한전략도 제시했다. 그 이유로 일본 기업이 배상금을 강제적으로 징수당하면 대항조치는 금융제재밖에 없다고 언급했다. 이어 한국에는 대형은행이라고 볼 수 있는 곳이 한 곳도 없고 가장 큰 우리은행이 미쓰비시도쿄UFJ은행의 1/10 이하 규모라고 주장했다. 그러면서 일본의 금융기관이 한국기업이나 경제에 대한 지원ㆍ협력을 끊으면 삼성도 하루 만에 무너질 수 있다는 망언을 퍼부었다.” 이거 제가 간략하게 말씀드렸습니다. 이 기사 원장님, 읽어보셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 신문을 통해서.
</p>
<p><b>○ 김광철 위원 </b> 언론보도를 통해서 보셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김광철 위원 </b> 제가 왜 모두에 이런 말씀을 드리냐면 경기개발연구원이 동북아의 싱크탱크를 겨냥해서 전략센터로 우리가 목표를 세우고 나가고 있습니다. 그런데 주변국의 정세는 어처구니없게도 우리가 이렇게 과소평가 당하고 있고 현재 우리 주소가 이것인가 하는 그런 것을 갖다가 자괴감을 느끼는 그런 아침의 보도를 보면서 그렇게 얘기를 들었습니다. 그래서 우리 경기개발연구원에서 적어도 동북아의 싱크탱크라고 이렇게 목표를 설정해 나갈 때는 외교, 동북아 관계국들과의 관계에도 좀 더 우리가 적극적으로 대처할 필요가 있지 않느냐 해서 모두에서 이런 발언을 드렸습니다. 
</p>
<p style="padding-left:1.2em">  질의드리겠습니다. 원장님은 지금 연구센터의 기능 중에 전략연구센터하고 미래비전연구실이 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김광철 위원 </b> 여기 자료에 의하면 정책현안에 대한 검토분석 및 국내외 정책환경 변화에 따른 대응방안을 제시한다. 이게 전략연구센터의 주 설립목표지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김광철 위원 </b> 그다음에 미래비전연구실은 지역경쟁력 강화와 삶의 질 개선을 위해 미래비전과 전략수립을 세우겠다 이렇게 돼 있어요. 그런데 원장님께서도 잘 아시겠지만 지금 경기도가 재정난에 봉착해 있지요? 여기에 대한 수요, 이런 상황이 경기개발연구원에서는 예측이 됐었습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김광철 위원 </b> 몇 년 전부터 예측이 됐었지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 부동산 경기가 침체된, 제가 와서부터 2011년도부터, 그전에도 부분적으로 연구는 했습니다마는 아시는 바와 같이 경기도의 수입이라는 것이 50% 이상 취득세로 구성되어 있고 취득세는 부동산 경기하고 밀접하게 연관이 되어 있기 때문에, 그런데 상대적으로 앞으로도 부동산 경기가 그렇게 획기적으로 개선될 가능성이 없기 때문에 도 재정은 앞으로도 상당히 쉽지 않을 거다라고 저희들은 계속 예측을 해왔습니다. 거기에 대한 발신도 계속 해왔고요. 
</p>
<p><b>○ 김광철 위원 </b> 그럼 2011년도에 이게 예측이 되어진다 그러면 연구자료를 냈습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 그래서 지방세를 국세, 지방세 조정을 비롯해 가지고 다양한 세수 확보 방안에 대해서 지속적으로 연구를 하고 있습니다. 하고 있었고 지금도 하고 있고요.
</p>
<p><b>○ 김광철 위원 </b> 이게 왜냐하면 우리가 연구의 기능이라는 것은 사후적 기능도 있지만 사전적 기능이 더 중요하지요. 미래예측기능이 더 중요하고요. 지금 우리가 세입구조에서, 지금 원장께서 말씀을 해주셨지만 우리가 거래세의 거의 반 이상, 50% 이상을 거래세에 의존하다 보니까 당연히 이런 부동산 경기의 침체에 대해서는 아마 일전에 우리 연천에서 연찬회 때 주택 부분에 대한 심도 있는 토론을 전개했었거든요. 그 이전에도 분명히 이게 예측이 되었던 사항이라 그러면 이게 가장 중요한 문제거든요, 사실은. 경기도의 재정이 건전하지 않고 어떻게 우리 도가 살림을 펴나갈 것이며 또 그다음에 우리 기초자치단체가 도의 보전금이나 보조금에 의존하고 있는 자치단체가 더욱 더 어려워질 것이라는 가장 큰 줄기이고 부분인데 이런 부분에 대해서 과연 경기도에 우리가 제언이라든가 또 아니면 연구를 해서, 지금 말씀하신 부동산 세제의 개편이라든가, 국세지요. 국세 소비세의 개편이라든가 이런 부분에 대해서는 우리가 어느 부분이나 다 예측할 수 있는 부분이었거든요. 정책적으로 활용해서 법안을 만들어야 된다는 부분에는 누구도 그건 동감하는 부분이거든요. 그 외에 경기도에 취할 수 있는 액션을 뭐를 취하셨는지 저는 그걸 묻고 싶거든요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 참고로 재정예산 분야의 연구를 말씀드리면 여태까지 12건을 했는데요. 2011년도에도 지방의 희생을 강요하는 재정현실이라든지 지방예산의 위기와 정책방향이라든지 또 경기도 지방재정 조기개편 문제라든지 이런 것에 대해서 다양한 연구를 했고요. 그래서 제가 이쪽의 완전 전문가가 아니기 때문에 자세한 내역을 말씀드리기는 그렇지만, 전문가들이 있기 때문에. 저희들이 하여간 지방세, 국세 조정문제를 비롯해서 예산 집행의 문제라든지, 효율적 집행의 문제라든지 다양한 것에 대해서 저희들이 대안을 제시한 바가 있었습니다. 
</p>
<p><b>○ 김광철 위원 </b> 지금 경기개발연구원에는 지방예산이라든가 세입이라든가 세출에 대해서 지방재정에 대해서 아니면 국가재정에 대해서 연구하시는 분들이 몇 분이나 계십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 전문가들은 자치경영연구실에 몇 분 계시고요. 그리고 저희들은 이 문제에 대해서 많은 연구원들이 같이 협업을 하기 때문에 그것만 딱 집어 가지고 전문가다라고 얘기하기는 뭐하지만 지방재정을 연구하는 분들은 한 세 분 정도 계십니다. 
</p>
<p><b>○ 김광철 위원 </b> 선임연구원들이십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 다 박사급들 연구요원급 이상입니다.
</p>
<p><b>○ 김광철 위원 </b> 연구요원급이십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김광철 위원 </b> 유감스러운 부분은 바로 이런 어떤 지방재정, 특히나 경기도 재정문제에 관해서 예측이 되었음에도 불구하고 그것을, 저는 어차피 올해 잘 터졌다고 생각합니다. 다만 이 후유증이 앞으로 어떻게 전개될지에 대해서는 상당히 허리띠를 졸라매야 되는, 그거와 더불어서 우리 기초자치단체에도 허리띠를 졸라매야 되는 이런 상황이 도미노처럼 아마 일어날 것이라고 예측이 되어지는데 원장님 견해는 어떠세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저도 예산문제는 지금 결국에는 세입ㆍ세출 문제인데 그래서 지금 보조금 문제라든지 지방교부세 문제라든지 세입 자체가 지금 굉장히 지방자치단체들이 거둬들일 수 있는 기반이 취약하기 때문에 그 문제를 해결하지 않고서는 이게 쉽지가 않겠다. 그래서 이것은 지방정부의 문제이기도 하지만 우리나라 전반적인 지방자치제의 큰 문제라고 생각을 하거든요. 그래서 이것은 중앙의 협조가 굉장히 필요하다 저는 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 김광철 위원 </b> 생각만 하고 있어 가지고는 되지 않고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다.
</p>
<p><b>○ 김광철 위원 </b> 경기도가 광역시도 중에서 제일 취약한, 왜냐하면 우리가 거래세 비중이 너무 높잖아요. 인천하고 경기도가 재정부분이 취약할 수밖에 없는 구조잖아요. 다른 광역단체에 비례해 가지고. 그럼 경기도에서 지분을 가지고 있는 우리 경기개발연구원에서 저는 무엇보다도 이 연구 부분이 선행됐어야 되고 그다음에 경기도에서는 이걸 정책적으로 분명하게 반영시켜서 선제적으로 대응이 됐어야 된다고 보는데 현재 우리가 겪어야 되는, 앞으로 허리띠를 졸라매는 상황이 언제까지 지속이 될지 누구도 예측을 못하고 있어요. 이 부분에 대한 것은 경기개발연구원이 이런 부분에 대한 선제적 대응능력이 부족했다고 전 보고 있습니다. 동의하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 위원님의 지적에 대해서 겸허하게 저희가 반성을 하고요. 그래서 저희들이 기존에 연구도 하고 있었습니다마는 앞으로 더 열심히 하겠습니다.
</p>
<p><b>○ 김광철 위원 </b> 이게 참 경기도의 재정이 가용재원이 줄어든 거지요. 총액 재원이야 점점 더 늘어나는데, 이따가 제가 시간이 되면 복지 부분에 대해서 말씀을 좀 드리겠습니다마는 이런 부분에 대해서 정확하게 우리가 도에 로드맵을 제시해줄 수 있고 그걸 정책적으로 정말 공허한 메아리에서 지금, 모든 소비세율 우리가 더 증가시키는 부분에 대해서 또 그다음에 국고보조금 영유아 누리과정이라든가 노인복지 부분에 대한 것을 국고에서 이렇게 전환이 되는 것 이런 부분에 대해서는 여러 가지 방편이 많이 나와 있어요. 나와 있는데 이런 부분을 정책적으로 입안을 적어도 하려면, 천상 국회에서 입법이 돼야 되는 부분 아닙니까? 그런데 지금도 계류되어 있는 게 상당히 많거든요. 그렇잖아요. 그런데 이걸 갖다가 정말 이게 아주 절실한 문제인데 이런 부분을 한 해가 지나가고 한 해가 지나가고 하다가 결국은 저희가 재정에 대한 위기감을 갖다가 맞지 않았나 본 위원은 이렇게 판단이 되고 있거든요.
</p>
<p style="padding-left:1.2em">  시간이 돼서 추가질문 때 말씀을 드리겠습니다마는 하여튼 우리 연구원에서 지금 가장 긴급한 현안으로 대두되고 있고 또 그다음에 앞으로도 미래예측이 가능했던 부분에 대해서, 특히나 도정 부분, 지방재정 부분에 대해서 현실적인 대안을 나눠줘서 도정이 움직일 수 있는 그런 연구업적이 세워졌으면 좋겠다는 말씀을 드립니다. 이상입니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다.
</p>
<p><b>○ 위원장 김현삼 </b> 김광철 위원님 수고하셨습니다. 다음은 권오진 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 권오진 위원 </b> 권오진 위원입니다. 저도 재정부터 시작을 해야 될 것 같습니다. 원장님 말이지요. 원장님, 저는 도지사께서 재정위기라고 하셨는데 하는 일을 보게 되면요. 그저 도민들을 갖다가 이렇게 위기다 위기다 하는 것 같고 아무 대책이 없는 것 같아요. 왜 그러냐, 재정에 대한 것은 수입과 지출이 있잖아요. 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다. 
</p>
<p><b>○ 권오진 위원 </b> 수입은 수입에서 세수가 줄었다 하는데 세수가 아까 원장님 말씀하신 건 취등록세가 줄었다. 당연한 거죠. 사람이 집을 안 사니까, 경기도에서. 제가 지난번에 신용보증재단이 지원을 5배수밖에 안 하고 있다. 더 해라. 이렇게 얘기했거든요. 재작년부터 서울시는 서울에 있는 기업들이 나가지 않도록 하기 위해서, 또 기업을 유치하기 위해서 경기도에 있는 알짜기업을 유치해 간대요. 여러 가지 다양한 지원이나 기금을 통해서 해 줘가지고 그게 재작년부터 시작한 겁니다. 이렇게 시작해서 하기 때문에 경기도에 기업이 줄 수밖에 없지요. 하다못해 사회적기업도 지원해서 끌어간답니다. 경기도에서 잘 만들어 놓고 나면 그들이 그걸 끌어간다는 거예요, 지원해 가지고서. 이러한 전략들을 정보를 받아가지고 어떻게 할 것인가를 갖다가 경발연은 도지사한테 요청해야 되는 겁니다. 제가 얘기를 그렇게 발언하고 도정질의 했더니 “아이구, 적자가 난답니다. 5배수도 많이 하는 겁니다.” 하고 있는 게 도지사입니다. 이걸 일깨우는 건 누구냐. 그걸 일깨우는 것은 경발연이다 이거죠. 누가 일깨우겠습니까, 그 주위에서. 이러한 것을 볼 때 정말 안타까운 부분이고요. 솔직히 또 세입은 그렇습니다. 그래놓고 나서 채권발행 안 하겠다. 또 땅을 팔겠다. 땅 팔면 됩니까, 그게? 안 되지요. 그러니까 안 되는 것만 해 가지고서 당연히 지난번에도 예산 하면서 이런 얘기를 했어요. 미래의 우리 후손들을 위해서 채권발행하면 안 된다. 할 건 해야죠. 할 건 해야 되는 것인데, 왜 그런지 아십니까? 세출 부분에서 교육청에 나가는 돈이 있습니다. 아시잖아요. 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 압니다. 
</p>
<p><b>○ 권오진 위원 </b> 그런데 그걸 왜 해줘야 되느냐. 교육청은 이미 땅값을 줬습니다. 거기에서 취등록세로 들어오는 것 중에서 학교를 지을 때 거기 땅값이에요. 그 땅값은 이미 줬습니다. 왜? 안 주면 LH가 이자 내라고 하니까요. 나머지를 못 쓰고 있는 겁니다, 지금. 교육 부분에서는 돌아간 학생이기 때문에, 지나갔기 때문에 학생들한테 혜택을 줘야 되는 겁니다. 각종 프로그램이나 시설을 해 가지고서. 이런 돈을 안 주겠다는 겁니다. 안 주는 겁니다, 지금. 돈이 없다 해 가지고서. 이런 걸 일깨워야 되는 겁니다, 솔직히 말해서. 그러니까 전혀, 도지사는 위기가 자기 입으로만 위기지.
</p>
<p style="padding-left:1.2em">  제가 한 번 이걸 조사하려고 해요. 우리가 산하기관 26개가 있잖아요. 그러면 거기를 통해서 집행된 예산이 상당할 겁니다, 솔직히 말해서. 아마 각 실국에서 그들을 통해서 거기 예산이 나갈 거예요. 거기서 손 안 대는 거예요. 말로만 통폐합시킨다. 제가 예를 한번 들어볼게요. 제가 전에 동부생명에 갔었어요. 발령 받아 가지고, 개혁하려고. 동부생명이 프랑스 AXA하고 동업한 회사입니다. 합작회사입니다. 저보고 사람을 30% 자르라는 겁니다. 200명 자르라는 거예요. 그래서 제가 “그게 정말 어렵습니다.” 그랬더니 한 달 후에 또 부르더라고요. 프랑스 임원이 부르더니 “당신이 나갈래, 사람 자를래?” 딱 그러더라고요. 이게 혁신입니다. 정말로 도지사가 경기도를 혁신하려고 마음먹었다면, 재정의 위기 때문에 한다면 산하기관 불러서 이거 15개로 운영하자, 어떻게 해서라도. 뭘 만들어야 되는 겁니다. 이런 한 마디 언급도 없이 위기, 말로만 위기죠. 경기도시공사 4조 4,000억만 금융이자 내는 부채다. “별로 걱정 없습니다.”라고 하는 게 경기도지사입니다. 이것을 연구를 통해서 계수를 통해서 제시할 것이 바로 경발연이지 또 어디 있습니까? 어느 누가 연구하겠습니까? 이러한 역할을 제대로 했느냐는 것이죠, 솔직히 제가. 정말로 여러 가지로 하는 거 좋습니다. 다 해요. 많이 했어요. 그래서 제가 압니다. 솔직히 말해서 오늘 사실 경발연에서 ‘야, 정말 질문할 게 너무나, 돈도 못 주면서.’ 그렇게 생각을 했어요. 그런데 정말로 경기도의 위기가 아까도 원장님이 말씀하셨잖아요. 위기를 몇 년 동안 연구해 왔다. 당연히 해왔죠, 하셨겠죠. 저도 작년에 들어봤어요. 그랬는데 정말로 위기가 어떻게 왔는지, 왜 기업체가 줄어들고 있는지. 기업체가 줄어드는데 어떻게 아파트가 팔립니까? 왜 원인이 되는지. 항상 그 원인은 왜 그럴까, 왜 그럴까 찾아 가지고 그 원인을 제거하는 것을 제시하는 것이 경발연이라고 생각을 하는데 정말 아주 답답했어요. 
</p>
<p style="padding-left:1.2em">  진짜 제가 지난번에 경기신용보증재단 가지고서 발의할 때도 나중에도 도지사 결국 하는 말이 “적자가 나서 그렇습니다.” 제가 그랬어요. “도지사님, 심사를 해 가지고서 대출하는 건 6% 이상 손해가 안 납니다. 그저 누가 해 먹으려고 하는 부분 빼면 안 납니다.” 그랬어요. 그러면 진짜 추진을 해서라도 중소기업들, 우량한 것들 해 가지고 대출보증 해줘 가지고 끌어오는 방법들이라든지 이러한 것들이 연구가 돼야 된다고 저는 보는 겁니다. 그래서 그러한 것에 대해서 너무나 그동안에 경발연이 좀 소홀하지 않았나 하는 것은 먼저 말씀을 드리는 겁니다. 
</p>
<p style="padding-left:1.2em">  그리고 다음에 문제가 그럴 텐데요. 제가 한번 거기서 해 가지고서 원장님께서 만이라도, 경발연의 제일 중요한 목적은 양질의 연구실적을 내는 것이라고 저는 생각하는데 맞습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 권오진 위원 </b> 그러기 위해서는 우수한 연구원들을 확보하고 퀄리티를 높이는 것이라고 생각하는데 예산을 지금 현재로 봤을 때 30% 줄인다고 한다면 대안이 있으신가요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 예산의 대부분이 인건비가 많기 때문에, 아까 연구사업비라는 것도 대부분이 인건비입니다, 사실은. 그래서 예산을 줄이면 결국에는 유능한 인재를 기존에 있던 인재들도 유지를 못할 뿐만 아니라 외부에서 오는 인재들도 상당히 힘들게 돼서 저희들이 국책연구소인데, 사실은. 절대적으로 예산을 결국에는 도에 의존하고 있는 이런 상태에서 예산이 줄어들면 저희는 상당히 힘들어집니다. 
</p>
<p><b>○ 권오진 위원 </b> 그렇죠. 이건 진짜로 다른 것 줄이는 것도 아니고.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 사람을 줄여야 됩니다.
</p>
<p><b>○ 권오진 위원 </b> 사람을 줄여야 되기 때문에. 예를 들어서 진짜로 경기도가 넓기 때문에 연구를 할 건 많고. 지금 진짜 아쉬운 딜레마에 우리가 사실 걸린 부분인데요. 왜 그러냐? 제가 경발연을 작년부터 해 가지고 쭉 보게 되면 꼭 필요한 기관이다. 왜? 경기도의 시군에는 계획이 없습니다. 아까 여기 참 좋은 것 몇 군데, 두 군데 했었어요, 보니까. 이런 계획이 없습니다, 시군에 전부 다가. 크거나 작거나 간에. 그러나 그러한 안들을 만들어 가지고 그 자체가 주민들의 안이라도 만들어 있다면 경기도에 이런 개발부분에서의 업자들이 준동 안 합니다, 못합니다. 우리는 이렇게 만들고 싶었다, 지역을. 하는 안을 만들어 주는 것도 필요하기 때문에 참 아주 좋은 기관이고 해야 된다고 생각하는데 예산이 그냥 준다고 하니까 답답해 가지고 혹시 그런 방법에 대해서 대안을 부탁드리고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 권오진 위원 </b> 제가 몇 가지만 말씀드려 보겠습니다. 첫째, 우리 이상대 박사님 잠깐 좀. 전에 제가 볼 때에 2020 발전계획이……. 잠깐만 앞으로 나오시죠. 간단히만 말씀드리겠습니다.
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 미래비전연구실장 이상대입니다. 
</p>
<p><b>○ 권오진 위원 </b> 2020 발전계획, 그때 저하고 같이 많이 얘기하셨잖아요?
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 네.
</p>
<p><b>○ 권오진 위원 </b> 김경희 국장님도 오셔 가지고 토론을 했는데 그게 수도권정비법을 대체한다고 그랬잖아요. 됐나요, 그게?
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 지금 하고 있는 걸 말씀하시는 겁니까, 아니면 전에 했던 도 종합계획을 말씀하시는 겁니까? 
</p>
<p><b>○ 권오진 위원 </b> 전에 했던 거요.
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 전에 했던 2020 도 종합계획 말씀입니까? 
</p>
<p><b>○ 권오진 위원 </b> 네, 도 종합계획.
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 그건 법정계획이기 때문에 대상범위는 경기도 지역입니다.
</p>
<p><b>○ 권오진 위원 </b> 그러니까 그게 결정이 됐나요, 그렇게? 그걸로 해 가지고서.
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 네, 작년 2월 달에 국토부장관 승인을 얻어서 지금 법정계획으로 시행되고 있고요. 시군 도시기본계획 가이드라인으로 지금 작용하고 있습니다. 
</p>
<p><b>○ 권오진 위원 </b> 작용하고 있습니까?
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 네.
</p>
<p><b>○ 권오진 위원 </b> 그러면 이제는 수도권정비법의 영향을 안 받고서 우리 계획 가지고서 경기도 개발할 수가 있다?
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 그건 아닙니다. 왜냐하면 도 종합계획은 국토기본법에 근거해서 수립되는 거고요. 수도권규제는 수도권정비계획법에서 규정해서 되는데 수도권정비계획법은 특별법입니다. 물론 국토기본법은 국토ㆍ도시에 관한 가장 기본적인 법임에도 불구하고 수도권정비계획법이라는 특별법이 우선하게 됩니다. 
</p>
<p><b>○ 권오진 위원 </b> 그렇습니까? 그때 저는 듣기를 그것이 성안이 되어 가지고서 하게 되면 수도권정비법의 제재 받지 않고 경기도가 우리 나름대로의 지역특성에 맞게끔 개발할 수가 있다고 하는 걸로 들었기 때문에, 아직은 살아 있다 이거죠?
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 그렇습니다. 그 내용들을 보면 수도권정비계획법 규제를 내용적으로 오해한다든지 그와 같은 내용들이 많이 들어 있습니다. 
</p>
<p><b>○ 권오진 위원 </b> 그럼 그것도 봐 가지고서 한 번 더 깊이 들어가서 대체할 수 있는 안을 마련해야 되는 것 아니겠습니까, 지금?
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 기본적으로 일단은 법이 개선돼야 될 부분입니다.
</p>
<p><b>○ 권오진 위원 </b> 그러니까 딱 지금 묶여 가지고서 있는 부분 속에서 경기 동부 같은 경우 개발제한구역이 있잖아요. 그러한 것들을 어떻게 할 것인가를 한 번쯤은 문제를 환기시키고 항상 지역의 문제를 수면에 띄우는 것은 경발연이라고 생각하거든요, 도의원들도 중요하지만. 그런 부분 속에서 한번 자꾸 문제를 환기시켜 가지고 지역의 문제를 풀어야 되지 않겠나 생각이 들어 가지고 그것도 한번 연구과제로 자꾸 제시해 가지고서 자꾸 문제를 수면으로 띄워야지만이 도의 국회의원도 생각할 것이고 이렇게 할 수 있지 않나 생각을 해서 말씀을 드리는 겁니다.
</p>
<p><b>○ 미래비전연구실장 이상대 </b> 수도권규제 문제에 있어서 최근에 우리 연구원이나 저 같이 도 담당하는 사람들의 전략이 바뀐 게 있는 것은 옛날에는 수도권규제를 풀어야 된다라는 그런 좀, 직접적으로 중앙정부나 지방하고 대결을 하는 전략을 했는데 최근에는 수도권규제 중에서 특히 군지역들의 수도권규제 제외 부분이라든지 그다음에 또 수도권규제 이 문제를 충청권이나 강원권하고 협력을 통해서 풀어나가는, 다시 말해서 접도지역 같은 경우는 공동 개발하자라든지 그다음에 평택ㆍ아산만권을 하나의 광역도시권으로 공동 풀어가자 이런 것들로 주로 전략을 저희들이 그렇게 구사를 하고 있고요. 그래서 지금 하고 있는 메가수도권 발전비전과 구상 같은 경우에도 충남발전연구원의 박사들이라든지 강원발전연구원의 박사도 같이 참여를 해서 이런 식으로 풀어나가는 식으로 해서 조금 접근방법을 지금 달리하고 있습니다. 
</p>
<p><b>○ 권오진 위원 </b> 알았습니다. 시간 지났나요? 이제 이걸로 본질의를 마치겠습니다. 
</p>
<p><b>○ 위원장 김현삼 </b> 권오진 위원님 수고하셨습니다. 추가질의는 또 기회를 드리도록 하겠습니다. 그러면 신현석 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 신현석 위원 </b> 파주 출신 신현석 위원입니다. 경기개발연구원에 대해서 기사를 검색하는 중에 흥미 있는 기사를 봤습니다, 원장님. 안병도 수석연구원이 좀 지났지만 경기도민이 주관적으로 느끼는 행복수준과 관련해서 만족도조사를 했더라고요. 아주 재미 있는 기사가 있기 때문에 한번 잠깐 말씀드리겠습니다. 경기도민 10명 중 5명은 행복한 사람이라고 그러고 1명은 불행한 사람이라고 느끼는 것 같습니다. 그다음에 4명은 행복하지도 않고 불행하지도 않고, 이런 연구결과가 나와서 잠깐 소개해 드렸습니다. 
</p>
<p style="padding-left:1.2em">  본 위원이 왜 이런 질의를 하냐 하면 동북아의 미래를 선도하는 경기도의 싱크탱크 역할을 GRI가 비전을 갖고 있기 때문에 먼저 이런 기사를 소개합니다. 본 위원은 전반기에 보건복지공보위원회에서 상임위를 했습니다. 원장님, 혹시 2013년도 보건복지 예산이 경기도 전체예산의 얼마인지 아십니까? 본 위원이 알기로는 30%가 넘는 걸로 알고 있습니다. 그런데 그 30%가 보건복지 예산으로 사용되고 있지만 실질적으로 체감하는 우리 경기도민은 그렇게 많이 있는 것 같지 않습니다. 그래서 안병도 수석연구원이 정말 현실에 다가가는, 경기도의 싱크탱크라 할 수 있는 현장밀착형 정책을 개발하고 있구나. 그리고 그런 기본 근저에 의해서 GRI의 정책연구가 되어졌구나라고 생각되어져서 상당히 감사하다는 말씀을 드리면서 질의를 하겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다. 
</p>
<p><b>○ 신현석 위원 </b> 본 위원이 지난 금요일 날 주방조리원, 이것도 같은 선상에서 연구를 했던 건데 주방조리원에게 인건비를 지급하자는 걸 한 번 도정질의를 한 적이 있습니다. 여기 김희연 박사가 뒤에 있는데 너무 감사드리고 한 1년 전부터 제가 조언을 받아서 경기복지재단하고 해서 장기요양보험에서 월 100만 원씩 지급하기로 했습니다. 주방조리원들이 뭐냐. 어르신들을 모시고 있는데 어르신들을 케어하다가 그다음에 식사시간이 되면 똥걸레 만지던 손으로 다시 밥을 짓는 그런 현상이 있는 겁니다. 이것도 정말 우리 경기개발연구원하고 그것에 대해서 현장밀착형으로 서민들을 위해서 경기도의 예산이 없음에도 불구하고 다르게 생각해서 그분들에게 이렇게 숨통을 트여주신 것에 대해서 논리적 제공을 해준 데에 너무나 감사드립니다. 
</p>
<p style="padding-left:1.2em">  첫 번째 질의하겠습니다. 아마도 우리 GRI에서 상당히 많은 연구를 하고 있는데 지방자치 관련해서 연구용역이 어떻게 잘 활발히 되고 있습니까? 2012년도에 관련해서.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 저희들이 지방자치 연구는 계속하고 있습니다. 
</p>
<p><b>○ 신현석 위원 </b> 2013년 대비 2014년은 어떻게 계획이 돼 있습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 내년에도 지방행정체제 개편 문제라든지 이런 연구를 계속 지금 하려고 하고 있습니다. 
</p>
<p><b>○ 신현석 위원 </b> 그런데 지방자치 말은 좋은데 지방자치 연구와 관계돼서 실질적으로 경기도 도의원의 지방자치, 인사독립권 내지는 의원들의 의정활동 수준은 상당히 취약할 수밖에 없는 그런 구조적 모순을 갖고 있는데요. 그것과 관련해서 의정연구센터에 대해서 질의하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  우리 원장님이 보셨을 때 의정연구센터의 성과와 한계가 뭐라고 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일단 성과부터 말씀드리겠습니다. 처음으로 의정지원을 할 수 있는 나름대로의 센터를 우리 연구원에 둬서 의정을 잘 이끌어가는 데 저희들이 본격적으로 센터를 만들어서 정식기구를 둬 가지고 소위 가교역할을 지금 하고 있다는 데 굉장히 큰 의의가 있다고 생각을 하고요. 앞으로 의정연구센터의 한계라고 할 것 같으면 예를 들면 가장 중요한 게 예산문제입니다. 저희들이 그래서 예산이 지속적으로 확보가 되고 그러면 올해의 경험을 바탕으로 해 가지고 더욱더 발전할 수 있을 거다 이렇게 생각을 하기 때문에. 그런데 향후에 어떻게 그 예산을 저희들이 제대로 확보하면서 좋은 연구인력을, 또 일당백의 연구인력을 계속적으로 확보를 하면서 의원님들을 서포트할 수 있는가가 가장 중요하다고 생각을 합니다. 
</p>
<p><b>○ 신현석 위원 </b> 그럼 문제점이 예산이네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 가장 중요한 게 예산입니다.
</p>
<p><b>○ 신현석 위원 </b> 본 위원이 알기로는 내년도 예산이 경기도에서 예산을 책정을 받지 못한 걸로 알고 있는데 맞습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 예산은 아직 끝난 건 아니기 때문에요. 현재로서는 저희들이 작년도에 107억 이상 예산이었는데 16~17억 정도 깎여서 지금 책정이 됐기 때문에 그 상태로 말씀드리면 아직까지는 의정연구센터 예산이 확보됐다고 볼 수는 없겠습니다. 
</p>
<p><b>○ 신현석 위원 </b> 경기개발연구원 센터에서 그러면 그 예산이 확보되지 않은 것에 대해서 어떤 노력을 하고 계시는지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 이 예산시즌만 되면 저희들이 돈 버는 집단이 아니기 때문에 여기저기 다니면서 상당히 많은 부탁도 하고 그걸 갖다가 계속 끊임없이 지금 하고 있죠. 저희 위원님들한테도 말씀을 드리고 또 도 담당 공무원분들께도 저희가 말씀을 드리고 그러면서 저희가 보이지 않게 아주 굉장히 노력을 많이 하고 있었습니다. 
</p>
<p><b>○ 신현석 위원 </b> 본 위원이 아까 전에도 말씀드렸지만 주방조리원이, 또 의원들이 하는 일에 비해서 상당히 많은 로드가 걸립니다. 그나마 의정연구센터 연구원들의 도움을 받아 가지고 저희들이 정확하게 경기도의 문제와 난맥상을 진단하고 또 저희들이 나름대로 연구하고 있는데 그런 의정연구센터가 이렇게 예산에 치우쳐 있고 예산이 성립되지 못하니까 연구원들의 사기가 상당히 많이 떨어질 것으로 판단됩니다. 우리 경기개발연구원장님은 그것까지 잘 감안하셔서 예산이 적극 반영될 수 있도록 노력해 주시고, 물론 저희 위원님들도 다 같이 노력을 할 예정이니까 좀 더 신경을 써주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 저희들도 계속 신경을 쓰겠습니다. 참고적으로 말씀드리면 의정연구센터가 신설된 조직이고 새롭게 사람들을 뽑았기 때문에 우리가 기존의 인력을 가지고 이걸 했었으면 사실은 어떻게 예산을 기존 방식대로 해 가지고 나름대로 꾸며볼 수 있지 않겠나 이렇게 생각할 수도 있지만 의정연구센터는 다 신규 인원으로 충원한 거기 때문에 절대적으로 예산이 필요하고요. 이 예산은 저뿐만 아니라, 저도 노력을 하겠습니다만 정말 의원님들께서 이 예산을 어떻게든지 저희들한테 마련해 주시면 저희는 의정연구센터를 정말 새로운 모델로서 계속 발전시키고 싶은 그런 방침이 있다 이렇게 말씀을 드리겠습니다.
</p>
<p><b>○ 신현석 위원 </b> 의원들의 연구 개인차는 있겠지만 의원들이 의정연구센터에 바라는 바에 대한 기대감도 클뿐더러 그에 대한 부응을 잘해 주시는 의정연구센터장님을 비롯해서 경기개발연구원장님께 감사의 말씀을 드리면서 두 번째 질의하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  경기도의회 의원연구모임이 있습니다. 저도 경기도사회복지정책발전연구회 회장을 같이 하면서 하고 있는데 보니까 GRI와 공동연구 현황이 2013년에는 상당히 많이 진척이 됐더라고요. 그래서 내년에도 우리 원장님이 경기도의회 의원연구모임과 GRI 공동연구에 대해서 어떤 계획을 갖고 있는지 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 의정 교류는 계속 하고요. 저희들이 의정포럼도 있고 그래서 그 부분에 있어서는 저희들이 소통도 굉장히 중요하고 또 의회가 도정의 다른 한 축이기 때문에 여기에 대해서 저희들은 지속적으로 기존에 해왔던 방식에서 더욱 발전시켜 나가고 문제점이 있으면 문제는 문제대로 저희가 고치고 더 확대해 나갈 수 있는 건 더 확대해 나가고 그럴 생각입니다. 
</p>
<p><b>○ 신현석 위원 </b> GRI가 태생부터 아무래도 싱크탱크의 역할을 하다 보니까, 집행부서가 아니다 보니까 어려운 상황은 충분히 이해가 갑니다. GTX 관련사업의 연구현황에 대해서 제가 질의도 하고 그것에 대해서 많이 들었는데 아무래도 연구부서하고 실행부서하고 틀리다 보니까 논리적 근거를 제시함에도 불구하고 그게 제대로 사업에 반영되지 않은 것이 많이 있을 것으로 판단됩니다. 그래서 연구부서지만 적극적으로 사업에 반영을 하기 위해서 경기개발연구원에서는 어떤 활동들을 주로 하고 계시는지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 연구가 저희들이 실행이 될 수 있는 건 결국에는 실행을 집행부가 하기 때문에 공무원분들한테도 지속적으로 보고서를 갖다 주면서 거기에 또 정책을 시행할 때 저희들이 보고서 형태는 아니더라도 많은 연구원들이 직접 같이 인볼브가 돼 가지고 시행도 하고 또 도의회한테는 조례라든지 이런 걸 통해 가지고 직간접적으로 반영하도록 하고 있고요. 저희 연구원의 기능이 두 가지 같아요. 하나는 직접적으로 도 정책에 반영되는 것하고 또 하나는 꿈을 그리는 역할이 있는 것 같거든요. 그래서 미래에 대한 꿈도 그리고 또 현안에 대해서 직접 도 정책에 또는 최종 정책에 반영되는 다양한, 그래서 반영된 실적 같은 경우도 저희들이 계속 발굴해 가지고 책자로 내서 발신도 하고 그러고 있습니다. 
</p>
<p><b>○ 신현석 위원 </b> 다시 한 번 우리 경기도의 싱크탱크 역할을 해주시는 원장님과 연구원들께 감사의 말씀을 드리고 추가질의에 다시 하도록 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다. 
</p>
<p><b>○ 위원장 김현삼 </b> 신현석 위원님 수고하셨습니다. 다음에는 신종철 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 신종철 위원 </b> 부천 출신 신종철 위원입니다. 제가 작년 행정사무감사에서 통일ㆍ동북아 문제에 대한 문제 제기를 한 바가 있었습니다. 그때도 동일하게 우리 경기개발연구원의 비전과 미션을 보면 비전은 동북아시대의 미래를 선도하는 경기도의 싱크탱크 GRI, 그리고 미션을 보면 그중의 하나가 동북아가 국제사회와 함께하는 세계적 연구기관이라고 돼 있고 중점사업의 주요현안과 비전을 제외하면 6대 중점사업 중의 하나가 동북아사업입니다. 여기에 통일문제 포함되어 있겠죠. 그리고 그 당시에도 이런 맥락에서 우리 경기개발연구원의 동북아ㆍ통일사업에 대한 문제가 좀 있다. 그래서 그런 부분을 보완하기로 얘기를 했었죠? 그건 기억이 나십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 신종철 위원 </b> 그런데 좀 이상하게도 2012년 행정사무감사 처리요구사항 조치결과를 보면 거의 나머지 내용은 다 조치결과가 완료됐는데 통일문제에 관한 내용은 추진 중으로 돼 있거든요. 1년 내내 추진을 한다는 얘기인가요, 아니면 추진한 게 없다는 얘기인가요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 위원님께서 잘 지적을 해주셨는데요. 지금 통일문제나 이런 것에 대해서는 저희들이 한계가 있는 게 분명합니다. 저희 지자체 연구소로서 한계가 있는 게 분명하고. 그럼에도 불구하고 저희들이 접경지역도 많기 때문에 그래서 상당히 많은 정책과제를 하고 있고요. 그래서 그 추진 중이라는 게 2014년도 정책과제로 경기도 남북교류 기본구상 연구를 지금 수행 중에 있고요. 앞으로 상황이 바뀌면 교류가 활성화될 때를 대비해서 끊임없이 저희들이 내부적으로는 지금 하고 있습니다. 
</p>
<p><b>○ 신종철 위원 </b> 제가 이렇게 2013년도 진행된 내용을 보면 없는 것 같은데요. 실행한 사업들이 있습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 2014년도 경기도 남북교류 기본…….
</p>
<p><b>○ 신종철 위원 </b> 2014년도가 아니라 13년도 올해 문제를 얘기하는 거죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 통일문제에 대해가지고? 지금 한 게 다섯 가지로 말씀드리겠습니다. 그러니까…….
</p>
<p style="padding-left:2.4em">    (경기개발연구원장, 관계직원에게 확인 중)
</p>
<p style="padding-left:1.2em">  죄송합니다. 다섯 가지를 하고 있는데요. 2014년 그건 지금 말씀드렸고요. 두 번째는 경기도 남북교류 지역협의회 구축 그런 사업이 있고요. 또 경기북부지역의 한중 경협단지 추진 문제가 있고요. 또 위탁연구과제로 평화통일시대를 대비한 경기도 접경지역 행정통합방안 연구를 한 게 있고요. 또 DMZ 먹는 샘물의 남북공동개발방안 연구를 하고 있고요. 그리고 개성공단 10년 평가와 새로운 남북경협 모델의 모색 그래서 경기도의 역할을 중심으로 연구하고 있고 또 현안으로 최근 북한문제 전망과 과제 이런, 저희들이 나름대로 통일문제를 하고 있고 참고적으로 말씀드리면 통일ㆍ동북아센터 저희들이 중요해서 센터를 하고 있는데 인원이 지금 적습니다. 저희들이 전문인원이 3명 있는데 1명은 서배티컬(sabbatical) 가 있어서 지금 정규 2명이 있는데 그분들이 그래도 열심히 나름대로 하고 있고 그래서 저희들이 정체성 문제도 있고 해서 통일ㆍ동북아문제를 연구하는 분들이 굉장히 힘듭니다. 정체성 문제란 건 뭐냐 하면 저희들이 지자체 연구소로서 어느 정도 범위까지 그걸 해야 되는가라는, 위원님들께서도 아시겠지만 그런 문제가 있고 그럼에도 불구하고 그러한 제약조건 하에서도 저희들이 열심히 하고 있다 이렇게 말씀을, 100% 만족스럽지는 않으시겠지만 하고 있다고 말씀드릴 수 있습니다.
</p>
<p><b>○ 신종철 위원 </b> 하여튼 지금 2013년도에 진행된 과제들을 보면 통일ㆍ동북아 문제가 6대 사업이지만 대단히 소극적으로 대응하고 있다. DMZ는 60주년 현안사업들이 있으니까 관계된 것 같고요. 접경사업, 비슷한 류의 사업들에 대한 고민들만 돼 있지, 실질적으로 동북아문제에 대한 고민들은 빠져있다고 저는 보여지거든요. 지금 말씀하신 대로 물론 국가사업이 있을 거고 우리 지방자치단체에서 어느 정도 갈 것인가의 문제는 그 역시 또 GRI에서도 지방자치단체에서 통일문제를 어떤 정도 접근하는 것이 적정한가에 대한 기준원칙이 나와야 되는 거죠, 거꾸로 역으로 말씀드리면요. 그리고 지금 당장도 최근 몇 년간이 남북관계가 대단히 경화되고 심지어는 포격사건도 발생한 준 전쟁위기 상황까지 발전하지 않았었습니까? 그런데 문제는 뭐냐 하면 전쟁시기 때 평화를 생각해야 된다는 것이 중요한 교훈 아닙니까? 전쟁시기 때 전쟁만 하는 것이 아니라 어떻게 평화를 준비할 것인가를 고민해야 되는데 남북 냉각시기에 손 놓고 있는 것이 된다고 하면 그건 정책을 연구하는 사람으로서 전 옳지 않다라고 생각합니다. 더군다나 그런 냉전시대에, 남북위기시대에서 어떻게 향후 교류를 만들어 나가고 어떻게 평화를 준비할 것인가를 노력하는 것이 매우 중대한 역할 중에 하나일 거다. 그 속에서 우리 지자체, 경기도라는 거대한 지자체가 갈 수 있는 역할은 나름대로 있을 거라고 저는 생각하거든요. 그러니까 그 점에서 다시 한 번 고민해 주시길 바라겠고요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다.
</p>
<p><b>○ 신종철 위원 </b> 부연을 약간 하면 엊그저께 바로 우리 박근혜 대통령과 푸틴 대통령이 나진-하산, 나진ㆍ선봉지구와 결국 하산, 그러니까 러시아를 연결하는 문제의 사업들을 진행하지 않았습니까? 얼마 전까지 전쟁의 문제에 있던 남북관계에서 새롭게 러시아와 북을 경유하는 문제는 그런 것들이 벌어지는 것이 동북아의 아주 다이내믹한 상황인데 그 다이내믹한 상황 속에서 우리와 관계된 부분들도 역시 있을 거라고 생각합니다. 그러니까 동해선이 있다라고 하면 경의선 문제가 있고요. 이게 다 여태까지 제기된 문제인데 그게 언제 닥쳐올지 모른다는 점에서 다시 한 번 통일ㆍ동북아센터의 역할 이런 부분을 좀 더 강화해서 2014년도에는 동북아 전체에 대한 구상과 내용이 나왔으면 하는 바람입니다.
</p>
<p style="padding-left:1.2em">  역시 마찬가지로 한 가지만 더 질의하면 2청 남북협력담당관실을 우리가 하면서 제기되었던 것이 남북협력담당관실이 기존의 사업에 머물러 있거든요. 그런데 그 내용들을 보면 결국 남북협력사업과 통일문제, 북한이탈주민 이런 문제에 대해서 경기개발연구원과 떨어져 있는 것 같아요. 싱크탱크 기능과 현장이 떨어져 있는 것 아닌가 저는 그런 생각도 해봤습니다. 그런 점에서도 현장에서 일하는 부서와 경기개발연구원과의 연관성, 이 부분에 대해서도 한번 점검해 주시길 바라겠고요. 나중에 이건 서면으로 대답해 주시면 고맙겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다.
</p>
<p><b>○ 신종철 위원 </b> 존경하는 신현석 위원님이 얘기하신 의정연구센터 문제인데요. 센터장님 한번 잠깐.
</p>
<p><b>○ 의정연구센터장 신원득 </b> 의정연구센터장 신원득입니다.
</p>
<p><b>○ 신종철 위원 </b> 일단 성과부분들은 자료로 나왔고 아까 원장님도 말씀하셨는데 대표적인 이걸 해야 되는 이유가 뭐라고 생각하세요? 실제 수행하는 입장에서 본다라고 하면 의정활동과 결합돼서 가장 두드러진 점이 어떤 점이라고 생각하십니까?
</p>
<p><b>○ 의정연구센터장 신원득 </b> 아까 원장님이 업무보고한 자료에는 다 싣지 못했습니다만 그동안에 도의회가 주요기능이 입법기능이라든지 또 감시ㆍ비판기능이 가장 중요하다고 보고 있습니다. 그런데 그동안에 외부에서 보면 의원님들의 정책역량이 좀 모자란다 이런 얘기가 나오는데요. 의원님들이 그동안에 한 400여 건의 자료요청을 하고 있습니다. 그게 저희들이 의원님들이 활동할 수 있는 객관적 판단근거를 제공하고 있다는 점에서 가장 의정센터의 중요점이 있다고 생각하고 있습니다. 
</p>
<p><b>○ 신종철 위원 </b> 지금 법적 문제로 우리가 1년을 지낸 건가요?
</p>
<p><b>○ 의정연구센터장 신원득 </b> 저희들이 실제로 4월 달부터 시작했기 때문에. 
</p>
<p><b>○ 신종철 위원 </b> 4월부터. 그러면 1년이 안 됐는데 어쨌든, 그러면 현행 제도에서 법적으로 이 제도가 문제가 있습니까?
</p>
<p><b>○ 의정연구센터장 신원득 </b> 법적으로 전혀 문제가 없습니다. 
</p>
<p><b>○ 신종철 위원 </b> 그럼 본 위원이 생각할 때는 어쨌든 현행법 쪽에서 의정활동을 지원할 수 있는 유일한 체계가 의정연구센터죠? 
</p>
<p><b>○ 의정연구센터장 신원득 </b> 네, 그렇습니다.
</p>
<p><b>○ 신종철 위원 </b> 알겠습니다. 이 문제와 관련해서 이런 점을 생각해 봤습니다. 2014년 예산이 반영이 안 됐다는 문제를 보면서 도의회와 도 집행부 또는 산하기관과 중요한 정책에 대해서 항상 교류하고 공감대를 가져왔습니다. 예를 들어서 재정위기라고 했을 때 도 집행부가 저희 도의회한테 어떻게 했습니까? 이 재정위기에 대해서 어떻게 극복할 건지 같이 논의를 해왔던 것이 여태의 모습입니다. 그런데 이 의정연구센터가 지금 말씀하신 대로 법적으로 문제가 없는 유일하게 대한민국의 사례가 될 수 있는 중요한 의정지원의 기능들을 갖고 있는데 이 부분에 대해서 어떻게 경기도는 일방적으로 이 예산을 편성을 안 합니까? 그 부분에 대해서 원장님은 사후통보를 받으신 건가요, 아니면 사전협의가 되신 건가요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 예산이 작년에 107억에서 90억으로 한 20% 이상 깎여서 내려온 거기 때문에, 저희들 예산과정이 항상 그렇습니다. 저희들이 요청하면 항상 이렇게 내려왔기 때문에 작년에도 그랬고 그래서 굉장히 럼섬(lump sum)으로 되는 거기 때문에 그래서, 다만 저희들이 아까도 말씀드렸지만 이게 신규 신설조직이기 때문에 새롭게 사람들을 뽑았고 그랬기 때문에 우리가 기존에 연구원 운영상에서 이걸 만약에 새롭게 조직개편을 통해서 하나 만들었으면 기존의 예산방식을 통해서도 어떻게 해볼 수 있는 방법이 있을지 모르겠습니다만 이건 신설조직이고 새로운 사람을 했기 때문에 그래서 그런 부분들이 빠졌다 이렇게 생각을 하는 겁니다. 
</p>
<p><b>○ 신종철 위원 </b> 하여튼 이 문제에 대해서 연구원 자체에 큰 문제를 제기하기보다는 경기도 정책 차원에서의 문제라고 본 위원은 생각합니다. 그래서 위원장님, 나중에 기조실 할 때 우리 기조실이 중요한 정책에 대해서 도의회와 사전협의하는 관행에도 불구하고 일방적인 이런 조치가 나온 부분에 대해서는 한번 점검을 해봤으면 하는 바람입니다. 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 신종철 위원님 수고하셨습니다. 다음에 윤희문 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 윤희문 위원 </b> 이천 출신 윤희문 위원입니다. 감사자료 열심히 만드시느라고 고생하셨네요. 다른 데보다는 그래도 성의 있게 하신 것 같아요. 감사합니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 감사합니다.
</p>
<p><b>○ 윤희문 위원 </b> 저는 몇 가지 우선 감사의 뜻을 전할게요. 이천지역에서 주민들의 오랜 숙원이었던, 민군정책팀에서 했던데 지난해에 제가 질의도 하고 또 제가 공무원 출신입니다. 그래서 인허가를 담당하다 보면 오랜 시간을 끌고 이런 부분이 민군정책팀에서 군사업무 협의를 통해서 규제완화를 하는 것으로, 그걸 행정기관에 위탁하면 행정기관의 공무원들은 빨리 처리가 될 거예요. 그래서 주민들한테 상당히 도움이 될 걸로 판단이 되거든요. 12월 달에 최종적으로 절차가 남았습니다마는 그 부분에 대해서 우선 고맙게 생각을 하고, 두 번째 2청의 현안사항으로 있었던 팔당 특별지역 내 특정수질유해물질 관리제도 개선방안 해서 조영무 박사가 한 자료가 있습니다. 도의 기획관리실장을 통해서 이걸 해결해야 된다, 이 부분은 환경부장관하고 면담을 하면서 했던 사안인데 앞으로 이 방안을 갖고 집행부하고 제가 같이 의논해서 우리가 어떻게 대응할 것인가라고 하는 부분을 찾겠다라고 해서 고맙게 생각을 하고요. 또 지난해 행감을 통해서 존경하는 권오진 위원님하고 경기개발연구원에서 많은, 그 엄청난 일을 많이 연구도 하고 하면서 비단 왜 동부권에는 관심이 없느냐. 팔당상수원 보호대책지역 내에 대해서는 연구한 게 없더라고요. 그 토질에 대해서 뭘 할 것인가라고 했더니 이상대 실장님이 지시하셔가지고 강상준 연구원 외에 이기영, 유영성, 조성한 공동연구를 통해서 경기 동부권 지역자원의 효율적 이용 및 관리비전, 주민들이 보면 이게 만족하진 못하죠. 그러나 정책적으로 봤을 때 더 깊은 연구가 필요하다 이런 감을 갖지만 그래도 관심을 가져주셨다는 데에서 참 고맙게 생각을 합니다. 며칠 전에 지난주에 양평에서 팔당의 상수원보호지역과 관련해서 10주년 기념식이 있었어요. 뭐에 대한 10주년이냐면 민간단체들이 형성됐습니다. 1988년인가 아마 9년 이렇게 돼서 10주년 기념을 하는 거예요, 기념식이요. 팔당상수원 보호지역으로 지정하자 여주, 양평, 가평 이쪽 주민들이 대단위로 가서 데모를 하고 그런 부분이 있었어요. 그와 관련해서 그동안 많은 변화, 상수원보호지역이 설치가 되고 지금 오염총량제 시행하기까지의 그 과정 있지 않습니까? 그런 부분도 영상을 통해서 보고 환경부장관도 참석을 했고 그때 지사님은 참석을 못하셨고 외국에 가셨을 거예요. 그래서 박수영 행정부지사가 참석을 하고 그랬던 적이 있는데 그걸 보면서 앞으로는 이 부분에 어떻게 더 환경도 보전해야 되고 또 주민들도 살아야 될 것인가라고 하는 부분이 걱정스럽더라고요. 그래서 그와 관련해서 제가 자료요청을 했습니다마는 오염총량제가 금년도 6월, 7월부터 시행하도록 됐지 않습니까? 그래서 여기서 저기했는데 이건 일방적으로 수질을 얼마나 깨끗하게 할 것인가, 그 지역에 있지 않습니까? 수질 목표를 두고. 그런데 주민들은 그 부분에 대해서 아직 감이 오지를 않죠, 일반 주민들은. 정책적인 것만 갖고 하니까. 그러면 축산을 하시는 분들도 있고 또 여러 가지 오염원이 되는 그런 기관이 많이 있습니다. 그런데 그런 데에 대해서 우리가 연구를 하거나 이런 부분은 아무것도 없어요, 그 사람들 주민들 입장에서. 수질대책을 수질을 어떻게 해서 한다는 규제를 위한 것은 있지만 먹고 살아야 될 주민들이 팔당상수원 보호지역 내의, 그 지역의 그런 부분은 없더라 이런 얘기예요. 그래서 이와 관련해서 향후 대응방안에 대해서 연구하실 용의가 있으신지. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희 연구원에서 지난 3년 동안 수질오염총량관리제도와 관련해서 16건 정도 연구과제를 수행한 적이 있고요. 그래서 그 과정 속에서 경기도 및 시군의 지역개발 요구를 최대한 반영을 해왔거든요. 예를 들어서 2013년 6월에 나온 경기도 수질오염총량 기본계획 같은 것도 제시했고 다만 지역의 직접 현안, 지역주민들하고 그건 저희들이 직접 더 지역 현안의 이야기를 듣고 좀 더 현장의 이야기를 듣고 반영해서 지속적으로 그 연구를 하겠습니다. 지금 청정산업지원 연구 같은 경우도 연구가 진행 중에 있고요. 하여간 추가적으로 이 오염총량제 가지고는 굉장히 많은 이슈가 되고 있기 때문에 저희들이 계속 연구를 하고 있습니다. 
</p>
<p><b>○ 윤희문 위원 </b> 이 환경 측면에서 보면 오염총량제가 절대 필요하다라고 얘기하지만 주민들의 이로 인한 고통은 지역마다 온도의 차이는 있겠지만 상당합니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 윤희문 위원 </b> 아시겠지만 광주 같은 경우 과거에 처음 시행을 할 때 상당히 불미스러운 일도 있었지 않았습니까? 이천, 여주, 양평 다 그렇고 용인도 일부지역은 이로 인해서 어떻게 할 수가 없어요. 그래서 주민들에게 미치는 영향에 대해서는 반드시 그 부분이 필요하다라고 생각이 듭니다. 
</p>
<p style="padding-left:1.2em">  그다음에 앞서도 제가 칭찬을 했습니다마는 동부권 지역자원의 효율적 이용 및 관리비전 있잖아요? 이 부분은 원장님이 특별한 관심을 가지시고 더 연구가 될 수 있도록 이렇게 해주시기 바라겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 윤희문 위원 </b> 그다음에 제가 요구한 자료 중에서 연구원 자질향상을 위한 사업현황이 뭐가 있느냐라고, 이 부분은 왜냐 하면 연구원이 계속 그 자리에 있다 보면 빼먹을 거 다 빼먹어서 남의 것 베끼는 일뿐이 할 수가 없어요. 그래서 자기충전을 해야 된다고요. 그러면 외국의 학회에 가서 참여해서 토론도 하고 세계 흐름도 봐야 될 거고 이런 부분이 절대 필요하다고 보거든요. 그런데 그와 관련돼서 예산이 있는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 다양한 방식으로 그게 있는데 출장형식도 있고요. 저희들은 연구연수년제도 있어서 일정연도 이상 지나면 외국에 가서 선진 연구기관이나 학교나 이런 데 가서 새로운 어떤, 1년 가까이 할 수 있는 기회도 있고 그래서 저희들이 연구원의, 왜냐하면 연구원이 가장 중요한 건 자질이기 때문에 그거 하나밖에 없거든요. 사실 우리가 공장도 아니고 여기서 뭘 만들어내는 조직도 아니고 연구보고서를 만들어내는 조직이기 때문에 연구원이 가장 중요하기 때문에 그래서 저희들이 그런 다양한 재충전 기회라든지 연수기회라든지 이런 건 적극 권장도 하고 있고 지금 시행도 하고 있습니다. 
</p>
<p><b>○ 윤희문 위원 </b> 원장님께서 “별 걱정을 다 하고 있네.” 이렇게 하실는지 모르지만 이 부분은 연구원들한테 아주 중요한 문제가 아닌가 생각이 듭니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아닙니다. 그런 관심을 가져주셔서 저희들은 고맙게 생각합니다. 
</p>
<p><b>○ 윤희문 위원 </b> 마지막으로 한 가지만 더 질문을 드리면 지난해 대비해 예산이 한 20억 줄었다고요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 17억 정도.
</p>
<p><b>○ 윤희문 위원 </b> 27억이요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 17억이요. 
</p>
<p><b>○ 윤희문 위원 </b> 그럼 핵심적으로 줄은 것이 그 부분에 뭐, 뭐입니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 예산 같은 경우에 아시겠지만 어떤 항목에 대해서 얼마 줄여라, 어떤 항목 얼마 줄여라 이렇게 내려오는 게 아니라 저희가 예산을 쭉 내면 그냥 얼마다 이렇게 내려오기 때문에 그래서, 그런데 지금 저희들이 작년도와 비교해 봤을 때 저희들 해오던 지속적 사업이 있고 그런데 그 부분은 만족스럽지는 않지만 그렇지만 지금 저희들이 줄은 부분은 공교롭게도 의정연구센터 쪽 예산은 확보가 안 되고 있습니다. 
</p>
<p><b>○ 윤희문 위원 </b> 의정연구센터의 그 부분 예산은 별도였었잖아요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 작년에도 별도로 이제…….
</p>
<p><b>○ 윤희문 위원 </b> 별도로 됐던 거 아닙니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 별도로 됐었었죠. 
</p>
<p><b>○ 윤희문 위원 </b> 네, 잘 알았습니다. 추가질문 나중에 하도록 하겠습니다. 
</p>
<p style="padding-left:2.4em">    (김현삼 위원장, 김광철 간사와 사회교대)
</p>
<p><b>○ 위원장대리 김광철 </b> 윤희문 위원님 수고하셨습니다. 다음은 임병택 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 임병택 위원 </b> 시흥 출신 임병택 위원입니다. 우리 2013년도 경기도 그다음에 31개 시군 모두가 다 예산 때문에, 재정난 때문에 좀 어려운 시기였는데요. 우리 경기개발연구원은 명실상부한 경기도민들의 싱크탱크지 않습니까? 이러한 경기도 재정난에 대한 예측 또는 조기경보 이런 역할을 좀 하셨다고 보십니까, 아니면 일이 터진 뒤에 사후약방문 형식의 후속대응에 치중하셨다고 보십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 경기도 지자체, 특히 경기도의 재정위기에 대해 가지고는 열몇 건에 걸쳐서 지속적으로 문제제기를 했었고요. 그것은 저희들 지금 얘기하는 게 사후약방문은 아니고요. 2011년부터 굉장히 위기다. 그래서 여러 가지 다양한, 간단히 몇 가지 타이틀을 말씀드리면 지방의 희생을 강요하는 재정현실이라든지, 2011년입니다. 지방예산의 위기와 정책 방향이라든지, 이것도 11년도 이야기고요. 또 지속적으로 저희들이 경고를 했었죠. 했는데 이게 그렇습니다. 경고를 하는 거하고 현실에서 닥쳐서 하는 문제하고는 약간 좀 다른 것 같습니다. 저희들은 연구하는 부서기 때문에 연구하는 사람들은 또 걱정이 많죠. 걱정이 많아 가지고 다양한 문제점들을 제기했었고 그렇습니다. 
</p>
<p><b>○ 임병택 위원 </b> 경기개발연구원의 조기경보가 지속적으로 있었음에도 불구하고 집행부에서 안일한 대응을 하신 거네요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 본인들은 최선을 다했는데 결과론적으로 세수 같은 것이 당초 예상보다 덜 채워져서 그런 불가피한 일이 있었겠다 이렇게 생각하고 있습니다. 특히 전망이라는 것이, 전망을 말씀드리면 경기도 같은 경우는 부동산경기하고 굉장히 밀접한 연관이 돼 있는데 이 부동산경기가 좋아질 것이라는 얘기도 부분적으로 한 쪽에 있었던 것도 사실이고 그래서 그 부분에 대해서는 굉장히 사전적으로 계획하기가 힘들었던 부분이 있었지 않았나 이렇게 생각을 합니다. 
</p>
<p><b>○ 임병택 위원 </b> 그러한 역할, 좀 더 도의회에도 직접적으로 그러한, 도민의 민생과 직결된 문제 아니겠습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 임병택 위원 </b> 이런 문제점을 느끼신다면 즉시 의회와도 좀 소통해 주시고 이야기를 좀 나눠주시기를 당부드릴게요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 자료에 보면 우리 경기개발연구원이 재정난 속에서 참 고생하시는 것 같고요. 일단 자료 중에 보면 경기도 및 시군으로부터 의뢰받은 연구용역 현황이 있습니다. 자료집 두꺼운 거에 15페이지인데요. 시군으로부터 의뢰받은 연구용역 현황을 보면 2011년 44건, 2012년 41건, 2013년 29건으로 대폭 줄었습니다. 특히 우리 경기도도 줄었고요. 시군도 2011년 25건수, 2012년 20건수, 2013년 13건수 이렇게 줄어들었는데요, 급격하게. 이유가 무엇일까요? 우리 경기개발연구원의 연구결과를 신뢰하지 못하는 시군의 분위기가 형성된 것 아니겠습니까? 어떻게 판단하십니까, 이 결과에 대해서? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 그 건수는 좀 줄었지만 금액으로는 줄지 않았고요. 저희가 2011년도, 그때가 가장 사실은 건수도 금액도 많았었는데 저희들이 사실은 시군하고 하려고, 그래서 2013년도에는 시군에 법정계획 같은 게 있고 그러면 저희들한테 좀 더 많은 의뢰를 했을 텐데 마침 법정계획이 없는 해라고 그러더라고요. 상대적으로 그래서 줄었지 시군이 저희 연구원의 어떤 작업에 약간 문제점이 있어서 그런 것은 아니라고 판단이 됩니다. 내년도에는 상당히 또 많아지리라고 저희들이 예상을 하고 있거든요. 
</p>
<p><b>○ 임병택 위원 </b> 이 수치는 어떤 것을 보여주는 걸까요? 2010년도에서 2013년 사이에 아예 우리 경기개발연구원에 연구용역을 의뢰하지 않은 시군이 있습니다. 성남ㆍ구리ㆍ고양시ㆍ광주ㆍ이천ㆍ양평 등등 해서 9곳이 10ㆍ11ㆍ12ㆍ13, 4년 동안 아예 연구용역 의뢰를 안 했어요. 이 결과는 무엇을 반증하는 것일까요? 이러한 현황파악을 아직 못하고 계시죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 이런 걸 일일이 다 파악을 해야 되는데 좀 놓친 부분이 있는 것 같고요. 그런데 전혀 없는 부분에 대해서는 저희들이 한번 왜 그런지 다시 한 번 평가를 해보도록 하겠습니다. 그래서 문제점이 드러나면 적극적인 조치도 하고 그래서 저희들이 내년부터는 좀 더 시군과의 밀착연구를 하겠다고 큰 하나의 어젠다를 설정하고 있거든요. 그래서 이 부분에 대해서는 좀 더 연구를 하도록 하겠습니다.
</p>
<p><b>○ 임병택 위원 </b> 성남ㆍ고양ㆍ남양주, 이제 백만 도시들이죠. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 큰 도시들인데. 
</p>
<p><b>○ 임병택 위원 </b> 작은 시군도 있습니다마는, 좀 더 적극적인 시군과의, 일단 시군이 그래요, 경기개발연구원을 신뢰하시고 적극적으로 연구용역도 의뢰하고 그런 관계가 되었으면 좋겠다는 생각을 해봅니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 
</p>
<p><b>○ 임병택 위원 </b> 원장님, GTX 관련해서요. 내년도 GTX 관련 전망을 어떻게 보십니까? GTX는 김문수 지사의 정말 핵심 중의 핵심사업이었고요, 중점 중의 중점사업이었습니다. 그리고 GTX 3개 노선이 지나가는 예정 노선지에, 특히 금정 같은 경우에는 GTX 연내 착공 이런 홍보물이 아직도 부동산에 붙어있어요. 그런데 GTX 관련해서 예비타당성조사도 벌써 2년 가까이 됐는데 발표되지 않고 있고요. 또 정부는 예타 결과가 발표되지 않았기 때문에 예산을 세울 수 없다 그러고요. 이 악순환이 계속 이어지고 있습니다. 동탄 같은 경우에도 광역교통개선대책비 관련해서 LH와 국토부가 대폭 삭감을 해버렸습니다. 그래서 삼성-동탄 구간의 GTX 또한 하세월될지도 모르고 있습니다. 그래도 GTX 관련해서 경기개발연구원의 역할도 상당하셨는데요. 이 사태를 어떻게 보고 계시고 내년 전망을 어떻게 하시는지 원장님의 견해를 듣고 싶습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아까도 위원님들 말씀하셨지만 이게 대규모 SOC 사업인데 지금 국가예산도 그렇게 쉽지 않은 것 같아요, 최근에. 국가예산도 쉽지 않고. 그래서 이 SOC 사업들이 상당히 전 국가적 차원에서 그렇게 쉽지는 않은 상황이거든요. 그리고 저는 개인적으로 GTX 사업은 경기도 입장에서는 경기도의 SOC를 큰 폭으로 개선하는 거기 때문에 경기도 차원에서 저는 글로벌 경쟁력 제고하고 도민 편의 증진 차원에서 필요한 사업이라고 생각하지만 비용이 지금 만만치가 않다. 10조 이상 들어가고 또 이게 대형 국책사업으로 추진돼야 되기 때문에. 그런데 이제……. 
</p>
<p><b>○ 임병택 위원 </b> 그러한 부정적인 현실에 대한, 우리가 보통 플랜B라고 표현하지 않습니까? 지속적으로 저는 요구해 왔는데 김문수 지사가 만약에 내년에 출마하지 않고 도지사를 그만둔다고 했을 때에 GTX 사업은 어떻게 될 것 같으세요? 이거 아주 중요한 질문인데요. 어떻게 될 것 같으세요, 원장님? 거기에 대한, 우리 경기개발연구원이 김문수 지사님이 내리는 오더만 받고 수행하는 기관이 아니라 저는 경기개발연구원의 주인은, 도지사는 바뀝니다. 도의원은 바뀌지만 경기도민은 계속 있는 분들이시고요. 그러한 플랜B와 관련된 대비책을 세우고 있냐는 그런 질문을 드리는 거예요. 어떻게 생각하세요, 원장님? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 GTX에 대해서 제가 좀 더 말씀을 드리면 일단 연말에 예비타당성조사가 발표될 예정으로 알고 있고요. 
</p>
<p><b>○ 임병택 위원 </b> 작년에도 그랬거든요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 현재 상황을 지금 말씀드립니다. 그래서 예정이니까 그거는 저희가 100% 딱 한다는 날짜가 정해져 있는 것은 아니고. 그런데 그 동탄-삼성은 현재 기본계획이 수립 중에 있다고 하고요. 그래서 2014년은 실시설계 후에 공사에 들어갈 것으로 예상이 되는데, 그게 현재의 상황판단이고. 그래서 GTX 문제는 그렇다고 봅니다. 이게 대형 SOC가 되다 보니까 수도권, 비수도권의 문제도 지금 결부가 되고 그래서 굉장히 간단한 사업은 아닌 것 같은데 하여간 경기도 입장에서는 이제는 됐으면 좋겠다라는 그런 개인적인 소망을 가지고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 플랜B를 미리 만들어낼 필요성은 없습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 플랜B라는 게 하는 거, 아니면 안 하는 건데 물론 플랜B도 항상 어떤 사업을 할 때…….
</p>
<p><b>○ 임병택 위원 </b> 저는 박사님들께서 준비하셔야 된다고 봐요. 더 이상 저도 신뢰가 안갑니다. 집행부의 의견도 그렇고요. 저는 위원 개인의 입장이지만. 김문수 지사가 10월 30일 날 성명서를 낸 게 있어요. 동탄 2신도시 관련해서 LH공사와 국토해양부가 광역교통개선대책비를 몇 조 잘라냈거든요. 혹시 그 내용은 한번 공유를 하시고요. 저는 사태가 아주 심각하다, GTX 관련된 사태가. 오죽했으면 김문수 지사 명의의 성명서를 냈겠습니까. 저는 금정에 GTX가 뚫릴 거라고 믿고 있었던 경기도민들, 참 그분들에게 사기 친 사람들이 과연 누군지에 대해서 참, 제가 좀 표현이 격해서 죄송합니다. 
</p>
<p style="padding-left:1.2em">  그리고 하나만 더 말씀을 드릴게요. 제안인데요, 정책적 제안인데 한번 생각을 해보시죠. 경기도 연천이 수도권입니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 수정법상에는…….
</p>
<p><b>○ 임병택 위원 </b> 수정법상에는 수도권이지만……. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 수정법상에는 수도권이라고 돼 있는데 사실은……. 
</p>
<p><b>○ 임병택 위원 </b> 아니죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 수도권이라고 얘기하기는 너무나 열악하고 그래서 문제가 많습니다. 저희도 그래서 계속…….
</p>
<p><b>○ 임병택 위원 </b> 그렇죠. 그런데 저는 우리 경기도의 싱크탱크 박사님들의 기본적인 연구계획도 있지만 보면 이 자료, 이러한 우리 업무보고에도 수도권 규제완화의 새로운 전략 연구에서 수도권 대 비수도권 대립구도 속의 정치적 이슈 이런 표현들이 있는데요. 저는 우리 경기도라면 가평ㆍ연천, 수도권 아니잖아요. 그런데 이 프레임의 전환, 서울 중심주의 대 비서울 간의 연대라는 그러한 전략적인 프레임, 틀. 이런 방향의 전환을 저는 경기도가 앞장서서 정말 과밀화돼 있는, 세계에서 가장 과밀화돼 있는 서울에 밀집되어 있는 것들을 우리 경기도로 가져올 수 있는 이러한 프레임의 역제안 등등등을 경기개발연구원이 앞장서서 해주셔야 되지 않을까. 그래서 수도권, 비수도권 하면 우리는 늘 수도권 편이에요. 그렇죠? 그런데 서울 중심주의 대 비서울 이런 식의 전략적인 설정을 해서 우리가 정책들을 연구해 나가면 그리고 또 그러한 의제들을 던지면 훨씬 더 우리 경기도에 이익이 되지 않을까라는 생각을 좀 해보게 됩니다. 이것은 제 개인적인 사견 또는 소신이기도 한데요. 
</p>
