<p><b>○ 배수문 위원 </b> 그게 좀 필요할 것 같고요. 왜 그런 말씀을 드리느냐면 어쨌든 도지사의 정치적 성향에 따라서 많은 연구들이 한 쪽으로 편향될 수밖에 없는 한계적인, 태생적 한계가 있는 게 맞기 때문에 그런 걸 벗어나서 원래 연구한다고 말씀을 하지만 실질적으로 국가 정책과 경기도 정책에 맞춰서 연구할 수밖에 없는 구조죠. 그래서 지금이 학자적 양심 그다음에 학자적으로 정말 도민을 위해서 개인이 생각하는 연구주제들을 선정할 수 있는 가장 좋은 기회라고 생각합니다. 동의하시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 이제 내년도에 지자체 선거를 앞두고서 경기도의 민선 6기를 대비한 정책과제들을 쫙 집어 가지고 연구를 하고 있고요. 그리고 개별 연구자들의 소위 기본연구라든지 이런 것은 여태까지 크게 지사의 어떤 정치적 성향에 따라서 이렇게…….
</p>
<p><b>○ 배수문 위원 </b> 그것은 동의하는데요. 그럼에도 불구하고 어떤 연구결과가 나왔을 때 어쨌든 가장 객관적으로 보는 시각에서의 연구결과가 나올만한 시기는 내년이 적기다라고 보는 거죠. 그러니까 사회적인 곡해된 시선들을 가장 중립적으로 갖다 놓을 수 있는 시기다라는 거죠. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 어떻게 보면……. 네, 그렇습니다. 그런 것은 독립적으로 할 수 있는…….
</p>
<p><b>○ 배수문 위원 </b> 무슨 얘기냐 하면 연구주제에서도 그렇고……. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 위원님 말씀 제가 충분히 이해하고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 정부3.0이라는 단어 하나가 들어감으로 인해서 연구자가 의도했던 그리고 연구자가 연구에서 담고 싶고자 했던 내용이 3.0으로 인해서 완전히 국가 쪽의 정책들을 담아내는 것처럼 보일 가능성이 되게 높거든요. 그런 거를 얘기하는 거죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 그래서 정치적으로 연구자들 입장에서는 본인들이 소신을 갖고 연구할 수 있는 가장 좋은 기회다라고 생각하는 거고 그거에 맞춰서 연구가 됐으면 좋겠다라는 주문을 합니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 충분히 알겠습니다.
</p>
<p><b>○ 배수문 위원 </b> 오늘 아침 뉴스에 북부청에서 DMZ 관련해 가지고 올해는 67억인가요, 그렇게 확보됐던 국비가 내년에 147억 확보돼 가지고 %로 137%가 늘었어요. 아마 불과 5년 사이에 25배나 많은 DMZ 연구가 났다라는 기사와 맞물려서 경발연의 일정부분 역할이 있었다라고 칭찬을 하고 싶습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다. 
</p>
<p><b>○ 배수문 위원 </b> 근데 147억 확보된 거와 더불어 단순히 행사진행용 그다음에 개발용만 지금 들어있거든요. 지금 군ㆍ관 관련해서 군 출신들이 연구원으로 들어와 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 저희들이 민군협력팀이 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 네, 그쪽 팀에서 보다 좀 더 비용을 받을 수 있으면 더 좋고요. 그 비용 중에서 일부를 연구원에서. 그렇지 않더라도 거기에 맞춰서 단위사업별로 연구가 좀 진행이 됐으면 좋겠다는 생각이 들어요. 평화공원 관련해서, 임진각 관련해서. 그게 이제 지금 시대를 반영하는 것들이 1년, 2년 사이에도 또 트렌드가 바뀌기 때문에 그런 것들은 지속적으로 지원해 준다면 올해 147억 확보에 많은 도움을 준 것처럼 또 2015년에 더 많은 지원을 받을 수 있는 근거가 될 수 있지 않은가라는 생각을 하거든요. 연구가 밑받침되지 않으면 그런 걸 받기 쉽지 않은 건데 많이 해주셔서 상당히 감사하다는 말씀을 다시 한 번 드립니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 감사합니다. 
</p>
<p><b>○ 배수문 위원 </b> 그다음에 연구원들이 혹시 재능기부, 여기서 말하는 재능기부라 함은 지식기부가 되겠죠? 이런 경우가 몇 케이스 있습니까? 여기 엘리트 집단이잖아요. 사회에서 볼 때는 가장 하이클래스 집단이고.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 사회적 기업에서 좀 한 적이 있는 것 같고요.
</p>
<p><b>○ 배수문 위원 </b> 제가 볼 때 전 원의 모든 박사님들이 짬이 되는 대로 이 부분에 대해서는 관심을 갖고 진행하지 않으면 이미지라든가 그리고 갖고 있는 공적기능에서 외부로 비춰지는 것들이 조금은 더 성의껏 도민들을 위해서 연구원이 움직이고 있다라고 할 수 있을 것 같거든요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 좋은 제안이십니다.
</p>
<p><b>○ 배수문 위원 </b> 지금 연 내에 나와 있는 1,700건의 기사문들 다 봤을 때 본인이 파악하기에 그런 엘리트 집단이 사회공헌 차원에서의 행사를 했던 것들이 결코 많아 보이지가 않아요. 경기도시공사 한번 보세요. 의도적으로라도 많이 하거든요. 이런 것들이 여기서 할 수 있는 가장 핵심적인 것은 재능기부일 거예요. 이런 것들의 틀을 갖춰서 그다음에 정말로 경기도를 사랑하는 사람들 연구하고자 하는 그다음에 이런 것들의 비전을 갖고 있는 학생들 교육이라든가 이런 것들을 아이디어가 많으시기 때문에 충분히 가능하다라고 보거든요. 김희연 실장님 같은 경우 그런 아이디어 되게 많으실 것 같은데, 센터장님 가능하시겠습니까? (위원장석을 향하여) 답변해도 되겠습니까?
</p>
<p><b>○ 위원장 김현삼 </b> 네.
</p>
<p><b>○ 사회경제센터장 김희연 </b> 사회경제센터장 김희연입니다. 저희 사회경제센터가 추구하는 바 중의 하나가 이런 사회적 자산을, 사회적 인프라를 자산으로 만들어서 사회에 공헌하는 그런 활동도 저희 센터에서 연구하는 것 중의 하나라고 할 수가 있는데요. 개인적으로 이런 연구활동을 통해서 사회에 공헌할 수도 있지만 개별 박사들이 자기가 갖고 있는 지식들을 사회단체나 시민활동을 통해서 기부할 수 있다고 생각합니다. 
</p>
<p><b>○ 배수문 위원 </b> 지금 아마 암암리에 하시는 분도 생각보다 있는 걸로 알고 있는데 이게 체계화되지 않고 공보가 안 되면 수고는 수고대로 하고, 음지에서 하는 거 모르게 할 일이 아닌 것 같아요. 특히나 여기는 공적기관이기 때문에 그런 걸 널리 알려서 자각을 좀 주는 것도 필요하고요. 지금 홈피를 한번 살펴보세요. 서울개발원 이런 쪽 홈피를 살펴보시면 일부 사회공헌 프로그램들이 가동되고 있거든요. 조금 더 활성화해야 된다라는 생각을 갖고 있습니다. 그래야 이미지, 그러니까 다른 쪽 예산에 비해서 그래도 개발연구원 예산은 아주 많은 손을 대지 않은 것처럼 보이거든요. 그런데 더 많이 확보해 드리려는 노력들을 우리 기획위원님들이 다 하고 있기는 한데 그런 차원에서라면 이런 노력들은 되게 필요하고요. 공익, 봉사 이런 것들 그다음에 재능기부, 지식나눔 이런 것들의 단어에 가장 코어가 여기였으면 좋겠어요. 그런 것들의 시발점을 만들어 주시고 여태까지 했던 것들이 안 했던 게 아니라 했다면 좀 더 모양 있게 만드는, 보기 좋게 만드는 작업들을 체계적으로 좀 해주시는 원이 됐으면 좋겠다라고 말씀을 드립니다. 
</p>
<p><b>○ 사회경제센터장 김희연 </b> 네, 그 부분에 있어서도 별도로 연구를 좀 진행해 보도록 하고요. 참고적으로 저희들이 하는 과제 중의 하나가 지역사회에 있는 복지자원을 발굴하는 그런 연구과제들도 있습니다. 실질적으로 제일 안 되는 부분이 어디에 얼마만큼의 자원이 있는지를 파악하는 것이 굉장히 중요함에도 불구하고 지금까지 그런 노력들이 안 되어 왔기 때문에 내년도 연구과제에도 그런 부분들이 많이 반영되어 있습니다. 위원님 말씀 받아서 그런 부분 사회공헌으로 연계할 수 있는 부분까지도 고민해 보도록 하겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 네, 질의 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 참고적으로 이 사회공헌에 대해서 한마디 말씀드리면요, 저희 연구원의 성격에 관계된 건데요. 저희 연구원들의 연구성과라는 것은 다른 어떤 제조업이라든지 다른 어떤 개인 상품을 얘기하는 게 아니라 다 사회의 굿이거든요. 소셜 굿이라고 생각을 하거든요. 그래서 사실은 저희들이 연구를 열심히 하고 연구성과, 그러니까 저희들이 홈페이지나 이런 거에다가 공개를 하는 것도 그런 이유가 있는 거고…….
</p>
<p><b>○ 배수문 위원 </b> 그런 말씀을 드리는데 그거는 도민들 생각에 어떻게 생각하느냐 하면 회사원으로서 페이를 받고 당연히 해야 될 일을 한 거다라고 생각하는 거죠. 이런 개념의 것들하고 인위적으로 좀 모양을 만들어서 정말 봉사 그다음에 기부하는 차원에서의 연구하고는 좀 의미가 좀 틀린 거죠. 이런 것들은 다른 게 아니라 터치만 해줘도 되거든요, 충분히. 박사님들의 네임 밸류 가지고 터치만 해줘도 충분히 가능한 부분이 있다라고 보여지는 거거든요. 이런 걸 좀 더 만들어 봤으면 좋겠다는 거죠. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 저희들이 그래서 그 부분도 연구를 통해 가지고 어떻게 하면 또 우리들이 가지고 있는 재능을 이런 연구뿐만 아니라 사람들이 필요로 한 부분에서 긁어줄 수 있는가 그것도 적극적으로 해보고요. 좋으신 제안이기 때문에 저희들이 적극적으로 한번 해보겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 김현삼 </b> 수고하셨습니다. 다음엔 신현석 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 신현석 위원 </b> 신현석 위원입니다. 저는 좀 이색적인 이력이 있습니다. 대기업에서 본부장을 하고 경영자를 했는데 그때 가장 큰 베스트셀러가 잭 웰치, 제너럴 일렉트릭사인가요? 제너럴 일렉트릭사 가지고 많은 필독서를 하고 연구도 하고 같이 그걸 어떻게 현업에 적용하느냐 하고 고민도 참 많이 했었습니다. 거기 잭 웰치가 세계적인 최고 경영자이고 제너럴 일렉트릭사가 지금도 최우량기업이 될 수 있었던 이유는 혁신을 끊임없이 했던 것 같습니다. 그래서 가장 큰 혁신 중에 아마 1990년대로 본 위원은 알고 있는데 회사 직원을 100%로 나눈다면 잘하는 회사직원 20% 그리고 좀 그냥 그럭저럭 하는 70%, 못하는 직원 10% 해서 이 10%를 감원시킨 거죠. 1990년대에. 그래서 그 추세가 앞다투어 초우량기업들이 막 따라서 했죠. 그게 아마 제가 알기로는 스택 랭킹이라 해서 다섯 가지로 분류가 된 것 같습니다. 그래서 앞다퉈 따라한 회사가 마이크로소프트사가 아마 그랬을 겁니다. 그래서 그 사람들도 A, B, C, D 등급으로 나눠서 D등급에 해당되는 사람들은 해고시키고 그런 추세로 된 것 같습니다. 그런데 이런 인사시스템이 2000년대에 들어와서 다 바꿔버렸죠. 어떻게 바꿨냐면 진짜 MS사가 경쟁을 할 사람이 구글인데도 불구하고 거기에 10%, 20%에 들기 위해서 내부경쟁을 하게 됩니다. 그러니까 협업이 전혀 없어지는 거죠. 다른 사람한테 주면 내가 할 수 없으니까 그런 현상이 일어나서 MS사에서는 그거 다 없애버리겠다. 그리고 너희들한테 커넥트 미팅을 하겠다. 그래서 어떻게 보면 협업을 하겠다고 했는데 그래서 MS사가 상당히 초우량기업으로 되고 잭 웰치도 그걸 포기했죠. 제너럴 일렉트릭사가 그래서 세계적인 기업이 됩니다. 그거에 반하는 건 야후사만 이번에도 600명 정도 해서 계속적으로 고집을 한 것 같아. E등급 나오는 사람들을 뽑아가지고 감원을 시켜버린 거죠. 그래서 잡지사에서도 그걸 많이 꼬집고 그랬는데 마이크로소프트사가 최악의 아이디어를 땅에 묻었는데 야후는 그것을 가지고 다시 받아들였다고 꼬집는 기사도 있습니다. 본 위원이 무슨 얘기를 하려고 그러는지 원장님은 감이 잡혔을 겁니다. 페이지 몇 페이지냐면 395페이지 본 위원이 이거에 대해 생각해서 이걸 질의를, 요구자료를 했습니다. 연구원들의 평가가 원장님, 어떤 방식으로 이루어지나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 연구위원회라고 있습니다. 연구위원회에서 평가위원회가 있거든요. 작업을 하면 연구원들이 설정한 여러 가지 심의위원들, 평가위원들이 1차적으로 하고요. 그게 굉장히 중요하죠. 거기서 객관적으로, 여러 심의위원들이 있기 때문에 거기서 하고 그다음에 경영진 평가가 또 있죠. 그런데 경영진 평가는 특별한 경우가 아니면 거의, 소위 저희들은 원자료라고 그러는데 평가위원회라든지 이런 데서 온 것을 그대로 비례적으로 하는 경우가 대부분이기 때문에 그래서 저희들은 될 수 있으면, 평가가 연구원들이 가장 민감하게 느끼는 부분들이기 때문에 될 수 있으면 공정하게 하려고 그런 평가위원회에서 그렇게 한 것을, 거기에서 받은 점수가 자기의 평가라고 생각하면 될 정도로 그렇게 하려고 하고 있습니다. 물론 예외적인 케이스는 부분적으로 있는데 예외적인 케이스라는 게 뭐냐 하면 이 친구는 굉장히 열심히 일을 했는데, 정말 열심히 일을 했는데 여러 가지 요인으로 평가를 제대로 못 받는 것 같다라는 어떤 뭐라 그럴까, 정성적인 그런 거는 간혹 가다가 있을 수가 있는데 대체적으로는 거의 90% 이상은 평가위원회에서 결정한 그 점수가 평가가 됩니다.
</p>
<p><b>○ 신현석 위원 </b> 원장님이 경험자다 보니까 아마 충분히 그것에 대해서는 고민을 많이 했을 겁니다. 우리 원장님께서도 지금 지적해 주셨지만 아까 협업이나 아니면 정량적인 것은 어떻게 평가가 될 수 있지만 정성적인 것은 평가하기가 좀 어렵잖아요. 그것에 대해서는 차제에 하고 좀 이따가 질문하고, 그러면 이 평가들의 방식은 알겠는데 절대평가입니까, 상대평가입니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 일단 평가는 절대적으로 하지만 결과론적으로 랭킹이 정해지죠. 그러니까 상대적 평가라고 볼 수가 있겠습니다, 결과론적으로 보면.
</p>
<p><b>○ 신현석 위원 </b> 잭 웰치가 했던 스택 랭킹, 그러니까 A, B, C, D로 평가를 한 거네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 신현석 위원 </b> 힘드실 것 같습니다. 제가 봐도, 저도 대학교수를 지금 하고 있는데……. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 힘듭니다.
</p>
<p><b>○ 신현석 위원 </b> 겸임교수를 하고 있는데 다 학생들에게 할 때 뭐냐면 이게 상대평가다 보니까 상당히 어려움이 많이 있더라고요. 그러면 원장님, 제가 이걸 보니까 성과급여도 나오더라고요. 성과급여를 어떻게 주고 있나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 저희들이 A, B+, B, C, D 이렇게 4등급으로 나누어서 0%부터 200%까지 이렇게 나누어서 주고 있습니다. 
</p>
<p><b>○ 신현석 위원 </b> 그러면 연구원들을 상대평가해서 성과급여를 주지 않는 경우도 있겠네요? 누가 잘 아시는 분 있으면 대답해 주세요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아닙니다. 괜찮습니다, 제가.
</p>
<p><b>○ 신현석 위원 </b> 그러면 다시 질의하겠는데요. 그럼 연구원들을 상대평가해서 성과급여를 주지 않는 경우도 있겠어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> D등급이 나오면 없습니다.
</p>
<p><b>○ 신현석 위원 </b> 안 주겠네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 신현석 위원 </b> 그러면 성과급여는 성과에 따른 보너스입니까, 아니면 보수의 개념입니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 보수.
</p>
<p><b>○ 신현석 위원 </b> 보수의 개념이라고요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 보수의 개념입니다.
</p>
<p><b>○ 신현석 위원 </b> 그러면 꼴찌 등급을 받는 사람들은 이 같은 등급을 받을 만큼의 일의 성과나 능력이 부족하다고 판단하십니까, 아니면 아까 말씀하신 정성적인 판단 부분을 지금 우리 경기개발연구원에서는 어떻게 하고 계시나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 정성적인 판단은 실장이 정성적인 부분을 또 하고 그다음에 경영진에서 정성적인 부분을 하고 있습니다. 
</p>
<p><b>○ 신현석 위원 </b> 그런데 그거는 후자 말씀하셨고 아까도 말씀드렸지만 등급을 받을 만큼의 일의 성과나 능력이 부족하다고 판단하는 거예요, D등급을 받으신 분이?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> D등급이 그 해, 그러니까 그 등, 그 반기, 그 반기에는 그런 평가를 받는 거죠.
</p>
<p><b>○ 신현석 위원 </b> 5~10%더라고요, 보니까 이 D등급에. 그런데 아까 제가 원장님께 앞의 서두에서도 장황하게 얘기했지만 1990년대에서는 아까 얘기했던 스택 랭킹 같은 게 추세였지만 아까도 협업이 중요하잖아요, 그렇죠? 저희도 상당히 협업이 중요하다고 생각하는데 너무 성과에 치우치다 보니까 지금 문제가 있어서 MS사는 부사장이 잭 웰치의 경영이념, MS하고는 틀리지만 MS사에서 그 보완을 하기 위해서 커넥트 미팅을 주선하고 협업을 강조한 거잖아요. 그러면 원장님께서 이런 D등급의 10%를 위해서 어떠한 노력을 하고 계시나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 D등급의 그 사람들, 그 양반들이, 그분들이 본인들이 알거든요. 그러니까 사실은 본인들이 C나, 그러니까 저희들이 이제 매번 해보니까 어떤 트렌드가 나타나느냐면, 패턴이 나타나는데 이분들이 다음에는 또 열심히 해서 연속 D를 맞는 경우가 거의 없더라고요. 그래서 다음에는 항상 등급이 올라가는 그런 경우가 생기기 때문에, 저는 그래서 처음에는 지금 위원님 말씀대로 어떻게 사람들을 A, B, C, D로 평가한다는 것이 과연 이게, 그리고 점수 차도 얼마 안 나요. 각 등급마다 종이 한 장 차이고. 이 종이 한 장 차이들을 가지고 이렇게 A, B, C, D로 나눠서 하는 것이 과연 합당한 것인가. 그러면 등급을 그냥 같이 해 가지고, 근데 어차피 우리가 성과연봉에 대한 포션이 있는 거고 그걸 나눠야 되기 때문에 그래서 여러 가지 고민을 많이 했는데 그래도 다행스럽게도 D등급 받는 분들이 다음 반기에는 올라가더라고요. B로도 올라가고 C, B, A까지 이렇게 올라가고. 그래서 저는 나름대로 이 평가시스템이 그래도 작동을 하고 있다 이렇게 생각을 하고 있습니다. 왜냐하면 계속 D등급 받는 분들이, 연구원들이 계속 D를 받는다고 그러면 이게 별 큰 인센티브가 안 되거든요. 그런데 거의 같은 걸 연속해서 하는 경우는 없더라고요, 더 올라가고. 그래서 저희들이 평가라는 것이 여러 사람들이 하는 거기 때문에 그래도 소위 평균의 법칙이 작용하더라고요. 그러니까 나름대로 100% 객관적이라고 할 수는 없겠지만 저희들이 항상 차선이라고 생각하거든요. 차선적인 방법으로서는 그래도 일관성을 유지하고 있는 게 아닌가 이렇게 생각이 들고요. 저도 이게 참 어려운 부분인데 연구원들이 가장 어떻게 보면 불만의 원천이 될 수도 있는 부분이 평가 부분들입니다. 연구원들이 굉장히 공부들을 잘한 친구들이고, 어렸을 때부터. 그래서 굉장히 학교 다닐 때마다, 제가 노상 하는 얘기지만 공부를 굉장히 잘한 친구들이기 때문에 C, D를 받은 경우는 거의 없었을 겁니다, 인생을 살아오면서. 그런데 이제 연구소 들어와 가지고 C도 받고 D도 받고 B도 받고, 보통 다 A급들만 받았을 텐데. 그래서 굉장히 본인들은 납득을 잘 못하는 경우가 있는데 그리고 이 연구라는 것은 본인들이 하면 본인들은 제일 잘했다고 생각을 하거든요. 자기가 최선을 다했다고 생각을 하는데 그게 이제 또 평가를 받게 되니까 그래서 그런 부분들이 있기 때문에 저도 그래서 이 평가 부분에 대해서는 가장 신경을 쓰는 부분 중의 하나고 어떻게 하면 최대한도로 사람들의 불만도 줄여가면서 그러면서 저희들이 평가시스템을 유지할 수 있는 방법이 뭔가 이렇게 하고 있는데 하여간 몇 년간의 트렌드를 보면 나름대로 작동을 하고 있는 게 아닌가. 저는 D를 누가 받았는지도 몰라요. 까먹습니다. 그런데 나중에 이렇게 보면, 그래서 D를 받는 그 사람을 특별하게 편견을 가지고 본다든지 그런 건 없는데 1년 후에 이렇게 보면 D를 받았던 분들이 다음에는 다 올라가 있더라고요. 일부러 올린 것도 아니고. 왜냐하면 저희들이 또 D를 연속 받으면 상당히 불이익이 있거든요. 그래서 인정이라는 게 작용하기 때문에 아무래도 그분들한테 다음에는 잘해 줄까 이런 생각도 드는데 그런 생각이 없는데도 불구하고, 그래서 저는 일부러 잊어버리거든요. 그런데 이렇게 보면 바뀌어 있고 바뀌어 있고 그렇더라고요. 그래서 ‘아, 이게 작동을 하고 있구나!’라고 저 개인적으로 생각을 하고 있습니다. 
</p>
<p><b>○ 신현석 위원 </b> 저도 이것 때문에 많이 고민하고 있어서, 아마 우리 원장님뿐만 아니라 CEO들은 대부분 이것에 대해서 상당히 많이 고민을 하고 있을 겁니다. 이게 동전의 앞뒷면이다 보니까, 그렇다고 해서 평가를 안 할 수도 없는 거고, 안 하자니 그렇고 그래서 이걸 어떻게 지혜롭게 관리를 해야 되냐라고 생각해야 될 부분이었기 때문에 말씀드린 거고요. 저도 이것에 대해서 고민을 많이 하고 있습니다. 그래서 제가 감명 깊게 읽었던 잭 웰치 그다음에 제너럴일렉트릭사를 보고 ‘아, 여기도 이렇게 돼 있구나!’ 그리고 원장님뿐만 아니라 많은 공공기관에 가면 제가 질문을 하곤 합니다. 그런데 저도 나름대로 공부는 해봤는데 제가 평가돼 가지고 D등급을 받았다고 생각해 보면 상당히 저도 당황스럽지 않았겠나 하는 생각이 듭니다. 그래서 원장님이 지금 섬세하게 잘, 섬세한 경영을 하고 계시는데 D를 받은 직원들의 마음도 헤아릴 수 있는, 제도적으로 아까 MS사가 커넥팅 미팅을 하든 그런 제도적으로 보완하시면, 연구원들을 잘 독려해서 하시면 좋지 않을까라고 생각하면서 질의를 마치도록 하겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 제가 계속 유의를 하겠습니다.
</p>
<p><b>○ 신현석 위원 </b> 고맙습니다. 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 신현석 위원님 수고하셨습니다. 다음에 권오진 위원님 질의하시기 바랍니다. 
</p>
<p><b>○ 권오진 위원 </b> 권오진 위원입니다. 아까 오전에 한 얘기 조금만 더 하고요 몇 가지만 질문하겠습니다. 원장님, 한번 여쭤볼게요. 어떤 집안에서 돈을 쓸 필요가 있는 곳이 거의 있거든요. 그런데 수입이 없다고 해 가지고서 그냥 안 쓸 수 있습니까? 쓸 건 써야죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 돈이 있으면, 구해 가지고 써야 되겠죠. 
</p>
<p><b>○ 권오진 위원 </b> 아까 아침에 제가 말씀드린 게 있어요. 때에 맞춰 쓸 돈이 있습니다. 아마 경기개발연구원에서도 사실 해야 할 사업들이 분명히 있습니다. 그걸 해 가지고서 나중에 돈을 갚을 수 있는데 도지사께서는 그냥 채권 발행은 무조건 후손에게 빚이다라는 명분 하나 가지고서 안 쓰고 있단 말입니다. 안 하고 있어요, 그냥. 이게 맞는 것인지 나는 진짜 모르겠어요. 제가 예결위원장이나 예결위원들 보고 그랬어요. 당신들을 뽑아준 건 그거 하라는 거다. 그 논리도 깨지 못하느냐, 도대체. 이게 현실입니다, 지금. 한 분의 그런 독선 때문에, 얼마나 후손을 생각하는지 모르겠지마는 이래 가지고 이렇게 돌아가는 거예요. 이런 부분 속에서 정말 참 안타까운 부분이 있거든요. 그런 부분에 대해서 한번 좀 생각해 주시기를 부탁드리고요, 제가 세 가지만 질문하겠습니다. 
</p>
<p style="padding-left:1.2em">  김문수 도지사님도 그랬고 싱크탱크라 그랬는데, 그래서 일자리가 복지다라는 얘기를 많이 하잖아요. 그런데 여기도 2013년도 연구목표에 보니까 경제 부분의 한 파트로 일자리와 생활의 안정이 공존하는 복지정책을 구현한다고 되어 있어요. 그런데 연구결과를 놓고 보니까 진짜 일자리를 갖다 복지를 위해서 하는 것인지 그런 부분이 부족한 것 같아요. 한번 재놓고 보니까. 저는 솔직히 말해서 일자리 부분을 놓고 볼 때에 일반적인 일자리도 중요하지만 경기도가 발전하려면 고급인력이 들어올 수 있는 여건이 되어야 된다고 전 보거든요. 그런데 여기 3년째 연구된 걸 보니까 그런 부분은 전혀 없어요. 경기도의 싱크탱크라고 한다면 싱크탱크를 모셔올 정도의 여건을 어떻게 해야 될 것인가 하는 게 중요한 과제라고 전 생각을 합니다. 
</p>
<p style="padding-left:1.2em">  제가 용인에 공장을 알아보기 위해서 조사해 봤더니 이런 용어가 있더라고요. “고급인력들이 양재벨트”라는 말이 있더라고요. 거기서는 안 나간대요, 그냥. 이런 부분 속에서 하게 되면 그럼 어떻게 할 것인가 하는 것을 갖다가 한번, 이런 것들은 큰 과제라고 생각을 합니다. 저는 사실 용인에 기흥에 있는 삼성단지가, 거기에 있는 인력들이 과연 평택 갈 것인가, 저는 솔직히 말해서 의문입니다. 그건 아마 삼성의 모험일 거예요. 그러니까 삼성이 100조 원 투자를 갖다가 말도 못 꺼내고, 그건 김문수 지사님이 만든 말이지만, 100조 원 투자라는 것이. 그것은 참 큰 과제일 거라고 생각합니다. 그러면 정말로 그런 부분에 대해서 한번 연구가 되어 가지고, 책을 보고 하는 게 아니라 현장을 연구해 가지고 경기도에 어떻게, 서울 양재벨트에 걸려 있는 그런 고급인력들을 어떻게 해줘야 경기도에 끌어올 것인가? 그래야지 기업이 살아날 수 있거든요. 그래야 일자리도 된다고 저는 보는 겁니다. 그런데 사실 여기서 보니까 사회적기업도 별로, 돈도 없는데 베이비부머 세대 있고, 세대 잇기, 명장 육성하고 이런 내용들만 일자리 사업으로 해서 연구된 것으로 나와 있습니다. 이러한 것들이 사실 정말로 이런 걸 할 때에 과연 내부인력만 가지고 이런 걸 검토해 가지고 과제로 선정된 그런 것인지, 여기 보니까 전부 다 이슈와 진단, GRI 정책제안, 연구과제이기 때문에 이건 내부 결정한 것이라고 저는 생각하기 때문에 이런 부분 속에서 이제는 앞으로 2014년, 다음 민선 6기를 생각하신다고 한다면 정말 그런 것들을 한번 검토할 필요가 있겠다. 안에서 중요한 것도 있지만 진짜로 이 시대에 경기도가 가야 될 싱크탱크로서 해줘야 될 과제는 무엇인가 하는 연구가 필요하다고 저는 생각을 해봅니다. 제가 그래서 아까 또 하나 과제, 두 번째 과제가 오총제 문제는 아까 윤희문 위원님께서 말씀하셨기 때문에 조금 피하겠습니다만 경기 동부권도 제가 도정질의나 5분발언을 통해서 크게 연구해 달라고 도지사한테 질의할 겁니다. 그 말씀을 드리고요.
</p>
<p style="padding-left:1.2em">  한 가지 마지막으로 시간이 됐기 때문에 부탁을 드리고 싶은 것은 사실 아까 말씀드렸듯이 산하기관이 우리가 26개가 있습니다. 그 26개 기관을 통해서 집행되어지는 게 상당히 돈도 많지만 그 기관에서 상당히 일을 많이 하고 있습니다. 그런데 평가 부분에서 상당히 문제를 갖고 있어요. 제가 1년 동안 본 게 그들의 평가서를 봤는데 평가서는 자기들이 계획서를 올립니다. 사업계획서가 평가목표입니다, 그대로. 진짜 이게 맞는 것인가? 지난번에 경기신용보증재단에서 법에는 15배 보증하게 돼 있고, 출연금의. 출연금이 800억 들어오는데 5,000억의 재원이 있어요. 그러면 보통 다른 데서는 8배, 10배 해줍니다. 기술기금 같은 데서. 그걸 갖다가 15배까지 법에 할 수 있는 것인데 5배를 해주고 나서 땡 치는 거예요. 그런데 그들이 맨날 우수입니다, 우수. 우수평가를 받는 거예요. 아마 개발원에서 그거 평가할 겁니다. 그런데 제가 안타까운 건 그런 겁니다. 그리고 300일밖에 일 안 했다 이거야, 좋다 이거죠. 그 주는 거 많이 받는지 뭘 해야 되는 것인데 하지 않고 그냥 배고파 죽겠다 그러는데 그게 있는 거예요. 그럼 평가를 꼴찌 받아야죠, 평가를. 맨날 우수예요. 그래서 제가 봤더니 자기들이 평가계획서 내는 거예요, 자기들이. 그걸 가지고 외부 박사들 모셔 가지고 평가하는 겁니다. 그러면 당연히 낸 거 똑같이 가지요. 계수는 1등 갑니다, 우수 갑니다. 단지 장애인 무슨 단체 이런 데는 맨날 꼴찌예요, 그 사람들은. 무슨 기관도 꼴찌고. 그래서 제가 부탁드리고 싶고 것은 딱 한 가지입니다. 경기개발연구원에서 26개 단체에 대해서 이 단체가 경기도에 어떻게 하면 기여할 것이다 하는 지표를 경발연에서 만들어야 된다고 보는 겁니다. 지표를. 이 단체, 신용보증재단은 어떻게 해야지 경기도에 기여한다. 10배를 보증해야지만 기여하는 것이다라고 평가가 나올 것 아닙니까, 그게. 도자재단, 어떻게 해야 된다 이런 얘기죠. 제가 도자재단 지난번에 방문해 가지고 이랬어요. 재단에서 그 옆에다가 보행길 만들고 하지 마시고, 그게 중요한 거 아닙니다. 도자재단은 도자업자들이 잘되게끔 하는 일을 하는 겁니다. 도자재단이 잘됐다고 도자가 잘되는 건 아니다. 그 도자에 관련되어 있는 기업체들이 신이 나서 일할 수 있게 만드는 것이 당신이 할 일이다 그랬어요. 그럼 예를 들어서 도자재단 몇 개가 활성화되었다. 이게 그들의 성과입니다. 이러한 것을 26개 하나하나 쪼개 가지고 정말로 어떻게 하는 것이 경기도에 도움이 된다, 너희들이. 하는 걸 딱 가지고 계시면서 이것에 대해서 너희들이 몇 % 달성했다라는 것이 그대로 평가되어야 됩니다. 이러한 것은 분명히 경기개발연구원에서 해야 될 일이고 할 수 있는 일입니다. 그것을 또 공문서 다 보내 가지고서 너희들이 뭐 할 수 있느냐 물어보지 마시고 거기의 고객들, 고객한테 물어봐 가지고 이 기관이 어떻게 하면 도움이 되겠습니까? 사회적기업 재단이 있잖아요. 물어보는 거예요, 사회적기업한테. 어떻게 하면 이들이 우리에게 도움이 되겠습니까 하는 걸 물어보시고 가서 상담하시고 해 가지고서 그걸 만들어 가지고 그걸 한번 언론에 딱 해보세요. 그럼 경발연이 진짜 필요한 데다, 우리 경기도에서, 하고 나올 겁니다. 이러한 것을 경발연에서 만들어주는 시스템이 되었으면 좋겠다 하는 생각을 좀 부탁드리겠습니다. 원장님, 답변 부탁합니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 다 옳으신 말씀이고요. 그래서 저희들이 연구할 때 참고를 많이 하겠습니다. 그리고 고급인력이 와야 되는 것 저는 100% 공감입니다. 사실 경기도가 어떻게 보면 서울의 문제점을 치유하기 위한 하나의 보조수단으로써 상당히 경기도가 활용되었던 것도 사실입니다, 지난 30년 동안에. 그래서 주택문제도 그렇고 여러 가지 문제에서 정말 경기도의 고급인력이라든지 양질의 주거문제나 주거환경도 대부분 100% 동감인데, 저희들이 그래서 이 경기도 문제는 아까 수도권, 서울하고 양재벨트 말씀하셨지만 우리나라 사람들이 아직도 서울을 좋아합니다. 이쪽의 대기업에 있는 사람들도, 여기 있는 사람들도, 수원에 대기업들 많지 않습니까? 유수의 대기업 사람들도 서울 가고 싶어 해요. 서울 가고 싶어 하고. 그래서 어떻게 하면 이 사람들을 유인할 수 있는가라는 건데 이것은 사실은 수도권 규제하고 굉장히 많이 작용을 합니다. 그래서 아까 모 대기업 말씀하셨는데 아산 탕정 같은 데도 크게 만들었는데 나름대로 성공을 하고 있거든요. 결국 이것은 큰 규제의 틀 안에서 경기도에서 끌어들일 수 있는, 경기도가 사실 외부사람을 끌어들일 수 있는 수단들이 별로 없어요. 세금을 깎아줄 수 있는 것도 아니고 오는 사람들에게 돈을 줄 수 있는 것도 아니고. 그래서 굉장히 말은 하기가 쉬운데 실제적으로 줄 수 있는 게 별로 없거든요. 그러니까 그런 수단을 많이 확보해야 되는데 그것이 결국에는 수도권 규제 쪽하고 또 연결이 돼서 그래서 그쪽으로 하면 상당히 앞으로 유리하겠다, 그래서 저희들도 고급인력을 끌어올 수 있는 다양한 정책대안을 마련하려고 노력하겠습니다. 그리고 또 일자리는 결국에는 기업들이 만들어내거든요. 기업들이 만들어내는 거고, 공공기관에서 만들어내는 일자리라는 것이 사실 좀 그렇지요. 다만 기업들이 일자리를 만들 수 있는 그러한 환경 같은 것을 어떻게 조성할 수 있는가 그런 연구를 계속 하도록 노력하겠습니다. 위원님 말씀 상당히 공감하고요.
</p>
<p style="padding-left:1.2em">  그리고 산하기관 평가문제인데요. 저희들도 산하기관을 평가하거든요. 저희들이 평가담당기관 중 하나인데 이 평가라는 게 그렇더라고요. 아까 제가 연구원들도 그랬지만 평가를 잘 받는 연구원이나 기관들은, 또 안 받는 기관들은 항상 여러 가지 이야기를 할 수 있겠더라고요. 그런데 특히 저희들 같은 경우 평가할 때 그 기관의 말만 직접 듣고서 하는 경우는 없습니다. 다른 사람들한테 물어보기도 하고, 다만 지금 위원님께서 말씀하신 굉장히 좋은 아이디어가 뭐냐 하면 각 기관마다의 핵심업무, 소위 말하는 핵심업무를 딱 설정해서 거기다 가중치를 많이 둬서, 그래서 거기다 좀 하는 것이 좋지 않겠는가라는 것은 굉장히 좋으신 말씀이어 가지고 제가 평가하는 데다가 이래라 저래라 할 수 있는 입장은 아니어 가지고, 왜냐하면 평가기술도 있기 때문에. 그래서 저도 얘기를 많이 듣거든요, 사람들한테. 그래서 각 기관장들 보면 평가 안 받은 사람들은 굉장히 화를 많이 냅니다. 어떻게 평가를 그런 식으로 하느냐, 잘하라고 하는데 또 상대적으로 잘 받은 사람은 별 말이 없어요. 잘했다 못했다. 그래서 그런 걸 많이 듣고 있기 때문에, 그래서 참 어렵다는 생각이 들지만 지금 말씀하신 어떤 각 기관의 고유업무에 대한, 핵심업무에 대한 것에 대해서는 가중치를 좀 더 둬서 그렇게 하자는 방법은 제가 평가 담당하는 연구원들하고 얘기를 해서 그래도 많은 사람들이 공감할 수 있는 그런 평가의 틀을 만들려고 노력을 해보도록 하겠습니다.
</p>
