<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 임병택 위원 </b> 직원 분들이 돌아가시면서 참 알기 쉽게, 제가 봐도 이해하기가 쉽네요. 제가 봐도, 보고서만 받으면, 집에서 받으면 저희가 보기에도 딱딱한데 기본적인 화두들을 이렇게 정리하셔 가지고 본문까지 연결시키는 이러한 부분은 참 잘하시는 것 같아서 직원분들 격려 좀 해주시길 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그리고 직제표를 한번 보겠습니다. 보면 실이 있고요, 센터가 사회ㆍ통일ㆍ의정 그다음에 전략연구센터 이렇게 나뉘어져 있습니다. 실과 센터의 차이가 뭐지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이건 참 제가 답변이 약간 궁색한데요. 실은 저희 연구소에 전통적으로 고유의 지속적으로 쭉 되는 거고 센터는 아무래도 시의성이 있는, 예를 들어서 사회경제센터도 그렇고 통일ㆍ동북아센터도 그렇고 의정연구센터도 그렇고 약간 플랙시블(flexible) 한 조직 개념으로 생각하시면 좋을 겁니다. 
</p>
<p><b>○ 임병택 위원 </b> 올해 신설된 조직이 사회경제센터하고 의정연구센터지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 임병택 위원 </b> 저희는 두 신설조직 모두에게 감사를 드리는 입장인데요. 의정연구센터는 워낙 도의회 의원님들이 기본적으로 목말라 하셨던 센터고 사회경제센터는 시대적 흐름에 맞춰서 잘하신 것 같습니다. 김희연 박사님이 센터장님이면서 보고서도 쓰시는 건가요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 임병택 위원 </b> 이번에 한국 노인의 사중고(四重苦) 원인과 대책이라는 보고서는 제가 아주 유익하게 잘 읽어서 감사함을 표해 드립니다. 이런 자료들이 저희들이 실질적으로 의정활동 하는 데도 정말 필요하고 각 정책집행 단위들에게도 31개 시군이나 아니면 경기도나 많은 분들에게 참 좋은 참고자료가 됐을 거라고 보여집니다. 그러면 전략연구센터도 센터잖아요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 임병택 위원 </b> 왜 원장님 직할로 빠져 있고 나머지 센터는 하단에 이렇게 배치되어 있는지, 무슨 특별한 의미가 있나요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 약간의 의미가 있습니다. 전략연구센터는 제 조직이라고 볼 수가 있지요. 그러니까 다른 조직들은 철저하게 자율적으로 하도록 하고 전략연구센터는 저한테 직접 보고도 하고 제가 몇 명 되지는 않지만 직접, 저희들이 또 중요한 그런 역할을 하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 오전에 동료 위원님들께서도 의정연구센터에 대한 필요성을 언급해 주신 위원님들이 다수셨는데요. 저 또한 거기에 동의를 하는 입장인데 다른 센터들 관련된 예산들은 다 확보를 하셨는데 의회와 관련된 의정연구센터 예산만 확보를 못하셨다는 이야기를 들었습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 확보를 못했다기보다도 다른 예산은 저희들의 보통예산이고 그리고 저희 의정연구센터는 작년에 추가적으로 예산이 확보되었던 건데 그런데 이번 같은 경우도 저희들의 의사를 적극적으로 얘기를 했는데 일단 나온 것은 하여간 결과론적으로 그렇게 지금 되어 있는 거죠.
</p>
<p><b>○ 임병택 위원 </b> 아예 독립기구화해 주시는 건 어떠십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네?
</p>
<p><b>○ 임병택 위원 </b> 아예 독립기구화.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 의정연구센터를요?
</p>
<p><b>○ 임병택 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희는 사실 장기적으로는 독립기구화 해야 된다고 생각을 합니다. 독립기구화 해서 의회의 직접 컨트롤하에서 직접 하는 것이 저는 가장 바람직하지 않은가. 다만 그러면서 저희 연구소하고도 밀접하게 협업도 하고 그러는데 의정연구센터는 사실 독립화되는 것이 저는 가장 적합하다고 생각을 합니다. 
</p>
<p><b>○ 임병택 위원 </b> 그런데 아직 집행부의 예산이 최종적으로 확정되지 않았는데 확보가 됐니 안 됐니 이런 말은 좀 성급하신 것 같으세요. 최종적으로 의회에 제출되는 시점까지는 지속적인 확보 노력을 하셔야 되고요. 의회에 제출되는 시점까지는 의정연구센터만 확보가 되지 않았다라는 이런 표현은 좀 지양하시는 게 좋을 것 같습니다. 직제표에도 보시면 분명히 경기개발연구원의 조직이고요. 잘못하면 오해를 받을 소지가 있습니다. 도의회와 연관성이 있는 곳이기 때문에 오히려 의도적으로 하지 않으려는 것 아니냐라는 의구심을 충분히 위원님들이 받으실 수가 있을 거라고 보여지거든요. 저는 성과에 따라서 필요성 여부를 재검토하는 것에 대해서는 찬성을 하지만 미리 먼저 벽을 치시면서 이렇게 접근하시는 태도는, 이 직제표에 보시다시피 이건 분명한 경기개발연구원 내의 조직이고 집행부ㆍ의회ㆍ경기연이 함께 정치적 결단을 통해서 만든 조직이기 때문에 하여튼 지속적으로 예산안이 최종 확정될 때까지는 원장님께서도 적극적인 관심을 가져주시기를 당부드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 임병택 위원님 수고하셨습니다. 우리 위원님들이 준비하신 추가질문은 전부 다 끝이 났습니다. 본질문과 추가질문 시간에 미처 준비하신 질문이 되지 않으신 위원님들 신청하시면 판단해서 기회를 드리도록 하겠습니다. 위원님들 중에 또 질의하실 위원님 계십니까? 
</p>
<p style="padding-left:1.2em">  우선 먼저 최재우 위원님부터 시작하시도록 하겠습니다. 
</p>
<p><b>○ 최재우 위원 </b> 최재우입니다. 2011년도 행정사무감사 처리요구사항 조치결과에 대해서 한 가지만 여쭤보려고 그럽니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 2011년도요?
</p>
<p><b>○ 최재우 위원 </b> 네. 이건 제가 그때 문의했던 건 아닌데 경기개발연구원 명칭에서 개발이라는 단어의 명칭 변경을 검토한 적이 있어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 있습니다. 
</p>
<p><b>○ 최재우 위원 </b> 있는데 거기 답변에는 추진 중이라고 돼 있는데 2003년이 어떻고 2004년이 어떻고 해 가지고 추진 중이라는데 누가 어느 부서에서 어떻게 추진되고 있는지에 대해 설명을 부탁드립니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 명칭?
</p>
<p><b>○ 최재우 위원 </b> 그렇습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 한번 검토를 쭉 했었고요. 그래서 저희들이 몇 가지 안도 있었습니다. 가장 저희들이 염두에 뒀던 것이 경기발전연구원이었거든요. 경기발전연구원이었는데 이게 정확하게 사단법인 이름으로 이미 등록이 돼 있더라고요. 그래서 그게 무산되고 나니까 여러 가지 정책연구원, 경기연구원 또 다양한 연구원 이름을 했었거든요. 했는데 간단하게 말씀드리면 경기정책연구원, 경기비전연구원, 경기정책전략연구원, 21경기발전연구원, 수도권정책연구원, 한국정책연구원, 경기연구원, 경기개발연구원 쭉 있는데 이게 참 저희들의 상상력의 한계인지는 모르겠습니다만 경기발전연구원, 경기21연구원, 하여튼 이렇게 선정도 했고 다양한 사람들한테 물어보기도 하고 그래서 가장 그래도 괜찮은 것들이 경기발전연구원하고, 저 개인적으로는. 경기연구원하고 이렇게 됐었는데 경기연구원 그러니까 너무 포괄적이어 가지고. 서울 연구원은 서울연구원이란 이름으로 개정도 했지만. 뭔가 그……. 저희 다양한 또 다른 기관도 있는데. 그래서 약간 그런 것도 있고 또 경기발전연구원은 아까도 말씀드린 것과 같이 가장 무난했는데 이미 재빨리, 몇 년 전에 설립했는지 모르겠는데, 경기발전연구원이. 그것도 경기발전연구원이 상당히 오래 전에 이미 사단법인으로 설립이 돼 있어 가지고. 그래서 우리의 아이덴티티를 살리려면 ‘경기’자는 들어가야 되고 말이 길어지면 또 그래서 저희가 지금 경기개발연구원이라고 두고 있는데. 그래서 저희는 어떻게 생각하느냐 하면 개발이라는 게 development인데 development가 반드시 토목 식으로 집 짓고 이러는 것이 아니라 포괄적으로 개념을 생각해서 시대 발전에 맞는 그런 복지연구도 개발이 될 수 있는 거고 복지 개발할 수 있는 것 아니겠습니까? 그래서 이걸 소위 토목 식으로만 생각하지 말자, 개발이라는 말을. 그래서 포괄적으로 생각을 하면 이 명칭 가지고도 충분히, 내용이 문제지. 그래서 그런 식으로 해 가지고 지금 홀딩 상태인데 상황은 그렇습니다. 그래서 저희들이 다양한, 2003년도, 2004년도에도 이 명칭 가지고 문제가 제기된 적이 있고 2011년에도 명칭 가지고 문제된 적이 있는데 그때마다 다양한 명칭을 가지고 이렇게 봤는데 딱 그렇게 눈에 띄고 이러는 것이, 그래서 그 이익이 현재 GRI라고 있는 것을 대체할 수 있는 그 정도의 이익이 되겠는가라는 생각이 들어 가지고 약간 주춤한 상태입니다. 그래서 좋은 명칭이 있으면 저희들이 언제라도 바꾸는데 이게 아까도 말씀드린 것과 같이 제가 다시 한 번 말씀드리면 저희가 적합한 나름대로 받은 게 경기정책연구원, 수도권정책연구원, 한국경제정책연구원, 또 경기메트로센터, 동북아정책연구원, 경기비전연구원, 21경기발전연구원, 한국정책전략연구원, 경기발전연구원, 경기21연구원, 경기정책전략연구원, 프로젝트KRI, 경기연구원, 경기개발연구원 이렇게 쭉 있는데 다른 것보다도 벌써 경기개발연구원, 경기발전연구원이 딱 눈에 띄거든요. 제일 무난하다. 또 아주 좋은 한글도 있을 수가 있고 고민을 좀 해 보겠습니다. 그런데…….
</p>
<p><b>○ 최재우 위원 </b> 어떻게 보면 ‘개발’이라는 그 두 자가 우리한테 와 닿는 거거든요. 민간 개발시대를 자꾸 떠올리는 것 같은데 하여튼 연구를 좀 더 해주시고요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 그래서 저희가 충분히 그 질문하신 취지는 이해하거든요. 개발 때문에 개발이라는 게 마치 속된 말로 쌍팔년도식 삽질이나 하고 말이죠. 이러는 것 아닌가, 그런 느낌이 든다. 제가 말이 좀 거칠어서 죄송합니다. 그런데 그런 느낌이 들어서 세련되게 좀 더 우리 경제수준과 사회발전 속도하고 맞춘 그런 이름이 돼야 되지 않겠는가라는 위원님의 지적에는 충분히 공감을 합니다. 그래서 저희가 좋은 게 있으면 언제든지 하겠습니다. 
</p>
<p><b>○ 최재우 위원 </b> 네, 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 최재우 위원님 수고하셨습니다. 다음에는 배수문 위원님 질의하여 주시기 바랍니다.
</p>
<p><b>○ 배수문 위원 </b> 한 가지만 질의하겠습니다. 위탁연구 대행에 대해서 다른 위원님들이 질의를 하신 것 같은데요. 혹여 위탁받은 연구를 중간에서 그냥 위탁받은 주체로의 이름만 빌려주고 또 재위탁하는 경우가 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지난번에도 한번 문제제기가 돼서요. 저희들이 위탁과제를 줄 때 참 어려운 부분인데 저희가 위탁을 줄 때는 재위탁주는 경우가 있습니다. 특히 기술용역 같은 경우에는 어차피 우리가 기술을 다 할 수가 없으니까 그런 건 위탁을 나가고요.
</p>
<p><b>○ 배수문 위원 </b> 자, 문제는요. 주체로서 하는 것까지 뭐라고 할 수는 없는데 금전적으로 위탁을 받고 또 재위탁을 주는 과정에서 하는 일에 비해 금전적으로 이득만 취하고 있는 것 아닌가라는 식의 시각도 있어서. 이것들에 대한 원장님의 생각은 어떠십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그러니까 저희가 이름이 있으니까 받아와서 재위탁 주고 중간에…….
</p>
<p><b>○ 배수문 위원 </b> 그렇죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 충분히 이해를 합니다. 
</p>
<p><b>○ 배수문 위원 </b> 그런데 그게 이름 가지고 했을 때 이득적으로, 물론 예산 때문에 자꾸만 이득을 챙기려고 하셨는지 모르겠지만. 뭐 그렇지는 않다고 보고요. 그럼에도 불구하고 그런 건이 한 건이라도 있다면 세간의 눈은 당연히 위탁받아서 또 거기는 하기야 하지만 “어, 원 위탁금액은 3,000만 원인데 나한테는 2,000만 원밖에 안 줘. 그럼 1,000만 원은 어디 간 거야.”라고 했을 때 결국은 행정적으로 처리하는 비용이 1,000만 원까지 될까라고 한다는 거죠. 이런 것들의 경우가 몇 번이나 있었죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그건 재위탁을 받은 사람들의 업체나 이런 쪽의 이야기일 수도 있고 그래서 저 개인적인 말씀을 먼저 드리겠습니다. 저는 재위탁주는 걸 개인적으로 굉장히 반대합니다. 그래서 연구원들한테 굉장히 많이 뭐라고 그러는데 그래서 일단 우리 연구원 이름으로 수탁을 받았으면 연구원이 해라. 왜 재위탁을 주느냐. 그래서 계속 제가 노래를 부르고 있는 중의 하나가, 굉장히 저는 개인적으로 싫어합니다. 
</p>
<p><b>○ 배수문 위원 </b> 그런데 저는 필요하다고 보는 것 중의 하나가 아까도 본 위원이 지적했던 것처럼 여기서 경기개발연구원을 통해서 좋은 연구물들이 발굴되는 건 되게 좋습니다, 거꾸로. 그건 개인이 하면 공인받지 못하지만 심사 같은 걸 통해서 논문지화 할 수 있다라고 보는 것과 같은 맥락에 일반적으로 개인이 위탁받기 쉽지 않지만 결국은 재위탁을 주는 과정에서 적절한 곳에, 정확하게 연구를 할 만한 곳에 줬다라는 것과 그 사이에 거래되는 금액까지 투명하고 적정성을 갖고 있다면 문제가 안 되는데 그 적정성 그리고 중간에서 그 역할을 하는 과정에서 발생되는 금액들이 적정했는가에 대한 것만 해소가 된다면 충분히 가능하다고 보거든요. 그러니까 지금 원장님 입장에서야 당연히 우리 연구원 박사님들의 연구능력을 믿으시니까 되도록 그렇게 하는 게 좋다라고 하지만 그럼에도 불구하고 아주 좋은 연구들이 경기개발연구원 이름으로 나가지 못해서 훨씬 더 사장되는 연구로 된다면 오히려 경기개발연구원 이름을 빌려서 그런 걸 더 드러내는 건 맞다고 보는 거거든요. 그러니까 그런 것에서 절차적으로 금전만 챙기는 원이 안 되는 상황을 어떻게 생각하시냐는 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 금전적으로만 챙기는 경우는 없고요, 일단. 그러니까 A라는 프로젝트를 따와서 여기서 그냥 손에, 쉽게 얘기하면 손에 코도 안 풀고 줘 가지고 하는 그런 경우는 없고요. 그걸 저희들이 재위탁이라고 그러는데 재위탁은 없고 부분위탁이 있습니다. 
</p>
<p><b>○ 배수문 위원 </b> 부분위탁요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 부분위탁만 있고 부분위탁의 여부라든지 규모 등은 연구위원회에서 같은 데서 충분히 저희들이 커버를 해서 지금 하고 있고요. 그래서 통째로 이렇게 갖다 맡기는 건 거의 없는 걸로…….
</p>
<p><b>○ 배수문 위원 </b> 어쨌든 재가공이 되고 퀄리티 있게 만드는 것들은 원의 큰 목적 달성에 가장 부합하는 행동이다라고 볼 수 있거든요. 그러니까 그걸 억제하고 누를 만한 문제는 아니라고 보여져요. 왜냐하면 개인이 아주 좋은 연구를 했는데도 불구하고 개인이 내는 건 전혀 공신력을 받지 못하지 않습니까? 그렇다면 경기도에서 가장 공신력 있게 모든 연구물들을 취급할 수 있는 거거든요. 특히 행정과 관련돼서는, 정책과 관련돼서는. 그렇다면 더 많이 활성화해야 된다고 보고 그런 것들을 더 공신력 있게 만드는. 그래서 제가 학술지 등재라든가 이런 것들을 다시 한 번 건의했던 거거든요. 그렇게 해주셨으면 좋겠다라는 말씀을 드립니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다. 그걸 제가 다시 한 번…….
</p>
<p><b>○ 배수문 위원 </b> 전체 매뉴얼을 한 번 더 살펴보시죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 부분위탁이나 재위탁 문제는 제가 계속 신경 쓰고 있는 부분 중의 하나기 때문에 그건 좀 더 투명하게 하도록 하겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 거기다 정책에 반영될 수 있는 건 더 적극적으로 반영할 수 있으면 좋죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 배수문 위원님 수고하셨습니다. 또 추가질의 하실 위원님 계시면 질의해 주시기 바랍니다. 안 계십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  경기개발연구원에 대한 행정사무감사가 오늘 이것으로 끝마치는 것이 아니고요. 저희가 마지막 날 종합감사가 또 한 번 있습니다. 종합감사를 활용해서 경기개발연구원에 대한 심도 있는 감사를 지속적으로 해주실 것을 부탁을 드리고요.
</p>
<p style="padding-left:1.2em">  오늘은 이상 마치고자 하는데 저는 두어 가지만 말씀드리도록 하겠습니다. 조금 전에 임병택 위원님께서 예산 관련한 말씀을 하셨습니다만 아직 분명한 것은 예산심의가 마무리되지 않았다라고 하는 거고요. 그럼에도 불구하고 전망컨대 경기도의 재정형편이 대체적으로 어려워서 상대적으로 올해에 비해서 좀 어렵지 않을까 이런 생각을 갖고 있습니다. 그것이 경기개발연구원의 재정형편에도 많은 영향을 끼칠 것 같다 이렇게 생각이 드는데. 그러나 그렇다고 해서 경기개발연구원의 어떤 위상과 또는 기능이 축소돼도 된다는 말은 아닐 것입니다. 저는 그런 측면에서 경기개발연구원이 우리 원장님 중심으로 해서 경기도의 그야말로 싱크탱크로서의 기능과 역할이 축소되지 않도록 하는 노력은 대단히 필요하다 이렇게 보여지고 그것이 연말 예산심의 과정에서 저희 위원들도 관심을 갖고 대응을 하겠습니다만 경기개발연구원 원장님을 비롯한 간부님들께서도 적극적으로 관심을 갖고 임해 주실 것을 부탁드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 또 하나는 오전에 도 산하 연구기관들에 대한 통폐합 또는 조정 문제에 대해서 존경하는 배수문 위원님께서 잠시 언급이 있었습니다만 저는 제가 개인적으로 경기도의회 의원 3년 6개월 동안 진행을 하면서 지사가 누구냐와 관계없이 지금 현재 경기도 산하 연구원에 대한 통폐합 작업, 기능을 조정하는 작업은 반드시 필요하다는 생각을 갖고 있습니다. 그래서 그런 부분에 대해서 저는 경기개발연구원이 연구가 가능하면 한번 가능한 방안을 강구해 봤으면 좋겠다 이런 생각을 갖습니다.
</p>
<p style="padding-left:1.2em">  더불어서 산하기관에 대한 통폐합 문제 이것 역시도 경기개발연구원에서 내년 6월이면 새롭게 어떤 분이 오실지는 모르겠지만 지사가 바뀌고 의회도 바뀌면서 새로운 민선체제가 시작이 되는데 저는 전후로 해서, 그 전후시기를 놓치게 되면 산하기관에 대한 통폐합 문제, 조정 문제는 또 4년 그냥 지나간다 이런 생각을 갖고 있기 때문에 저는 연구원에서 그 부분에 대한 이를테면 데이터베이스를 미리 준비하시고 의회나 또는 집행부 차원의 어떤 요구가 있게 되면 곧바로 연구가 진행돼서 빠른 속도로 빠른 시일 내에 안이 제시되어질 수 있는 그런 방안들에 대해서 준비를 해주셨으면 좋겠다는 말씀을 드립니다. 그렇게 해주실 수 있나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 위원장 김현삼 </b> 더 이상 질의하실 위원님이 안 계시므로 오늘 경기개발연구원에 대한 질의와 답변을 모두 마치도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 홍순영 경기개발연구원 원장을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료 준비와 위원님들의 질의에 성의껏 답변해 주신 경기개발연구원 원장을 비롯한 임직원 여러분께 감사드립니다.
</p>
<p style="padding-left:1.2em">  그러면 이상으로서 오늘 경기개발연구원 소관 사항에 대한 2013년 행정사무감사를 모두 마치겠습니다. 산회를 선포합니다.
</p>
<p class=''ar''>(15시12분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(9명)
</b></p>
<p class=''aMan''>김현삼배수문김광철권오진신종철신현석윤희문임병택최재우</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   입법전문위원 조남
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p><p class=''em15''>경기개발연구원장 홍순영부원장 김대호</p>
<p><p class=''em15''>기획조정본부장 강철구사무처장 김경희</p>
<p><p class=''em15''>전략연구센터장 이정훈미래비전연구실장 이상대</p>
<p><p class=''em15''>자치경영연구실장 박충훈도시ㆍ주택연구실장 이성룡</p>
<p><p class=''em15''>창조경제연구실장 문미성교통연구실장 류시균</p>
<p><p class=''em15''>환경연구실장 김동영사회경제센터장 김희연</p>
<p><p class=''em15''>통일ㆍ동북아센터장 김동성의정연구센터장 신원득</p>
