<h4>기획위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2012년 11월 9일(금)
</p>
<p>장  소 : 경기개발연구원 회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시16분 감사개시)
</p>
<p><b>○ 위원장 김현삼 </b> 좌석을 정돈해 주시기 바랍니다. 성원이 되었으므로 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기개발연구원에 대한 2012년도 행정사무감사를 시작하겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 경기도의회 기획위원회 감사위원장 김현삼 위원입니다. 오늘은 우리 위원회 감사일정에 따라서 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 
</p>
<p style="padding-left:1.2em">  여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악해서 의정활동에 반영하고 2013년도 예산안 심사 자료 및 도정의 현실을 파악하여 도민의 삶의 질 향상에 기여하고자 함이 목적이므로 매우 중요한 의미가 있다고 하겠습니다. 따라서 오늘은 경기도의 싱크탱크인 경기개발연구원의 운영 실태를 감사하는 것이니만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러서 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주실 것을 당부드립니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기에 앞서서 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 실장, 부장, 센터장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 됩니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2012년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조의 규정에 의하여 고발될 수 있습니다. 또한  증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 피감사기관의 증인께서는 모두 일어나셔서 서주시기 바랍니다. 경기개발연구원 원장 나왔습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 부원장 나왔습니까? 
</p>
<p><b>○ 부원장 김대호 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 기획조정실장 나왔습니까? 
</p>
<p><b>○ 기획조정실장 강철구 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 사무처장 나왔습니까?
</p>
<p><b>○ 사무처장 이재동 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 전략연구센터장 나왔습니까? 
</p>
<p><b>○ 전략연구센터장 김은경 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 미래연구부장 나왔습니까? 
</p>
<p><b>○ 미래비전연구부장 이상대 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 자치의정연구부장 나왔습니까? 
</p>
<p><b>○ 자치의정연구부장 김동성 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 도시ㆍ주택연구부장 나왔습니까?
</p>
<p><b>○ 도시ㆍ주택연구부장 이성룡 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 창조경제연구부장 나왔습니까?
</p>
<p><b>○ 창조경제연구부장 이정훈 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 교통연구부장 나왔습니까? 
</p>
<p><b>○ 교통연구부장 류시균 </b> 네.
</p>
<p><b>○ 위원장 김현삼 </b> 환경연구부장 나왔습니까? 
</p>
<p><b>○ 환경연구부장 김동영 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 통일동북아센터장 나왔습니까?
</p>
<p><b>○ 통일동북아센터장 최용환 </b> 네. 
</p>
<p><b>○ 위원장 김현삼 </b> 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인들을 대표해서 경기개발연구원 원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에 서서 오른손만 들어주시기 바랍니다. 그러면 선서를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관업무에 대한 2012년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2012년 11월 9일 원장 홍순영. 
</p>
<p><b>○ 위원장 김현삼 </b> 모두 자리에 앉아주시기 바랍니다. 그러면 경기개발연구원 원장 나오셔서 간부 소개와 업무보고를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 안녕하십니까? 경기개발연구원장 홍순영입니다. 지난 9월 11일 업무보고에 이어 오늘 경기도의회 기획위원회 행정사무감사에 존경하는 김현삼 위원장님과 위원님들을 모시고 저희 연구원의 주요업무보고를 드리게 되어 감사의 말씀을 드립니다. 우리 연구원은 동북아 미래를 선도하는 경기도의 싱크탱크로서 경기도민의 삶의 질 향상을 위해 경기도정 현안을 해결하고 경기도 미래비전을 제시하는 등 임직원 모두가 열정을 다해 정책개발을 추진해 가고 있습니다. 향후에도 연구원의 발전을 위하여 기획위원회 위원님들의 많은 관심과 성원을 부탁드립니다.
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 연구원의 주요간부를 소개해 드리겠습니다. 먼저 김대호 부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  강철구 기획조정실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이재동 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김은경 전략연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 미래비전연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 자치의정연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이성룡 도시ㆍ주택연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정훈 창조경제연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  류시균 교통연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동영 환경연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  최용환 통일동북아센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 연구원의 주요업무를 보고드리겠습니다. 배부해 드린 보고자료의 목차를 봐주시기 바랍니다. 보고 순서는 일반 및 재정운영 현황, 2012년 주요실적 그리고 2013년 주요 연구사업계획 순입니다. 
</p>
<p style="padding-left:1.2em">  먼저 일반 및 재정운영 현황입니다. 일반현황, 재정운영 현황 순으로 보고드리겠습니다. 3쪽의 일반현황에 대해 간략히 보고드리겠습니다. 저희 연구원은 1995년에 개원하여 경기도의 중장기 비전 제시와 정책개발 기능을 수행하고 있습니다. 부서별 주요기능은 두 달 전 업무보고 때와 동일한데 보고자료를 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 4쪽의 기구 및 인력에 대해 보고드리겠습니다. 우리 연구원은 현재 1실 1처 6부 2센터 2과 7팀의 조직으로 구성되어 있습니다. 연구기능 조직은 전략연구센터, 미래비전연구부, 자치의정연구부, 도시ㆍ주택연구부, 창조경제연구부, 교통연구부, 환경연구부 그리고 통일동북아센터가 있습니다. 그리고 우리 원의 인력은 원장 1명, 부원장 1명, 연구직 52명, 관리ㆍ정보ㆍ기능직 23명 등 77명의 정규직원과  계약직원 등 총 173명이 근무하고 있습니다. 참고로 10월 1일부로 포스코경영연구소 출신 경제학 박사 1명을 신규 채용한 바 있습니다. 다음은 재정운영 현황에 대해 보고드리겠습니다. 올해의 총 예산규모는 205억 원으로 일반회계 150억 원, 수탁용역사업 특별회계 55억 원입니다. 일반회계의 수입ㆍ지출 내역을 구체적으로 말씀드리겠습니다. 수입항목은 경기도의 출연금이 전체의 60%인 90억 원으로 가장 많습니다. 지출항목으로는 인건비가 49%인 74억 원으로 가장 많으며 연구사업비가 56억 원으로 전체의 37% 정도 차지하고 있습니다. 9월 업무보고 시 위원님들께서 지적하신 바와 같이 저희 연구원은 수탁과제 전출금 증액, 시장가격에 맞는 용역사업 수주 등 자체 수입 확대를 위해 부단히 노력해가고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 6쪽 기금입니다. 연구원의 기금은 총 230억 원으로 모두 안전한 금융기관에 예치하고 있습니다. 이 중 일부가 8월 말 만기가 도래하여 정기예금으로 재예치한 사항 이외에는 지난 9월 업무보고 시 보고드린 사항과 동일합니다. 특히 지난 9월 보고 시에도 잠시 언급된 바 있지만 우리 원은 도 산하 공공기관으로서 위험한 투자는 가능한 지양하고 있으며 안전성과 수익성을 함께 고려한 금융상품에 기금을 운용하고 있다는 것을 알려드립니다. 그 밖에 출연기관 및 예치기관별 현황은 보고자료를 참조하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 2012년도 주요실적에 대해 보고드리겠습니다. 보고자료 9쪽부터 22쪽이 되겠습니다. 먼저 9쪽의 2012년 연구사업 목표에 대해 보고드리겠습니다. 우리 연구원은 동북아 미래를 선도하는 경기도의 싱크탱크라는 비전을 달성하기 위해 2012년 연구사업 목표를 사회ㆍ경제 패러다임 변화에 대한 정책 대응, 현장밀착형 복지ㆍ교통 및 사회환경 시스템 구상, 지속가능 발전을 위한 스마트 경기도 구상 이렇게 세 가지로 설정하였습니다. 그리고 이를 달성하기 위해 7개의 중점연구와 3개의 추진전략을 설정한 바 있습니다. 
</p>
<p style="padding-left:1.2em">  다음은 10쪽 2012년 주요실적에 대해 보고드리겠습니다. 2012년의 주요성과는 크게 도 현안에 대한 선제적 대응, 경기도 중장기 비전 수립, 대내외 소통 강화, 고객만족 향상 이렇게 네 가지로 구분할 수 있으며 지난 9월 기획위원님들께 보고드린 사항 외에 새롭게 추가된 사항을 중심으로 보고드리겠습니다. 먼저 도 현안에 대한 선제적 대응입니다. 첫 번째, 반환공여지 불평등 지원정책 전환을 위한 정책수립 연구입니다. 이는 경기도 반환공여지에 대한 국가지원을 이끌어내기 위한 정책수립연구로 지난 9월에 보고드린 바 있습니다. 이러한 연구결과를 토대로 경기북부 미군 반환공여지에 대해 용산공원에 상응하는 지원대책을 경기북부청을 통해 중앙정부에 요구한 바 있습니다.
</p>
<p style="padding-left:1.2em">  11쪽입니다. 두 번째는 경기도 협동조합의 활성화 방안입니다. 위원님들께서도 잘 아시듯이 오는 12월 협동조합기본법이 시행되면 경기도에서도 협동조합 활성화를 위한 각종 정책이 봇물을 이룰 것으로 예상됩니다. 협동조합은 일자리 창출과 복지증진 등 오늘날 새로운 경제사회 발전의 대안 모델로 각광받고 있습니다. 스위스의 생필품 유통회사 미그로, 미국의 썬키스트 등도 모두 협동조합 형태를 띠고 있습니다. 세 번째는 구도심 주민불편사항 실태 및 해소대책입니다. 구도심지역 주민불편사항 중 시급한 현안을 조사하여 26건의 주민요구사항을 도출하고 사회복지프로그램 확충 등의 해소대책을 제시하였습니다. 
</p>
<p style="padding-left:1.2em">  12쪽입니다. 네 번째로 경기북부의 도로, 교통, 주택 낙후실태 및 개선방안입니다. 지난 9월 업무보고 시 존경하는 김광철 간사님께서 깊은 관심을 보이신 경기북부에 대한 연구로서 수도권정비계획법과 군사시설보호구역으로 중첩 규제를 받고 있는 경기북부지역 개발의 어려움을 해소하기 위한 연구입니다. 향후에도 경기북부지역 낙후실태를 알리고 발전방안을 모색하는 연구활동을 지속 수행해 나가겠습니다. 다섯 번째로 취득세 세율인하에 대응한 제도개편 연구입니다. 이도 역시 지난 9월 존경하는 배수문 위원님께서 취득세 감면에 따른 지방행정의 어려움에 대해 말씀하신 바 있습니다. 이에 우리 원은 정책연구를 착수하였으며 금년 말까지 종료할 예정입니다.
</p>
<p>앞서 보고드린 사항 외에도 파주출판도시 활성화 방안, 보금자리지구 내 학교용지 확보 등 다양한 주요 도정현안 연구를 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 13쪽으로 2012년 주요실적 중 중장기 비전연구에 대해 보고드리겠습니다. 먼저 국가발전 전략과제 기본구상 연구입니다. 본 연구는 12월 대선 등 국내외 정책환경이 급변하는 상황에서 국가 및 경기도의 주요정책 아이디어, 중앙정부, 수도권, 경기도 차원의 정책 실행계획을 경기도의 관점에서 연구하였습니다. 그 결과 5대 목표, 18대 전략, 100대 정책과제를 선정하고 4월 총선, 대선후보, 정당 등에 정책 세일즈를 추진하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 14쪽 및 15쪽입니다. 14쪽의 공생발전을 위한 수도권ㆍ지방 간에 상생발전 전략, 법정 도종합계획인 2020 경기도 종합발전계획 수립, 15쪽의 향후 20년 수도권의 전망과 메가트렌드를 제시한 수도권 메가트렌드 2030과 한국적 복지모델 개발은 지난 9월 업무보고 시 보고드린 사항으로 생략하겠습니다.
</p>
<p style="padding-left:1.2em">  다음으로 16쪽 5대 서비스산업의 경기도 신성장동력화 방안입니다. 본 연구에서는 
</p>
<p>의료서비스, 문화콘텐츠, 관광ㆍ레저, 사회서비스, 비즈니스서비스 등 5대 서비스 산업발전을 위한 전략과 실천계획을 수립하였습니다. 다음 생활형 복지정책 연구입니다. 본 연구는 주거ㆍ교통ㆍ교육ㆍ문화ㆍ환경 등 부문별 계획지표를 설정하고 이를 달성하기 위한 생활형 복지정책을 지역 차원에서 제안한 것입니다. 그리고 DMZ 접경지역의 비전과 발전전략과 17쪽의 경기도 해양수산 중장기 발전방안 연구, 경기도 농어업ㆍ농어촌 중장기 발전방안 연구는 기이 보고사항으로 생략하겠습니다. 참고로 DMZ, 생활형 복지, 수도권ㆍ지방 상생, 2030 등 비전연구 결과를 토대로 내년 초 시의성을 감안하여 대규모 심포지엄을 개최할 계획으로 있습니다. 그 밖에 지난 9월 존경하는 안병원 위원님께서 관심을 가져주신 무등록공장 지원방안에 대해서는 현재 마무리 연구 중에 있는데 11월 중 최종보고서가 나오면 제공해 드리도록 하겠습니다. 그리고 존경하는 배수문 위원님께서 사후연구 필요성을 제기하셨는데 우리 원에서는 올해 초 완료된 연구에 대해서 정책 반영성과 사례집을 발간한 바 있으며 연구과제별로 정책반영조사를 실시하고 있습니다. 향후 연구관리시스템 개선 등을 검토 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 18쪽 대내외 소통 강화에 대해 보고드리겠습니다. 우리 원은 연구활동의 소통ㆍ공유ㆍ연계ㆍ참여를 활성화하기 위해 노력해오고 있습니다. 먼저 경기도 및 시군과의 소통입니다. 매주 월요일 점심시간 현안주제에 대해 경기도와 연구원 간 정책토론을 벌이는 GG공을 브라운백 미팅 형식으로 진행하고 있습니다. 또한 시군 순회토론회 개최, 시군 현안연구 수행 등 현장에 기반한 실효성 있는 정책 발굴에 적극 노력하고 있습니다. 그 외에도 존경하는 신현석 위원님께서 강조하신 현장의 목소리에 더더욱 귀를 기울이고자 권역별 시군 간담회를 추진하고 있습니다. 보다 자세한 시군 현안 연구사례는 19쪽을 참고하여 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 20쪽 의회 및 전문가와의 소통입니다. 우리 원은 기획위 정책교류 토론회,  의정포럼을 개최하는 등 경기도의회 및 전문가와의 적극적인 교류를 추진하고 있습니다. 그리고 존경하는 김현삼 위원장님과 임병택 위원님께서 지난 안면도 토론회에서 제안하신 GRIㆍ도의회 정책교류 토론회를 계획 중에 있습니다. 다음은 SNS를 활용한 경기도민과 GRI 간의 소통입니다. 우리 원은 트위터, 페이스북, 블로그 등     다양한 방법으로 SNS를 적극적으로 활용하고 있으며 4GWP, 강한 GRI만들기 등 조직문화 개선에도 진력하고 있습니다. 또한 존경하는 임병택 위원님께서 도의원과의 SNS 교류 확대를 제안하신바 9월 중순 연구원 페이스북 계정을 경기도의회 의원 70여분께 널리 알려 드리고 팬이 되어 주실 것을 요청드렸습니다. 향후에도 연구원의 소식에 많은 관심 부탁드립니다.
</p>
<p style="padding-left:1.2em">  다음은 21쪽 언론ㆍ여론 선도입니다. 우리 원은 매주 이슈&진단을 발간하여 경기도의 주요현안에 대해 쟁점과 대안을 제시하고 경기도 정책에 대한 공감대 형성을 유도하기 위해 적극적으로 노력하고 있습니다. 특히 환경복지, 물산업 아이디어 제공은 경기도에 큰 반향을 일으켰는데 해당 실국에서 시책사업으로 채택하였습니다. 또한 경기도 현안해결을 위해 시군 현장과 밀착한 정책세미나를 개최하여 여론선도에 힘쓰고 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 22쪽 고객만족 향상입니다. 우리 원은 현안 대응, 비전 제시, 현안세미나 개최, 도정 자문 등 다양한 방법으로 고객만족을 실천하고 있습니다. 자세한 내용은 제시된 자료를 참고하여 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음은 2013년 주요연구사업 계획에 대해 보고드리겠습니다. 보고자료 25쪽부터 36쪽이 되겠습니다. 먼저 25쪽의 2013년 연구사업 목표에 대해 보고드리겠습니다.저희 연구원은 GRI의 비전과 3대 미션의 성공적 추진을 위하여 2013년 연구사업목표를 새정부 출범과 대중앙정부 정책개발 강화, 민선5기 후반기 경기도의 정책대응방안 제시, 현장밀착형 정책개발로 설정하였습니다. 그리고 이를 달성하기 위하여 23개 중점사업 방향을 설정하여 연구사업을 추진할 계획입니다. 보다 자세한 내용은 28쪽 주요사업계획에서 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 26쪽 연구사업 추진전략에 대해 보고드리겠습니다. 우리 원은 2013년 연구사업 목표달성 및 8대 분야 23개 중점사업을 원활하게 수행하기 위하여 혁신적 변화를 주도하는 창의적 연구, 4GWP 실현과 조직의 역량을 극대화하는 협업 연구,수요자 중심의 결과를 유도하는 현안대응형 밀착형 연구를 3대 추진전략으로 설정하여 연구사업을 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음 27쪽 연구사업 추진체계입니다. 연구사업 추진체계는 내년도에도 올해와 동일하게 연구과제사업을 중심으로 연구부대사업, 연구지원사업 및 연구기반사업으로 구분하여 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 28쪽의 2013년 주요 연구사업계획에 대해 보고드리겠습니다. 2013년에는
</p>
<p>서울-경기만권 발전 비전과 전략구상, 고발전 저성장기에 대응한 지역경제 및 공간개발 전략구상, 지방 3정 법령 모니터링 및 제도 분석 등 경기도의 주요 어젠다에 대해 중장기 비전 전략과제로 추진할 계획입니다. 제시된 전략과제는 부서간담회, 도 실국간담회 및 GRI 경영전략회의를 통해 검토된 바 있으며 11월 말 이사회를 거쳐 최종적으로 확정할 계획입니다. 첫 번째로 전략연구센터에서는 경기도정 및 도정 관련 국내외 이슈를 발굴하고 분석하여 정책방향을 제시하겠습니다. 그리고 새정부 출범에 따른 경기도 현안 해결을 위해 선제적으로 대응하고자 합니다. 이를 위하여 현안분석보고서 세분화, 협업 등 업무 효율성, 신속성 및 현안보고서 품질 제고에 노력을 기울일 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 미래비전 분야입니다. 미래비전 분야는 고발전 저성장기에 대응한 지역경제 및 공간 개발전략 제시, 초광역 경제권으로서 수도권의 발전 비전 연구 추진, 안전 사회 행복 경기를 위한 추진 전략 제시 등을 중점적으로 추진하고자 합니다. 이를 위해 2013년도에 추진할 과제는 표를 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 31쪽 행정ㆍ의정 분야에 대해 보고드리겠습니다. 행정ㆍ의정 분야에서는 미래형 지방분권의 방향 제시, 도정 주요사업의 분석ㆍ평가 및 개선방안 제시, 경기도 지방 3정 발전방안 강구, 경기도 공공서비스의 효율성 제고와 전달체계 강화 등을 중점적으로 연구하고자 합니다. 이와 관련된 연구과제는 표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  32쪽입니다. 도시ㆍ주택 분야에서는 저성장 시대의 지역ㆍ도시 관리, 양적 안정화 시기의 지자체 주택정책 확립, 주거환경 개선과 도심 활성화 등의 도시재생, 낙후지역 발전 전략 및 기후변화 대응방안 등에 대해 초점을 맞추고 있습니다. 특히 지난 9월 존경하는 안병원, 권오진 위원님께서 독거노인 및 주거복지 관련 질의를 하셨는데 우리 원은 금년 독거노인 농촌빈집활용방안 연구를 수행한 바 있으며 내년에도 후속 연구로 유휴시설을 활용한 낙후지역의 사회적 경제 활성화 방안을 추진할 계획입니다. 또한 존경하는 신종철 위원님께서 부천시를 사례로 뉴타운 이후 구 도시 개발자료 연구를 요청하신 바 있습니다. 이에 우리 연구원은 부천지역을 포함하여 경기도 뉴타운 출구전략을 다각도로 연구하기 위해 뉴타운 구조조정에 따른 도시재생전략을 수행할 예정입니다. 참고로 지난 업무보고 시 존경하는 김현삼 위원장님께서 뉴타운 관련 보고서의 대외별 처리문제를 지적하고 해당보고서를 제출하도록 말씀하신 바 기획위원님들과 김종석 의원님께 바로 제출하였으며 연구원 홈페이지에도 즉시 공개했음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  다음은 33쪽 창조경제 분야에 대해 보고드리겠습니다. 창조경제 분야에서는 경기침체에 대응한 서민경제의 안정과 선진화, 고급 서비스산업 거점 구축, 국내외 기업투자유치 활성화, 일자리와 생활의 안정, 사회적 금융과 관련한 새로운 복지시스템 등에 대해 연구를 계획하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 34쪽 교통정책 분야에 대해 보고드리겠습니다. 교통정책 분야에 있어서는 수도권 광역교통망 확충, 복지교통 기반 구축 및 안전한 교통환경 조성, 광역철도사업비 분담구조 개선 등 교통 분야 현안 내용을 중심으로 연구를 추진할 계획입니다. 이와 관련된 연구과제는 표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 35쪽 환경정책 분야에 대해 보고드리겠습니다. 환경정책 분야에 있어서는 생활밀착형 환경복지 구현, 건강위해성 관리 강화, 안전하고 건강한 환경복원 등 관련 연구를 중점적으로 수행하고자 합니다. 이를 위해 표에 있는 바와 같이 녹색경제로의 이행을 위한 경기도 10대 전략, 자원순환도시 구축 방안 등의 연구를 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  마지막으로 36쪽 통일ㆍ동북아 문제에 대해 보고드리겠습니다. 2013년 통일ㆍ동북아 문제는 경기도의 남북협력, 통일정책사업 체계 구축 및 북한변화 대비, 경기도 국제교류협력의 다양화ㆍ다변화 추진, 지자체 제기 대군 지역현안의 해소 지원 등을 중점으로 연구를 추진할 계획입니다. 이를 위해 동아시아 국제환경 변화에 따른 한중협력 증진 및 갈등해소 방안 연구 등을 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 37쪽 2013년도 연구사업계획 총괄에 대해 보고드리겠습니다. 2013년도에는 연구과제사업으로 기본연구과제 17개, 정책연구과제 90개, 정책현안분석 150개, 수탁연구과제 48개 그리고 협약연구과제 5개 등 총 310개의 과제를 계획하고 있으며 11월 말 이사회에서 2013년 연구사업계획을 최종 확정할 예정입니다. 연구부대사업, 연구지원사업 그리고 연구기반사업의 내용은 도표를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 41쪽 2012년 연구과제 목록과 51쪽 2011년 행정사무감사 처리요구사항 조치결과는 허락해 주신다면 자료로 대신하겠습니다. 이상으로 연구원의 주요업무를 모두 마치겠습니다. 경청해 주셔서 대단히 감사합니다.
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 김현삼 </b> 원장님 수고하셨습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위해서 질의는 일문일답으로 하되 질의시간을 제한하도록 하겠습니다. 우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 일단 5분을 드리도록 하겠습니다.
</p>
<p><b>○ 임병택 위원 </b> 위원장님, 질문시작 전에 자료 하나만 좀 요청하고 시작하겠습니다.
</p>
<p><b>○ 위원장 김현삼 </b> 제가 좀 이따가 발언기회 드리도록 하겠습니다. 그리고 5분의 추가질문이 끝나면 감사 진행상황과 시간 등 제반여건을 감안해서 추가질문을 계속할지 여부를 결정하도록 하겠습니다. 원활한 감사 진행을 위해 부득이 시간제한을 두게 된 점 널리 양해해 주시면 고맙겠습니다.
</p>
<p style="padding-left:1.2em">  오늘 질문 순서를 말씀드리겠습니다. 오늘 질문 순서는 김광철 위원님, 최재우 위원님, 임병택 위원님, 안병원 위원님, 배수문 위원님, 권오진 위원님, 신종철 위원님, 오완석 위원님 순서로 진행하도록 하겠습니다. 아울러 질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리면 위원님들의 질의에 대하여 원장의 답변이 어려울 경우 업무담당부장 및 센터장 등 실무자가 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나오셔서 소속과 직, 성명을 분명히 밝히고 대답을 해주시기 바랍니다. 그러면 질문에 앞서서 임병택 위원님으로부터 의사진행발언이 있었습니다. 말씀해 주시기 바랍니다.
</p>
<p><b>○ 임병택 위원 </b> 초빙연구원 관련된 규정이 있잖아요? 제가 어제 부탁드렸는데 풀버전, 이건 받았네요. 그러면 우리 기획조정실장님, 초빙연구원 현재 몇 명 정도 있으시죠?
</p>
<p><b>○ 기획조정실장 강철구 </b> 현재 20명 있습니다.
</p>
<p><b>○ 임병택 위원 </b> 그렇죠? 그 전엔 10여 명 있다라고 말씀하셨던 것 같은데 20명 관련 현재 재직 중이신 분들 명단 좀 주시겠어요?
</p>
<p><b>○ 기획조정실장 강철구 </b> 알겠습니다.
</p>
<p><b>○ 임병택 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 수고하셨습니다. 그러면 첫 번째로 김광철 위원님께서 먼저 질의하시기 바랍니다.
</p>
<p><b>○ 김광철 위원 </b> 안녕하십니까? 연천 출신 김광철 위원입니다. 일단 우리 홍순영 원장님 이하 또 연구원 여러분, 또 임직원 여러분들의 노고에 진심으로 감사를 드리고 치하와 격려를 드립니다. 제가 기획위원회에 와 가지고 업무보고 시에 원장님과 우리 북부문제에 대해서 여러 가지로 의견을 질의한 바가 있습니다. 그래서 오늘은 이 문제에 대해서 좀 제가, 감사사항에 대해서 질의를 좀 하고자 합니다. 원장님은 혹시 승용차로 구리에서 유료도로 구간을 이용해 보신 적이 있습니까, 의정부까지?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 있습니다.
</p>
<p><b>○ 김광철 위원 </b> 요금이 얼마 정도 되죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 그건 정확히 모르는데 제가 거기에 대해서 문제점을 인식한 거는 그쪽의 요금이 남쪽보다 훨씬 더 비싸다는 거를 알고 그래서 문제가 많이 있다라는 걸로 알고 있습니다.
</p>
<p><b>○ 김광철 위원 </b> 그럼 원장님은 수행자가 있어서 항상 다니셨나요, 아니면 개인적으로 가보신 적은 없으세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 최근에는 제가 개인적으로 가본 적은 없습니다.
</p>
<p><b>○ 김광철 위원 </b> 개인적으로 가보신 적은 없고 전부 다 업무 차 가셨기 때문에 얼마가 나온지는 모르신다?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 얼마가 나온지는 모르는, 그러니까 정확한 액수는 모르지만 그쪽에 우리 통행료가…….
</p>
<p><b>○ 김광철 위원 </b> 보통 우리 고속도로 통행요금이 일반적으로 시내구간이 얼마나 되죠? 한 750원에서 800원 정도 되지 않습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김광철 위원 </b> 그렇게 들거든요. 그다음에 거기는 지금 말이죠, 구리에서 우리가 민자고속도로로 들어가는 구간에 1,700원의 요금이 편도당 나옵니다. 몇 배입니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 2배 이상 되는 걸로 알고 있습니다.
</p>
<p><b>○ 김광철 위원 </b> 2배 이상의 요금을 내고 지금 북부지역의 주민들이 그 도로를 이용하고 있고요. 마찬가지로 우리가 고양에서 의정부까지의 구간도, 거기는 요금이 조금 더 비쌉니다. 이렇게 이용을 하고 있거든요. 이게 북부지역에 현실이 돼 놔서 몇 가지 추론을 좀 하고자 합니다. 원장님께서 여기 취임하신 지 얼마나 되셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 1년 8개월 정도 됐습니다.
</p>
<p><b>○ 김광철 위원 </b> 그럼 뭐 오래 되셨네요. 1년 8개월이면 거의 2년 차 좀 다 돼 가시는데 북부문제에 대해서 연구원 측이, 지금 여러 가지로 아까 경기북부의 도로교통, 주택 낙후실태 개선방안에 대해서 연구과제로 설립을 하고 계속해서 연구과제물을 도출을 해주셨습니다. 그런데 원장님이 정말 이게 필요하다. 북부 문제에 대해서 이러한 이러한 방향이 설정이 되지 않으면 안 되겠다는 부분에 대해서 혹시 인지한 것이 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 말씀하신 북부의 인프라 문제, 또 저희들이 연천, 포천, 이런 쪽이 북부의 굉장히 열악한 지역인데도 불구하고 수도권정비법이라든지 다양한 규제에 묶여 있어서 발전을 못하는 문제 또 북한의 낙후된 산업문제 이런 것에 대해서 경기도 내에서도 와서 보니까 남북 간에 문제가 생각보다 훨씬 더 크다라는 것을 제가 느끼고 그래서 저희들이 북부 문제에 대해서 다양한 연구도 하고 있고 지금 시군 토론회도…….
</p>
<p><b>○ 김광철 위원 </b> 잠깐만요. 제가 시간이 많지 않기 때문에 짧게짧게 좀 대답을 해주세요. 제가 지금 묻는 질문의 요지는 북부 문제가 최우선 돼야 되는 게 무엇이다 하는 게 인지된 게 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일단 인프라 문제하고 규제완화 문제가 좀 굉장히 중요하다고 생각을 하고 있습니다.
</p>
<p><b>○ 김광철 위원 </b> 여태 우리 도지사나 또 아니면 우리 연구직들이 그 문제에 대해선 다 동감을 하고 벌써 오래 됐죠. 이 분야에 대해서 메아리를 계속 쳐봤자 실질적으로 개선이라든가 가시적으로 보여지는 그런 어떤 결과는 보이지가 않습니다. 그게 왜 그런지 아십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> …….
</p>
<p><b>○ 김광철 위원 </b> 한 가지 더 질문하겠습니다. 우리 경기북부 문제에 대해서 2012년도에 과제가 지금 몇 개나 과업이 진행됐죠? 자료 빨리 준비해 주시고요. 시간이 별로 없어서.
</p>
