</p>
<p><b>○ 최재우 위원 </b> 987쪽 한번 봐주세요. 금년도 인건비가 101억으로 나와 있는데 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 최재우 위원 </b> 도에서 출연금도 90억 받고.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 최재우 위원 </b> 인건비 지출이 출연금을 초과했으니 아마 부족재원을 기금이나 수탁 과제용역비로 충당하였을 텐데 언제까지 도에서 매년 100억씩 지원해야 하는지 묻고 싶습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 굉장히 정확하시고 예리한 지적이신데요. 지방자치단체 산하 연구원의 설립에 관한 법률이라든지 그런 공공단체들의 성격은 어떤 세입, 수입을 자체 충원하는 것도 물론 있지만 일단 공공정책을 만들라는 거기 때문에 저희들이 소위 재정자립도하고 공공정책을 만들어내는 거하고의 두 가지 목적을 다 달성해야 되는 과제가 있습니다. 그래서 저희가 반 정도는 수탁으로 하고 있고, 200억 중인데, 반 조금 못 미치지만 그게 도비로 지금 하고 있기 때문에 저희들이 될 수 있으면 도로부터 도비를 어떻게 하면 적게 받을 수 있는가를 다각도로 연구하고 있고 또 노력을 하고 있는데 그럼에도 불구하고 기본적인 한계가 있다는 것을 말씀드릴 수 있겠습니다. 
</p>
<p><b>○ 최재우 위원 </b> 본 위원이 생각하기에 앞으로도 수년간은 현재 시스템으로 갈 것 같은데 그나마 운영비 절감을 위해서 인력의 효율적 관리가 필요할 것 같습니다. 그러기 위해서 초빙연구원 등 인력을 최소화할 계획이 혹시 있는지요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 초빙연구원 문제는 여러 가지 문제점도 있고 나름대로 장점도 있고 단점도 있고 이런 면이 있어서 지금 위원님 말씀하신 대로 초빙연구원 문제는 근본적으로 재검토 해 가지고 될 수 있으면 인력을 최소화하는 방향으로 운영하도록 노력을 하겠습니다. 
</p>
<p><b>○ 최재우 위원 </b> 그렇게 계획도 있는 거지요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 최재우 위원 </b> 내년도 경기개발연구원 인력운영 현황을 지켜보겠으며 2013년도 행정감사에서 이 문제를 다시 한 번 거론하지 않도록 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다. 
</p>
<p><b>○ 최재우 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 최재우 위원님 수고하셨습니다. 다음은 임병택 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 임병택 위원 </b> 세 번째 행정사무감사입니다. 2010년, 2011년 그리고 세 번째인 이 행정사무감사에서도 저는 똑같은 주제로 말씀을 드려야 되는 상황이 무척 참담합니다. 먼저 앉은 자리에서 답변 좀 해주세요, 강철구 기획조정실장님.
</p>
<p style="padding-left:1.2em">  초빙연구원이 총 몇 분이시지요?
</p>
<p><b>○ 기획조정실장 강철구 </b> 현재 20명으로 되어 있습니다.
</p>
<p><b>○ 임병택 위원 </b> 그런데 왜 12명이라고 그렇게 말씀하셨던 것 같은데.
</p>
<p><b>○ 기획조정실장 강철구 </b> 15명 정도라고 제가…….
</p>
<p><b>○ 임병택 위원 </b> 그렇게 말씀하셨습니다. 그럼 왜 5명은…….
</p>
<p><b>○ 기획조정실장 강철구 </b> 제가 잘 기억을 못해서.
</p>
<p><b>○ 임병택 위원 </b> 기억을 못해서요? 기획조정실장님께서 초빙연구원이 몇 명인지도 기억을 못하실 수가 있나? 우리가 비상임정책연구위원이 또 계시네요. 이분들은 몇 분이나 되실까요?
</p>
<p><b>○ 기획조정실장 강철구 </b> 현재는 없습니다. 
</p>
<p><b>○ 임병택 위원 </b> 전혀 없으십니까? 비상임연구위원이 있고 비상임정책연구위원이 있네요?
</p>
<p><b>○ 기획조정실장 강철구 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 두 분 다 안 계세요, 아무도?
</p>
<p><b>○ 기획조정실장 강철구 </b> 비상임연구위원은 있습니다, 과제별로. 
</p>
<p><b>○ 임병택 위원 </b> 이분들은 몇 분 정도나 계시는지.
</p>
<p><b>○ 기획조정실장 강철구 </b> 과제별로…….
</p>
<p><b>○ 임병택 위원 </b> 저는 비상임연구위원 분들이 몇 분이나 계시고 어떤 과제를 수행하시고 또 이분들의 보수는 어떻고 기본적인 현황이 또 궁금하네요. 자료 좀 제출해 주시기를 부탁드릴게요. 
</p>
<p><b>○ 기획조정실장 강철구 </b> 알겠습니다.
</p>
<p><b>○ 임병택 위원 </b> 원장님께 질문드리겠습니다. 작년 2011년 8월 달에 우리 경기개발연구원 설립 및 운영 조례가 개정된 거 알고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 저도 있었습니다. 
</p>
<p><b>○ 임병택 위원 </b> 그 자리에 계셨지요?  
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 개정내용이 어떤 내용이었나요?  
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 국가를 빼고 도정에 관련된 국내외 주요현안을 추가해 가지고 한 걸로 알고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 왜 그러한 조례가 개정이 됐고 본회의 통과해서 실질적인 개정까지 이루어졌습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그건 그전에 상당한 논란이 사실 있었는데 그래서 일단은 그때 당초 개정은 저희들로서는 경기도정을 수행하는데 국가를 연구 안 할 수 없지 않느냐라는 생각이 있었지만 그러나 국가라는 걸 또 강조하다 보면 경기도를 떠나서 국가라는, 경기도정을 떠난 국가 전체를 하는 것은 중앙정부에서 할 일이 아니냐 그래서 그런 것에 대한 명확한 입장 정리가 필요하다 이래서 알고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 제가 좀 더 부연설명을 하자면 경기개발연구원 광고비로 좌승희 원원장께서 광고를 하셨잖아요, 인터뷰 광고를. 그런 인터뷰 광고에 경기개발연구원은 김문수 대통령 후보의 싱크탱크다 이런 광고를 하셨어요. 행정사무감사 2010년도, 2011년도 자료를 보시면 아세요. 제가 지적했던 부분인데요. 경기개발연구원 연구주제는 물론이고 경기개발연구원 전임원장이셨던 좌승희 원장의 스텐스(Stance), 지금 이사장으로 계시지요. 대놓고 김문수 도지사 대통령 후보 싱크탱크라고 경기개발연구원의 존립목적 자체를 원장이라는 분이 그리고 고위간부라는 분들이 훼손하고 계시기 때문에 경기개발연구원 솔직히 다수의 선량한 목적을 가지시고 우리 지역개발 정책에 열심이신 연구원들, 박사님들 많이 계십니다. 몇몇 오염된 고위직들이 그런 식의 정치플레이 하는 것에 대해서 강제로라도 막아야 되겠다라고 해서 여야 공감대를 이루었고 원장님도 충분히 그 자리에 오셔서 동의하셨고 개정을 했단 말이에요. 그 회의록을 한번 보시면 제가 한 대목만 원장님께 다시 한 번 말씀을 드릴게요. 지금 현재 기획위원장인 김현삼 위원장이세요. 그분이 이렇게 발언을 하세요. “더불어서 이 연구원의 주체이신 원장께서도, 홍순영 원장님을 말씀드린 겁니다. 그야말로 학자적 양심을 걸고 이 경기개발연구원의 설립취지, 설립목적에 크게 벗어나는, 이를테면 일부에서 제기되어지는 경기개발연구원이 도지사의 싱크탱크냐 아니냐 하는 이런 우려를 불식시킬 수 있도록 스스로 노력을 기울이는 게 필요하다. 이렇게 생각하는데 원장님은 어떻게 생각하느냐.”라고 현재 기획위원장님이 그렇게 원장님께 여쭈었습니다. 원장님, “네, 옳으신 말씀입니다. 명심하겠습니다.” 학자적 양심을 걸고 경기개발연구원의 설립취지, 설립목적에 벗어나지 않도록 경기개발연구원을 지키셔야 되지 않습니까? 원장님은 그런 책무가 있다고 생각하지 않으세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그때는 그렇게 답변도 했고요. 지금도 그렇게 행동하고 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 지금도 그렇게 생각하고 행동하고 계시다고 하니 제가 몇몇 사례들을 원장님께 여쭈어 볼게요. 초빙연구원 중에 한 분이 이런 이야기들을 하셨어요. 저도 어제 너무나 이 자료들을 보면서, 생계형 좌파, 사회주의 틀렸다며 펑펑 울었다. 공짜 점심에 자유를 팔 것인가. 평등주의가 장악한 세상 그 악몽. 자유인이 될 것인가 꽃제비가 될 것인가. 경기개발연구원 초빙연구원 신분으로 칼럼을 쓰고 대외적인 인터뷰를 한 사람의 이야기들입니다. 무상급식, 10대 난동사건 해결방안은 있는가. 너무 멋진 이야기들을 많이 하셔서, 왼쪽 눈을 잃고 난 뒤로부터 진짜 세상이, 이런 분이 누구인지 아세요? 황성준 초빙연구원이라는 분이세요. 선임연구원이라고 홍보하시는 분이신데요. 2011년 7월 8일부터 8개월 근무하셨습니다. 월 평균 400만 원을 받으셨고요. 이분의 연구실적, 어이가 없습니다. 저희들에게 제공한, 기획조정실장님도 잘 들으시고 부원장님도 잘 들으세요. 원자료에 이분이 연구한 게 뭐로 되어 있느냐면 러시아 대외정책과 동향 등 공동연구라는 주제를 했다라고 보고를 하셨어요. 그래서 제가 세부자료를 정말 뭐를 하셨느냐라고 다시 한 번 요구를 했더니 러시아 이야기는 전혀 없어요. 김정일 사후 북ㆍ중관계 공동연구 하셨고요. 중국어선 서해불법조업현황 공동연구하셨어요. 원자료에 황성준이라는 초빙연구원이 무슨 연구보고서를 했는지, 연구를 했는지도 거짓보고를 하셨었고요. 원자료를 달라고 했더니 이 자료는 전혀 다른 주제의 공동연구로 되어 있어요. 이런 분이 3,000만 원이 넘는 인건비를 챙겨서 가셨습니다. 이분이 경기개발연구원을 위해서 기여한 부분이 있으면 한번 이야기 해보세요, 원장님. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 황성준 초빙연구원은 처음에 저희가 통일동북아센터도 있고 저희들이 러시아라든지, 4대국 있지 않습니까? 중국, 러시아, 일본, 미국이 있는데 저희들이 러시아 쪽은 없어 가지고 일단 채용을 했는데 와서 본인의 성향이라든지 이런 게 연구소와 잘 제대로 안 맞는다고 해서, 보통 우리가 연구를 해 가지고 성과가 나오려면 2년 이상 걸리는데 이 친구는 그래서 퇴사를 시켰습니다. 올해 2월 달에 퇴사를 했고 그래서 지금 경기개발연구원 소속은 아니고요. 저희들이 보통 새로운 연구원이 들어오면 쭉 지켜보는 그레이스 피리어드라는 게 있습니다. 그래서 보면 여러 가지 문제점이 있어 가지고 저희들이 퇴사를 시켰습니다.
</p>
<p><b>○ 임병택 위원 </b> 이분의 너무 멋진 표현이시네요. 생계형 좌파, 사회주의 틀렸다며 펑펑 울었다. 이분 같은 경우에는 이분의 말을 그대로 돌려드리면 생계형 구국파예요. 경기개발연구원에 둥지를 틀고 인건비 3,000만 원 챙겨서 가신 분이세요. 계약사항을 명백히 위반하셨지요?  
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 계약사항 위반 같은 건 제가 법률과가 아니기 때문에 그렇고요. 그래서 이 친구는 분명히 말씀드리는 건 내보냈습니다. 그래서 지금 여기 소속이 아닙니다. 
</p>
