<p><b>○ 경기개발연구원장 홍순영 </b> 그건 훨씬 더 많고요. 저희들도 그래서 연구보고서를, 원래 연구원들이 보고서를 쓰면 책자로 내는 것이 보통의 Norm이죠. 기준인데 학교도 그렇고 학자들이 자기들 보고서 내면 책자 내는 것, 그래서 그렇게 했는데 그것은 학자들은 그렇게 해도 우리는 좀 더 줄이자 해서 올해부터는 다양하게 반드시 보고서를 낼 필요는, 있는 것은 내겠지만 인터넷이라든지 또 SNS라든지 다양한 방식을 통해서 될 수 있으면 우리가 보고서를 인쇄하는 건 줄이자, 그게 아까 말씀하신 저희 소위 예산의 효율적 사용을 위해서 저희들이 다각도로 지금 많이 줄이고 있습니다. 제가 와서 줄이고 있는데 그럼에도 불구하고 지금 그런 지적을 들어서 저희들이 또 반성을 하겠습니다. 
