<p><b>○ 안병원 위원 </b> 못해도 저는 그렇습니다. 계속 주장하는 게 저도 여기 GRI 행감 세 번째 들어왔지 않습니까? 될 수 있으면 자체적으로, 자생적으로 또 치고 나갈 수 있는 방법론을 자꾸만 제가 외치지 않습니까, 말씀드리고. 그래서 어떤 용역 그런 부분에 대해서 2012년도의 자료를 보니까 31개 지자체에 대해서 열 군데도 안 돼요. 굉장히 노력을 안 하셨다, 저는 솔직히. 연구하시기 때문에 그렇게 할 수 있는 상황이 못 따라준다는 말씀도 들은 적은 있습니다. 그러나 연구하시는 분이 계시고 또 그렇지 않은 분들은 나름대로 그런 부분에 대해서, 경기도 지자체 사항을 누구보다도 제일 잘 아는 게 경기도청 아닙니까? 또 거기에 관여돼 있는 공기업이 GRI고. 그래서 이런 부분에 대해서 굉장히 미흡하다, 노력이. 제가 계속 말씀드렸던. 왜 그러느냐면  이게 출연금이 지금 처음에 왔을 때 120억 받으셨을 거예요, 2010년도에. 
