</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 2년 가까이 투병을 했습니다. 
</p>
<p><b>○ 배수문 위원 </b> 아까 존경하는 임병택 위원님이 지적하신 건에 대해서 연장선상으로 본 위원도 질의를 하겠습니다. 좌승희 이사장님 올해 어느 정도 활동하셨습니까, 혹여? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 올해는 작년에 의회에서 집중적으로 문제제기가 있어 가지고 그 이후로는 저희들 연구원 내에서 이사장 역할을 지금…….
</p>
<p><b>○ 배수문 위원 </b> 이사장으로 돼 계시고요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이사회에 나오셔 가지고 회의 주재하는 거 서너 번. 
</p>
<p><b>○ 배수문 위원 </b> 하셨죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 
</p>
<p><b>○ 배수문 위원 </b> 이사회의 회의록을 보니까 그때 하셨더라고요. 이사회 회의록하고 그 주재를 하셨는데 좌승희 이사장님에 대한 인터넷 검색을 해보면 외부적으로 상당히 많은 발언들을 하세요. 임병택 위원님께서 지적하셨던 연장선상에서 지금 경제민주화에 관해서는 민주당, 새누리당 할 것 없이 다 국회에서도 특위를 만들어 놓고요. 경기도의회에서도 2012년 10월 10일인가요. 경제민주화특위 만든 거 아시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 
</p>
<p><b>○ 배수문 위원 </b> 그럼에도 불구하고 경제민주화라는 용어는 좌파들이나 쓰는 용어다라고 하고 있고요. 이건 망국의 지름길이다라고 얘기하고 있습니다. 기존의 정치권들을 다 바보로 몰아가고 계십니다, 언론플레이를 통해서. 본인의 의견을 개진하는 건 이사장으로 안 계실 때 본인이 학자적인 위치에서만 가능한 얘기고요. 이런 발언들은 상당히 문제가 되는 발언이거든요. 특히나 극보수주의 발언을 너무 많이 하세요. 중도를 지켜주셔야지요. 그리고 좌승희 이사장님이 본인의 신념으로 경기개발연구원의 이사장직을 수행하는 게 아니라 도민들이 만들어준 세금으로 운영하는 곳이잖아요. 정치적 중립을 너무 위반하고 계십니다, 이분은 정말로. 상당히 많은 문제점을 내포하고 계신 분입니다. 특히나 언론의 홍보 같은 것은 상당히 잘 되고 있는데 이분에 할애된 부분도 많고요, 경기도 내에서는. 
</p>
<p style="padding-left:1.2em">  한 가지 더 지적하면 우리 서상목 연구원 아시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 
</p>
<p><b>○ 배수문 위원 </b> 경기복지재단에 본 위원이 산하 상임위원으로 2년 동안 상당히 많은 부분을 지적하신 분이에요. 내용 알고 계시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 이번 총선을 대비해 가지고 본인이 관용차량으로 본인 선거운동까지 하고 다니신 분이에요. 임병택 위원이 지적했던 월 500만 원, 참 안타깝습니다. 각고의 노력을 하고 경기도 발전을 위해서 연구하시는 다른 연구원들의 기본적인 마음에 상처를 많이 주신 활동들을 하신 분이 사실은 두 분이십니다, 역으로 생각하면. 그 많은 노력들이 이 두 분의 활동으로 인해서 다 덮인다는 얘기죠. 두 분에 대해서 코멘트하기 힘드시죠, 원장님?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 좌 원장에 대한 것은 좌 원장이 저희들이 그래서 이사장은, 저도 물론 거기 임원의 한 사람이지마는 저희 이사장이기 때문에 될 수 있으면 대외활동 같은 거 할 때는 경기개발원의 이사장 직함을 사용하지 마시라…….
</p>
<p><b>○ 배수문 위원 </b> 다 쓰고 계시고요. 아예 특별좌담까지 하셔서 인터뷰 기사가 나오고 있습니다, 신문에는.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그것도 정치적으로 저는 그렇게 바람직하지는 못한 일이라고 개인적으로 생각을 하고, 경기개발 이사장으로서는 그렇게 생각을 하고 있고요. 그래서 이사장의 활동범위라든지 이런 것을 저희들이 일일이 따라다니면서 할 수는 없는 거고 그렇긴 한데, 하여간 그 부분에 있어서는 배수문 위원님의 이야기를 적극적으로 저희들이 전달도 하고 그러겠습니다. 그리고 아까 서 이사장 문제는 존경하는 임병택 위원님께서도 지적하셨지만 그런 문제도 있지만 저희들이 소위 말하는 SIB라는 그런 특정목적, 거기에 대한 전문가 차원에서 했기 때문에.
</p>
<p><b>○ 배수문 위원 </b> 네, 목적도 모르는 게 아니고요. 채용됐던 과정이 정관에 없는 불법적인 방법으로 한 것도 아닌 것 알고 있습니다. 그럼에도 불구하고 그 분이 갖고 계신 상징성이 너무 부정적인 부분이 많고 특히나 그런 부정적인 부분과 연관 지어서, 본 위원은 그 상임위에 소속돼 있어서, 보건복지공보위원회 소속으로 있어서 그 절차를 누구보다 잘 압니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 저희도 명심하겠습니다.
</p>
<p><b>○ 배수문 위원 </b> 좀 쉬었다 오셔야죠, 오셔도. 그리고 연구과제에 국한돼서 특별히 오셔서 그것만 수행하시고 마치시면 참 좋은 건데 너무 안 좋을 때 오셨어요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 지금 고시 공고에 의해서…….
</p>
<p><b>○ 배수문 위원 </b> 그리고 그 건에 대해서 의혹이 되게 많습니다. 지사님과 친한 친분관계 때문에 오신 걸로 다들 생각하고 있어요, 누가 보더라도. 왜 경기개발연구원이 그런 데 연루가 돼 가지고 그간의 모든 연구실적을 다 날려버립니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그리고 SIB는 제가 뭐…….
</p>
<p><b>○ 배수문 위원 </b> 네, 알겠습니다. 그 건은 저희들이 내용 모르는 건 아니고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 명심하겠습니다. 네, 명심하겠습니다.
</p>
<p><b>○ 배수문 위원 </b> 임병택 위원님이 얘기했던 것처럼 조례라도 제정할 필요가 있을 것 같다라는 생각을 좀 하고요. 본 위원이 행감 준비를 하면서 주신 자료 다 살펴보았고 경기개발연구원과 관련된 보도자료 다 살펴보았고요. 그다음에 우리나라 유수의 연구소, 특히 세리에 계셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 배수문 위원 </b> 세리나 뭐 LG연구소, 현대연구소, SK연구소까지 다 확인해 봤습니다. 홈페이지 내용하고 거기서 주로 하고 있는 내용이 뭔지. 
</p>
<p style="padding-left:1.2em">  여기 임직원들은 타 기관과의 비교 어느 정도 하고 계십니까? 지금 본 위원은 강원발전연구소, 인천도 인천발전연구소, 서울연구원, 부산도 부산발전연구원 이렇게 쓰고 있더라고요, 명칭도.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 부산연구원 원장님은 특히나 세리 출신이시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 잘 알고 있습니다. 
</p>
<p><b>○ 배수문 위원 </b> 그래서 원장님은 어느 정도 교류하고 계세요? 각 지역 원장님들하고. 이창현 서울연구원장님이나.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 서울연구원, 인천발전연구원, 또 부산발전연구원은 아주 제가 익히 알던 친구이고.
</p>
<p><b>○ 배수문 위원 </b> 저희 것을 전파해야 될 만큼 잘 돼 있다라는 것 본 위원 동의합니다. 하지만 다른 연구원에서 제대로 가고 있고 방향을 잘 잡고 있는 것들에 대한 차용은 좀 하고 계십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그럼요.
</p>
<p><b>○ 배수문 위원 </b> 어떤 게 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 예를 들어서 지난번에 보니까 전북발전연구원에서 상당히 재미있는 연구를 하고 있더라고요, 규모는 작아도 상당히. 그래서 그거를 봐서 우리도 이런 연구를 한 번 해보자라는 것도 있고 예를 들어서 전북에 대한 발전방안 같은 것이 상당히 제가 볼 때는 정리가 잘 돼 있더라고요. 그래서…….
</p>
<p><b>○ 배수문 위원 </b> 또 한 가지 요청을 좀 하겠습니다. 그런 것을 그냥 보는 것뿐만 아니라 필요하다면 어떻게 운영되고 있는지에 대한 구조를 좀 살펴볼 필요가 있다라고 생각을 합니다. 혹여 원장님이나 임직원들께서는 각 인천이나 강원, 서울연구원, 부산연구원 등의 예산이나 조직들 그리고 업무보고 자료 좀 받아보신 적 있습니까? 검토해 보신 적 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 업무보고 자료는 조금 그렇지만 저는 끊임없이 홈페이지라든지 이 사람들의 연구내용이라든지 저는 심지어 파워포인트 하나 잘 만들어도 연구원들한테 권합니다. “이런 식으로 한 번 만들어 봐라.”라고.
</p>
<p><b>○ 배수문 위원 </b> 네, 그건 감사하고요. 본 위원이 행감을 준비하면서 사실은 각 연구원의 행감 자료를, 2011년도 행감 자료를 모두 봤습니다, 속기록을. 그 정도 노력은 있어야 된다, 연구원들 입장에서는. 특히나 연구원을 운영하는 핵심 브레인들은 그런 노력을 충분히 할 필요가 있다라고 보여집니다. 맞습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 고마운 충고이십니다.
</p>
<p><b>○ 배수문 위원 </b> 행감을 준비하면서 다른 쪽이 얼마만큼 하고 있는지, 뭘 대비하고 있는지, 뭐에 트렌드를 쫓아가고 있는지는 다 인지하고 계셔야 된다. 필요하죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 필요할 것 같습니다.
</p>
<p><b>○ 배수문 위원 </b> 다시 한 번 요구를 합니다. 그래서 기회가 된다면 각 연구원에서 행감 때 요청됐던 자료 같이 공유하시고요. 다른 지자체도 다 의뢰를 하시고요. 그다음에 각 업무 내용들을 좀 비교분석하시는 작업들을 그냥 보는 게 아니라 모여서 집중적으로 연구하시는 게 훨씬 더 발전에 도움이 될 거다. 왜냐하면 각고의 노력들을 다 하고 계시거든요. 강원 같은 경우는 정원이 34명인데도 불구하고 경영평가 순위 5년 연속 1위예요. 알고 계세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 경영평가라는 것이 어떤?
</p>
<p><b>○ 배수문 위원 </b> 전국 지자체, 그러니까 광역단체 연구원들의 경영평가를 매긴 점수에서 5년 연속 1위 했습니다. 그럼 분명히 차용해 볼 만한 내용이 있는 거다라고 보여지거든요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 배수문 위원 </b> 내용을 보니까 “너무 많이 연구를 해서 되게 피곤해 있다.”라고 위안을 하는 내용까지 포함됐을 정도로 되게 열심히 연구하고 있습니다. 지역적 여건이 좋지 않음에도 불구하고. 그거는 많이 좀 해볼 필요가 있다라는 생각이 듭니다. 거기서 얘기돼 있는 것 중에 하나가 직원 운영 합리화, 유연출근제 이런 부분들, 지금 원장님이 오셔서 유연출근제는 거꾸로 돌려 놓으셨죠, 역으로?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아닙니다. 유연출근제 하고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 하고 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 서울연구원 같은 경우도 해외 연구 학술자료 같은 것에 대한 재분석 같은 것, 그다음에 나름대로 좋은 내용들 좀 찾아볼 수 있다라고 생각합니다, 본 위원이 본 바에 의하면. 그리고 부산연구원 같은 경우는 저탄소 녹색도시와 관련된 팀이 따로 구성이 돼 있습니다. GRI 홈페이지를 보니까 저탄소 녹색도시처럼 돼 있는, 부산 같은 경우는 녹색도시연구실을 따로 만들어 가지고 하고 있거든요. 물론 지금 GRI도 충분히 녹색연구를 하고 있다라고 보여지는데 콘텐츠를 따로 만든 것 같은 느낌이 없습니다. 홈페이지 첫 장면에 보면 “저탄소 녹색도시 경기도에서 피어납니다.”라고 지금 로고처럼 거의 쓰고 계세요. 알고 계시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 그렇다면 기후기금도 인천에 유치된 것처럼 녹색이 향후에 가장 또 중요한 이슈 중에 하나일 겁니다. 그렇다면 여기에 대한 특별팀도 만드는 거는 고려해볼 시점이 아닌가라고 생각을 합니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
