<p><b>○ 권오진 위원 </b> 권오진 위원입니다. 저도 임병택 위원님, 배수문 위원님 연장선상에서 말씀을 잠깐 드릴까 생각을 합니다. 아직도 좌승희 씨가 이사장을 하시는 거죠?
