<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 지배구조상 이사회라는 게 또 있어야 되니까. 이사회가…….
</p>
<p><b>○ 권오진 위원 </b> 솔직히 이사회를 없애고 싶어요, 저는 솔직히 말해서. 이사회 회의록을 다 제가 봤는데요. 내가 이걸 왜 봤나 하는 생각이 들 정도예요. 이사회 회의록이 정말로 이 시대의 가고 있는 걸 갖다가 제시해 주고 있는 건지를 모르겠고요. 여기는 정말로 다 끝난 얘기 같은 얘기만 하고 있고 그냥 자기들 모여 가지고서 별도의 단체 운영하는 것 같은 생각이 들어요. 뭐 교섭, 사회단체, 사회 뭡니까? 그런 조직들. 참석해 보셔서 알겠지만. 정말로 여기에 중앙으로 가신 박수영 실장님께서 하신 말씀이 아주 재밌게 나와 있어요. 좌승희 씨에 대해서 아주 상당히 칭찬해 가면서 이사장 올린 걸 갖다가 잘했다고 여기 돼 있고 난 도대체 이걸 보고 나서 도대체 이사회가 왜 필요한 것인가. 오히려 연구하는 데 바쁘신 선임연구원님들 보고하는 데 시간 아깝게 말이죠. 전 그런 생각이 듭니다. 솔직히 이사회라는 데가 경기도의 방향을 끌어가 줘야 되고 연구과제도 좀 봐줘야 되고 이런 것이 돼야 된다고 저는 생각을 하는데 솔직히 이런 이사회 내용을 가지고서, 앞으로 이사회 끝나시면 이사회 회의록을 갖다가 도의회 우리 기획위원회 위원님들한테 좀 보내주실 수 있으시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그럼요.
</p>
<p><b>○ 권오진 위원 </b> 보내주셔 가지고 즉시즉시 될 때마다 문제를 삼고 어떤 분의 발언에 대해서 한 번 삼을까 생각합니다. 여기에 보게 되면 뭐 좌빨이 어떻고 이런 얘기만 나와 있어요. 아무래도 이 내용을 가지고 연구원들이 영향을 안 받는다고 하는 것도 정말 이상한 것이고 아무래도 이사장이 원장님한테 한마디 하면 원장님이 또 가만히 있겠어요? 우리 한국 조직사회에서 이렇지 않을 것 아니에요. 이런 내용에서 볼 때 상당히 어렵다고 생각합니다. 그래서 사실 그동안에 이거는 지난번 전반기 우리 의회 기획위 위원님들이 좀 잘못한 것 같아요. 왜 잘못했다고 보느냐, 사실 이런 내용들에서 아까 말씀드린 황성준이나 서상목 이런 분들을 왜 초빙연구원으로 해촉했나 해서 봤더니 그런 걸 하지 말라고 해서 예산을 줄였어요. 그랬더니 기금에서 19억을 더 썼더라고 보니까. 이건 예산을 절감한 감사 의미가 없는 거예요. 행감 목적이 다음해 예산 책정할 때 절감하든지 어떤 걸 갖다가 삭감하는 이런 기능이 있는 것인데 “잘라봐라. 우리 기금에서 쓴다.” 이게 경기개발연구원이에요, 솔직히 말해서. 그럼 우리 다음 이번 예산에서는 우리 위원들은 그럴 거예요. 기금이 소진될 때까지 예산을 다 잘라보자, 한 번. 기금을 왜 만든 겁니까? 기금을 갖다가 이렇게 해 가지고서 경기도에서 출연하고 시군에서 출연하고 해서 만든 것이 예를 들어서 금년에 19억, 작년에 13억, 10년에 10억, 그런데 안 썼어요. 그러니까 이번에 8대가 들어왔을 때부터 예산 잘리게 되면 기금에서 쓰는 거예요. 이게 맞다고 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 기금사용은 저도 몇 번 도하고도 같이 예산 협의를 할 때 “못 쓰겠다.” 그런 제 입장이고요, 기금은. 기금은 정말 긴급하고 위급하고 이럴 때 쓰는 것이 기금인데 이것이 매년 예산의 부족분을 채우는 식으로 기금을 운영해선 안 된다는 것이 제 개인적인 소신이고요. 그런데 예산을 짜는 분들은 기금까지도 예산안의 자금 안에서 생각을 하더라고요. 그래서 저는 거기서 굉장히 반대의 생각을 갖고 있고 아니라고 계속 지금 주장을 하고 있습니다.
</p>
<p><b>○ 권오진 위원 </b> 원장님이 그러시면 이사회에 발언해서라도 이거 이사회에 올려야 될 것 아닙니까? 이사회에서 쓰라고 그랬어요, 분명히. 10억 써라, 19억 써라 했으니까 쓴 건데 그렇다면 그거에 대해서 이사회에서 발언해서 안 쓰겠다라고 해서 나와야지 되는 거죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그거는 참고로 말씀드리면 처음부터 기금을 쓰는 걸 전제로 해서 예산이 통과됐기 때문에, 그러니까 위원님들께서 저희들 예산을 좀 확보해 주시면 저희들이 기금을 거의…….
</p>
<p><b>○ 권오진 위원 </b> 아니죠. 예산을 자르는 것은 좀 효율적으로 쓰고 절약을 하고 이런 엉터리 같은 사람들 채용하지 말라는 거죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다.
</p>
<p><b>○ 권오진 위원 </b> 적어도 좌승희 씨가 있는 한은, 여기 말한 대로 서상목 씨가 있는 한은 예산을 갖다가 못 얻을 거예요. 그러면 조례 바꿔 가지고 만들 거예요. 조례 바꿀 거예요, 그러면. 이렇게 운영을 해야지 이런 분들 와서 하게 되면 어떤 일이 생기느냐 연구를 열심히 하신 연구원들이 정말 실망하는 겁니다. 나는 그게 더 두려운 거예요. 솔직히 이사회 같은 데가 이 시대의 트렌드인 시대정신에 맞춰서 아까 말씀하셨지만 경제민주화라든지 어떤 팀 하나 선정할 때 여기서 보시면 다 금년, 작년 다 보세요. 지금 트렌드가 엄청나게 빠져 있습니다. 지금 발표하신 내용 중에서. 왜, 본인들이 하겠다고 우리 연구원들이 내신 자료들이에요. 여기 있지 않습니까? 여기 아래 있는 게 본인이 내신 것 아닙니까? 아래 있는 것, 제안 연구과제는. 이런 내용 속에서 엄청나게 하고 싶은 것이 빠져 있는 거예요. 만약에 이걸 하겠다고 했으면 좌승희 어떻게 해서라도 박살내겠지. 이런 겁니다, 솔직히 말해서. 제가 설명을 드려볼까요, 한 번? 그래서 사실은 이사회가 그만큼 중요하다 생각하는 것이고 이사회 구성도 정말로 거기에 맞춰가지고 돼야 되는 것인데 여기 보세요. 행정의정 같은 경우 보게 되면 여기에 균형발전이라는 부분이 없습니다. 아까 우리 김광철 간사님이 말씀하신. 없잖습니까, 솔직히 말해서. 그런 것도 없고 북부엔 있지만 동부 쪽에는 더 없고요, 지금. 도시주택 부분에서 해야 될 부분은 주거복지입니다. 없지 않습니까, 지금. 복지가 빠진 것은 왜 빠졌습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 복지 연구를 지금 하고 있습니다. 
</p>
<p><b>○ 권오진 위원 </b> 복지 연구를 한 걸 좀 자료를 주세요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 권오진 위원 </b> 복지 연구한 것에 대해서.
