<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 권오진 위원 </b> 이것을 사실 지난번에 봤을 때 왜 빠졌나 했더니 복지재단 쪽에서 연구가 되기 때문에 연구원으로 갔다. 그래서 못했다고 얘기를 했어요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 작년까지는 그랬습니다.
</p>
<p><b>○ 권오진 위원 </b> 그러면 이사회라는 데가 서상목 씨가 와서 얘기했을 때 암만 끗발이 세도 이사회에서 “이거는 정말로 가면 안 됩니다. 연구는 여기서 해야 됩니다.”라고 말을 해야 된다는 거지요, 이사회에서. 이사들이 앉아가지고서 멍청하게 도지사가 말하니까 가만히 들어가지고서 넘어가는 것도 두고 있는 그런 이사회가 뭐 존재가 필요 있느냐. 이게 제가 말씀드리는 거예요. 또 창조경제에 있어서는 경제민주화 하나도 없죠? 그다음에 통일ㆍ동북아 문제에 있어서도 아까 안병원 위원님이 말씀하셨듯이 정말로 지역에 필요한 내용들이 없습니다, 솔직히 말해서. 이거는 지금 뭐가 문제냐면 경기도에서 해결할 사항들에 대해서만 연구대행 해주는 거예요. 정말로 중요한 것은 민군정책팀에서 해야 할 일은 민과 군하고 중간에 관이 껴가지고서 관에서 해결해야 줘야 되는 겁니다. 민의 문제를. 진짜 이들 5명이 앉아가지고서 민의 문제를 알고 있냐는 거죠, 진짜로. 이게 안병원 위원님이 말씀하신 그런 내용들이에요. 이런 내용들을 갖다가 스스로 파악을 해 가지고서 연구하고 군관협력팀을 통해 가지고서 해결하기도 하고 이런 것들이 돼야 되는 것인데 이러한 것들이 과연 현직 이사회에서 끌어갈 수 있겠느냐 하는 것이 문제입니다. 이사회 개편할 용의가 있으신지 하는 걸 한 번 답변해 보세요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이사회는 제 소관이 아니기 때문에.
</p>
<p><b>○ 권오진 위원 </b> 누구 소관입니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이거는 이사들이 자율적으로 정하고 있고 우리나라 지배구조의 특수한 사정이고 권 위원님께서 말씀하시는 건 상당히 많이 옳은 내용이 있으십니다. 그래서 이사회 기능을 정상화시켜서 이렇게 하는 걸 저희들이 여러 가지 방안을 강구해 보도록 하고요. 저도 물론 이사진의 한 사람이니까 이사회를 어떻게 구성하고 어떻게 끌고 가야 되겠다는 것은 저도 고민을 좀 많이 해보겠습니다.
</p>
<p><b>○ 권오진 위원 </b> 그럼 이사회는 도지사가 결정하는 것이다 이런 얘기입니까?
