<p><b>○ 신종철 위원 </b> 잠깐만요. 이건 기술적인 문제로 논란을 갖자는 게 아니에요. 앉으셔도 좋아요. 그러니까 우리 많은 용역의 근본적인 문제입니다. 중요한 정책을 결정하는데 의정부의 요구에 맞춰서 한 건지 객관적인 그런 의심이 들 정도로 당초로 7만 9,000명이 탈 거라고 예측해 놓고 지금 1만 1,000명밖에 안 타거든요. 용인도 마찬가지 아닙니까? 예산낭비의 대표적 사례입니다. 그러면 용역이 잘못되었다는 거 아닙니까? 입증되는 거지요, 결국. 결과로 입증되지 않습니까? 문제는 뭐냐 하면 본 위원이 의정부경전철은 경기도 사업이 아니라 의정부시 문제인데 불행하게도 경기개발연구원에서 1년 전에 이 문제에 대해서 다시 용역을 하신 거거든요. 여기에서 지금 수요가 줄 것이다 이런 문제들이 제기가 되니까 아마 의정부에서 용역을 마쳐서 활성화 방안을 했습니다. 그런데 여기에서도 수요예측을 어떻게 했느냐면 시나리오를 1, 2, 3으로 나눠서 시나리오 1 단독요금제일 경우에는 5만 6,000명, 당초의 71% 정도가 탈 것이다. 통합요금제일 때는 6만 3,000명, 그리고 시나리오 3일 때는 5만 7,000명 이런 식으로 예측을 다 했단 말이에요, 나눠서. 그런데 실제로 1만 1,000명 타는데 5만 6,000명 탈 거라고 예측을 하는 이런 엉터리조사가 어디 있습니까? 말이 안 되잖아요. 그러니까 이건 입증되는 것 아닙니까? 1만 1,000명밖에 안 되는 걸 5만 6,000명 이렇게 연구를 하고 그걸 1억 9,000 받아가지고 의정부에 제출했으면 경기개발연구원에 책임이 있지 않습니까? 
