<p><b>○ 경기개발연구원장 홍순영 </b> 일단 위원님의 지적에 대해서 겸허하게 수용을 하고요. 앞으로 연구를 할 때 좀 더 수요예측에 대해서 신중을 기울이겠습니다. 다만 저희들의 수요예측이라는 것은 안정적으로 완전히 정상적으로 운영됐을 때에 5만 명 된다는 이야기거든요, 개통된 게 아니고. 그래서 한 2∼3년 더 지나봐야 된다는 얘기인데 일단 그렇다 하더라도 지금 1만몇 명이 타는 것은 저희들이 볼 때 상당히 적은 숫자이고 문제가 있다는 것은 충분히 저희들이 수용을 하고 앞으로 용역수행을 할 때 좀 더 객관적으로 연구를 하도록 지금보다 더 노력을 기울이겠습니다. 
