<p><b>○ 경기개발연구원장 홍순영 </b> 이 문제는 연구이기 때문에, 저희들은 연구할 때 객관적으로 그 당시의 나름대로 여러 가지 툴을 활용해서 연구수행을 진행한 거기 때문에 지나놓고서, 예측이라는 게 굉장히 어렵습니다. 저도 개인적으로 예측을 많이 담당해봤었는데 상당히 하루 앞도 못 볼 때도 굉장히 많고요. 그래서 지탄도 많이 저거하고 그래서 굉장히 힘든 작업입니다, 예상이라는 것이. 미래의 일이기 때문에. 그럼에도 불구하고 정확하게 하려고 저희들이 계속 여러 가지 다양한 학문적 기법이나 개인적 노력을 앞으로 기울이도록 하겠습니다. 
</p>
<p><b>○ 신종철 위원 </b> 예측을 한다는 건 쉬운 일은 아닐 거라고 생각을 합니다. 본 위원이 그래서 지금 과학적인 문제를 따지자고 하는 게 아니고 이건 정책에 대한 책임문제에 대해서 우리가 어떻게 생각할 것이냐 그리고 두 번째로는 경기개발연구원이 이런 연구에 대한 검증장치를 제대로 가지고 있느냐 이런 거에 대한 의구심입니다. 연구용역은 지금 아주대학교 KSM기술 여기에다 맡겼는데 나온 결과로 보면 엉망이거든요. 일반적인 표현으로 하면 엉터리 용역입니다, 엉터리 용역. 1만 명 타는데 5만 9,000명 탄다는 이런 용역이 어디 있습니까? 그러면 앞으로 아주대학교 KSM기술연구원에는 용역 못 맡기겠네요? 여기 하고 앞으로 할 계획 있습니까? 무슨 조치가 있어야 되지 않겠습니까? 이게 뭡니까? 우리 내에서는 그러면 이런 엉터리 용역을 1억 9,000을 해 가지고 했는데 용역이니까 틀릴 수 있다 이래 가지고 넘어가면 저거입니까? 우리 내에서 어떤 조치를 하겠습니까? 이런 용역이 발생 안 되도록 어떤 일을 하겠는지 이런 게 있어야 되지, 아니 뭐 그냥 연구했는데 우리가 예측하고 틀렸다 이렇게 넘어가면 됩니까? 도덕적 문제입니다. 비도덕적 행위지요. 우리 책임 없다, 미안하게 됐다, 잘못 예측했다 이래 가지고 넘어가면 되는 문제입니까? 이 문제로 인해서, 우리가 물론 당초용역을 가졌던 건 아니니까 근본 책임은 없습니다만 경기개발연구원이라는 연구원의 명예를 가지고 본다라고 하면 엉터리 용역을 했다는 이 불명예를 어떻게 씻겠습니까?
