<p><b>○ 경기개발연구원장 홍순영 </b> 이 용역에 대해서는 제가 부임하고 난 다음에 용역이나 이런 거에 대해서 객관적으로 자기 양심에 따라서 자기 실력을 최대한 발휘해서 하자라는 게 제 개인적인 생각이고 다만 각 부문에 있어서의 전문, 교통이나 이런 건 다 전문영역들이니까 제가 다 알 수는 없습니다. 그러나 일단 저희 연구원들이 최대한으로 한 연구용역이기 때문에 저희들이 엉터리는 아니고요. 다만 수요예측이 틀린 부분에 대해서는 시간이 지나봐야 확인되는 거고 여러 가지 문제가, 그러나 제가 모두에 말씀드린 대로 지금 차이가 나고 있으니까 우리가 발주한 데라든지 수주한 데에 대한 기관에 대해서 철저하게 앞으로 더 조심을 하고 더 얘기를 하고 우리도 사후적으로 연구용역을 했는데 결과적으로 틀리면 왜 틀렸는지 이런 거에 대해서 연구원들한테도 좀 더 경각심을 갖고 재검토하는 기회를 반드시 갖도록 할 것고요. 이 문제는 굉장히 잘 지적을 해주셨는데 앞으로 하여간 이런 용역에 대해서 결과가 나오면 사후검토도 하고 또 검증절차를, 나름대로 검증절차를 하고 있는데 아무래도 가장 전문가들이 하는 검증을 비전문가가 하기가 조금 힘든 측면이 있어서 그것을 저희들이 어떻게 할 것인가 다양하게 방법을 고안해 보도록 하겠습니다. 아주 좋은 말씀 주셔서 감사드립니다. 
