<p><b>○ 경기개발연구원장 홍순영 </b> TF팀은 도에서 꾸려가지고 저희가 참여하는 거고요. 경제부지사가 팀장이고. 여기에서 서 위원께서는 그 TF팀의 일원인데 그건 저희 경기개발연구원이 주가 아니고 도가 주고, 그래서 하고 있는데 거기에서 다양한 소위 실행계획, 사례, 어떻게 만드는가 이런 걸 하는 걸로 알고 있습니다.
</p>
<p><b>○ 오완석 위원 </b> 그러면 서상목 초빙연구원이 독자적으로 하는 것이 아니고 아까 공동연구한다고 했잖아요. 그러면 이상훈 선임연구원님이 하시는 팀에 공동으로 들어가는 건가요? 몇 분이 연구하시는 거지요?  
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이재광 박사라고 저희 다른 친구가 있는데 2명이 지금 하고 있고 또 이 양반들이 도에서 하는 TF팀 하고 같이…….
</p>
<p><b>○ 오완석 위원 </b> 본 위원이 보기로는 본청에서도 김문수 지사의 회전문인사 내지는 보은성인사 이런 것 때문에 한참 말이 많고 지금도 그 부분이 해결이 안 된 것으로 알고 있습니다. 사실 서상목 이분이 건강보험공단의 이사장을 하셨고 그래서 보험 서비스 체계라든가 아니면 복지 관련된 체계에 대한 부분에 대해서 많은 경험을 하셨겠지만 이거는 그 경험만 가지고 되는 것이 아니고 이론적 토대로 해서 하는 연구인데 과연 맞느냐라는 생각이 들지요. 그리고 그 얘기는 뭐냐 하면 공교롭게도 이분이 충청도에 가셔가지고 선거에서 떨어지고 난 이후에 특별히 하시는 게 없어요, 보면. 없지요? 없고 오히려 구설수에 오르고 언론에 보면 좋은 얘기도 많이 안 나왔던데 여하튼 아까도 복지재단에 있을 때 그런 문제점이라든가 이런 부분은 위원님들께서 말씀하셨기 때문에 제가 굳이 말씀 안 드리고 이건 분명히 제가 보기에는 아까 우리 임병택 위원님도 말씀하셨겠지만 연구목적이나 이런 걸 봤을 때 어울리지 않는 분이시다 이렇게 생각이 됩니다. 그리고 이건 보은성, 그다음에 몇 개월 동안 자리를 보전해 주고 급여를 지급해서 생활할 수 있게끔, 죄송합니다. 인신공격하는 것은 아닌데 그 정도 수준으로도 누구라도 다 오해할 수 있는 그런 소지가 아닌가 이렇게 생각을 해봅니다. 그래서 초빙연구원에 대한 해임 권한을 누가 가지고 있습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 초빙연구원의 계약이 만약에 불성실한다든지 안 그러면…….
</p>
<p><b>○ 오완석 위원 </b> 아니, 권한을 누가 가지고 있어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 해지할 수 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 제가 보기에는 해임하시는 게 좋을 것 같습니다. 경기개발연구원에 서상목 현 초빙연구원보다도 월등히 유능하신 분들이 많이 계실 것 같고 이 이론 자체가 아까도 말씀하셨지만 이미 실무화돼 있고 도입단계에서, 물론 경기도만의 특별한 계획이라고 하는데 복지정책 솔직한 얘기로 경기도에서 독자적으로 하는 게 뭐가 있어요? 다 국가에서 해야만이 되는 문제고 그런 문제 아닙니까? 그래서 본 위원이 생각하기로는 경기개발원의 연구원을 가지고도 충분히 가능하다고 보고요. 초빙연구원 쪽에서 이렇게 논란이 빚어지면 해임을 하시는 게 맞다라고 생각이 됩니다. 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 목적을 달성할 수 있는가, 없는가를 위원님들이…….
</p>
<p><b>○ 오완석 위원 </b> 물론 그 부분을 제가 속마음은 어떻게 알겠습니까, 하지만 누가 봐도, 객관적으로 봐도 연구원으로 선임한 과정에 충분한 오해의 소지가 많다는 얘기죠. 그리고 이분이 어떤 연구결과를 내놓을지, 연구결과야 다른 분들하고 공동으로 하니까 내놓겠지만 어떤 역할을 할지 기대가 안 됩니다, 도저히. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그건 저희들이 5개월 한시적으로 한 거고.
</p>
<p><b>○ 오완석 위원 </b> 그러면 이 부분에 대한 부분은, 사회성과 연계채권 활용방안에 대한 부분은 경기개발연구원에서 제안을 하신 거죠? 그리고 합당한 연구진을 찾다보니까 서상목 초빙연구원을 찾게 된 겁니까? 아니면 그분이 먼저 제안을 하신 겁니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일단 도청에서 얘기가 있었고요. 도청에서 누가 제안했는지 모르겠습니다. 그리고 저희도 그런 유사한 일을…….
</p>
<p><b>○ 오완석 위원 </b> 도청에서 제안한 거죠? 경기개발연구원에서 제안한 게 아니죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들도 하려고 마음 먹…….
</p>
<p><b>○ 오완석 위원 </b> 아니, 도청에서 했습니까, 경기개발연구원에서 했습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 양방향에서…….
</p>
<p><b>○ 오완석 위원 </b> 경기도청에서 제안을 한 거죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들 사회적 경제, 사회경제는 저희들이 연구를 하고 있었고 SIB는 도청에서 하자고 그랬고. 
</p>
<p><b>○ 오완석 위원 </b> 그러니까 이 부분이 구체적으로, 이건 곧 정책입니다. 먼젓번에 업무보고 했을 때 말씀드렸지만 경기개발원이 하는 것 중의 하나가 경기도정 지원 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다. 
</p>
<p><b>○ 오완석 위원 </b> 정책개발하고 그 정책에 대해서 하는 건데 이건 바로 직결되는 거죠. 지금 하겠다는 거 아닙니까? 펀드 조성해 가지고 주식회사 만들어가지고 민간자본 끌어들여서 복지하겠다는 거 아니에요. 복지예산이 자꾸 늘어나니까. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.  
</p>
<p><b>○ 오완석 위원 </b> 이게 곧 정책이에요. 그럼 경기도에서 제안하는 거 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다. 
</p>
<p><b>○ 오완석 위원 </b> 그러면 같이 서상목 초빙연구원 써봐라 했겠죠. 그렇지 않습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 뭐…….
</p>
<p><b>○ 오완석 위원 </b> 그럼 어떻게 해서 서상목 초빙연구원이 이거와 관련된, 이 이론이 아직 일반화된 것도 아니고 생소하고 국내에 들어온 지 얼마 되지도 않았는데, 전 세계적으로도 그렇게 활성화된 제도가 아닌데 서상목 초빙연구원이 적합자라고 판단하게 된 동기가 뭐예요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그 양반이 그런 연구에 대해서 발표도 했고요. 
</p>
<p><b>○ 오완석 위원 </b> 언제 했습니까? 발표된 자료가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 있습니다. 
</p>
<p><b>○ 오완석 위원 </b> 그 자료 좀 주시고요. 그래서 그거 보고 이분이 적당하다고 해서, 합당하다고 해 가지고 초빙하신 거예요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 사람들 초빙연구원할 때는 다양한 경로가 있고 추천도 받고…….
</p>
<p><b>○ 오완석 위원 </b> 어디서 추천받으셨어요? 도에서 받으셨죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 추천받은 것은 다양한, 저희들이 판단하는데…….
</p>
<p><b>○ 오완석 위원 </b> 경기도에서 받으셨죠? 어디서 받았어요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니 서 이사장님이, 솔직히 얘기해서 서 이사장님이 저한테 전화도 했고 이러이러한 게 있다. 
</p>
<p><b>○ 오완석 위원 </b> 본인이 하고 싶다?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이런 게 있다라고 했고 또 도청에서 이런 걸 했으면 어떻겠느냐, 제가 봐도 괜찮은 거 같고. 
</p>
<p><b>○ 오완석 위원 </b> 알겠습니다. 결국은 이 부분에 대해서 도청에서 제안을 했고 직접 원장님한테 서 초빙연구원 전 이사장이 제안을 했고 그렇지 않습니까? 전화도 왔고 그래서 이것에 대해서 검토해 봐라라고 경기개발원의 박사님들한테 얘기했겠죠. 해보니까 찾아보니 미국에서 그렇게 하고 있고 그다음에 서울시도 한다고 하고 하면 큰 문제 없을 것 같습니다, 해서 진행한 거 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그리고 이 양반이 이 전문가시니까…….
</p>
<p><b>○ 오완석 위원 </b> 이 전문가라는 걸 뭐로 증명하죠? 이걸로 논문 낸 거나 박사학위 받은 거 있습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니, 대한민국 보건복지부장관 하신 분이…….
</p>
<p><b>○ 오완석 위원 </b> 보건복지부장관도 분야가 여러 가지가 있죠. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 특히 연금이라든지 이런 쪽에 관심이 있고요. 그리고 여러 가지, 그리고 제가 알기는 알겠습니다. 위원님 말씀 충분히 알고…….
</p>
<p><b>○ 오완석 위원 </b> 그래서 본 위원이 생각하기로는 이것은 분명히 경기도에서 지정된 선임연구원이고요. 과제 또한 마찬가지로 경기도에서 지정을 했고, 물론 좋습니다. 경기도에서 도정에 관련된 정책을 개발하기 위해서 한 것은 좋죠. 당연하다고 보는데 본 위원이 생각하기로는 서상목 전 이사장은 적합하지 않다, 이렇게 판단이 되고요. 우리 원장님께서 해임에 관련된 그 당위성을 만드셔가지고 해임시키세요. 아니면  이거 계속 더 추궁할 겁니다. 도에도 마찬가지고. 
</p>
<p style="padding-left:1.2em">  김문수 지사가 한두 명이 아니죠. 선거 때마다 회전문인사 누구나 다 아는 문제고 단 한 사람도 혜택을 안 본 사람이 없어요. 어떻게 했든 간에 선거에 참여했던 사람들은 단 한 사람도 다시 채용이 안 된 경우, 복직이 안 된 경우가 없습니다. 이분도 마찬가지예요. 선진당으로 가가지고 충청도에 내려가서, 왜 책임져야 됩니까, 우리가. 그리고 아주 유명하게 황수관 박사의 웃음치료처럼 아주 대단한 그런 연구실적을 가지고 있다든가 그런 유명한 분도 아니고 보건복지부장관 한 분이야 수도 없이 많죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> KDI 연구위원도 하셨고요. KDI 부원장도 하셨고 연구 나름대로, 알겠습니다. 
</p>
<p><b>○ 오완석 위원 </b> 부원장, 물론 부원장이 계시지만…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 위원님 말씀 제가 충분히 이해를 했고요. 고려해 보겠습니다.
</p>
<p><b>○ 오완석 위원 </b> 그래서 이 부분은 도하고 상의를 해보십시오. 상의를 하셔가지고 조치를 하시는 게 좋을 것 같습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 여러 가지로 생각을 해보겠습니다. 
</p>
<p><b>○ 오완석 위원 </b> 조치를 하세요. 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 오완석 위원님 수고하셨습니다. 서상목 초빙연구원과 관련해서 저도 드릴 말씀이 많이 있습니다만 중식시간이 됐기 때문에 마무리 시간에 제가 말씀을 더 드리도록 하고요. 
</p>
<p style="padding-left:1.2em">  위원님들께 양해말씀을 드리도록 하겠습니다. 감사를 진행하다 보니까 중식시간이 경과됐습니다. 따라서 중식과 휴식 후 계속 감사를 진행하고자 하는데 이의 없으십니까? 
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 중식과 휴식을 위해서 2시 30분까지 감사를 중지하겠습니다. 
</p>
