<p class=''ar''>(14시34분 감사계속)
</p>
<p><b>○ 위원장 김현삼 </b> 좌석을 정돈해 주시기 바랍니다. 오전에 이어서 감사를 계속하겠습니다. 오전에 위원님들 10분씩 질의를 전부 다 모두 끝마쳤습니다. 그래서 추가질문 답변시간을 갖도록 하겠는데요. 추가질의 답변 시간은 5분씩 드리도록 하겠습니다. 그래서 그 순서는 윤희문 위원님 그리고 신현석 위원님 그리고 오전에 했던 순서대로 해서 진행을 하도록 하겠습니다. 질의에 앞서서 위원장으로서 한 말씀드려야 될 것 같습니다.
</p>
<p style="padding-left:1.2em">  오전에 저희 위원들께서 경기개발연구원 원장을 상대로 질의응답이 있었습니다만  오늘 질의응답을 지켜보면서 본 위원장이 느꼈던 감회가 그렇습니다. 경기개발연구원이 경기도의 종합연구기관으로서 그 기능을 제대로 수행을 하고 있는지, 사실은 감사의 핵심의제가 돼야 되는 건 너무나 당연한 겁니다. 그런데 그런 쪽에 포커스를 맞춰서 저희 위원들께서 행정사무감사를 준비를 했습니다만 그런 시간보다는 경기개발연구원이 지난 시기에 특정한 인물 몇몇을 저희 위원들이 보기에 합당하지 않다고 생각되어지는 방식을 통해서 초빙연구원이랄지 위촉이 돼서 연구활동 수행하는 거에 대한 지적이 있었는데요. 참 참담한 심정입니다. 
</p>
<p style="padding-left:1.2em">  여러분께서 많이 지적을 하셨습니다만 예를 들면 서상목 씨 같은 경우에 경기복지재단 이사장인가로 있을 때 그때 편법으로 공금을 활용해서 본인의 책을 출판한다든지 또는 공공기관 재산물, 그 당시 승용차였죠. 공공기관의 재산물을 경기복지재단 업무와 전혀 상관없는 그런 곳에 활용을 하고 그런 것들이 지적이 되면서 사실은 그래서 물러난 거죠. 물러나신 분인데 그런데 초빙연구원으로 지금 경기개발연구원에 와서 근무를 하고 계신단 말이에요. 저는 이게 도덕적으로 어떻게 이런 일들이 있을 수 있는가. 우선 당장은 서상목 원장께서 본인 스스로가 사실은 주위로부터의 권유가 설령 있었다 하더라도 그것을 회피하는 게 본인을 그동안 경기복지재단 이사장으로 임명시켜준 김문수 지사에 대한 도리라고 생각을 하는데 오히려 오전에 원장님 답변과정에서도 드러났습니다만 정말로 뻔뻔하게 원장님한테 전화를 걸어서 본인을 채용해 줄 것을 부탁하고 저는 정말 있을 수 없는 일이 벌어졌다 이런 생각이 들어서 이분이 실제로 수행하고 있는 연구과제물의 어떤 내용 여부를 떠나가지고 우리 경기도민을 정말로 우롱하는 것 아닌가, 경기도의회 해당상임위에서 서상목 씨에 대한 끊임없는 문제제기를 통해서 그 결과로 물러났다고 보여지는데 반성은커녕 또 다른 자리로 자리를 옮겨서 근무를 하고 있다라고 하는 게 정말 이해가 되지 않습니다. 
</p>
<p style="padding-left:1.2em">  그래서 오늘 행정사무감사가 다 끝나고 나서 저희 위원들과 함께 서상목 씨 처리에 관한 것에 대해서 저희가 심도 깊은 논의를 해볼 생각입니다만 우리 원장께서도, 어쨌든 인사권을 최종적으로 행사하시는 원장께서도 서상목 씨의 향후 진퇴여부에 대해서 깊이 있는 고민을 해주실 것을 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  더불어서 좌승희 원장님 지금 이사장으로 되어 있는데 좌승희 원장님의 역할이 도대체 경기개발연구원에서 어떤 역할인가, 이사회에서 회의를 주재하는 것 외에 아무런 역할이 없는 것 같아요. 저는 그래서 좌승희 원장의 거취문제에 대해서도 마찬가지로 저희 위원들께서 논의를 모아나가겠습니다만 경기개발연구원을 최종적으로 책임지고 계시는 우리 원장께서도 마찬가지로 깊은 고민을 해주실 것을 부탁드리겠습니다. 원장님 어떻습니까, 제 의견에 대해서.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 여기서 답변해도 되겠습니까? 아니면 요 자리에 가서. 
</p>
<p><b>○ 위원장 김현삼 </b> 나오셔서.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 서상목 이사장은 저희들이 여러 가지 방안을 생각해 가지고 저희들로서는 가장 합당한 것이 SIB 연구기간이 5개월입니다. 5개월 동안 충분한 역할을 저희들이 만약에 계약이 있으니까 못한다고 그러면 언제든지 저희들이 재검토를 할 필요도 있고 전화를 걸어서 저한테 자리 부탁한 것은 아니었고요. 전화를 걸어서 그 SIB에 대한 설명을 쭉 했었고.
</p>
<p><b>○ 위원장 김현삼 </b> 그게 그거지 않습니까? 아 다르고 어 다른 얘기죠. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런 거고. 그래서 전에는 자리 이런 생각은 없었는데 그 연구를 진행하다 보니까 연구에 참여하게 됐고 도하고 같이 TF를 만들어가지고. 그래서 저희들이 과업, 보통 초빙연구원이면 과업과 관계없이 1년 계약, 2년 계약 이렇게 하는데 이것은 과업의 시한부로 10월부터 3월 달까지…….
</p>
<p><b>○ 위원장 김현삼 </b> 저는 사실은 서상목 씨한테 하고 싶은 말이 많은데 오늘 이 자리에 안 계셔서 유감입니다만 3선 국회의원을 하시고 보건복지부장관까지도 하신 분이 이렇게 행동하는 것은 경기개발연구원에 대한 이를테면 선배로서의 올바른 태도, 선배로서의 올바른 도리도 아니다, 이렇게 생각을 해요. 본인이 이를테면 어떤 과정을 통해서 경기복지재단 이사장직을 그만두게 됐는지 우리 원장님 잘 아시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아마 총선출마 때문에 나간 걸로 알고 있는데 전 잘 모르겠습니다. 그 자세한 내막은…….
</p>
<p><b>○ 위원장 김현삼 </b> 그것은 원장님께서 알아보시고요. 표면적인 이유야 총선출마였지만 사실은 그 전 과정이 쭉 있었던 거죠. 해당상임위에서 계속 위원장이 말씀을 드렸습니다만 서상목 씨가 이미 경기복지재단 이사장으로 재직 시에 여러 가지 문제가 있었던 거죠. 언론에도 많이 나왔고. 그런 것들이 결국은 누적되고 그러면서 이사장직을 그만뒀다고 보여지는데 참 이해가 안 돼요. 그래서 서상목 씨라고 하시는 분이 여기 초빙연구원 있는 것 그 자체로 저는 경기개발연구원이 그동안 쌓아왔던 어떤 공신력, 이런 것들이 많이 훼손되고 있다 이런 생각을 갖고 있어서 의원으로서 경기개발연구원이 우리 경기도의 정말로 자랑스러운 종합연구기관으로서 그동안 쌓아왔던 공신력을 제대로 지켜내기 위해서라도 서상목 씨에 대한 즉각적인 인사조치가 있어야 된다, 이렇게 보여지고 있고요. 저희 위원들이 별도로 기회를 갖고 종합감사 때 서상목 씨를 저희가 증인으로 채택할 계획을 갖고는 있습니다만 하여튼 원장님께서도 저희 위원들이 서상목 씨에 대해서 지금 어떤 생각을 갖고 있는지에 대해서 잘 염두에 두시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 위원장님 말씀 유념해…….
</p>
<p><b>○ 위원장 김현삼 </b> 좌승희 이사장님도 마찬가지입니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 좌승희 이사장님 같은 경우에 저희 이사장이고 이사장에 대한 거취문제는 여러 이사회에서 여러 가지 얘기기 많이 나와도 함부로 하지 못해가지고 최근에 상당히 언론에서도 다른 기관입니다마는 오르내리고 그러는데 하여간 저희들이 오늘 나온 이야기를 두 분한테 가감없이 전달을 해서 그래서 두 분이 나름대로의 숙고의 시간을 갖도록 하는 기회를 저희들이 드리도록 하겠습니다. 
</p>
<p><b>○ 위원장 김현삼 </b> 그러면 추가질의 순서를 갖도록 하겠습니다. 윤희문 위원님부터 추가질의 하시겠는데요. 우리 위원님들 양해가 되신다면 경기개발연구원 홍순영 원장이 자리에 앉아서 감사를 받을 수 있도록 하셨으면 하는데 어떻습니까? 
</p>
<p style="padding-left:2.4em">    (「좋습니다.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  그러면 홍순영 원장께서는 자리에 앉으셔서 감사에 임해주시기 바랍니다. 임병택위원님 순서는 아닌데.
</p>
<p><b>○ 임병택 위원 </b> 네, 오전에 부탁드린 게 아직 안 와서요. 인사복무규정 제4조의2에 2항입니다. 제가 이걸 달라고 했는데, 마이크로는 하지 않았지만 스텝에게 말씀을 드렸었는데요. “초빙연구원과 관련돼서 자격기준, 계약기간, 근무내역, 처우 등에 관한 사항은 원장이 따로 정한다.”라고 규정되어 있어요. 그래서 따로 정한다, 어떻게 정했는지를 알고 싶어서 준비하시는 분께 부탁을 드렸었는데 아직 안 왔네요. 그래서 이것 한번 챙겨봐 주시길 바라겠습니다.
</p>
<p><b>○ 위원장 김현삼 </b> 그러면 계속해서 윤희문 위원님, 죄송합니다. 잠깐만 권오진 위원님 진행발언 간단하게 해주시기 바랍니다.
</p>
<p><b>○ 권오진 위원 </b> 자료 좀 요청하겠습니다. 제가 기금에 대해서 보려고 그러니까 기금관리위원회가 있더라고요, 보직에. 기금관리위원회 현재 위원들 명단하고요. 경력하고 그다음에 활동내용에 대해서 있으면 주십시오. 기금관리위원회요. 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 윤희문 위원님 계속 질의하도록 하겠습니다. 
</p>
<p><b>○ 윤희문 위원 </b> 이천 출신 윤희문 위원입니다. 질의에 앞서 자료 좀 요청하겠습니다. 한강수계 수질오염총량관리 기본계획 수립 용역해서 연구 책임자가 송미영 박사님 같은데 이 부분하고 그다음에 한강수계 수질오염총량관리 기본계획안 쟁점과 대응방향해서 이것도 송미영 책임연구원이 아마 하신 것 같습니다. 그 자료를 주셨으면 좋겠습니다. 아마 제가 받았을 텐데 하도 연구원에서 많이 보내주니까 어디 있는지 아마 모르는 것 같아요, 제가. 꼭 좀 참고로 제가 볼 사안이 있어서 저한테 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  제가 자료를 요구한 것은 세 가지를 했습니다. 그런데 세 가지 이외에 또 경기개발연구원과 관련됐던 사항을 하나만 더 추가로 여쭙도록 이렇게 하겠습니다. 15쪽에  경기도 및 시군으로부터 의뢰받은 연구용역현황하고 자료가 있는데, 17쪽을 한번 봐주시기 바랍니다. 17쪽을 보시면 2009년까지야 그렇겠습니다만 최근 2010년도, 11년, 12년 보면 연구의뢰 받은 연구용역현황이 계속 줄어들었어요. 그죠? 경기도에서 보내온 것도 그렇고 예산액도 줄었고 시군에서 준 것도 줄었고. 이 부분은 어떻게 보면 과업이 없기 때문에 도나 시군에서 그럴 수 있다라고 내가 긍정적으로 생각하고 싶은데 또 여기를 보면 우리 경기개발연구원에 갖다가 의뢰했더니 시원찮단 말이야, 자료가. 그러니까 다른 데다가 맡겨버리는 거야. 그런데 이게 왜 꼭 필요하느냐면 시군에도 도하고 경기개발연구원하고 업무가 경기도 걸 하기 때문에 연계가 돼요. 저는 시군 것 전부 경기개발연구원에 의뢰를 줘야 된다라고 하는 것이 제 소신입니다. 그래서 전체 계획이, 경기도가 발전할 수 있는 계획이, 경기도 계획과 시군 계획이 같이 연계해 나가야 된다고 보고 또 국가 계획도 마찬가지이고요. 그래서 경기개발연구원의 역할이 아주 중요하다고 생각하거든요. 그런데 사업 건수가 이렇게 줄은 이유가 뭡니까? 원장님, 이거에 대해서 한 번 분석을 해보셨어요? 이게 많이 들어와야지 개발연구원 수익도 늘고 권위도 있는 것 아니겠어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 말씀드리겠습니다. 일단 저희들이 여기 2012년에 한 것은 9월 말까지 실적이기 때문에 3개월 더 되면 더 올라간다고 보고요. 그래서 2010년하고 11년, 10년보다 조금 올라갔죠. 그래서 올해도 3개월을 더 하면 그렇게 낮아질 것 같진 않습니다.
</p>
