<p><b>○ 윤희문 위원 </b> 경제부분 아닙니까? 창조경제는 경제부분 아니에요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아닙니다. 창조경제라는 것이 문화관광을 다 포함한, 왜냐하면 새로운 경제라는 것이 옛날에 어떤 개발연대식으로 이렇게 만들어내고 제조업하고 건설업하고 이러는 게 아니라 새로운 트렌드는 문화라든지 관광이라든지 기타 서비스라든지 이런 쪽이 오히려 새로운 어떤 창조경제 분야다 이래 가지고 이름을 창조경제로 해서 그런 거를 총괄하고 총할하고 연구하라고 해 가지고 그런 부서를 만든 겁니다. 그러니까 더 확대 개편을 한 겁니다.
</p>
<p><b>○ 윤희문 위원 </b> 폭을 넓혀놓은 거죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 그래서 저희들이 이제…….
</p>
<p><b>○ 윤희문 위원 </b> 폭을 넓혀놓은 거지 어떻게 더 확대, 문화관광을 더 확대해서 해 놨다 이런 얘깁니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다.
</p>
<p><b>○ 윤희문 위원 </b> 그렇지 않죠. 그게 어떻게 그렇습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니, 그러니까 저희들이 작년에 문화관광부가 있었고…….
</p>
<p><b>○ 윤희문 위원 </b> 폭을 넓혀놔서 그 부분에 문화관광이 있는 거죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 문화관광을 담당하던 부장이 그 업무를 총괄해서 부장을 맡아가지고 지금 하고 있습니다.
</p>
<p><b>○ 윤희문 위원 </b> 2012년에 얼마나 했어요? 그 부분의 연구 이런 부분이 얼마나 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 간단히 말씀드리면 에코벨트라든지, 공공체육시설 활용도라든지, 운악산 권역 관광 활성화라든지, 또 기타 호텔, 파주도시라든지 여러 가지가 있습니다.
</p>
<p><b>○ 윤희문 위원 </b> 내가 보기에는 여기 48쪽에 차이나파워, 경기도의 대응방안 이것뿐이 없네요. 지금 여러 가지 나열을 하시는데 없네요. 여하튼 제가 말씀드리고자 하는 것은 강원도의 그런 것 같이 우리도 이 부분에 대해서 소홀하기 쉬운 것을 제가 다시 한 번 말씀드리는 겁니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 윤희문 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 윤희문 위원님 수고하셨습니다. 다음은 신현석 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 신현석 위원 </b> 파주 출신 신현석 위원입니다. 현장 밀착형 복지, 교통 및 사회환경시스템을 구상하시고 동북아 미래를 선도하는 경기도의 싱크탱크 역할을 하는 GRI 원장님과 여러 관계공무원들에게 감사의 말씀을 드리면서 질의하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  원장님, 올해 경기개발원이 수행한 연구사업 중 실제 정책에 반영된 사례가 있을 겁니다. 어떤 게 있는지 말씀해 주시기에 앞서서 본 위원도 대학교에서 학생들을 가르치고 있는데 학문을 연구하는 것의 가장 큰 맹점은 뭐냐면 수요자 중심, 실질적으로 생활에 적응되지 않는 학문이 많다는 겁니다. 다시 말해서 학문을 위한 학문이 너무 많이 있는데 우리 경기개발연구원이 정말 실제 정책에 반영된 사례가 어떤 것이 있는지 궁금하고요.
</p>
<p style="padding-left:1.2em">  두 번째 저도 좀 이것에 대해서 관심을 상당히 많이 갖고 있는데 본 위원도 보건복지공보위원이었습니다. 그다음 기획위원회에서, 여러 상임위원회 활동을 하고 있는데 제가 발의한 조례들이 어떻게 도민들하고 연관이 있는지 상당히 발의하면서도 많은 관심거리였습니다. 마찬가지로 제가 경기개발연구원에서 답을 얻고 싶은데 오늘 경기개발연구원이 수행한 연구사업 중에 실제 정책에 반영된 사례가 있는지, 있다면 그 피드백을 하고 계시는지 한번 듣고 싶습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 다양하게 도하고 같이 일도 하고 정책에 반영된 사례가 있고 또 수요자 중심으로 정책연구를 하자라는 것은 계속 제 취임 이후로 때가 될 때마다 반복적으로 연구원들한테 제가 부탁드리는 말씀이고요. 먼저 반영된 사례 보면 2020경기도종합발전계획 같은 경우는 법정종합계획으로 경기도의 미래발전 제시하였고 중장기 시책사업 추진과 시군의 상위 계획으로 지금 실제적으로 활용을 하고 있는 사항이고요. 또 예를 들어서 국가발전전략 과제의 기본구상 같은 경우는 경기도의 미래 먹거리, 복지, 경제, 글로벌 메가시티리즌, 통일한국 등 5대 목표하고 100대 정책과제를 제시했고 또 지난주에 저희들이 또 4월 총선 때 경기도하고 밀접하게 연구를 해서 4월 총선에 공약으로 정당에 14건, 국회의원 80건 공약채택에 기여도 했고요. 또 DMZ경제특구 구상 이런 것은 경기북부발전전략을 저희들이 제시해서 경기북부발전에 상당히 도움이 됐고 또 환경복지, 또 물 산업 육성, 특히 경기도 순환버스 도입 같은 경우는 광역버스를 굉장히 많이 사람들이 필요로 하는데 그 광역버스 차내 혼잡도 개선에 상당히 기여를 했고 또 주민의 친화적인 광역대중교통개선 쪽에서도, 저희들 교통부 쪽에서도 상당히 일을 해 가지고 경기도 주민들이 직접 활용하는 버스문제 이런 거에도 저희들이 나름대로 조그마한 기여를 하고 있다 이렇게 말씀드리겠습니다. 생각나는 것만 몇 개 대표적인 것 말씀드렸습니다.
</p>
<p><b>○ 신현석 위원 </b> 실제 정책에 반영된 사례가 많군요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 신현석 위원 </b> 그것에 대한 피드백을 해서 다음에 연구할 때는 꼭 그것이 반영되는 그런 정책들을 내놓을 수 있기를 좀 부탁드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 신현석 위원 </b> 본 위원이 18페이지 업무보고 자료를 봤습니다. 거기에 보면 시군순회토론회 개최가 있는데, 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 신현석 위원 </b> 본 토론회 개최 현황과 성과를 좀 구체적으로 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일단 지금 4차, 올해 네 번 했고요. 한 번 앞으로 더 할 계획이고, 특히 시군 쪽하고 저희들이 나름대로 소통 이런 쪽이 상대적으로 부족하다고 느껴서 가장 쉬운 방법은 직접 다니면서 시군 의원들, 또 시군 시장ㆍ군수분들 또 여러 가지 도의원들하고 같이 시군의 현안에 대해서 지금 논의하자는 그런 취지에서 만들었고요. 일단 1차로는 경기북부의 새로운 발전 패러다임 해 가지고 북부권에서 한 번 했었고요. 그때 의정부에서 했습니다. 그리고 ‘경기도 이제는 서해안 시대다.’ 그래 가지고 서해안권 쪽으로 해 가지고 평택에서 저희들이 했었고, 세 번째는 지역 환경과 지역발전의 조화 그래서 양평에서 한 번 또 열었었고 최근에는 지방분권 해서, 대통령 선거를 앞두고서 지방자치 확대와 강화 이런 쪽으로 해서 저희들이 수원에서 열어가지고 경기도의 동서남북 4권역을 나름대로 나눠서 한 번씩 열었고요. 올해 가기 전에 한 번 더 이거를 열 계획이고 내년에도 이 반응하고, 이게 상당히 성과가 좋아가지고요, 또 평가도 좋고 이래 가지고 계속 확대할 생각을 가지고 있습니다.
</p>
<p><b>○ 신현석 위원 </b> 본 위원은 경기도 정책 내지 모든 정책은 스피드가 아니라 방향으로 저는 생각하고 있습니다. 그 방향이 실제 정책에 반영되고 그다음에 실질적으로 소통하고 시의원, 도의원을 포함해서 우리 도민들과 소통하는 그런 순회토론회가 방향을 잘 잡고 진행하셨다고 생각하는데 마찬가지로 소통을 좀 더 많이 늘려서 도민들과 소통하면서 정책이 반영됐으면 좋겠다고 생각했습니다.
</p>
<p style="padding-left:1.2em">  원장님, 제가 매주 발간하는 이슈&진단 보고서를 잘 보고 있습니다. 이슈&진단의 발간 현황하고 문제점하고 성과가 있다면 어떤 게 있는지 한번 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 작년부터 제가 취임한 이후에 매주 나오는 다양한 보고서들이 있어서 그것을 통폐합해 가지고 이슈&진단이라는 보고서를 만들었습니다. 현재까지 70호가 지금 발간되고 있고요. 경기도의 주요현안에 대해 새로운 논점과 아이디어를 가지고 시의성 있는 이슈를 연구주제로 선정해 가지고 여러 정책제안이나 정책아이디어를 제시함으로써 GRI가 경기도 정책의 방향 설정과 이런 쪽에 도움을 주고 있고 연구원의 위상 강화에도 저희들은 크게 기여하고 있다고 생각을 합니다. 특히 이것은 매주 연구원들의 전반적인, 소위 말하는 우리 연구원 전체의 역량을 모아가지고 내는 보고서이고 그 가독성과 시의성 이런 쪽으로 상당히 많은 평가를 받고 있고요, 나름대로. 예를 들어서 주제 같은 거를 보면 사회적 경제라든지 환경복지, 여가문화산업, 또 새로운 사회화 대응, 지역의 경쟁력, 지방분권, DMZ, 한국형 복지모델, 귀농, 귀촌 굉장히 다양한 분야의 시의성 있는 주제를 잡아서 문제를 지금 던지는 그러한 이슈&진단 보고서입니다. 그래서 20페이지 정도 되는데요. 일단은 문제제기적 성격이 상당히 강하고요. 그래서 그런 문제제기가 돼 가지고 사람들한테 상당히 많은 관심과 도라든지 이런 쪽에 있으면 더 깊은 연구를 통해 가지고 그것이 정책으로 연결될 수 있는 그러한 다양한 연구를 하고 있는 우리 연구원의 대표적인 발간물이라고 볼 수 있습니다.
</p>
<p><b>○ 신현석 위원 </b> 보니까 사회경제 패러다임, 시시각각으로 변하는 패러다임에 대해서 정책을 적극적으로, 주도적으로 대응하는 것 같아서 본 위원이 상당히 좋게 생각하고 있었습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다.
</p>
<p><b>○ 신현석 위원 </b> 본 위원이 업무보고 자료 11페이지에 보니까 경기도 협동조합의 활성화 방안 부분이 있더라고요. 경기도 협동조합의 활성화를 위해서 지금까지 어떤 기여를 GRI에서 했는지 한번 말씀해 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 협동조합법이 작년 12월 달에 통과가 됐고 그리고 올해 12월 달에 이게 시행이 되고 있었는데 올 초 보니깐 거기에 대한 준비나 생각들이 전혀 없더라고요. 그래서 저희들이 그거를 이슈를 적극 꺼내서 그것도 공무원들에게 그 필요성과 의미 이런 거를 전달을 지금 하고 있고요. 그래서 지금 도하고도 같이 포럼 같은 걸 만들어가지고 같이 지금 연구도 하고 있고 또 도에서도 그걸 적극적으로 추진하는 그런 부서 사람들도 배정을 해서 지금 12월 달에 정식 발효가 되는 협동조합에 대해 도가 준비를 하는데 저희들이 크게 일조를 했다고 생각을 하고 있습니다. 그래서 앞으로도 이게 사회적 경제에 있어서의 새로운 대안 중에 하나가 될 것 같아서 저희들이 지속적으로 이 일을 하고 있고 지금 도로부터도 특별용역을 받아서 지금 작업을 수행하고 있는 그런 상황입니다.
</p>
<p><b>○ 신현석 위원 </b> 잘 들었습니다. 원장님, 업무보고 자료와 경기개발연구원이 여러 가지 정책들을 낸 것을 통해서 보면 그간 경기개발연구원이 SNS 최우수 수상 등 대내외 소통을 위해 다각적으로 노력해 온 것으로 본 위원은 판단됩니다. 그러나 도민과 시군을 대상으로 현장연구는 다소 미흡하지 않았나 본 위원은 판단하고 있는데 현장연구 활성화 계획이 있으시면 원장님이 말씀해 주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 저희들이 여러 가지 다양한 SNS도구를 이용하고 또 도하고도 밀접하게 매주 정책협의회나 토론회 또는 발표회도 갖고 있는데 지금 위원님께서 말씀하신 시군까지 그러한 노력이 다소 미흡한 것도 사실입니다. 그래서 저희가 올해부터 일단 1차적으로 시군토론회를 개최하였고 앞으로는 저희들 연구원에 연구위원급 이상이 50명 가까이 되는데 저희들이 시군마다 한 사람당 하나씩 시군을 맡겨서 지속적으로 시군에 대한 현안이라든지 그런 것을 할당제를 통해서 한번, 우리가 전체적으로 뭘 하자라고 하는 것이 잘 안 되는 것 같아서 아예 연구위원들을 할당제를 하는 방법도 있을 것 같고요. 저희들이 그 생각을 해보고 있고 그리고 저희들이 자치의정 연구를 하는 부서가 지금 있거든요. 의회하고 소위 경기도의 전반적인 자치의정 연구를 하는 데가 있는데 그쪽 부서 연구원들로 하여금 소위 시군에 대한 정책수요라든지 이런 것을 주기적으로 듣고 또 저희들은 사실 많이 안 알려져 있지만 시군에서 하는 다양한 연구자문위원회라든지 평가 이런 회의들이 많거든요. 저희 연구원들이 거기에 적극적으로 참여하고 있고 갈 때마다 그 양반들하고 같이 앉아서 소위 말해서 시군 현안에 대해서 토론하고 있는데 또 정책수요를 입력을 받고 있는데 그럼에도 불구하고 아무래도 저희들이 도 연구위원이다 보니까 시군에 대해 느끼는 체감, 접촉이 상대적으로 작게 느껴질 수가 있어서 그 부분에 대해서는 저희가 다각도로 노력하고 있다고 말씀드리겠습니다. 
</p>
<p><b>○ 신현석 위원 </b> 필터링 되고 모니터링 되고 있는 것은 다행이라고 생각합니다. 원장님, 마지막으로 질문하겠습니다. 행감 시작 전에 우리 위원장님께서 참 좋은 말씀을 해주셨습니다. 서상목 선임연구원에 대해 말씀해 주셨는데 서상목 연구원은 본 위원이 알기로는, 저도 전반기에 보건복지위에 있었기 때문에 너무나 잘 알고 있습니다. 그래서 제가 한번 서상목 그분에 대해서 네이버하고 다음에 들어가서 쳐봤습니다. 저번에 잘 나가실 때는 다음하고 네이버에서 검색순위가 1위였는데 다음에서도 상당히 많이 맨 끝에, 구석진 곳에 서상목 이렇게 올라와 있더라고요. 네이버에서도 맨 밑에 하나 올라가 있었는데 상당히 안타까웠습니다. 왜 안타까웠느냐면 그분이 보건복지 분야 쪽에는 선구적 역할을 상당히 많이 했습니다. 그럼에도 불구하고 언론에 오르내렸던 것 또한 사실입니다. 그분이 어떻게 그분의 노하우, 지식을 우리 GRI에 적용할 수 있으면 너무나 금상첨화인데 그러한 것들이 필터링만 됐다면 아마 보건복지 쪽에서는 경기도 GRI에서 세계적인 선도를 할 수 있는 큰일을 하실 분이다라고 생각을 합니다. 그건 우리 원장님이 잘 판단해 주시고 특히 우리 위원장님께서 말씀해 주신 것도 피드백을 하시면서 잘 판단해 주셨으면 감사하고요. 누가 뭐래도 저는 서상목 선임연구위원이 보건복지부에서는 선구자적인 지식을 가지고 있고 그거에 대한 노하우가 있다고 생각합니다. 
