<p><b>○ 경기개발연구원장 홍순영 </b> 성과급은 어느 조직이든지 간에 성과를 되게 싫어합니다. 평가를 받는다는 걸. A, B, C, D등급을. 그래서 연구원들도 항상 될 수 있으면 격차를 적게 해서 평균적인 걸 하도록 하자라는 것이, 저희들이 의견을 항상 수렴, 어느 조직이든지 그게 나오는데 제가 구태여 여기에서 길들이기를 할 이유도 없는 거기 때문에, 저희들이 성과급을 하는 것은, 저의 입장에서는 연구원들한테 가장 좋은 소리를 들으면 개인적으로 인기도 좋고 좋은데 그러나 제 임무 중에 하나가 연구원의 성과를 올리는 거에……. 
