<p><b>○ 경기개발연구원장 홍순영 </b> 만약에 그런 부분이 있다면 제가 계속 노력할 거고요. 될 수 있으면 공정성을 지키도록 하고 그리고 지금 위원님께서 말씀하신 경기개발원의 독립성과 자율성 이것을 제가 계속 지키려고 노력을 하겠습니다. 외부의 압력이라든지 이런 것도 제가 웬만하면 철저하게 막아서 연구원의 공정성 이런 것을 지키려고 계속 노력을 하겠습니다. 
