<p style="padding-left:1.2em">  하나 더 말씀드리겠습니다. 우리 공공부문의 비정규직의 정규직화는 우리 의회에서도 무척 바라는 사안입니다. 비정규직에서 정규직화한 현황을 좀 봤는데 그렇게 많지는 않더라고요. 쉽지 않은 의제지요?  
