<p><b>○ 경기개발연구원장 홍순영 </b> 네, 한 분은 무기계약직으로 저희가 전환을 시켰고 또 한 분은 저희들이 정규직으로 전환을 했고요. 그리고 한 친구는 외국으로 유학 간다고 해서 나갔고 그리고 나머지 몇 사람들은 아직 2년이 안 됐고 그리고 연구원들은 연구원의 성격상 전문직이나 또는 연구업무에 직접 관여하는 연구원들은 2년 이상 저희들이 원하면 할 수 있기 때문에 저희들이 일반 통상적으로 얘기하는 비정규직 이쪽은 저희 연구원하고는 지금 거리가 있는데 상대적으로 저희들 위촉연구원들, 석사급 연구원들이 계약직으로 되어 있기 때문에 외부에서 볼 때는 비정규직이 많은 걸로 그렇게 나타나고 있습니다. 
