<p><b>○ 임병택 위원 </b> 하나만 여쭤보지요. 지금 현황으로는 계약직원이 76명으로 되어 계시더라고요. 그리고 특별채용 규정을 보면 특별채용은 업무상 불가피한 사유가 있거나 소수의 인력을 긴급히 충원, 불가피와 긴급성이라는 양대 요건이 있더라고요. 우리 행정직에서 관리직이 되신 2011년 3월 9일 계약직 3년 근무하시고 특별채용으로 정규직이 되셨던데 특별한 사유가 있으십니까? 
