<p><b>○ 경기개발연구원장 홍순영 </b> 면접은 저희들 절차에 따라서, 저는 관여 안 했습니다, 면접 같은 경우는. 아마 절차에 따라서 뽑았을 겁니다. 
</p>
<p><b>○ 임병택 위원 </b> 저는 조직을 통할하시는 분의 가장 중요한 잣대는 공정이라는 잣대이고, 비정규직이 정규직화되는 것에 대해서는 백 번 동의합니다. 그런데 자료들을 쭉 보면 3년 만에 되셨다라는데 계약직의 임용현황 등을 보면 정말 오래된 분들이 많으세요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 어떤 분을 말씀하시는 겁니까? 
</p>
<p><b>○ 임병택 위원 </b> 계약기간이 7∼8년 되시는 분들도 많으시고.
