<p><b>○ 경기개발연구원장 홍순영 </b> 7∼8년 된 분들은 저희들이 다 정규직화 했다고 제가 파악하고 있는데.
</p>
<p><b>○ 임병택 위원 </b> 기획조정실에 권진경이라는 분도 2006년도 계약이 되셨고. 
