<p><b>○ 경기개발연구원장 홍순영 </b> 외국으로 유학 간다고 해서, 무기계약직 전환을 저희들이 제안을 했는데 김혜경 씨 같은 경우에는 정규직 전환을 자기가 마다하고 유학을 간다고 해 가지고 그것은 본인의 선택이기 때문에……. 
