<p><b>○ 위원장 김현삼 </b> 임병택 위원님 수고하셨습니다. 다음엔 배수문 위원님 질의하여 주시기 바랍니다. 
</p>
<p><b>○ 배수문 위원 </b> 배수문 위원입니다. 질의하도록 하겠습니다. SNS를 통한 소통을 강화해서 제2회 SNS 어워드 최우수상을 수상하셨네요, 교육기관 연구소 부문?  
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 배수문 위원 </b> 축하드리면서 소통을 위한 이런 부분들은 더 강조되어야 되겠다라는 얘기를 드립니다. 한 가지 더 얘기하자면 그럼에도 불구하고 GRI 홈페이지 일반 언론기사 건 아니면 자료 건들을 클릭해봤습니다. 그런데 최고 많이 본 자료 클릭 건수가 보통 2,000번 정도로 꽤 많이 본 거고요. 평균 1,000건을 넘어가는 게 많지 않습니다. 아시지요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 
</p>
<p><b>○ 배수문 위원 </b> 물론 자료를 배포하는 것도 필요하지만 요즘은 페이퍼워크보다는 인터넷으로 보는 것들을 훨씬 더 중요하게 생각하고 있습니다. 경기도 산하의 공무원만 해도 충분히 그 숫자는 넘길 수 있고요. 제가 seri.org를 들어가 보니까 확실히 많이 본 조회 수는 4만 건, 5만 건 정도 돼요. 물론 규모의 차이가 있겠습니다만 홈페이지에 볼거리가 많다는 얘기예요. 홈페이지에 볼 만한 건들을 좀 더 집중화할 수 있도록 했으면 좋겠다. 그리고 자료를 보고 난 다음에 본인이 자료 본 건이 올라가게 되면 그거에 따른 인센티브도 주는 게 아마 LG연구원인가요, 거기 보면 본인이 본 자료, 나중에 보면 얼만큼 봤는지. 현대경제연구소가 그렇군요. 본인이 본 자료가 딱 목록화돼 있어요. 나중에 보기 편하게. 개인이 회원으로 등록하게 되면. 그런 건 쉽게 만들 수 있는 것 같거든요. 그래서 본인이 본 자료라든가 관심 있는 보고서들에 대해서 쫓아갈 수 있게끔 되어 있고요. 그런 것들은 찾아봐야 되겠다라는 생각이 듭니다. 특히 홈페이지에 관한 것들은 일반 민간 쪽에서 구성하고 있는 홈페이지는 많이 차용할 필요가 있다. 그래서 광역 단위의 연구원에서 만들어 놓은 홈페이지 중에서는 그래도 경기개발연구원이 상당히 잘되어 있습니다. 그거에 대해서는 감사를 드리는데 거기를 볼 게 아니라 경기도라면 일반 민간인이 운영하는 연구소 홈페이지 이상의 능가하는 것들을 좀 더 갖출 수 있지 않을까 생각을 합니다. 왜냐하면 비용을 내고 보는 게 아니고 또 여기에 접할 수 있는 사람들이 경기도민이다라고 생각했으면 좋겠고요. 부산 홈페이지를 보니까 조직도에 어떻게 나와 있느냐면 가장 위에 원장님, 이사장님이 되어 있는 게 아니라 그 위에 부산시민으로 적어놓고 있습니다. 아마 이게 시민들을 상대로 부산연구원이 보여줄 수 있는 마음가짐이지 않을까라는 생각이 들어요. 오전에 지적했던 그런 건들도 가장 위에 도민이 있다고 생각한다면 그런 것들에 대한 행정적인 처리는 원장님의 명예를 걸고라도 막았어야 된다라는 생각을 본 위원은 하게 되었습니다. 동의하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 동의합니다.
</p>
<p><b>○ 배수문 위원 </b> 꼭 그렇게 해주시기를 당부드립니다. 그다음에 자료를 보니까요, 이슈&진단이 주 1회씩 나오는데 그러다 보니까 이건들이 매번 뉴스화되더라고요. 그래서 보도자료 보니까, 경기도 언론 보니까 평균 GRI가 다뤄지는 건이 4.5회예요. 그러다 보니까 언론을 통해서 GRI가 알려지는 것은 참 잘하고 있다라는 부분은 더 강조해야 된다. 이건 다른 연구원에 비해 훨씬 잘하고 있습니다. 그런 소통은 훨씬 더 잘하고 있는데 그게 일부 좌승희 이사장님처럼 다른 엉뚱한 얘기를 도배할 수 있는 면을 또 제공할 수 있거든요. 그러니까 중립적인 입장에서 GRI의 지향하는 바가 도민만을 바라보고 지향하는 바가 실렸으면 좋겠다라는 것을 얘기하고 싶습니다. 
</p>
<p style="padding-left:1.2em">  그리고 정책제안과 정책이슈를 보니까 2011년에 비하면 상당히 많은 건 아니지만 그래도 일부 적었어요. 앞으로 남은 기간 동안 2011년에 비해서 넘어갈 수 있을 것 같습니까? 정책제안이나 정책이슈 발행 건이. 지금 10회도 있고 정책제안은 13회도 있거든요. 그런데 작년에 19회, 18회로 지금 12월 달까지 돼도 이 숫자를 채울지가 의문입니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 9월 30일 기준이고 3개월이기 때문에 향후에는 좀 올라가리라고 저희들이 생각을 하고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 알겠습니다. 그다음에 간행물 만들어서 유료로 하고 있는 게 있고 무료로 배포하고 있는 게 있지요? 정책은 무료로 하고 있고 일반적으로 봐야 될 기본적인 것들은 1만 3,000원에서 1만 1,000원 정도로 유료로 하고 있습니다. 그래서 책자 만든 게 한 700만 원 정도의 수익을 얻고 있네요? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 이걸 지금 보다 더, 판매처가 지금 오프라인에서 7개, 온라인에서 세 군데 이 정도면 충분하다고 보십니까? 이걸 조금 더 확대할 수 있는 방안은 없나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 이 책자에 대해서 약간 다른 생각이 좀 있는데…….
</p>
<p><b>○ 배수문 위원 </b> 다른 생각을 가지고 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 알겠습니다. 그러면 이 건에 대해서는 크게 염려 안 해도 되겠네요? 그러면 더 인터넷을 통해서 도민과 소통한다든가 연구된 자료들이 그저 연구된 걸로 끝나는 게 아니라 누군가라도 봐서 정책에 반영될 수 있게끔 더 많은 알림을 책임져야 한다 이렇게 생각합니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 저희들이 인포그래픽스를 도입해서 하려고 하고 있고 보고서를 이제는 종이보다는 온라인이라든지 이런 것을 통해서 직접 보내려고 하고 다양한 생각들을 하고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 홈페이지 보니까 도서관이 개설되어 있어요. 보니까 매년 신규 구입한 책이 40권밖에 안 돼요. 비용이 없어서 그런가, 아니면 자료로 해서 볼 수 있게끔 오픈이 되어 있는 겁니까? 일반적으로 오프라인에서 구입해서 비치돼서 연구원들이 보게끔 만든 도서관 운영인 것 같은데…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그건 제가 좀 더 살펴보고요.
</p>
<p><b>○ 배수문 위원 </b> 40권밖에 안 된다는 건 연구원들에 대한 지원이 너무…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 확대하겠습니다.
</p>
<p><b>○ 배수문 위원 </b> 자료를 더 많이 얻을 수 있는 방법은 최대한 강구해야 되겠지요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 한 달에도 저희들이 수백 권씩 지금 하고 있는데.
</p>
<p><b>○ 배수문 위원 </b> 그다음에 올해 연구 접수를 보니까 5건이에요. 작년에 7건이었는데 이걸 보면서 세리 홈피를 보니까 늘 일상적으로 연구논문을 접수받고 있더라고요. 아시지요, 그런 제도 있는 거?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 세리에 대해서 굉장히 잘 알고 있습니다. 그런데 거기도 잘하는 것도 있고 못하는 것도 있고 굉장히 마케팅을 잘하는 데입니다.
</p>
<p><b>○ 배수문 위원 </b> 워낙 그쪽에서 임원 선까지 가셔서 이쪽으로 오셨기 때문에 훨씬 잘할 수 있는데.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 잘하는 것도 굉장히 많거든요, 세리보다도.
</p>
<p><b>○ 배수문 위원 </b> 그쪽에서 이쪽으로 접목할 수 있는 건 18개월 되셨으니까 충분히 하셨다고 보는데 공공성을 담보로 하고 있는 연구논문들에 대한 권위 있는 시장성 같은 거를 제대로 했으면 좋겠다. 이런 것들은 기획 쪽으로 했으면 좋겠고요. 그래서 접수되는, 그다음에 정책을 연구한다든가 아니면 국가를 경영하는 데 있어서의 연구자료들의 핵심역할을 GRI가 해줬으면 좋겠다. 그래서 경기개발연구원에서 인정하는 논문들이라면 어느 곳에서도 퀄리티가 떨어지지 않는 것들을 발굴해 내고, 그럴 만한 것들을 발굴해 내는 역할이 있다라고 전 봅니다. 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 좋으신 말씀해 주셨는데 그래서 저희들도 일반인들한테도 정책제안이나 어떤 연구논문이나 이런 것도 나름대로의 이벤트를 해서, 이벤트라는 게 다른 게 아니고 채택이 된다든지 그러면 소정의 상품을 준다든지 이런 것을 통해가지고 소위 말하는 일반인들로부터도 정책제안 같은 것을 받을 노력을 하겠습니다. 하고 저희들 연구보고서도 사람들한테 할 때 피드백 같은 것을 하거든요. 그럴 때 좋은 피드백 같은 게 있으면 저희들이 적극적으로 받아들이고 이렇게…….
</p>
<p><b>○ 배수문 위원 </b> 알겠습니다. 
</p>
