<p><b>○ 경기개발연구원장 홍순영 </b> 전 잘못된 것이라고 생각합니다. 
</p>
<p><b>○ 권오진 위원 </b> 알았습니다. 그다음에 제가 아까 제기드리다가, 사실 주제설정 부분에 있어서 보면 말이죠. 지금 하나 의문되는 것이 있는데 저희가 국방부 같은 데서도 용역을 받나요, 용역을? 
