<p><b>○ 권오진 위원 </b> 여기 917쪽에 보면 말이죠. 이런 게 있어요. 민군정책팀의 연구가 현역복무병 급여개선 및 보상방안에 대해서 했는데 이게 도대체가 현역복무병 급여개선에 대해서 왜 여기서 연구를 하죠? 917페이지 맨 아래쪽에 있지 않습니까? 이게 뭔지 모르겠어요. 실제로 북부 쪽에서 이런 것을 요청했을 리도 없고 사실 수원비상활주로 고도제한 구제완화 방안 등은 이런 걸 해서 제시해야 되기 때문에 맞는 것이지만 이런 내용들이 사실 많아요. 군 평생교육 활성화 지원방안, 왜 지원합니까, 이걸 갖다가? 이건 군에서 할 것이지.
