<p><b>○ 경기개발연구원장 홍순영 </b> 뭔가 이유가 있었을 겁니다. 
</p>
<p><b>○ 권오진 위원 </b> 민관군에 대해서 연결고리를 할 수 있는 그걸 연구해야 되는 것이 여기 있는 일곱 분들이 할 일인데 진짜로 저희 의원들이 지역에서 볼 때는 우리가 민에 대해서 요구할 사항이 많이 있거든요, 민들이 군에 대해서. 이런 내용을 잘 모르고서 실질적으로 우리 말하는 도에서 요청할 사항이라든지 이런 걸 할 수 있다면 민이 너무 소외된 것이 아니겠는가 생각이 들어서 이들이 역할을 제대로 하려면 정말로 민의 입장에서, 사실은 군부대들이 많지 않아요, 우리 경기도에 넓이는 많지만. 그런 데 가서 진짜 뭐가 필요한 것인가를 한번 알아보면 좋겠다는 것을 말씀드립니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 대부분이 군…….
</p>
<p><b>○ 권오진 위원 </b> 그다음에 제가 또 한 말씀드리는 것은 아까도 다른 위원님이 말씀드린 것 같은데 평가 같은 거라든지 또 연구내용 자체의 신뢰가 중요한 것인데 아까 말씀대로 의정부경전철이 3만 5,000명 탄다고 얘기했는데 1만 명도 안 타기 때문에 문제되고 있다고 그랬잖아요, 지금. 그런데 공기업 경영평가를 요새 했습니다. 하고 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 도하고 같이 하고 있습니다. 
</p>
<p><b>○ 권오진 위원 </b> 경기도ㆍ시군 산하 지방공기업 경영평가에서 10년, 11년 했는데 여기서 보게 되니까 2010년도에 용인지방공사가 우수로 나와 있어요. 그게 그때부터 터져서 난리 나갖고 지금 검찰청 검사받고 있고 난리입니다, 사장이 관두고. 이런 결과가 나올 수 있는 자체가 또 그 한쪽에 시설관리공단이 꼴찌로 미흡하니까 또 그걸 합쳐버렸어요, 솔직히 말해서. 이런 문제들이 실제로 경영평가가 기준이 잘못됐으면, 기준도 여기서 만들었을 것이고 이런 내용들을 가지고 어떻게 신뢰를 경발연이 가질 수 있겠는가 하는 생각이 드는 겁니다. 우리가 연구라고 하는 것에 대해서는 예측은 실수도 할 수 있습니다, 예측은. 그런데 있는 것을 가지고서 평가하는 것을 봤을 때 우수라는 평가를 가지고 그들이 상금 받아가게 하고 폼 잡았던 것을 갖다가 지금 사장이 관두고 본부장이 관두고 난리 났어요, 지금. 이런 내용들이 이미 그때부터 예측돼 있던 부분이다, 이거죠. 그러니까 단순히 껍데기 평가를 가지고 상을 주는 것은 잘못된 것이라는 것을 말씀드리고. 또 한 가지 부분에 있어서는 아까 말씀드린 그런 부분입니다. 
</p>
<p style="padding-left:1.2em">  사실 저 개인의 입장에서는 아까 얘기 나왔던 것이 서상목 연구원하고 좌승희 이사장 부분에 있어서는 솔직히 그들이 있어 가지고는 경기개발연구원이 움직일 수 없다. 더 나아가서 경기도에서도 상당히 문제가 있다라는 생각을 말씀드리는 겁니다. 저는 서상목 연구원이 복지재단 이사장을 할 때에 이런 패턴을 봤어요. 어떤 조직을 하려고 해놓고 나서 사람 하나 이렇게 집어넣어요. 그래놓고 그 조직을 떼어놓으면 거기다가 그 사람을 앉히는 겁니다, 자리 갖다가. 우려가 되고 있는 것은 복지분야를 연구하는데 사회적 금융회사라는 부분이 제가 보니까 생활형 복지패러다임과 사회적금융에 대해서 이미 보고서 나와 있어요, 개발연구원에서. 다 됐는데 여기 유명하신 분들이 많이, 이상훈 박사 다 써있더라고요. 그런데 이런 것에 대해서 왜 구태여 서상목 씨가 들어와서 이렇게 자리 잡으려고 하는 것이냐, 이거 우리 위원들의 앞으로 걱정은 이런 거예요. 사회적 금융회사 만들 때 서상목 씨가 또 관여하고 싶어 하는 거 아니겠는가. 이런 부분입니다. 서상목, 좌승희 두 분 해서 하게 되면 김문수 지사 꼼짝도 못합니다. 이런 거 아니라도 그렇게 돼 있어요, 지금. 사회적기업 진흥지원재단 만들어서 누구 앉혔잖아요, 솔직히 말해서. 이것이 우리 사회적기업에 대해서 가는데 얼마 진행됐는지 알 수 있을 거예요, 아마 연구해 보시면. 이런 패턴을 지금부터라도 막아야 되겠다는 생각이 들어서 자꾸만 말씀을 드리는 거예요. 그래서 경발연이 신뢰를 회복하고 연구된 것이 맞다고 한다면, 맞을 수 있다면 이런 것을 받아들여서 원장님의 결단, 정말로 도지사하고 결단을 독대해서라도 만들어야지만이 되는 것이다, 이런 생각이 드는 겁니다. 이게 모든 패턴이 도의원들이 느끼는 것이 다 그런 겁니다, 지금. 하다보게 되면 또 뭐 하는 것처럼 해놓고 나서 다리 하나 걸쳐놓고 나서 이미 연구는 다 됐어요. 제가 금융회사기 때문에 이거 제가 잘 압니다. 어떻게 하는지 머릿속에 벌써 다 들어와 있어요, 읽어보게 되면. 이러한 부분의 패턴 속에서의 그런 것이 문제가 되기 때문에 정말로 말씀드리고 싶고, 정말로 이번 기회에 경발연이 바른 자리를 찾아갈 수 있도록 부탁을 드리는 겁니다. 이 부분에 대해서 한번 확실하게 답변을 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 위원님께서 지적하신 거 오전에 지적하신 것의 연장선상에서 정말 충정에서 저희들한테 충고해 주신 것으로 저는 그렇게 이해를 하고 있고요. 그래서 저도 원장으로서의 저희 연구원의 신뢰성과 소위 명성 또는 이걸 지키려고 앞으로 계속 노력을 할 거고요. 기금문제는 그렇습니다. 저 개인적 소견으로는 기금을 쓰면 안 된다라는 건데 보통 저희들 예산편성을 할 때 기금으로 사용할 걸 전제로 해서 항상 예산을 세워서 적게 배정을 하기 때문에 최근에 지금 그걸 몇 십억씩 곶감 까먹듯이 솔직한 얘기로 까먹고 있는데 그건 저는 잘못된 일이라고 생각을 합니다. 그래서 저희들이 예산이나 이런 것을 기금을 전제로 하지 않고 예산편성을 해야 되는데 편성 때부터도 지금 그렇게 나와 가지고 그런 문제가 있다, 이렇게 말씀을 드리고요.
</p>
<p><b>○ 권오진 위원 </b> 아까 말씀드린 대로 이러한 초빙연구원 같은 이런 시스템을 인정을  안 한다면, 예산에 대해서 정확하게 한다면 당연히 해드려야죠. 그런데 위원들이 볼 때는 이렇게 방만하게 쓸 수 있겠구나 하고 생각을 하니까는 예산을 자르는 거예요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 저희들이 그 부분은 주의를 할 거고요. 지금 몇 분 특정인들은 위원님들께서 왜 그런 우려를 하시는지 저도 충분히 공감을 하고요, 공감을 하고. 그래서 앞으로도 하여간 저는 제가 할 수 있는 능력 그리고 할 수 있는 능력 플러스 할 수 있는 권한이라든지 이런 걸 통해서 최대한으로 저희 연구원의 독립성과 자율성을 지키도록 계속 노력을 해나가겠습니다. 
</p>
<p><b>○ 권오진 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 마지막으로 5분 추가질문 신종철 위원님, 자리에 안 계십니다. 조금 전에 임병택 위원께서 자료 도착문제로 인해서 추가질의를 신청하셨습니다. 임병택 위원님 추가질의 해주시기 바랍니다.
</p>
<p><b>○ 임병택 위원 </b> 저는 경기개발연구원을 보면서 원칙 몇 가지를 정했으면 좋겠습니다. 직접적인 이해당사자는 아니지만 경기개발연구원을 아끼고 보호하려는 관점에서 드리는 말씀이라는 걸 먼저 이해해 주시고 들어주십시오. 김문수 도지사 들어서 가장 큰 역점사업 두 개를 들자면 저는 그렇게 생각합니다. 뉴타운사업과 GTX사업이라고 생각합니다. 뉴타운사업 성공했습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 뉴타운사업에 대해서는 저희들이 할 얘기가 많은데 저희들이 처음으로 뉴타운에 대한 문제점 같은 것들을 지적해서 그래서 상당히 뉴타운을 철수하는데 있어서 저희들 나름대로 굉장히 도움이 됐다고 지금 생각을 하고 있습니다. 저는 작년부터 취임하고 난 다음부터 뉴타운에 대한 정확한 실상과 거기에 대한 비용문제를 분명히 얘기를 해라, 이렇게 해가지고 사실 그게 지난번에 여러 선거 때도 문제가 돼 가지고 홈페이지에 내리고도 올리고도 이런 여러 가지 우여곡절이 있었습니다마는 뉴타운 문제에 대해서는 저희들이 적극적으로 연구원의 역할을 했다고 저희들이 개인적으로 생각을 하고 있고 오히려 그것은 지사한테 저희들이 굉장히 충언을 드렸다고 생각을 하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 충언드리는 시기가 너무 늦었습니다. 너무 늦었고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제 취임 이후로 말씀드리는 겁니다. 
</p>
<p><b>○ 임병택 위원 </b> 뉴타운의 폐해가 뭔지 아십니까? 저희 지역 같은 경우만 해도 5,000만 원 하던 빌라를 3,000만 원 전세에 신혼부부가 살았습니다. 저가주택들이 많았어요. 뉴타운 지정하고 집값이 두 배 세 배 뛰었습니다. 1억, 1억 5,000, 3,000만 원 전세 살던 신혼부부들이 어떻게 1억 5,000짜리 빌라를 사게 됩니까? 그리고 나서 뉴타운 해제 됐어요. 집값 빠집니까, 안 빠집니다. 집 사려면 이사 가야 됩니다. 그래도 가장 싱크탱크라고 불리는 분들이 계셨습니다. 그 위험신호를 계획 당시에 그래도 플랜A, 플랜B까지 생각하는 그런 현명한 지혜가 있었으면 좋겠어요. 전 뉴타운도 마찬가지입니다. 김문수 도지사 체제 이후에 어떤 도지사가 오실지 몰라요. 본인의 정치적 야욕과 욕심에 의해서 어떠한 대형사업을 경기개발연구원에 제안할지 모릅니다. 뉴타운과 GTX가 저는 반면교사가 돼야 된다라고 보고요. 그러한 대형 국책사업과 관련되어서 논리적 근거를 제공할 때는 저는 자기방어기제가 있어야 된다고 봐요, 우리 경기개발연구원이 힘없이 끌려가는 게 아니라. 저는 그러한 부분도 꼭 좀 고민해 주셨으면 하는 부탁을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  뉴타운과 관련되어서 제가 참 어이없는 펙트 하나만 말씀드리면 제가 본청의 자료를 받아봤어요. 현재까지 얼마가 들어간 줄 아십니까? 공식적인 자료만 650억이 들어갔어요, 650억. 경기도시공사가 직원들 30명 달라붙어서 돈 쓴 거 그거 빼고, 경기개발연구원 용역비 다 빼고, 650억이에요, 650억. 그럼 그 돈이 어디로 갔어요? 그 아까운 돈으로, 그러니까 모두의 공동책임인데요. 저는 경기개발연구원은 그래도 정말 싱크탱크시라면 그러한 부분에 있어서 좀 더 각별한, 차기 도지사 체제에서도 저는 그것은 변함없으리라고 보여집니다. 그 취지를 저는 아실 거라고 보고요. 
</p>
<p style="padding-left:1.2em">  다음 질문 하나 더 하겠습니다. 마찬가지로 인사문제, 비정규직 박사님들이 정규직 박사님이 되시는 거, 비정규직 공무원들이 정규직 공무원 되는 거, 저는 당연히 공공기관이 앞으로 해야 될 일이라고 봅니다. 그런데 한 점 의혹도 있으면 안 돼요. 정말  공정하고 투명한 절차를 통해서 구성원들이 합의할 수 있는 기준을 만들어 놓고, 구성원이 제시해 놓고 하셔야지 정말 자료 보다가 깜짝 놀랐습니다. 저는 원장님께서 다시 한 번 돌아보셔야 될 과제지 않을까, 문제지 않을까 그렇게 생각합니다. 저는 꼭 필요하다라고 봅니다. 공정하고 투명한 구성원들이 동의할 수 있는 기준, 성과급도 마찬가지고 인사 관련 부분도 마찬가지입니다. 저는 그렇게 당부드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 앞으로 보다 더 철저하게 기준이나 이런 것을 공정하게 해서 하도록 노력하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 마지막인데요, 제가 오전에 질문 드렸던 거 결론을 꼭 좀 내야 될 것 같아요. 저는 황성준 이 초빙연구원에 대한 이야기인데요. 이참에 경기개발연구원에 분명한 원칙 하나는 원장님께서 만드시죠? 원장님 체제하에서 이루어졌던 이 몰상식한 행동이, 행동이었습니다. 황성준이란 이분은 입으로는 건강한 모습, 공동체를 위한 자기희생이라는 이야기를 밥 먹듯이 하는 분이고 색깔론과 이념 공세로 솔직히 제 의견은 김문수 지사 이데올로기 역할을 하고 있어요. 기본적인 이론 제공자이신 것 같아요. 이런 분이 경기개발연구원과 러시아 대외정책과 동향 등 공동연구를 하겠다고 해서 계약을 했어요. 러시아 대외정책과 동향 등 공동연구라는 과제물을 냈으면 모르겠습니다. 그런데 안 냈잖아요. 계약변경도 없었죠, 중간에?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 말씀드렸지만 황성준 씨는 중간에 퇴사를 했고요, 1년도 못 채웠고. 그래서 한…….
</p>
<p><b>○ 임병택 위원 </b> 아니, 보십시오.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 1년도 못하고 퇴사시켰고.
</p>
<p><b>○ 임병택 위원 </b> 2011년 7월 8일부터 2011년 12월 31일까지 1차 계약기간이었어요. 이 계약기간 동안 성과물이 없으면 당연히 내보내셔야죠. 다시 2012년 1월 1일 날 또 계약하셨어요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 내보냈는데 저희들 연구의 특성을 좀 이해를 하셔야 되는 게…….
</p>
