<p><b>○ 배수문 위원 </b> 알겠습니다. 민선 5기가 후반기로 접어든…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 잠깐 얘기하기 전에 아까 서울연구원 말씀을 하셔 가지고 저희들이 또 따라하는 그런 것도 좀 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 그래서 지금 말씀드리는 거예요. 그럼에도 불구하고 지금 대안이 서울발전연구원 같은 경우는 이미 언론사에서 선점했잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 그건 뭐 돈 주고 사오기도 그런 시점이잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 그 발전이라는 게, 다른 시도 연구원들이 다 development institute거든요. 거기도 사실 영문은 다 똑같이 개발이고 그런데 그래서 이게 발전하고 개발하고 그 차이라는 게, 다만 위원님들께서는 개발이라고 그러면…….
</p>
<p><b>○ 배수문 위원 </b> 오히려 그런 걸로 보면 GRI로 바꾸신 건 더 획기적이다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 빨리 잘 바꾼 거죠.
</p>
<p><b>○ 배수문 위원 </b> 오히려 잘하신 거죠. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 잘한 겁니다.
</p>
<p><b>○ 배수문 위원 </b> 워낙 고민하셨던 흔적들이 많기 때문에 답이 나왔으면 좋겠다라는 얘기고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 배수문 위원 </b> 지금 민선 5기 후반기로 접어들었죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 중립적인 것과 민선 6기를 대비하고 더 많은 경기도의 비전을 제시할 시기라고 봅니다. 왜냐하면 민선 5기 단체장이 요구하는 것들을 담아내는 시기가 아니라 정말로 경발연이 주도적으로 뭔가 만들어갈 수 있는 최적의 시기라고 생각합니다. 올해부터 후년 선거 전까지가요. 이 시기 때 정말로 무엇을 해야 될지 2013년도 계획에 보니까 일부 좀 미흡한 점이 있어 보입니다. 다시 한 번 이런 정치적 상황들을 잘 검토하셔서 행해야 될 것들을 좀 해주셨으면 좋겠고요.
</p>
<p style="padding-left:1.2em">  하나 더 얘기한다면 본 위원이 얘기했지만 이번 2013년도 예산안을 경기도에서 만들면서 경기도민에게 조사한 내용이 있습니다. 여론조사를 해봤는데 가장 먼저 경기도에서 신경 써서 예산을 세웠으면 좋을 게 뭐냐라고 했더니 첫 번째가 복지였습니다, 31%. 그다음이 교통이었습니다. 교통이 16%고요. 그런데 경기개발연구원에서 연구하는 내용들이 도민의 욕구를 많은 부분 쫓아가줘야 되는 게 당연하다고 보는데 그럼에 비하면 복지에 대한 연구는 홀대된 게 분명합니다. 그리고 지금 박사 한 분이 오셨지만 제가 보기에 연구분야가 100% 복지의 기본을 다루고 있는 것 같지는 않고요. 그래서 좀 더 집중적으로 만들어서 복지가 좀 더 큰 포션을 차지하고 발전의 테마로 놨으면 좋겠다라는 말씀을 드리면서, 이러면서 다시 얘기를 하는 게 경기도 산하의 단체장들 좀 문제가 생겼죠? 특히 여성가족연구원장 같은 경우 상당히 문제가 되고 있습니다. 차제에 여기가 브레인 그룹으로서 가장 선두라면 연구 일부를 집중화시키고 그 외에 경기도 내에 다른 쪽으로 업무만 지원하는 기능변화를 검토해 가는 것도, 연구를 일단 해 놓고요. 그다음에 집행부와 확인하는 건 어떨까, 지금 시점에 그렇다는 얘기입니다. 다른 때보다 하기 좋은 시점이라는 거죠. 고민을 좀 해봤으면 좋겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 복지 쪽에 지금 말씀하신 거는 옳으신 말씀이고요. 저희도 복지연구를 더 확대 강화를 하려고 사람도 하나 충원했고 사실 이번에 SBI연구도 복지연구의 차원이기 때문에…….
</p>
<p><b>○ 배수문 위원 </b> 알고 있습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 다만 그런 걸 하는…….
</p>
<p><b>○ 배수문 위원 </b> 다만 SIB연구 쪽 책자도 보니까 서상목 선임연구원은 이름도 지금 올라가 있지 않더라고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 그래서 이게 특정인 때문에 또 오해가 돼 가지고 그러는데 저희들이 복지연구는 내년쯤 돼 가지고 상당히 많은 봇물이 터질 겁니다.
</p>
<p><b>○ 배수문 위원 </b> 그 봇물이 터지는 건 좋은데 인력이 없다는 거고요. 그리고 주거복지라든가 교통복지도 다 연구하고 있기 때문에 모든 연구에, 사실은 복지를 기본적으로 생각하고 있는 연구원들이 TF팀에 다 참석을 해서 복지가 기본이 되게 만들어줘야 되는 시점이다 이렇게 봅니다. 지금도 경기도 예산이 30%가 복지로 편성이 된 것 아시죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 서울도 그렇게 됐고 경기도도 역시 그렇게 되고 있습니다. 국가예산도 OECD 기준에 보면 복지예산이 약 60%밖에 미치지 못하지만 그렇다면 향후 40% 더 복지예산이 증가할 걸로 봅니다. 그렇다면 GRI에서 주안점을 무엇에 두고 무엇을 목표로 두고 연구해야 될지를 생각할 때 자명해진다라고 생각합니다.
</p>
<p style="padding-left:1.2em">  그다음에 예산부분에 대해서 지금 90억 원을 가지고 운영을 하고 있죠? 거기다가 55억이 위탁을 주면서 얘기가 되고 있는데 출연금이 맨 처음에 GRI를 설립할 때 시군으로부터 많게는 3억까지 출연금을 받은 걸로 알고 있습니다. 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 그래서 시군에 대한 연구는 동료 위원님들께서 다 지적해 주셨기 때문에 보다 더 강화해야 된다라고 얘기가 되고 있습니다. 그리고 밀착형, 아까 연구원들마다 각 시군과 접목시켜서 1개 이상의 과제를 수행하게끔 한다고 하셨는데 특히나 우리 기획위원들하고의 연계관계를 잘 생각하셔서 주제를 선정하는데 같이 연구가 됐으면 좋겠다라고 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  아까도 말씀드렸지만 기관과 통합 같은 거는 연구가 선행되고 난 다음에 그 연구를 바탕으로 어떻게 더 효과적인지를 만들어낸다면 분명히 필요한 방법들이 좀 나올 수 있으리라고 생각이 듭니다.
</p>
<p style="padding-left:1.2em">  그다음에 조직도에 보니까 전략센터가 원장 직할로 돼 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 이 부서의 가장 핵심적인 건 뭐죠? 연구하는 겁니까, 아니면 원장이 원하는 것들을 지원해주는 서포팅 차원입니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그건 아닙니다. 연구를 하고 있고요. 연구 중에 굉장히 단기성 연구, 상당히 많은 역할을 했고요. 제가 그걸 만든 배경은 작년에 정책센터를 이름을 바꾼 건데 그때도 얘기가 많이 나왔습니다마는 제가 부임하면서 보니까 굉장히 현안연구를 해야 될 게 많은데 연구원들은 또 연구원들의 고유의 임무가 있고 또 정책연구도 있고 기본연구도 있고 수탁과제도 있고 이것을 다 현안에 동원하기에는 너무나 다른 연구들 부담이 있는 것 같아서 그래서 직접 조직을 만들어서…….
</p>
<p><b>○ 배수문 위원 </b> 만들어서 따로 지금 원하는 것들만 급하게 추진해서 만들 수 있게 해놨다?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 이 친구들 계속 정말 밤낮이 없습니다. 밤낮이 없고 상당히 노동강도가 세죠. 노동강도가 세고 굉장히 힘들여서 연구들을 하고 있는데…….
</p>
<p><b>○ 배수문 위원 </b> 알겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런 연구를 하고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 본 위원이 다른 홈피와 조직도를 비교해 봤을 때 GRI의 연구강도가 아주 세다고 하시는 것은 죄송하지만 강원발전연구원에 비하면 사실은 세진 않아요. 검토해 보시면 아시지만.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 좋으신 말씀입니다.
</p>
<p><b>○ 배수문 위원 </b> 물론 직원들이 본 위원의 발언을 어떻게 인지하고 있을지는 모르겠는데 아무래도 모든 조건에서, 특히나 아주 좋은 세리라든가 이런 쪽과 비교하면 좀 떨어지겠지만 업무강도가 좀 더 세다고 느낄 수도 있고 보수가 좀 더 미흡하다고 할 수 있지만 그럼에도 광역단체의 연구원 치고는 근무여건이 그렇게 나쁘지 않은 거다. 동의하시죠, 그거는?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 제가 계속 그 말을 강조하고 있는데 잘 안 믿습니다.
</p>
<p><b>○ 배수문 위원 </b> 본 위원도 그럼에도 불구하고 지금, 아마 그 구조 속인 것 같아요. 7단계로 처음에 나눠서 인센티브를 줬던 부분이 지금 5단계로 줄이셨죠, 강도를 줄이시느라고?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 배수문 위원 </b> 그때 느꼈던 것이 훨씬 크지 않을까라는 생각을 합니다. 그래서 공정한 것이 된다면 그것도 아주 좋은 제도라고 생각을 하고요.
</p>
<p style="padding-left:1.2em">  그다음에 좀 안타까운 기사 하나가 팔당본부에서 계시다 오신 박사님 계시죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 조영무 박사라고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 항간에 많은 염려 섞인 부분들을 가지고 오셨는데 오셔서 적응 잘하시고 일 잘하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 와서 제가 생각했던 것보다 훨씬 더 적응도 잘하고 있고 열심히 일을 하고 있습니다.
</p>
<p><b>○ 배수문 위원 </b> 죄송합니다만 이분에 대해서 환경단체에서 상당히 많은 지적들을 하고 이쪽으로 왔었을 때 특혜다, 특혜논란이 있었어요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 특혜는 아니고요.
</p>
<p><b>○ 배수문 위원 </b> 본 위원에게 조영무 박사님의 연구실적 그리고 오셔서 감당했던 역할들에 대해서 따로 보고를 좀 부탁드립니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 배수문 위원 </b> 그다음에 언론에서 지적됐던 게 웹사이트가 직원용이다라는 지적이 또 나왔어요. 이것도 본 위원이 아까 지적했던 것처럼 경기도 산하의 모든 공무원들이 원활하게 접근할 수 있는 콘텐츠를 좀 많이 개발해서 정말 들어오고 싶은 사이트가 되고 안 보면 궁금한 사이트가 될 수 있도록 특단의 조치를 취해줘야 되겠다라는 생각을 합니다. 그런 것은 충분히 잘하실 수 있으리라 생각이 들어요. 세리에서 계셨기 때문에. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 그쪽을 담당은 안 했습니다만 하여간에 돌아가는 모습은 압니다. 
</p>
<p><b>○ 배수문 위원 </b> 그리고 그런 쪽에 있는 정보를 얻기는 훨씬 쉬우신 위치에 계시잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 다 돈입니다. 이것도 돈하고…….
</p>
<p><b>○ 배수문 위원 </b> 알고 있습니다. 그다음에 환경부에서 GRI 연구결과를 수용할 수 없다라고 했어요. 내용 아시지요?  
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 내용 압니다. 
</p>
<p><b>○ 배수문 위원 </b> 이거 굴욕 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그건 우리가 굴욕이 아니라요. 아마 환경부 쪽에서는 경기도 의견을 너무 충실하게 반영한 거 아닌가.
</p>
<p><b>○ 배수문 위원 </b> 거꾸로?
</p>
