</p>
<p style="padding-left:1.2em">  국토해양부의 BC분석에 의하면 0.56으로 나와서 검토 자체가 사실은 문제가 됐었어요. 그럼에도 이전에 나왔던 GRI 연구내용을 보면 GTX 안 하면 안 되는 것을 전제로 하고 연구한 것처럼 내용이 되어 있습니다. 어떻게 생각하십니까? 
