<p><b>○ 경기개발연구원장 홍순영 </b> 중립적 입장에서 제가 말씀을 드리겠습니다. 경기도에 플러스 되는 게 뭔가 이걸 생각을 해봐야 될 거 같고요. 그래서 경기도민들이 원하는 게 뭔가라는 건데 중앙정부는 될 수 있으면 경기도에서 하는 걸 안 하려고 합니다. 수도권 문제 때문에. 그래서 될 수 있으면 정부의 예산이나 SOC에 대한 것들을 수도권에는 전반적으로 안 하려고 들고 지방으로 가려고 하는데 경기도 입장에서는 될 수 있으면 경기도에서 바람직하고 경기도 사람들이 빨리빨리 왔다 갔다 할 수 있는 것을 해야 되겠다는 입장이 있는 것 같고 그래서 이게 특정 정치적인 집단에 있는 수장이 뭘 주장을 했다 안 했다를 떠나서 제가 GTX를 보면서 느낀 게 중앙정부의 소위 말하는 경기도를 바라보는 시각, 저희 수도권을 바라보는 시각이 굉장히 많이 왜곡되어 있다, 저는 그런 생각을 하고 있습니다.
