</p>
<p><b>○ 권오진 위원 </b> 권오진 위원입니다. 지금 배수문 위원께서 말씀하셨듯이 제가 볼 때도 복지 부분의 연구가 상당히 부족한 거 같은 부분을 느끼고 있습니다. 지금 저한테 실적을 가져 왔는데요, 13건밖에 없어요. 그나마 몇 년 동안 복지 부분의 연구가 단절되었었지요? 복지재단으로 넘어가는 바람에 많이 줄었던 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 상대적으로 그런 측면이 있습니다. 
</p>
<p><b>○ 권오진 위원 </b> 그렇지요? 그래서 앞으로 복지 분야에 대해서 더 연구를 강화시킬 필요가 있다고 보는 것이고요. 서울에 5대 복지정책을 하는데 거기에서 첫 번째 일자리, 두 번째가 주거예요. 그다음에 교통, 교육 이렇게 되어 있던데, 보니까. 이런 것을 분명히 한번 우리 연구원들 중에서 실력 많으신 분들이 연구해서 일자리 부분하고 주거 부분에 관심을 가지시고 연구를 더 강하게 해주시기를 부탁드리고요.
</p>
<p style="padding-left:1.2em">  사실 지난번에 제가 우리 간담회 때 나왔던, 말씀을 제가 많이 드린 것 같은데 그 내용들이 여기에서 정책에는 하나도 반영이 안 되었던 것 같습니다. 솔직히 제 느낌은 그렇습니다. 제가 얘기했던 그런 사항들이 일자리 부분은 어떻게 발전시켰으면 좋겠다, 주거 복지는 어떻게 했으면 좋겠다 하는 부분들이 제가 많이 말씀드린 것 같았는데, 저쪽 안면도 가서 했을 때 그 내용들이 여긴 전혀 관심이 없었던 것 같고 이러한 내용들이 솔직히 말해서 윗분들이 생각하고 있는 우리 경기도 발전에 대해서 개발 중심의 근거를 만들어 드리기 위한 연구원으로 되어지지 않았나 생각이 드는 것이 제 우려였으면 좋겠습니다. 그렇지 않고 정말로 경기도에서 주민들의 삶의 질을 높이기 위한 복지 부분을 강하게 임팩트가 되었으면 좋겠다는 생각이 들어서 말씀을 드리는 겁니다. 그렇게 말씀을 드리고 그런 거에 더 신경을 써주시기를 부탁드리고요. 일자리하고 주거 부분에 있어 같은 경우는 사실 저는 일자리를 이렇게 생각합니다. 경기도에서 사실은 여러 가지로 서울에서 돈을 벌어오는 사람이 한 60% 된다고 저는 생각을 합니다, 서울에서 출퇴근 하면서. 그렇기 때문에 그런 부분들, 거기에 따라서 교통의 문제가 생기고 있고요. 또 주거 문제에 있어서는 상당히 경기도 분들은 서울하고 달리 소득이 상당히 한정된 기준이 있습니다. 저는 주거복지의 기본원칙이 지금 하우스푸어가 생기는 것은 자기소득의 60%를 주거에 쓴 사람들은 하우스푸어입니다, 신문에 나왔듯이. 적어도 50% 이상 쓰게 되면 어렵고요, 20% 이상 쓰게 되면 매우 어려워집니다. 20% 이내에서 주거비용을 써야지만 정상적인 가정생활을 할 수 있다고 저는 생각을 하고 있거든요. 그러니까 그런 연구부터 되어 가지고 어느 정도의 집이 되어져야지만 주거가 이루어지는 것이다라는 관점을 연구하고서 주거복지를 접했으면 좋겠다는 생각이 첫 번째로 드는 겁니다. 
</p>
<p style="padding-left:1.2em">  그다음 제가 시간이 없으니까 교통 문제하고 몇 가지만 말씀드리겠습니다. 아까 신현석 위원님께서 얘기하고 나가시면서 박원순 서울시장이 은평 뉴타운 앞에 가서 서울 사람을 막더라도 교통을 해결하겠다고 말씀하셨다고 그래서 흥분해서 가셨어요, 신 위원님께서. 그랬는데 사실 제가 그동안에 버스에 대해 상당히 관심을 많이 가지고 책을 봤습니다, 여기에 나온 책들을 봤는데 사실 제가 용인에서 서울을 가다 보니까 용인에서 한남동까지는 30분이 안 걸립니다. 그런데 한남동에서 종로까지 1시간 걸렸어요. 그러니까 내가 서울시장이래도 열 받겠지요. 막히니까. 그런 차원에서 볼 때 한번 경기도가 어떻게 하면 교통을 해결할 것인가 차원의 연구 발상을 해야 될 것이라는 생각이 드는 겁니다. 제가 서울에 진입하는 버스를 찾아보았습니다, 제가 여러 가지 생각을 해 가지고. 그랬더니 333개 노선에서 4,782대가 다니고 있더라고요, 서울에. 그러니까 서울사람들은 경기도 버스 때문에 묶여 있는 거지요, 솔직히 말해서. 어떻게 이런 발상을 연구가 더 깊이 되어 가지고서 서로 윈윈 될 수 있는 방법을 연구할 필요가 있지 않겠는가 이런 차원에서 말씀을 드리는 겁니다. 그러니까 일상적인 발상이 아니고 획기적으로 이런 제안을 가지고 나가야지만 서울사람들도, 경기도에서도 말이지요, 이런 게 있어요. 용인에서 분당 정자역까지 가는데 한 정거장만 가게 되면 편합니다. 그런데 성남시가 오케이 안 해 가지고 한 정거장 전에 내려서 또 지하철 타는 겁니다. 제가 싸우러 갔어요, 성남시에. 그랬더니 성남시에서 뭐라고 그러느냐면 용인에서 들어오는 버스가 14개 노선에 147대다 이거예요. 147대가 다니는데 어떻게 그 길을 하겠느냐. 성남시민이 가만히 있겠느냐라고 해서 오케이 못하더라고요. 이렇듯이 정말로 이런 것을 다양하게 연구했으면 좋겠다는 생각이 첫째 들어서 연구방향을 잡아줬으면 좋겠다는 말씀을 드리는 겁니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 거기에 대해서 참고로 말씀드리면 저희들이 교통연구원이라고 있습니다. 서울하고 경기, 인천의 각 연구원들이 같이 심포지엄도 할 거고 같이 연구도 하려고 하고 있습니다, 그런 문제 때문에. 종합교통망 형성하는. 
</p>
<p><b>○ 권오진 위원 </b> 다음은 제가 북부지원에 갔다가 좋은 사례가 있어서, 이상대 박사님 여기 계신가요? 잠깐만 앞으로 나오시지요. 제가 북부청에 갔을 때 군관협력팀의 자료를 받았더니 수원 비행활주로 하는 데 200억이 드는데 수원시가 80억, 경기도가 80억, 화성시가 40억 들여서 공사를 하지 않습니까? 그 근거를 내라고 했더니 GRI에서 연구한 자료가 나왔어요, 저한테. 봤더니 그렇게 한다 했을 때 주위개발을 해 가지고 수원시가 재산세가 14억이 생기고 취득세가 450억이 생긴답니다. 그리고 화성시가 재산세가 11억이고 취득세가 383억이 나왔어요. 저는 이것을 보고 나서, 그분이 끝에 것을 복사해줘 가지고 이게 끝에 건 줄 알았더니 앞에 수원시도 있더라고요, 보니까. 그런데 재산세는 시군에 떨어지는 거 아니에요. 그러니까 수원시도 5년만 받으면 70억이 떨어지는 거고 화성시도 50억이 떨어지는 거더라고요. 세금이 발생하는 거예요, 세금이. 경기도는 솔직히 말해서 취득세 하더라도 450억하고 380억이니까 780억이 떨어지는 거예요. 세수 추계도 되는 거지요. 이러한 시스템을 가지고 재개발 있잖아요. 재개발이라든지 뉴타운이 발생했을 때 솔직히 우리가 산업단지 개발해 가지고서 제일 세금 많이 들어가는 게 중앙정부 아닙니까? 이렇듯이 이런 논리를 만들어 가지고서 중앙정부 재원을 끌어내고 도에도 끌어내고 시군에서 끌어내 가지고서 여길 개발할 수 있는 가능성이 없는지 하는 것을 답변해 주시기 바랍니다. 
</p>
<p><b>○ 미래비전연구부장 이상대 </b> 미래비전연구부장 이상대입니다. 위원님 말씀에 동의하고요. 그다음에 저를 포함한 저희 연구원에서도 사실은 거의 10년 전부터 TIF라고 그러는데요. 조세담보부채권 발행해서, 왜냐하면 개발사업을 하게 되면 국가도 이익을 보고 도도 이익을 보고 시군도 이익을 보지 않습니까? 그런데 시군 같은 경우에는 재산세가 늘어나지 않습니까? 그 부분들을 현가화해서 그렇게 채권을 발행해서 유동화시켜서 도의 정비사업이라든지 기반시설투자 이런 데로 연결시키자는 얘기를 사실은 10년 전부터 제안을 해놓고 있지만 국토해양부라든지 그다음에 정부 쪽, 국회 쪽에서는 아직 그 부분에 대해서는, 그 부분에 대해서 물론 검토는 하고 있습니다만 아직 입법은 안 되고 있는 상황입니다. 
</p>
<p><b>○ 권오진 위원 </b> 일본에서는 이렇게 하고 있더라고요, 물어봤더니. 
</p>
<p><b>○ 미래비전연구부장 이상대 </b> 맞습니다.
</p>
<p><b>○ 권오진 위원 </b> 개발을 해서 무조건 돈을 내라고 하는 것이 아니라 돈이 안 들어오게 되면 뉴타운도 안 되고 다 아무것도 안 되는 거예요, 솔직히 말해서. 그런 것을 연구해서 발전시킬 수 있으면 좋겠습니다. 
</p>
<p><b>○ 미래비전연구부장 이상대 </b> 저희들이 입법정책대안을 더 열심히 하도록 하겠습니다. 
</p>
<p><b>○ 권오진 위원 </b> 수고하셨습니다. 감사합니다. 이상입니다.
</p>
<p><b>○ 위원장 김현삼 </b> 권오진 위원님 수고하셨습니다. 또 질의하실 위원님 계십니까?
</p>
<p style="padding-left:2.4em">    (「없습니다.」하는 위원 있음) 
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원님이 안 계시므로 오늘 경기개발연구원 소관 업무에 대한 질의와 답변을 모두 마치겠습니다.
</p>
<p style="padding-left:1.2em">  홍순영 원장을 비롯한 경기개발연구원 임직원 여러분! 한정된 예산과 어려운 여건 속에서도 경기개발연구원은 그동안 천이백삼십사만 경기도민의 삶의 질 향상과 경기도의 미래비전을 위하여 많은 역할을 해왔습니다. 감사의 말씀을 드립니다. 따라서 경기개발연구원이 경기도의 종합연구기관으로서 공신력 그리고 자긍심을 잘 지켜나가셨으면 좋겠다는 생각입니다. 그런 차원에서 GRI 공신력과 자긍심에 상처를 주는 일들이 발생되어져서는 안 될 것입니다. 오늘 위원님들께서 지적하신 많은 사안들에 대해서 특별히 유념해 주실 것을 부탁드리고 더더욱 후속조치에 대해서 특별한 고민을 해주실 것을 부탁의 말씀을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 홍순영 경기개발연구원장을 비롯한 임직원 여러분! 장시간 열의를 가지고 행정사무감사에 임해주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성의껏 답변해 주신 경기개발연구원 원장을 비롯한 임직원 여러분께 감사의 인사말씀을 드립니다. 그러면 이상으로 오늘 경기개발연구원 소관사항에 대해 2012년 행정사무감사를 모두 마치겠습니다. 산회를 선포합니다. 
</p>
<p class=''ar''>(16시40분 감사종료)
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(11명) 
</b></p>
<p class=''aMan''>김현삼배수문김광철권오진신종철신현석안병원오완석윤희문임병택</p>
<p class=''aMan''>최재우</p>
<p><b>○ 출석전문위원 
</b></p>
<p class=''em15''>   수석전문위원 김용덕
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p><p class=''em15''>경기개발연구원장 홍순영부원장 김대호기획조정실장 강철구</p>
<p><p class=''em15''>사무처장 이재동전략연구센터장 김은경미래비전연구부장 이상대</p>
<p><p class=''em15''>자치의정연구부장 김동성도시ㆍ주택연구부장 이성룡창조경제연구부장 이정훈</p>
<p><p class=''em15''>교통연구부장 류시균환경연구부장 김동영통일동북아센터장 최용환</p>
