            <div','경기도의회',false,'{"legacy_id": "audit-1005", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1005"}'::jsonb,'2012-11-09'::date,'2012-11-09'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-1005');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2011.11.07. 월요일] 경기개발연구원 — 기획위원회 2011년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제8대 경기도의회 기획위원회</b> · 2011년도 행정사무감사(2011. 11. 04. ~ 2011. 11. 17.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1097" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2011년도 행정사무감사
</p>
<h4>기획위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2011년 11월 7일(월)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시16분 감사개시)
</p>
<p><b>○ 위원장 강득구 </b> 좌석을 정돈해 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조의 규정에 의하여 경기개발연구원에 대한 2011년도 행정사무감사를 시작하겠습니다.
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 홍순영 원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 강득구 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 혹시 럼스펠드 룰을 들어보신 적 있습니까, 원장님?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 못 들어봤습니다.
</p>
<p><b>○ 위원장 강득구 </b> 럼스펠드는 1970년대 중반에 백악관 비서실장을 지내고 두 번의 국방부장관을 지낸 분입니다. 이분이 작성한 규정이 럼스펠드 룰이라고 불리는 거죠. 이건 참모의 금과옥조라고 미국에서는 인정하고 있다고 그럽니다. 그 룰의 제1조가 뭐냐면 “대통령에게 욕을 퍼붓는다고 생각할 정도로 자유롭게 말할 수 없거나 그럴 수 있는 용기가 없다면 자리를 수락하거나 그 자리에 남아 있어서는 안 된다.”입니다.
</p>
<p style="padding-left:1.2em">  조선시대에는 사간원이라는 직책이 있었습니다. 왕에게 쓴소리를 하는 임무였습니다. 아무나 뽑지 않았습니다. 학문이 높고 기개가 있으며 사심을 버린 사람만이 가능했다고 합니다. 간관과 럼스펠드 룰을 종합해서 본 위원장은 경기개발연구원의 역할은 경기도정의 참모라고 정의하고 싶습니다. 1인, 한 사람을 위한 예스맨이 아니라 천이백만 경기도민을 섬기고 경기도민을 위한 길라잡이 역할을 해야 된다고 생각합니다. 참모의 역할은 장기적인 전망과 더불어 최상의 지식과 최고급 정보를 제공하는 것입니다. 직언과 충언을 마다하지 말아야 됩니다. 비판에 몸 사리지 말아야 됩니다. 21세기 지식정보사회, 스마트한 사회에서는 참모는 얽매이지 말고 창의적이어야 합니다.
</p>
<p style="padding-left:1.2em">  그런 의미에서 오늘 열리는 우리 행정사무감사는 경기개발연구원의 사업을 평가하고 대안을 마련하는 자리입니다. 오늘 행정사무감사가 경기개발연구원과 우리 위원회가 힘을 모아서 경기도와 경기도민을 위한 좋은 연구원이 되는 계기가 되기를 진심으로 기대하고 바랍니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 이와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그러면 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 부장, 센터장은 증인의 자격으로 소관업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 합니다.
</p>
<p style="padding-left:1.2em">  증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2011년도 행정사무감사를 실시함에 있어 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다라는 서약을 받기 위한 것입니다. 증언 또는 진술을 거부한 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다.
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인 출석여부를 확인하겠습니다. 피감기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동 기립)
</p>
<p style="padding-left:1.2em">  경기개발연구원장 나오셨습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 부원장 나오셨습니까?
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 사무처장 나오셨습니까?
</p>
<p><b>○ 사무처장 이재동 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 정책센터장 나오셨습니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 자치행정연구부장 나오셨습니까?
</p>
<p><b>○ 자치행정연구부장 송상훈 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 도시ㆍ지역계획연구부장 나오셨습니까?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 교통정책연구부장 나오셨습니까?
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 환경정책연구부장 나오셨습니까?
</p>
<p><b>○ 환경정책연구부장 이양주 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 경제사회연구부장 나오셨습니까?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 문화관광연구부장 나오셨습니까?
</p>
<p><b>○ 문화관광연구부장 이정훈 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 통일ㆍ동북아연구센터장 나오셨습니까?
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 의정연구센터장 나오셨습니까?
</p>
<p><b>○ 의정연구센터장 신원득 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 다음은 선서요령을 말씀드리겠습니다. 선서는 전체 증인을 대표해서 원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손만 들어주시면 되겠습니다. 그러면 선서를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관업무에 대한 2011년도 행정사무감사를 실시함에 있어 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2011년 11월 7일 홍순영.
</p>
<p><b>○ 위원장 강득구 </b> 자리에 앉아주시기 바랍니다. 그러면 우리 원장 나오셔서 간부소개와 업무보고를 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 안녕하십니까? 경기개발연구원장 홍순영입니다. 오늘 경기도의회 기획위원회 행정사무감사에 앞서 존경하는 강득구 위원장님과 위원님 여러분을 모시고 저희 연구원의 주요업무보고를 드리게 되어 감사의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  연구원은 동북아 미래를 선도하는 경기도의 싱크탱크로서 경기도의 미래발전을 견인하고 도민의 삶의 질 향상을 위하여 임직원 모두가 열정을 다해 정책개발을 추진해 나가고 있습니다. 기획위원회 위원님들의 많은 도움과 성원을 부탁드립니다.
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 연구원의 간부를 소개해 드리겠습니다. 먼저 조응래 부원장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  강철구 기획조정실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이재동 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김은경 정책센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  송상훈 자치행정연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 도시ㆍ지역계획연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김대호 교통정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이양주 환경정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 경제사회연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정훈 문화관광연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 통일ㆍ동북아연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  신원득 의정연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고 지금부터 연구원의 주요업무를 보고드리겠습니다. 배부해 드린 보고자료의 목차를 봐주시기 바랍니다. 보고순서는 일반 및 재정운영현황, 2011년 주요연구사업 실적, 2012년 주요연구사업 계획 순입니다.
</p>
<p style="padding-left:1.2em">  먼저 일반 및 재정운영현황입니다. 일반현황, 재정운영현황 순으로 보고드리도록 하겠습니다. 3쪽입니다. 일반현황에 대해 간략히 보고드리겠습니다. 저희 연구원은 1995년에 개원하여 경기도의 중장기비전 제시와 정책개발 지원기능을 수행하고 있습니다. 부서별 주요기능은 보고자료를 참조해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음 4쪽의 기구 및 인력에 대해 보고드리겠습니다. 현재 1실 1처 6부 3센터 2과 7팀의 조직으로 구성되어 있으며 인력은 원장 1명, 부원장 1명, 연구직 50명, 관리ㆍ정보ㆍ기능직 22명 등 총 74명의 정규직원과 그밖에 계약직원 97명 등 총 171명이 근무하고 있습니다. 참고로 부족한 연구원의 보완을 위해 통계, 정보기술, 도시계획, 경제 등 4개 분야에 대하여 현재 채용절차를 진행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음 재정운영현황에 대해 보고드리겠습니다. 올해의 총 예산규모는 193억 8,300만 원으로 일반회계 151억 9,500만 원, 수탁용역사업 특별회계 41억 8,800만 원입니다. 일반회계 151억 9,500만 원의 수입ㆍ지출내역을 구체적으로 살펴보면 수입항목은 경기도 출연금이 전체의 59%인 90억 원으로 가장 많으며 기금전입금이 13억 원, 기금이자수입 등이 14억 900만 원, 사업수입이 14억 2,200만 원, 전기이월금이 20억 6,400만 원입니다. 지출항목으로는 연구사업비가 전체의 40%인 60억 5,300만 원, 인건비가 47%인 71억 5,300만 원, 부서운영비가 9억 5,500만 원, 청사관리비가 9억 4,500만 원, 예비비가 8,900만 원입니다.
</p>
<p style="padding-left:1.2em">  다음은 6쪽입니다. 연구원의 기금은 총 249억 원입니다. 기금을 출연기관별로 살펴보면 경기도가 59%인 147억 원으로 가장 많으며 시군이 16%인 39억 6,100만 원, 민간부분이 8%인 20억 원, 자체적립이 17%인 42억 3,900만 원입니다. 예산과 기금이 효율적으로 운용될 수 있도록 최선을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  다음 2011년도 주요연구사업 실적에 대해 보고드리겠습니다. 보고자료 9쪽부터 26쪽이 되겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 9쪽의 2011년도 연구사업 목표입니다. 비전은 ‘동북아 미래를 선도하는 경기도의 싱크탱크 GRI’로서 2011년도 연구사업 목표를 경기도 경제ㆍ사회시스템 선진화를 위한 정책지원, 수도권 글로벌 경쟁력 강화를 위한 메가시티 전략 제시, 글로벌 수준의 현장밀착형 복지ㆍ문화ㆍ교육시스템 구상, 이렇게 세 가지로 설정하였습니다. 또한 연구사업 목표달성을 위해 미래를 선도하는 대도시권 전략, 지방자치ㆍ지방분권 강화 등 7대 중점사업을 선정하였습니다. 2011년도 주요연구사업 실적은 7대 중점사업을 중심으로 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 10쪽의 주요연구사업 실적에 대해 보고드리겠습니다. 첫 번째 중점사업은 미래를 선도하는 대도시권 전략입니다. 이와 관련하여 2020 경기도 종합발전계획 수립, 경기경제자유구역 지정 추진, 21세기 서해안발전 거점화 구상 등의 연구를 수행하였습니다. 먼저 2020 경기도 종합발전계획은 경기도의 비전을 비롯해 4대 목표, 8대 기본과제를 설정하였습니다. 또한 공간구조 형성을 위한 7대 핵심전략, 경제ㆍ교육ㆍ환경ㆍ교통 등 8대 부문별 전략과 5개 권역별 25개 핵심전략 등의 내용을 담고 있습니다. 향후 관계부처 협의와 국토해양부 승인을 거쳐 도의 중장기 시책사업 추진과 31개 시군 도시계획의 상위계획으로 활용될 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 경기경제자유구역 지정 추진입니다. 저희 연구원은 경제자유구역의 개발구상, 타당성조사, 특성화 방안 등에 관한 연구를 꾸준히 수행해 왔습니다. 그 결과 지난 3월 지식경제부에 경기경제자유구역 개발계획을 제출하였고 금년 중으로 경제자유구역위원회의 심의ㆍ의결이 있을 예정입니다. 주요내용으로는 군자지구, 시화MTV, 송산그린시티 등 6개 지구 총 101.7㎢의 면적에 경제자유구역의 조기 활성화를 위하여 융복합산업단지 및 해양레저산업단지 조성, 서해안 융복합 신산업벨트 조성을 위한 사업 추진방안을 제안하였습니다.
</p>
<p style="padding-left:1.2em">  그리고 세 번째는 21세기 서해안 발전거점화 구상입니다. 중앙정부의 서해안 발전종합계획에 서해안 전략특구 조성방안을 반영하였고 세부 추진전략으로 미래 경기도 서해안 발전거점 구축을 위한 서해안 간척지 활용방안을 제시하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 12쪽입니다. 두 번째 중점사업으로 지방자치ㆍ지방분권 강화입니다. 이와 관련하여 지방행정체제 개편 특별법에 대한 후속대응, 한국의 조세체계 분석과 국세 대 지방세의 합리적 조정방안, 경영평가를 통한 공공기관의 역량강화 등의 연구를 수행하였습니다. 먼저 지방행정체제 개편 특별법에 적극적으로 대응하기 위해 대도시 행ㆍ재정 특례 대안을 제시하였습니다. 지방행정체제 개편 특별법에서는 재정보전금과 별도로 인구 50만 이상의 시에서 징수하는 도세 중 10% 이하의 범위에서 일정비율을 대도시에 교부하여야 합니다. 이렇게 되면 최대 2,540억 원을 추가로 교부해야 되고 이는 도 가용재원의 40%에 해당하므로 경기도의 재정운영에 심각한 문제가 발생됩니다. 이에 대한 대안으로 이양사무 관련 예산만 대도시에 지원하는 방안, 대도시 지원에 따른 재정결손분을 중앙정부의 특별교부세, 부동산교부세 등으로 보전하는 방안 등 대도시 행ㆍ재정 특례에 대한 대안을 제시하였습니다. 그리고 도의 지위와 기능 재정립 방안과 관련해서는 중앙정부의 핵심적인 권한을 발굴하여 시도에 이양하는 방안 등을 제시하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 한국의 조세체계 분석과 국세 대 지방세의 합리적 조정방안입니다. 현재 국세 대 지방세의 비율은 80 대 20으로 지방재정이 매우 취약한 형편입니다. 이에 대한 대안으로 지방소비세 세율인상, 소방사무 국비지원 등 지방세 관련 경기도의 대안을 중앙정부에 제시하였습니다. 또한 부동산거래 활성화를 위한 중앙정부의 취득세 감면정책에 대해 지방 개별소비세 신설, 국세와 지방세 세목교환 등 대응논리를 제공한 바 있습니다. 그리고 세 번째 경영평가를 통한 공공기관의 역량강화와 관련해서는 공공기관 경영평가 업무를 GRI의 명품브랜드사업으로 육성하고자 합니다. 경기도 공공기관과 시군 공기업에 대한 경영평가를 통해 CEO의 기관운영에 대한 경영마인드 도입 및 경영효율화 증진에 기여하고 있다고 판단하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 14쪽입니다. 세 번째 중점사업인 동반성장을 위한 지역발전전략 수립과 관련해서는 DMZ 세계평화ㆍ생태 거점조성 추진, 경기북부 발전을 위한 특정지역 도입, 경기도 자영업 활성화를 위한 연구를 수행하였습니다. DMZ 세계평화ㆍ생태 거점조성 추진을 위해 중앙정부, 강원도와 협력하여 지난 9월 UNESCO에 DMZ 생물권보전지역 지정 신청서를 제출하였으며 내년 6월에 지정여부가 결정될 예정으로 있습니다. 생물권보전지역 지정이 이루어지면 DMZ 지역은 법적으로 보호해야 하는 핵심지역, 특화마을 조성과 생태탐방ㆍ교육ㆍ연구사업을 할 수 있는 완충지역, 생태관광ㆍ친환경사업을 육성할 수 있는 전이지역 세 가지로 구분하게 되어 생물다양성 보존과 지역사회 발전에 크게 기여할 것이라고 예상하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 경기북부 발전을 위한 특정지역 도입입니다. 핵심내용은 경기북부의 풍부한 역사자원을 활용한 문화관광 활성화와 지역개발 인허가 행정절차 간소화입니다. DMZ와 임진강에 역사문화벨트를 구성하는 특정지역 도입을 통해 경기북부의 역사적 가치와 자원을 재발견하고 남북관계 개선 시 DMZ와 임진강유역을 남북관광의 중심지로 조성하는 방안을 제시하였습니다. 또한 연천지역의 역사문화 보전사업을 특정지역과 연계 추진하는 방안을 제시하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 16쪽입니다. 경기도 자영업 활성화를 위하여 경기도 자영업자의 경영애로사항을 분석하고 산업육성을 통한 임금근로자 취업기회 확대, 무분별한 진입의 억제와 원활한 퇴출지원, 신용카드 수수료 인하 등의 경영환경 개선방안 등 자영업 활성화를 위한 정책을 제안하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 네 번째 중점사업인 글로벌 산업경쟁력 강화 및 일자리 창출입니다. 이와 관련하여 FTA 효과 극대화, 서비스업 육성을 통한 일자리 창출, 신레저산업 및 중국인 관광객 유치 활성화 방안 등의 연구를 수행하였습니다. FTA 효과 극대화를 위하여 한미, 한중, 한ㆍEU FTA에 대한 총체적 접근을 통해 경기도 차원의 정책방안을 마련하고 중앙정부 정책건의를 통해 경기도의 FTA 이익 극대화와 경기도의 업종별 대응과 수요자 입장에서 심도 있는 대응방안을 제시하는 연구를 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음으로 서비스업 육성을 통한 일자리 창출입니다. 이제 제조업을 통한 일자리 창출은 한계에 도달한 상황입니다. 따라서 문화ㆍ녹색ㆍ사회서비스 등에 대한 일자리 창출방안을 제시하였습니다. 이를 위해 경제구조의 혁신, 패러다임 전환을 위한 창조경제 개념의 도입과 활성화 방안 제시, 사회적기업ㆍ커뮤니티 비즈니스 활성화를 위한 대안 등의 연구를 수행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 18쪽입니다. 신레저산업 및 중국인 관광객 유치 활성화와 관련해서는 소득 2만 불 시대에 새롭게 등장하는 요트, 캠핑, 경비행기, 승마 등의 신레저산업의 활성화 방안을 제시하고 중국인 관광객의 급증세에 따른 중국인의 여가관광 트렌드 분석 및 경향을 전망하여 계층별, 주요 사회지표별 중장기 대응방안을 제시하고자 연구를 수행하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 다섯 번째 중점사업인 의정발전을 위한 교류협력 및 정책개발 강화입니다. 지방자치 발전을 위한 지방의회의 역할, 권한 등 다양한 주제로 의정포럼, 전문가 토론회, 의정세미나 등을 개최하여 의견교환의 장을 마련하였습니다. 또한 지방의회 의정비제도 개선방안 연구를 통해 의정활동의 물적 기반이 되고 있는 의정비제도의 문제점 분석과 지방의회 의원의 안정적 보수제도 방안을 제시하는 연구를 수행하였습니다. 그리고 경기도의회 홍보전략과 관련해서는 경기도의회의 의정활동 전파와 주민들의 알권리 충족을 위한 홍보전략 개발을 위한 연구를 수행하여 정보유통기능 강화, 도민들과의 소통ㆍ연계 강화, PR활동 전문성 강화 등의 방안을 제시하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 20쪽 여섯 번째 중점사업입니다. 도민의 삶의 질 향상을 위한 정책개발과 관련해서는 수도권 광역대중교통 개선, 민군 협력을 통한 삶의 질 개선 및 재산권 확보, 복지전달체계 개편, 도민을 위한 자연ㆍ환경대책 수립 등의 연구를 수행하였습니다.
</p>
<p style="padding-left:1.2em">  먼저 수도권 광역대중교통 개선 분야입니다. 광역버스 차내 혼잡 개선을 위해 대화역-서울역, 사당역-수원역, 강남역-경희대까지 3개 노선에 2층 버스 도입방안을 제시하였고 현재 서울시, 국토해양부, 수도권교통본부와 협의 중에 있습니다. 경기도 내 철도망 조기구축 정책지원과 관련해서는 광역철도 연장노선, 사업 우선순위 등 논리개발 지원을 통해 서울 5호선은 예비타당성이 통과되었고 서울 6호선 및 인천 2호선은 예비타당성조사를 신청한 상태입니다. 또한 광명ㆍ시흥 보금자리주택에 도시철도 대안을 제시하였으며 고양, 부천, 오산, 파주, 성남 등에 지자체가 추진하는 철도기본계획을 수립 중에 있습니다. 그리고 수도권 수요대응형 버스서비스 도입방안을 제시하여 여객자동차운수사업의 종류에 수요대응여객자동차 운송사업을 추가하는 법률 개정안을 제시하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 민군 협력을 통한 삶의 질 개선 및 재산권 확보입니다. 퇴직한 군 장성들로 이루어진 저희 민군정책팀은 수원비상활주로의 수원공군기지 내 이전을 추진하여 지난 10월 5일 경기도ㆍ수원시ㆍ화성시와 공군 간의 합의서를 체결한 바 있습니다. 이는 경제적으로 2조 6,861억 원에 달하는 소득창출 효과에 해당합니다. 또한 김포시 도심의 장릉산 군기지의 개방을 위해 김포시와 공군 간의 협약서를 지난 9월 8일에 체결하였으며 기지 외곽의 7∼8부 능선의 둘레길 조성, 한강 조망대 설치와 주변의 지뢰제거, 산사태 우려지역 방재공사를 추진하기로 하였습니다. 그리고 구리시 사노동 일대의 고도제한을 완화하는 등 지역개발 장애요인을 해소하고 도민들의 재산권 확보를 위하여 열심히 노력하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 22쪽입니다. 복지전달체계 개편과 관련해서는 경기도 특성 및 수요자 맞춤형 복지전달체계 모델을 통해 평균수명 100세를 대비한 노인복지 비전 수립, 무한돌봄사업 발전방안, 무한돌봄센터와 일자리사업 연계방안, 조부모세대와 손자녀세대 간 갈등완화를 위한 공감 프로그램 등을 제안하였습니다. 복지쟁점 분석 및 다양한 정책대안을 위해 경기복지재단과 공동으로 협업연구를 진행 중에 있습니다.
</p>
<p style="padding-left:1.2em">  다음 도민을 위한 자연ㆍ환경대책 수립과 관련해서는 장마철 홍수대책을 마련하여 매년 홍수로 인한 인명과 재산피해 방지를 위한 단기 및 중장기 대책을 제시하였습니다. 또한 대기오염물질 배출 총량관리 및 수질오염 총량관리를 위한 정책연구도 함께 수행 중에 있습니다. 지난 겨울 축산업뿐만 아니라 우리나라 경제를 크게 위협한 구제역과 관련해서는 매몰지 관리를 위한 현황분석도 작성, 매몰지 관리 및 모니터링 방안 제시, 구제역 이후 경기도 축산업 방향제시 등 적극적인 연구를 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 24쪽입니다. 일곱 번째 중점사업인 신속한 도정현안 대응과 현장밀착형 시스템 구축입니다. 저희 연구원은 현재 이슈와 진단, GRI 현안분석, 정책제안, 정책이슈 등을 통해 경기도의 다양한 현안에 신속 적절하게 대응하고 있습니다. 이슈&진단과 정책제안의 사업성과는 아래의 연구사업 유형별 언론보도 현황을 보시면 알 수 있듯이 총 765건의 연구사업에 대한 언론보도 중 이슈&진단이 207건, 정책제안 114건이 보도되었습니다. 그리고 이슈&진단과 각종 연구보고서는 수시로 우편 또는 이메일로 의원님들에게 제공하여 드리고 있습니다. 또한 현장밀착형 정책세미나를 개최하여 경기도 축산업의 방향제시, KTX광명역 활성화 대책, 지역건설산업 활성화 등 경기도와 시군의 주요현안사항에 대하여 현장중심의 신속한 대응을 위하여 노력하고 있습니다. 마지막으로 아래의 도표는 2011년 연구결과에 대한 정책반영 실적으로 도 정책기조의 변화 및 개발 30건 등 5개 분야에 대하여 총 92건의 정책반영 성과를 이루었습니다.
</p>
<p style="padding-left:1.2em">  다음은 26쪽의 2011년 연구사업 추진실적 총괄에 대해 보고드리겠습니다. 2011년 연구과제사업으로는 기본연구과제 20개, 정책연구과제 90개, 수탁연구과제 45개 그리고 협약연구과제 5개 등 총 160개의 과제를 계획하여 9월 30일 현재 이월과제를 포함하여 187개의 연구과제를 수행하고 있습니다. 2011년 남은 기간 동안에도 경기도의회와 경기도정을 위한 정책개발을 위하여 최선의 노력을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  다음 연구부대사업, 연구지원사업, 그리고 연구기반사업은 자료로 대신하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 2012년 주요연구사업 계획에 대해 보고드리겠습니다. 보고자료 29쪽부터 40쪽이 되겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 29쪽의 2012년 내년도 연구사업 목표에 대해 보고드리겠습니다. 저희 연구원은 GRI의 비전과 3대 미션의 성공적 추진을 위하여 2012년 연구사업 목표를 경기도 글로벌 경쟁력 강화를 위한 정책개발, 현장밀착형 복지ㆍ교통 및 사회환경시스템 구상, 지속가능 발전을 위한 스마트 경기도 구상으로 설정하였습니다. 그리고 이와 같은 연구사업 목표의 달성을 위하여 17개 중점사업을 선정하여 이를 중심으로 연구사업을 추진할 계획입니다. 중점사업에 대해서는 32쪽 주요사업 계획에서 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 30쪽 연구사업 추진전략에 대해 보고드리겠습니다. 연구사업 추진전략은 2012년 연구사업 목표 달성 및 8대 분야 17개 중점사업을 원활하게 수행하기 위하여 혁신적 변화를 주도하는 창의적 연구, 수요자 중심의 현안대응ㆍ현장밀착형 연구, 조직의 역량을 극대화하는 협업연구 세 가지를 3대 추진전략으로 설정하여 연구사업을 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음 연구사업 추진체계입니다. 연구사업 추진체계는 내년도에도 올해와 동일하게 연구과제사업을 중심으로 연구부대사업, 연구지원사업, 연구기반사업으로 구분하여 추진할 계획입니다. 다만 이슈&진단, GRI 현안분석, 정책제안, 정책이슈 등의 정책현안사업을 경기도정의 다양한 현안사항에 신속 적절하게 대응하기 위하여 기존 연구부대사업에서 연구과제사업으로 변경하여 추진하고자 합니다.
</p>
<p style="padding-left:1.2em">  다음은 32쪽의 2012년 주요연구사업 계획에 대해 보고드리겠습니다. 첫 번째 정책센터에서는 경기도정 관련 국내외 주요이슈를 발굴하고 분석하여 정책방향을 제시하겠습니다. 그리고 2012년 경제ㆍ사회 여건변화에 따른 도정이슈에 대하여 선제적으로 대응하고자 합니다. 이를 위하여 이슈&진단 50건, GRI 현안분석, 정책제안, 정책이슈 100건 등 총 150여 건의 정책현안 분석과제를 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 행정ㆍ의정 분야입니다. 차별적 분권이 가능한 행정체계 개편논리 개발, 재정건전성을 위한 안정적 세수확보 방안 제시, 의정역량 제고와 생산적ㆍ협력적 의정 네트워크 구축 등을 중점적으로 추진하고자 합니다. 이를 위해 2012년도에는 경기도의회사무처 조직의 진단, 지방법인세 도입 타당성 및 방안, 재정역량에 따른 차별적 분권 연구, 공공투자사업에 대한 지방재정영향평가 도입방안 등의 연구과제를 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 34쪽 도시ㆍ지역계획 분야에 대해 보고드리겠습니다. 도시ㆍ지역계획 분야에서는 도시재생정책 및 주택정책 구체화, 사회변화에 대응한 도시정책 구상 등에 대한 연구를 추진하고자 합니다. 이를 위하여 2012년도에는 경기도 도시활력 증진을 위한 도시주택정책 전환, 주택부동산 전망과 주거안정화 정책, 경기도 마을만들기 사례연구, 경기도 동부지역 지원 특별법 제정방안 등의 연구과제를 수행할 예정입니다.
</p>
<p style="padding-left:1.2em">  다음은 교통정책 분야에 대해 보고드리겠습니다. 교통정책 분야에서는 수도권 광역대중교통의 확충, 지속가능한 복지교통ㆍ녹색교통체계 구축에 대한 연구를 추진하고자 합니다. 이를 위하여 경기도 교통정보 융합ㆍ제공 방안 등 연구, 지속가능한 교통복지를 위한 정책방안 연구, 광역급행철도 수요예측모형 개발 및 적용, 미래 교통수단 연구 등의 연구과제를 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 36쪽 환경정책 분야에 대해 보고드리겠습니다. 환경정책 분야에서는 기후변화 및 이상기후 대비 정책방안 제시, 도민건강 위해(危害)에 대비한 정책연구를 중점적으로 수행하고자 합니다. 이를 위하여 경기도 라돈 방사능 피해의 경제성 분석, 경기도 연안의 해양폐기물 관리방안, 수도권지역의 대기오염 위해성 공간분포 분석, 이상기후 대비 다목적 빗물저류공간 개선 및 적용방안 등에 관한 연구과제를 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 경제사회 분야에 대해 보고드리겠습니다. 경제사회 분야에 있어서는 경기도 고용정책과 산업정책의 융합체계 강화, 공공과 민간의 협업복지시스템 구축 등에 대한 연구를 추진하고자 합니다. 이를 위해 한중 FTA의 경기도 파급효과와 대응방안, 경기도 낙후지역 산업육성 방안, 경기도 말산업 활성화 방안, 사회복지시설 기능 다각화 모델 연구, 사회서비스 산업과 일자리 창출 등에 대한 연구과제를 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 38쪽 문화관광 분야에 대해 보고드리겠습니다. 문화관광 분야에 있어서는 창조경제 활성화 및 일자리 창출 증대, 중국인 관광객 1,000만 명 유치를 위한 연구를 추진하고자 합니다. 이를 위해 경기도 관광 중장기전략 구상, 경기도의 외국인 개별관광객 유치방안, 강변레저스포츠 활성화 방안, 외래관광객 증가에 따른 도내 관광호텔 수급분석 및 공급방안 등의 연구과제를 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음은 통일ㆍ동북아 분야에 대해 보고드리겠습니다. 통일ㆍ동북아 분야에 있어서는 통일 및 남북협력 대비 경기도 대응전략 마련, 군관련 지역현안 해소 및 민군 협력 강화에 대한 연구사업을 추진할 계획입니다. 이를 위해 주한미군 지역사회정책의 분석과 평가, 경기도 남북문화관광 교류사업 추진방안, 군관련 현안사항 대응방안 등의 연구과제를 수행할 계획입니다.
</p>
<p style="padding-left:1.2em">  다음 40쪽은 2012년도에 연구원에서 다양한 협업을 통해 중점적으로 추진할 전략과제입니다. 추진할 전략과제는 DMZ 경기북부특구 개발 전략, 경제ㆍ사회 여건변화 대비 경기도 발전 정책개발, 광역경제ㆍ수도권-지방 상생발전 정책개발, 일자리, FTA 연착륙, 서비스업 등 지역경제 활성화 전략, 주택 부동산 전망과 주거안정화 정책, 미래 교통수단과 교통복지 정책, 경기도 관광 중장기 전략 등입니다. 7건의 전략과제는 지난 10월 13일부터 1박 2일 동안 전 연구진이 참여한 경영전략회의를 통해 선정되었습니다. 
</p>
<p style="padding-left:1.2em">  다음은 41쪽의 2012년도 연구사업계획 총괄에 대해 보고드리겠습니다. 2012년도에는 연구과제사업으로 기본연구과제 17개, 정책연구과제 90개, 정책현안분석 150개, 수탁연구과제 48개 그리고 협약연구과제 5개 등 총 310개의 과제를 계획하고 있습니다. 연구부대사업, 연구지원사업 그리고 연구기반사업의 내용은 도표를 참조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음 43쪽의 2011년 연구과제 목록과 56쪽의 2010년 행정사무감사 처리요구사항 조치결과는 허락해 주신다면 자료로 대신하겠습니다. 그리고 이것은 건수 내용이고요. 저희들이 맨데이(man-day) 그러니까 시간 대비는 이 건수하고는 정확히 일치는 안 됩니다. 어떤 사업 같은 경우는, 굉장히 단기적인 사업 같은 경우에는 과제 건수는 많아도 투입된 일자는 좀 적고요. 어떤 과제는 과제가 하나라 하더라도 투입되는 일수는 중장기과제 같은 거는 굉장히 커서 건수만 가지고 저희 연구소의 소위 작업을 나누는 그런 비중으로는 좀 보기 힘든 측면이 있다 이렇게 말씀드리면서 연구사업 총괄계획을 말씀드렸고요. 그리고 일단은 연구원의 주요업무보고를 마치도록 하겠습니다. 경청해 주셔서 대단히 감사합니다. 이상입니다.
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 강득구 </b> 원장님 수고하셨습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위해서 질의는 일문일답으로 하겠습니다. 그리고 질의시간은 1차는 15분으로 제한하겠습니다. 그러면 김현삼 위원님부터 지그재그 식으로 하는 걸로 하겠습니다. 김현삼 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김현삼 위원 </b> 안산 출신 김현삼 위원입니다. 자료 준비하느라고 고생 많으셨고요.
</p>
<p><b>○ 위원장 강득구 </b> 잠깐만요. 양해해 주시면 앉아서 답변해도 좋겠습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 감사합니다. 
</p>
<p><b>○ 김현삼 위원 </b> 보고 잘 들었고요. 행정사무감사 자료 준비하느라고 고생 많으셨습니다. 작년도에 출연금이 10억 삭감됐었는데 그럼에도 불구하고 많은 연구성과를 본 위원이 자료를 통해서 알게 되었습니다. 다시 한 번 고생했다는 말씀을 드리고요. 이 경기개발연구원이 경기도 산하 연구기관으로서 자기 역할을 충분히 잘하고 있다 이런 평가를 먼저 드리면서 말씀을 좀 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  오늘 행정사무감사가 오전과 오후에 걸쳐 진행이 되는데 저는 오전에는 주로 경영에 관한 건을 말씀드리고 오후에는 정책에 관한 행정사무감사를 진행할까 하는데요. 먼저 경기개발연구원에서 진행하는 연구사업 중에 이슈&진단이라고 하는 게 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 있습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 이슈＆진단의 성격은 어떤 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 작년도에 보니까 CEO Report하고 Policy Brief라고 그래 가지고 주간의 현안에 대해서 보고서가 있더라고요. 그래서 동일한 보고서가 두 개 가까이 있어 가지고 이번에 그걸 통폐합해서 저희들의 현안 플러스 중장기 큰 어떤 이슈에 대해 가지고 저희 연구소의 역량을 모아서 매주 한 번씩 발행하는 저희들의 주간보고서입니다.
</p>
<p><b>○ 김현삼 위원 </b> 네. 그 이슈&진단에서 다루는 의제선정은 누가 하는 겁니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 의제선정은 보통 저희들이 목요일 날 부서장 회의를 하거든요. 저희들 아까 나오신 분들하고 부서장 회의하면서 거기에서 각 부서마다…….
</p>
<p><b>○ 김현삼 위원 </b> 그러면 그 부서장 회의에 원장님도 같이 참석하시나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 저도 참석하고요. 참석해서 거기에서 나온 것을 가지고 저하고 같이…….
</p>
<p><b>○ 김현삼 위원 </b> 최종적으로 그러면 원장님이 승인을 하시는 거네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아무래도 제 의견이 많이 반영이 되겠죠. 그렇지만 제 의견도 내고 또 연구부장들 의견도 내서 각 부장들이 문제, 이슈로 올리면 저도 같이 봐 가지고 그렇게 해서 같이 협의에 의해 가지고 결정하는 그런 시스템입니다.
</p>
<p><b>○ 김현삼 위원 </b> 협의를 해서 결정하지만 어쨌든 최종적으로는 우리 원장님께서 결정을 하시는 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희 연구소의 모든 일은 저 원장이 책임을 지고 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 우리 원장님, 취임하신 지가 언제죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 3월 8일입니다.
</p>
<p><b>○ 김현삼 위원 </b> 네, 잘 알겠습니다. 제가 물어보려고 하는 게 7월 달에, 7월 15일 날 포퓰리즘과 재정위기라고 하는 이슈&진단 보고서 작성하신 적 있으시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 있습니다. 있는 걸로 알고 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 포퓰리즘과 재정위기, 5페이지짜리로 제가 기억하는데 간단한 내용에 대해서 기억하고 계신가요? 간단하게.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 포퓰리즘과 재정위기는 최근의 여러 유럽의 위기문제라든지 이런 것이 재정적 위기기 좀 있어 가지고 그래서 재정을 어떤 예산 또는 제약 없이 쓸 경우에는 좀 위기가 오는 것이 아니냐 그런 취지에서 저희들이 한번…….
</p>
