<p><b>○ 김현삼 위원 </b> 인사권자가 궁극적으로는 김문수 지사기 때문에 그것에 대해서 우리 원장께서 말씀하실 때 기본적으로 한계가 있다라고 하는 건 저도 인정하겠습니다만 이를테면 좌승희 전 원장이 이사장을 맡아야 될 만한 특별한 사유가 없는 거죠? 그냥 김문수 지사께서 이사장을 관행적으로 계속 맡고 있어도 별반 차이가 없는 거죠. 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 글쎄, 그것은…….
</p>
<p><b>○ 김현삼 위원 </b> 좌승희 이사장께서, 이사장의 역할에 관해서는 제가 정관을 좀 살펴봤습니다만 이사장이 되고 난 이후에 특별한 어떤 역할이 있었습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아무래도 좌 이사장님 같은 경우에는 명망이 있으신 학자시고 그래서 저희 연구소의 이사장이 된 것에 대해 가지고 저희 연구원을 대외적으로 아무래도 좀 알리고 그러는 데 도움이 되지 않았겠나 생각이 들고…….
</p>
<p><b>○ 김현삼 위원 </b> 이사장에 대한 대우는 어떻죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희 이사장님은 비상근이고요. 승용차하고 기사를 제공해 주고요. 그리고 한 달에 약간의 업무추진비라고 그럴까요, 그것을 제공해 주고 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 약간의 업무추진비가 대략 얼마입니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 200만 원입니다. 
</p>
<p><b>○ 김현삼 위원 </b> 제가 정관이랄지 그리고 이사회 회의록을 쭉 봤어요. 그리고 제출하신 자료 전체를 제가 훑어봤는데 좌승희 전 원장께서 이사장을 맡고 나서 특별히 자동차를 제공받고 기사를 제공받고 월 200만 원의 업무추진비를 제공받을만한 그런 역할을 과연 했는지에 대해서는, 과연 그럴 필요성이 있는지에 대해서는 의문이 드는 게 사실입니다. 그래서 일각에서는 우리 좌승희 전 원장께서, 지금 현재 이사장이죠? 김문수 지사의 어떤 대권행보를 위한 이를테면 싱크탱크의 실제 조직가로서의 역할 이런 것들을 그동안 계속적으로 해오셨던 것으로 언론에서도 보도된 바가 있고 향후에도 이사장을 시키신 이유가 그런 역할에 대한 기대 때문에 그런 것 아니냐, 이런 지적이 있는 것을 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 개인적 김 지사의, 좌승희 이사장께서 개인적으로 어떤 싱크탱크 역할을 하는 건 제가 잘 모르겠고요. 그런데 저희가 최소한도 공식적으로 좌 이사장이…….
</p>
<p><b>○ 김현삼 위원 </b> 자, 우리 원장님!
</p>
<p><b>○ 위원장 강득구 </b> 김현삼 위원님 마무리…….
</p>
<p><b>○ 김현삼 위원 </b> 네, 마무리하겠습니다. 이사장의 변경을 도지사에게 건의하실 그럴 의향은 없으신가요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 만약에 필요하다면 위원들이 이러이러한 의구심을 가지고 있다라는 이야기는 얘기할 용의가 있습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 이상 마치고 오후에 다시 하도록 하겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 다음 장호철 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 장호철 위원 </b> 우리 원장님, 박사님들 행정사무감사 준비해 주시느라고 고생했습니다. 지금 원장님 오시고 오늘 첫 답변하시는 것을 뵈니까, 사실은 제가 의정연구지원센터에 대한 지원이 너무 약하다 이걸 질의드리려고 그랬는데 답변 도중에 말이에요. 포퓰리즘하고 무상급식에 대해서 잠깐 나와서, 전문가들이시니까 하나 질의 좀 드리겠습니다. 사실은 원래 급식문제나 어떤 정책분야에 있었을 때 무상과 유상이라는 단어를 많이 씁니다. 그죠? 유상이나 무상이란 단어를. 그러면 이 포퓰리즘이란 개념을 원장님은 어떻게 보세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 아까 김 위원님께서도 말씀하신 바와 같이 지금 정치적 쟁점이 돼서 사실은 조심했어야 됐다, 우리가 그 타이틀로. 그런 전제하에서 그래서 그냥 정치적 의도 없이 제 개인적으로 느끼는 포퓰리즘은 실현가능성이 없는 정책을 사람들이 좋아한다고 그래 가지고 책임 없이 또는 재원의 뒷받침 없이 하는 정책을 저는 포퓰리즘이라고 개인적으로 이해하고 있습니다. 
</p>
<p><b>○ 장호철 위원 </b> 네. 그러면 또 하나 제가 말씀드릴게요. 주민세금이나 국민세금으로 뭐가 지출되면 공짜입니까, 아니면 세금으로 주는 것도, 사실 무상이란 단어가 없어요. 의무교육이나, 우리 학교에서는 “의무”를 붙였지 무상과 유상이라는 단어가 없었습니다. 그런데 전번 선거상으로 볼 때 지방자치 때 이게 나온 건데, 그래서 포퓰리즘이다 막 이랬지만. 사실은 주민세금이나 이런 것으로 줄 때 무상이란 단어가 사실은 안 되는 겁니다. 무상은 어떤 분이 사회적 기부라든가 사회적 통합 차원에서, 가진 분이 사회복지 차원에서 사회적 약자에게 자기가 개인재산을 기부했을 때 그때 공짜로 아니면 “아, 저 사람이 나를 그냥 주는구나.” 그냥 이란 표현으로 저는 이해하고 있거든요. 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 이 무상급식에 대해서는 경기도에서 친환경급식이라고 지금 하고 있는 걸로 이해하고 있고요. 그래서 무상ㆍ유상이란 얘기는 안 쓰는 걸로 지금 이해를 하고 있고요. 그래서 저는 위원님 의견에 동조합니다. 
</p>
<p><b>○ 장호철 위원 </b> 본 위원이 94년도에 국내산 친환경급식 지원 우수농수산물 지원조례를 주민발의해 가지고 문화관광공보위원회 때 제가 적극 앞장섰었어요. 주민발의 도의회가 전국 최초로 친환경 국내산 우수농수산물 해 가지고 지원조례를, 전국 최초로 조례를 주민발의로 해서 의회와 도와 행정부가 같이 한 걸 기억하십니까? 94년도에 전국 최초로.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 죄송합니다. 제가 좀…….
</p>
<p><b>○ 장호철 위원 </b> 그때 WTO, GATT 3조에 위배된다고 그래서 대법에 제소했습니다. 그때 노무현 정부였을 때. 그래 가지고 2007년도인가 조례안을 개정하면서 국내산을 삭제했습니다. 그래서 다시 친환경급식으로 조례를 바꾸어서 그걸 의회에서 제가  예산결산특별위원장 역임할 때 특별히 지원한 적이 있습니다. 그래서 경기도 급식본부에서 감사패도 받았습니다, 저도. 그때 전례를 보면 일단 우리가 정확히 짚고 가야 될 문제가, 특히 여기 저보다 더 전문가이시고 다 박사님이시고 그래서 어떤 연구결과를 보면 정확하게, 지금 존경하는 김현삼 위원님이 질의하셨지만 이 공공 쪽에서는 정확하게 의제를 하실 필요가 있습니다. 그걸 지적하고 우리 원장님 견해를 좀 들은 겁니다. 그래서 본 위원 같은 경우는 경제나 모든 전문가는 아니지만 종합적으로 봤을 때, 요즘에 그리스 위기라든가 보면 다 3만 불 넘는 국가들이 요새 문제가 되어 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 
</p>
<p><b>○ 장호철 위원 </b> 그게 사람이 그렇습니다. 근본적으로 좀 현금을 만지다 보면 요구하는 쪽이 많게 되어 있습니다. 예를 들면, 본 위원의 개인적인 예를 들면 다 형님들이 돌아가셨지만 제가 첫 결혼했을 때 “형! 나 집 좀 사줘.” 예를 든 겁니다. “땅을 사라.” 7남매 중 막내인데 “너는 땅은 안 사고 무조건 공짜를 바라냐. 넌 정신상태가 틀렸다.” 이러한 우리 돌아가신 큰 형님의 생각도 지금 나고 있습니다. 이 이유가 뭐냐면 어떤 가정이나 국가가 존재하는 이유는 상향평준화가 되어야지 하향평준화가 돼서는 안 된다. 요새 중산층의 몰락이란 위기를 몰고 왔다고 본 위원은 그렇게 생각하는데 원장님 생각은 어떠세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그리스나 유럽의 재정위기는 다양한 요인들이 있기 때문에 그래서 제가 어느 한 원인만 가지고 얘기하기는 뭐하지만 분명히 하여간 예산제약조건을 무시하고 하는 정책은 실현도 그렇고 효과도 상당히 전무하다라는 일반적인 얘기를 좀 드리겠습니다.
</p>
<p><b>○ 장호철 위원 </b> 그래서 본 위원 생각에는 이 공공 특히 연구기관에서는 어느 단어하나 선택할 때는 제가 전자에 말씀드렸지만 유상ㆍ무상이라는 개념이 아니라 정확하게 주민들이 올바른 가치와 판단할 수 있도록 해주셨으면 부탁드리고 어떤 연구과제에서는 소신이 있어야 됩니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 참조하겠습니다. 
</p>
<p><b>○ 장호철 위원 </b> 그러면 본 위원이 원장님의 견해를 들었으니까, 우리 의원님들이  131명입니다. 각 지역을 대변하기 위해서, 경기도정을 견제와 협력하기 위해서, 정책개발하기 위해서 열심히들 하고 계십니다. 6대, 7대도 마찬가지였지만 8대 때 아주 우수한 의원님들이 많이 계십니다. 그런데도 불구하고 우리 의원님들이 전문적인 의원도 계시지만, 요새 보면 주민참여예산제도도 막 다양하게 요구되고 있고 중앙정부에서도 그것을 긍정적으로 정책 반영해야 되겠다라는 걸 아시죠? 주민참여예산제도. 이게 바로 주민대안을 제시하고 주민들의 욕구를 의회에 담아가고 정책에 반영하는 그런 시뮬레이션이 이루어지는 겁니다. 그런데 우리 의원님들이 기능이 막대한, 특히 경기도는 막대한 예산에도 불구하고 본 위원 경험으로 비춰봤을 때는 참 힘든 현실적인 의원 생활을 하고 있다고 봅니다. 어떻게 생각하세요, 원장님?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 굉장히 힘들게 지금…….
</p>
<p><b>○ 장호철 위원 </b> 그런데도 불구하고 우리 경기개발연구원이 먼저 행정사무감사에도  질의했지만 우리 의정연구센터 한 소속이죠? 의원 정책 반영할 수 있는 연구기관이, 직접적인. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 의정연구센터에 연구위원, 선임연구위원이 한 분 계시고요. 그 밑에 박사들 두 분이 계시고 또…….
</p>
<p><b>○ 장호철 위원 </b> 지금 현재 신원득 박사님하고 또 있으세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 밑에 또 연구 위촉으로 초빙연구위원들이 둘 지금 있습니다.
</p>
<p><b>○ 장호철 위원 </b> 아, 의정연구센터에요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 장호철 위원 </b> 제가 의정연구포럼의 위원장인데 저는 한 분이 계신 줄 알고 있는데.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들 체계가 연구위원, 초빙연구위원 또 연구원 이렇게 좀 나누어져 있거든요. 그러니까 소위 연구위원은 한 분 계시고 그 밑에 연구원으로 또 몇 분 계십니다. 
</p>
<p><b>○ 장호철 위원 </b> 얼마 전에 저희가 부산시하고 창원시를 방문했습니다. 의정연구포럼에서 의원님들하고 다녀왔는데 부산시의 연구, 지방자치에 대한 지원 연구센터 그 실이 연구정책실이라고 있어요. 의원들을 지원해 주는 다양한 지원시스템이 되어 있더라고. 그래서 야, 이거 경기도에서 말이야. 대경기도뿐만이 아니라 대한민국을 선도하는 경기도, 막대한 예산과 제일 많은 인구를 가지고 있는 우리 경기도에서 의원들을 지원해 주는 시스템이 이렇게 차이가 나나, 본 위원이 진짜 놀랐습니다. 그래서 우선 예산부터 많이, 요새 막 도세가 줄어드니까 계속 예산도 많이 삭감되는 걸 저도 이해는 합니다만 원장님께서는 우리 의원님들이 의원 연구활동이나 정책활동할 때 지원하는 게 어떻게 더 약하다고 보십니까? 부족하다고 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일단 위원님 말씀 100% 옳으신 말씀이고요. 저희들이 해야 되는데, 저는 이렇게 생각했거든요. 그러니까 저희 GRI는 아까 보시다시피 여러 분야에서 일을 하고 있는데 그래서 모든 분야가 다 의정을 서포트하는 거다. 그래서 모든 부에서 적극적으로 의정을 의원님들하고 서로가 인터액션을 한다든지, 적극적으로 지원을 한다든지 그것을 어느 한 센터에서 할 게 아니고 우리는 모든 연구부서가 한다라는 게 첫 번째 전제고요. 두 번째 그중에서 창구를 의정연구센터가 하는 거지 의정연구센터만 하는 거는 아니다 지금 그렇게 생각하고요. 그래서 그럼에도 불구하고 의정연구센터가 사람이 또 적은 것도 사실이고 그래서 그것을 저희들이 내년에 운영할 때 여러 가지 참작해서 어떻게 하면 더 원활하게, 도의회하고 저희 연구원하고의 활발한 그것이 되도록 그렇게 좀 노력을 하겠습니다. 
</p>
<p><b>○ 장호철 위원 </b> 네. 가령 의정연구센터를 통해서 박사님들 50명 되시는데 지금 제가 연락, 이것 좀 한번 달라고 그랬습니다, 오기 전에. 연구직 박사님들의 현황을 좀 봤는데 정말 제가 책자를 가끔 집에 배달우송된 것을 보면 참 도움도 많이 됩니다. 되는데, 실제 아까 주민에 대한 각 지역마다 특성 있는 31개 시군 의원님들의 다양한 욕구를 채워줄 때, 약간 기간이 제 경험으로 봐서는, 전에 평택항 서부두 본 위원이 비전문직, 최고 판사님들에 의해서 잘못된, 나중에 “다만, 행정적으로 불합리할 때는 재조정할 수 있다.”는 단서는 달았지만 전문적이지 못한 불합치한 단어 때문에 그 주민들이 엄청 고통을 받고 있습니다, 현재도. 그런데 그걸 연구자료를 제가 요청했더니 의회사무처를 통해서 해 달래요. 그걸 제가 받기까지 한 두세 달 걸렸어요. 그때 한참, 제가 평택항 특별위원장 그때 2006년도에 맡았을 때. 그때 좌승희 원장님하고 막 옥신각신도 했고 그럴 때예요. 이런 걸 좀 빨리빨리 각 부처별로 우리 의원님들이 의정센터라든가 박사님, 연구직 2명하고 우리 신원득 센터장님, 박사님을 거기 포괄적으로 집중 배치해서 각 분야별로 131명의 의원님들이 진짜 주민을 대변할 수 있고 우리 도를 견제하고 같이 협력할 수 있는 그런 체계적으로 빨리빨리 될 수 있는 이 정책방향이 연구직 방향 52건 이게 보고자료로 나와 있지만 이것보다, 각 지역마다 특성이 있습니다. 예를 들어 남부 쪽에서 미군기지 이전에 대한 정말 대한민국의 큰 사건도 있는데 불구하고 이게 아직 특이한 이런 게 지금 안 나오고 있어서 제가 자료를 좀 받은 게 있습니다.
</p>
<p style="padding-left:1.2em">  그래서 지금 요새 아까 정책자료 중점사업 1번에 봐도 경기경제자유구역 지정 추진, 그다음에 지방행정구역 개편 특별법 이런 문제는 굉장히 지금 논란의 여지가 많은 그런 정책개발이거든요. 예를 들어서 경기경제자유구역 추진하려면 실질적으로 공공기관인 LH, 국가 공공기관이 벌써 부도위기거나 개인사업체 같았으면 벌써 부도입니다. 그런데도 불구하고 통합 이후로 월 구십 몇억이라는 이자를 내면서, 100억 가까이 이자를 내면서 여태 수용을 하고 있는데 대형 국책사업이에요. 전부 포기로 인해서 이런 황해자유구역 같은 큰 대물류, 중국 대전진기지 전초지역인 이런 평택항 내륙 경제자유지역의 이런 포기로 인해서 우리, 아시죠, 원장님?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 장호철 위원 </b> 그런 포기로 인해서 잘 시책이 이루어지지가 않는데, 국책사업이 이루어지지 않는데 지금 또 경기경제자유구역 지정 추진 이런 부분이 과연 지속 가능한 건지. 또한 지방행정체제 개편 특별법이라는 50만 인구지만 지금 현재로, 제가 5분발언을 본 위원이 9월 16일 날 했지만 3개 시군 통합으로 인해서 우리 경기도는 미금시하고 남양주시도 했지만 우리 평택시ㆍ평택군ㆍ송탄시 통합된 지 16년인데 불구하고 중앙정부에서 약속한 16년 동안 지원은 전무했습니다. 이런 부분이 문제가 산적해 있는데도 불구하고 이게 가능한 건지, 할 건지. 또 창원시에 방문했더니 거기는 법이 또 틀린, 도농복합시 틀린 걸 적용해서 거기는 지원이 굉장히 다양하게 많이 가는, 뭐 미봉책인지 몰라도. 이런 불합리한 통합 전제가 우리 연구원에서는 어떻게 나올 것인지. 지금 또 12년에 있더라고요, 보니까. 지금 지속적으로 하신다고 그러는데, 지금 시간이…….
</p>
<p><b>○ 위원장 강득구 </b> 장호철 위원님 마무리해 주시기 바랍니다.
</p>
<p><b>○ 장호철 위원 </b> 네. 지금 제가 원장님한테 이런 두 가지 부분을, 일단 시간이 다 됐으므로 두 가지만 간단하게 답변 요구하면서 또 추가질의 시간에 다시 하겠습니다. 두 가지 답변 좀 해주십시오.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그 두 가지는 저희 의정연구센터는 하여간 저희들이, 제가 취임하고서도 지속적으로 지금 연구원들한테 주지를 시키는 것 중에 하나가 도정이라 하면 도 집행부도 있고 도의회도 있다. 그래서 두 쪽에 거의 동등한 비중을 가지고 우리가 서포트하자라는 것이 제 방침이고요. 그래서 그것을 지금 상대적으로, 그래서 저희들이 센터를 하나, 부서를 하나 따로 만든 것이고, 그렇기 때문에. 그래서 앞으로도 그것을 어떻게 하면 더 효율적으로 할 수 있는가를 저희는 지속적으로 지금 생각해 가지고 내년에는 올해보다도 더 의정을 잘 서포트하게끔 그렇게 노력을 하겠습니다. 그리고 여러 가지 도 현안에 대해서는 저희가 지속적으로 한번…….
</p>
<p><b>○ 장호철 위원 </b> 연구중점사업 하나하고 두 번째 이런 부분은 지금 분란의 소지가 많은데 불구하고 또 중점 추진해서 대응방안을 마련하시는 게 적극적으로 정책방향이 될 수 있도록 하시고 이제 질의시간이 다 돼서 주한미군기지 이전에 대한 것은 추가질의 시간에 하겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 장호철 위원 </b> 이상입니다, 위원장님.
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 다음 우리 박승원 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 박승원 위원 </b> 반갑습니다. 박승원입니다. 행감 준비하느라고 고생 많이 하셨고요. 작년에 행감 하면서 우리 연구원분들 중에서 각 지역의, 연구원님들이 각 지역에 중심적으로 전문적으로 맡아서 하신 분들하고 각 지역의 도의원들하고 지역현안과 관련해서 토론이나 또 여러 가지 정책대안과 관련해서 여기서 그런 일들을 많이 진행했으면 좋겠다라고 제안했었는데 어쨌든 작년에 KTX광명역 관련해서 토론회 같이 진행해 주셔서 이양주 박사님이나 관계되신 분들한테 감사의 먼저 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  오늘 경기개발연구원 연구시스템 관련해서 질문을 좀 드리려고 그러는데요. 지금 개발원이 설립된 게 몇 년도였죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 1995년입니다.
</p>
<p><b>○ 박승원 위원 </b> 95년. 10여 년 이상의 세월이 흘렀는데요. 제가 자료를 보니까 2008년, 9년, 10년, 11년 현재 이렇게 보면 2008년도 경기도로부터 의뢰받은 연구용역 건수가 25건에 18억 정도 됩니다. 2009년도는 23건에 26억, 2010년도에는 18건에 35억, 2011년 현재는 13건 이렇게 돼 있는데요. 건수는 줄고 예산은 더 높아가고 있습니다. 이런 현상에 대해서 우리 원장님은 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 도 의뢰의 여기 하는 건 수탁과제 중심이고요. 저희들이 돈을 안 받고 도에서 의뢰하는 과제들이 많거든요. 그런 것을 치면 아마 더 많지 않을까 이렇게 생각이 듭니다. 그러니까 지금 큰 용역의 액수는 돈을 받고 하는 과제들이고요.
</p>
<p><b>○ 박승원 위원 </b> 제가 금액 차원 때문에 질문드린 건 아니고요. 점차 해마다 용역건수가 줄어들고 있습니다, 경기도로부터. 그래서 전에 언론에서도 한 번 거론이 됐던 걸로 기억을 하고 있습니다마는 현재 경기도에 약 22개 정도의 출자ㆍ출연기관들이 있습니다. 그 해당 기관들에서 자체적인 연구작업들이 많이 진행되고 있는 건 잘 아시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 박승원 위원 </b> 그래서 경기복지재단에서도 11명의 박사분들이 자체적인 연구작업 진행을 하고 있고요. 또 최근에 보면 경기가족여성연구원에서도 16명의 박사급 연구위원들이 많은 연구활동을 진행하고 있습니다. 그리고 최근에 경기중소기업지원센터에서도 자체적인 연구팀들을 꾸려보겠다고 논의하는 걸로 제가 지금 알고 있고요. 이런 현상들에 대해서 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 다양한 세부기관에서 연구업무를 하는 것은 반가운 일이라고 생각을 하고요, 일단 연구자 입장에서. 그런데 저희 GRI는 어떤 특정분야가 아니라 전반적인 소위 그 종합한다고 그럴까요? 그런 걸 하기 때문에 이 필요성이라든지 이런 것은 아까 용역 같은 경우는 저희들이 돈을 안 받고 하는 게 많기 때문에, 오히려 역으로. 그래서 건수라든지 중요도는 다른 어떤 기관들이 한다고 해서 저희 GRI 역할이라든지 중요도라든지 이런 것은 조금도 줄지가 않았다. 그래서 도에서도 저희들한테 상당히 많이 지금도 자료도 요청하고 이러는 걸로 알고 있습니다.
</p>
<p><b>○ 박승원 위원 </b> 네, 알겠습니다. 최근에 경기도 평생교육진흥원 재단법인을 설립하겠다라고 해서 결정이 됐습니다. 평생교육진흥원이 설립을 하게 되면 또 평생교육과 관련된 모든 자체 정책연구사업들은 자체로 진행을 하겠죠. 올해, 작년에 보니까 개발원에서도 평생교육과 관련된 연구용역사업을 한 서너 건 정도 진행한 걸로 돼 있습니다. 그래서 점점 이렇게 주민의 삶과 직접적으로 연결되어지는 부분들은 자체 출연기관에서 자체적인 독립적 연구시스템들을 점점 강화해 나가고 있는 상황이고 이런 부분들이 점점 더 진행될 것이라고 저는 보고 있거든요. 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 말씀드렸지만 저희 연구원은 그래서 소위 개별 그런 세부적인 특정기관들하고의 그것을 경쟁하자면 안 되고요. 그래서 그런 공공기관들, 다른 기관들이 할 수 없는 그런 것을 계속 해야 될 것이 아닌가. 그리고 또 그런 기관들이 많아질수록 저희들한테 어떻게 보면 경쟁적인 압력도 지금 오는 거고요. 그래서 저희들이 좀 더 정신차려야겠다 이런 생각도 하면서 또 그런 기관들하고의 어떤 협력관계 이런 것도 하면서, 어차피 다 그런 기관들도 경기도를 위한 기관들이기 때문에. 또 저희는 지금 95년부터 생겼다고 그러지만 벌써 한 16년도 더 되는 노하우도 지금 쌓여 있고요. 그래서 어떻게 보면 또 저희들의 책임도 더 크다 이렇게 지금 생각을 하고 있습니다.
</p>
<p><b>○ 박승원 위원 </b> 그래서 본 위원은 경기개발연구원이 지금 정도는 한 번 정도 연구시스템에 대한 구조개편을, 한번 자체적으로 연구해서 구조개편을 해야 되지 않나 이렇게 생각합니다. 그래서 원장님께서 말씀하신 지금 현재 진행하고 있는 거시적인 측면들 있지 않습니까? 경기도의 행정이나 도시계획이나 교통이나 환경이나 경제, 뭐 큰 틀에서의 거시적인 측면들은 계속 해도 무관하다라고 생각합니다. 그런데 현실적으로 지금 도민의 삶의 질과 직접적으로 관련 있는 문화, 복지, 교육, 여성 이런 부분들과 관련해서는 현재 출연기관들이 많이 있고 세부적으로 현장에 주민들의 목소리를 들어가면서 현장의 실무자들이, 현장에서 직접 일하는 사람들이 중심이 돼서 정책개발을 하고 있고 그것이 주민들의 삶에 직접적으로 연결돼 있기 때문에 훨씬 더 의미가 있다라고 생각하고 제가 과거에 개발원에서 진행했던 몇 가지 사업들 중에서 보면 제가 한 가지 예를 들면 한 5년 전에 개발원에서 경기도 평생학습도시 체제에 관한 연구를 한 적이 있었어요. 그걸 잠깐 봤는데 그 연구한 연구자분들이 사실은 전문가분들이 아니셨어요. 그러니까 큰 틀에서 수박 겉핥기식의 자료만 수집하는 형태의 이런 연구들이 종종 있었습니다. 그래서 저는 정말 도민의 삶의 질과 관련된 부분들은 그분들한테, 그런 출연기관들한테 넘겨서 실제로 도민들한테 필요가 되는 정책연구가 될 수 있도록 하는 게 필요하다고 보고, 그래서 전향적으로 개발원 차원에서 이 부분에 대한 자체적인 연구작업이 필요하다고 봅니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 명심하겠습니다. 그리고 저희들도 그런 부분들, 그러니까 우리가 비교우위가 없는 부분들 이런 부분들까지도 저희가 다 할 힘도 없고 그럴 능력도 없거든요. 그래서 출연기관들하고의 그런 생활밀착형이라든지 주민밀착형 이런 것은 저희가 이양할 것 있으면 이양을 하고 또 도움 받을 것 있으면 받고 또 저희가 과거에 가지고 있는 여러 가지 있으면 같이 나누고 그렇게 좀 하고 그리고 지금 위원님 말씀대로 저희들도 앞으로 연구의 내용이라든지 범위 이런 것은 계속 고민을 하고 있습니다.
</p>
<p><b>○ 박승원 위원 </b> 그래서 제가 노파심에서 말씀을 드리는 건데 그럴 리야 없겠지만 어쨌든 저는 개발원이 좀 더 심도 깊게 정책연구사업이 진행되어져야 된다고 보거든요. 그런데 아까 원장님께서 김현삼 위원님께서 질의했던 부분에 대한 답변을 주실 때 이슈＆진단인가요? 일주일에 한 번씩 연구부장님들끼리 모여서 그 주의 관련된 이슈들을 선정해서 정리해서 글도 좀 내시고 하신다고 그러는데 GRI 현안분석도 보면 사실은 거의 유사한 내용들이거든요. 그래서 이제 정말 연구에 집중해야 되는데 너무 현안과 관련해서 너무 즉자적으로 대응하는 게 아닌가. 이것이 자칫 잘못하면, 도민 삶의 질에 정말 필요한 부분의 현안에 대한 진단과 분석이 돼야 되는데 자칫 잘못하면 자꾸 정치적 판단에 이끌려져서 김문수 지사의 어떤 대권을 향한 여러 가지 백작업들을 해주는 형태로 많은 도민들이 의구심을 가질 수밖에 없는 거죠. 그래서 본말이 전도되는 형태가 되지 않도록 되었으면 좋겠다라는 말씀을 드리고 다시 한 번 이 부분에 대한 심각한 검토 그리고 연구, 구조개편을 위한 노력을 다시 한 번 해보시길 부탁을 드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 박승원 위원 </b> 나머지는 이따가 오후에 다시 질문하도록 하겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 박승원 위원님 수고하셨습니다. 다음 우리 정재영 위원님.
</p>
<p><b>○ 정재영 위원 </b> 다른 분들 말씀하시고요.
</p>
<p><b>○ 위원장 강득구 </b> 네, 우리 박용진 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 박용진 위원 </b> 안양 출신 박용진 위원입니다. 행감 준비하시느라고 수고 많으셨습니다. 아까 원장님 처음에 업무보고를 하실 때 제가 쭉 들어보니까 사실 제 요구자료에서도 있었지만 수원의 비상활주로 이전 관련해 가지고 우리 경기개발연구원에서 아까 퇴역장성들 위주로 해서 아마 협상팀이 꾸려졌었나 보더라고요. 맞습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 김동성 박사, 저보다 더 많이 그 문제에 대해서 알고 있는 우리…….
</p>
<p><b>○ 박용진 위원 </b> 아니, 일단 그 전에 그러면 우리 경기개발연구원 조직에서 퇴역장성들로 구성된 조직이 따로 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 있습니다.
</p>
<p><b>○ 박용진 위원 </b> 그 조직이 여기서 어디죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 민군정책팀이라고요.
</p>
<p><b>○ 박용진 위원 </b> 민군정책팀이요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 통일ㆍ동북아센터 안에 있습니다.
</p>
<p><b>○ 박용진 위원 </b> 거기가 지금 여기 보면 어디 정보직에 해당합니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그게 초빙연구원들입니다. 초빙직입니다.
</p>
<p><b>○ 박용진 위원 </b> 아니, 그러니까 여기 보면 연구직, 관리직, 정보직, 기능직 이렇게 있는데.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니, 연구직들입니다.
</p>
<p><b>○ 박용진 위원 </b> 아, 연구직 안에 들어가 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 연구직 안에 들어가 있죠.
</p>
<p><b>○ 박용진 위원 </b> 그분들은 현재 정규직으로 돼 있습니까, 아니면 뭐?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 비정규직들입니다.
</p>
<p><b>○ 박용진 위원 </b> 비정규직.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그러니까 우리가 정규직, 비정규직으로 나누면 비정규직입니다.
</p>
<p><b>○ 박용진 위원 </b> 올해 아마 본예산 때도 그쪽 관련돼서 예산이 편성된 걸로 알고 있는데 그 정확한 인원하고 예산이 어느 정도 됩니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 6명에 5억 정도. 그런데 그 중에서 1명은 저희들이 정규예산으로 하고 나머지는 수탁, 그러니까 저희들이 수탁예산이라는 것은 프로젝트를 해서 돈을 받으면 그 양반들 인건비를 대는 거죠. 그런데 만약에 프로젝트가 없다, 그러면 그 양반들은 재원이 없는 거죠. 그래서 1명 정도가 지금 우리 예산에 돼 있는 겁니다, 일반예산에.
</p>
<p><b>○ 박용진 위원 </b> 한 분이요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 한 분이요.
</p>
<p><b>○ 박용진 위원 </b> 아, 한 분 예산이 5억입니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니요. 우리가 전체예산이 5억인데 그 나머지는, 한 분의 인건비를 제외한 나머지는 수탁, 저희들이 수탁이라면 용역과제를 의미하죠. 용역이라는 것은 돈을 받고서 하는 연구인데 그걸…….
</p>
<p><b>○ 박용진 위원 </b> 그 민군정책팀이 지금 정확히 생긴 게 언제죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 2009년에요.
</p>
<p><b>○ 박용진 위원 </b> 2009년도요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 2009년.
</p>
<p><b>○ 박용진 위원 </b> 올해 이분들 혹시 성과 간단하게 말씀해 주실 수 있겠습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 올해 1월부터 9월까지 그러니까 수원……. 그거 말씀드리기 전에 제가 와서도 이제 군인들이 계시더라고요, 퇴역군인들이. 제가 연전에 아시는 분들이. 그래서 깜짝 놀랐습니다. “여기 이분들이 왜 있냐?” 그래서 물어봤거든요. 그랬더니, 그래서 저도 알았는데 경기도가 일을 하는 데 있어서 군부대하고 상당히 많이 충돌이 되는 모양이에요. 충돌이라기보다는 협의할 일이 많은데 일반 공무원이나 이런 사람들은 군부대조차 들어갈 수가 없다고 그러더라고요. 그래서 이분들을 모셔다가, 이분들을 모시면 이제 그런 게 굉장히 원활해 가지고 어떻게 보면 경기도에서 대군 창구 이런 역할을 하시더라고요. 그게 도에다 놓기 뭐 하니까 저희 연구원에 놓은 게 제가 이해하는 그거고요. 그래서 저는 “이분들이 하는 일이 뭐냐?” 와서 물어봤는데 보니까 한 분이 오관치 박사라고 있습니다. 그 양반이 팀장 격인데 그 양반은 이제 밴더빌트에서 학위도 하시고 그리고 포스코에서 원장도 하시고 그래서 일반 연구원 출신이고. 그 양반이 팀장이 돼 가지고, 그 양반은 이제 저희 연구소 예산으로 하는 거고 나머지 분들은 퇴역장성들, 육군도 있고 해군도 있고 공군 대령도 있고 이런 분들인데 그래서 이런 분들이 그럼 뭘 하는가 봤더니 아까 말씀드린 그런 역할을 하고 그래서 보니까 상당히 의미 있는 일들을 하시더라고요.
</p>
<p style="padding-left:1.2em">  그러니까 예를 들어서 수원비상활주로 이런 거라든지 김포시 장릉산 군기지 개방이라든지 양평 군비행장 민군 공동이용방안 이렇게 제시한다든지 또 군사시설보호구역 내에 고도제한 이런 걸 또 연구한다든지. 그리고 저희들 탄약고 위험반경 대폭 축소방안을 한다든지 또 군사시설 주변지역 지원 및 종전부지 개발을 위한 특별법안도 제출을 했고 또 경기북부 산업체의 국방조달 이럴 때 참여방안 이런 것 해서 경기도민들의 군과 관계된 그런 거 있을 때 저희 연구원들이 생각할 수 없는 또 접근할 수 없는 그런 연구들을 다양하게 하셔서 그래서 저는 의미가 있다 이렇게 생각을 하고 있습니다.
</p>
<p><b>○ 박용진 위원 </b> 그러면 이분들이 올해 완료한 연구성과가 방금 말씀하신 게 다 완료된 사항들입니까, 올해 안에?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 올해 주로 한 실적입니다, 9월까지.
</p>
<p><b>○ 박용진 위원 </b> 9월까지. 방금 나열하신 일고여덟 가지.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 박용진 위원 </b> 다 이렇게 연구가 완료됐고.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 완료됐습니다.
</p>
<p><b>○ 박용진 위원 </b> 따로 이게 다 보고서도 나오고 그랬습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 보고서도 있고 또 이 양반들이 보면 민원해결, 가서 같이 얘기도 하고. 그래서 여기에 열거되지 않은 상당히 많은 민원들을 해결하고 계시더라고요. 그러니까 그런 것도 하고 그래서, 저희가 연구라는 것이 단순하게 글로 써 가지고 보고서 만들고 그런 것만 연구가 아니고 경기도에서 필요로 한, 또 현안이 되는 또 민원이 되는 이런 것도 이분들이 상당히 역할을 하셔서 저는 처음의 생각보다도 ‘제가 모르는 부분이 상당히 많구나! 이런 부분들을 이 양반들이 하고 있구나!’ 이래서 긍정적으로 생각을 하고 있습니다.
</p>
<p><b>○ 박용진 위원 </b> 지금 어쨌든 다른 연구원분들은 연구성과물로 이렇게 평가를 받는데 이분들은 뭐 꼭 그 틀에 맞게끔 평가하는 건 아니겠네요, 그러니까.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다. 그래서 그런 문제라든지 또 아까 말씀드린 7~8개 건수들은 대체적으로 민원적 성격이 굉장히 강하고 또 그런 것도 보고서를 낼 때도 있고 또 그냥 가서 할 때도 있고. 그런데 제가 아까 말씀드린 것은 대체적으로 보고서가 나와 있는 거죠.
</p>
<p style="padding-left:2.4em">    (관계직원, 경기개발연구원장에게 개별설명)
</p>
<p style="padding-left:1.2em">  군관련 협력과제로 일단 보고서 형태로 지금 나온 그런 것도 있습니다.
</p>
<p><b>○ 박용진 위원 </b> 그러면 이분들 올해 활동성과물을 따로 정리를 해서 서면으로 제출을 부탁드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다.
</p>
<p><b>○ 박용진 위원 </b> 그리고 그렇게 본다면 현재 우리 수원비상활주로 이전에 있어 가지고 저희들은 지금까지 경기도 그다음에 수원시, 화성시하고 공군 간의 어떤 협약을 통해서 이렇게 일이 진행돼 온 걸로 알고 있었는데 실제 이분들의 역할이 거의 지대한 역할을 하신 거네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 상당한 역할을 한 거죠.
</p>
<p><b>○ 박용진 위원 </b> 사실 경기도에서 따로 여기의 전문적인 인력이 없으니까 이분들이 실제 역할을 다 하신 거네요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 박용진 위원 </b> 수원비행장이 지금 이번에 이전을 하게 된 가장 근원적인 원인이 무엇이라고 생각하십니까? 이전 결정을 하게 된.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 참고로 이쪽 민군정책팀에 관련된 세부적인 내용은 제가 많은 지식이 없거든요, 지금. 그래서…….
</p>
<p><b>○ 박용진 위원 </b> 아니, 그래도 우리 경기개발연구원의 민군정책팀에서 그런 활약을 했는데 우리 원장님께서 그 내용을 모르시면 안 되죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 그러니까 제가 말씀드리는 것은 보고는 받는데 제가 아까 다른 것만큼은 전문적 지식이 좀 부족하다 이런 건데 일단 소음문제가 많았고요. 거기 소음문제가 많고. 또 지역경제 활성화 차원에서 아무래도 거기가 활주로가 되고 그러면 상당히 중요한 요지에 아무래도 군부대 전용이 되고 그러니까 부지활용문제라든지 또 소음문제라든지 이런 것이 주민들의 숙원이었다고 저는 생각을 하고 그래서, 그런데 보통 우리가 군에 관계된 거다 그러면 성역같이 돼 가지고 잘 건드리지 못했는데 아무래도 이분들이 와서 그런 문제에 대해 가지고 상당히 적극적인 역할을 하지 않았겠는가 이런 생각이 제가 비전문가로서 생각이 든 그런 얘기입니다.
</p>
<p><b>○ 박용진 위원 </b> 저뿐만 아니라 다른 위원님들도 비슷한 생각을 가지고 계시는데 사실 비상활주로 관련돼서 민원이 한 해 두 해 있었던 것도 아니고 계속적으로 소음문제 이런 것 때문에 계속 민원이 끊이지 않았고. 그런데 최근 한 1년 사이에 굉장히 급진전돼서 이게 다 협의가 체결이 됐어요. 그런 과정에서 비상활주로가 공군기지 안으로 들어가는 이런 결정을 하셨고 그리고 거기에 소요되는 총예산 200억이라는 예산이, 경기도가 80억, 수원이 80억, 화성이 40억 해서 총 200억이라는 예산이 전부 다 우리 지자체 예산으로 충당을 합니다. 분명히 이거 비상활주로 같은 경우에는 국가시설인데 국가시설물을 옮기는 데 있어서 국비를 하나도 지원을 받지 못하고 이렇게 일사천리로 진행하는 데 있어 가지고 만약에 그 퇴역장성들이 여기서 어떤 역할을 하셨다면 사실 그분들이 아무래도 군에 인맥도 많고 하시니까 군의 요구대로 거의 끌려다니신 게 아닌가. 실제 지자체의 어떤 대변을 위해서 하신다면 이런 엄청난 양의 예산을 어떻게 한 푼도 국비를 받아내지 못하고 이런 협상결과를 끌어낼 수 있었나 거기에 대해서 의구심이 들지 않을 수 없거든요. 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 이분들이 여기 와 계신다고 해서, 여기가 직장이거든요. 그래서 전 직장의 무슨 이해를 대변한다라는 생각은 저는 개인적으로 안 들고요. 다만 제가 어떻게 생각이 드냐면 이게 계속 현안인데 아무래도 우리나라의 중앙정부라든지 군 같은 경우에는 굉장히, 이런 말씀을 드려도 될지 모르겠습니다마는 고답적이라고 그럴까요? 자기들 주장을 잘 안 굽힙니다, 지자체가 얘기하는 것에 대해 가지고. 그래서 거의 마이동풍일 때가 굉장히 많거든요. 그래서 아마 이게 계속 현안이 됐는데도 불구하고 안 됐는데 그래서 이번에 아마 하면서 타협을 한 게 아닌가. 그러니까 이쪽에 여태까지 현안되는 것을 자기들이 양보하면서 부분적으로 그 이전비용은 아마 지자체 쪽으로 이렇게 해서 서로 분담하는 구조가 되면서 해결한 것이 아닌가라는 것이 제 판단입니다.
</p>
<p><b>○ 박용진 위원 </b> 그런데 이번에 비상활주로가 공군기지 안으로 들어가면서 실제적으로 이 소음문제는 전혀 해결이 안 됐어요. 아시죠? 바로 옆에 붙어 있는데 이 소음문제가 해결되겠습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아무래도 소음이라는 게 옆에다 보통 방음벽을 그냥 하늘 꼭대기까지 설정하지 않는 한 옆에 있고 그러면 소음문제가 좀 있겠죠.
</p>
<p><b>○ 박용진 위원 </b> 결국은 지역의 어떤 민원, 재산권 행사에 대한 그런 민원 정도밖에 해결이 안 되는 꼴인데. 그리고 또 원장님께서 말씀하셨을 때 이게 2조 6,800억에 달하는 경제효과가 있다. 우리 경기개발연구원에서 이거 추정하신 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 저도 이 내용을 받아 봤는데 지금 이게 1번 국도 경수산업도로 주변에 이게 지금 아무리 고도제한이 풀린다고 하더라도 여기 보면 주택은 15층 그다음에 상가건물은 20층 이 정도의 건물을 지을 수가 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 여기서 우리가 어떤 경제적 효과를 할 때요. 미래에 일어나는 일이기 때문에 그걸 정확하게 하지 못하지만 저희가 할 때 보통 주변의 유사한 지역이 어떻게 활용되고 있는가에 대한 가격을 따져서 하는 거기 때문에 그래서 앞으로 향후에 거기에 어떤 건물이 어떻게 생긴다라는 것은 일일이 제가 말씀드리긴 뭐하고요. 여태까지 활용된 그런 가치를 보니까 그 정도 되지 않겠는가라는 하나의 추정치라고 생각하시면 될 것 같습니다.
</p>
<p><b>○ 박용진 위원 </b> 그러니까 원장님도 이 추정치에 대해서는 충분히 신뢰를 하신다 그런 말씀이시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 박용진 위원 </b> 우리 작년에 G20정상회의 할 때 경제효과가 24조에서 많게는 450조까지 추정을 했는데 다들 거기에 대해서 좀 의아하게 생각하는 부분이 많이 있습니다. 아무튼 지금 질의시간이 거의 다 됐는데요. 저는 이분들이 이번 수원비행장 이전에 있어 가지고 어떤 결정적인 역할을 하셨다는 사실을 오늘 처음 알게 됐습니다. 저는 경기도나 우리 수원ㆍ화성에서 이렇게 전문적인 인력이 있었는지 모르겠지만 어쨌든 이분들의 아까 제가 요청한 연구자료에 대한 성과물 제출을 부탁드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 나중에 제출하겠습니다.
</p>
<p><b>○ 박용진 위원 </b> 오후에 다시 보충질문 하겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 다음 우리 임병택 위원님.
</p>
<p><b>○ 임병택 위원 </b> 안녕하십니까? 시흥 출신 임병택 위원입니다. 원장님, 언제 취임하셨습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 올해 3월 8일.
</p>
<p><b>○ 임병택 위원 </b> 오시면서 우리 경기도의 과제 중에 원장님께서 참 중요한 과제는 이러한 것들이 있다라는 것 한 두세 가지만 우선 말씀을 해주시겠어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일단 우리 지자체가 지금 지자체 선거도 하고, 소위 말해서 지자체를 갖다가 95년도부터 새롭게 시작을 했는데 상대적으로 재원이 대개 부족하다. 쓸 수 있는 돈들이 굉장히 부족하다. 저희가 지방세하고 아까 국세 얘기했는데 국세와 지방세의 세입비중이 80 대 20. 그런데 이게 95년 시작할 때보다도 더 갭이 늘어났습니다. 그래서 지방자치가 되는데 오히려 지방세수는 줄어들고 그래서, 이 지역이 특히 경기도 같은 경우에는 우리나라의 축소판이고 상당히 수도권이고 우리나라 인구의 1/4 정도 되고 경제력도 그 정도 되고 그러는데 거기에 걸맞은 세수입 권한이 굉장히 없다. 그래서 이것을 최소한도 6 대 4 정도로 바꿔야 되는 것이 아니냐 그런 생각이 들고요, 첫 번째는. 두 번째는……. 그건 이제 세수입 측면이고.
</p>
<p style="padding-left:1.2em">  그리고 두 번째는 또 역시 재정 측면인데요. 소위 권한이 굉장히 없더라고요, 도의 권한이. 대부분 다 중앙이 가지고 있더라고요. 심지어 예를 들어서 그린벨트 해제권한도 그렇고 택지개발권한도 그렇고. 이제 그래서 그런 권한 같은 것도 가져야 되는 것이 아니냐. 그런 권한의 이양문제 이런 것도 굉장히 중요하고요.
</p>
<p><b>○ 임병택 위원 </b> 네, 알겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 또 수도권하고의 연계문제, 서울하고의. 그런 게 굉장히 중요한 것이 아니냐.
</p>
<p><b>○ 임병택 위원 </b> 저는 제가 판단하기에 그런 거시적인 우리 경기도의 과제들이 있죠. 있는데 당장 제가 원장님께 말씀드리고 싶은 것은 당부의 말씀입니다. 원장님이 좀 아셔야지 관심을 가지고 좀 하실 수 있지 않을까 싶습니다.
</p>
<p style="padding-left:1.2em">  저는 뉴타운이야기를 하고 싶습니다. 경기도 뉴타운이 발표되고 12개 시의 23개 지구 100만 명에 가까운 이해당사자가 뉴타운지구 경기도민으로 살아갔습니다. 단순히 그 지구만의 문제가 아니라 그 연접한 이웃 도민들에게도 직접적인 영향을 미치는 사업이거든요, 뉴타운사업이. 그런데 2006년부터 시작된 뉴타운사업이 이제 5년 가까이 됐습니다. 그런데 올해 들어서 우리 경기도는 이제 본격적인 출구전략을 시행하고 있습니다. 그래서 안 될 곳은 정리하고 넘어간다라는 그런 분위기거든요. 지금까지 경기개발연구원은 뉴타운을 성공시켜야 된다라는 일념하에 연구과제들을 수행해 왔습니다. 제가 뉴타운 관련된 경기개발연구원 연구현황을 받아봤습니다. 2007년, 2008년, 2009년, 2010년까지 뉴타운 추진전략계획 그다음에 주거안정지수 개발 등등등 이러한 뉴타운을 성공시키겠다는 일념으로 연구과제들을 수행해 왔는데요. 지금은 2010년도에는 뉴타운과 관련된, 그렇게 많은 분들이 이해당사자임에도 불구하고 2010년도에는 뉴타운과 관련된 연구가 전혀 없습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 작년도요?
</p>
<p><b>○ 임병택 위원 </b> 아, 2011년도 올해. 이제 원장님, 그 뉴타운 관련된 문제점에 대해서 원장님이 인식하시는 기본적인 개념을 좀 여쭙고 싶네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 제가 올해도 사실 뉴타운은 굉장히 소위 민감해 가지고요. 외부에 공포를 못했지 저희 내부적인 보고서는 꽤 있습니다, 제가 와 가지고. 저는 뉴타운 문제는 이렇다고 봅니다. 사람들한테 너무 희망을 부르는 프로젝트였다, 개인적으로.
</p>
<p><b>○ 임병택 위원 </b> 그렇죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 이게 경제사정이 안 좋아지고 집값이 떨어지면서 상당히, 그리고 이 뉴타운 할 때 비용분담이라든지 이런 것도 제대로 알려주지도 않고, 주민들한테. 그래서 이게 마치 황금알을 낳는 거위처럼 인식이 들어 가지고 그랬는데 저는 그래서 제가 취임하고 난 다음부터는 뉴타운의 정확한 실상을 알려서 그리고 거기에 대한 비용분담이나 이런 거를 정확하게 주민들한테도 알리고 도한테도 그 기준을 알려 가지고 그래서 분명한 기준을 제시하자, 제 방침은 그렇고요. 그래서 이 뉴타운을 저희는 올해 들어와서는 뉴타운을 하자, 말자 이런 것이 아니라, 그래서 저희는 뉴타운 전체에 대해 개별적으로 비용까지도 지금 계산해 놓은 게 있거든요. 그래서 계산도 하고 이래 가지고 굉장히 뉴타운문제에 대해서는 저희가 소위 말하면 출구전략이라면 출구전략이라고 그럴까요. 이런 거를 올해도 굉장히 신경을 써서 지금 저희들이 하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 저는 경기개발연구원이 우리 경기도민 내지 우리 경기도의 싱크탱크로서 이미 그러한 부분에 대한 대안들이 좀 나왔었어야 했다라고 저는 봅니다. 물론 메가시티도 중요합니다. 동북아에서 경기도의 위상을 높이겠다라는 거시적인 발전전략도 중요하지만 실질적으로 경기도민의 복리증진과 관련된 부분에 대해서 좀 더 밀착해서 연구하고 오히려 경기도를 이끌어갈 수 있는 그런 정책을 개발하고 선도해 나가는 그런 경기개발연구원이 됐으면 좋겠습니다. 그래서 저는 좀 더 용기 있게, 아까 김현삼 위원님께서도 말씀드렸지만 뭐 포퓰리즘 관련된 보고서도 내시면서 참 용기 있는 연구결과물이라고 저는 보여집니다, 저는 동의할 수는 없으나. 그러나 실질적으로 삶의 질과, 경기도민의 삶의 질과 직접적으로 연관되는 이 뉴타운문제에 대해서도 좀 더 경기도 집행부를 견인해 낼 수 있는 그런 자료들을 좀 생산해 주시기를 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 그래서 저희들이 내부적으로는 간단히 말씀드리면 도의 담당하는 분들하고 저희들이 투닥투닥 거리기도 하고요, 입장이 틀리니까. 그런데 그런 것을 저희들이 외부에 이렇게 공개하는 건 좀 그렇고 그래서 저희 내부적으로는 상당히 뉴타운문제에 대해서 여러 도에 실질적인 도움이 되는 그러한 연구들을 하고 있었다 이렇게 말씀드립니다. 그리고 지금 위원님 말씀하신 것 챙겨 가지고요, 계속…….
</p>
<p><b>○ 임병택 위원 </b> 결과물이 나와야 될 것 같습니다. 결과물이 없습니다. 2011년도 결과물은 전혀 없고요. 2012년도 업무계획 속에는 포함되어 있습니다. 최대한 빨리 나와야 될 것 같습니다. 뉴타운이 해제된다라고 그래서 문제가 풀리는 게 아니에요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다.
</p>
<p><b>○ 임병택 위원 </b> 서울시정개발연구원 같은 경우에는 휴먼타운 내지는 소규모 정비방식 등의 대안들을 내놓고 있습니다. 우리 뉴타운지구 주민들이 해제된 곳에 우리는 어떤 대안이 있냐. 현재로서는 경기개발연구원에서 그 어떠한 대안도 제시한 적이 없습니다, 해제된 곳에 대해서. 그분들은 4년 동안 경기도를 믿고 본인의 재산권을 의탁했던 분들이신데 이제는 안 되니까 포기하겠다. 경기개발연구원 싱크탱크라는 곳에서 그 어떠한 대안도 제시하지 않고 있는 현실이에요. 저는 필요하다라고 봅니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 임병택 위원 </b> 저는 경기개발연구원이 독립된 연구기관으로서 좀 더 잘하셨으면 좋겠어요. 그런 차원에서 후속된 질문 좀 드리도록 하겠습니다. 일단 우리 좌승희 원장님 관련된, 좌승희 이사장님과 관련된 부분은 김현삼 위원님께서도 말씀을 주셨는데요. 제가 이사회 회의록을 봤습니다. 이사회 회의록을 쭉 훑어봤는데 3월 8일 날 임시이사회에서 좌승희 원장님께서 이제 선임이사로 되시고, 그 자리에서 선임이사로 되시고 곧바로 그 자리에서 이사장까지도 임명이 되셨더라고요. 3월 6일 날 우리 원장님도 그날 처음으로 이사회 승인을 받으신 거죠? 3월 8일.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇죠. 제가 먼저 하고 그다음에 이사장 저기가 있었습니다.
</p>
<p><b>○ 임병택 위원 </b> 일단 작은 문제점일 수도 있지만 저는 이사장님으로 좌승희 원장님께서 곧바로 그 자리에서 선임이사가 되시고 선임이사에서 다시 이사장으로 되신 과정이 너무 급박했다라고 보여져요. 원래 우리 정관에 의하면, 경기개발연구원 정관에 의하면 정관 14조3항입니다. “선임직 이사는 원장이 학계ㆍ산업계 등의 추천을 받아 이사회의 의결을 거쳐서 경기도지사가 임명하는 자가 된다.”라고 되어 있습니다. 그런데 이사회 회의록을 보면 이사회 의결은 거쳤어요, 그 자리에서. 그러나 그 이후 요건인 경기도지사의 임명절차는 거치지 않았습니다, 그죠? 혹시 정관 보실 수 있으세요? 정관 14조3항. 정관을 지금 못 보십니까? 누구 저기 실무적으로 좀, 이게 실무적인 문제라…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 볼 수 있습니다.
</p>
<p><b>○ 임병택 위원 </b> 이사회 의결을 거쳐 경기도지사가 임명하는 자가 되는 거죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그런데 좌승희 이사님 같은 경우에는 바로 그 자리입니다. 원장에서 선임직 이사가 돼요. 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그런데 선임직 이사가 되기 위해서는 의결을 거쳐서 경기도지사가 임명을 해야 되잖아요. 그런데 경기도지사의 임명절차가 빠져 있습니다. 그죠? 이사회 회의록을 보면 곧바로 도지사의 임명절차도 거치지 않은 사람을, 그러니까 선임직 이사가 안 된 거죠, 최종적으로는. 그런 사람을 곧바로 그 자리에서 이사장으로 임명하게 됩니다. 그런 좀 절차적인 하자가 있어요. 물론 실질적인 요건은 채웠겠죠. 지사님의 승인이라든지. 그러나 형식적인 요건은 채우지 않았습니다. 그런데 저는 이 문제를 지적하는 게 경기개발연구원 조직이 어쨌든 원장 공백상태가, 임기만료가 2월에 되었죠? 2월 14일 날, 좌승희 원장의 임기만료가 2월 14일이었고요. 3월 8일 날 원장님이 취임하셨는데 한 달이란 기간이 붕 떴다라는 겁니다. 저는 참, 이 부분도 이해하지 못하고 그리고 이사장님의 필요성, 김현삼 위원님께서도 말씀하셨는데 경기개발연구원을 대표하시는 분은 원장님이신데 이사장님이란 분이 새롭게 생겼단 말이에요. 그런데 그 이사장님께 경기개발연구원의 사무실을 주고 차량을 주고 기사를 주고 업무추진비를 주고 했습니다. 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다.
</p>
<p><b>○ 임병택 위원 </b> 어떤 근거로 주시는 거예요? 예산집행의 근거가 있으십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 근거는 있는 거고요.
</p>
<p><b>○ 임병택 위원 </b> 있어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 왜냐하면 이사장이니까. 저희들 구조가, 지배구조가 이사장, 원장 이렇게 되어 있거든요. 그리고 감사, 이사장, 이사회 이렇게 돼서. 그런데 정관에는 상임직 상근이사는 원장 하나밖에 없고요. 저도 이사 중의 하나거든요. 상근제 이사는 원장 하나밖에 없고 나머지 이사들은 다 비상근인데 그 이사장에 대한 최소한의 예우 정도로 저희들이 생각하고 있거든요. 그래서 물론 이사장이 없으면 어떠냐, 지금 또 그러신데 이제 그 전에는 지사가, 항상 어느 조직이든 간에 이사가 있고 이사회가 있는 건데…….
</p>
<p><b>○ 임병택 위원 </b> 이제 이사장님에게 지급되는 비용들에 근거가 있다라고 말씀을 하셨는데 근거가 있으면 한번 해석을 하셔서 저에게 전해 주세요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다.
</p>
<p><b>○ 임병택 위원 </b> 근거 없습니다, 근거 없고. 제가 왜 이 말씀을 드리냐면, 이제 본론인데요. 이사장님이, 9월 15일 날 좌승희 이사장님께서 이사회를 또 개최하셔서 하신 말씀을 보면 “매년 이야기할 때 복지포퓰리즘을 많이 이야기합니다만 나쁘게 말하면 좌파 포퓰리즘이지요. 이러한 정부 재정지출 압박…….” 그러시면서 “내년도 가용예산 그다음에 의회에서 무상급식 관련 160억 원을 주냐?” 이런 식의 질문을 하시고 박수영 이사께서는 “1,500억입니다.”라고 말씀을 하시지요. 이사장님께서 제가 봤을 때는 실질적인 원장 역할을 하고 계시는 것 같으세요. 경기개발연구원이 나아갈 방향에 대한 이런 지침도 주시고 좌파 포퓰리즘이란 딱지도 붙이시면서. 그래서 제가 볼 때는 좌승희 이사장님의 역할이 단순히 경기개발연구원을 지켜보는 그런 위치가 아니고 여전히 홍순영 원장님 위에 계시면서 경기개발연구원의 정책기조를 좌지우지하시는 분이 아닌가라는 의구심이 들어서 말씀드리는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그 문제에 대해서 말씀드릴게요. 저희가 그때 정관도 개정했고요. 정관도 지금 부원장, 사무처장을 이사장의 저거인데 그것을 또 뺐거든요. 원장이 하는 거로 되어 있고. 그리고 저는 참고로 말씀드리면 연구원에 일어나는 모든 것은 제 책임하에서, 누구한테 물어보셔도 될 겁니다. 제 책임하에서 하고 그야말로 이사장님은 이사장, 이사회를 개최하고 또 이사회 개최할 때도 안건이나 이런 것은 저희들이 다 하는 거고 그래서 이사장의 제가 무슨 그런 건 아니고요. 제가 전권을 행사해서 지금 하는 거고요. 또 좌 이사장님에 대한 역할이라든지 이런 것은 제가 여기서 이런 말씀을 드려도 될지 모르겠습니다만 좀 과대평가된 측면이 있습니다. 왜냐하면 이 양반이 시장주의자라고 본인이 얘기해서 여기저기서 목소리가 좀 크시기 때문에 그런 게 좀 있는데 그런데 실질적으로 여기에서 무슨 우리 연구원의 앞으로 나아갈 방향을 갖다가 한다든지 이것은 전혀 아니라는 것을 제가 아주 100% 말씀…….
</p>
<p><b>○ 임병택 위원 </b> 좋습니다. 이사장님께 지급되는 그 비용들이 근거가 있다라고 하시니까 그 근거자료를 점심식사 이후까지 제출해 주시고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 임병택 위원 </b> 짧은 거 하나만 더 여쭙도록…….
</p>
<p><b>○ 위원장 강득구 </b> 추가질의 때…….
</p>
<p><b>○ 임병택 위원 </b> 네, 알겠습니다. 추가질의 때 말씀을 드리도록 하겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 다음 권칠승 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 권칠승 위원 </b> 안녕하십니까? 화성 출신 권칠승 위원입니다. 행감 준비하시느라고 수고 많으셨을 거라고 생각합니다. 평소에도 공공기관은 수많은 규정하고 감시 속에서 일을 하셔야 되니까 어려운 점이 많으시리라고 알고 있습니다. 원장님께 좀 묻겠습니다. 지금 현안분석은 이슈＆진단 그리고 현안분석, 정책제안, 정책이슈 이렇게 네 가지로 나눠져 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 현안분석 중에서 다시 또 작은 현안분석 이 주제는 어떻게 정하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 참고로 말씀드리면 이슈＆진단은 저희 연구소의 공식적인 문건으로 나가는 거니까, 외부에. 그래서 아까도 말씀드린 거와 같이 저희 부장 회의에서 결정을 하고 그리고 정책제안이나 이런 것은 각 부서에서 결정해서, 정책현안도 그렇고 그렇게 해서…….
</p>
<p><b>○ 권칠승 위원 </b> 현안분석은 어떻게 하시는지 그것만 좀 답변해 주십시오.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 현안분석도 지금 각 부서장이, 정책센터장이…….
</p>
<p><b>○ 권칠승 위원 </b> 부서장이 원장님에게 보고하고 최종결재…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 사후에 보고할 때도 있고요. 그래서 그렇게 독자적으로 알아서 처리하고 있습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 이 현안분석 자료는 어떤 것은 홈페이지에 있고 어떤 것은 홈페이지에 없습니다. 홈페이지에 없는 것은 왜 그렇습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아무래도 홈페이지에 없는 것은, 저희가 모든 어떤 연구결과를 홈페이지에 띄우는 것이 원칙이기는 하겠습니다만 어느 조직이든 간에 외부에도 좀 알려 가지고 예를 들어서…….
</p>
<p><b>○ 권칠승 위원 </b> 이거 지사님한테 바로 보고하는 것 맞죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지사한테 바로 보고하는 것도 있고요.
</p>
<p><b>○ 권칠승 위원 </b> 알겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그리고 밑에 있는 참모들한테 보고하는 것도 있고, 뭐 같이 합니다.
</p>
<p><b>○ 권칠승 위원 </b> 원장님이 보시기에도 이 현안분석 자료가 2쪽짜리 이런 것들도 많이 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그런 것도 있습니다.
</p>
<p><b>○ 권칠승 위원 </b> 이런 게 기본적으로 깊이 있는 연구분석 자료는 아니다 이렇게 생각하시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇죠.
</p>
<p><b>○ 권칠승 위원 </b> 저는 세 가지 측면에서 이 보고서들에 대해서 좀 문제를 지적하고자 합니다. 첫째는 이게 김문수 지사 개인의 정치ㆍ정무보고서다. 전부 다 그렇다는 뜻은 물론 당연히 아닙니다. 그다음 야당정책에 대한 적대적 시각이 강하다. 그래서 정당연구소 같은 느낌이 좀 든다는 것. 그다음에 세 번째 친기업 시각이 굉장히 노골화되어 있다. 그래서 마치 기업연구소 같은 느낌을 주는 그런 보고서들이 있습니다. 제가 좀 시간되는 데까지 하고 모자라면 보충 때 하겠습니다.
</p>
<p style="padding-left:1.2em">  최근에 제가 보는 견지에서는 이렇습니다. 대외적으로 지사가 정치적인 스탠스를 정하거나 입장을 정리하는 데 혹은 말씀 참고자료처럼 보이는 대목들이 굉장히 많습니다. 물론 현재 우리나라 공무원제도가 단체장들의 정무적인 활동을 보좌할 수 있는 어떤 그런 인적 진입을 못하게 하는 그런 게 기본적으로 저는 문제가 있다고 생각합니다만 현 제도하에서 받아들이고 말씀을 드리겠습니다. 유치원 무상급식에 대한 대응방안이라고 6월 30일 날 작성한 문건이 있습니다.
</p>
<p style="padding-left:2.4em">    (자료를 들어 보이며)
</p>
<p style="padding-left:1.2em">  이겁니다. 기억나십니까? 여기에 보시면, 6쪽에 보시면, 제가 지금 예로 드는 것은 전부 다 홈페이지에 게재가 안 되어 있는 것들입니다. 일부는 되어 있고 일부는 안 되어 있습니다. 전부 다 홈페이지에 게재가 안 되어 있는 겁니다. 여기 6쪽에 보시면 제가 그대로 읽겠습니다. “사립유치원에 대한 의존도가 높고 유치원비의 격차가 큰 상황에서 유치원 전면 무상급식은 부자 무상급식 확대” 이렇게 되어 있습니다.  이것 부자 무상급식의 확대라고 이렇게 딱 정리하는 게 연구보고서, 연구원의 입장에서 적절하다고 생각하십니까? 제가 볼 때는 전형적인 정치보고서입니다.
</p>
<p style="padding-left:1.2em">  다음에, 답변을 하실 게 있으면 하십시오.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아닙니다. 지금 참고로 말씀드리면 제가 다 기억을 하지 못하거든요.
</p>
<p><b>○ 권칠승 위원 </b> 물론이죠. 제가 그러면 보여드리겠습니다. 여기 있습니다. 6쪽에  있는 거 제가 방금 그대로 읽어드렸습니다. “유치원 무상급식은 부자 무상급식의 확대다.”이렇게 딱 되어 있습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 여기 있습니다. 6페이지.
</p>
<p><b>○ 권칠승 위원 </b> 다음에 “한나라당 반값등록금 정책에 대한 평가” 있습니다. 이것도 역시 홈페이지에 없습니다. 제가 자료요구를 해서 받은 겁니다. 여기 보시면 “구체적인 재원조달 방안을 제시하지 않은 채 재정지출 확대를 통한 등록금 인하추진은 포퓰리즘 정책” 이렇게 되어 있습니다. 그것은 조금 전에 원장님이 정의하신 포퓰리즘 정책과 같죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 뭐, 그 문구 자체는…….
</p>
<p><b>○ 권칠승 위원 </b> 네, 이 문구 자체만요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 문구 자체는 누구든지 그건 동의할 겁니다. 
</p>
<p><b>○ 권칠승 위원 </b> 그런데 이 문구 전체를 읽어보시면 반값등록금제를 제안한 민주당의 정책제안이, 주장이 포퓰리즘이다 이런 뜻입니다. 지금 기억을 못하신다니까 즉답을 안 하시는데 제가 그러면 하나만 더 말씀을 드릴게요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이게 한나라당 보고서 아닙니까? 이게 한나라당…….
</p>
<p><b>○ 권칠승 위원 </b> 아닙니다. 뒤에, 한나라당 보고서는 제일 앞에 있습니다. 한나라당 은 25%입니다. 24%, 15%, 24%, 30%이고 뒤에 민주당은 국공립대 50% 인하 있습니다. 그다음에 아까 답변 중에 이렇게 말씀하셨죠? 무상급식과 포퓰리즘, 이렇게 무상급식을 포퓰리즘으로 딱 정의를 내리는 거는 좀 문제가 있다 이렇게 말씀하셨죠? 답변하실 때.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다. 그렇게 되면 무상급식이 포퓰리즘이라는 얘기했죠. 저는 개인적으로 무상급식을 포퓰리즘이라고 생각 안 합니다. 
</p>
<p><b>○ 권칠승 위원 </b> 그건 원장님 개인의 생각이신데요. 경기개발연구원의 최고 경영진들은 그런 생각을 하고 있다고 저는 확신합니다. 66차 임시이사회 회의록에 보면 여기에 의장이니까 좌승희 원장님인 것 같습니다. 좌승희 이사장님이 의장입니다. 이렇게 말씀하셨습니다. “복지포퓰리즘을 많이 이야기합니다만 나쁘게 말하면 좌파 포퓰리즘이지요.” 쭉 가서 “이거 때문에 사실 경기도 재정도 압박을 많이 받고 더 나아가 연구원에도 예산에 많은 장애가 있지 않을까 하는 걱정을 하게 됩니다. 제가 듣기로는 내년도에 가용예산이 4,000억 원 정도밖에 안 된다고 하는데 의회에서는 무상급식ㆍ친환경급식으로 160억 원 입니까?” 이렇게 묻는 대목이 있습니다. 최소한 좌승희 원장님은, 전임 원장님은 무상급식이 포퓰리즘 정책이라고 보시는 거죠? 이 문구의 내용상 그런 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 좌승희 이사장하고 저하고의 어떤 세계관의 차이라든지 이런 거는 충분히 있는 거고요. 또 이 양반이 어떤 그런 생각을 갖고 있다고 그건 본인의 의사, 자유이지 그것을 우리 연구원의 방침을 따른다든지 이런 건 전혀 별개라는 걸 좀…….
</p>
<p><b>○ 권칠승 위원 </b> 그러면 개인의 생각이 연구원들의 연구활동에 전혀 영향을 안 미친다는 말씀이신가요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 최소한도 좌승희 이사장의 생각이 현재 우리 연구원에 미칠만한, 저는 없다고 생각합니다. 물론 개인적으로, 좌승희 이사장을 개인적으로 존경해 가지고 그 양반 말을 따르겠다 이런 연구원이 있을지는 모르겠습니다만 연구원의 방침하고는 전혀 관계가 없는…….
</p>
<p><b>○ 권칠승 위원 </b> 그러면 좌승희 이사장님이 과거 원장인 시절에는 그랬을 수도 있겠다 이런 말씀이시네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 뭐 그럴 수도 있겠죠, 아무래도 원장이니까. 그런데 일단…….
</p>
<p><b>○ 권칠승 위원 </b> 그러면 지금 현재 원장님의 생각은 연구원에 또 투영될 수가 있겠네요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 어느 기관이든지, 저는 솔직히 이야기합니다. 어느 기관이고 기관장의 의견이 투영되지 않겠습니까?
