<p><b>○ 권칠승 위원 </b> 그렇습니다. 제가 그 부분을, 답변을 한꺼번에 하셔도 좋은데요. 제가 지금까지 질문을 드린 게 다 그 내용들입니다.
</p>
<p style="padding-left:1.2em">  그다음에 유치원 무상급식에 대한 대응방향, 아까 보여드린 문건에 대해서 조금 더 말씀을 드리겠습니다. 아, 이거부터 먼저 보여드리겠습니다. “최근 경기도 교육정책 관련 쟁점”이라는 5월 11일 날 나온 문건이 있습니다. 여기에 무상급식 확대는 선심성 정책이다 이런 것들은 빼고 대응방향이라는 게 있습니다. 저는 연구보고서에 이것도 좀 맞지 않은 제목인 것 같은데요. 이렇게 되어 있습니다. “도교육청의 기자회견은 기관장의 정치적 입장을 선전하기 위한 정치적 수단이므로 먼저 나서서 직접적인 언급은 불필요” 이 문구를 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이때 기관장이라는 것은 도지사를 말씀드리겠죠? 의미하는 거겠죠? 제가 좀 정확하게…….
