<p><b>○ 경기개발연구원장 홍순영 </b> 아니요. 가지고 있습니다. 제가 이 내용을…….
</p>
<p><b>○ 권칠승 위원 </b> 이게 어떤 보고서죠? 이게 연구보고서입니까, 아니면…….“이 직접적인 언급은 불필요” 이 언급의 주어가 누구입니까? 도지사죠? 그렇지 않습니까? 
