<p><b>○ 권칠승 위원 </b> 그렇게 말씀하시면, 도지사죠? 그렇지 않습니까? 도지사가 아니라는 겁니까? 그러면 누구한테 보고하셨는데요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니, 그러니까 저희가 도에다 보고할 때는 보통 정책현안, 우리가 이것을…….
