<p><b>○ 권칠승 위원 </b> 뭐를 연구하셨습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 참고로 이 현안에 대해 가지고 말씀을 드리면 일단 위원님 지적하는 바를 충분히 제가 수용한다는 전제하에서 제가 말씀을 드립니다. 저는 여기서 아규(argue)하는 자리는 아니고 저희들이 문제점에 대해 지적을 받고 고치는 자리이기 때문에 그걸 100% 수용한다는 전제하에서 말씀드리도록 하겠습니다. 참고로 저희 현안하고 이런 것은 저희 연구소의 투입이 100이라면 이 현안에 투입되는 것은 1/10밖에 안 된다. 일단 그걸 말씀드리고요, 건수는 많을지 몰라도.
