<p><b>○ 경기개발연구원장 홍순영 </b> 제가 말씀드릴게요. 그리고 그것도 크다면 또, 그런데 우리가 연구를 할 때 연구냐, 이게 조사냐 또 어떤 전략보고서냐라는 것이 대개 혼동스러울 경우가 굉장히 많거든요.
</p>
<p><b>○ 권칠승 위원 </b> 이게 정치전략보고서입니다. 저도 이런 일을 좀 해봐서 굉장히 눈에 익은 문구들이거든요. 제가 그 밑에 것도 읽어드릴게요. “갈등발생 시 혹은 언론인터뷰 등에 대비한 기본적인 입장정리는 필요” 정치적인 상황에서 미리미리 대비하라는 거잖습니까. 이건 누가 해야 되는 일이죠? 지금 현재처럼 정무적인 기능이 공직사회에 들어올 수 없는 상황에서는 도지사의 개인 사조직이 하든가 아니면 당에서 하든가 그렇게 해야 되는 거 아닌가요? 이런 것을 예산으로 움직이는 경기개발연구원에서 한다는 게 이게 말이 됩니까? 어떻게 생각하십니까? 
