<p><b>○ 권칠승 위원 </b> 다음 하나 더 하겠습니다. “무소속 돌풍, 평가와 전망”이라는 것 있습니다. 9월 7일 날 2쪽짜리 보고서입니다. 쟁점 3개 있습니다. 하나. “박찬종ㆍ이인제 등 과거 무소속 돌풍과 어떻게 다른가?” 쟁점 2. “기존 정치와 안철수, 무엇이 다른가?” 쟁점 3. “안철수 신드롬은 계속될 것인가?” 이게 지금 경기개발연구원에서 연구할 내용입니까? 전망과 시사점, “박근혜 대세론 균열 가능성”, “문재인ㆍ안철수ㆍ조국 등 PK 3인방의 약진은 PK의 아래로부터의 반란을 초래하면서 한나라당의 기반약화 및 분열야기 가능”. 이거 전형적인 여의도 찌라시 비슷한 그런 것 아닌가요?
