<p><b>○ 경기개발연구원장 홍순영 </b> 아닙니다. 지금 지적하신 것 제가 100% 수용을 하고요. 그래서 앞으로 이런 부적절한 용어가 안 되도록 제가 철저히 챙기겠습니다. 
