<p><b>○ 경기개발연구원장 홍순영 </b> 네. 지금 이 자료를 말씀하시는 거죠? 지금 한 것.
</p>
<p><b>○ 정재영 위원 </b> 정재영 위원입니다. 95년도에 경기개발연구원이 출발했습니다. 시작은 경기도 도정의 싱크탱크로 거듭나겠다고 출발을 했는데 지금으로부터 한 16년 됐죠? 16년 지난 결과를 이렇게 쭉 살펴보니까 우리 경기도정을 넘어서서 이제는 대한민국의 미래, 더 나아가서는 세계속의 경기도를 지향하는 그런 다양한 연구를 발표하셔서 이제는 우리나라 어느 연구원에 비교해도 손색이 없는 그런 연구원으로 아주 성장했다 저는 자부하고 있습니다. 아울러서 이 연구원장 자리가 굉장히 중요한데 쭉 제가 살펴보니까 초기에는 퇴직공무원들이 그저 잠시 머물다 가는 그런 자리로 이렇게 있다가 또 그 이후에 잠시 정치적인 이런 원장님들이 오셔서 또 정치적인 색깔을 좀 많이 내셨다. 그런데 지금 홍순영 원장께서 몇 대시죠?
