<p><b>○ 정재영 위원 </b> 9대. 그건 기억을 좀 하시기 바랍니다. 9대를 이렇게 홍순영 원장께서 오셨는데 여기 주 프로필에도 보시는 바와 같이 여러 가지 경력을 쌓으시고 또 특히 삼성경제연구소에서 근무를 하셔서 이 내용들이 보면 그저 허황된 것이 아니라 실사구시적인 그런 정책에 기반을 둬서 연구를 많이 한 걸 제가 감으로 이렇게 느끼고 있습니다. 오랜동안 하다 보니까 제가 그렇게 느끼고 있습니다. 이런 차제에 정말 홍순영 원장께서 경기개발연구원 스스로 자평을 한번 해보신다면 어떻게 할 수 있는지 짤막하게 요약을 해서 해주시기 바랍니다. 우리 경기개발연구원에 대한 자평을 한번 해보세요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 우리 연구원을 제가 바깥에서 보던 것보다는 와서 보니까 연구원들도 굉장히 유능하고요. 어떤 다양한 전공의 다양한 전문가들도 많고 그래서 앞으로 앞에서, 위에서 잘만 이끌면 상당히 대한민국 최고의 연구소가 될 수 있다 저는 이렇게 생각을 하고 있습니다.
</p>
<p><b>○ 정재영 위원 </b> 결국은 잘하고 있다, 앞으로 잘할 것이다 그런 말씀이죠?
