<p><b>○ 정재영 위원 </b> 동감을 하는데 하여튼 우리 동료위원님들께서 말씀하신 대로 너무나 정치적인 이런 데 휩싸이시면 연구원 자체의 존립이 근본 목적하고 달라지기 때문에 그런 문제에 대해서 우리 위원님들이 지적하신 문제에 대해서도 항상 염두에 두시고 연구원을 이끌어 주시길 부탁을 드리겠습니다.
</p>
<p style="padding-left:1.2em">  다음으로는 여러 가지 연구과제를 많이 발표를 하시는데 예를 들면 작년도에는, 아니 금년도죠. 160개의 과제를 만들어 내시고 또 내년도에는 그보다 배가 되는 310개 과제를 선정하셔서 의욕적으로 이렇게 연구를 하시겠다고 했는데 그런 연구발표하는 과정을 보면 제가 모르긴 몰라도 과제를 선정하고 또 자료를 수집하고 조사하고 연구하고 또 그 결과를 발표하시고, 중요한 것은 이게 발표까지는 여러분들의 몫인데 과연 이런 몫이, 여기까지 하신 것이 도정이라든지 아니면 대한민국 정치정책에 반영이 돼야 됩니다, 이게. 그래서 도민들의 삶이 보다 좀 나아지고 개선이 돼야 되는데 제가 보기에는 그것까지는 못 미친 것 같습니다. 도민들은 이 정책이, 여러분들이 연구한 결과물이 정책에 반영돼서 그것이 도민들의 삶에 획기적인 변화를 주고 또 보다 나은 개선이 돼야 되는데 그렇게까지 못한 것 같다라고 본 위원은 생각을 하는데 우리 원장께서는 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그 부분에 대해서는 저도 비슷한 생각을 하고 있고요. 저희들이 정책에 최대한도로 반영시키려고 노력을 하고 또 이미 정책에 반영된 게 잘 드러나지가 않거든요. 그래서 체감적으로 좀 못 느끼는 부분이 있는데 그럼에도 불구하고 위원님 말씀하신 것과 같이 좀 더 정책에 많이 반영되도록 저희들이 더 계속 노력을 하겠습니다.
</p>
<p><b>○ 정재영 위원 </b> 뭐 아주 없다라고는 할 수 없겠지만 그래도 그중에서 대표적으로 이런 것이 우리 연구한 결과가 도정에 반영돼서 아니면 국가적인 정책에 반영이 돼서 뭔가 좀 변화가 됐다, 사회의 모든 변화에 한 주도를 담당했다라고 하는 그런 대표적인 사례 있으면 한 가지만이라도 좋습니다. 말씀을 좀 주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 예를 들어서 올해 취득세 감면하겠다고 그럴 때 대부분 저희 지방세 문제거든요. 그래서 그것을 아주 적극적으로 빨리 대응해서 그 문제가 최소한도로 영향을 미치도록 하는 데 저희가 상당히 영향을 줬다고 생각하고요. 그리고 아까 말씀드린 군관계 그런 것, 또 저희들이 굉장히 많습니다. 많아 가지고 그걸 하나하나씩 저희가 말씀드리긴 뭐 하지만 제가 목록을 만들어 가지고 위원님한테 제출하도록 하겠습니다.
</p>
<p><b>○ 정재영 위원 </b> 네. 그런 것은 그렇습니다. 아무리 여러분들이 잘하신다 하더라도 저희 의원들은 거기까지는 저희들이 그 보고를 받을 수가 없어요. 연구원에서 연구한 결과가 정책에 반영돼서 도민을 위해서 쓰여졌다고 하는 그런 결과물에 대해서는 우리가 들은 바가 없어요. 그거 중요한 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 정재영 위원 </b> 부뚜막에 소금이 있다 한들, 뭡니까? 집어넣지 않으면 그거 소용이 없는 소금이 되는 거나 마찬가지로 이렇게 아무리 좋은 말씀을 하시고 연구자료를 만들어도 남들이 알아주지 않으면 공염불에 지나지 않을 것입니다. 그러니까 보다 더 적극적으로, 연구원 과제 쭉 여기 지금 자료를 보니까 전부 그냥 이 한 권이 거의 다 나 잘했다라고 하는 과제물만 쌓아놨는데 이것이 도정에 반영됐다고 하는 근거는 하나도 없어요. 정말 중요한 것을 잃어버렸습니다, 이게. 농사 열심히 지어놓으면 뭘 합니까? 가을 때 지나서 수확하지 않으면 그냥 논밭에서 퇴비로 썩혀지는 그런 경우와 똑같은 겁니다. 그러니까 반드시 수확을 하시면 수확결과물을 공표하시고 더 홍보를 해서, 특히 의원들한테도 이런 것을 해주시기 바랍니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 명심하겠습니다.
</p>
<p><b>○ 정재영 위원 </b> 그래서 연구원이 이만하면 지금 잘하고 계십니다마는 정말 하셔야 될 것은, 우리 홍순영 원장께서 하셔야 될 것은 실사구시 정책을 하셔야 됩니다. 그다음에 실용주의입니다, 이게. 그저 갖고 있으면 뭘 합니까? 실용이 돼야 됩니다, 이게. 우리 도민들이나 모든 정책에서. 그리고 아무리 실사구시, 실용주의 다 좋다 하더라도 실천하지 않으면 그만입니다. 그러니까 실천할 수 있는 실사구시 정책에 의해서 실용하고 실천할 수 있는 이런 원의 많은 연구결과가 나오기를 제가 기대를 하겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 정재영 위원 </b> 그리고 이번에 지방의회 의정비제도 개선에 대해서 아마 자료를 주신 것 같습니다. 급히 집에 가보니까 자료로 이렇게 왔던데 이 문제는 굉장히 시의적절하게 잘 낸 결과물이라고 생각이 되는데 제가 다 읽어보지는 못 했는데, 또 혹시 못 본 위원님도 계신데 이 연구과제로 해서 연구를 하신, 우리 담당 신원득 박사님께서 하셨나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 신원득 박사님.
</p>
<p><b>○ 정재영 위원 </b> 짧게 그 결과가 어떤 내용인지 좀 설명해 주시기 바랍니다.
</p>
<p><b>○ 의정연구센터장 신원득 </b> 경기개발연구원 의정센터장 신원득입니다. 이 과제는 지금 최근에 우리 의원님들이 많이 보셨겠지만 10월 말까지 의정비제도심의위원회에서 결정해 가지고 신문지상에 최근 많이 오르내리고 있습니다. 저는 여기 그동안에 4년 동안 의정센터장을 맡으면서 굉장히 가슴 아프게 생각하고 있습니다. 이 과제의 요점은 딱 두 가지로 요약될 수 있습니다. 하나는 동일하게 의원의 신분, 소위 말해서 주민선거로 인해서 선출되는 특수경력직 정무공무원으로 법에, 규정에 명시돼 있습니다, 지방의원의 신분이. 그럼에도 불구하고 동일한 유사 신분을 가진 자치단체장이나 유사 신분들은 이 고정급제 봉급을 가지고 있습니다. 이 차이점으로 말하면 왜 매년 지방의회 의원들 소위 말해서 월정수당은 타의에 의해서 결정돼야 되는 것인가? 이게 가장 핵심의 화두로 떠오르고 거기에 대해서 두 가지 본질을 제가 규명했습니다. 하나는 과연 이게 보수인가? 보수라 그러면 두 가지 문제를 충족시켜야 됩니다. 하나는 생계급여의 수단을 충족시켜야 되고 나머지 하나는 활동에 따른 수당, 부가적 수당이 지급돼야 되는데 첫 번째 생계ㆍ부가적 급여가 지급되지 않는 것을 실증적으로 보고서에 담았습니다.
</p>
<p><b>○ 정재영 위원 </b> 네. 박사님, 더 상세하게 듣고 싶은데 제가 질의에 할당받은 시간이 다 됐다고 그래서 이하는 나중에.
</p>
<p><b>○ 의정연구센터장 신원득 </b> 간단하게 그럼 두 가지 요점만 결론을 말씀드리겠습니다. 하나는 앞으로 그렇다면 미시적으로는 현재 있는 의정비제도를 고쳐야 되는 것이고 거시적으로는 새로운 보수체계를 마련하려는 것입니다. 새로운 보수체계는 소위 말해서 저희 보고서에는 원가적산에 의한 방식을 하나 채택했고 하나는 시장비교에 의해서 하는 채택을 했습니다. 이 두 가지를 관철시켜야 되는데 아까 정재영 위원님 말씀대로 여기까지는 저희 연구원 몫이지만 이 제도를 바꾸는 지방자치법 개정이라든지 시행령 개정은 또 다른 방향에 있기 때문에 저희 연구원에서는 거기에는 좀 한계를 가지고 있습니다.
</p>
<p><b>○ 정재영 위원 </b> 네, 알겠습니다. 좀 더 상세히 듣고 싶지만 그 정도로 제가 듣도록 하겠습니다. 위원장님, 제가 딱 1분만 더 쓸까요?
</p>
<p><b>○ 위원장 강득구 </b> 네.
</p>
<p><b>○ 정재영 위원 </b> 감사합니다. 오늘 여러 가지 위원님들 말씀 중에 존경하는 김현삼 위원님께서 발제를 해주셔서 논의가 됐는데 포퓰리즘에 대해서 각자의 얘기가 나왔는데 저는 이 포퓰리즘이라고 하는 단어 자체에 대해서 너무 민감할 필요는 없다, 저는 이렇게 생각합니다. 포퓰리즘이라고 하는 게 영어로 해서 포퓰리즘이고 우리 해석을 하면 대중인기영합주의 아니겠습니까? 그런데 대중인기영합주의는 정치를 하는 분들이면 누구든지 그건 할 수 있다라고 저는 생각합니다. 이게 이제 민감한 문제가 아니고 이제는 사회적인, 통념적인, 상식적인 단어가 돼서 애도 알고 어른도 알고 지나가는 소도 알 정도로 모두가 다 아는 내용인데 굳이 이걸 민감하게 우리가 대응할 필요는 없다라고 생각이 되고요. 이것은 좌파니 우파니, 진보니 보수니 모두 다 포퓰리즘에 빠질 수 있습니다, 이것은. 그래서 마치 어느 한 특정한 정당이나 어떤 단체에만 이것이 해당되는 용어인 것처럼 이렇게 해석을 하면 서로가 여기에서 다른 문제가 생기니까 이것을 이런 보수나 진보나 또 좌파나 우파나 이 단어에 대한 알레르기 반응을 일으킬 필요가 없다, 저는 이렇게 생각이 됩니다.
</p>
<p style="padding-left:1.2em">  따라서 정 이게 어렵다고 그러면 이런 연구하시는 데, 저는 이런 것을 우리 위원님들이 말씀하시면 우리 연구원들이 이런 단어에 속박돼 가지고, 구속돼 가지고 앞으로 이 단어를 쓰지 못한다고 그러면 보다 진전적인 게 될 수가 없다는 생각에서 제가 말씀드립니다. 이 단어는 누구를 막론하고 아무 때나 연구원이 그 단어 자체를 쓰지 못한다면 저는 이게 더 큰 문제라고 생각되기 때문에 우리 위원님들이 어떤 정파라든지 정당을 떠나서 이 단어에 대해서는 자유롭게 연구원들이 연구할 수 있는 단어로 사용할 수 있도록 해주시기를 제가 개인적으로 말씀을 드립니다.
</p>
<p><b>○ 위원장 강득구 </b> 네, 감사합니다.
</p>
<p><b>○ 정재영 위원 </b> 이상 마치겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 다음 우리 김주삼 위원님 질의해 주시기 바랍니다.
</p>
<p><b>○ 김주삼 위원 </b> 군포 출신 김주삼 위원입니다. 바로 질의를 하도록 하겠습니다. 우리 김현삼 위원님께서 이슈＆진단 포퓰리즘과 재정위기에 대해서 말씀을 하셨는데 어쨌든 제가 오늘 주요하게 질문을 드리려고 가져왔습니다. 이거 내용 읽어보셨다고 아까 질의과정에서 저는 판단을 했는데 안 읽어보셨더라고요, 우리 원장님께서. 다 못 읽어보셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 다 읽어보지는 않았습니다.
</p>
<p><b>○ 김주삼 위원 </b> 하여튼 이것이 정책센터에서 나온 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습……. 아니, 정책센터가 아니라요. 저희 그거 나오는 것은 저희 연구원에서 나오는 거죠. 연구원 박사 이름으로다.
</p>
<p><b>○ 김주삼 위원 </b> 아니, 그러니까 정책센터라고 우리 원장님이 새로 오셔서 만든 조직이 하나 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그게 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 거기서 나온 것 아닙니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그것은 이슈＆진단의 어떤 호는 거기에서 나오는 게 있고 어떤 호는…….
</p>
<p><b>○ 김주삼 위원 </b> 아니, 그러니까 포퓰리즘과 재정위기에 대한 게 정책센터에서 나온 것 아니에요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 정책센터에서 나온 겁니다. 정책센터의 연구원…….
</p>
<p><b>○ 김주삼 위원 </b> 정책센터장 나와 계십니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 어차피 우리 원장님이 안 읽어보셨으니까 질의응답이 안 될 것 같으니까 좀 나와 보세요. 우리 정책센터 센터장님은…….
</p>
<p><b>○ 정책센터장 김은경 </b> 안녕하십니까? 경기개발연구원 정책센터장 김은경입니다.
</p>
<p><b>○ 김주삼 위원 </b> 읽어보셨어요?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 다 읽어보셨겠죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 아까 원장님 질의 답변 과정에서 원장님이 내용을 잘 모르신다는 것 느끼셨어요?
</p>
<p><b>○ 정책센터장 김은경 </b> 원장님이 워낙 많은 현안보고서를 보시기 때문에 아마 잠깐 잊어버리셨다고 생각을 하시고요.
</p>
<p><b>○ 김주삼 위원 </b> 왜냐하면 중요하게 일단 하나만 제가 잘못, 이해를 못하신 게 무상급식과 관련해서 정확하게 무상급식에 대한 어떤 문제점에 대해서 못 박지 않았다고 그렇게 얘기를 하셨는데 이 자료에 보면 맨 앞부분에 그런 내용이 나옵니다. 아, 맨 앞부분이 아니고 맨 뒤에요. 저는 상당히 이걸 보면서 좀 놀라운 게 맨 마지막 부분에 시사점이라고 나왔을 때 “국민들의 정책이해도 제고를 위한 방안 필요” 하고 “공짜점심은 불가능하다는 사실에 대한 홍보 및 교육 강화”라고 그렇게 돼 있습니다. 그죠? 이건 명백하게 현재 우리 경기도에서 주요이슈가 되고 있는 무상급식에 대한 대응논리로 지금 얘기하신 거죠? 맞죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 아닙니다.
</p>
<p><b>○ 김주삼 위원 </b> 아니에요?
</p>
<p><b>○ 정책센터장 김은경 </b> 그거 제가 실수한 게 뭐였냐면 편집과정에서 저희가 공짜는……. 공짜점심을 원어로 프리런치라고 그럽니다. “There is no free lunch”라고 그래 가지고 유명한 경제학에서 쓰는 문구입니다.
</p>
<p><b>○ 김주삼 위원 </b> 잠깐만요.
</p>
<p><b>○ 정책센터장 김은경 </b> 거기서 가져온 거고 제가 실수를 한 겁니다.
</p>
<p><b>○ 김주삼 위원 </b> 이거 인쇄가 잘못된 거예요?
</p>
<p><b>○ 정책센터장 김은경 </b> 그걸 거기에 인용한 겁니다, 프리런치라는 걸.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까.
</p>
<p><b>○ 정책센터장 김은경 </b> 무상급식은 아닙니다. 프리런치입니다. 흔히 쓰는 단어입니다.
</p>
<p><b>○ 김주삼 위원 </b> 공짜점심이라는 게 뭐예요?
</p>
<p><b>○ 정책센터장 김은경 </b> 실질적으로 비슷한 맥락이지만 무상급식에 대해서 객관적으로 얘기를 한다면 기본적으로 저희가 프리런치는 비용 없는 건 아무것도 없다는 의미로 프리런치로 쓰는 거거든요, 경제학에서는요.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 그런 표현을 공짜점심이라고 한 근본적인 이유가 상식적으로는…….
</p>
<p><b>○ 정책센터장 김은경 </b> 아니, “There is no free lunch”라고 경제학적으로 일반적으로 쓰는 용어입니다. 그걸 쓴 걸 제가 잘못한 것은 뭐냐면 옆에 프리런치를 넣어야 되는데 제가 편집과정에서 잘못을 했습니다. 죄송합니다.
</p>
<p><b>○ 김주삼 위원 </b> 그럼 프리런치가 공짜점심이라고 해석될 수 있어요?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 그렇습니다. 그렇게 쓰고 있습니다, 일반적으로.
</p>
<p><b>○ 김주삼 위원 </b> 그런데 우리 일반국민들은 공짜점심을 지금 뭐라고 쓰죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 저는…….
</p>
<p><b>○ 김주삼 위원 </b> 특히 정치권에서?
</p>
<p><b>○ 정책센터장 김은경 </b> 아, 여기서 공짜점심하고 무상급식은 좀 다릅니다. 죄송합니다. 제가 그것은 언어상의 실수가 있었습니다.
</p>
<p><b>○ 김주삼 위원 </b> 이거 그러면 잘못됐다고 정정자료 낼 수 있어요?
</p>
<p><b>○ 정책센터장 김은경 </b> 저는 제가 잘못했다는 의미는 프리런치를 빼먹었다는 의미입니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 이 공짜점심에 대한 그런 부분들에 대해서 정확하게 다시 자료를 낼 수 있느냐고요.
</p>
<p><b>○ 정책센터장 김은경 </b> 아니, 그럴 필요가 없다는 겁니다.
</p>
<p><b>○ 김주삼 위원 </b> 그럴 필요 없죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 결국은 일반국민들의 공짜점심에 대한 부분을 교묘하게 이용했다고밖에 볼 수가 없죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 제가 그 정도로 정치적인 머리는 안 돌아가고요. 저희 경제학적으로, 제가 기본적으로 거기서 계속 그 용어를 쓴 겁니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 머리가 안 돌아갔으면 정확하게 사실관계를 얘기해 줘야죠.
</p>
<p><b>○ 정책센터장 김은경 </b> 사실관계는 프리런치이고요.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 그 부분에 대해서 정확하게 자료를 내셔야 될 거 아닙니까!
</p>
<p><b>○ 정책센터장 김은경 </b> 아니요, 자료를 낼 필요 없습니다. 잘못된 게 아니기 때문입니다. 영어가 빠졌다는 것뿐이고요.
</p>
<p><b>○ 김주삼 위원 </b> 그럼 영어 빠진 부분에 대해서는…….
</p>
<p><b>○ 정책센터장 김은경 </b> 그걸 무상급식으로 인용, 인정하는 사람들은 그 본인들이 가지는 의식일 뿐입니다.
</p>
<p><b>○ 김주삼 위원 </b> 아, 그건 알기는 너희들이 알아서 알아라.
</p>
<p><b>○ 정책센터장 김은경 </b> 저희는 실제로 객관적으로 쓰는 거고요.
</p>
<p><b>○ 김주삼 위원 </b> 하여튼 알겠습니다. 그리고요…….
</p>
<p><b>○ 정책센터장 김은경 </b> 그 판단은 보시는 분이 하신다고 생각을 합니다.
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 그리고 이 부분에 대해서 여러 가지 자료를 인용하셨는데 결국은 포퓰리즘, 그러니까 지방재정의 위기가 결국은 포퓰리즘 복지정책 때문에 그랬다는 결론이거든요. 그죠? 이것의 내용은요.
</p>
<p><b>○ 정책센터장 김은경 </b> 그것은 지금 현재 그럴 만한 우려가 있다고 말씀을 드리는 겁니다, 시사점에서요. 왜냐하면 실질적으로 세계적 정황을 봤을 때 실제로 이렇게 지방재정이 파탄된 곳들이 있고 국가재정이 파탄된 경우도 있기 때문입니다.
</p>
<p><b>○ 김주삼 위원 </b> 여러 가지 내용 중에 그리스를 얘기하셨죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 거기에서 인용한 자료가 현재 한국은행에서 나온 “그리스 국가부도 위기의 원인과 전망”도 인용하셨더라고요. 그죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 거기에 한국은행에서 나온 그리스 국가부도의 가장 큰 원인이 뭐라고 나와 있죠? 혹시 그 자료 보셨어요? 한국은행에서 나온 자료요?
</p>
<p><b>○ 정책센터장 김은경 </b> 이건 작성자가 있습니다. 우리 황상연 박사님하고 작성자들이 했고요. 저는 최종검토만 합니다.
</p>
<p><b>○ 김주삼 위원 </b> 그리스 국가부도 위기의 원인과 전망, 한국은행에서 나온 자료 못 보셨어요?
</p>
<p><b>○ 정책센터장 김은경 </b> 제가 직접적으로 볼 필요는 없었습니다. 연구책임자가 황상연 박사이기 때문에요, 연구진들은 모든 자료들을 가지고 검토를 해서 이걸 작성을 하고요. 저 같은 경우는 부서장으로서 최종적으로 수정 자구라든지 아니면 필요한 편집활동만 하고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러면 예를 들어서 인용된 자료가 맞는지 틀린지 물론 그런 건 최종적으로 연구원 작성자 책임이죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그럼 그 책임연구원 있어요? 나오셨어요, 오늘?
</p>
<p><b>○ 정책센터장 김은경 </b> 이 자리에는 지금 없고요. 연구실에 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그럼 누구한테 그 책임을 물어야 되죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 제가 보기에 연구책임은 황상연 박사를 호출하시는 게 가장 맞을 것 같습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러면 정책연구센터장이나 연구원장은 이 자료에 대해서 잘못 인용됐거나 아니면 뭔가 선별적으로, 의도적으로 왜곡돼서 취합한 자료에 대해서는 책임이 전혀 없나요?
</p>
<p><b>○ 정책센터장 김은경 </b> 아닙니다. 그게 아니고 그건 일단 연구를 각자 하는 연구자들에 대한 신뢰와 그리고 그 사람들이 정확하게 공부를 한다는 취지에서 저희가 모든 연구를 하는 것이지 무슨 정당이라든지 아니면 관료처럼 하이라이트를 줘서 하는 건 아닙니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 그런…….
</p>
<p><b>○ 정책센터장 김은경 </b> 그렇기 때문에 모든 연구결과에 대해서 연구책임자들은 자신의 연구에 대한 책임과 신뢰를, 책임과 의무를 갖고 있는 겁니다.
</p>
<p><b>○ 김주삼 위원 </b> 그런 책임은 이해합니다. 이해하는데 그럼 그분의 이 인용자료가 의도적으로 왜곡됐다고 생각했을 때는 어떻게 해야 됩니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 그것은 그분께 여쭤봐야 되는데 저는 아직까지 그런 얘기는 못 들었습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그런 생각은 안 하셨다는 얘기죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그 얘기는 어쨌든 인용된 자료가 다 옳다고 판단을 하신 거죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 연구자의 책임하에서 연구가 잘 됐다고 생각하고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러면 제가 이 자료 우리 연구원장님하고 제가 보기에 안 보신 것 같아요. 이 자료 이것 좀 갖다 드리세요.
</p>
<p style="padding-left:2.4em">    (관계공무원, 답변석에 자료전달)
</p>
<p style="padding-left:1.2em">  이게 우리나라 한국은행에서, 가장 권위가 있는 한국은행에서 나온 자료인데 그리스 국가부도 위기에 대한 원인을 얘기한 겁니다. 거기에 보면 재정적자의 가장 큰 원인이 재정적자 확대인데 이 부분이 첫 번째로 한국은행에서 얘기한 부분이 세수기반이 취약하다. 쉽게 얘기해서 지하경제 규모가 GDP 대비 25% 정도라고 그렇게 돼 있습니다. OECD 평균 지하경제 규모가 그리스 25%, 대부분이 17, 뭐 독일 14, 캐나다 12 그렇습니다. 그런데 가장 큰 재정적자의 원인이 지하경제. 그런데 참고로 우리 센터장님, 우리나라 지하경제 현재 규모가 어느 정도인지 아세요?
</p>
<p><b>○ 정책센터장 김은경 </b> 저는 언뜻 들었던 기억이 300조보다 떨어지는 걸로 알고 있습니다. 그렇게 들어본 바가 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 몇 % 정도 하나요, GDP 대비? 몇 %라고 얘기 들었어요?
</p>
<p><b>○ 정책센터장 김은경 </b> GDP 대비로 한 30% 되나요? 30% 정도 수준의, 그러니까 25%~30%선 정도로는 알고 있었습니다. 그런데 지금은 어느 정도 되는지 모르겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 이게 99년도에, 99년도면 외환위기 바로 직전에 22.3%, 그리고 2003년도에 이게 17%까지 떨어집니다. 국민의 정부, 참여정부에 들어와서. 그러다가 이명박 정부에 들어서 다시 22%, 23%로 올라갑니다. 그리스 재정위기와 우리나라 재정위기가 지금, 저는 우리나라 재정위기가 앞으로 닥쳐올 수도 있는 게 그리스를 보면 저는 그게 좀 우려가 된다는 얘기고요. 두 번째 그리스 재정위기가 아시겠지만 감세입니다. 이 내용도 잘 모르시겠죠? 당연히 이 자료를 안 봤으니까 모르시겠죠.
</p>
<p><b>○ 정책센터장 김은경 </b> 저는 모르겠습니다만 보는 관점에 따라 틀릴 것 같습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 보는 관점이 아니고요. 보세요, 센터장님! 보는 관점이 아니고요. 원장님, 보는 관점이 아니라 한국은행에서 나온 자료예요. 정식 보고서예요. 이건 관점의 차이가 아니라. 그래서…….
</p>
<p><b>○ 정책센터장 김은경 </b> 모든 보고서에는 관점이 들어갑니다.
</p>
<p><b>○ 김주삼 위원 </b> 저하고 지금 말꼬리 잡고 씨름하자고 그러는 거예요?
</p>
<p><b>○ 정책센터장 김은경 </b> 죄송합니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 기본적으로 지금 원장님과 센터장님이 가장 큰 잘못을 저지르고 계신 게 어떤 보고자료가 나오면 그 부분에 대해서 정말 이게 옳은 자료인지, 우리 경기개발연구원이 책임을 지고 대외적으로 발표할 자료인지에 대한 책임감을 계속 하부조직, 나중에는 오타 났다고 그렇게 얘기하실 정도까지 지금 그러고 있어요. 아니면, 이 뭡니까? 공짜점심에 대한 영어해석의 문제, 그걸 영문표기를 안 했다는 둥 그런 식으로 책임회피를 하시면 안 됩니다. 최소한 저는 이런 자료가 나오면 한국은행에서 나온, 그러니까 정말 정부의 공식적인 기관에서 나온 이 그리스 재정위기의 원인이 뭔지에 대해서 최소한 고민을 하셨고 검토를 하셨어야 돼요. 이게 우리나라 지금 상황하고 비슷합니다, 이명박 정부에서 나온 상황과. 또 하나가 뭐 왔습니다. 법인세율 인하, 기부세 인하, 그다음에 부동산 상속세 폐지. 똑같이 그렇게 지금 되고 있습니다.
</p>
<p style="padding-left:1.2em">  그다음에 세 번째가 기본적으로 그리스는 관광업 중심입니다. 우리나라는 제조업 중심입니다. 경기변동이 굉장히 관광하고 민감합니다. 그런 부분에 원인이 있습니다. 그리고 네 번째 과다한 사회보장비 지출이라고 한국은행에서 그렇게 판단했습니다. 이 사회보장비 지출도 실질적으로 우리가 얘기하는, 지금 경기개발연구원이나 경기도에서 염려하고 있는 공짜점심이나 아이들 교육문제 그다음에 복지문제가 아니고 정말 국민연금, 국민연금이 실질적으로 거의 한 90……. 국민연금이 실질적으로 기존 자기가 받은 급여의 95% 이상 되는 이런 잘못된, 어쩌면 사회보장도 특별한, 사회복지도 특별한 한 분야의 잘못된 구조 때문에 일어난 부분입니다.
</p>
<p style="padding-left:1.2em">  그렇기 때문에 실질적으로 저는 예를 들어서 복지 포퓰리즘과 재정위기를 연관시키려고 그러면 제대로 사실관계에 입각해서 연관을 시켜야 됩니다. 그런데 그리스 재정위기의 가장 기본적인 이유는 아시겠지만 부자감세입니다. 그리고 또 하나가 잘 아시겠지만 지하경제. 그러니까 세수 자체가 안 들어온 거죠, 세입 자체가. 그리고 이제 사회복지도 일부 포함이 됩니다. 그런데 이렇게 사회복지 부분이라고 단 하나만 끄집어내서 재정위기로 그리스가 지금 저렇게 온통 국가적 혼란을 겪는 게 사회복지 때문에 그런 것인 양, 그것도 일반 정치적 어느 특정 정치집단이 그렇게 주장하는 건 이해가 됩니다. 자기들의 정치목적을 위해서. 하지만 경기도 도민들의 세금으로 운영되는 경기개발연구원에서 이런 자료들이 나온다는 것 자체가 문제가 있는 것 아닙니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 위원님께서 잘못 이해하신 것 같은데요. 저희가 여기 그리스가 재정위기로 간 것은 복지, 무상복지나 이런 의미로 얘기한 게 아니고요. 공공부문에서 굉장히 중요한 적자를 내왔던 것 중심으로 얘기를 한 겁니다. 즉 무슨 얘기냐면 지적하셨듯이 그리스든 어떤 나라든 간에 재정위기는 여러 가지 원인으로 올 수 있는 겁니다. 그래서 저희는 그걸 공공부문 적자 관련해서 얘기를 한 것이고 여기 수치가 한국은행 부분들이 조금씩 인용돼 있는 걸로 알고 있고요. 그거와 관련해서 실질적으로 결론의 문제는 또 다른 차원의 문제인 것 같고요.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 보세요. 그럼 같은 얘기 아닙니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 그 부분은 제가 시정하도록 노력하겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 지금 그리스 재정위기의 가장 근본적인 이유가 공공부문도 물론 들어갑니다. 유로화에 편입되면서 그 부분에 대해서 일정 정도 대응을 잘 못한 부분도 그 후순위에 들어갑니다. 제가 그것까지는 얘기를 안 했어요. 그런데 전체적으로 포퓰리즘과 재정위기라는 이 주제가 결국은 포퓰리즘이 복지 포퓰리즘이고 복지비용이 많이 들어가니까 재정위기가 가중된다. 그래서 나중에 결론도 여기에 뭐라고 나옵니까? 보세요. 여기에 보면 수입, 세입부분에 대한 문제가 아니라 세출부분에 대해서 우리가 굉장히, 그러니까 쉽게 얘기해서 복지지출을 줄여야 된다는 그런 결론이에요.
</p>
<p style="padding-left:1.2em">  제가 말씀드릴게요. “세금부담을 고려하지 않은 채 지속 가능하지 않은 포퓰리즘 정책을 공짜점심으로 생각하여 지지할 수도 있다.” 이건 뭐냐, 결국 복지비 줄이라는 얘기 아닙니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 아니요, 저는 증세를 해야 된다고 생각합니다, 복지를 하려면요.
</p>
<p><b>○ 김주삼 위원 </b> 그런데 여기에 세금 늘리라는 얘기 있었습니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 그러니까 증세를 지금 논의를 안 하고 있기 때문에 제가 그렇게 말씀을 드립니다.
</p>
<p><b>○ 김주삼 위원 </b> 아니, 그러니까 그러면 이 포퓰리즘 재정위기에 대해서 예를 들어 대안으로 세금 더 걷자고 얘기는 하셨습니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 아니요, 다음에 또다시 연구를 하면 또 하게 되겠죠, 그렇게.
</p>
<p><b>○ 김주삼 위원 </b> 다음에 그거 얘기하려고 그랬습니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 저는 재정지출은, 일단 올해는 핵심이 재정지출이라고 생각을 하는 것이고요. 저희가 선택한 연구주제나 상황에 따라서 필요하면 증세문제도 얘기를 하게 될 거라고 생각을 합니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 그 상황이라는 게…….
</p>
<p><b>○ 위원장 강득구 </b> 김주삼 위원님, 마무리해야 되는데요.
</p>
<p><b>○ 김주삼 위원 </b> 네, 알겠습니다. 하여튼 시간이 한정돼 있는데 그 상황이라는 게 그러면 정치적 상황이 바뀌면 그때는 이제 또 세수증대, 뭐 세금 더 거둬야 된다 그렇게 얘기하시려고 그러는 거예요?
</p>
<p><b>○ 정책센터장 김은경 </b> 아닙니다. 또 세입과 세출은…….
</p>
<p><b>○ 김주삼 위원 </b> 그럼 언제 얘기하시려고 그럽니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 그건 제가 결정하……. 저희 연구원에서 결정하고 제가 또 판단하는 겁니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 언제 그런 계획이 있습니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 아직은 없습니다. 생각을 고려하겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 결국 안 한다는 얘기죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 아니요, 그건 잘못 이해하신 것 같습니다.
</p>
<p><b>○ 김주삼 위원 </b> 문제점을 제가 말씀드리니까 즉흥적으로 대답한다는 얘기죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 아니요, 그렇지 않습니다. 저는 증세해야 된다고 생각합니다. 저희 조세부담률이 20% 정도밖에 안 됩니다.
</p>
<p><b>○ 김주삼 위원 </b> 그런데 증세해야 된다고 생각하면 그런 연구계획 있습니까? 없죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 고려해 보겠습니다. 저는 할 생각이 있습니다, 개인적으로는. 복지정책을 하려면 증세를 해야 된다고 생각을 합니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러면 재정위기 이 자료가 나온 지가 7월 달입니다. 그러면 내년이나 내후년쯤 국민적으로 대부분 다 그럼 뭐 이거 안 되니까 증세합시다 그러면 그때 연구하려고요?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 그렇게 생각하고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 아, 그러니까 국민들 입맛에 맞춰서?
</p>
<p><b>○ 정책센터장 김은경 </b> 아, 그거 굉장히 중요합니다.
</p>
<p><b>○ 김주삼 위원 </b> 지사가 바뀌면?
</p>
<p><b>○ 정책센터장 김은경 </b> 지사의 문제는 전혀 상관이 없습니다.
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 하여튼 연구원장님.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 좀 질의드리겠습니다. 마지막으로 어쨌든 이 한 부분만 가지고 제가 시간을 너무 많이 끌었는데요. 다시 계속 지금 제가 질의를 드리겠습니다마는 저는 일단……. 아, 들어가셔도 되겠습니다.
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 들어가겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 일단 대단히 실망스러웠던 게 경기개발연구원에서 나온 자료에 대해서 우리 연구원이나 각 연구하시는 책임자들이 실질적으로 어떤 그런 정치적 목적을 가지고 저는 한다고 생각할 수밖에 없습니다. 그것은 우리 권칠승 위원님 질의에서도 나왔지만 저는 그게 우려스러운 게 우리 원장님이 새로 부임한 작년도부터 더 노골화돼 있다. 저는 정책센터가 만들어진 부분이 왜 그랬는지 충분히 이해하려고 하면서도 여러 가지 자료들이 나오는 걸 보면 굉장히 정치적으로 지금 편향된 그런 결과물들을 쏟아내고 있다. 그래서 저는 그런 부분에 대해서 일단 먼저 우려를 드리고요. 그게 우연스럽게도 우리 원장님이 새로 오시면서 그런 문제들이 막 드러나고 있습니다. 이 한두 장짜리, 서너 장짜리, 대여섯 장짜리 리포트 형식으로. 저는 이런 부분들이 대단히 우리 경기개발연구원의 앞날에 우려스럽다. 저는 그걸 분명히 말씀을 드리고요.
</p>
<p style="padding-left:1.2em">  제 질의가 길어졌습니다마는 마지막으로 하나 딱 드리고 싶은 건 혹시 우리 경기도의 전체 지방재정 중에 복지비가 몇 % 차지하는 줄 아세요? 최소한 저는…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 20% 정도.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 복지문제, 재정위기가 정말 복지문제 때문에 그렇다는 걸 주장하시려고 그러면 우리 경기도에서 차지하는 전체 재정 중에 복지비용이 몇 % 정도인가는 아셔야죠. OECD 평균 어느 정도인지 아세요? 혹시 누구 연구원 중에 알고 계세요? OECD 평균 전체 재정 중에 복지비가 차지하는 비율 몇 %인지 아세요?
</p>
<p><b>○ 위원장 강득구 </b> 김주삼 위원님 마무리…….
</p>
<p><b>○ 김주삼 위원 </b> 네, 알겠습니다. 마무리하겠습니다. 혹시 아시는 분 계시냐고요. 우리 경기도가 복지비용이, 재정 중에 복지비율이 몇 %인지 아세요? 혹시 알고 계신 분 안 계세요? 그러면서 무슨 놈의 우리 경기도의 복지비용이 지금 많아서 재정위기가 있다는 둥 그런 얘기를 합니까! 20%가 안 돼요. OECD 평균 40~50%입니다. 우리는 지금 우리 재정의 배의 배를 해도 겨우 OECD 평균 따라갑니다. 이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 조금 전에 답변했던 연구위원 잠깐만 좀 나와 주실래요?
</p>
<p><b>○ 정책센터장 김은경 </b> 네. 
</p>
<p><b>○ 위원장 강득구 </b> 지금 직책이 어떻게 되죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 정책센터장입니다.
</p>
<p><b>○ 위원장 강득구 </b> 네?
</p>
<p><b>○ 정책센터장 김은경 </b> 정책센터장입니다.
</p>
<p><b>○ 위원장 강득구 </b> 이름이 어떻게 되죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 김은경입니다.
</p>
<p><b>○ 위원장 강득구 </b> 김?
</p>
<p><b>○ 정책센터장 김은경 </b> ‘은’자 ‘경’자 씁니다.
</p>
<p><b>○ 위원장 강득구 </b> 우리 김은경 연구위원은 작년보다 더한 것 같아요. 작년에는 그 자리에서 일관되게 우리 위원들이 질의하는 것에 대해서 냉소적으로 계속 반응 보이고 얘기하고 그랬는데 올해는 더한 것 같아요. 그리고 프리런치 얘기했죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 제가 네이버로 찾아보라고 그랬어요. “서비스로 내는 간단한 점심” 구호가 공짜 같은 것입니다. 그리고 안에 토를 달았습니다. “실은 비싼 거”. 이거에 대한 입장은 떠나서 말씀 얘기한 대로 경기개발연구원이 행정기관이랑은 달라요. 그렇기 때문에 최대한 저는 자율성을 존중하려고 그러고요. 그리고 또 창의적인 분위기 만들어야 된다고 제가 우리 원장께 여러 번 얘기했습니다. 그런데 마지막 날 본회의 때 제가 김주삼 위원님 포함해서 다시 한 번 질의하겠습니다. 그리고 다시 한 번 얘기하는데 이 자리는 우리 위원님들이 다양한 시각, 다양한 입장을 갖고 얘기할 수 있는 거예요. 그런 걸 갖고 그렇게 흥분해 갖고 얘기할 필요까지 있나요?
</p>
<p><b>○ 정책센터장 김은경 </b> 죄송합니다. 시정하겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 우리 원장께서 어떻게 생각하세요? 나와서 얘기하세요. 들어가시고 나와서 얘기하십시오.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일단 김은경 박사가 약간 흥분한 목소리로 얘기한 것에 대해서는 제가 대신 사과를 드리고요. 아마 그, 저희들하고 얘기할 때도 말하는 습관이 좀 그래 가지고 얘기할 때 그냥 정상적으로 얘기하는데도 톤이 좀 올라가고…….
</p>
<p><b>○ 위원장 강득구 </b> 아니, 그런 걸 감안한다고 하더라도.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 죄송합니다.
</p>
<p><b>○ 위원장 강득구 </b> 작년이랑 기본적으로 달라진 게 없습니다. 물론 김은경 연구위원님께서 보시기에 도저히 말이 안 되는 얘기일 수도 있죠. 그리고 도저히 입장이 다를 수도 있죠. 그렇다고 하더라도 의회라는 게 다양한 생각들이 모여서 의회를 통해서 집행부의 입장들을 반영하고 이러는 건데, 그런 것 아닙니까? 오늘 끝까지 한번 하면서 얘기들을 해보겠는데 저는 이 부분에 대해서…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 원장으로서 주의를 주도록 하겠습니다. 그리고  앞으로 충분히 여기 얘기를 제가 말씀드리겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 알겠습니다. 일단 안병원 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 안병원 위원 </b> 안병원 위원입니다. 질의하기 전에 위원장님, 올해 행감부터는 좀 양당 간사하고 위원장님하고 세 분이서 정확한 시간 같은 것을 좀 지키자 했습니다.  어떤 쟁점이 되는 부분도 있습니다. 있지만 그다음에 추가질의 때, 또 기다리시는 위원들이 여러 분이잖아요.
</p>
<p><b>○ 위원장 강득구 </b> 15분씩 드리고 위원님들 개별적으로 입장 얘기하실 때는…….
</p>
<p><b>○ 안병원 위원 </b> 다른 때 같으면 10분 했다가 오늘 이런 사항 때문에 15분으로 하지 않았습니까? 물어보시는 위원님들도 그 부분에서 총체적인 요점만 이렇게 하셔서 그렇게 진행 좀 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  이 안 공기가 굉장히 덥습니다. 위원님들이 점점 갈수록 상의를 탈착하시고 질의하시는데 온도 줄일 수 있으면 한번 줄여주십시오. 방법 있습니까? 이 안에. 중앙시스템입니까? 
</p>
<p style="padding-left:1.2em">  경기개발연구원, 도청ㆍ도의회하고 많이 떨어져 있어서 접근하기가 굉장히 어려운 지역에 있어요. 그래서 작년에 이어서 또 두 번째 와봅니다. 688쪽을 참고 좀 해주시겠어요? 초빙연구원에 관련돼서 좀 묻겠습니다. 지금 초빙연구원이 열일곱 분이 있는 거로 알고 있습니다. 특히 초빙연구원이 여러 가지 연구도 하지만 또 어떤 사항에서는, 자료에 기재된 사항 보면 안 들어와 있는 사항도 있어요. 그래서 그런 사항에 대해서 구체적으로 초빙연구원이 하는 것에 대해서 짧게 짧게 원장님께서 답변을 주시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 저희 연구원에 초빙연구원제도가 있습니다. 연구원의 시스템을 보면 선임연구위원, 연구위원, 초빙연구위원, 연구원 이렇게 되고 연구위원부터는 소위 얘기하는 정규직입니다. 저는 정규직이라는 말을 그렇게 썩 좋아하지 않는데. 왜냐하면 유기직과 무기직이 있지 정규직ㆍ비정규직이란 용어가 저는 상당히 잘못된 용어라고 생각하기 때문에. 그런데 구태여 나누자면 정원이 있는, 그게 이제 연구위원부터. 그런데 연구 수요는 많기 때문에 저희들이 초빙연구위원제도를 지금 두고 있습니다. 그래서 여기 있는 분들인데 그중에서 하나씩 말씀을 드리면요. 최희순 박사는 주로 기획조정실에 소속되어 있어 가지고 이 친구는 소위 행정학을 전공했습니다. 그래서 다문화 문제라든지 또 여론ㆍ언론, 여론조사 같은 것을 전공해  가지고 소위 서베이, 저희 서베이하는 데 서베이 쪽을 담당하고 있는 그런 친구고요. 강일원 박사 같은 경우는 중앙대에서 법학을 전공했는데 저희가 법학전공이 거의 없거든요. 아무래도 연구소는 주로 전공들이 경제학이나 도시공학, 환경 이런 쪽이지 법적인 문제에 대해 가지고, 사실 이게 굉장히 중요한데, 그래서 저는 항상 법을 전공한 사람들 좀 했으면 좋겠다 그랬는데 굉장히 법 전공한 분들을 모셔오기가 쉽지가 않습니다. 주로 변호사 한다든지 이쪽으로 나가 가지고. 그래서 법을 전공했기 때문에 그 법적인 문제에 저희들이 자문을 하고 그런 입장이고.
</p>
<p><b>○ 안병원 위원 </b> 그러니까 여기 계신 분들이 결론은 연구보다는 자문 쪽…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 자문도 하고 저희가……. 
</p>
<p><b>○ 안병원 위원 </b> 그쪽으로 많이 치우치고 있다 이렇게 보면 되겠네요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 자문이란 표현을 했는데 연구라는 표현, 저희가 연구하고 자문하고 이게 연구원에서는 모든 업무가 사실 연구죠. 모든 업무가 연구인데 아까 제가 자문이란 표현은 약간 좀 잘못된 용어였습니다. 연구를 하고 있는데 그런데 연구라는 것이 예를 들어서 막 보고서 몇백 페이지 쓰는 연구도 있고 또 언어로 하는 연구도 있고 조사로 하는 연구도 있고 이렇게 다양합니다. 그래서 그런 식으로 각 연구위원들의 롤이 정해져 있고 나름대로 또 보고서도 나오고 그럽니다. 
</p>
<p><b>○ 안병원 위원 </b> 지금 정책센터의 한 분 계시죠? 최창옥 연구위원 같은 경우는 굉장히 뉴욕에서 박사학위 따시고 대단한 재원이신데 이런 분들이 실적이 없어요. 그죠? 올해 어떤 연구실적 같은 게 없고 또 9쪽, 11쪽 보면 거기 명단에도 빠져 있어요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 다 낸 걸로 알고 있는데…….
</p>
<p><b>○ 안병원 위원 </b> 그래서 이런 경우 굉장히 아까운 인재인데 그대로 우리 경기개발연구원에서 나름대로 그쪽의 정책센터나 또 기획조정실 있다가 통일ㆍ동북아연구센터 이런 데 나름대로 역할을 하고 있습니다만 그래도 굉장히 어떤 부분에서는 좀 미흡하다. 연구실적 같은 것이 좀 해야 되지 않냐, 그래도. 저는 그렇게 보고 있거든요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 더 적극적으로 활용하도록 하겠습니다. 지금도 몇 개는 하고 있는데요. 더 적극적으로 활용하도록 하겠습니다. 
</p>
<p><b>○ 안병원 위원 </b> 어쨌거나 초빙연구원님들 채용할 때 그 부분에서 필요한 부분에 우리 경기도 여러 가지 정책에 해서 이렇게 채용하는 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다.
</p>
<p><b>○ 안병원 위원 </b> 그중에서도 최고 권위 있는 분들 이렇게 해서 하는 건데 정말 아까 원장님 말씀하셨다시피 채용과정에서 굉장히 모시기 힘든 그런 분들이지만 그래도 우리 경기도에서 어떤 연구한 부분이 또 대한민국 어떤 그런 정책에도 반영되는 사항을 많이 보고 있어요. 그런데도 그대로 어쨌거나 실적이 없다는 것은, 한 건이라도 없다는 것이 굉장히 큰 자원을 그대로 사장시키는 것 아닌가 이렇게 보고 있어요. 그래서 이 부분에서 또 원장님께서는 나름대로 많이 활용해야 되지 않나 이렇게 보고 있어요.
</p>
<p style="padding-left:1.2em">  특히 제가 물어보고 싶은 게 뭐냐면 금요일 날 북부 2청에 행감을 갔었습니다. 2청의 기획예산담당관실에 DMZ총괄담당계가 있어요. 그래서 여기 보면 통일ㆍ동북아연구센터에 여덟 분의 연구위원이 계신데 이 여덟 분의 연구위원 중에서 지금 한 여섯 분 정도는 군하고 관련, 군대생활을 하셨던 그런 연구위원님들이죠? 두 분은 아닌가요? 맨 밑 688쪽에.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 거기서 손광주하고 황성준 씨는 아니고 다른 분들은 다…….
</p>
<p><b>○ 안병원 위원 </b> 아니고 오관치 연구위원부터…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 송철헌…….
</p>
<p><b>○ 안병원 위원 </b> 이분들은 여기 연구용역 사항이 별로 없어요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다.
</p>
<p><b>○ 안병원 위원 </b> 보면 아까도 얘기가 나왔습니다만 박용진 위원께서, 이분들의 역할 특히 민군협력을 통한, 그래서 올해도 수원비상활주로 문제, 얼마 전에 제 지역구인  김포시 도심 가운데 있는 장릉산 군기지의 문제점 또 구리시 사노동의 고도제한 완화, 그 외에도 우리 경기도의 군사개발제한구역 이런 부분에서 많이 접근하는 것 같아요. 저는 누구보다도 특히 군조직의 생리에 대해서 많이 알고 있습니다. 제 인맥이, 저는 그런 쪽은 아닙니다만 나름대로 많은 분들을 그쪽에 알고 있기 때문에 그분들의 어떤 폐쇄된 그런 모습을 누구보다도 더 많이 아는데 이 부분에 대해서는 저는 대단히 칭찬해 줄 수밖에 없다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다.
</p>
<p><b>○ 안병원 위원 </b> 왜냐면 그 조직에 있던 사람을 통하지 않고는 절대 접근이 불가하다는 걸 알고 있습니다. 그런데 2청에서 행감하면서 특히 김포뿐 아니라 연천ㆍ파주에도 여러 사항이 있었습니다만 특히 민통선 출입구역할 때, 들어갈 때 특히 거기에 사시는 분들이 출입할 때 일일이 어떤 통과할 때의 문제점 이런 부분을 행감할 때 얘기했더니 특히 이상이 없다. 이것이 아마 다 이상 없이 될 것이다. 그런데 그분들도 어디에 모든 것을 치우치냐면 특히 아마 여기에 통일ㆍ동북아연구팀, 군관팀이라고 그러나요? 정책팀? 명칭이? 아, 민군정책팀. 여기에 아마 모든 것을 기대를 걸고 있는 것 같아요. 그래서 이분들한테 하는 걸 보고나서 저희한테도 어떤 사항에 대해 답변을 주시고 하는데 그 부분에 답변 온 것에 대해서 왜 이렇게 일을 처리 못했냐 했더니 처음에는 여기에서 다 될 것 같이 답변을 줬기 때문에 당신들도 그 부분에 계신 분들도 우리한테 이렇게 답변 줘서 저희 또한 그 부분을 갖고 주민들한테 “여기는 언제까지 이렇게 될 것입니다.”하고 반상회뿐 아니라 어떤 간담회 자리에서도 했던 그런 기억이 있어요. 그러나 특히 우리 김포 같은 데는 해병대가 관할하기 때문에, 육군도 있습니다. 공군도 있고. 그렇지만 육군지역이 아니기 때문에 이런 사항에 대해서 다른 데는 다, 파주나 연천은 다 이상 없이 되는데 해병대 쪽은 안 된다. 손을 놓고 있었어요. 그러면서 굉장히 어렵다, 해병대 쪽이 뚫고 들어가기가. 그렇다면 지금 여기 연구위원들, 초빙연구위원님들이 여섯 분 있는데 이 안에 육군뿐 아니라 공군 또 해군도 있어요. 또 나름대로 해군하고 해병대하고는 어떤 차이점이 있습니다, 분명히. 선이 있어요. 그래서 저도 어떤 질의할 때 해병대 관련된 분도 한번 이렇게 초빙하시면 안 되겠냐 그런 얘기를 했던 기억이 있습니다. 그래서 지금 그런 사항이 어떻게 조금 진전이 되고 있는지 또 도저히 이분들이 군별 그것을 넘어서 접근이 좀 어려운 건지 그런 부분에서 원장님 아시는 대로 좀 답변을 주시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 군들이 육ㆍ해ㆍ공군이 있는데 아마도 해병대부분은 해군제독이 와 계시거든요. 그래서 물론 직접적으로 해병대랑 관계는 없지만 아무래도 인맥이나 또 이렇게 통하면, 해병대는 아무래도 해병대 출신 저거도 해군 출신들일 테니까. 그래서 그렇게 하시면 되고 해병대 출신을 따로 또 여기에서 추가로 그건 저희들이 생각을 해보겠습니다만, 지금 상황은 그렇고요. 그리고 제가 또 개인적으로 이 모든 연구의 하나하나를 다 관장하고 있지 못하고요, 책임은 제가 집니다만. 왜냐하면 연구의 자율성도 있고, 비단 여기뿐만 아니고 모든 분야에 대해 가지고. 그래서 제가 해군을 더 뽑겠다 이런 것은 아직 크게 생각해 보다, 지금 얘기가 나오고 지난번에도 나온 거가 진행이 잘 안 되었기 때문에 지금 질문을 주시는 건데 제가 참조를 한번 해보고요. 그런데 현재 안에서도, 지금 이분들 안에서도 혹시 해결할 방법이 있나 이런 걸 한번 확인해 보도록 하겠습니다. 
</p>
<p><b>○ 안병원 위원 </b> 네, 아마 첫 예로 제주도 같은 경우도 제독이 투스타가 모든 걸 관리합니다. 또 제주방어사령관 해병대 원스타가 있지만 어쨌거나 투스타가 계시기 때문에 자기 마음대로 어떤 사항에 대해서 접근하지 못하는 모습을 봤고 또 이쪽도 마찬가지라고 저는 봐요. 그래서 그런 부분 또 특히 지금 파주ㆍ연천ㆍ김포 여기에서  이것뿐 아니라 또 만약에, 아까도 얘기했습니다만 민통선 통과여부 그 부분에서 우리 시민들이, 도민들이 자유롭게 들어갈 수 있는 어떤 시스템 그런 부분에, 예산은 조금 들어갑니다만 그런 부분에서 하고 또 그 이외에도 몇 가지 그런 요구사항이 있어요. 그래서 그런 부분에 대해서도 북부청 부분에서 우리 경기개발연구원에다 연구 좀 해 달라는 그런 것이 몇 건이나 올라와 있는지 좀 얘기해 주시겠습니까? 파주ㆍ연천 또 일산도 포함될 수 있습니다. 김포 이렇게 4개 지자체에 이것 말고도 지금 어느 정도가 연구 좀 해달라고 올라온 것이 있는지. 한 예로 그냥 만약에 김포로, 제 지역구로만 한다 그러면 김포 쪽에서 이런 부분에 대해서 좀 올라온 사항 아시는 것 있습니까? 
