<p><b>○ 이승철 위원 </b> 이승철 위원입니다. 저는 시간이 얼마 없으니까 질문 몇 가지만 드리도록 하겠습니다. 조금 전에 우리 위원님들께서 계속 질문하셨던 중에 산하기관들이 계속 연구활동을 하기 때문에 경기개발연구원이 잘못하면 존재가치가 없어지지 않겠느냐라는 우려 섞인 목소리를 내신 겁니다. 그 부분에 대해서는 원장님께서 충분히 감안하셔서 앞으로는 경기연에서 하는 연구 자체가 저희 도민들한테 직접적으로 와 닿는, 피부에 와 닿는 그런 연구가 진행이 돼서 정책으로 반영이 됐으면 하는 바람으로서 제가 좀 말씀드리면서 위원님들께서도 아까 말씀하셨지만 구조적인 개편도 좀 필요하지 않겠느냐. 경기개발연구원이 온 지가 한 16년 정도 됐으니까 지금쯤에서는 어느 정도 한 번 정도는, 요즘 소위 말하는 개혁, 변화, 쇄신 이런 말씀을 많이 하지 않습니까? 그런 데에 대해서 한 번쯤은 생각해 보셔야 될 때가 되지 않았나 해서 다시 한 번 말씀을 드립니다. 어떻게 생각하십니까? 짧게.
