<p style="padding-left:1.2em">  도시철도사업에 대한 연구가 지금 과제명이 여기 이렇게 쭉 돼 있는데 이 과제명이 여기 2011년도인가 2009년도부터 다 찾았는데 한 군데도 없어. 과제명하고 틀리다고요. 지금 세계지역연구에 대한 과제명은 맞는데, 그건 다 있어요, 이 안에. 그런데 다른 것은 없어요. 도시철도에 대해서 나갔다 오신 분들이 이렇게 많은데. 이것은 제가 봤을 때 왜 이렇게 안 맞는지에 대해서 답변을 좀 해줬으면, 누가 어느 분이라도 답변을 해줘 보세요.
