<p><b>○ 위원장 강득구 </b> 실무책임자가 나와서 답변해 주세요.
</p>
<p><b>○ 이승철 위원 </b> 왜 과제명이 틀린 건지 좀 얘기해 주세요.
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 교통정책연구부장 김대호입니다. 답변드리겠습니다. 지금 연구과제는 정확히 맞습니다. 맞는데 지금 다른…….
</p>
<p><b>○ 이승철 위원 </b> 그러면 경기도 도시철도 기본계획수립 연구용역이라고 과제명이 있죠? 2011년도.
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 네, 그렇습니다.
</p>
<p><b>○ 이승철 위원 </b> 그 과제명이 우리 여기 2011년도 정책과제 이 안에 있냐고요.
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 아, 그게 수탁과제입니다, 위원님.
</p>
<p><b>○ 이승철 위원 </b> 그럼 수탁과제에 대한 게…….
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 경기도로부터.
</p>
<p><b>○ 이승철 위원 </b> 나와 있어요, 따로 자료가?
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 네, 따로 있습니다.
</p>
<p><b>○ 이승철 위원 </b> 수탁과제로 돼 있는 게 따로 돼 있습니까?
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 148페이지를 참고하시면 될 것 같습니다.
</p>
<p><b>○ 이승철 위원 </b> 알겠습니다. 그것은 제가 찾아서 보도록 하겠습니다. 그건 수탁과제에 대한 내용이니까 제가 확인을 하도록 하겠습니다. 들어가셔도 좋습니다.
</p>
<p style="padding-left:1.2em">  제가 전에도 항상 행감 때마다 말씀드리는 게 우리 해외에 나가시는 분들에 대한 연구활동 하시는 것에 대해서 철저하게 들여야 될 비용은, 사업비는 들이되 철저하게 거기에 대한 것은 검증이 필요하다는 말씀을 드리는 겁니다. 나갔다 오신 것에 대해서 연구하신 부분이 철저하게 또 우리 정책에 반영이 돼야 됩니다. 그래서 나갔다 오시는 것에 대해서 제가 뭐라고 말씀드리는 것은 아니고 갔다 오신 것에 대한 철저한 검증이 필요하다 그 말씀을 다시 한 번 드리고요.
</p>
<p style="padding-left:1.2em">  우리 경기개발연구원이 본인들이 가지고 있는 고유목적이 있습니다. 자기 연구에 대한 목적이 있는데 이런 목적에 사업비가 정확하게 쓰여져야 되지 다른 데, 지금 위원님들이 자꾸 추궁하고 뭐하는데 목적의 그런 다른 부분에 사업비가 쓰여져서는 절대 안 되거든요. 이 점을 다시 한 번 말씀드리면서 일반 우리 연구하시는 연구원님들의 개별적인 사업비도 있겠지만 또 전체적인 총괄연구사업비가 따로 돼 있을 겁니다. 그런 부분이 중첩되지 않도록 하셔야 됩니다. 그런 것에 대한 철저한 감독과 감시를 원장님께서 하셔야 돼요. 그냥 보고만 받으시고 사인만 하실 게 아니라 그런 부분에 대한 철저한 감독을 해주실 것을 다시 한 번 부탁드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 제가 지금…….
</p>
<p><b>○ 이승철 위원 </b> 말씀 한마디 하시면서 제 질의는 마치도록 하겠습니다. 답변 주세요, 원장님.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 취임하고 나서 출장이라든지 이 비용이라든지 이런 것은 굉장히 까다롭게 지금, 그렇기 때문에 지금 출장건수도 상대적으로 줄어들고 이래서 제가 너무 까다롭게 하는 게 아닌가 이런 생각도 하고 있을 정도로 까다롭게 지금 하고 있습니다.
</p>
<p><b>○ 위원장 강득구 </b> 알겠습니다. 우리 위원님들이 질의하신 내용 중에서 제가 한두 가지만 관련해서 질의하겠습니다.
</p>
<p style="padding-left:1.2em">  우리 행정사무감사 요구자료-Ⅱ에 보면 614쪽 제65차 임시이사회 회의록입니다. 거기 일시가 2011년 3월 8일 12시부터 12시 40분까지라고 써 있습니다. 그리고 장소가 세전수사 2층이라고 써 있습니다. 아까 원장님이 그런 얘기했죠? 예를 들면 결국 마지막은 기관장이 책임진다라고 얘기했죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 이날 65차 임시회 이사회가 신임 원장 선임하고 그리고 선임직 이사를 선임하고 신규 이사장을 선임하는 자리입니다. 그러니까 경기개발연구원 입장에서 어떻게 보면 이 이사회가 상당히 중요한 의미를 갖고 있는 그런 이사회입니다. 그렇습니까, 안 그렇습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그런데 장소가 세전수사 2층이에요. 그리고 12시부터 12시 40분이라고 했는데 마지막 보니까 12시 13분에 끝난 걸로 돼 있습니다. 그러니까 12시부터 시작했다고 그러지만 한 12시 2, 3분 뭐 3, 4분에 시작을 해 갖고 12시 13분에 폐회를 했겠죠. 그게 10분도 안 됐습니다. 그리고 그다음 날 보니까 홈페이지에 이사장 해 갖고, 좌승희 이사장 해 갖고 인사말 나와 있고. 물론 이게 속된 말로 짜고 치는 고스톱이죠. 이건 이미 내부적으로 다 정해져 있는 거죠. 그죠? 그렇다고 하더라도 최소한의 형식과 절차는 필요한 것 아닙니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 위원장 강득구 </b> 이 이사회 때 원장이 결원됐었죠? 원장이 선임 안 됐으니까, 그죠? 결원된 상태잖아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇죠. 시작하기 전에는 그렇죠.
</p>
<p><b>○ 위원장 강득구 </b> 그러면 부원장이 참석 안 한 걸로 제가 알고 있습니다, 이 회의록 보면. 참석 안 했죠?
</p>
<p style="padding-left:2.4em">    (「했습니다.」하는 관계직원 있음)
</p>
<p style="padding-left:1.2em">  여기 이 자료에 의하면. 그래서 이 회의록을 보면 김문수 이사장이 당연직 이사장이죠. 참석 안 했죠? 불참했죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 여기 불참했는데 정관 제13조3항에 보면 이럴 경우에 연장자가 직무를 대행하도록 돼 있습니다. 그죠? 그래 갖고 연장자가 의장 직무를 대행했어요. 그래요, 안 그래요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다. 그런 걸로 알고 있습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그래서 원장은 이사회의 의결을 거쳐 이사장이 임명하도록 정관 제16조제1항에 명시돼 있습니다. 제14조제3항에 의하면 “선임직 이사는 원장이 학계, 산업계 등의 추천을 받아 이사회 의결을 거쳐 경기도지사가 임명하는 자로 한다.”라고 돼 있어요. 그러면 이날 12시부터 12시 13분 사이에 우리 원장이 여기 원장이 되신 거잖아요, 그죠? 정식으로.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 그러면 학계, 산업계 등의 추천을 받게 돼 있는데 학계, 산업계의 추천을 받았나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 이 이사회 건에 대해서, 이사장 건에 대해서 이사장 선임하는 데서 절차상에 하자가 있다는 것은 제가 인정을 합니다.
</p>
<p><b>○ 위원장 강득구 </b> 그리고 도지사가 임명하게 돼 있는데, 아까 임병택 위원님도 얘기했지만 도지사가 임명하는 절차가 없었습니다. 그러니까 선임직 이사는 원장이 학계, 산업계의 추천을 받아서 분명히 이사회 의결을 거쳐서 하게 돼 있는데 그런 과정도 없었고 경기도지사가 임명하게 돼 있는데 그런 과정도 없었어요.
</p>
<p style="padding-left:1.2em">  그러니까 회의록을 재구성하면 이렇습니다. 홍순영 원장 선임, 선임직 이사로 좌승희 전 원장을 선임하고 곧바로 좌승희 이사를 이사장으로 선임하는 순으로 13분 만에 일사천리, 실제로는 10분도 안 걸렸을 겁니다. 그것도 세전수사에서 식사하면서 이렇게 그냥 몇 명이, 어떻게 보면 100% 경기도에서 출연한 기관인데 세전수사에서 그냥 식사하면서 뭐 커피 마시면서 얘기를 했겠죠. 그죠? 그리고 어쨌거나 그렇게 어수선하게 그런 자리에서 만장일치로 가결됐단 말입니다. 분명히 산업계나 학계 추천 안 받았죠? 조금 전에 인정한 거죠, 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 그날 이제…….
</p>
<p><b>○ 위원장 강득구 </b> 아니, 그러니까요. 제가 말하는 것 분명히…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그 부분에 대해서는 제가 특별히 더 드릴 말씀이 없습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그렇죠, 할 말 없죠? 분명히 잘못된 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다. 드릴 말씀 없습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그리고 선임직 이사는 이사회 의결사안이 아니에요. 경기도 도지사가 임명하는 사안입니다. 도지사는 분명히 당일 이사회에 불참했어요. 경기도지사의 임명이 어떻게 이루어지죠? 구두로, 아니면 서면으로?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그것은 미리 사전에 구두로 임명할 수도 있기 때문에 그래서 그런…….
</p>
<p><b>○ 위원장 강득구 </b> 아니, 그렇다고 하더라도 분명히 절차상에는 나와서 얘기하게 돼 있습니다. 전화로 예를 들면 “당신이 이사장 해!” 아니면 “내 멘토, 이사장 해!” 이게 아니고 이사회 회의에 참석해서 절차를 거쳐야 된다라는 거죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그것은 제가 잘 모르겠습니다. 와서 꼭 해야 되는 건지 아니면 따로 임명절차가 있는 건지 그건 모르겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 아니, 그러면 정식으로 이사회가 구성돼 갖고 이 정관에 의해서, 모든 게 정관에 의해서 되는 거잖아요. 정관의 절차를 생략하고 무시하고 그랬는데 이게 합법적이라는 건가요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 합법, 비합법은 제가 법률전문가가 그걸 확인할 수는 없지만 하여간 그날 일부 석연치 않게 좀 불투명하게 진행된 것은 분명하게 있다고 생각합니다. 제가 그 문제에 대해서는 특별히 더 드릴 말씀 없습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그러니까 이사장, 65차 임시이사회에서 이사장 선임한 것에 대해서 원천적으로 이건 무효일 수밖에 없습니다. 그런 다음에 그다음 회의록에 66차 임시이사회를 이사장이 소집합니다. 그러면 법적으로 하자가 있는 이사장이, 선임절차에 있는 이사장이 소집한 66차 임시이사회의 의결은 유효한 겁니까, 무효한 겁니까? 이것에 대해서 분명히 법적인 책임을 우리 원장께서 책임져야 됩니다. 65차 임시이사회에서 법적 절차를 무시하고 생략한 채로, 정관에 규정된 대로 하지 않고 일방적으로 예를 들면 내부적으로는 뭐 합의됐겠죠. “아, 내가 물러날 테니까 우리 좌승희 원장께서 고생 많이 했으니까 이사장 하시오.” 이렇게 됐겠죠. 그거랑 공식적인 절차, 경기도시공사 사장도 마찬가지예요. 내부적으로 이미 선임되기 한 달 전부터 이사장 경기도시공사 누구는 다 내부적으로 정해져 있었어요. 우리가 다 얘기 들었습니다. 그렇지만 선임절차라는 게 있었거든요. 선임절차가, 형식절차가 하자가 없었기 때문에 인정한 겁니다. 그런데 이 부분은 선임절차가 분명히 여기 정관과 규정에 근거가 있음에도 불구하고 근거를 무시하고 생략하겠다라는 건 인정할 수가 없는 것이고 인정이 안 되는 거죠. 이것은 다시 한 번 의뢰를 해보겠습니다. 그리고 그 이사장이 66차 임시이사회를 소집해 갖고 몇 가지 의결을 합니다. 그러면 이 66차 임시이사회에서 의결한 게 이게 유효한 겁니까, 무효한 겁니까?
</p>
<p style="padding-left:1.2em">  혹시 2006년도에 노무현 대통령이 사법시험 동기인 전효숙 씨를 임기 6년의 헌재 소장에 앉히려고 한 거 기억납니까, 안 납니까? 그래서 임기가 남은 전효숙 재판관을 직을 사퇴시켰습니다. 그래서 인사청문회특위가 열리자 조순형 의원이 한 얘기가 민간인 신분인 전 후보자에 대한 국회 임명동의 요청안은 헌법재판관 중에서 헌재소장을 임명하도록 한 헌법 규정의 위반이라고 해 갖고 상당히 논란이 장기간 있었습니다. 그래 가지고 결국 103일 만에 노무현 대통령이 지명을 철회했던 것 기억나세요? 제가 보기에는 이것은 그것보다 더 큰 겁니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 이제, 죄송합니다. 제가 해석을 하자면요, 물어보시니까. 일단 위원장님이 제기하신 여러 문제점을 충분히 제가 이해를 하고 또 납득을 합니다. 그런데 이게 저희들이 보니까 임명절차도 그렇고 이게 순간순간적으로 벌어지는 일에 대해 가지고 이게 어떻게 해석을 하니까 저를 먼저 선임을 했고, 지사가. 미리 사인이 돼 있습니다. 그래서 그 중간에, 그러면 0.001초 차이는 어떻게 하느냐. 그러면 그전에…….
</p>
<p><b>○ 위원장 강득구 </b> 아니, 잠깐만요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제 대신에 부원장이 있습니다. 부원장이 직무대리로 있고 그래서 굉장히…….
</p>
<p><b>○ 위원장 강득구 </b> 잠깐만요, 원장을 선임한 부분까지는 누가 뭐라고 하는 게 아닙니다. 문제는 뭐냐면 원장이 학계나 산업계의 추천을 받아서 선임이사를 하게 돼 있습니다. 그죠?
