<p><b>○ 위원장 강득구 </b> 그리고 이사 중에 호선하게 돼 있단 말입니다. 그래서 이사를 경기도지사가 임명하게 돼 있단 말입니다. 그런데 그런 첫 번째, 세 번째 과정들을 무시하고 생략하고 했다라는 거예요. 분명히 여기 제가 얘기했지만 정관 규정에 다 이사장 선임절차 이게 나와 있는데 그게 안 됐다는 말입니다. 원장 임명한 부분에 대해서 제가 뭐라고 그러는 게 아닙니다.
