<p><b>○ 위원장 강득구 </b> 그러면 이 이사장이 적법한 절차를 밟지 않았는데 됐다. 이 부분에 대해서 분명히, 나는 이건 원장 잘못은 없다라고 생각합니다. 그렇지만 이 법적으로 절차상 하자가 있는 이사장이 66차 임시이사회를 소집하고 그리고 의결했단 말입니다. 그러니까 이사장 선임절차에 저는 문제가 있기 때문에 이 이사장에 대한 부분은 다시 한 번 고민을 해봐야 된다. 그리고 66차 임시이사회 회의록에 문제가 있다라면 이건 다시 한 번 원천적으로 이건 무효다, 이런 관점에서 이 문제를 바라볼 수밖에 없습니다. 어떻게 생각하세요?
