<p style="padding-left:1.2em">  이제 정리를 하겠습니다. 정리를 하고 다시 오후에 또 위원님들도 한 바퀴 더 추가질의를 하는 걸로 하겠는데 다시 한 번 얘기하겠지만 아까 김은경 연구원이라고 그랬나요? 저는 오늘 분명히 얘기하지만 사적인 자리에서도 제가 우리 원장님한테 말씀드렸어요. 가급적이면 경기개발연구원은 행정기관이 아니기 때문에 우리 연구원분들의 자율성과 창의성 이런 부분 속에서 최대한 존중할 수 있도록 해 달라, 제가 그런 부탁 몇 번 했죠?
