<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 그러면 중식과 휴식을 위해서 3시 10분까지 감사를 중지하겠습니다.
</p>
<p class=''ar''>(13시45분 감사중지)
</p>
<p class=''ar''>(15시17분 감사계속)
</p>
<p><b>○ 위원장 강득구 </b> 그러면 감사를 계속하겠습니다. 그러면 권칠승 위원님부터 질의하는 걸로 하겠습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 화성 출신 권칠승 위원입니다. 죄송합니다. 서류정리가 덜 돼서. 오전에 이어서 보충질문 원장님께 드리겠습니다. 보고하신 현안분석 중에서 홈페이지에 올라온 내용들은 뒤에 보면 작성자가 있습니다. 그런데 별도로 제출하신 자료에는 작성자가 없습니다. 특별한 이유가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희 기조실장이 담당이기 때문에 기조실장이 잠깐 답변하도록 하겠습니다.
</p>
<p><b>○ 기획조정실장 강철구 </b> 기획조정실장 강철구입니다. 저희 연구원에서 생산되는  현안분석하고 이슈＆진단, 정책제안, 정책이슈가 여러 건이 있습니다. 있는데, 홈페이지에 공개여부는 명단이 있는 거하고 없는 게 있는데 홈페이지에 공개할 때는 작성자를 편의상 맨 뒤에 넣습니다. 왜냐하면 작성자가 있는 상태에서 홈페이지에 공개를 해야 되고 그렇게 해서 했고…….
</p>
<p><b>○ 권칠승 위원 </b> 알고 있습니다. 없는 경우만 말씀해 주십시오.
</p>
<p><b>○ 기획조정실장 강철구 </b> 없는 경우는 뭐냐면 경기도에 보낼 때 발신의 어떤 창구단일화라는 차원에서 기획조정실장 명의 내지는 정책센터장 명의로 보내기 때문에 이메일 표지에, 그렇게 편지글에 이렇게 보냅니다. 그래서 내용상에는 연구책임자하고 공동작성자가 생략되어 있습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 그러면 전부 센터장 명의로 작성되어 있다는 말씀인가요? 
</p>
<p><b>○ 기획조정실장 강철구 </b> 발신할 때는 그렇지 않고요. 이메일 보낼 때 마지막에 예를 들면 “정책센터장 누구누구 드림” 하고 돼 있고 거기에 보면 작성자가 명시는 되어 있습니다. 보고자료 작성자, 보고일시 해 가지고 이메일 상에 그게 돼 있습니다. 보고서에는 없고.
</p>
<p><b>○ 권칠승 위원 </b> 아, 보고서 안에는 없고.
</p>
<p><b>○ 기획조정실장 강철구 </b> 보고서 안에는 없고 이메일 보낼 때…….
</p>
<p><b>○ 권칠승 위원 </b> 표지에 있다 이렇게 보시면, 별도…….
</p>
<p><b>○ 기획조정실장 강철구 </b> 이메일 표지에 돼 있습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 네, 알겠습니다. 두 번째 문제점인데요. 최근 경기개발연구원에서 나온 자료 중에서, 들어가셔도 좋습니다. 야당의 정책에 대해서 일방적으로 비난한다. 제가 전부 다 그렇다는 뜻은 당연히 아닙니다. 문제가 되는 것들을 제가 지적하고자 하는 겁니다. 9월 달에 “지방예산의 위기와 정책방향”이라는 이슈＆진단이 나온 게 있습니다. 거기 9쪽에 보시면 “지방자치단체와 지방의회의 정치적 견해가 상이함에 따라 예산편성의 혼란을 가중하고 예산편성 규율의 약화 초래” 이렇게 돼 있습니다. 작은 동그라미 2개 있는데 사실상 이게 같은 내용입니다. “지방의회와 지자체의 입장이 상이할 때” 또 그 밑에는 “야당이 의회 다수를 차지하는 경우” 사실은 거의 같은 이야기입니다. 원장님 동의하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 이런 것 때문에 예산편성의 규율이 약화되고 재정위기가 온다, 그런 말 아니겠습니까? 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> “예산편성 규율의 약화 초래” 그 말 그대로입니다.
</p>
<p><b>○ 권칠승 위원 </b> 그래서 책 제목이 “지방예산의 위기”입니다. 그래서 재정의 위기가 온다 이런 뜻인데요. 그러면 지난 8년 동안 한나라당이 사실은 지방의회를 완전히 장악하고 있었죠? 그때는 왜 가용자원이 자꾸 내려갔습니까? 그래서 이런 건 이유가 안 된다는 거죠. 실제와 다른 이야기지 않습니까? 그래서 이런 것도 저는 경기개발연구원에서 나온 자료들 중에 몇 개는 제가 읽어보면 ‘야, 제가 민주당 소속으로 있는 게 정말 잘못됐는가.’ 이런 생각을 많이 합니다. 맞는 정책이 하나도 없어요, 다 틀렸고. 그리고 민주당이 다수가 되는 게 지방예산의 위기를 가져온다, 이런 것도 참 저는 도저히 인정할 수가 없습니다. 그런데 저는 이게 사실은 의회에 대한 인식이 그런 게 있지 않느냐 이런 생각도 좀 합니다. 그리고 정치적으로 보면 야당에다 정치적인, 현재 재정위기의 책임을 떠넘기려고 하는 의도가, 의도가 있든 없든 결과적으로 그렇습니다. 원장님의 생각은 어떠십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이거는 일단 제가 위원님 말씀 경청하고요. 앞으로 보고서를 쓸 때 어떤 정치적 편견이나 그게 혹시 오해 살 부분을 갖다가 저희들은 조심할 거고요. 그리고서 말씀을 드리면 이게 일반적인 이야기를 한 거라고 생각을 하시면 될 것입니다. 왜냐하면 도지사가 민주당이 되면 또 일치가 되는 것 아니겠습니까? 그래서 의회가…….
</p>
<p><b>○ 권칠승 위원 </b> 그렇게 되면 안 된다는 거죠, 제 말은.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 그러니까 예를 들어서 아무래도 집행부하고 의회하고 상이할 경우에 이런 경우가 발생할 수 있다라는 걸 저희들이 한번 노파심에서 얘기를 한 거지 어떤 특정한 걸 깎아내리려고 쓴 것은 아니라는 걸 말씀드리고 싶습니다.
</p>
<p><b>○ 권칠승 위원 </b> 그런데 중간에서 보면 그런 생각이 들 수밖에 없고 그런 의도가 있다고 해석을 해도 사실은 할 말이 없습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 참고로 말씀드리면 저희가 구태여, 이것은 공식 보고서거든요. 외부로 나가는데 외부로 나가는 것을 위원님들의 심중을 거슬려가면서까지 저희가 할 이유가 없죠. 그래서…….
</p>
<p><b>○ 권칠승 위원 </b> 거슬려도 관계없죠. 아무 관계없는데 이게 제가 볼 때는 사실과 다르고 이 연구원의 연구결과라고 보기가 어렵다는 측면이 있다는 겁니다. 그다음에 의료법인 영리화 문제 같은 것 이런 것도 사실은 좀 여야가 대립되어 있는 구조 아닙니까? 지금 그 건에 대해서요. 혹시 논란이 있는 것 아십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 뭐 여당 내에서도 대립이 있고요. 여당 내에서 대립이 있고. 
</p>
<p><b>○ 권칠승 위원 </b> 물론입니다. 그런데 큰 틀의 그거는 있죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 또 야당 내에서 대립이 있고 상당히 많은 대립이 있는 걸로 알고 있습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 큰 틀의 그게 있죠. 지금 제주도 같은 데는 법적으로, 제도적으로는 지금 도입이 사실 갖추어져 있는 것 아닙니까? 안 들어와서 그렇지. 이번에 우리가 제주도 갔을 때 양영오 원장님이 그렇게 설명을 하셨거든요, 같이 워크숍을 했는데요. 그런데 여기에 혹시 보셨습니까? 이 현안분석 자료에 보시면, 거기에 보시면 전국적으로 확대해야 된다고 되어 있습니다. 그러면 그걸 반대하는 사람 입장에서 봤을 때 사실 우리나라 건강보험제도 근간하고 그대로 맞물려 있어서 논쟁이, 논란이 얼마나 많습니까? 그런데 이런 걸 전국적으로 확대해야 된다고 딱 못을 박아놓으니까 참 진짜 혼란스럽습니다. 지금 우리나라가 사실, 혹시 원장님 이런 것 잘 아시겠죠. 공부를 그쪽으로 쭉 하셨으니까. 우리나라가 복지지출이나 이런 게 OECD에서 최하위인 거는 그건 다 아실 거고요. 상대적 빈곤율도 가장 높다는 것 아십니까? 30개국 중에 25위인가 제가 그렇게 기억합니다. 자살률 최고 높은 것 얼마 전에 보고서 내셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 그다음에 제가 아까 한번 찾아봤는데요. OECD 들어가 보니까 있습디다. 제가 영어를 잘 못해서, 이게 자살률하고 주관적인 인생에 대한 만족도 이렇게 해 가지고 상관관계 비슷하게 해 놓은 게 있습니다. 거기 보면 한국이 제일 왼쪽이고 제일 위쪽입니다. 왼쪽이 삶의 만족도고 밑의 줄이요. 위쪽이 자살률입니다. 삶의 만족도가 SVK라고 슬로바키아인가 그럴 것 같습니다. 거기를 제외하고는 한국이 최고 삶의 만족도가 떨어지고 자살률은 월등하게 1등입니다. 이런 나라에서 복지재정을 좀 늘리자고 하는 게 그렇게 못마땅한 건지. 저는 공공연구기관으로서 이렇게 하시는 게 이게 맞는가 싶습니다. 요즘 우리나라 대표적인 보수언론들 이야기를 보면 스웨덴이나 핀란드 이런 나라들은 망해도 한 4, 50년 전에 벌써 망했어야 될 나라들입니다. 원장님 생각은 어떠십니까? 그런 쪽으로 다 공부를 하시고 정보도 많으시니까 의견이 있으실 것 같은데요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희 나라 자살률이 제일 높고 주관적 삶의 만족도가 굉장히 안 좋습니다. 그래서 그걸 고쳐야 됩니다. 그래서 그것은 100% 동의하고요. 그리고 우리나라가 2만 달러 되면서 복지재정이 늘어나야 된다는 것도 적극적으로 동의하고요. 그런데 저희들이 보고서에서 어디든지 복지재정을 늘리면 안 좋다는 얘기가 아니라 재원을 마련해서 늘리자라는 얘기거든요. 그러니까 재원 확보 없이 재정을 늘리는 것은 좀 곤란하지 않겠냐 이런 얘기고요. 그래서 재정을 늘릴 때 여러 가지 방안이 있겠죠. 그래서 재정 자체를 할 때 지금 재정이 어렵다고 하니 어려운 이유가 뭔가를 현상적으로 밝힌 거지 위원님의 철학하고 저하고는 뭐 크게 틀리지 않고 저는 옳다고 봅니다. 그래서 저희 나라도…….
</p>
<p><b>○ 권칠승 위원 </b> 좋습니다. 그 부분에 대해서는 제가 조금 이따가 다시 한 번 말씀을 드릴게요. 혹시 대형할인마트가 들어오는 것에 대해서는 어떤 의견을 가지고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 어떻게 생각하냐면 이게 중도인지 어느 쪽 생각인지 모르겠습니다만 저는 대기업이 할 수 있는 영역이 따로 있고 중소ㆍ중견기업이 할 수 있는 영역이 아직도 따로 있다고 생각합니다. 그래서 우리나라의 많은 문제점 중의 하나가…….
</p>
<p><b>○ 권칠승 위원 </b> 대형할인마트가 들어오는 것에 대해서는 조금 부정적으로 보시는…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그것은 중소ㆍ중견기업의 영향을 살펴보고 그리고 해야 된다고 생각합니다. 
</p>
<p><b>○ 권칠승 위원 </b> 좋습니다. 그러면 “대기업 MRO사업 철수압박에 대한 평가”라고 2 쪽짜리 보고서가 있습니다. 여기 보시면요, MRO 잘 아시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 저는 이렇게 생각합니다. 대기업이 조달청을 하나 만들고 있다 이렇게 생각합니다. 제가 그렇게 비교하면 크게 틀리지 않습니까, 아니면 많이 틀립니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 맞습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 대기업 조달청이 MRO인데요. 지금 전부 그 밑으로 들어가 있죠, 중소기업들이.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 그렇지 않습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 저는 대형할인마트하고 크게 다르지 않다고 생각합니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 권칠승 위원 </b> 그러면 원장님의 인식은 제가 아까 확인했으니까 더 이상 묻지 않고요. 이 MRO사업 철수압박에 대한 평가에 보면, 제가 지금 드리는 말씀은 원장님오신 후에 친기업적인 성향이 더 강화된 것 같아서 드리는 말씀입니다. 좌 원장님도 사실 기업 출신이라고 해도 틀리지 않고요. 평가가 이렇게 되어 있습니다. “MRO사업이 일감몰아주기나 부의 대물림이라는 비판은 일면적이다. MRO는 기업이 규모의 경제와 효율성을 추구하는 방식이기 때문에 대기업의 중소기업 영역침범이라는 비판은 부적절하다. 대기업 계열 MRO기업들이 중소기업과의 상생을 저해하고 있는지는  불분명하다. 경제회복과 지속가능한 성장을 위해 대기업 때리기 중단 필요. 규제 중심의 대기업ㆍ중소기업 상생정책을 중지해야 된다.” 이게 지금 제가 읽어드린 게 키워드입니다. 두 장짜리 보고서의 키워드입니다. 그러면 원장님 이게 나가기 전에 보셨습니까? 
