<p><b>○ 경기개발연구원장 홍순영 </b> 저는 그건 안 봤고요. 지금 말씀드린 그거 사후에 검토했는데 MRO에 대한 이야기는 지금 나간 거하고 저하고는 상당히 다른 생각을 가지고 있습니다. 그래서 제가 연구원의 생각은, 연구원들이 저의 의견을 반드시 100% 따라야 되는 건 아니고 저는 MRO가 대기업에서 하는 것은 문제가 있다고 생각하는 사람이고 그래서 그 문제는 지금 나간 것, 여기 현안 이거하고 저하고는 생각이 다릅니다. 
