<p><b>○ 권칠승 위원 </b> 저는 망할지 안 망할지 한번 두고 보고 싶은데요. 여기 영리의료법인 도입도 보고서 4쪽에 보면 이런 내용이 있습니다. “기획재정부, 병원협회, 재계, 금융계, 보험업계 등은 의료산업의 경쟁력 제고, 고용창출, 해외환자 유치확대 등을 위해 영리의료법인 도입을 지지하고 있다.” 맞습니다. 딱 이겁니다. 이 사람들의 이해관계가 딱 맞는 게 바로 이 영리의료법인 도입이거든요. 그래서 이건 당연히 영리의료법인을 도입하면 현재 건강보험이 독점적으로 건강보험공단과 계약해야 되는 이 부분들이 해체가 되지 않으면 의미가 없지 않습니까? 그래서 이런 부분들하고 그대로 연결이 되어 있거든요. 그러면 이게 사실 크게 따지면 의료산업이 커진다라는 게 전부 다 환자들의 의료비로 사실은 가는 거지 않습니까? 크게 잘라서 봤을 때요. 그런 문제들이 있는데 지나치게 친기업 쪽으로 가고 있다 이게 제 판단입니다. 그런데 그게 원장님이 그렇게 생각을 안 하신다고 하니 원장님이 와서 그렇게 변했다 이렇게까지는 제가 이야기를 안 하겠습니다. 그렇게 말씀하신 적은 없죠?
