<p><b>○ 권칠승 위원 </b> 그래서 요청을 받고 선의로 사실은 받아서 넣었습니다. 넣었는데 이 부분을 너무 이렇게 현안분석이란 쪽으로 막 하시니까 제가 조금 안 좋은 기분이 있었습니다. 그때 받아주지 말걸 그랬나 이런 생각이 좀 들기도 하고 사실 그런 게 좀 있었습니다. 그래서 앞으로 인식의 차를 좁히고 신뢰하는 하에서 할 수 있도록 앞으로 연구자료나 이런 거에 대해서, 자꾸 이게 연구원들 스스로 자체적인 판단에서 나왔다고 말씀을 하시는데 그러면 연구원들 구성이 잘못된 겁니다. 이렇게 일방적으로 나온다는 것은 그건 제가 봤을 때 이해할 수가 없습니다. 이상입니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그것은 저희가 주의하고요. 또 현안 얘기 나와 가지고 말씀인데요. 제가 와서 취임해서 보니까 우리 연구원에 대한 상당히 많은 비판 중의 하나가 너무 대응이 늦다. 항상 버스 떠나고 난 다음에 손 흔들고, 당장 무슨 일들이 막 터지는데 거기에 대한 연구소 의견이 전혀 없다. 그래서 이게 연구원이 학교도 아니고 어떤 일어나는 일에 대해서 즉각적인 대응이 있으면 좋겠다라는 것이 많은 수요자들의 그런 저거였기 때문에 저희들이 그래서 현안이라는 것을 해야 되겠다라는 생각이 들었고요. 그래서 어떤 것은 조사적인 성격이 있고요, 두 페이지, 세 페이지를 연구라고 볼 수는 없죠. 한 부 만드는 데 하루 정도 걸려서 그냥 전문가로서의 의견제시죠. 의견제시가 있고, 그런 게 상당히 많습니다. 그런데 그러면 이런 게 연구냐라고 볼 때 또 정책수요자들이 생각할 때는 상당히 그게 고마워도 하고 막 그러더라고요. 다양한 부분을 보면서. 그래서 이거 앞으로 균형을 좀 맞추고 그래서 중장기적인 어떤 도의 현안도 또 열심히 해야 되지만 당시 당시 일어나는 어떤 현안에 대한 이런 이야기들도 굉장히 많더라고요. 그래서 저희들이 그 균형을 잡으려고 노력을 지금 많이 하고 있다라는 말씀을 드리겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 알겠습니다. 아까 원장께서 현안대응은 우리 경기개발연구원 업무량으로 따지면 한 1/10에 안 된다라고 얘기하셨잖아요. 그죠?
