<p><b>○ 위원장 강득구 </b> 그런데 조금 전에 얘기하신 대로 좌승희 원장 때는 상대적으로 현안대응에 대해서 좀 소홀히 한 감이 있습니다. 그렇게 되면 홍 원장이 들어오시면서 어느 정도 정상화되었다라고 생각을 하고, 긍정적으로 보면. 그리고 우리 도의 실국장들 포함해서 현안대응에 대한 부분들은 좌승희 원장 있을 때보다 훨씬 더 나름대로 역량들이 강화되었다 이건 인정합니다. 인정하는데 관점이죠, 관점. 관점에 대한 부분에서는 사실 조금 더 고민해 봐야 될 것 같아요. 그런데 일단 큰 틀에서 보면 현안대응만 해서도 안 되고 기본과제 자체 발굴, 정책과제 이런 부분들과 잘 조화를 맞추어야 되는 것 아닙니까. 그죠?
