<p><b>○ 안병원 위원 </b> 두 가지만 질의를 드리도록 하겠습니다. 일단 업무보고 10쪽하고 자료 347쪽을 인용하도록 하겠습니다. 347쪽에 연구결과가 정책이나 사업에 반영된 사례를 보면 금년도에 92건이 있어요. 도정 현안사업과 도정 정책기조의 변화 및 개발에 많은 성과가 있는 것으로 되어 있어요. 특히 구체적 사례가 어떤 것이 있는지 짧게 몇 가지만 먼저 말씀 좀 해주십시오. 
