<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 뒤에 375페이지, 376페이지, 377페이지부터 쭉 나와 있거든요. 몇 가지 말씀드리면요. 법령 같은 것도 예를 들어서 “상습침수지역의 구조적 개선을 위한 사업계획”이라든지 또 “경기도 주민참여예산제도의 합리적 정책방안”이라든지 또 “국가의 법과 제도에 의한 지방세 감면의 문제점 제시하고 이에 대한 제도개선 촉구”라든지 또 도정현안 지원으로써 “경기만 경제자유구역 대상지역 선정문제”라든지 또 도정현안문제로써 “음식물류 폐기물”이라든지 또 “유네스코 DMZ생물보전지역 신청서”를 제출했다든지 상당히 많은 부분이 지금 쭉 있거든요. 그래서 혹시 저거하시지만 379페이지부터 386페이지까지에 저희들의 정책반영 내용이 쭉 담겨져 있습니다. 
