<p><b>○ 경기개발연구원장 홍순영 </b> 거의 100% 된 것도 있고요. 또 부분적으로 저희들이 된 것도 있고 또 어떤 아이디어를 줘 가지고 정책 당국자들이 깨닫지 못하는 거를 저희들이 해줬다라든지 상당히 있습니다. 
