<p><b>○ 안병원 위원 </b> 네, 알겠습니다. 좌우간 나름대로 열심히 하셔서 좋은 그런 정책연구가 나와서 반영될 수, 도민들에게 좋은 쪽으로 반영될 수 있도록 해주시고요. 지금도 2020경기도종합발전계획 수립 진행하고 있죠?
