<p><b>○ 안병원 위원 </b> 업무보고 10쪽에 보면 2011년 3월 달부터 31개 시군 지자체 설명회가 있었고 또 7월 달에 도민공청회가 있었어요. 그런데 3월 달에 저희 김포도 설명회가 있었는데 그 당시에 한번 제가 중간에 말씀드렸던 사항도 있어요. 참 대단히 유감스럽고 잘못됐다. 그러면서 그 당시에 제 기억으로는 오셨던 주민들이 김포의 현안, 각 지역 지자체의 현안, 중요한 거 있는데 그런 것이 제대로 반영 안 되다 보니까 많이 실망하고 나가면서 한마디씩 다 하셨어요. 도의원들 “뭐하고 와! xx” 이런 식으로 했어요. 그런데 얼마 지나고 후에 보니까, 우리 지방언론 기사를 보니까 광주시에서도 거기에서 똑같은 사항이 벌어지더라고요. 그것을 보면서 ‘아, 이거 참 안 바뀌고 문제점이 있구나!’ 그런데 31개 지자체 설명회를 다니시면서, 원장님, 그 당시 안 계셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 와서 한 부분도 있고요, 안 와서 한 부분도 있고.
