<p><b>○ 안병원 위원 </b> 그런 부분에 대해서 많은 얘기 들었을 거고 또 31개 시군을 마치면서까지, 정확하게 제가 파악은 못했습니다만 그런 사항이 그대로 이루어진 건지 그 부분에서 그 당시에 설명하면서 많은 얘기들을 들었을 텐데 그 부분에 대해서 설명을 좀 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아마 이게 31개 군들은 군 자체 내에서 상당히 많은 또, 당연합니다만 요구사항이 있는데 아무래도 연구하는 입장에서 보면 전체를 다 아울러야 되기 때문에 예를 들어서 예산제약조건이라든지 또 경기도 전체를 보는 어떤 지역배치도라든지 뭐 이런 그림이 있기 때문에 아마도 이게 자칫하면 31개 군의 다 불만을 살 수 있는 그런 계획이 되기 십상이거든요. 왜냐하면 다 들어주면 좋지만 각 군마다. 그거 다 중요하고 또 그걸 비판하는 사람들을 저는 전혀 나무라고 싶은 마음은 없고요. 당연히 자기 군이나 이런 쪽의 하는 걸 담아야 되는데 아마 연구하는 분들은 그것을 다 담아주지 못하니까 아무래도 그 부분이 조금 그런 애로가 있지 않나 이렇게 생각을 하고 있습니다.
</p>
<p><b>○ 안병원 위원 </b> 어쨌거나 그 지역에 사시는 분들이 내 지역에 우선 어떤 것이 먼저 돼야만이 우리 생활에 또 여러 부분에 이로울 것인가 그런 부분에서 그런 얘기를 한 것이고 그런 것이 또 말 그대로 각 지자체를 통해서 도에까지 올라갔을 거란 말이에요. 그런데도 그런 반영이 안 되고 그대로 와서 획일적으로 그냥 설명회를 해버리니까 이제 그런 상황이 벌어졌었어요. 그래서 상당히 그때, 아마 여기 위원님들 전부 다 계시지만 그 당시 기분이었다면, 오늘도 이 자리에서 똑같다면 아마 여기서 엄청나게 안 좋은 그런 상황까지도 갈 수 있는 그 당시의 그런 마음이었다는 것을 말씀드리면서, 그러나 결론은 나중에 이런 사항이 다시 반영된 부분이 있죠. 이 문제점이 있기 때문에 지자체에서도 이것은, 다시 이것은 너무 잘못된 부분이다, 이것은 우리 지자체에 꼭 필요한 부분인데 아무리 도에서도 예산상 어떤 사항의 그런 문제점으로 인해서 그냥 딱 차단시켰을 때, 그러나 다시 그것이 반영된 부분이 얼마나 돼요?
