<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 도시ㆍ지역계획연구부 이상대고 도종합계획 수립 연구책임자입니다. 김포의 시군설명회에 가서 김포나 김포 시민들이 생각하는 만큼 그런 충실한 내용이 못돼서 죄송스럽게 생각하고…….
