<p><b>○ 안병원 위원 </b> 나중에 확 좀 바뀌었어요?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 시군설명회하고 난 다음에 또 수정이 되었고요. 그 시군설명회는 제가 방문을 해서 거듭 말씀드린 것처럼 의견을 청취하는 것이지 일방적으로 설명하고 양해를 구하는 것은 아니다라고 말씀을 드렸고요. 그래서 시군설명회 했을 때 191개의 의견이 나왔고 그중에 20개 정도는 미반영했습니다. 미반영한 것은 경전철 문제라든지 그다음에 시군이 해야 될 노인복지관 문제 이런 부분들은 반영을 하지 못했습니다. 그리고 김포 같은 경우에는 김포, 고양, 파주를 봤을 때 고양하고 파주 개성공단은 아무래도 주축인데 김포가 자꾸 발전축에서 밀리는 그런 부분이 있을 겁니다. 그래서 그런 것들이 김포시민들의 굉장히 불만사항이고 그래서 저희들이 김포-강화-해주로 연결되는 그와 같은 간선축, 성장축을 하나 만들었고요. 그다음에 김포도 공간구조 위계에 의해서 조금 다시 상향조정하는 식으로 또 수정을 했고. 그다음에 그때 사실은 김포시민들의 큰 불만 중에 하나가 중전철 문제였을 겁니다. 이 문제는 그 이후에 도하고 계속 상의해서 또 김포, 조금의 진전을 이루는 방향으로 계획을 수정한 바 있습니다.
</p>
<p><b>○ 안병원 위원 </b> 나름대로 그 후에 도민들이 원하는 그런 부분 또 지자체가 원하는 부분 이런 것에 아마 접근하셔서 약간 수정도 하고 바뀔 수 있는 것에 대해서는 열심히 하신 것에 대해서 고맙다는 말씀드리고 그러나 이것이 지금도 여기서 경기도, 경기개발연구원에서 아직도 하는데 11월, 이게 정확하게 마무리되는 시점이 언제쯤이에요?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 지금 저번 주 금요일 날 경기도 도시계획위원회에 심의ㆍ자문이 상정이 되었습니다. 그리고 18일 날 그것도 분과위에 위임이 돼서 예정대로라면 분과위원회에서 경기도 심의ㆍ자문이 종결될 거고요. 그리고 그다음에는 국토부에 승인신청이 올라갑니다.
</p>
<p><b>○ 안병원 위원 </b> 그렇죠.
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 그러면 국토부에서 관계부처 협의회를 하는데 저희들 생각은 12월 말까지 국토부의 승인신청을 받아내는 것을 목표로 하고 있습니다. 그런데 관계부처의 협의기간이 1개월은 촉박합니다. 그래서 1월 초로 조금 넘어갈 가능성도 있습니다. 그렇지만 국토부의 국토정책과에 저희들이 요청한 것은 연내로 깔끔하게 끝내서, 국토부도 그렇고 우리 경기도도 바로 내년 초부터 집행에 들어갈 수 있도록 협조해 줬으면 좋겠다는 우리 입장을 전달했고 국토정책과는 호의적입니다. 그런데 또 국토부 내에서 수도권정책과나 이런 데서는 여러 가지 다른 생각들이 있기 때문에 장담할 수 없는 상황입니다.
</p>
<p><b>○ 안병원 위원 </b> 또 얼마 전에 2020 경기도 종합발전계획에 인구계획이 빠졌다는 기사가 나왔었어요. 이 부분에 대해서는 어떻게 된 사항인지?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 인구부분은 도 종합계획에서는 일부러 시군별로 계획인구지표를 제시하지 않습니다. 사실은 계획이 집행성을 가지고 그다음에 계획이 실천성을 가지기 위해서는 도의 계획인구뿐만 아니라 시군마다 이렇게 줘야 되는데 그것이 잘못됐을 때는 경직적으로 흐르고 또 시군하고 도하고 입장차이가 명확하게 드러날 수 있기 때문에 도 종합계획에서는 경기도 전체적으로 지표를 제시하는 선에서 마무리할 생각입니다. 그것은 도도 지금 마찬가지 생각을 가지고 있습니다.
</p>
<p><b>○ 안병원 위원 </b> 시간이 거의 다 된 것 같은데 결론은 이런 사항이 도시 심의위까지 왔고 국토부 승인까지 이제 다가왔는데 프로테이지로 31개 지자체에서 점수를 매겨준다면 이 연구용역에 대해서 한번 몇 점 정도 나온 것 같아요?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 그것은 나중에 위원님께서 점수를 좀 매겨 주시고요.
</p>
<p><b>○ 안병원 위원 </b> 그렇죠. 도의원들이 금방 알 수가 있죠. 각 지자체 출신들이기 때문에, 지역이다 보니까 얼마나 열심히 했고 또 반영이 됐나 그런 부분에서.
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 당부, 그 당시도 말씀드렸지만 이상대 선임연구위원님이신데 참 말 한마디가……. 굉장히 그 당시에 느끼셨죠? 이렇게 친한 것도 좋지만 어떤 좋은 얘기해 주고 싶지만 항상 상대성이 있다는 얘기, 그것은 아마 살아가시는 동안에도, 이쪽의 권위자시지만 살아가시는 동안에 꼭 다시 한 번 생각하셔서 한쪽이 좋으면 한쪽은 진짜 아픔이 있고 여러 가지가 있습니다. 그런 부분에도 생각하시고 항상 발언해 주시고 이렇게 해주십시오.
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 네, 잘 알겠습니다.
</p>
<p><b>○ 안병원 위원 </b> 마치겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 다음 우리 김주삼 위원님.
</p>
<p><b>○ 김주삼 위원 </b> 군포 출신 김주삼 위원입니다. 원장님, 혹시 포퓰리즘 중에 좋은 포퓰리즘, 나쁜 포퓰리즘 그런 얘기 들어보셨어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> …….
</p>
<p><b>○ 김주삼 위원 </b> 네, 알겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 포퓰리즘이라는 말 자체는 그게 뭐라고 그럴까 가치판단이 없다고 생각합니다. 그러니까 나쁘다 좋다라기보다도 어떤 의미에서는 크게 보면 다 포퓰리즘이고 그럴 수도 있고…….
</p>
<p><b>○ 김주삼 위원 </b> 하여튼 알겠습니다. 들어보시지 않았으면 관계없고요. 그런데 하여튼 최근에 중앙 일간지에서 그렇게 글을 어느 분이 쓰셨더라고요. 좋은 포퓰리즘하고 나쁜 포퓰리즘. 그래서 일단 오전에 제가 했던 질의를 계속 이어서 좀 말씀을 드리겠습니다. 제가 오전에 우리 경기도에서 경기도 전체예산 중에 복지예산이 차지하는 비중이 어느 정도인가 물어봤는데 알아보셨습니까, 정확하게?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 한 20% 정도라는 걸로 알고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 아니, 대략이 아니고 이제는 정확히 얘기를 하셔야죠. 왜냐하면 제가 오전에 그 부분에 대해서 좀 알아보시라고 얘기를 드렸기 때문에. 그런데 저는 제가 굉장히 지금 이해가 잘 안 되는 부분이 분명히 경기개발연구원에서 우리 경기도 재정에 대해서 여러 가지 많은 자료들도 내고 연구도 하고 고민도 하고 그래서 재정위기라고까지 이런 자료도 냈는데 그중에 복지비용이 어느 정도 차지하는지에 대한 기본 데이터가 없이 이런 자료들이 나올 수 있는 건지 저는 지금 상식적으로 이해가 안 돼요. 그런데 그걸 연구를 하셨던 연구원님들도 그런 건 잘 모르세요? 아니면 우리 센터장도 그걸 잘 모르세요?
</p>
<p><b>○ 정책센터장 김은경 </b> 20% 정도로 알고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 정도가 아니라 정확히 얘기를 하셔야죠. 하여튼 알겠습니다. 그러니까 제가 지금 굉장히 우려스럽게 얘기하는 게 현재 우리 경기도 지방재정에 있어서 복지비용이 차지하는 비용이, 지출액이 정말 지방재정 위기로까지 얘기할 정도로 그렇게 과다한지 그리고 또 하나가, 이 부분은 제가 나중에 또 추가로 질문을 다시 드리겠습니다마는 그런 기본적인, 그러니까 예를 들어 그러면 그 위기의 근거가 어디하고 비교를 해서 그런 건지 그런 기본적인, 아주 기초적인 데이터를 지금 잘 모르고 계신다는 게 저는 좀 이해가 안 되고요. 그걸 다시 좀 정확히 알아보십시오. 그러니까 제가 자료로, 자료가 아니라 이따 구두로 말씀해 주세요. 전체적으로 우리 국가재정에서 차지하는 복지비 지출비율, 그다음에 경기도가 차지하는 비율 그다음에 각 시군들이 차지하는 비율 좀 밝혀주시고. 그다음에 OECD국가들의 평균 지방정부의 복지비 지출비율, 아마 그런 정도는 기본적으로 알고 계셔야 포퓰리즘에 대한 지방재정 위기 이런 자료들이 나올 수 있는 거고요.
</p>
<p style="padding-left:1.2em">  그 연장선상에서 이번에 보니까 2012년 정부예산안 평가라고 GRI에서 현안분석으로 내놓으셨더라고요. 우리 김은경 박사께서 하셨죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 잠깐만 나와 보시죠.
</p>
<p><b>○ 정책센터장 김은경 </b> 정책센터장 김은경입니다.
</p>
<p><b>○ 김주삼 위원 </b> 이 정부예산안 평가가 앞부분은 전체적인 현황을 얘기한 거고 이 평가라고 얘기한 부분이 우리 김은경 박사를 비롯한 연구진들의 판단이죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 의견입니다.
</p>
<p><b>○ 김주삼 위원 </b> 그리고 정책방향도 의견이고.
</p>
<p><b>○ 정책센터장 김은경 </b> 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 이 평가에 보면 소득수준 상관없이 만 5세 보육료, 유아학비 전액지원, 대학등록금 지원 등 경직성경비의 복지지출 이 부분에 대한 우려로 맞춤형 복지가 아니라 야당의 복지논쟁에 떠밀려갈수록 증가되고 있는 복지예산에 대한 신중한 검토가 필요하다 이렇게 견해를 주셨죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 이것은 변함없는, 그쪽 김은경 박사께서 혼자 하신 겁니까?
</p>
<p><b>○ 정책센터장 김은경 </b> 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그럼 신념이시네요?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 저는 향후 10년을 고려해서 예산을 짜야 된다고 생각을 합니다.
</p>
<p><b>○ 김주삼 위원 </b> 그렇지요. 맞춤형 복지로 가야 된다는 얘기죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 이 맞춤형 복지는 선별복지를 얘기하는 거죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 현 단계에서 선별적 복지라고 생각을 합니다.
</p>
<p><b>○ 김주삼 위원 </b> 선별적 복지라는 건 유감스럽게도 우리 민주당하고 틀린 한나라당의 당론이고 한나라당에서 주로 지금 추진하는 복지방향이죠. 그죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 저는 당을 보고 입장을 정하지는 않습니다. 제 개인적 입장입니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 어쨌든 그렇죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 지금 현재 모양새는 그런 것 같습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 맞춤형 복지, 선별적 복지는 한나라당의 지금 당론으로 정해진 복지정책입니다. 그리고 보편적 복지는 우리 민주당과 야당의 복지정책이거든요. 그러니까 선명하게 한나라당의 복지정책을 지금 여기에 얘기를 하신 거죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네. 한나라당의 복지정책을 얘기한 건 아닙니다.
</p>
<p><b>○ 김주삼 위원 </b> 네, 알겠습니다.
</p>
<p><b>○ 정책센터장 김은경 </b> 제 관점을 얘기한 겁니다.
</p>
<p><b>○ 김주삼 위원 </b> 어쨌든 그런데, 우리 그러면 김은경 박사는 확실하게 한나라당 복지정책의 관점에 동의하시는 거죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 제가 알기로는 민주당 내에서도 그러신 분이 많은 걸로 알고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 제가 얘기하는 것을 민주당이라고 묻지 않았거든요.
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 아까 민주당이라고 말씀하셔 가지고요.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 한나라당의 전체적인 복지정책에 확실히 동의하시는 거고?
</p>
<p><b>○ 정책센터장 김은경 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 그래서 그걸 이렇게 GRI나 경기도에서, 경기개발연구원에서 나오는 여러 자료에 계속 꾸준히 발표하시는 거고.
</p>
<p><b>○ 정책센터장 김은경 </b> 제 개인적 입장을 계속 제시하고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 들어가 주세요.
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 들어가겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 원장님, 잠깐 나와 주세요. 이렇게 어떤 자료가 대외적으로 나올 때 연구원의 개인적 신념을 충분히 연구자료로 발표하는 건 좋습니다. 그러나 이런 어떤 아주 예민한 현안분석이나 경기개발연구원의 자료가 특정 정당의 이런 정당정책을 대변하는 형태, 이런 자료들이 나오는 데 대해서 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 결과론적으로 특정 정당하고 같게 되는 것은 굉장히 유감이고요. 유감이고. 저희들은 사실 이렇게 하면서 어떤 정당을 갖다가 한 적은 없고요. 그게 우연하게, 또 우연하게 어떨 때 보면 민주당 정책하고도 뭐…….
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 제가 지금 정당이라고 표현을 했지만 저는 최소한 객관적인 자료라 하면, 맞춤형 복지로 가야 된다는 건 신념일 수 있습니다. 자기 정책적 판단일 수 있고 그러면 맞춤형 복지로 갔을 때의 장단점, 그다음에 보편적 복지로 갔을 때의 장단점도 함께 논의를 해서 객관적 시각을 유지시켜 줄 필요가 있지 않느냐 저는 그런 의미로 지금 묻는 거거든요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 옳습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 이게 개인적인 리포트면 관계가 없습니다. 김은경 박사 개인의 이름으로 나오는 리포트면 전혀 문제가 없죠. 누구도 이의제기 못하고 그냥 아, 저 사람의, 저분의 정책신념인가보다 그렇게 알죠. 그런데 도민의 혈세로 운영되는 경기개발연구원에서 나오는 리포트이기 때문에 문제가 되는 거예요. 저는 이런 평가들이 예를 들어서, 그걸 또 더 나아가서 지금 얘기를 하면 이미 맞춤형 복지가 잘못됐고 우리 사회는 앞으로 보편적 복지로 가야 된다는 건 모든 국민들이 동의했습니다. 대표적으로 최근에 서울시장 선거를 통해서도 그리고 서울 오세훈 시장의 주민투표를 통해서도 검증이 됐어요. 그 이전에 이미 우리가 계속 검증이 됐다, 검증이 됐다 했는데 최근에 그렇게 검증이 됐습니다. 그런데 그런 내용을 가지고도 지금도 특정 정당 연구원에서나 나올 법한 이런 리포트들이 나온다는 것에 대해서 저는 정말 경기개발연구원 이러면 안 됩니다. 정말 이런 식으로 계속 하면요, 특정 정당의 연구원 산하기관으로 존속시키든가 그래야지 도민의 혈세로 운영비 드릴 수가 없습니다. 아시겠습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 명심하겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 최소한의 객관적인 어떤 이 판단을 도민들이 할 수 있도록, 그리고 정말 이미 예를 들어서 보편적 복지가 여러 차례 국민들로부터, 도민들로부터 검증이 돼서 이건 안 된다고 판단이 됐다고 그렇게 칩시다. 그런다고 그러면 또 모르겠습니다. 그러니까 어떤 학문적 자기의 주관도 그것을 개인은 끝까지 주장할 수 있지만 그리고 개인의 이익을 대변하는 무슨 사설기관이나 연구, 특정기업의 기관이면 뭐 그럴 수도 있습니다. 그 기관의 이익을 대변해야 되기 때문에. 경기개발연구원은 어떻게 해야 됩니까? 모든 도민들이 가장 원하는 그리고 필요한 그런 정책들을 만들어서 그 정책의 논리적 저기를 만들어 주고 그렇게 정책을 펼 수 있도록 해줘야 되는 것 아닙니까? 그런데 이런 자료들을 버젓이 이렇게 낼 수 있는 저는 이런 시스템이 문제라는 얘기죠. 아까 연구원장님께서 각 개인들이 여러 가지 자료들을 낼 수 있다고 그랬는데 그걸 좀 시스템으로 통제할 수 있도록 해야 되지 않겠느냐 그런 의견도 잠깐 주셨는데 정말 필요한 겁니다. 그러니까 권위를 가진다면 그 권위에 맞는 어떤 이 시스템과 자료도 객관적 내용이 돼야죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 맞춤형 복지에 대한 이 부분은 이미, 뭐 학술적으로는 어떨지 모르겠습니다. 그러나 국민들 대다수는 이건 안 된다고 이미 판결을, 결론을 낸 것 아닙니까, 투표로? 민주주의 사회에서 가장 최고의 결론이 뭡니까? 투표입니다. 투표로 이건 안 된다고 했어요. 그런데 그걸 지금 끝까지, 이게 나온 게 언제입니까? 9월입니다. 9월 28일이니까 엊그저께죠. 저는 이런 연구원들이 경기개발연구원에 어떻게 지금 계속 계시는지 모르겠습니다마는 저는 이런 부분들에 대해서 연구원 자체 내부의 어떤 조치가 있어야 되지 않느냐 그런 생각을 합니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 필터링 시스템 같은 걸…….
</p>
<p><b>○ 김주삼 위원 </b> 뭔가 정말 객관적인 시각을 갖고 정말 올바르게 도민들을 위하는 도민의 입장에서 정말 우리 경기도의 이익이 되는 정책들을 펼 수 있도록 신념을 가지고 끝까지 밀어붙이는 건 좋습니다. 그런데 이미 사회적으로 그리고 이미 모든 국민들, 도민들은 선별적 복지는 싫다, 보편적 복지 해 달라고 지금 그런 것 아닙니까? 그래서 우리가 조금씩 조금씩 그 방향으로 지금 가는 것 아닙니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그 문제에 대해서는 적극 앞으로 연구할 때 참조하도록 하겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 많이 참고해 주시기 바랍니다. 그렇다고 제가 누구의 연구기능을 위축시키거나 그러려고 그러는 건 아닙니다. 그러나 최소한 우리 모두가 함께 공유하는 시대 보편적 어떤 함께 공유할 수 있는 그런 것들이 있잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그런 부분들에 대해서는 유의를 해주십사 하는 부분이고요. 앉아서 질의를 좀 드리겠습니다. 죄송합니다. 제가 일어나서 말씀을 드리게 한 것은 제 나름대로 상당히 중요한 부분이라고 생각이 돼서 그랬습니다. 앉아서 편하게 답변해 주셔도 되는데요.
</p>
<p style="padding-left:1.2em">  이것도 비슷한 내용일 수도 있지만 이건 제가 오전에도 잠깐 질의를 드렸는데 지금 우리 GRI 현안분석이라고 해서 나오는 여러 가지 자료들을 보면 우리가 조례개정을 했을 때에 국가사무는 역량이 좀, 물론 하면 좋지만 안 하고 우리 경기도에 집중했으면 좋겠다 그런 내용인데 실제 현안분석이 중국 경제 경착륙 위기론-그 의미와 시사점, 그다음에 일본 민주당 공약실패 시사점, 민주당정권 공약실패 시사점, 10월 15일 글로벌시위 현황 평가 및 전망, 계속 이런 자료들을 내거든요. 그러니까 의회에서 아무리 우리 경기도에 집중하라고 요청을 해도 ‘그래, 너희는 그렇게 요청해라. 우리는 우리 갈길 가겠다.’ 지금 그런 것인지 참 모르겠어요.
</p>
<p style="padding-left:1.2em">  저는 개인적으로는 제가 그 당시에, 조례 개정 당시에도 그랬습니다. 저는 조례에 국가사무가 들어가든 안 가든 중요하지는 않다. 중요한 건 우리 연구원 자체에서 스스로 판단해서 정말 집중해야 될 게 뭔가, 저는 그렇게 자율성을 부여하고 싶다고 그렇게 얘기를 했습니다. 그래서 그때도 유보적 저기였었는데 저는 그러면 정말 연구원에서, 우리 경기도의 현안들이 많잖아요. 그 많은 현안들에 집중할 줄 알았거든요. 그런데 이런 내용 그다음에 정말 아까 우리 지금 자료 받아오면 너무 어이가 없는 이런, 정말 정당 정책연구소에서 나올 만한 그런 리포트들 이렇게 쏟아내는 것 저는 정말 문제가 있고요.
</p>
<p style="padding-left:1.2em">  그 당시에 중요하게 얘기한 게 통일문제연구소 때문에 그랬습니다, 통일연구소 때문에. 그런데 실질적으로 저는 개인적으로 통일연구소가 됐든 남북교류연구소가 됐든 필요하다고 보고 그런 부분에 집중해 줬으면 좋겠다는 생각이었거든요. 그래서 조례에서 조례 개정할 때 나온 부분이 우리 경기도가 필요한 여러 가지 이익에 관계되는 국내외의 여러 가지 연구사례들 연구하는 것에 동의했었는데 저는 이런 부분들이 오전에도 잠깐 말씀드렸지만 우리 원장님 오시면서 이게 너무 정치적 색채를 드러내는 게 아닌가 그래서 우려가 됩니다. 그 우려에 대해서 앞으로 유의를 해주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  그리고 한 두 가지만 내부적인, 우리 연구원에 관련된 내부적인 질문을 드리겠습니다. 자료 가지고 계시죠? 업무보고 내용 질의입니다. 수탁용역사업 특별회계에서 전년도 대비해서 약 29억 정도 굉장히 많이 지금 감소를 했어요. 이 사유가 왜 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> …….
</p>
<p><b>○ 김주삼 위원 </b> 누구 다른 실무책임자 있으면 좀 답변을 해주세요. 직접 답변을 해주세요.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 재정지원과 강윤구 과장입니다. 자료에서 비교한 수치는요. 2010년도는 12월 말 기준이고요. 2011년은 9월 30일 기준 계약금입니다. 그래서 좀 차이가 있습니다마는 그 수탁용역사업이 건수는 비슷한데 금액이 줄어드는 추세에 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 수탁단가가 줄어든다는 얘기네요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 단가가 계약심사제도 때문에 그런지 사실 수탁 수주규모가 줄어들고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 아, 그리고 이건 9월 달까지라고요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 네, 그렇습니다.
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 그리고 일반회계 사업수입하고 특별회계 사업수입이 어떻게 차이가 납니까? 항목은 같은 걸로 지금 돼 있는데.
</p>
<p><b>○ 재정지원과장 강윤구 </b> 계리를 따로 하는 방법입니다. 그래서 저희가 수탁사업에서 벌어들이는 건 이익이 발생한 부분만 일반회계로 경상비로 전용해서 수입을 잡아서 쓰는 제도입니다.
</p>
<p><b>○ 김주삼 위원 </b> 그게 무슨 얘기죠?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 그 회계가 2개 설치돼 있어 가지고요.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 회계는 2개 설치되는데 사업수입이라는 건, 그러니까 그렇다는 얘기인가요? 예를 들어서 경기도청에서 받은 건 일반회계로 하고 아니면 외부기관에서 하는 건 특별회계로 하고 그런 내용인가요, 아니면 어떤 내용인가요?
</p>
<p><b>○ 재정지원과장 강윤구 </b> 제가 지금 사업수입에 대해서 조금만 설명을 보고드리도록 하겠습니다. 사업수입은 저희가 두 가지 일반회계 사업수입인데 수탁용역 사업수입하고 도서판매수입하고 2개가 사업수입으로 계리되는데요. 수탁용역사업 특별회계에서 수입이라 함은 계약고 전체를 얘기하고 일반회계에서 수입은 수익이 발생한 전출금의 수입만 얘기하고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 네, 알겠습니다. 그리고 장애인 채용이 현재 어느 정도나 돼 있죠, 여기에?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희 3명 지금 돼 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그럼 전체인원 중에 몇 %입니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 171명이거든요, 저희가?
</p>
<p><b>○ 김주삼 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 171명 중에서 그게 3을 171로 나누면 한 1.75가 되고요. 또 171을 2.3으로 하면 3.8명 이렇게 되더라고요. 그러니까 저희 이 해석이 좀 헷갈리는데 그래서 저희가 3명이면 일단 2.3%가 지금 된다고는 하더라고요. 하는데 저는 약간 좀…….
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 그게 법을 지금 맞췄냐 하는 부분보다 저는 장애인 채용이 잘 안 되는 어떤 이유가 있나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그러니까 저희도 웬만하면 장애인을 채용하려고 노력은 하고 있는데 그런데 이제…….
</p>
<p><b>○ 김주삼 위원 </b> 네, 계속 좀 노력을 해주시기 바랍니다.
