<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 그리고 비정규직 전환은 지금 어떻게 되고 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 저희가…….
