<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 정규직 전환, 그러니까 이게 제가 잠깐만 설명을 좀 드릴게요. 이거 제 개인적인 얘기를 좀 하겠습니다. 그러니까…….
</p>
<p><b>○ 김주삼 위원 </b> 잠깐만요. 연구원 말고요. 일반관리직 얘기하는 겁니다, 지금.
