</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 일반관리직이 한 10명 정도 저희들이…….
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 열 분 정도인데 일반관리직 중에 비정규직에서 정규직으로 전환한 분이 몇 명이나 되냐고요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 올해요? 올해는…….
</p>
<p><b>○ 김주삼 위원 </b> 아니, 지금까지요, 전부.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금까지는 2008년부터 3명 정도가 됐습니다. 3명이요.
</p>
<p><b>○ 김주삼 위원 </b> 제가 작년도 행정감사 때 지금 계속 2년, 3년 이상씩 지속적으로 근무하시는 분들 어차피 법적으로 정규직 전환을 해야 되는데 정규직 전환을 좀 할 수 있도록 해 달라 그랬는데 그게 잘 안 되고 있네요, 그럼. 세 분밖에 안 되면.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 저는 이것을 굉장히 적극적으로 생각하고 있는데 그래서 제 개인적으로는…….
</p>
<p><b>○ 김주삼 위원 </b> 적극적으로 생각해 주십시오.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 적극적으로 생각하고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 적극적으로 생각해서 올해 안으로 최소한 비정규직으로 계신 분들은 정규직으로 전환을 해주시는 게 필요하지 않느냐.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 여러 방법을 지금 생각하고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그리고 마지막으로 관리직 뽑을 때요. 지금 학력규정을 두고 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희는 관리직에서는 학력규정은 없습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 있죠. 그러니까 학력규정을…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 공식으로 규정으로 되어 있는 것은 없고요. 대학을 졸업해야 된다라든지 이런 건 없고요.
</p>
<p><b>○ 김주삼 위원 </b> 아니, 그런데 지금 홈페이지에 보면 사람 채용하실 때 저기가 있잖아요. 학력규정이 되어 있잖아요. 그죠?
