</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 관리직은 저는 없는 걸로 알고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 학사 이상 졸업이라고 되어 있습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래요? 그건 제가 좀 잘못 알고 있었습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 아시겠지만 이명박 정부에서도 학력철폐 해서 좀 저기한다고 그러는데 저는 그런 부분도 우리 공공기관들이 앞장서서 좀 해야 되리라고 생각합니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 10분씩 하신 다음에 한 번씩 더 기회를 드릴 테니까요. 다음 임병택 위원님.
</p>
<p><b>○ 임병택 위원 </b> 원장님께 여쭙겠습니다. 오전에 좌승희 이사장님께 지금 지급되고 있는 업무추진비와 차량과 그다음에 기사님과 관련된 예산지급의 근거를 좀 달라고 말씀을 드렸어요. 그래서 주신 게 GRI 제65차 이사회 개최계획. 이사장제 운영 활성화를 통해서 이사장 예우. 연간 소요예산 1억 800만 원, 차량기사 4,800만 원, 연구보조 3,600만 원, 업무추진비 2,400만 원, 사무실 지원, 기존시설 활용. 이렇게 되어 있습니다. 이 중에서 실질적으로 지금 이사장님께 지급되는 예우가 어떠어떠한 것들이 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 차량, 기사 포함해 가지고 차량 임차하고요. 그리고 업무추진비 그리고 사무실 지원 이렇게 되어 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 근거가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들은 그 근거는, 그러니까 이사장도 직원에 준하는 거죠. 그래서 비상근이기는 합니다만 비상근에 맞는 나름대로 이사장에 대한 대우를 하는 걸로 알고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 실질적으로 2011년도 예산편성지침이라는 경기개발연구원 편성지침이 있습니다. 이 편성지침의 31페이지 보면 업무추진비 예산편성기준, 직위별 예산편성기준에서 원장 월 300, 부원장 150, 이곳에는 우리 이사장이라는 분이 계시지 않아요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아마 그때는 이사장이 지사기 때문에 그런 거 아닌가 싶습니다.
</p>
<p><b>○ 임병택 위원 </b> 그러면 일단 이사장님께 드려야 된다라고 함은 그게 만약에 필요하다라면 2010년도 예산편성지침에 따라서 드려야 되는 게 절차적으로 타당한 게 아니겠습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 2011년도에 지사가 이사장을 관두고 다른 분이 이사장이 됐으면 아마 그때 뒀을 텐데 3월 달에 갑자기 결정돼 가지고 그런 거로 알고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 그러니까 편법지원하신 거잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 편법은 아닙니다. 왜냐하면 매년 사람을 하나 고용하면 그 사람에게 또 들어가는 거니까. 그것을 예를 들어서 우리가 연구원도 뽑기도 하고 이러는데 그러면 그전에 뽑는 것을 예측 못했다가 또 뽑고 그러는 것 때문에, 저는 이사장도 크게 봐서 연구원의 전체 직원이 아닌가 이런 생각 때문에 지금 됐기 때문에 이분이 다른 사람이라면 모르겠는데 그런 생각이 좀 듭니다. 
</p>
<p><b>○ 임병택 위원 </b> 우리가 관용차량을 사용할 수 있다라는 것은 공적 업무 수행에만 관용차량을 사용할 수가 있잖아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇죠.
</p>
<p><b>○ 임병택 위원 </b> 이사장이 비상근인 이유는 무엇입니까? 상근과 비상근의 차이가 뭐죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 글쎄, 아무래도 비상근으로 한 이유가 이사장을 상근으로 하면 원장을 갖다 조정할 거고 만날 와 가지고, 연구원 내 헤드가 또 두 명이고 그러면 뭐 좀 그런 문제 때문에 아마 안 둔 것 아닌가 이런 생각이 좀 듭니다. 
</p>
<p><b>○ 임병택 위원 </b> 비상근, 아니 그러니까 비상근이 365일 공적 업무를 수행하기 때문에 차량과 기사를 그렇게 대주고 계시는 거라고 생각하시는 거예요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아무래도 이사장이 하는 일들이 GRI의 명성도 높이는 일도 하고 또 검증된 분이시고, 이 양반이. 그래서 여러 가지 활동하는 데 편의를 봐주는 거 아닌가 저는 그렇게 생각하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 아니, 편의를 봐 주시기 위해서 규정에도 없는 우리 공적인 조직에서…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이때 편의라는 건요. 일반적으로 말하는 그런 편의가 아니라 이사장님이 이사장으로서의 역할을 하실 때 아무래도 좀 더 편하게 하시라고 그러는 차원에서.
</p>
<p><b>○ 위원장 강득구 </b> 그런데 원장님, 제가 말을 막아서 미안한데요. 편하게 해드릴 수 있죠. 그리고 경기개발연구원의 명성을 높이는 데 큰 역할을 한다. 다 좋아요. 그런데 공무원들이 하는 모든 행위는 법적 근거를 갖고 하는 거잖아요. 그죠? 행정행위가 어쨌거나 다 법적 근거를 갖고 하는 거잖아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그런데 편의를 봐줘야 된다. 그러면 법적 근거를 확보한 다음에 해야 되는 거잖아요? 아니, 행정……,
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 이때 편의라는 것은 제가 일반 어휘의 편의가 아니라요. 우리가 지금 모든 공직에 있어서 어떤…….
</p>
<p><b>○ 위원장 강득구 </b> 홍순영 원장께서 세리(SERI)에 근무하셨죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 예를 들면 이건희 회장이 삼성 계열회사에 이사로 등재된 데가 있고 등재 안 된 데가 있죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇죠.
</p>
<p><b>○ 위원장 강득구 </b> 등재가 된 데에는 이사에 대한 수당이 나오죠? 등재가 안 된 데는 수당이 안 나오죠? 똑같은 거죠. 그러니까 이게 법적 근거가 없는데, 뒷받침해 줄 수 있는 근거가 없는데 어떻게 편의를 봐준다고 이렇게, 이건 개인회사가 아니잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아닙니다. 제가 개인적인 얘기한 것이 이사장에게 나가는, 지출하는 비용이 당연히 연구소 내의 예산으로 나가는 거죠. 그게 법적 근거가 없는 게 아니죠. 그러면 만약에 저희가 법적 근거가 없이 이사장한테 나간다든지 그러면 문제죠.
</p>
<p><b>○ 위원장 강득구 </b> 그러면 지난번에 김문수 지사는 현직 지사이기 때문에 안 나갔다는 겁니까? 그건요 예산편성지침의 기본을 모르는 거죠. 예산편성지침에 이사장은 얼마만큼  나가게 한다라는 지침하에서 움직이는 게 맞죠.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이분 같은 경우는 굉장히…….
</p>
<p><b>○ 위원장 강득구 </b> 지금 한 말에 대해서 책임질 수 있나요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 어떤…….
</p>
<p><b>○ 위원장 강득구 </b> 지금 예를 들면 나가는 게 당연하다라고 말씀하시는 거잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 당연한 것은 아니고요. 저희가 이사장에 대해서…….
</p>
<p><b>○ 위원장 강득구 </b> 분명히 법적 근거, 편성지침 포함해서 규정이나 내부지침이 없는데 예를 들면 운전기사, 사무실, 사무실까지는 몰라요. 운전기사 월급 또 업무추진비, 연구비 이게 나가는 게 과연 맞는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 연구비는 아니고요.
</p>
<p><b>○ 위원장 강득구 </b> 거기에 지금 연구비도 포함되어 있잖아요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들이 정확하게는 차량하고 업무추진비 그 두 가지죠. 두 가지고, 그래서 하여간 여러 위원님들 지금 염려하신 바가 뭔지 충분히 알고요. 다시 한 번 제가 확인해 가지고 그 예우에 대한 것은 저희가 법적 검토를 다시 해서 정확하게 하겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그러면 이사장 예우에 대한 규정을 만들어서 그걸 이사회 의결을 거친 다음에, 그렇게 한 다음에 시행하는 게 맞죠. 이건 지극히 상식적인 건데 그것을 자꾸자꾸 당연히 이사장, 지침에 없다라고 하더라도 경기개발연구원의 나름대로 명성을 높여주는 분이기 때문에 해야 된다. 이렇게 자의적으로 판단한다라는 게 이해가, 누가 이해하겠습니까. 설령 이해를 한다고 하더라도 법적 근거 없이 누가 그렇게 할 수가 있어요. 이거는 그러면 정식으로 우리가 경기도 감사파트에다 감사요구를 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희가 여기, 다시 한 번 제가 2011년도 업무추진비 예산편성기준 변경안이라고 되어 있고요.
</p>
<p><b>○ 위원장 강득구 </b> 아니, 그러니까 2011년도…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 이게 저희들이 예산 같은 건 도의 허락을 받거든요. 그래서 거기의 허락을 받았고요, 이사장에 대한 저거를 갖다가. 그래서 자의적으로, 이따 보시면 아시겠지만, 무슨 말씀하시는지 제가 충분히 이해했고요. 이해했는데…….
</p>
<p><b>○ 위원장 강득구 </b> 도의 허가를 득했다고 그러는데 그러면 여기 정관이나 임원 예우규정 이런 부분에 그게 나와 있어야 되는데 없잖아요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그게 2011년도, 작년도에 10월 26일까지 이렇게 돼 있는 거로 돼 있고요.
</p>
<p><b>○ 임병택 위원 </b> 위원장님, 제가…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 충분히…….
</p>
<p><b>○ 임병택 위원 </b> 김태호 국무총리 후보자가 낙마한 결정적인 이유 중의 하나가 부인이 경남도의 관용차를 타고 학교로 출퇴근한 사례가 지적이 됨으로 인해서 그 부도덕성이 부각됐던 적이 있습니다. 우리 관용차량이, 비상근이세요. 이사장님이 상근이 아니고 비상근이신데 예우 차원에서 종일 기사와 차량을 지급한다라는 것은 대단한 도덕적 해이로 보이거든요. 차량을 지원해야 된다는 근거 자체도, 규정 자체도 아예 없습니다. 그것은 비상근임에도 불구하고 관용차량을 대줄 수 있다라는 건 저는 도저히 상식적으로 이해가 안 됩니다. 지원할 수 있다라는 근거를 가져오라고 하니까 가져오지 못하셨잖아요. 주셨습니까, 저에게? 주지 못하셨잖아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 저희들은, 일단 저희가 한번 검토해 보고요. 지금 위원님들 말씀을 고려해서 다시 한 번 이 문제를 재검토하도록 하겠습니다. 그런데 저희들이 참고로 말씀드리면 일단 예산 같은 사항은 도의 승인을 받아야 되고 저희들은 작년도 예산편성지침에 들어가 있었고 또 이번에 새롭게 이사장을 바꾸면서 그 지침을 받아 가지고 시행을 했다 이렇게 말씀드릴 수 있겠고 다만, 비상근에 대해서 차량 운행하는 지급은 좀 과다한 거 아니냐라는 것은 저희들이 충분히 이해가 되는 그런 대목입니다.
</p>
<p><b>○ 임병택 위원 </b> 감사관실에 정식으로 감사를 의뢰할 겁니다, 의회 이름으로. 그 부분에 대해서 그 결과 가지고, 원장님께서 오늘 말씀하셨던 부분 속기록에 다 남아 있습니다. 그래서 과연 원장님의 인식이 옳았는지 저희들의 인식이 옳았는지에 대해서는 공식적으로 다시 한 번 밝히는 자리가 있을 거라고 보여집니다. 
</p>
<p style="padding-left:1.2em">  우리 정책센터 현안자료를 제가 받아봤습니다. 원장님께서 부임하신 이후에 정책센터라는 기구가 만들어졌죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그리고 또 권칠승 위원님과 김주삼 위원님께서 말씀하시는 시비소지가 있는 연구자료들이 발표가 됐어요. 그렇죠? 정책센터가 만들어진 이후에 그러한 보고들이 지사님께 올라간 것 아니겠습니까. 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그건 사실이죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 시비 여지가, 저는 오늘 될 수 있으면 아규(argue)를 지금 안 하려고 그러거든요.
</p>
<p><b>○ 임병택 위원 </b> 네?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아규를 안 하려고 그러거든요. 그런데 시비의 기준도 그게 저희가 만약에 다른 쪽으로 쓰면 또 다른 쪽에서 시비가 걸리고 그래서 그런 애로가 좀 있습니다. 다만 보실 때 그런 문제가 있다라는 걸 저희들이 충분히 감안해서 그래서 일단 이 현안을 올리는데 아무래도 주관적으로, 작성자의 주관이 약간 좀 실려 있고 제가 중간에서 정말 객관적 삼자로서 그걸 일일이 다 검토하고 이랬어야 되는데 그걸 못한 거에 대해서는 제 불찰로 생각하고 앞으로 굉장히 편차를 줄이도록 노력하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 개인적으로는 참 자괴감이 드는 이유가 1년 전 행정사무감사 때 경기개발연구원이 김문수 도지사의 싱크탱크, 경기도민의 싱크탱크는 되어야 하지만 대통령 후보 김문수 싱크탱크 역할을 하는 것은 정말 부당하다는 지적을 했습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 옳으신 말씀입니다. 
</p>
<p><b>○ 임병택 위원 </b> 이것은 여기에 몇몇 자료도 있죠. 받아봤습니다. 받아봤는데, 이것은 우리 경기개발연구원이 만들어낼 연구보고서의 성격이 아닌 것 같고요. 이것은 비서실 내지는 외부에 있는 대선캠프에서 생산해야 될 문건들이라고 저는 생각해요. 이것은 저도 경기도민을 대표하는 의원의 입장에서 말씀드리는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 참고로 여기 제목들, 타이틀 쭉 있지 않습니까? 대부분 제가 볼 때는, 제가 객관적으로 경기개발연구원장으로서 얘기할 수 있는 게 여기 지금 1번부터 쭉 현안들이 있는데, 사람별로, 제가 볼 때는 경기도하고 대부분 관계가 있는 것 같거든요. 이게 뭐 어떤 예를 들어서 “대학진학률 80% 허와 실”이다, 이건 어떻게 보면 경기도와 관계가 있을 수도 있고 없을 수도 있는데 이러한 것도 경기도하고 굉장히 관계가 있거든요. 그래서 제가 볼 때는 우리가 어떤 정무적 판단이라든지 정치적인 사안에 대해 가지고 이렇게 한 것은 저는 거의 없다고 보고요. 지금 상당히 많은 현안이 올라가 있는데 대부분 경기도지사로서의, 그러니까 저희들이 공개를 한 거거든요. 만약에 그렇다면 공개 안 했겠죠.
</p>
<p><b>○ 임병택 위원 </b> 아니, 그러면 원장님. “권칠승 위원님과 김주삼 위원님 지적을 100% 수용한다는 전제하에 저는 이렇게 생각합니다.”라고 말씀하셨던 것은 거짓이 되는 거예요.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니, 지금 그것을 100% 수용한다는 전제하에서, 제가 아까 말씀드릴 기회를 놓쳐서 그러는데 저희들이 현안 같은 걸 쭉 하는데 그 현안의, 아까도 말씀드렸지만 대부분의, 이제 몇 개가 그렇거든요. 몇 개가 오해의 소지가 있는 부분들, 아까 MRO라든지 프리런치 이런 건 정말 충분히 오해의 소지가 있다고 생각하고 그런데 그런 거를 제외하고는 저희들이 볼 때 대부분의 연구내용이 이렇게 어떤 한…….
</p>
<p><b>○ 임병택 위원 </b> 무소속 돌풍은 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 무소속 돌풍도 당시에 무소속이 나왔을 때 좀 관심이 있을 것 같다라고 생각이 들어서 한 거거든요.
</p>
<p><b>○ 임병택 위원 </b> 경기도민들이요, 아니면 지사님이?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지사님도 그렇고 경기도 공무원들도 그렇고 아마도 많은 분들이 관심이 있었을 겁니다. 그런데 저희들은 싱크탱크라는 것이 굉장히 어떻게 보면 폭넓은 걸 다뤄달라는 주문이 굉장히 많습니다, 저희한테. 그러니까 그것도 사실은 도정을 이끌어 나가는데 지금 새로운 어떤 물결이 흐른다 그러면 당연히 여기에 반영해야 되지 않겠습니까? 그래서 과거에 예를 들어서 어떤 이데올로기적인 편향이 있었다면 새롭게 중간지대가 많이 나오고 그리고 그런 분들이 바라는 바가 굉장히 또 다른 욕구라든지 수요가 많이 있을 것 아닙니까. 경기도 내부에서도? 그러면 그것을 적극적으로 반영해야 되겠다라는 생각도 들기 때문에 이게 무슨 어떤 대선주자, 이것은 누가 봐도 판단할 수 있는 것을 갖다가 저희들이 구태여 그걸 할 거는 아니라고 생각하고 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 원장님은 원장님 본분에 충실하셔야 될 것 같고요. 저희들은 저희들의 본분에 충실하겠습니다. 그리고 저희 의원들에게 주어진 예산에 대한 승인권을 잘 활용하도록 할 것이고요. 저는 대단히 실망입니다, 개인적으로는, 원장님의 인식에 대해서. 정말 그 정도는 문제가 없어 보인다라고 생각하시는 거 자체가 적어도 제가 생각했던 원장님의 첫인상과는 너무나도 다르기 때문에 개인적인 소회를 밝혀드립니다. 보십시오. 이제 정 그렇게 말씀하시면 이슈＆진단 제18호죠. “지방예산의 위기와 정책방향” 이 보고서에 대해서 며칠 전 우리 도의회 본회의에서 고양의 이재준 의원께서 문제점을 지적하신 내용을 보고받으셨습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 보고받았습니다. 
</p>
<p><b>○ 임병택 위원 </b> 어떤 내용이었죠? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 8페이지에 “예산편성권의 혼란으로 인한 예산편성 난맥” 타이틀이 이렇게 되어 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 이재준 의원의 문제의식에 대해서 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 지금 이재준 의원 거기에 대한 답변은 아니고요. 8페이지에 보면 지금 분명히 지방자치단체의 예산편성권이 충돌하는 것은 사실인 것 같아요, 저희들이 볼 때.
</p>
<p><b>○ 임병택 위원 </b> 9페이지 한번 봐주십시오. 제가 읽어드릴게요. “지방의회의 재정비율 부족으로 인해 각종 사업확대를 통한 이권추구 및 복지예산 증가를 통한 대중영합주의적 경향 강화”. 경기도의회의 이권추구라고 되어 있는 거죠. 경기도의회가 어떠한 이권을 추구했죠? 센터장님, 발언대로 나와서 소속을 밝히고 말씀하시죠.
</p>
<p><b>○ 정책센터장 김은경 </b> 정책센터장 김은경입니다. 저희는 이슈＆진단의 원칙들은 기본적으로 우리나라 전반적인 어떤 현안들이나 이런 걸 좀 많이 다뤄보자. 그리고 연구자들이 경기도의 현안 자체가 전국적인 이슈와 많이 맞물려 있기 때문에 그러한 관점에서 보는 겁니다. 그래서 보시다시피 저희는 18쪽까지의 모든 통계나 이런 것들은 경기도 통계보다는 전국 통계를 중심으로 저희가 얘기를 하고 있고요. 그리고 기본적으로 나오는 얘기들도 경기도의회의 문제가 아니라 전반적인 기초자치단체가 될 수도 있고 어떤 특정 의회가 될 수도 있겠지만 저희는 전반적으로 지적되고 있는 현재 상황들을 얘기한 것이지 경기도의회가 이권을 추구한다라는 이런 얘기는 전혀 없습니다.
</p>
<p><b>○ 임병택 위원 </b> 지방의회에 경기도의회가 포함되죠?
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 그렇습니다. 하지만 모든 지방의회가 그렇지는 않지 않습니까.
</p>
<p><b>○ 임병택 위원 </b> 경기도의회가 지방의회에 포함됩니다. 
</p>
<p><b>○ 정책센터장 김은경 </b> 네, 포함됩니다.
</p>
<p><b>○ 임병택 위원 </b> 센터장님 앉으시고요. 저는 여기에서 제가 의원으로서 상당한 모멸감을 느끼면서 말씀드리는 건데 지방예산의 위기의 원인 해서 중앙정부의 재원이양 없는, 그다음에 예산편성권의 혼란으로 인한 예산 난맥, 중앙정부의 지방재정 관리강화로 인한 예산 압박. 거기에 저희 경기도의회, 또 야당이 의회 다수를 차지하는 경우 압력이 더욱 증가한다. 이런 의견을 썼어요. 저는 우리 경기개발연구원에서 최소한 정치적으로 독립된 기관이라고 보고 좀 균형 잡힌 보고서가 나왔으면 좋겠다라는 그런 바람에서 당부의 말씀을 드리는 건데요. 국회예산정책처가 있습니다. 국회예산정책처에서 분석한 자료 중의 하나 이제 보도자료인데요. 감세로 인해 지방재정 30.2조 원이 감소한다라고 국회예산정책처에서 이러한 보고자료를 내놓은 적이 있어요. 관련 연구자료는 무조건 두텁죠. 감세로 인해서, 감세는 우리 민주당 측에서 주장하는 것은 부자감세라고 표현하고 있습니다만 감세로 인해서 우리 경기도만 해서 2조 5,000억 원이, 이명박 대통령의 감세정책에 의해서 2조 5,000억이라는 지방세 감소가 예상된다라는 이 자료가 있습니다. 저는 그렇다면 우리 경기개발연구원 지방예산의 위기와 정책방향에 현 정부의 그러한, 우리가 많이들 알고 있잖아요. 상식적으로 이명박 MB정부에서 감세로 인해 지방재정이 악화되고 있다라는 그 단순한 상식조차도 표현하지 않으면서 지방의회 탓을 하고 있다라는 이런 문제의식 자체가 무척 저는 통탄스럽다라는 그런 말씀입니다. 저는 그런 가운데 오전에도 그렇고 오후에도 그렇습니다. 경기개발연구원장 홍순영 원장님, 저는 작년 행감 때도 그랬습니다. 경기개발연구원이 정치적으로 좀 중심을 잡아 달라. 아니, 그러한 요구가 집행부에서 있으면, 지사님의 요구가 있으면 원장님이 커버를 해드려야죠. 연구원들의 중립성을 지켜드리기 위해서 원장님이 바람막이 역할을 하셔야 되는데 최소한 좌승희 원장 그분께서는 행감장에서 말씀이라도 그렇게 하셨어요. 원장님께서는 전혀 문제가 없다라는 취지로 이야기하시는 것에 대해서 저는…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 문제가 없다는 얘기가 아니고요. 저희가 현안 얘기를 할 때 다 지금 공개하고 이러는 게 상당히 많은 부분이 현안이기 때문에 어떻게 보면 경기도의 현안이고 어떻게 보면 중앙정부의 현안이지만 그게 다 경기도랑 같게……. 지난번에 저희들이 조례개정할 때도 계속 그런 문제가 나왔었고 그래서 저희들이 적극적으로 설명을 해서, 그래서 어떤 개인의 중앙정치하는 데 그런 것은 좀 아니지 않느냐 그런 취지에서 말씀을 드린 거지 저는 위원님 말씀에 반박할 그럴 의도는 전혀 없습니다. 
</p>
<p><b>○ 임병택 위원 </b> 알겠습니다. 그리고 홍보비와 관련된 부분을 좀 하나 여쭙겠습니다. 데일리와이의 기사죠. 기사내용을 보면 우리 경기개발연구원 홍보 책임자께서 그렇게 인터뷰를 하셨습니다. “경기개발연구원이 독자적으로 판단해서 집행하는 홍보예산은 거의 없다. 90% 이상이 대변인실의 요구가 있다.”라는 인터뷰를 하셨어요. 경기개발연구원이, 이 엄청난 브레인집단이 광고 집행 하나도 경기도 대변인실의 조종을 받아야 되는 겁니까? 그거 알고 계셨습니까, 원장님? 실상이 그렇다라는 것.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 데일리와이에 대한 것을 보고를 받았고요. 홍보 같은 경우는 이게 주로, 해명이 어려운 부분인데…….
</p>
<p><b>○ 임병택 위원 </b> 작년 행정감사 때도 지적이 됐었던 사항으로 알고 있습니다. 대변인실이 독립된 우리 경기도 관련 기관들에게 압력 가해서 언론광고비를 조종하고 있는 행태에 대해서 지적을 했어요. 지적을 했는데 한 가지 개선된 점은 광고형 정책기사 광고를 하지 않았다라는 것에 대해서는 저는 지적사항을 수용해 주셔서 감사합니다. 그러나 경기개발연구원이 독자적 판단하에서 광고비를 집행하는 게 아니라는 것은 그 관습은, 아니 그런 관행은 경기개발연구원이 좀 과감히 끊어주셨으면 좋겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 이상으로 마치겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 또 다른 위원님. 김현삼 위원님.
</p>
<p><b>○ 김현삼 위원 </b> 김현삼 위원입니다. 장시간 지속되는 행정사무감사에 원장님 수고하십니다. 제가 물어볼 게 많아서, 질의를 드릴 게 많아서…….
</p>
<p><b>○ 위원장 강득구 </b> 10분씩 하고 한 바퀴 더 도는 걸로 하겠습니다.
</p>
<p><b>○ 김현삼 위원 </b> 하여튼 10분 동안 한번 해보도록 하겠습니다. 분위기를 좀 바꿔서요. 우리 경기개발연구원은 우리 경기도의 종합연구기관이죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 그렇습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그런데 보면 도 산하공공기관 중에서 자체적으로 연구기능을 수행하고 있는 데가 몇 군데가 있어요. 그렇죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 알고 계시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 그래서 저는 이게 경기개발연구원의 위상과 기능에 있어서 변화가 올 수 있는 가능성이 있다 이렇게 보여지거든요. 왜냐하면 조금 전에 저도 주장했고 우리 원장님도 말씀하셨던 것처럼 경기개발연구원은 그야말로 어떤 특정 분야에 대해서 연구하는 기관이 아니고 경기도가 도정을 수행하는 데 있어서 필요한 거의 대부분의 의제들을 종합적으로 연구하는 그런 기관인데 경기도 내 산하 각 기관들이 자체적으로 연구능력을 확보해서 연구를 수행하는 게 최근의 흐름인 것 같고 또 많아지고 있더라고요. 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 GRI 원장이기 때문에 드리는 말씀은 아닌데요. 저희들이 계속 협의를 해본다든지 도의 공무원들이라든지 이런 사람들의 평가를 들어 보면 그래도 GRI가 아무래도 전통도 있고 또 인력풀이라든지 이런 쪽을 통해서  굉장히 아직도 전반적인 연구에 대해서는 상당히 비교우위를 갖고 있다 이렇게 좀 자화자찬 겸 말씀을 드립니다. 
</p>
<p><b>○ 김현삼 위원 </b> 제가 왜 이 말씀을 드리냐면 저는 개인적으로 경기도 내 경기개발연구원을 제외한 나머지 기관들이 자체적으로 연구수행 능력을 갖추는 것에 대해서사실 좀 부정적으로 보는 입장입니다. 왜냐하면 연구라고 하는 것은 아시는 것처럼 연구를 사전에 기획을 해야 되고 그리고 연구를 수행해야 되고 연구수행하는 과정에 또 서포트가 이루어져야 되고 그것을 뒷받침해 주는 이를테면 행정인력이 또 있어야 되고 이런, 하나의 연구 성과물이 나오기 위해서는 다층적인 그런 과정들이 진행이 되는데 그게 전부 다 비용이고 예산이란 말이죠. 그래서 경기도 재정 건전성이 지금 극도로 악화되어 있는 현재 시점에서 산하기관들이 그렇게 하는 게 과연 올바른 건가. 종합적인 연구기관으로서 경기개발연구원이 있는데도 불구하고. 결국 제가 기획조정실 행정사무감사 때 기조정실장하고 토론을 한번 해보겠습니다만 본 위원은 그런 문제의식을 갖고 있다라고 하는 걸 일단 말씀을 좀 드리고 우리 경기개발연구원이 종합적인 연구수행기관으로서 자기 위상을 보다 분명히 할 수 있도록 보다 더 배전의 노력을 기울였으면 좋겠다 이런 말씀을 드리고자 이런 말씀을 드렸습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다. 
</p>
<p><b>○ 김현삼 위원 </b> 그다음에 작년 6ㆍ2지방선거가 그 두 번째 질문인데요. 작년 6ㆍ2지방선거 끝나고 난 이후에 몇 개 지자체가 이를테면 비정규직을 정규직화하는 다양한 노력들을 시도하고 있습니다. 전남 순천이랄지 성남도 그렇고요. 그리고 얼마 전에 보궐선거를 통해서 당선된 박원순 서울시장이 서울시 비정규직 2,800명의 정규직화를 위해서 타당성조사를 한번 해보겠다, 이런 얘기를 발언한 적이 있는데요. 정규직화가, 비정규직이 정규직화하는 것은 올바른 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 사실은 일단 찬성이고요. 될 수 있으면 비정규직이 없어야 된다고 생각하고요. 이 말조차도, 용어조차도, 제가 여기 와서 깜짝 놀란 게 도대체 용어가 규정상 정규직ㆍ비정규직이라는 용어가 있느냐를 제가 먼저 살펴봤습니다. 그런데 어디 근거도 정규직ㆍ비정규직이란 용어는 없습니다, 지금. 그래서 이 문제 가지고 저는 굉장히 개인적으로 연구의 과제가 되는데 일단 비정규직은 없어야 된다고 개인적으로 생각하고 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그래서 제가 자료를 찾아보니까 2011년 8월 말 현재 통계청이 발표한 비정규직 숫자가 600만 명이고 그런데 노동계 쪽에서 주장하는 비정규직 숫자는 830만 명이라고 주장하고 있습니다. 그리고 전체 경제활동인구의 약 48.7%가 해당되는 거고요. 임금총액은 정규직에 대비하면 비정규직이 50%를 조금 상회하는 약 56% 정도 이렇게 되는 거로 봐서 이것은 단순하게 비정규직의 정규직화가 당사자들의 어떤 권익보호 차원을 뛰어넘어서 사회적 통합 그리고 경쟁력 강화라고 하는 국가적 관점에서도 대단히 중요한 문제다 이렇게 보여지고 있는데요. 저는 그런 측면에서 봤을 때 GRI가 내년도 정책연구과제를 이것을 한번 해봤으면 좋겠어요. 물론 김문수 지사의 어떤 관점이라고 하는 게 있기 때문에, 뭐 그건 차치하더라도 연구기관으로서 경기개발연구원이 경기도를 비롯한 경기도 산하기관들, 지금 경기개발연구원 같은 경우도 뭡니까, 정원이. 현원이 74명인데 이 74명을 상회하는 숫자가 이를테면 비정규직, 우리 원장님께서 주장하시는 지금 유기직으로 돼 있는 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 그처럼 지금 문제가 심각한데 경기도를 비롯한 산하기관들의 유기직, 그러니까 비정규직의 실태에 대해서 조사를 한번 해보는 건 어떨까 제가 제안을 드립니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 좋습니다. 저는 개인적인 바람은 제가 그걸 갖다가 몇 번 말씀을 드렸는데 비정규직 없는 경기도가 제 개인적인 모토입니다.
</p>
<p><b>○ 김현삼 위원 </b> 그거 연구과제로 선정해서 한번 연구해 보실 의향 있으신 거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 세 번째 질문드리도록 하겠습니다. 경기비전 2020 담당하시는 이상대 박사님 잠깐만 좀 앞으로 나와 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  황해경제자유구역이 2008년 5월 달에 지정이 됐고요. 그렇죠? 지정이 된 이유는 평택항배후단지를 개발하기 위해서 황해경제자유구역을 지정했습니다. 그런데 얼마 전 8월 달에 지식경제부의 축소방침에 따라서 이를테면 향남지구 같은 경우는 161만 평이 전면 해제됐고 그리고 포승지구 같은 경우는 포승지구가 한 609만 평 되는데 100만 평으로, 그러니까 1/6로 축소된 것 알고 계시죠?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 도시ㆍ지역계획부장 이상대입니다. 이 부분은 경제사회연구부에서 종합관리를 하고 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 아, 그렇습니까? 그러면 우리 경제사회연구부장님 좀 나오시죠.
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 경제사회부장 김군수입니다.
</p>
<p><b>○ 김현삼 위원 </b> 제가 조금 전에 질문드렸던 내용 인식하셨나요?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네, 알고 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그게 사실인 거죠?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네, 맞습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그 해제되거나 또는 축소된 이유가 뭐죠?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 우선 가장 중요한 게 LH공사가 그 사업추진 주체였는데 여러 가지 경제사정이나 LH공사 내부의 사정 때문에 그 공사를 추진하지 못하게 됐습니다. 그래서 가장 중요한 게 그 사업주체가 있어야지만 그 사업이 추진될 수 있고 그래서 약 100만 평에 해당되는 것만 사업추진 주체가 있기 때문에 그것만 추진하는 걸로 그렇게 됐습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그렇죠. 그 경제주체가, 개발주체가 불분명하고.
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그런 밑바탕의 원인들은 장기적인 부동산 경기침체랄지 이를테면 제조업의 위축 이런 것들이 원인이 됐겠죠.
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그렇습니다. 그래서 이제 그렇게 축소가 됐는데 그런데 11페이지 보게 되면 경기개발연구원이 지식경제부에 2011년 3월 15일 날 경기경제자유구역 개발계획을 제출했어요. 그죠?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네, 그렇습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그리고 여기 보면 군자지구, 시화MTV, 송산그린시티, 대송지구, 해양복합산업단지, 해양레저 콤플렉스 해 가지고 제가 대충 계산을 해보니까 한 1,000만 평 정도 되더라고요. 1,000만 평 정도가 되든데 이게 문제없습니까? 한쪽에서는 이를테면 축소하고 폐지하는데 지금 경기개발연구원에서는 다시 경기경제자유구역을 확대하는 이런 연구를 수행하는 게 앞뒤가 안 맞는 것 아닌가요?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 이와 관련해서 도에서 요청이 와서 저희가 연구를 했는데요. 지금 5개 지구가 약 1억 ㎡입니다. 약 3,000만 평 정도가 되는데…….
</p>
<p><b>○ 김현삼 위원 </b> 3,000만 평.
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 이 중에서 시화, 송산, 대송 3개 지구를 뺀 군자, 해양복합, 해양레저 이 3개 지구를 합한 게 785만 ㎡입니다. 이 3개 지구가 지자체 소유의 땅으로 되어 있습니다. 그래서 사업주체가 지금 현재 있고 그래서 이 3개만 지금 경기경제자유구역으로 지금 하려고…….
</p>
<p><b>○ 김현삼 위원 </b> 아니, 그러니까 제가 드리는 말씀은 뭐냐면 한편에서는 바로 옆 동네에서 지정됐던 경제자유구역이 축소되고 폐지되는 마당에 또 바로 옆 동네에서는 그것을 다시 지정해서 확대하는 이런 정책이 과연 올바르냐 이거죠.
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 그것에 대해서는, 저도 그 부분에 대해서는 상당히 저희 부서에서 논란이 됐습니다마는 황해경제자유구역에 지금 남아 있는 게 100만 평 정도입니다. 그리고 지금 이걸 합쳤을 때 한 300만 평 정도인데요. 경제자유구역이 어느 정도 되려면 한 300만 평은 돼야 되지 않겠나 해서 같이…….
</p>
<p><b>○ 김현삼 위원 </b> 경제자유구역이라고 하는 것은 본 위원이 이해하기로 이를테면 각종 혜택을 주는 거죠. 그리고 국내에서 경제활동을 하는 데 있어서 많은 예외조치들이 따르는 거고. 그런 특별한 어떤 혜택을 주는 건데 저는 경제자유구역이 이를테면 이렇게 무차별적으로 지정되는 것, 저는 이건 우리 국가경제의 장래를 위해서 별로 바람직하지 않다라고 하는 개인적인 소신을 좀 갖고 있습니다. 이를테면 노동권이 제약되고 환경권이 제약되고 이런 과거의 경제자유구역 관련해 가지고 많은 논쟁이 있었습니다마는 그걸 차치하고라도 경제활동 예외조치, 각종 혜택들을 지원받으면서 특별한 지역에서 기업활동을 하는 것들이 장기적으로 이를테면 과연 경쟁력을 가질 수 있을 거냐. 저는 아주 그야말로 특별한 예외가 아니면 경제자유구역은 가급적이면 지정되는 게 별로 바람직스럽지 않다, 이런 개인적인 소신을 갖고 있습니다마는 우리 박사님한테 저의 그런 소신에 대한 그 의견을 물어보자고 하는 건 아니고요. 어쨌든 이 앞뒤가 맞지 않는 경제자유구역 관련 정책을 도가 추진하고 있는데 그것에 대해서 이론적 근거를 경기개발연구원이 서포트하는 것은 뭔가 이게 잘못돼도 한참 잘못된 것 아니냐라는 생각을 갖는 거죠.
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 제가 딱 한 말씀드리면 우선 사업성이 확보되고 사업주체가 있는 그런 가장 거의 400만 평 정도만 되는 그것만 사업이 추진되어야 한다는 그런 말씀을 드리고 나머지 부분은…….
</p>
<p><b>○ 김현삼 위원 </b> 아니, 지금 보자고요. 예를 들면 해양복합산업단지 같은 경우에도 제가 얼마 전에 화성시장을 만나봤는데 이게 저희 경기도가 주장해서 경기도시개발공사가 개발한 것 맞죠? 택지개발한 것 맞죠?
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 그런데 지금 이게 그 비용이 경기도가 주장을 해서 해놓고 경기도는 35%를 부담하고 화성시가 65%를 부담한다는 거예요. 그로 인해서 화성시가 엄청난 재정적 압박을 받고 있다라고 화성시장께서 저한테 말씀을 하시더라구요. 이를테면 지역적 상황을 전혀 고려하지 않은 상태에서 경기도가 그야말로 뉴타운지구 지정하듯이 지역주민들 의견수렴하지 않고 지구 지정하듯이 경제자유구역 이렇게 지정하는 게 과연 올바른 정책이냐. 저는 그래서 경기경제자유구역 지정 추진정책에 대해서 우리 경기개발연구원이 해당지역 지자체의 의견들까지를 충분히 좀 들어서 다시 한 번 재검토를 해봤으면 좋겠다라는 의견을 드리기 위해서 부장님한테 말씀드린 겁니다.
</p>
<p><b>○ 경제사회연구부장 김군수 </b> 네, 지금 말씀 잘 듣고 저희 내부에서 다시 한 번 생각해 보겠습니다.
</p>
<p><b>○ 김현삼 위원 </b> 고생하셨습니다. 들어가 주시기 바랍니다. 마지막으로 하나만 더요.
</p>
<p><b>○ 위원장 강득구 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 경기개발연구원, 우리 원장님이요. 경기개발연구원의 영어명칭이 어떻게 되죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네?
</p>
<p><b>○ 김현삼 위원 </b> 경기개발연구원의 영어명칭.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> GRI입니다.
</p>
<p><b>○ 김현삼 위원 </b> GRI인데 Gyeonggi…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> Research Institute입니다.
</p>
<p><b>○ 김현삼 위원 </b> 그렇죠. Gyeonggi Research Institute입니다. Research라고 하는 건 여러 가지 단어로 해석될 수도 있던데 이를테면 본 위원이 작년에도 전임 원장님한테 그런 의견제시를 한 번 했던 적이 있었어요. 이 개발이라고 하는 표현이 이를테면 90년대 중반 이후 우리 한국사회에서 받아들여지는 어감이 이게 좀 별로 좋지 않다. 이를테면 지속가능발전이라고 하는 개념이 폭넓게 사용되어지는 현재 시점에서, 이를테면 Sustainable Development죠. 지속가능발전이라고 하는 개념이 폭넓게 채택돼서 민관영역 어디를 구분하지 않고 다 그렇게 지금 일반적으로 쓰여지고 있는 거죠. 그런 차원에서 이 개발이라고 하는 표현이 과연 지금 이 시대를 제대로 반영하는 용어냐, 제가 이런 주장을 했던 적이 있었는데 우리 원장님 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 동감입니다. 개발이라는 말 자체가 이게 60년, 70년대식 냄새가 물씬 나고 그래서 저는 예를 들어서 개인적으로는 경기발전연구원이라든지 또는 다른 좋은 말이 있으면 이렇게, 아니면 뭐 그냥 경기연구원이라든지 이런, 아니면 경기지속가능 뭐 하여간 다양한 소위 말하는 21세기에 맞게 했으면 좋겠는데 그런데 이름 바꾸는 일이 이게 쉬운 일이 아니더라구요. 한번 이렇게 정해 놓으면 굉장히 여러, 하여간 쉬운 일이 아니어 가지고…….
</p>
<p><b>○ 김현삼 위원 </b> 네, 잘 알겠습니다. 그러니까 이제 명칭을 바꾸는 데서 오는 실무적인 어려움은 있다 하더라도 그러나 기본적으로 제가 말씀드린 명칭을 변경하는 것과 관련된 저의 의견에 대해서는 기본적으로 동의를 하신다 이거죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 100% 동감입니다. 개발이란 말 자체도 뭐…….
</p>
<p><b>○ 김현삼 위원 </b> 이를테면 경기발전 또는 경기도정 또는 경기지속가능발전연구센터, 연구원 이렇게 할 수도 있을 것 같습니다.
</p>
<p style="padding-left:1.2em">  그러면 제가 한 가지 제안을 드리도록 하겠습니다. 어떤 정책을 수립하거나 또는 그 정책을 뒷받침하기 위한 조례를 제ㆍ개정할 때는 당연하게도 실무적인 뒷받침, 이를테면 예산수반 이런 것들이 같이 검토가 돼야 되겠습니다마는 이 명칭의 변경과 관련돼서 향후에 저희 의회하고 우리 원장님을 중심으로 한 우리 연구원하고 폭넓은 의사소통을 통해서 합리적인 그리고 시대의 어떤 이념을 적절히 담아내는 그런 명칭변경에 대해서 상호 토론을 계속해서 합의를 만들어 나갔으면 좋겠어요. 어떻습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 좋습니다.
</p>
<p><b>○ 김현삼 위원 </b> 네, 고맙습니다. 이상 마치겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 다음 박승원 위원님.
</p>
<p><b>○ 박승원 위원 </b> 원장님, 최근에 서울시의 박원순 시장이 당선되고 나서 제가 들은 얘기입니다마는 서울시청 공무원들이 앞다퉈서 무상급식의 필요성을 막 이렇게 문건을 만들어서 드린다고 그래요. 그전에 오세훈 시장님 계실 때는 무상급식에 대한 반대이론을 막 만들어서 드리고. 이런 현상들에 대해서 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 사실 공무원 입장에서는 이해가 가는 측면이 있거든요. 일단 시장의 시정을 서포트하는 게 공무원들이고 그런데 시장이 다른 철학을 갖고 왔으면 거기에 또, 물론 공무원들은 혼이 없다라는 얘기도 하지만 또 역설적으로 다른 식으로 얘기해 보면 당연히 새 시장이 오면 새 시장의 방침에 맞춰서 공무원도 일을 해야 되는 건 당연하다고 생각을 합니다. 거기에 또 새 시장이 왔는데도 갑자기 또 아니라고 말이죠, 그런다든지 그러면 결국 피해는 시민이나 국민들이 보기 때문에 새 시장이 오면 새 시장에 맞는 시정, 그런 생각을 해야 되는 것은 당연하다고 봅니다.
</p>
<p><b>○ 박승원 위원 </b> 문제는 오버하는 게 문제죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 오버하는 거죠.
</p>
<p><b>○ 박승원 위원 </b> 그죠. 오버하는 게 문제고. 그런데 최근에 김문수 지사가 또 오버하는 모습을 보여줬는데 지난주 금요일 날 우리 기획위원회 행정사무감사 처음 시작하는데 그날 북부청인가 공무원들을 대상으로 해서 노사문화대상 시상식하고 나서 인사말을 하는데 FTA 문제를 말씀하시면서 갑자기 이것은 반미운동이다라고 규정을 했어요. 반미운동이라고 규정하면서 이 바이러스는 어디서 왔느냐, 그것은 북한 김정일한테 왔다, 이렇게 뜬금없는 주장을 했습니다. 혹시 이것에 대해서는 어떻게 생각하십니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 그 말을 제가 직접 안 들어 가지고 그 판단할 그런 입장이 아니고요. 이게 정치적 발언이기 때문에, 제가 여기서 또 얘기하면 정치적 해석이 가능하기 때문에 그것은 좀 제가 개인적으로 말씀을 드리겠습니다.
</p>
<p><b>○ 박승원 위원 </b> 마찬가지로 김문수 지사가 오버를 하신 거죠? 지나치게 오버를 하신 거죠. 오늘 아침에 중앙일보 아까 쉬는 시간에 제가 잠깐 봤더니 중앙일보 톱 1면에 민변의 어느 교수가 트위터를 올렸는지 어디에 올렸는지 FTA는 식민지를 새로 규정하는 그런 것이다라고 하는 것을 1면 탑으로 해서 딱 이렇게 다뤘더라고요. 그래서 이건 반미운동이고 뭐 이런 식으로. 그런데 김문수 지사도 똑같이 도용하고, 제가 그걸 보면서 무슨 생각이 들었냐면 그런 것들이 소위 말해서 보수언론에서 자꾸 다룸으로써 FTA 촛불시위를 더 촉발시키는 거거든요. 그러니까 이렇게 정말 뭔가 김문수 지사가 대권을 염두에 두시고 자꾸 오버하는 발언을 하다 보니까 공직사회도 더 오버하는 게 아닌가라는 생각이 드는 겁니다. 그런 과정 속에서 그럼 개발원은 정책적 연구과제나 이런 부분들을 어떻게 고민할 것인가에 대해서도 심도 있게 고민해 봐야 되지 않겠어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 박승원 위원 </b> 오늘 전반적으로 행감에서 다룬 문제들에 대한 핵심적인 내용이라고 저는 생각이 좀 들고요. 아주 중요한 시기이고 항간에는, 김문수 지사가 내년 4월에 사임한다는 설도 항간에 떠돌고 있습니다. 그 과정상에 개발원이 오버하지 않았으면 좋겠다는 말씀드리고요.
</p>
<p style="padding-left:1.2em">  간단하게 몇 가지만 질문하겠습니다. 작년에도 행감 때 많이 얘기가 나왔던 건데 지금 개발원에서 진행하고 있는 여러 가지 정책연구과제 관련해서 이것이 어떻게 정책적으로 실현되고 있는지 그 피드백 하는 작업들이 지금 어떻게 진행되고 있습니까, 구체적으로?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아까 저희가 낸 보고서들이 어떻게 법이 고쳐지면 법이 고쳐지는 대로 또 공무원들이 수행하면 수행하는 대로 저희들이 목록을 쭉 만들어 가지고 옆에다 지금 해놓고 있고요. 사실 저희들이 제일 큰 보람은 저희들이 보고서를 탁 내면 그게 딱 실현이 돼 가지고 세상이 변하는 거죠, 바람직하게. 그런데 어떤 것은 또 보고서를 냈는데 별로 이렇게 반응이 없을 경우도 있고. 그래서 저희들은 항상 보고서를 내면서 그것이 어떻게 되는가를 항상 주의해서 보고 있고요. 그리고 계속 공무원들한테 피드백을 주고 저희가 또 의원님들한테도, 저희가 그렇게 의원님들이 썩 만족을 못하시지만 제가 취임하고 난 다음에 의원님들 계속 지금 보고서를 보내드리라는 거거든요. 그래야지 의원님들이 그것을 봐야지 뭐가 있는 줄 알고 우리가 서포트를 하지 아무것도 없이 그냥 도와달라는 게 얘기가 안 된다. 그래서 저희들은 될 수 있으면 의정에서 저희 보고서를 보고 저희를 도와줄 수 있도록 계속 앞으로도 더욱더 저희들 보고서라든지 정책제안이라든지 아니면 가서 이야기라든지, 직접 가서 그런 노력을 계속 하려고 지금 그렇게 하고 있습니다. 그래서 좀 지켜봐 주십시오.
</p>
<p><b>○ 박승원 위원 </b> 그것을 정량화해서 실제로 예산이 수반돼서 집행되어진 사업들은 어떤 것들이고 또 긍정적인, 부정적인 효과는 어떻게 나왔다 이런 부분까지 좀 세세하게 연차적으로 정리를 해놓으면 나중에 훨씬 이게 효과가 있을 거라고 보고요. 사장되어지는 것들이 워낙 많기 때문에 그런 것에 대한 명확한 근거들을 만들어 놓을 수 있는 시스템을 만들었으면 좋겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 아주 좋은 말씀이십니다.
</p>
<p><b>○ 박승원 위원 </b> 그다음에 외국출장 가시잖아요, 연수. 자료수집하러 가시는데 다녀오셔서 주로 보고회를 어떤 형식으로 지금 진행을 하고 있습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 아까도 그 얘기가 나왔는데 제가 취임하고 난 다음에 해외출장을 되게 엄격하게 합니다. 엄격한데 이번에는 4건밖에 안 되는데요. 사실 와서 1년 동안에. 그래서 저는 기본적으로 국내에서 할 수 있는 일, 요즘에 인터넷이라든지 굉장히 정보 활성화가 잘돼 가지고 꼭 가야만 하는 걸 가도록 했는데…….
</p>
<p><b>○ 박승원 위원 </b> 아니, 다녀와서.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇게 해 가지고 이제 다녀오면 출장보고서를 써서 때로는, 저희 월요회의를 하거든요. 월요회의 할 때 사람들 앞에서 다 내가 이번에는, 왜냐하면 해외경험이라는 것도 같이 셰어해야 되니까, 이번에 가 가지고 해외가 어떻게, 그것을 단순하게 연구뿐만 아니고 분위기라든지 이런 것 때문에 외국 나가는 건데. 그래서 그걸 직접 연구원들하고도 같이 공유하고 또 거기에 대한 내용을 이야기하고 그러면서 저희들이 그것을…….
</p>
<p><b>○ 박승원 위원 </b> 발표회를 꼭 합니까?
</p>
