<p><b>○ 경기개발연구원장 홍순영 </b> 수원활주로 문제에 대해 가지고는 저보다는 통일동북아센터장께서 답변하는 게…….
</p>
<p><b>○ 박용진 위원 </b> 네.
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 통일ㆍ동북아연구센터장 김동성입니다. 이 자리에는 사실 이 연구 책임을 맡으셨던 민군정책팀장님하고 또 관련 초빙연구원들이 다 와계십니다. 그래서 제가 답변하는 것보다는 민군정책팀장님이 답변하시는 게 더 정확할 것 같은 생각이 듭니다.
</p>
<p><b>○ 박용진 위원 </b> 네, 좋습니다.
</p>
<p><b>○ 민군정책팀장 오관치 </b> 민군정책팀장 오관치입니다.
</p>
<p><b>○ 박용진 위원 </b> 제가 오전에 자료요청을 해 가지고 지금 받은 자료를 보니까 저희는 처음에 비상활주로 이전과 관련해서 경기도와 화성시 이렇게 시작이 된 줄 알았는데 보니까 이게 2010년도 4월 달에 업무보고 시 우리 김문수 지사님이 직접 민군정책팀에게 지시를 해서 이게 시작이 된 걸로 이렇게 나오네요. 맞습니까?
</p>
<p><b>○ 민군정책팀장 오관치 </b> 저희들이 군의 입장과 우리 도의 입장을 보고서 비상활주로를 다른 방법으로 어쨌든 없애는 게 좋겠다고 저희들이 검토를 먼저 했습니다. 그런 다음에 공군을 접촉했죠.
</p>
<p><b>○ 박용진 위원 </b> 아니, 그러니까 그 시작이 김문수 지사님이 지시를 해서 시작을 한 겁니까?
</p>
<p><b>○ 민군정책팀장 오관치 </b> 그것이 아닙니다. 저희들이 먼저 자발적으로 그런 문제를 파악했던 것입니다. 그런 다음에 어느 정도 저희들이 확신이 선 다음에 업무보고에서 보고를 드렸습니다.
</p>
<p><b>○ 박용진 위원 </b> 어쨌든 김문수 지사님이 직접 지시한 건 맞죠? 검토를 하라고 지시한 건 맞죠?
</p>
<p><b>○ 민군정책팀장 오관치 </b> 저희들이 그런 건의를 드렸을 적에 결심을 그렇게 하셨습니다. 그리고 업무지시를 하셨습니다.
</p>
<p><b>○ 박용진 위원 </b> 네. 어쨌든 2010년 4월 달에 김문수 지사님이 직접 민군정책팀에게 검토방안의 지시를 내린 게 맞고요. 그리고 여기 지금 보고서에 보니까 사실 현재 있는 비상활주로가 어차피 제 기능을 발휘 못하는 그런 상황이네요. 여기 보니까 어차피 여기가 사람들이 많이 밀집해 있는 인구밀집지역에다가 그다음에 비상활주로와 유도로가 연결된 그쪽에 보니까 경부선 및 1호선 전철 선로가 설치돼 있어 가지고 하루에 600번 이상의 열차 및 전철이 왔다 갔다 하고요. 그래서 “전시에 전투기가 출동을 하면 열차와 추돌이 예상되고 그다음에 대형 항공기의 경우는 수직안전판이 전철 상부의 전기선과 접촉될 수 있는 등 안전상 저해요인이 항상 상존한다. 이와 같은 여건을 고려할 때 전시 예비기지로서의 기능발휘가 제한적일 수밖에 없다.” 이게 검토내용이거든요. 그러면 애당초 여기는 비상활주로의 기능을 못하는 그런 비상활주로죠?
</p>
<p><b>○ 민군정책팀장 오관치 </b> 애당초 비상활주로를 설치했을 때의 그 말씀이신가요?
</p>
<p><b>○ 박용진 위원 </b> 그러니까 현재 상황에서 이 비상활주로가 제 기능을 할 수 없는 무용지물 아닙니까?
</p>
<p><b>○ 민군정책팀장 오관치 </b> 그렇게는 저희 판단으로는, 물론 제한은 됩니다. 그러나 전시가 되면 1번 도로를 차단하고 교통통제를 하면 비상활주로로서는 역할을 하죠.
</p>
<p><b>○ 박용진 위원 </b> 그런데 여기도 마찬가지 “교통에 대한 입출입 및 교통량이 너무 과다하고 그다음에 비상활주로 통제 시에는 교통이 마비가 돼서 예비기지로서는 발휘가 안 된다.” 이렇게 지금 보고서에 나왔거든요. 보고서 내용 그대로 제가 읽은 겁니다. 
</p>
<p><b>○ 민군정책팀장 오관치 </b> 네, 내용이 조금 그렇게도 지금 위원님이 해석하신 것처럼 볼 수 있는데 좀 과도하게 표현이 된 것 같습니다. 저희 실무자의 보고인데요. 저희들이 걱정하는 것은 국도1호선이 그와 같이 교통량이 많을 텐데 그것이 차단되었을 때 국민경제에 여러 가지 영향을 미치는데, 그래서 장단점이 다 있기 때문에 비상활주로 역할이 수원기지 내로 옮겨졌을 적에 좀 줄어드는 것은 사실입니다. 같은 피폭대상이 되기 때문에. 그럼에도 불구하고 저희들은 2개보다는 1개가 더 있으면 그래도 전시에 3개 중의 하나가 파괴되더라도 활용할 수 있다고 본 것이 현재를 그대로 두고 교통을 차단하면서까지 활용하는 것보다는 낫다고 저희들은 봤습니다. 그래서 건의한 것입니다.
</p>
<p><b>○ 박용진 위원 </b> 그러니까 제가 볼 때는 어차피 지금 현재 비상활주로는 여기 검토보고서에 나왔다시피 거의 무용지물인데 공군 입장에서는 하나가 더 있었으면 좋은 그런 상황이고 그래서 굳이 이것을 저희가 저희 비용을 대가면서 설치할 이유가 없는데 공군 측의 어떤 요구만 다 수용한 게 아닌가 그런 생각이 들거든요. 애당초 비상활주로가 공군이 봤을 때는 전시에 이걸 사용하지 못한다는 것을, 그렇게 판단할 수 있는 그런 상황이었고. 또 하나 방금 말씀하셨지만 사실 전시에, 우리 속담에 “계란을 한 바구니에 담지 말라.”는 말도 있지만 어차피 피폭이 되는데 그 안에 비상활주로가 들어간들 그게 무슨 비상활주로가 되겠습니다. 똑같이 피폭되면 다 똑같은 거죠. 괜히 예산낭비만 한 것 아닙니까?
</p>
<p><b>○ 민군정책팀장 오관치 </b> 위원님 지적하시는 것을 저희들이 전적으로 부정하는 것은 아닙니다. 그런데 조금 전에 말씀드린 바와 같이 전시에 1호 도로를 차단하면 비상활주로로써 활용이 가능합니다. 그다음에 수원기지로 이전함으로써 같은 피폭위험이 있지 않느냐, 그런데 활주로를 못 쓰게 하는 방법은 여러 가지가 있는데요. 우리 비행기가 파손이 돼 가지고 착륙할 수가 있습니다. 그러면 그것을 제거할 때까지는 상당기간 동안 활주로는 그대로 있지만 파괴된 비행기가 내려앉음으로 해서 활주로를 못 써요. 그러니까 하나가 더 있으면 꼭 그런 경우에도 여유가 있지 않겠습니까? 그러니까 비상활주로 역할은 어느 정도 합니다, 함께 있어도. 피폭이 되면 그것도 특히 화학탄 공격을 받았을 때는, 저희들이 제일 걱정하는 건데, 문제가 생길 수가 있어요. 그러면 또 어떤 문제가 있냐면 밖에 비상활주로가 있으면 화학제독장비를 그쪽으로 보내서 제거해야 돼요. 그런데 같은 데 있으면 보다 빠른 시간 내에 제거가 가능하거든요, 같은 장비 가지고. 그러니까 이게 상당히 복잡한 계산인데 저희들은 조금 전에 말씀드린 바와 같이 결론적으로 이전을 하는 것이 작전의 융통성도 있고 또 국민경제에도 도움이 되고 그렇게 판단하는 것입니다. 
</p>
<p><b>○ 박용진 위원 </b> 우리 팀장님께서 그렇게 말씀하셨지만 제가 볼 때는 이전이라기보다는 그냥 하나를 더 설치해 준 것밖에 아닌 것 같아요. 어차피 지금 있는 비상활주로가 거의 역할을 못하는 상황에서 그냥 공군의 요구대로, 여기에도 나왔지만 비용을 경기도가 부담한다면 수용하겠다, 이 공군의 입장. 결국 그냥 공군 비행장 안에 활주로만 하나 더 가설해 주는 게 아닌가 그런 생각이 들거든요. 
</p>
<p><b>○ 민군정책팀장 오관치 </b> 지금 위원님께서 보신 바와 같이 또 저희들도 그렇게 판단을 한 것인데 1번 국도를 차단하면 비상활주로로써 사용이 가능합니다. 
</p>
<p><b>○ 박용진 위원 </b> 네, 알겠습니다. 어쨌든 아직 다 의문은 풀리지는 않지만 아마 이 문제에 대해서는 저희 의원들뿐만 아니라 지난번에 언론이나 이런 데에서도 굉장히 의문을 많이 제시했던 그런 사항이고 굳이 이게 이전이란 단어를 써가면서까지 비행장 안으로 갖고 들어가는 게 과연 실효성이 있는가, 어차피 전시에는 똑같이 폭격을 맞아 가지고 활용을 못할 게 뻔한데. 그런 상황에서 우리가 200억이란 예산을 들여서 하는 게 이게 맞는 정책인지 아직 저도 혼란스럽습니다.
</p>
<p style="padding-left:1.2em">  일단 이 정도만 하고요. 간단하게 하나만 더 여쭤보겠습니다. 제가 행감요구자료에  경기개발연구원의 지방분권 관련 연구를 요약해 달라고 요청을 드렸습니다. 2007년부터 2011년까지 총 5건의 연구가 있는데요. 그간에 우리 언론지상에서 보면 김문수 지사님께서는 굉장히 지방분권에 대해서 반대적인 그런 입장을 계속 피력하고 계시는 것 같아요. 원장님 알고 계십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 거꾸로 생각하는데 우리나라의, 본인이 항상 뭐라고 주장하냐면 “선거는 있고 자치는 없다.”라고 그래 가지고 굉장히 화를 많이 내는 그런 경우를 제가 여러 번 많이 봤거든요. 그래서 분권을 예를 들어서 지역에 대한 어떤 개발권한이라든지 여러 가지 것을 줘야 된다고 계속 역설하는 것을 제가 몇 번 봤기 때문에, 글쎄, 모르겠습니다. 그것이 분권을 싫어하는 건지 좋아하는 건지는 모르겠습니다만 일단 지역에 있어서의 수단이 없다라는 것에 대한 불만 내지는 거기에 대한 비판은 여러 번 하는 걸 제가 본 적이 있습니다.
</p>
<p><b>○ 박용진 위원 </b> 어쨌든 지자체장으로서 당연히 그런 말씀을 할 수가 있죠. 균형발전하고 분권은 어떤 관계가 있다고 보십니까? 지역균형발전하고 분권.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 같은 거라고 보죠. 
</p>
<p><b>○ 박용진 위원 </b> 같은 거라고 보세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 그런데 김문수 지사 생각은 전혀 틀리거든요. 김문수 지사가 했던 발언내용을 보면 지방분권에 대해서 이런 말까지 하셨어요. “대통령, 감사원, 검찰, 국세청, 국정원 등 중앙정부가 칼자루 다 쥐고 있으면서 어떤 부패권력을 도려내면 되지 굳이 지방권력이 필요가 있느냐?” 이런 말씀도 하셨고 그다음에 지역균형발전에 대해서는 좀 더 심하게 말씀하셨네요. “균형발전이란 논리는 하향평준화하자는 논리고 함께 못살자는 논리로써 공산당식 발상이다. 이런 측면에서 볼 때…….” 그다음에 쭉 이야기가 나오는데 어쨌든 균형발전에 대해서 굉장히 거부감을 많이 갖고 계세요, 우리 김문수 지사님은. 공산당식 발상이라고 이렇게 말씀을 하시는데. 그래서 우려가 되는 게 지금 분권에 대해서 GRI 연구도 저도 쭉 이렇게 봤지만, 물론 원문은 제가 안 봤지만, 여하튼 분권을 강력히 주장하는 쪽보다는 그냥 다소 평가하는 정도. 그다음에 현재 우리 지방자치에서 재정분권이라든가 기타 여러 가지 부족한 부분에 대해서 정부에 어떤 지원을 확대하는 그런 요구 정도, 거기에서 더 벗어나지는 않는 것 같아요. 어떻게 말하면 좀 분권에 대해서 소극적인 그런 입장을 견지하고 있다고나 할까요? 원장님 생각은 어떠십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 글쎄요. 연구원이 어떤 입장인지 모르겠는데 저 개인적으로는 제가 취임하고 난 다음에 분권이 지방자치의 핵이다. 그래서 이 분권이야말로 경기도가 발전하는 가장 핵심적인 저거고. 왜냐하면 분권이라는 것은 당연히 권한과 권리를 중앙으로부터 분리 받는 거기 때문에, 그런 생리이기 때문에 제가 소극적이라는 거는 저도 개별보고서를 보면 느낄 수, 모르겠습니다. 그런데 저 개인적으로는 분권이 굉장히 중요하다고 보고 그리고 이 경기도하고 균형발전, 이게 어렵더라고요. 왜냐하면 아까 분권이 균형발전이면 사실은 경기도가 가장 유리합니다. 저는 그래서 우리 경기도 입장에서는 계속 분권을 주장해야 된다고 생각합니다. 왜냐하면 여기에 자원이 있고 인원이 있고 그래서 소위 말하는 수도권, 그렇기 때문에 경기도는 분권을 통하면 가장 유리한데 문제는 그렇지 않은 지역이 사실은 문제입니다. 그래서 지금 현실적으로 분권을 통하면 오히려 지역 간 불균형이 더 심화될 가능성이 상당히 많습니다. 그러면 이 문제를 우리 경기도가 어떻게 해야 되는가를 앞으로 지혜를 짜내야 됩니다. 그래서 저는 개인적으로는 경기도는 분권을 주장해야 되고 경기도야말로 분권을 통해서 잃어버릴 게 별로 없다라는 입장인데 그렇지 않은 지역들 많지 않습니까? 그런 쪽이 우리 경기도하고 이게 소위 이익의 충돌이 생길 가능성이 상당히 많습니다, 이 분권에 대해 가지고. 그런데 이것은 경기도 입장에서는 이 분권이 곧 경기도의 발전, 경기도의 발전이 균형발전이라고 본다면, 서울하고 비교했을 때, 이것이 저는 같이 가는 거기 때문에 분권문제에 대해서는 저는 굉장히, 제가 이쪽으로 와서 여기서 녹을 먹고 있는 그런 입장에서 가장 중요한 과제고 또 이 분권은 경기도가 앞으로 지향해 나가야 할 그러한 것이 아니냐라고 개인적으로 생각하고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 원장님 생각대로 정말 그렇게만 된다면 진짜 제대로 된 지방분권의 어떤 해결의 실마리를 찾을 것 같은데 좀 우려되는 게 우리 지사님하고는 생각이 많이 부딪칠 것 같다는 우려가 생깁니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그러면 제 소신입니다, 지방분권에 대해.
</p>
<p><b>○ 박용진 위원 </b> 지금 한참 진행 중인 지방행정체제개편에 따라 가지고 시군통합이 많이 논의되고 있잖아요. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 사실 이것도 어떻게 보면 지난번에 우리 GRI에서 포럼도 한 번 했지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그렇습니다.
</p>
<p><b>○ 박용진 위원 </b> 이 내용도 제가 봤는데 지금 현재 시군통합을 일종의 소통합주의적인 거라고 표현을 하더라고요. 그래서 조그만 단위의 시군을 합해서 여러 개를 만드는. 그런데 이런 경우에는 아주 대표적으로 분권과 상치되는 그런 측면이 있는 것 같아요. 그리고 김문수 지사님께서는 현재 경기도도 사실 작으니까 더 크게 파이를 키워서 가자 이런 측면인데 지금 이렇게 시군끼리 통합하는 그렇게 가면 결국은 나중에 도의 역할이 없어지고, 그렇죠? 그렇게 되면 어느 정도 도의 입장하고 또 연구의 입장하고 서로 부딪칠 텐데 이럴 때 원장님은 어떻게 방안을 찾으실 계획이십니까? 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 제가 저희 연구원에서 도의 역사적 그런 것을 한번 살펴보자. 왜냐하면 시군통합이라든지 이런 것이, 이런 표현을 해도 될지 모르겠는데 불순한 의도도 있는 게 아니냐, 도를 무력화시키려고 그러는. 그래서 우리가 도라는 것은 고려시대 때부터 또는 그 이전의 시대를 살 때부터 경기도라는 게 있었던 거고. 그래서 이게 단순하게 어떤 행정편의적으로 갈라진 게 아니다, 경기도라는 것이. 이게 역사적으로 결정되어 있는 거기 때문에 이것을 단순하게 어떤 행정편의 또는 경제적인 효율성 관점에서 도를 좌우할 수 있는 게 아니다. 그래서 이것을 단순하게 어떤 성장 차원, 발전 차원이 아니라 역사적 차원에서 한번 도의 배경과 도의 의의를 한번 보자 저는 이런 입장입니다. 그래서 저 개인적으로는 소위 우리나라에 지금 있는 도라는 천년 이상 된 제도 이것은 앞으로 인위적으로 훼손하기가 힘든 그런 거 아니냐, 저는 그렇게 개인적으로 생각하고 있고 어떻게 보면 이거야말로 역사적으로 형성된 지방자치제의 단위 아니겠는가, 이렇게 저는 개인적으로 생각하고 있습니다. 그 틀 안에서 큰 것을 보고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 아무쪼록 마무리하면서 어쨌든 지금 아마도 이 분권의 문제는 굉장히 큰 화두가 앞으로 될 수밖에 없을 것 같습니다. 또한 국토의 균형발전, 지역 균형발전을 위해서도 같이 분권이란 개념이 맞물려가야 되는데 그 과정에서 원장님이 소신을 잃지 마시고, 김문수 지사의 생각이 물론 다른 쪽에 있을 수 있겠지만 우리 연구원의 어떤 소신을 가지고 제대로 조언을 해주실 수 있도록 그렇게 부탁을 드리고요. 그리고 향후에도 지금 연구들이 물론 제가 아까 다 원문을 안 읽어봤지만 분권을 정말 그렇게 중요하게 판단하신다면 적극적인 분권에 대해서 어떤 강한 주문을 할 수 있는 연구들을 더 많이 좀 내주시고요. 지금처럼 현 상황에서 이게이게 부족하니까 이거 늘려야 된다, 이런 좀 방어적인 그런 연구보다는 적극적으로 분권을 유도할 수 있는 그런 연구들도 많이 좀 진행해 주시기를 부탁드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 경기도뿐만 아니라 중앙에다가 적극적으로 그 의견을 개진해서 분권을 가져올 수 있는 그런 여러 가지 연구들을 하도록 하겠습니다. 
</p>
<p><b>○ 박용진 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 강득구 </b> 한 바퀴…….
</p>
<p><b>○ 임병택 위원 </b> 자료요구 하나 하겠습니다. 좌승희 이사장님 관용차 운행일지가 있을 겁니다. 경기개발연구원 관용차 운영규정과 함께 이사장님의 관용차 운행일지, 그것은 용도, 목적지, 거리, 유류비 모든 부분이 포함된 공적인 문서거든요. 그걸 내일모레까지 의회에 전달을 좀 해주십시오.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 알겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 직제 및 직원 정관에 보면 제26조에 “연구원의 모든 직원은 원장이 임명하고 부원장 및 사무처장의 임기는 2년으로 하되 연임할 수  있다.”라고 나와 있고 그다음에 두 번째 조항에 “직원의 임면, 승진, 보수, 복무기준 등 필요한 사항은 따로 규정으로 정한다.”라고 나와 있습니다. 그러면 이사장 예우에 관한 부분들, 보수에 관련된 부분 포함해서 이게 규정에 나와 있어야 돼요. 그런데 보니까 2006년 12월 29일 날 전문개정한 걸로 나와 있습니다. 다시 말하면 2010년도 이후에는 개정안이 없다라는 겁니다. 그러면 분명히 규정집이 있잖아요. 그죠? 정관이 있고. 정관과 규정에 의거해서 다 가는 거거든요. 그런데 정관에 없고 규정에 없는데 했다라는 건 원장이나 김문수 지사가 자의적으로 이사장에 대해서 관용차량과 업무추진비 그리고 약간의 활동비를, 넓은 의미에서 업무추진비도 그런 거지만, 그랬다라는 건 이건 아주 큰 겁니다. 그리고 제가 여기 수신자 경기도에서 온 자료를 보면 “정관 제14조, 제17조의 규정에 의거하여 경기개발연구원 제65차 임시이사회 시 의결된 선임직 이사를 아래와 같이 임명하였음을 알려드립니다.” 제14조, 제17조 규정에 의거. 그런데 이 절차를 안 거쳤어요. 그러면 절차도 안 거쳤으니까 하자도 있고 규정에도 없고 이것을 우리 원장께서는 당당하게 좌승희 원장이 여태까지 한 공로 그리고 브랜드파워가 있기 때문에, 경기개발연구원의 명성을 높일 수 있기 때문에, 이런 식으로 이야기하는 거는 저는 도저히 납득이 안 갑니다. 이 부분에 대해서 마지막 날 종합사무감사할 때 지금 한 말에 대해서는 분명히 책임을 져야 됩니다. 그래서 이 부분에 대해서 다시 한 번 분명히 짚고 얘기를 할 테니까 이 규정 다시 한 번 찾아보고요. 그리고 말씀하신 모든 부분들 다 가져와서 마지막 날 얘기를 하기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그리고 아까 김은경 센터장 잠깐 나오십시오.
</p>
<p><b>○ 정책센터장 김은경 </b> 정책센터장 김은경입니다.
</p>
<p><b>○ 위원장 강득구 </b> 홍 원장께서 취임하신 다음에 정책센터가 필요하다고 이야기하셨죠, 원장님이?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 저는 동의했습니다. 왜냐하면 어쨌거나 도정현안을 신속하게 적시에 대응하는 게 저는 김문수 지사 개인이 아니고 도지사 김문수 그리고 또 경기도입장에서 필요하다고 생각했기 때문에 동의했습니다. 그리고 임 지사 때도 수도권정책센터가 있었습니다. 그래 가지고 임 지사 같은 경우는 외자유치, 수도권 규제완화 이런 부분들에 대해서 제일 고민을 많이 했기 때문에 그에 대한 부분들을 수도권정책센터가 일정 정도 역할을 했습니다. 손학규 지사 때도 정책개발센터가 있었습니다. 그렇지만 손학규 지사도 이 GRI에 대해서 상당히 요구하는 자료 그리고 또 그레이드 이런 부분에 대해서 좀 마지막에는 부정적으로 얘기했던 것 같습니다. 그럼에도 불구하고 저는 정책센터가 필요하다고 생각했습니다. 현안대응이라는 게 어쨌거나 적시에 해야 되고 가만히 두면 잘 안 돌아가고 그럴 수 있기 때문에 필요하다고 하는 부분은 인정합니다. 문제는 이겁니다. 김은경 센터장께서 당당하게 자신 있게 얘기하는데 반값등록금 정책, 예를 들면 “한나라당 반값등록금 정책에 대한 평가”, “0세-4세 무상교육 검토 의견” “대기업 MRO 사업철수와 압박에 대한 평가” 이런 것들이 도지사 김문수 입장에서 필요한 건지 아니면 잠재적 대권주자 김문수 입장에서 필요한 건지. 이게 그렇습니다. 국가사무도 중장기적으로 필요한 부분이 있고 단기적으로 필요한 부분이 있고 우리 경기도와 연계된 부분이 있어요. 고민하면서 국가 사무, 국가라는 부분을 지웠던 것은 이런 부분들, 아니 정책현안에 대해서 대응하지 말라라는 것이 아니에요. 이런 것을 당당하게 얘기하는 센터장 양식이 저는 의심스럽습니다. 나는 우리 연구원분들의 자율성과 창의성을 최대한 존중해야 된다고 생각해요. 그렇지만 최소한 경기개발연구원은 경기도에서 100% 출연한 기관 아닙니까? 그런 부분 속에서 고민하다가 우리가 국가라는 부분들을 뺀 것 아닙니까? 그러면 거기에 맞게 좀 고민들을 해야죠. 그리고 다시 한 번 마지막 날 얘기하겠지만 이 부분에 대해서 당당하게 얘기하는데 그날도 당당하게 얘기해 보십시오. 그래서 같이 한 번 토론을 통해서 얘기하겠습니다. 그런데 어쨌거나 그렇고, 들어가십시오.
</p>
<p><b>○ 정책센터장 김은경 </b> 들어가겠습니다. 
