<p><b>○ 경기개발연구원장 홍순영 </b> 100점 만점으로 보면 그렇습니다. 그런데 지난번 같은 평가는 주로 양 위주로 되어 있어 가지고요. 점수로 해 가지고 본인들의 질에 관계없이 양을 채우면 잘하는 거로 되어 있더라고요. 그래서 그걸 다 질로 바꾼 겁니다. 그러니까 모든 연구의 질평가를 양하고 같이 겸해서 하는 쪽이 저희 평가제도 바꾼 것의 기본적인 겁니다. 작년까지만 해도 다 점수가 있더라고요. 그래서 그 점수만 채우면 자동적으로 좋은 점수를 받게끔 되어 있는, 그래서 그런 게 상당히 좀 문제가 있다 싶어서 이렇게 바꾼 겁니다. 
