<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 이 평가라는 게 저도 한 20년 해봤는데요. 권 위원님 말씀하신 거 충분히 이해하고요. 그런데 이게 100% 완벽한 제도가 없더라고요. 잘 맞으면 굉장히 좋은 제도고, 잘 맞은 사람들한테는. 또 안 맞으면 그 제도가 어떻더라도 불만의 여지가 되고 그래서 차선을 추구할 수밖에 없는데 그런데 여태까지 평가라는 것이 주로 양 위주로 되어 있어 가지고 이번에 질 위주로 좀 전환을 시키는데 아무래도 질에 대한 평가가 주관적인 평가가 개재될 수가 있어서 그런 의구심이 날 수도 있다고 생각합니다. 
