<p><b>○ 권칠승 위원 </b> 어차피 이것은 인사와 관련된 것이어서 크게 봐서 원장님 전속권한이라고 생각합니다. 그래서 한번 운영해 보시고 그런 부분들이 그냥 옆에서 봤을 때는 좀 우려가 보입니다. 그래서 그런 부분들은 잘 챙겨가면서 운영을 하셨으면 합니다.
