<p><b>○ 권칠승 위원 </b> 그리고 아까 뭐 이런 게 있었습니다. 공짜점심 이야기할 때 김은경 센터장님이 “경제학에 나오는 프리런치다.” 이렇게 말씀을 하셨는데 그 말씀 맞죠. 그런데 좀 교묘한, 영어로 펀(fun)이라고 하죠. 말장난. 그런 게 좀 있다고 봅니다. 왜 그러냐면 이 보고서가 나올 때 이미 레디앙부터 조선일보까지 다 보신다고 하니까 제가 드리는 말씀인데 “공짜점심 한나라당” 이렇게 포털에 치면 수백 건의 기사가 나옵니다. 이미 공짜점심이라는 게 무상급식을 막기 위한 하나의 낙인처럼 사용된 정치공세 용어였습니다, 이미. 그렇게 사용되고, 그것 아니라고 하면 그것은 좀 팩트를 거부하는 거라는 생각이 좀 들고요. 이미 사실상 그렇게 굳어지게 사용이 되어 왔었죠. 그거는 원장님도 알고 계십니까? 
