<p><b>○ 권칠승 위원 </b> 그런데 이런 논문을 쓰고 검토하는 입장에서는 어떻게 이렇게 저널을 검색을 안 하실 수가 없는데 하면 그거는 뭐 기가 막힌 용어를 찾았다고 생각할 겁니다. 과거에 세금폭탄에 거의 버금가는 아주 훌륭한 공세용 용어죠. 그런데 이것을 저는 다분히 의도적으로 썼다고 생각합니다. 그렇지만 내심에 있는 거니까 제가 확인할 길은 없지만. 그리고 또 억울하게 생각하실 수도 있겠지만 그렇게 해석을 해도, 이야기해도 모면할 길이 없습니다, 사실. 이미 그 당시에 굉장히 객관적으로 그런 용도로 변질돼서 사용하고 있는 시기였거든요. 그래서 그런 부분들은 들켰다고 생각하십시오.
</p>
<p style="padding-left:1.2em">  그리고 제가 정리를 하겠습니다. 사실은 이번에 지금 현재 행감에서 이렇게 문제제기하는 부분들이 지사가 바뀐다고 해서 개선될 수 있느냐. 저는 사실 그렇게 쉽지 않다고 생각합니다. 다른 생각을 가진 지사가 와서 다른 내용을 주문하고 하면 사실 따라갈 수밖에 없는 현실적인 문제도 있다고 생각합니다. 그래서 좀 장기적으로, 제가 좀 이상론일 수도 있는데 장기적으로 이런 연구를 하고 아주 원시적인 정책을 만들어내고 평가하는 이런 단체들은 의회로 오는 게 맞다 이런 생각이 좀 듭니다. 그래서 그런 방법도 신원득 박사님이 중심이 돼서 하시든, 국회 보면 예산정책처라든가 입법조사처 이런 게 있지 않습니까? 경기개발연구원은 그런 일을 하는 게 오히려 어떤 위상이나 그런 면에서 훨씬 맞다는 생각이 듭니다. 그리고 또 다른 면에서는 단체장을 정무적으로 보좌하는 어떤 기능도 합법적으로 인정해 주는 것, 이것 저는 반드시 필요하다고 생각합니다. 지금은 못하게 돼 있기 때문에 우리가 해서는 안 된다고 하는 것 아니겠습니까? 그래서 그런 쪽으로 좀 대안을 생각해서 장기적으로, 이게 앞으로 3년, 4년이 걸리더라도 장기적으로 그런 방법이 뭐가 있는지 사실 그런 것들을 찾아야, 정말 훌륭한 분들이 모여 있는 고급집단인데 이런 데 좀 휘둘리지 않고 개인적인 소모적인 논쟁도 안 하고 그렇지 않을까 이런 생각이 듭니다. 오히려 의회 같은 곳에서 정치색깔을 정확하게 드러내고 자신의 사상과 이념을 가지고 정책을 만들고 상대방의 정책을 비판하는 그런, 차라리 드러내놓고 공명정대하게 하는 그런 판이 만들어질 수 있는 그런 연구원의 자리가 있었으면 좋겠다 이런 생각이 듭니다. 원장님 말씀 듣고 정리하겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 좋으신 말씀입니다. 100% 공감합니다.
</p>
