<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 다음 우리 김주삼 위원님.
</p>
<p><b>○ 김주삼 위원 </b> 김주삼 위원입니다. 본의 아니게 계속 정책센터의 문제만 얘기하는 것 같은데 실제는 정책센터의 문제가 아니라 경기개발연구원에서 나온 자료들을 쭉 보다 보니까 하여튼 우연치 않게 좀 문제가 된다고 생각하는 그런 자료들이 주로 정책센터에서 많이 나왔더라고요. 그래서 본의 아니게 이렇게 계속 질문이 정책센터에 집중되는 것 같습니다.
</p>
<p style="padding-left:1.2em">  우리 경기개발연구원 사업에 보면 아까도 말씀을 드렸지만 딱 하나만 제가 물어볼게요. 예를 들어서 ‘무소속 돌풍 평가와 전망’ 그렇게 얘기했는데 이게 우리 사업에 굳이 준용을 한다고 그러면 어느 사업을 수행하는 거라고 생각이 되세요, 우리 원장님께서는?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 솔직하게 말씀드려 가지고요. 무소속 돌풍에 대한 주제선정은 시의적절하지 못했다는 생각이 들고요. 그리고…….
</p>
<p><b>○ 김주삼 위원 </b> 이건 시의적절하지 못한 게 아니라 연구원 사업에 맞지가 않다는 얘기죠, 제 얘기는.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 제가 시의뿐만이 아니고 적절하지 못했다 이런 말씀이고요.
</p>
<p><b>○ 김주삼 위원 </b> 저도 1~6번까지 있는데 도대체 뭐 끼워 맞출 데가 없어요. 차라리 우리 의회에서 지난번에 문제가 됐던 통일연구소 남북문제 같은 경우는 국내 연구기관과의 교류협……. 아니, 도정발전에 관련된 국내외 주요현안연구 뭐 그렇게 얘기할 수도 있겠죠. 예를 들어서 이번에 보니까 또 이런 ‘동일본 대지진의 경제적 파급효과 및 시사점’ 뭐 어거지로 끼워 맞추면 도정발전에 관련되는 국내외 주요현안연구라고 그렇게 맞출 수도 있겠죠. 그런데 저는 경기개발연구원이 자기 본래의 고유사업들을 충실하게 수행하는 과정에서 많은 정치적 어떤 이슈들이나 사회적 이슈, 무소속 돌풍도 하나의 우리 경기도의 어떤 사업을 연구하면서 중요한 변수 중의 하나였다. 그래서 그 부분을 변수로 놓고 이렇게 생각을 한다, 그런 것은 이해가 되지만 현안연구로 이렇게 하는 건 맞지가 않다.
</p>
<p style="padding-left:1.2em">  그래서 제 결론은 정책연구센터를 이걸 없애고 본래의 연구원들을 각각 자기 본래 소속돼 있는 연구사업에 전념할 수 있도록 그렇게 해주셔야 맞다고 그렇게 생각합니다. 정책센터에서 나오는 게 결국은 우리 김문수 지사의, 그러니까 정치적 오해를 받는 자료들이 계속 나오고 그 얘기는 결국 정치적 오해를 지금 받고 있다. 그래서 저는 그 부분에 대해서 강력하게 요청을 합니다. 원장님 생각은 어떻습니까? 계속 정책센터를 이런 식으로 놔두시겠어요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 정책센터에서 저희들이 현안을 해야 된다는 것은 어떤 지사가 와도 해야 되는 것이기 때문에 그래서…….
</p>
<p><b>○ 김주삼 위원 </b> 그 현안이 경기도의 현안이어야 되죠?
