<p><b>○ 경기개발연구원장 홍순영 </b> 제가 좀 말씀을 드리겠습니다. 그래서 앞으로는 운영할 때 정책센터에서 나오는 주제에 대해서는 경기도의 도정하고 연결된 주제로서 한정되도록 제가 챙기겠습니다. 그래서 앞으로는 의원님들한테 쓸데없는 또는 오해라든지, 그런 주제 같은 것을 통해 가지고 오해를 안 사도록 노력을 하겠습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러면 지금까지는 전혀 챙기시지 않으셨다는 얘기예요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 아니요. 제가 또……. 아닙니다. 경기개발연구원에서 모든 자료의 최종적 책임은 저에게 있는 거죠. 그런데 저는 또 한편 여러 가지 주제에 대해 가지고 또 연구원의 자율과 창의성을 존중한다는 차원에서 일일이 그걸 봤고 사후에 평가를 받는 게 있습니다. 그런데 몇 가지, 오늘 위원님들이 지적해 주신 몇 가지 주제들은 제가 나중에, 왜냐하면 우리가 모든 연구를 할 때 나중에 평가를 하는 게 있지 않습니까? 그래서 이건 잘했다 그러면 좋은 평가를 받는 거고 못했다고 그러면 나쁜 평가를 받는 거거든요. 그래서 그런 주제들은 좋은 평가를 받지는 못한 그런 주제들이고, 그렇습니다. 그래서 그게 또 눈에 탁 띄어 가지고 오늘 또 집중적으로 지금 공격 아무튼 그게…….
</p>
<p><b>○ 김주삼 위원 </b> 글쎄요, 그…….
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그래서 저희 많은 연구 중에서 사실은 어떻게 보면 또 그렇게 잘하지 않은 부분들이거든요. 그래서 그 부분에 대해서 저희들이 적극 수용을 하고 그래서 앞으로는…….
</p>
<p><b>○ 김주삼 위원 </b> 아니, 그것은 우리 위원들 입장에서 봐서는 잘하지 않는 거지만 우리 김문수 지사 입장에서 봐서는 굉장히 잘한 것이 될 수도 있습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 그런데 반드시 뭐 그런 것만 아니죠.
