<p><b>○ 김주삼 위원 </b> 그리고, 말씀 다 저기 되셨죠? 지금 문제가 저는 또 하나의 문제인데 정책센터에서 나오는 이런 자료들이 실제 모든 지금 일반적으로, 전문적으로 바라보지 않는 일반 의원들도, 저 같은 경우도 이렇게 보면 훑어봐도 ‘아, 이 부분은 좀 뭔가 있겠다.’ 그래서 이렇게 훑어보는 형태인데 문제는 지금 원장께서도 그러지 않았다는 얘기죠. 정책현안이나 이슈나 이슈＆진단에서 나오는 그런, 이게 실제 많은 페이퍼도 아니고 페이퍼 한두 장짜리고 서너 장짜리의 한 2, 3분, 5분 정도면 그냥 훑어볼 수 있는 내용들이거든요. 그런 건 저는 최소한 사후에라도 훑어보고 정확하게 이런 부분들에 대해서 어떤 문제가 있다. 그래서 이런 것은 사후에라도 좀 고치고 어떤 정책적 균형을 좀 갖게 하고 그래야 되는데 지금까지 그런 절차가 전혀 없었다는 얘기죠.
