<p><b>○ 경기개발연구원장 홍순영 </b> 그것도 사후에는 봤습니다. 그리고 제가 저것도 봤고요. 그 기획회의 같은 것도 제가 주재를 했었고요. 그런데 이제 개별적인 내용들, 그러니까 그게 문장이라든지…….
