<p><b>○ 김주삼 위원 </b> 아니요. 저도요, 이거 세세히 안 읽어봤습니다. 그냥 한번 훑어보고 이거 좀 그렇다, 그래서 눈에 띄는 것 몇 개 이렇게 지금 저기 하면서 하다 보니까 자세히 읽게 되고 그러거든요. 원래 모든 자료는 그렇지 않습니까? 자료가 있으면 일단 제목이 이게 좀 관심이 가는 건지 거기부터 시작을 하는 거죠. 그런데 저는 아주 민감한 거거든요, 정치적으로.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저는 그래서 말씀 중에 죄송합니다마는 이슈＆진단 같은 경우는 앞에 쟁점과 대안 그 요약이 있지 않습니까? 그것을 저는 주로 보거든요. 그래서 봐서 큰 문제가 없다, 저는 생각을 했었고. 그 앞에 쟁점과 대안, 포퓰리즘은 제가 가장, 한 줄만 읽어드리겠습니다. “포퓰리즘은 현재 가장 유행하는 단어이지만 그 의미가 모호하여 학계에서조차 합의된 정의는 없다.” 그러면 뭐 이거 오케이고. “포퓰리즘은 좌우파의 이념문제가 아닌 하나의 정치적 전략으로 득표를 위해 실현가능성과 지속가능성이 없거나 재원조달방안이 없는 정책을 추진하는 행위이다.” 그래서 이 업명에 그렇게 크게 어떤 정치적인 그런 게 없다 싶어 가지고 제가, 가장 중요한 게 쟁점과 대안이거든요. 그래서 이게 반드시 어떤 포퓰리즘이 어느 당의 문제다 이런 걸 지적한 게 없고 일반적인 이야기를 한 것이기 때문에 저는 크게 문제가 없다 이렇게 생각했는데 위원님께서 그 중간에 굉장히 민감한 부분을 저한테 지적해 주셔 가지고 그 부분에 대해서는 오해가 있을 수 있다 이렇게 생각을 하는 겁니다.
</p>
<p><b>○ 김주삼 위원 </b> 그런데요. 저는 이 쟁점과 대안 맨 앞부분을 이렇게 쭉 봐도 이건 어쨌든 상당히 문제가 있습니다. 그러나 정치적 입장에 따라서는 다 틀릴 수가 있죠. 그런데 이건 전형적으로 지금 현재 복지가, 우리 대한민국의 복지정책이 그러니까 우리 야당에서 주장하는 보편적 복지가 문제가 있다는 시각이거든요.
</p>
