<p style="padding-left:1.2em">  그러면서 좀 드리고 싶은 말씀은 저는 경기개발연구원에 소속된 연구원들, 연구자들, 저는 학자적 양심이나 소신은 대단히 중요하다고 생각을 합니다. 그러나 본 위원이 판단하건대 더 중요한 것은 경기도가 출자한 연구기관으로서 이 경기개발연구원이 경기도정의 발전에 직접적으로 도움을 주는 것, 저는 이것이 더 중요하다고 생각을 하고 있거든요. 어떻습니까?
