<p style="padding-left:1.2em">  제가 얼마 전에 경기도 중기지방재정계획심의위원회 제가 위원인데 거기에 참여를 했어요. 향후 5년간 경기도가 진행하는 대규모 투자사업 중심으로 그 중기지방재정계획을 심의하는 그런 자리인데 제가 깜짝 놀랐습니다. 뭐냐 하면 세수부족의 여러 가지 원인을 몇 가지 나열했는데 그중에서 제가 두 번째인가로 기억을 하는데 부자감세라고 하는 항목이 들어 있더라고요. 그러니까 특정한 정당 출신의, 이를테면 도지사가 있는 그런 집행부가, 그 정당에서 그동안 부자감세를 추진하지 않았습니까? 그런데 이 부자감세가 지방세 부족의 상당히 큰 원인으로 작용을 하고 있다라는 인식을 공식 책자에 이렇게 집어넣은 걸 보고 상당히 좀 놀랐어요. 그래서 ‘야, 이게 이를테면 부자감세라고 하는 게 어떤 특정한 정치집단 또는 세력만의 주장이 아니라 이것이 전체적으로 보면 일반화된 개념이고 부자감세에 대한 평가이겠구나!’ 이런 생각을 한번 가져봤던 적이 있었고요. 마찬가지로 급식에 관한 것 역시도 저는 특정한 정치집단세력에서 출발했지만 그것이 결국은 일반화된 그런 개념이다 이렇게 지금 보여지는데 우리 원장님 어떻습니까?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 이게 저는 개인적인 생각으로는 복지라든지 이런 것은 증세를 통해야 됩니다, 사실. 그래서 복지모델이 고복지 고세금이거든요. 그리고 만약에 고복지 저세금으로 가려면 다른 데 지출을 갖다가 복지 쪽으로 돌리고 이런 게 돼야 되기 때문에 그래서 지금 세수가 부족한 그런 것은 어떤 경우든 간에 세금을 적게 거둔 경우는 세수부족으로 연결이 되겠죠. 그래서…….
</p>
<p><b>○ 김현삼 위원 </b> 그렇죠. 그래서 본 위원이 말씀드리고자 하는 것은 그런 겁니다. 어떤 특정한 정책적 사안에 대해서 찬성과 반대 있을 수 있고 논쟁이 있을 수 있습니다마는 그것이 국민적 판단에 의해서 객관성을 획득한다고 저는 생각을 하는 거거든요. 그런 측면에서 이를테면 쟁점이 되고 있는 부자감세랄지 무상급식의 문제가 저는 이미 판명 났다 이렇게 보여지고 있고요. 그런 측면에서 이를테면 경기개발연구원의 의제선정, 그리고 그 선정된 의제에 대한 기술은 대단히 잘못됐다 이런 생각을 갖고 있습니다. 그런 말씀을 좀 드리고요.
</p>
<p style="padding-left:1.2em">  저희가 행정사무감사를 하는 이유는 그렇습니다. 지난 1년간의 사업에 대해서 잘잘못을 따지고 잘한 것을 격려하고 하는 차원을 뛰어넘어서 그런 결과를 갖고 향후에 곧바로 있게 될 예산심의에 저희가 근거자료로 활용하기 위해서 행정사무감사라고 하는 것을 저희가 준비해서 하는데요. 저희가 오늘 많은 시사점을 얻었다고 생각합니다. 지금 아시겠습니다마는 경기도시공사가, 경기도시공사의 부채규모가 경기도의 재정건전성을 압박하고 위협하는 수준까지 지금 와 있어요. 알고 계시죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 그런데 제가 볼 때는 경기도시공사뿐만 아니라 경기도가 출자한 21개 기관들이 전체적으로 보면 방만경영, 부실경영에 지금 있다 이렇게 보여져서 이 행정사무감사의 결과를 토대로 저희가 다양한 대책을, 예산심의에 관한 것뿐만 아니라 다양한 대책을 저희가 지금 강구하고 있다는 말씀을 드리도록 하겠습니다. 하여튼 경기개발연구원이 도가 출자한 연구기관으로서 도정발전에 지속적으로 일익을 담당할 것을 부탁드리면서 그 시대흐름에 역행하지 않는 의제선정과 연구를 해주셨으면 좋겠다는 말씀드리면서 제 말씀 마치도록 하겠습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 알겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 수고하셨습니다. 다음 우리 말씀하실 위원님 안 계십니까? 알겠습니다. 제가, 혹시 우리 원장님 뇌구조그림 보신 적 있습니까? 요새 뇌구조그림. 요즘에 뇌구조그림이라고 해 가지고 인터넷에 나오는 그림 혹시 보신 적 없으신가요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 못 봤습니다. 뇌구조그림 보지 못했습니다.
</p>
<p style="padding-left:2.4em">    (강득구 위원장, 자료를 들어 보이며)
</p>
<p><b>○ 위원장 강득구 </b> 여기 20대가 바라는 새 서울시장의 뇌구조 했는데 제일 크게 그려진 부분이 소통입니다, 소통. 그리고 여기도 보니까 관심, 경청, 세심함, 수용력을 원한다고 하네요. 역시 소통입니다.
</p>
<p style="padding-left:1.2em">  저는 우리 김현삼 위원님이 행정사무감사의 취지, 행정사무감사를 하는 이유에 대해서 얘기를 했지만 동의하면서 동시에 사실 이게 소통하는 자리라고 생각합니다. 우리 위원분들의 시각 또 경기개발연구원의 시각 이런 부분들에 대해서 토론을 통해서 한번 합리적인 접점, 인식을 한번 나눠보자, 공유해 보자 이런 부분도 사실 있는 겁니다. 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 충분히 그걸 이해하고 있습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그런데 여기 보니까 소통 포함해서 경청 몇 가지가 있는데 이 그림의 뇌구조에 보면. 예를 들어 원장님 입장에서 경기개발연구원의 뇌구조를 한번 그림을 그린다면 뭘 집어넣고 싶으세요? 들어갈 키워드가.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 제가 지금 눈이 안 좋아가지고요. 그 그림의 정확한 의미를 파악을 못해 가지고 그러니까…….
</p>
<p><b>○ 위원장 강득구 </b> 예를 들면 경기개발연구원의 뇌구조, 뇌를 경기개발연구원이라고 그러면 그 안에 어떤 키워드를 한번 넣고 싶은지.
