<p><b>○ 위원장 강득구 </b> 그걸 나눠보면 현안대응에 대한 부분도 있고 중장기과제도 있고 뭐 이럴 것 아닙니까, 그죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네. 도정 또 균형 뭐 이런…….
</p>
<p><b>○ 위원장 강득구 </b> 그런데 제가 경기개발연구원 연구실적 자료를 보면서 이게 떠오르는 건 GTX, 뉴타운개발 예를 들면 김문수 지사 이런 부분들이 경기개발연구원 과제의 상당 부분을 점하고 있는 느낌이 드는 겁니다. 그래서 제가 몇 가지 한번 자료를 쳐봤습니다. 예를 들면 중소기업이요, 중소기업. 중소기업 요구한 자료를 갖고 몇 년 동안 중소기업에 관한 단어를 한번 찾아봤어요. 그런데 1995년 설립된 이후로 중소기업, 목록이 1,602건인데 그 목록에서 중소기업 키워드로 검색되는 연구명은 불과 5건이었습니다. 1996년, 2001년, 2004년, 2007년, 2011년. 그리고 2003년부터 축적돼 있는 이슈＆진단 자료 285건 중에서 중소기업 키워드로 검색되는 것은 2011년 올해 단 1건이었습니다. 예를 들면 노인, 다문화 이주여성 이런 키워드도 마찬가지예요. 도정이라고 그러셨죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
