<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 여기서 당당하게 우리, 저는 김은경, 제가 이름도 잘 모르겠습니다. 아무런 관련도 없고 오늘 여기서 얘기하면 다음에 또 볼 이유도 없습니다. 그런데 예를 들면 ‘안철수 무소속 돌풍이유’ 이런 것들을 당당하게 경기개발연구원에서, 경기도에서 100% 출연한 연구기관에서 해야 된다라고 얘기하는 인식을 갖고 있는, 이렇게 당당하게 얘기하는 센터장과 저희들이 얘기하는 중소기업, 노인, 다문화 이주여성, 서민 이런 부분들과 인식의 편차 이런 것들을 오늘 이런 자리를 통해서 소통하고 접점을 찾는 이런 자리가 되기를 진심으로 바랬습니다. 그래서 제가 중소기업이라는 단어를 한번 찾아봤던 건데 이게 중소기업이라는 단어가 제목에 들어가야만, 중소기업 관련 연구 이런 부분은 없고 노인, 다문화 이주여성 이런 부분도 하나도 없어요. 다시 말하면 복지분야 이런 부분도 거의 경시되고 있다라는 거죠. 이건 어쨌거나 김문수 지사의 도정철학, 뭐 공약과도 관계됐지만 그렇지만 이 경기도정의 미래를 생각한다, 아니면 경기도에 살고 있는 대다수의 서민들 입장에서 고민해야 될 어젠다 이런 부분들 속에서 보면 과연 이 안철수 무소속 돌풍현상이라든지 몇 가지 얘기한 부분들 이런 게 맞는 건지 좀 더 경기도 대다수의, 천백만 도민들의 대부분을 차지하고 있는 서민들 입장에서 고민들을 하는 게 맞는 건지, 이런 것에 대한 접점 이런 것들을 저는 좀 찾고 싶었습니다. 우리 원장님께서는 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 저희들도 그 노인문제는 계속 지금 노인자살문제 관련해서 다루고 있고요. 다문화문제라든지, 중소기업은 최근에 사회적기업 이런 쪽에 묻어서 저희들이 연구를 하고 있고요. 또 특히 서비스 발전방안에서 중소기업을 안에 넣어 가지고 저희가 보기 때문에 지금 위원장님께서 말씀하신 노인이라든지 다문화라든지 중소기업이라든지 이런 복지문제를 갖다 저희들이 결코 과소평가한다든지 무시하고 이런 건 아닙니다.
</p>
<p><b>○ 위원장 강득구 </b> 그리고 원장께서 그런 말씀하셨죠. 예를 들면 현안대응에 대한 부분은 전체 사업, 전체 연구비중으로 봤을 때 1/10도 안 된다라고 얘기를 했죠?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 그런데 저는 현안대응 필요하다고 생각하는 사람입니다. 그런데 사실은 제가 보기에는 어쨌거나 홍순영 원장께서 오신 다음에 현안대응에 대한 비중이 상당히 높아졌습니다. 그런데 현안대응과 중장기 마스터플랜 내지는 기본과제들 이것에 대한 균형점 그리고 예를 들면 복지와 개발 이런 것들에 대한 균형점, 이런 것들에 대한 합리적인 접점 속에서 우리 경기개발연구원의 비전과 역할들을 찾는 게 맞다라고 생각합니다. 저는 다시 말하지만 우리 경기도의 발전과 도민의 삶의 질 향상을 위해서는 경기개발연구원의 정책 연구가 어느 한 분야에 치우치는 게 아니고 좀 합리적이고 객관적으로 잘 형평성 있게 배분되어야 된다라고 생각합니다. 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 100% 옳으신 말씀입니다.
</p>
<p><b>○ 위원장 강득구 </b> 그래서 우리 원장님이 오늘 하루를 정리하시면 진짜 경기개발연구원 한번 스스로 뇌구조그림을 그려보시고 어떻게 그림을 그리는 게 맞는 건지, 어떻게 비전을 갖는 게 맞는 건지, 어떤 콘텐츠를 만들어가는 게 맞는 건지 그런 큰 틀에서 고민을 해주시기를 바라고 오늘 여기 계신 연구원분들도 그런 입장에서 같이 고민해 보고 접점을 찾아보자고, 저는 이 자리에 있는 이유가 김현삼 위원님 말씀하신 부분도 있지만 그런 부분도 있다라고 생각합니다. 그래서 마무리를 하면 좀 더 큰 틀에서 경기도민 그리고 경기도정 이런 부분에서 좀 고민해 주시기, 물론 지금도 고민하시지만 합리적인 선, 균형점, 이런 것들을 잘 찾아주길 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 옳으신 말씀입니다.
</p>
<p><b>○ 위원장 강득구 </b> 그러면 지금부터 우리 위원님들 한 분당 이렇게 마무리하는 걸로 해 가지고 오늘 하루를 정리하는 걸로 하겠습니다. 괜찮으시죠? 뭐 잠깐 질의하시는 것도 괜찮고요. 권칠승 위원님부터 마무리…….
</p>
<p><b>○ 권칠승 위원 </b> 화성 출신 권칠승입니다. 수고 많이 하셨습니다. 많이 하셨고요, 아까 잠깐 말씀드렸는데 원래 공적기관이 이런 과정들을 다 겪는 것 아니겠습니까? 또 저희들이 그런 임무를 띠고 와 있고 그렇습니다. 오늘 하루 수고 많으셨습니다. 이상입니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다.
</p>
<p><b>○ 위원장 강득구 </b> 다음 김현삼 위원님.
</p>
<p><b>○ 김현삼 위원 </b> 수고하셨습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 다음 박승원 위원님.
</p>
<p><b>○ 박승원 위원 </b> 원장님 오셔서 첫해 행정감사 받느라고 고생 많으셨습니다. 수고하셨습니다.
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다. 
</p>
<p><b>○ 위원장 강득구 </b> 박용진 위원님.
</p>
<p><b>○ 박용진 위원 </b> 원장님, 수고 많으셨고요. 어쨌든 지난해 이어서 올해도 계속 경기개발연구원이 어떤 지사의 싱크탱크냐 이런 지적들이 많이 이어지는데 사실은 그게 아무런 근거 없이 나오는 이야기는 아닐 거라고 생각합니다. 어쨌든 간에 연구원에서 발간되는 연구방향이나 그런 논점의 흐름들이 그런 오해가 있다면 오해를 풀어야겠지만 설령 만약에 진짜 그런 의도로 경기개발연구원이 존재가 된다면 이것은 정말 심히 다시 한 번 생각을 해봐야 되지 않을까 이렇게 생각이 듭니다. 아무쪼록 오늘 위원님들 많은 지적과 그런 사항들을 잘 고려하셔 가지고 원장님 학자적인 그런 양심에 위배되지 않도록 경발연 잘 이끌어 주시기를 부탁드립니다. 
</p>
<p><b>○ 경기개발연구원장 홍순영 </b> 네, 감사합니다. 
</p>
<p><b>○ 위원장 강득구 </b> 다음 임병택 위원님.
</p>
<p><b>○ 임병택 위원 </b> 없습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 그러면 마무리하겠습니다. 저는 오늘 개인적으로 우리 지역 선배님이 지금 앞자리에 계십니다. 그래서 속으로 한편으로 부담도 되고 그랬습니다. 부담도 되고 그랬는데 어쨌거나 저는 의원으로 있는 동안은 사명감 갖고 가고 싶습니다. 의원으로 있는 동안은 소명감 갖고 싶습니다. 아마 지금 함께하고 있는 위원님들 다 입장이 그런 부분에 대해서 마찬가지라고 생각합니다. 그게 저를 포함한 우리 11명 위원님들이 이 자리에 앉게 해준 도민에 대한 최소한의 예의라고 또 도의라고 생각하기 때문에 그렇습니다. 행정사무감사 목적이 피감기관을 야단치고 이런 게 아닙니다. 피감기관이 미처 보지 못했던 또 생각하지 못했던 이런 부분들에 다양한 시각들이 있다라는 것을 얘기하고 싶었고 또 문제점에 대해서 같이 고민해 보고 대안을 좀 찾고 싶었던 겁니다. 오늘 하루 한 게 그냥 이벤트성 행사라고 생각하지 마시고요. 서로가 고민하고 또 서로가 다시 한 번 1년을 되돌아보는 시간이 되기를 진심으로 바라겠습니다. 이상으로 마치겠습니다.
</p>
<p style="padding-left:1.2em">  오늘 함께해 주신 모든 분들께 감사드리고 마지막으로 저희 위원님들이 혹여라도 얘기한 부분 중에서 상대방이 마음을 상했다든지 그런 부분들이 있으면 좀 이해해 주십시오. 개인적인 사감은 아무것도 없습니다. 
</p>
<p style="padding-left:1.2em">  우리 위원 여러분 그리고 홍순영 경기개발연구원장을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성의껏 답변해 주신 홍순영 원장님을 비롯한 임직원 여러분께 감사드립니다.
</p>
<p style="padding-left:1.2em">  그러면 이상으로 오늘 경기개발연구원 소관사항에 대한 2011년도 행정사무감사를 모두 마치겠습니다. 산회를 선포합니다.
</p>
<p class=''ar''>(18시58분 감사종료) 
</p>
<p><hr /></p>
<p><b>○ 출석감사위원(11명)
</b></p>
<p class=''aMan''>강득구권칠승안병원김주삼김현삼박승원박용진이승철임병택장호철</p>
<p class=''aMan''>정재영</p>
<p><b>○ 출석전문위원
</b></p>
<p class=''em15''>   수석전문위원 오태철
</p>
<p><b>○ 피감사기관참석자
</b></p>
<p><p class=''em15''>경기개발연구원장 홍순영부원장 조응래기획조정실장 강철구</p>
<p><p class=''em15''>사무처장 이재동정책센터장 김은경자치행정연구부장 송상훈</p>
<p><p class=''em15''>도시ㆍ지역계획연구부장 이상대교통정책연구부장 김대호</p>
<p><p class=''em15''>환경정책연구부장 이양주경제사회연구부장 김군수</p>
<p><p class=''em15''>문화관광연구부장 이정훈통일ㆍ동북아연구센터장 김동성</p>
<p><p class=''em15''>의정연구센터장 신원득</p>
