            <p class="skip">맨위로 이동</p>

            <div','경기도의회',false,'{"legacy_id": "audit-1097", "files": [], "source": "kms.ggc.go.kr 행정사무감사", "url": "https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1097"}'::jsonb,'2011-11-07'::date,'2011-11-07'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'audit-1097');
insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'audit','[2010.11.17. 수요일] 경기개발연구원 — 기획위원회 2010년도 행정사무감사','<div class="box" style="margin-bottom:16px"><b>제8대 경기도의회 기획위원회</b> · 2010년도 행정사무감사(2010. 11. 15. ~ 2010. 11. 24.)<br>원문: <a href="https://kms.ggc.go.kr/cms/mntsViewer.do?mntsId=1192" target="_blank" rel="noopener" style="color:var(--primary);text-decoration:underline">경기도의회 회의록 뷰어에서 보기</a></div><p>2010년도 행정사무감사
</p>
<h4>기획위원회 회의록
</h4>
<p class=''ar''>경기도의회사무처
</p>
<p><hr /></p>
<p>피감사기관 : 경기개발연구원
</p>
<p><hr /></p>
<p>일  시 : 2010년 11월 17일(수)
</p>
<p>장  소 : 경기개발연구원회의실
</p>
<p><hr /></p>
<p class=''ar''>(10시11분 감사개시)
</p>
<p><b>○ 위원장 강득구 </b> 좌석을 정돈하여 주시기 바랍니다. 지금부터 지방자치법 제41조, 동법 시행령 제39조 및 경기도의회 행정사무감사 및 조사에 관한 조례 제2조 규정에 의하여 경기개발연구원에 대한 2010년도 행정사무감사를 시작하겠습니다.   
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 경기개발연구원 원장을 비롯한 임직원 여러분! 안녕하십니까? 기획위원회 감사위원장 강득구 위원입니다. 오늘은 우리 위원회 감사일정에 따라 경기개발연구원에 대한 행정사무감사를 실시하게 되었습니다. 여러분께서도 잘 아시는 바와 같이 지방의회의 행정사무감사는 연구원의 행정사무 전반에 관한 실태를 정확히 파악하여 의정활동에 반영하고 2011년도 예산안 심사자료 및 정보획득을 통해 이를 도정시책에 반영하고자 함이 그 목적이므로 매우 중요한 의미가 있다고 할 수 있겠습니다. 따라서 경기도의 싱크탱크인 우리 경기개발연구원의 운영실태를 감사하는 것인 만큼 연구원에 대한 심도 있는 감사활동으로 경기도 발전을 위한 정책대안이 제시될 수 있도록 위원 여러분들의 적극적인 감사활동을 부탁드립니다. 아울러 감사에 임하는 원장과 임직원 여러분께서도 위와 같은 목적이 달성될 수 있도록 적극 협조해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  경기개발연구원은 제가 알기에는 1995년 3월 20일 날 개원한 것으로 알고 있습니다. 그렇지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 벌써 15년의 세월이 흘렀습니다. 공자는 15세에 학문에 뜻을 둔다고 하였습니다. 경기도 발전을 위해 뜻을 둔 경기개발연구원 행정사무감사가 저는 그 의미가 남다르다고 생각합니다. 오늘 행정사무감사가 경기개발연구원의 다음 15년을 내다보는 전환의 발판이 되기를 희망합니다. 
</p>
<p style="padding-left:1.2em">  그럼 감사를 시작하기 전에 증인선서를 받도록 하겠습니다. 감사를 받는 원장 및 부원장, 부장, 센터장은 증인의 자격으로 소관 업무를 보고하고 질의에 답변하기에 앞서 먼저 선서를 하셔야 됩니다. 증인선서의 취지와 관계규정을 말씀드리면 선서를 하는 이유는 이번에 경기도의회가 2010년도 행정사무감사를 실시함에 있어서 증인으로부터 양심에 따라 숨김없이 사실대로 증언하겠다는 서약을 받기 위한 것입니다. 만약 증인이 허위증언을 할 때에는 지방자치법 제41조제5항 및 경기도의회 행정사무감사 및 조사에 관한 조례 제30조 규정에 의하여 고발될 수 있습니다. 또한 증언 또는 진술을 거부할 때에는 동법 규정에 의하여 500만 원 이하의 과태료가 부과될 수 있음을 알려드립니다. 
</p>
<p style="padding-left:1.2em">  그러면 먼저 증인출석 여부를 확인하겠습니다. 피감사기관의 증인은 모두 자리에서 일어서 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (일동기립) 
</p>
<p style="padding-left:1.2em">  원장님 나오셨지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 부원장 나왔습니까?
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 기획조정실장 나왔습니까? 
</p>
<p><b>○ 기획조정실장 김군수 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 사무처장 나왔습니까? 
</p>
<p><b>○ 사무처장 강세훈 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 자치행정연구부장 나왔습니까?
</p>
<p><b>○ 자치행정연구부장 송상훈 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 도시ㆍ지역계획연구부장 나왔습니까? 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 교통정책연구부장 나왔습니까? 
</p>
<p><b>○ 교통정책연구부장 김대호 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 환경정책연구부장 나왔습니까? 
</p>
<p><b>○ 환경정책연구부장 이양주 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 경제사회연구부장 나왔습니까?
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 통일ㆍ동북아연구센터장 나왔습니까? 
</p>
<p><b>○ 통일ㆍ동북아연구센터장 김동성 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 의정연구센터장 나왔습니까? 
</p>
<p><b>○ 의정연구센터장 신원득 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 문화관광연구센터장 나왔습니까? 
</p>
<p><b>○ 문화관광연구센터장 이정훈 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 감사합니다. 다음은 선서의 요령을 설명드리겠습니다. 선서는 전체 증인을 대표하여 원장이 발언대에 나오셔서 오른손을 들고 선서문을 낭독하시고 다른 증인들께서는 자리에서 오른손만 들어주시기 바랍니다. 그러면 선서를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 선서! 본인은 경기도의회가 지방자치법 제41조, 같은 법 시행령 제39조제1항, 경기도의회 행정사무감사 및 조사에 관한 조례 제2조에 따라서 소관 업무에 대한 2010년도 행정사무감사를 실시함에 있어 기관장으로서 성실하게 감사를 받을 것이며 또한 증인으로서 증언을 함에 있어서는 지방자치법 시행령 제43조제5항과 경기도의회 행정사무감사 및 조사에 관한 조례 제19조에 따라 양심에 따라 숨김과 보탬이 없이 사실 그대로 말하고 만일 거짓이 있으면 위증의 벌을 받기로 서약하고 이에 선서합니다. 2010년 10월 17일 경기개발연구원장 좌승희.
</p>
<p style="padding-left:2.4em">    (경기개발연구원장, 위원장에게 선서문 제출)
</p>
<p><b>○ 위원장 강득구 </b> 자리에 앉아주시기 바랍니다. 
</p>
<p style="padding-left:2.4em">    (일동착석)
</p>
<p style="padding-left:1.2em">  그러면 좌승희 원장 나오셔서 간부소개와 업무보고를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 안녕하십니까? 경기개발연구원장 좌승희입니다. 오늘 경기도의회 기획위원회 행정사무감사 수감에 앞서 존경하는 강득구 위원장님과 위원님 여러분을 모시고 우리 연구원의 주요업무보고를 드리게 되어 감사의 말씀을 드립니다.
</p>
<p style="padding-left:1.2em">  우리 연구원은 경기도정을 선도하는 싱크탱크로서 경기도와 나아가 대한민국의 발전을 견인하고 도민의 삶의 질 향상을 위한 정책개발에 임직원 모두 노력하고 있습니다. 우리 연구원은 금년 남은 기간과 내년에도 이와 같은 목표를 차질 없이 추진해 나갈 계획이오니 기획위원회 위원님들의 많은 도움과 성원을 부탁드립니다.
</p>
<p style="padding-left:1.2em">  그러면 보고에 앞서 우리 연구원의 간부를 소개해 드리겠습니다. 제 오른쪽으로 조응래 부원장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김군수 기획조정실장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  강세훈 사무처장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  제 왼쪽으로 송상훈 자치행정연구부장입니다. 
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이상대 도시ㆍ지역계획연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김대호 교통정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이양주 환경정책연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김은경 경제사회연구부장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김동성 통일ㆍ동북아연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  신원득 의정연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  이정훈 문화관광연구센터장입니다.
</p>
<p style="padding-left:2.4em">    (인   사)
</p>
<p style="padding-left:1.2em">  김제국 수도권정책센터장은 신체검사결과가 안 좋아서 오늘 병가로 참석하지 못했습니다. 대신에 김은경 경제사회연구부장이 필요한 질문에 대한 답변을 하기로 했습니다. 다음 팔당물환경센터장은 현재 공석 중입니다. 정책연구부장인 이기영 박사가 대리참석했습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 간부소개를 마치고, 지금부터 우리 연구원의 주요업무를 보고드리겠습니다.
</p>
<p style="padding-left:1.2em">  배부해 드린 보고자료의 보고순서를 참조해 주시기 바랍니다. 보고드릴 순서는 일반 및 재정운영현황, 2010년도 연구사업 목표 및 추진실적, 2010년도 주요 연구사업실적, 2011년도 연구사업계획 순입니다. 연구사업 목표와 주요 연구사업실적을 중심으로 간략히 보고드리도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  먼저 일반 및 재정운영현황입니다. 일반현황, 재정운영현황 순으로 보고 올리겠습니다. 먼저 3쪽에 일반현황에 대해 보고드리겠습니다. 우리 연구원은 1995년에 개원하여 현재 1실 1처 5부 5센터 2과 10팀의 큰 조직으로 성장했습니다.
</p>
<p style="padding-left:1.2em">  다음은 4쪽의 인력현황에 대해 보고드리겠습니다. 현재 인력은 원장 1명, 부원장 1명, 연구직 53명, 관리직 등 77명과 계약직 116명으로 총 193명이 근무를 하고 있습니다. 연구직의 일부 부족한 인력은 분야별로 보강해 나가고 있습니다.
</p>
<p style="padding-left:1.2em">  다음 5쪽의 재정운영 상황에 대해 말씀 올리겠습니다. 올해의 총 재정규모는 477억 3,900만 원이며 여기에는 일반회계, 수탁용역사업특별회계, 기금이 포함되어 있습니다. 여기서 재정규모의 주요 감소원인을 보시면 2009년도에 비해서 2010년이 재정규모가 많이 감소했습니다만 이것은 경기도의 출연금 감소와 연구직 성과연봉 지급시기를 연초로 바꿈에 따라서 2010년 예산이 다소 감소하게 되었습니다. 
</p>
<p style="padding-left:1.2em">  일반회계 수입ㆍ지출내역을 구체적으로 살펴보면 수입총액은 160억 3,000만 원이고 수입항목은 경기도 출연금이 전체의 62%인 99억 원, 기금전입금이 6%인 10억 원, 기금이자수입 등이 10%인 15억 5,500만 원, 사업수입이 7%인 11억 8,500만 원, 전기이월금이 15%인 23억 9,000만 원이며, 지출항목으로는 연구사업비가 전체의 48%인 76억 원, 인건비가 39%인 63억 4,000만 원, 부서운영비가 6%인 9억 8,700만 원, 청사관리비가 6%인 9억 5,300만 원, 예비비가 1%에 해당하는 1억 5,000만 원입니다. 인건비가 다소 많은 것은 연구원의 특성상 연구원은 인건비가 사실은 사업비와 크게 다르지 않다고 생각합니다. 그래서 분리는 따로 했지만 연구사업에 다 들어간 비용으로 생각하시는 게 좋겠다고 생각합니다.
</p>
<p style="padding-left:1.2em">  다음은 6쪽이 되겠습니다. 연구원의 기금에 대해서 말씀 올리겠습니다. 기금총액은 현재 262억 원입니다. 출연기관별로는 경기도가 56%인 147억 원, 시군이 15%인 39억 6,100만 원, 민간부분에서 8%인 20억 원이 출연되었고요. 자체적립이 21%인 55억 3,900만 원입니다. 예치기관별 운용현황은 표를 참조해 주시면 감사하겠습니다. 예산이 효율적으로 운용될 수 있도록 최선을 다하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 2010년도 연구사업 목표 및 추진실적에 대해 보고드리겠습니다. 보고자료 9쪽부터 10쪽이 되겠습니다. 9쪽 2010년도 연구사업 목표에 대해서 말씀 올리겠습니다. 우리 원은 비전을 “대한민국을 움직이는 중심 브레인 GRI”라고 설정을 했고요. 이러한 비전을 달성하기 위한 3대 미션으로 “경기도정을 선도하는 종합적 연구기관”, “대한민국의 미래를 여는 중추적 연구기관”, “동북아ㆍ국제사회와 함께하는 글로벌 연구기관”으로 내걸고 연구사업을 진행하고 있습니다.
</p>
<p style="padding-left:1.2em">  2010년도 연구사업목표를 말씀드리면 경기도 경제활성화와 일자리 창출지원, 수도권 경쟁력 강화를 위한 메가시티 전략 제시, 저탄소 녹색성장 대응 정책연구 선도로 설정했습니다. 이러한 연구사업목표의 달성을 위하여 연구분야를 행정ㆍ의정 분야, 도시ㆍ교통 분야, 환경ㆍ물 분야, 산업ㆍ경제 분야, 수도권ㆍ동북아 분야, 문화ㆍ복지 분야의 6대 분야로 구분하고 각 연구분야별로 지방행정체계 개편 대응체계 구축 등 24개 대과제를 선정하였으며 이를 중심으로 연구사업을 추진하였습니다. 특히 올해의 경우 지난해 경기도 인재개발원과 공동으로 도출된 우리 원의 핵심가치와 인재상의 정착을 위한 교육개발사업을 추진하여 구성원 모두의 역량 극대화에 최선을 다하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 10쪽이 되겠습니다. 우리 원의 연구과제사업 등 4대 사업별 사업계획 대비 추진실적을 보고드리겠습니다. 2010년도 연구과제사업은 신규과제 168개 과제와 전년도 이월과제 65개 과제를 포함하여 총 233개 과제 수행을 계획하였으며 10월 31일 현재 89% 진행 중에 있습니다. 연구부대사업은 정책세미나 19회, 선진화위원회ㆍ포럼 운영 50회 등을 수행하여 현재 85% 진행 중에 있으며 연구지원사업과 연구기반사업도 차질 없이 추진 중에 있습니다. 각 단위사업별 구체적인 추진실적은 37쪽 이후의 2010년 단위 연구사업 실적을 참고해 주시기 바랍니다.
</p>
<p style="padding-left:1.2em">  다음은 2010년도 주요 연구사업 실적에 대해서 보고 올리겠습니다. 보고자료 13쪽부터 27쪽이 되겠습니다. 먼저 13쪽 행정ㆍ의정 분야의 연구실적에 대해 보고드리겠습니다. 행정ㆍ의정 분야는 금년도 주요과제로 지방행정체계 개편 대응체계 구축, 공공기관ㆍ공기업 평가 선진화, 지방자치 역량강화 그리고 의정역량 제고 등 4대 과제를 선정하여 이를 중심으로 개별연구과제를 수행하였습니다. 지방행정체계 개편 대응체계 구축과 관련해서는 지방행정체제 개편에 관한 특별법안의 법리적 문제점 진단 등을 통해 관련 특별법에서 도 폐지 문구를 삭제하는 성과를 달성했습니다. 다음으로 공공기관ㆍ공기업 평가 선진화와 관련해서는 경기도 공공기관 경영평가제도 개선을 위한 평가모형개발 연구 등을 통해 경기도 공공기관 및 공기업 평가체계 및 지표를 보완하여 어느 때보다도 공정한 공기업 평가를 진행하였습니다.
</p>
<p style="padding-left:1.2em">  다음으로 14쪽입니다. 지방자치 역량강화 연구와 관련해서는 광역자치단체 역량 강화방안 연구 등을 수행하였고 그리고 의정역량 제고와 관련해서는 지방의회의 의정성과지표 개발에 관한 연구, 지방의회 관련 법령 및 자치법규 개선 연구 등을 수행하여 도의회의 법령 개정 등의 의정활동을 지원하였고, 특히 의정포럼을 운영하면서 도의회의 문제를 발굴하여 개선방안을 제시하는 노력을 했습니다.
</p>
<p style="padding-left:1.2em">  다음으로 도시ㆍ교통 분야 실적에 대해서 보고 올리겠습니다. 도시ㆍ교통 분야는 금년도 주요과제로 수도권 광역급행철도 연계 도시ㆍ교통정책, 녹색성장의 도시ㆍ교통모델 개발 정립, 도시계획 패러다임 전환체계 정립, 복지교통수단의 활성화ㆍ광역화 등 4개 대과제를 선정하여 이를 중심으로 연구과제를 수행했습니다. 수도권 광역급행철도 연계 도시ㆍ교통정책과 관련해서는 광역철도 건설에 따른 재원분담기준 방안연구 등을 통해 경기도와 시군 간 광역철도 재원분담기준의 개선 변경 등을 이끌어내었습니다.
</p>
<p style="padding-left:1.2em">  다음은 16쪽이 되겠습니다. 녹색성장의 도시ㆍ교통모델 개발 정립과 관련해서는 교통서비스 지표를 활용한 도시 경쟁력 비교 연구, 경기도 저탄소 녹색도시 조성 방안에 관한 연구 등을 수행하였습니다. 특히 외곽순환고속도로를 이용한 지역 간 버스노선체계 구축방안 연구를 통해 올해 8월부터 경기순환버스 운행이 개시되었으며, 경기도 저탄소 녹색도시 조성 방안에 관한 연구에서는 시범도시 건설지원을 위한 조례안을 제시하였습니다. 또한 지난 9월 도의회에 보고드린 바와 같이 경기도 최초의 법정 종합계획으로써 경기도 종합발전계획 수립 연구용역을 수행 중에 있습니다. 기획위원회 위원님들께도 향후 별도의 보고를 드릴 예정이므로 많은 관심과 고언을 부탁드립니다.
</p>
<p style="padding-left:1.2em">  다음은 17쪽입니다. 도시계획 패러다임 전환체계 정립 연구와 관련해서는 창조도시이론과 미래도시발전방향에 관한 연구, 광역 수도권의 발전단계에 따른 경기도 계획과제 연구 등을 수행하고 있으며, 특히 서해안 발전전략 구상에 따라 경기도, 안산시, 시흥시 및 화성시 간 MOU가 체결되었으며, 도시관리계획 권한이양에 따른 예상영향 및 대응방안 연구결과는 국토해양부의 국토의 계획 및 이용에 관한 법률의 수정안에 반영되어 현재 국회에 계류 중에 있습니다. 복지교통수단의 활성화ㆍ광역화 연구와 관련해서는 광역버스 노선 신설ㆍ개편 및 환승체계 구축방안 용역을 했고 차세대 교통수단, 택시 PRT 도입 구상 등의 연구를 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 18쪽이 되겠습니다. 다음은 환경ㆍ물 분야의 연구실적에 대해 보고드리겠습니다. 환경ㆍ물 분야는 기후변화ㆍ녹색성장 대응 환경정책, DMZ 보전ㆍ이용을 위한 정책연구, 환경산업 지원 및 육성 정책 그리고 미래형 수질관리 방안 구축 등 4개 대과제를 선정하여 이를 중심으로 세부 연구과제를 수행했습니다. 기후변화ㆍ녹색성장 대응 환경정책과 관련해서는 경기도 폐자원 에너지 활용방안, 경기도의 토양환경 현황파악 및 정책방향 설정 연구, 도시열섬 완화를 위한 옥상녹화 활성화 방안 등의 연구를 수행하였습니다. 특히 경기도 기후변화 대응 종합계획 수립에 있어서는 경기도 실국별 실행계획을 작성하여 실천토록 조치하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 19쪽이 되겠습니다. DMZ 보전ㆍ이용을 위한 정책연구와 관련해서는 민통선지역의 유네스코 생물권지역 지정을 위한 타당성조사 및 관리방안 연구 등을 수행하였으며, 환경산업 지원 및 육성 정책 연구와 관련해서는 경기도 대기분야 환경산업 현황 및 육성 방안에 대해서 연구하였고, 미래형 수질관리 방안 구축과 관련해서는 수질오염총량관리제의 합리적 이행평가 방안에 관한 연구, 미계측 유역에서 기준유량 산정 방안 연구 등을 수행했습니다. 모두가 다 수질오염총량제와 관련된 연구가 되겠습니다. 특히 경기도는 민통선지역의 유네스코 생물권지역 지정을 위한 타당성조사 및 관리방안 연구결과를 바탕으로 DMZ 유네스코 생물권지역 지정을 추진하고 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 20쪽의 산업ㆍ경제 분야입니다. 산업ㆍ경제 분야는 신성장동력산업의 글로벌 거점화, 일자리중심의 산업정책 비전ㆍ전략 제시, 경기도형 일자리 창출모형 개발, FTA 대응 산업구조 고도화 등 4개 대과제를 선정하여 이를 중심으로 구체적인 연구를 수행하였습니다. 신성장동력산업의 글로벌 거점화 연구와 관련해서는 기업입지 유형별 생산성 분석, 신성장동력 산업의 집적특성 연구 등을 수행하고 있습니다. 특히 산업입지 공급정책 발전방안 연구를 통해 국토해양부의 경기도 산업입지공급 규모를 확보하였으며, 평택항 서부두 행정구역 조정에 관한 연구를 통해 평택항 서부두 행정구역 조정 중앙분쟁조정위원회의 심의자료를 작성 제출한 바가 있습니다.
</p>
<p style="padding-left:1.2em">  다음은 21쪽이 되겠습니다. 일자리중심의 산업정책 비전ㆍ전략 제시 연구와 관련해서는 경기도 단기지역경제전망 모형 구축에 관한 연구를 했고 경기도 지역산업의 중장기 발전계획 등을 수행하였으며, 경기도형 일자리 창출모델 개발과 관련해서는 경기북부 섬유산업 육성방안, 경기북부 가구산업 경쟁력 강화방안 등에 대해서 연구를 수행했습니다. 특히 경기도 일자리 정책 마스터플랜 수립을 통해서 가칭 경기일자리은행을 제안하여 경기일자리센터를 설립하는 데 기여하였으며 경기북부 섬유산업 육성방안 연구를 통해서는 경기북부 섬유센터를 설립하고 마케팅 계획을 수립하는 데 기여하였습니다.
</p>
<p style="padding-left:1.2em">  다음은 22쪽입니다. FTA 대응 산업구조 고도화 연구와 관련해서 지역 간 산업연계 및 협력방안 연구, 녹색성장 정책의 진단 및 개선안 등의 연구를 수행하였습니다. 특히 기업형 슈퍼마켓 확산의 지역상권 영향과 대응방안 연구는 경기도의 SSM 사전조정단계 합의건수 비율을 전국 최다수준으로 견인하는 데 일조했다고 생각합니다.
</p>
<p style="padding-left:1.2em">  다음은 23쪽 수도권ㆍ동북아 분야의 연구실적에 대해 보고드리겠습니다. 수도권ㆍ동북아 분야는 세계 대도시권ㆍ지역 연구, 수도권 성장을 위한 규제개혁 추진, 남북관계 분석 및 위기관리체계 구축, 민군협력ㆍ접경지역 상생강화 등 4개 대과제를 선정하여 이를 중심으로 세부 연구과제를 수행하였습니다. 세계 대도시권ㆍ지역 연구와 관련해서 세계지역연구, 동아시아 경기제에 관한 비교연구 등을 수행완료 또는 수행 중에 있습니다. 특히 세계지역연구를 통해서 GCR, 풀어쓰면 Global City Region Review라는 제명의 준학술지 성격의 세계도시 및 지역연구 매거진을 창간하고 창간호를 “근대도시 100년” 주제로 지난 10월 발간하였습니다. 또한 경기도 국제교류협력 기본계획 연구를 통해 경기도, 일본 가나가와현 및 중국의 랴오닝성의 3지역 우호교류 합의서에 각 지역에 교류실무자급 핫라인을 구축하는 성과를 거두었습니다.
</p>
<p style="padding-left:1.2em">  다음 24쪽이 되겠습니다. 수도권 성장을 위한 규제개혁 추진 연구와 관련해서는 지역경제 활성화를 위한 환경규제 합리화방안 연구, 수도권 규제 합리화를 통한 외국인투자 촉진방안 등의 연구를 수행했습니다. 그리고 남북관계 분석 및 위기관리체계 구축과 관련하여 한반도 동맹구조와 한국의 신대외전략, 북핵문제의 진전 전망과 대북정책의 과제, 남북관계 변화에 따른 경기도의 대응방안 연구 등을 수행하였습니다.
</p>
<p style="padding-left:1.2em">  다음 25쪽입니다. 민군협력ㆍ접경지역 상생강화를 위한 연구는 군 관련 현안사항 대응방안 마련 연구 등을 수행했습니다. 특히 저희 연구원에 전직 장성급으로 구성된 민군정책팀이 구성돼서 그분들의 군 경험과 인적네트워크를 활용하여 수행 중에 있는 군 관련 현안사항 대응방안 마련 연구에서는 우선 도시개발법 개정 및 군작전 영향평가법 제정을 추진하였고, 둘째로 군비행장 민군공동이용방안에 대한 연구를 추진하고 있으며, 셋째는 무건리훈련장 주민 이주단지 보상현실화 등 수많은 민관군 관련 현안사항을 지원하고 있습니다. 군 접경지역을 가지고 있는 경기도로서 민군정책팀이 큰 기여를 하고 있습니다. 또한 한반도 신평화구상 이행전략 연구를 통해서 남북청소년교류센터를 경기도에 유치하는 성과를 거두었습니다.
</p>
<p style="padding-left:1.2em">  다음은 26쪽입니다. 문화ㆍ복지 분야 실적에 대해서 보고드리겠습니다. 문화ㆍ복지 분야는 녹색관광산업 육성, MICE산업과 문화콘텐츠 개발, 양극화ㆍ고령화에 대응한 복지정책, 효율적 지역복지전달체계 구축 등 4개 대과제를 선정하여 이를 중심으로 세부 연구를 수행했습니다. 녹색관광산업 육성과 관련해서는 서해안 갯벌생태관광 상품화 전략, 신한류콘텐츠 음식관광 활성화 방안 등의 연구를 수행하였고, MICE산업과 문화콘텐츠 개발과 관련해서는 경기도 문화유산의 스토리텔링화 방안에 관한 연구를 수행 중에 있습니다. 특히 강변 문화관광개발계획, 한강 문화관광권 발전계획 연구 결과는 문화부의 2010년도 강변 문화역사자원 개발사업 예산에 반영되는 성과를 거두었습니다.
</p>
<p style="padding-left:1.2em">  다음은 27쪽이 되겠습니다. 양극화ㆍ고령화에 대응한 복지정책과 관련해서는 저소득 취약계층의 건강보호방안 연구, 2014년 경기노인복지 비전 수립 등을 수행완료 또는 수행 중에 있습니다. 특히 2014년 경기노인복지 비전 수립을 통해 지난 9월 발표된 건강노인 백세 프로젝트가 수립되었습니다.
</p>
<p style="padding-left:1.2em">  2010년도 연구사업 진행상황 보고를 마치고, 다음에는 2011년도 연구사업계획에 대해서 보고드리겠습니다. 보고자료 31쪽부터 36쪽이 되겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 원장님, 가급적이면 짧게 유인물로 대체할 건 대체하시고요. 감사합니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알겠습니다. 먼저 31쪽 2011년도 연구사업 목표 및 연구사업 분야별 과제에 대해 보고드리겠습니다. 우선 비전과 3대 미션 및 6대 전략의 성공적 추진을 위하여 2011년도 연구사업목표를 경기도 경제ㆍ사회ㆍ문화시스템 선진화를 위한 정책지원, 수도권 글로벌 경쟁력 강화를 위한 메가시티 전략 제시, 동북아 메타경제권 구축 및 발전전략 구상으로 설정했습니다. 그리고 이와 같은 연구사업 목표의 달성을 위하여 연구 분야를 6대 분야로 세분화하고 주요 대과제 24개를 선정하여 이를 중심으로 구체 연구사업을 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  6대 분야 24개 대과제는 31쪽 하단에 보고드렸는데 간략하게 말씀 올리겠습니다. 행정ㆍ의정 분야의 지방자치ㆍ지방분권 강화 등 4과제, 도시ㆍ교통 분야의 GTX연계 녹색철도망 계획 수립 등 4과제, 환경ㆍ물 분야의 기후변화ㆍ녹색성장 대응 및 적응 등 4과제, 산업ㆍ경제 분야의 환황해권 대중국전략특구 조성 추진 등 4과제, 수도권ㆍ동북아 분야의 세계 대도시권ㆍ지역 연구 등 4과제, 사회ㆍ문화 분야의 통합 에듀케어시스템 구상 등 4개 과제가 포함되어 있습니다.
</p>
<p style="padding-left:1.2em">  32쪽 2011년도 연구사업 추진체계입니다. 연구사업 추진체계는 내년에도 올해와 동일하게 연구과제사업을 중심으로 연구부대사업, 연구지원사업 그리고 연구기반사업으로 구분하여 추진할 계획입니다. 다만 연구과제사업 중 지역연구과제는 경기도 시군의 정책현안에 대한 지원을 강화하기 위하여 정책연구과제의 지역정책과제로 변경 추진하고자 합니다. 금년에는 지역 시군에 대한 정책현안 지원을 강화하도록 노력하겠습니다. 이렇게 함으로써 그 동안 지역연구를 연간 한두 건 한정된 범위 안에서만 수행을 했었습니다만 보다 적극적으로 시군 정책수요에 탄력적으로 대응할 계획입니다. 
</p>
<p style="padding-left:1.2em">  다음은 33쪽 2011년도 연구사업 총괄에 대해서 보고드리겠습니다. 2011년도에는 연구과제사업으로 기본연구과제 20개 과제, 정책연구과제 90개 과제, 수탁연구과제 45개 과제 그리고 협약연구과제 5개 과제 등 총 160개 과제를 계획하고 있습니다. 연구과제사업은 연구원의 연구사업 목표와 분야별 과제를 중심으로 내년도 대외 여건의 변화를 반영하여 추진할 계획입니다.
</p>
<p style="padding-left:1.2em">  연구부대사업, 지원사업, 기반사업의 세부내용은 자료로 대신하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  다음은 34쪽입니다. 2011년도 연구사업 6대 분야 24개 과제별 제안과제 목록도 위원님들께서 허락해 주신다면 자료로 대신하도록 하겠습니다.
</p>
<p style="padding-left:1.2em">  이상으로 우리 원의 주요업무보고를 마치겠습니다. 위원님들, 경청해 주셔서 감사합니다
</p>
<p>업무보고서(경기개발연구원)
</p>
<p><b>○ 위원장 강득구 </b> 원장님 수고하셨습니다. 다음은 감사를 위한 질의 답변 순서가 되겠습니다. 감사의 효율적인 진행을 위해서 질의는 일문일답으로 하겠습니다. 그리고 질의시간을 이번에도 제한하도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  우선 위원님 한 분당 10분씩 시간을 드리고 추가질의는 일단 6분 정도 드리는 걸로 하겠습니다. 그리고 추가질문이 끝나면 감사 진행상황과 시간 등 제반 여건을 감안해서 추가질문을 계속할지 여부를 결정하도록 하겠습니다. 원활한 감사진행을 위해 부득이하게 시간제한을 두게 된 점을 양해해 주시면 감사하겠습니다. 
</p>
<p style="padding-left:1.2em">  오늘은 김주삼 위원님부터 질의하도록 하겠습니다. 아울러 질의에 앞서 위원장으로서 한 가지 부탁의 말씀을 드리겠습니다. 위원님들의 질의에 대해서 원장님 답변이 어려울 경우에는 업무 담당부장 및 센터장 등 실무자가 답변해도 좋습니다. 다만 사전에 위원장에게 동의를 얻은 후 발언대로 나와서 소속과 직, 성명을 분명히 밝히고 답변해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  그럼 첫 번째로 김주삼 위원님이 먼저 질의를 해주시기 바라고요. 위원님들이 양해해 주시면 원장님 앉아서 답변해 주셔도 좋습니다. 양해해 주실 수 있죠?  
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  감사합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다.
</p>
<p><b>○ 위원장 강득구 </b> 김주삼 위원님.
</p>
<p><b>○ 김주삼 위원 </b> 군포 출신 김주삼 위원입니다. 일단 먼저 자료 보완 요청을 두 가지만 드리겠습니다. 업무추진비 집행내역 중에 2010년 10월분, 그러니까 9월분까지 자료가 돼 있는데 10월분 추가로 바로 제출을 해주시기 바라고요. 연구원들에 대한 자체평가 결과를 제가 받았는데 평가시스템만 지금 보고가 되어 있습니다. 그래서 평가결과가 어떤지 그런 자료를 바로 보완을 해주시기 바랍니다. 추가질의 때 제가 좀 필요합니다. 
</p>
<p style="padding-left:1.2em">  그럼 제가 두 가지만…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위원님, 자료 보완과 관련해서 첫 번째 자료는 바로 저희가…….
</p>
<p><b>○ 김주삼 위원 </b> 그렇게 하세요. 그거는 나중에 얘기를 하시고요. 그것은 제가…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 두 번째 자료는…….
</p>
<p><b>○ 김주삼 위원 </b> 요청을 드린 거고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 김주삼 위원 </b> 그다음에 세 가지만 간략하게 질문을 드리겠습니다. 먼저 비정규직에 대한 문제입니다. 행정감사자료 579쪽인데 원장님, 비정규직보호법 잘 아시죠? 기간제 및 단시간 근로보호 등에 관한 법률 거기에 보면 현재 연구원에 제출된 자료에 의하면 행정원으로 비정규직이 열여덟 분 계시거든요. 그런데 이게 최근 제가 2006년도부터 자료를 쭉 받았는데 연속해서 지금 계속 근무를 하고 계신 분들이 계십니다, 비정규직으로. 그럼 이분들은 현재도 신분은 비정규직이죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 그럼 그게 지금 법 위반이라는 사실도 알고 계세요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 지난해에 말이죠. 확인을 해야 되겠습니다만 바로 그 문제 때문에 저희 연구원이나 대학의 전임강사를 포함하는 연구직의 비정규직 문제가 저는 그동안 문제가 있다고 생각을 해서 청와대와 노동부를 통해서 제가 어필을 했습니다. 그래서 2년이 지나더라도, 대통령령을 바꿨는데요. 정규직으로 하지 않아도 지속적으로 할 수 있도록…….
</p>
<p><b>○ 김주삼 위원 </b> 지금 얘기하시는 게, 원장님께서 얘기하시는 게 시행령 제3조에 보면 기간근로제 사용기간 제한의 예외규정을 얘기하시는 거죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 맞습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 그런데 그 예외규정 8항에 보면 연구업무에 직접 종사하는 경우 또는 실험조사 등을 수행하는 등 연구목적에 직접 관여하는 지원업무에 종사하는 경우에 한하도록 돼 있습니다. 이분들이 전부 연구업무에 직접 종사를 합니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지원업무의 행정원은 지원업무에 종사…….
</p>
<p><b>○ 김주삼 위원 </b> 그런 의미로 얘기하면 경기개발연구원 모두가 다 지원업무를 하시는 거죠. 그러니까 사무처에 계시는 분들도 다 지원업무를 하고 있다고 광의로 해석하시는 거예요? 그건 아니죠. 여기서 얘기하는 연구업무라는 건 직접적으로 본 연구원이 연구를 수행함에 있어서 보조적 업무, 그러니까 그 보조라는 게 이런 일반 업무보조나 행정보조가 아니라 실험을 하는 데 있어서 조교 형태의 어떤 보조업무를 얘기하는 것 아니겠어요? 그죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다, 무슨 말씀인지.
</p>
<p><b>○ 김주삼 위원 </b> 그래서 저는 경기개발연구원이 심각한 기간제 근로……. 이걸 우리가 통칭 비정규직보호법이라고 하는데 그것을 위반하고 계신 거예요. 그런데 그 내용도 아세요? 특별한 조치 없이 2년 이상 연속해서 근무를 시키면 자동적으로 정규직으로 전환되는 것 알고 계시죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 알고 있습니다.
</p>
<p><b>○ 김주삼 위원 </b> 이분들 빨리 정규직으로 전환을 하셔야 맞고요. 그런데 제가 또 하나 상당히 유감스럽고도 놀라운 것은 2010년도 자료를 보면, 내가 특정인을 지칭하지 않겠습니다. 기획조정실의 어느 분은 전체적으로나, 2006년도부터 5년 동안 근무를 하셨는데 올해는 2월 1일부터 12월 31일까지 계약기간이 돼 있어요. 한 달 지금 텀이 있습니다. 이 얘기는 연속적으로 근무를, 계약을 안 하는 그런 형태를 취한 것이 돼서 기술적으로 비정규직에 대한 법을 빠져나가려고 그러는가 하는 의혹이 들어요. 이런 경우는 좀 문제가 있지 않겠어요? 한 5년 지금 근무하고 계신 분이 한 달 동안 휴가를 냈어요. 이런 부분들은 제가 보기에 원장님께서 전체적으로 비정규직에 관련된 부분에 좀 더 신경을 써주시고 제가 비정규직 관련 자료를 보면 연구원이나 촉탁연구원, 위촉연구원은 방금 얘기한 대로 예외규정에 다 적용이 돼요. 그러나 이 행정원들로 자료 제출된 이분들은, 이분들까지도 이렇게 예외규정에 적용한다는 것은 제가 보기에는 법망을 교묘하게 빠져나가려고 하는 의혹이 드는 그런 문제가 있거든요. 그래서 이 부분들에 대한 어떤 처우문제, 아, 처우가 아니라 자격문제에 대한 전향적인 자세를 가지고 계셨으면 좋겠습니다. 그리고 법에 맞게 조치를 취해 주시는 게 맞다고 생각이 됩니다. 그렇게 하실 수 있겠죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 그 취지를 충분히 이해를 하고요. 제가 한 말씀드리고 싶은 것은 우리 연구원에 지금 박사들이 전부 다 비정규직이나 다름없습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 지금 고유의 연구를 하고 계시는 분들을 얘기하는 것 아니에요. 그분들은 법에 맞게 잘하고 계시는 거예요. 그런데 제가 얘기하는 건 행정직에 있는, 사무처에 계시거나 기획조정실이지만 실제적으로 업무를 보면 단순 일반 행정업무를 취급하시는 분들이거든요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 행정원이 우리 사무처에 순수한 행정을 하는 사람도 있지만 많은 경우에는 박사들이 기조실장이라든가 정책팀장이라든가 이런 것을 하기 때문에 자연스럽게 연구하는 RA들이 가서 하는 경우도 있고 그래서 사실은 꼭 행정지원업무만 하느냐, 연구를 하느냐 하는 것은 사실 구별하기가 애매한 경우가 없지 않습니다.
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 이건 법 해석의 문제일 수도 있지만 지금 이 입법 취지는 연구업무에 직접 관여하는 지원업무거든요. 그 얘기는 예를 들어서 실험을 하는 데, 이분들이 논문 작성하는 데 자료……. 대신 연구해 주는 건 아니잖아요. 그렇기 때문에…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 잘 아는데 꼭 제가 드리고 싶은 얘기는 연구원의 성격상……. 제가 드리고 싶은 얘기는 박사도 그렇고 모든 직원이 사실은 평생 직장 보장이라고 하는 그런 틀이 아니고 항상 성과와 이런 게 연계가 돼서 재임용하는…….
</p>
<p><b>○ 김주삼 위원 </b> 원장님, 그분들 얘기하는 건 아니니까요.
