<p><b>○ 경기개발연구원장 좌승희 </b> 그런 시스템이기 때문에 행정원이라고 하는 사람도 같은 정신에서 하는 게 좋지 박사들이나 RA는 전부 다 2년, 3년 이렇게 재임용을 받는데…….
</p>
<p><b>○ 김주삼 위원 </b> 비정규직 보호법의 기본취지 원장님 잘 아시잖아요. 박사들이나 연구원들은 이 경기개발연구원 말고도 어디든지 가서 자기 스스로 연구해서 어떤 생활보호를 받을 수 있는 분들이에요. 그런데 비정규직 기간제 보호 입법 취지는 그럴 능력이 안 되는 분들을 얘기하는 겁니다. 
