<p><b>○ 경기개발연구원장 좌승희 </b> 그런데 행정원이 꼭 그렇지는 않습니다. 나중에, 이 내용의 취지는 충분히 아는데요…….
</p>
<p><b>○ 김주삼 위원 </b> 그러면 예를 들어서 4대 보험 업무 신고 공문서 접수하는 이분들이, 이분이 지금 5년 근무를 했어요, 여기서. 그런데도 전부 비정규직으로 지금 있습니다. 이건 좀 문제가 있는 것 아닙니까? 그러니까 저는 당연히 사무처에 계신 분들은 100% 다 포함이 돼야 되고 기획조정실에 계신 분들도 그렇다는 얘기입니다. 
</p>
<p style="padding-left:1.2em">  일단 시간이 없어서 하나만 더 하겠습니다. 이 부분은 이런 데로 시정이 되리라고 그렇게 기대를 하고, 그다음에 업무추진비에 대해서 제가 말씀을 드리지 않을 수가 없는데 추가로 이따 보충자료가 오면 되겠지만 제가 서울시연구원하고 비교를 해봤어요. 그런데 서울시연구원의 업무추진비는 2009년도 기준으로 3,866만 원입니다. 총 예산이 200억이에요. 그런데 저희 경기개발연구원 같은 경우 총 예산이 160억, 어쨌든 전체적으로 비슷하지만, 그런데 2009년도 업무추진비가 6,800만 원, 배 이상을 쓰고 계세요. 저는 이런 부분들은……. 그리고 업무추진비의 사용에 대한 목적성이, 제대로 이게 합목적적으로 되고 있느냐는 부분도 제가 쭉 짚어 보니까 이런 부분도 앞으로 좀 원장님께서 유의를 하셔야 할 것 같습니다. 예를 들어서 제가 이 부분도 관련법을 찾아보니까 물론 결혼축의금이나 조의금으로 사용할 수는 있습니다. 그러나 그 경우에도 엄밀하게 제한이 돼 있어요. 그런데 전체적으로 제가 내용을 보면 특정 어느 대학교수 그런 분들 그다음에……. 그러니까 충분히 사용을 하시는 분이 개인적으로 하실 수 있는, 개인적 관계라고 생각이 되는 그런 분들한테도 지출되고 그랬는데 저는 이런 부분들도 아까 전체, 서울시정개발연구원과의 비교에서 업무추진비의 과다한 문제와 함께 합리적으로 좀 써주셨으면 좋겠다 그것을 요청드리고요.
</p>
<p style="padding-left:1.2em">  그다음에 마지막으로 이 부분도 원장님하고 직접적인 관계가 되는 부분인데 원장님께서 “대한민국 성공경제학” 이 책 주셔서 아주 유용하게 잘 봤습니다. 제가 4대강 문제를 김문수 지사한테 문제 제기할 때도 이 책의 도움을 많이 받았어요. 그리고 경기개발연구원에서 나온 자료, 송미영 박사께서 나온 자료 도움을 제가 많이 받았는데 어쨌든 저는 그렇습니다. 당연히 정책자료나 CEO REPORT나 아니면 우리가 연구과제로 낸 그런 부분들은 당연하게 우리 경기개발연구원에서 나오는 게 맞습니다. 그런데 실제 우리 원장님께서 지금 발행하신 이 책은 제가 보기에 원장님의 개인적 견해시잖아요. 그게 우리 경기개발연구원의 과제를 받아서 한 연구이거나 그런 건 아니거든요. 그런데 이 부분이 지금 경기개발연구원에서 발간이 됐거든요. 저는 이런 부분도 어떻게 보면 이게 오해를 살 수 있습니다. 쉽게 얘기해서 원장님의 사적 견해를 경발연, 도비를 쓰는 경기개발연구원의 공적비용으로 출판할 수 있는 이게 좀 문제가 되지 않겠느냐 저는 그런 생각입니다. 그래서 이왕 나온 건 어쩔 수 없지만 앞으로 이런 부분들은 정말 어떤 출판이나 출간에 대한 검증할 수 있는 공적 시스템을 거쳐서 저는 이런 책들이 나와야 된다고 그렇게 보고 있습니다. 어떻게 생각하세요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 좀 생각이 다른데요. 연구원장도 연구는 할 수 있다고 생각합니다. 그런데 그동안 연구원장이 연구를 안 했죠. 그러니까 그런 작품이 나갈 수 없었다고 생각합니다. 
</p>
<p><b>○ 김주삼 위원 </b> 당연히 연구를 하시는 건 맞는데요…….
</p>
