</p>
<p><b>○ 김주삼 위원 </b> 이 연구 내용이 제가 보기에는 평소에, 예를 들어서 어떤 과제를 받아서 하는 그런 연구는 아니라고 봅니다. 좌승희 원장님의 지극히 개인적 견해시거든요. 그리고 그 견해도 실제……. 그럼 이런 견해들이 예를 들어서 경기도정에 반영이 돼야 되는데, 제가 대표적으로 한 곳만 지적하겠습니다. 
</p>
<p style="padding-left:1.2em">  “4대강사업 지역사업화해야 탈 정치화되고 추진력이 배가된다.” 이런 내용 지금 주장하고 계시는 거죠?
