<p><b>○ 김주삼 위원 </b> 그런데 김문수 지사께서는 지금 어떻습니까? 김문수 지사께서 4대강 남한강 사업 경기도로, 국토부나 중앙정부에 경기도에서 하겠다고 그렇게 얘기하고 계십니까? 안 하잖아요.
