<p><b>○ 경기개발연구원장 좌승희 </b> 주시면 잘할 수 있다고 그런 얘기하신 적이 있죠. 
</p>
<p><b>○ 김주삼 위원 </b> 그런데 그런 얘기들이 지극히 피상적이고 정말 누가 봐도 김문수 지사께서 4대강 사업 우리 경기도가 발주하고 경기도에서 책임지고 해야 된다 그런 얘기 안 하시잖아요. 그리고 실제 우리 요즘에 경상남도하고 문제가 되고 있는 그 부분에 대해서 이 견해에 기초해서 어떻게 생각하십니까? 
