<p><b>○ 김주삼 위원 </b> 경상남도가 원치 않는 게 아니잖아요. 경상남도는 검증을 거쳐서 제대로 하자는 얘기죠. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 해서 하면 또 그 방법도…….
