<p><b>○ 김주삼 위원 </b> 그런데 국토부에서는 그냥 그런 검증을 거치지 말고 목표 정해 놓고 목표 시한이 부족하니까 회수해 갔습니다. 좌승희 원장님 견해로 봐서는 정부가 잘못하는 것 아닙니까?
