<p><b>○ 김주삼 위원 </b> 하여튼 알겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 제가 드리고자 하는 말씀은 우리 기본연구나 모든 연구가 결국 박사들의 생각을 담는 것 아니겠어요?
</p>
<p><b>○ 김주삼 위원 </b> 당연히 그렇죠. 그러니까 원장님께서 팀의 일원으로 어떤 과제를 가지고 그 팀을 가지고 그 과제에 함께 하시는 건 100% 그렇게 하셔야죠. 아주 좋은 자세죠. 그런데 지극히 개인적 견해를 경발연에서 발간하는 책으로 나온다는 것은 하여튼 저는 동의할 수 없습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 그 점에 대해서는 충분히 제가 숙지하겠고요.
