<p><b>○ 경기개발연구원장 좌승희 </b> 그런 건 아닌데…….
</p>
<p><b>○ 김주삼 위원 </b> 그다음에 그래서 제가 마무리를 하면 이렇게 비정규직 문제, 업무추진비 사용문제, 이런 출판문제 이런 부분들이 저는 전체적으로 평소에 좌승희 원장님의 살아온 과정이나 견해, 어떤 대한민국의 보수주의자로서의 큰 어른으로서의 위치에 맞지 않는 그런 부분이 아닌가 그런 아쉬움이 들어서 말씀을 드렸습니다. 제가 시간이 많이 지나갔는데 죄송합니다. 이상으로 마치겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 감사합니다. 제가 조금만…….
</p>
<p><b>○ 김주삼 위원 </b> 말씀하세요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 말씀 좀 드리겠습니다. 업무추진비하고 관련해서 제가 와서부터 이렇게 돼 있어서 사실 제가 비교를 못했습니다. 오늘 지적해 주셔서 참 고마운데요. 제가 써보니까 아무리 써도 그렇게 쓸 수가 없어요. 그래서 이걸 줄이자고 몇 번이나 얘기한 적이 있는데 마침 김 위원님께서 그걸 지적해 주셔서 제가 추후에 개선할 수 있는 길을 찾겠고, 축의금 건은 제가 우리 사무처에서 분명 제가 모든 건에 대해서 검증을 받아서 하는데 그럼에도 불구하고 또 미흡한 점이 있었다고 하면 제가 그건 앞으로 시정을 해서 문제가 없도록 하겠고요. 
</p>
<p style="padding-left:1.2em">  비정규직 문제는 저 나름대로 저도 참 고민을 많이 했고 아까 지적도 했습니다만 우리 연구원 석사급 직원들이 너무나 2년 뒤에 자꾸 잘리는 문제가 안타까워서 제가 지난해에 정말 애를 써서 이걸 바꾸려고 했습니다만 행정원 문제에 대해서는 어떻게 보면 우리가 소홀했던 점도 없지 않아 있었다는 생각도 들고 그래서 검토를 잘해서 위법이 안 되도록 하고. 또 그렇다고 해서 연구하는 사람들과 너무 형평에 차이가 나서도 안 되고 다 같이 봐야 되기 때문에 그런 걸 감안해서 위원님 지적하신 대로 개선사항이 있으면 개선해 나가도록 노력을 하겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 감사합니다. 김주삼 위원님 수고하셨습니다. 다음 박용진 위원님 질의순서인데 잠깐 제가 좀 좌승희 원장님한테 부탁을 드리겠습니다. 
</p>
<p style="padding-left:1.2em">  저는 좌승희 원장님의 철학이나 가치 이런 것 개인적으로 존중합니다. 개인적으로도 존중하고 기획위원장 입장에서도 그 부분에 대해서 왈가불가할 수 없다고 생각합니다. 왜냐하면 가치니까. 그럼에도 불구하고 부탁을 드린다 그러면 저는 따뜻한 보스였으면 좋겠습니다. 그리고 상대방을 배려하는 보스였으면 좋겠습니다. 더더욱 약자를 항상 고민하는 보스였으면 좋겠습니다. 그런 의미에서 김주삼 위원님이 말씀하신 행정직의 정규직화, 비정규직의 정규직화 문제라든지 말씀하신 대로 원장님 입장에서는 당연히, 저도 동의합니다. 우리 연구원 석사급 분들이 2년마다 재계약하는 부분들 사실 그분들 입장에서는 상당히 신분상 불안하죠. 그런 부분들에 대해서 좀 더 적극적으로 관심을 갖고 좀 나름대로 대안을 가져주시기를 바랍니다. 
</p>
<p style="padding-left:1.2em">  동시에 책자, 제가 구체적으로 읽어보지는 않았지만 당연히 원장님 입장에서 ‘연구하는 원장’ 얼마나 좋아요. 그럼에도 불구하고 과연 어떤 적법성, 절차적으로 과정을 제대로 밟고 책을 발간했는지 이 부분에 대해서는 한번 마지막 날 제가 검토를 해본 다음에 얘기하겠지만 그런 부분에 문제가 있다 그러면, 하자가 있다 그러면 그것에 대해서는 원장 신분에 맞지 않다라는 겁니다. ‘연구하는 원장’ 좋죠. 그렇지만 절차와 적법성이라는 부분에서 제가 전제가, 한번 제가 오늘 자료를 받아서 고민해 보겠습니다. 그런 부분에 대해서는 다시 한 번 재고를 해주시기 바랍니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 그런데 제가 이 연구를 하면서 연구원 돈을 쓰지 않았습니다, 출판하는 비용만 썼지. 그 점은 제가 상당히 비용을 많이 절약한 셈입니다. 
</p>
<p><b>○ 위원장 강득구 </b> 연구하는 비용이랑 출판하는 비용, 당연히 연구는 개인의 문제기 때문에, 이게 프로젝트 사업이 아니잖아요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그러니까 제가…….
</p>
<p><b>○ 위원장 강득구 </b> 프로젝트 사업이 아닌데 그것을, 출판비용을…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 연구원 비용으로 썼다. 그거 위법 아닌가요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 연구원에 기여했다고 할 수도 있죠.
</p>
<p><b>○ 위원장 강득구 </b> 아니죠. 예를 들면 연구원에서 발간하는 모든 책자는 절차와 과정이라는 게 있잖아요. 원장님 말씀대로 ‘연구는 내가 개인 입장에서 했지만 출판은 연구원 비용으로 했다.’ 이게 맞는 건가요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런데 연구원 연구라고 저는 생각하고 했습니다만 저는 이 점에 대해서 제가 더 이상 얘기를 안 하겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 원장님, 제가 이게 적법한지, 적법하다면 근거가 뭔지 그것에 대해서 자료를 주세요. 알았죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 적법하다, 안 하다는 차원 문제가 아니고요. 
</p>
<p><b>○ 위원장 강득구 </b> 아니, 알겠습니다. 자료를 점심시간까지 제출해 주시기 바랍니다. 
</p>
<p style="padding-left:1.2em">  다음 박용진 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 박용진 위원 </b> 안양 출신 박용진입니다. 먼저 원장님께 지금 경기개발연구원이 가지고 있는 기금이 총 규모가 어떻게 되죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 262억입니다.
</p>
<p><b>○ 박용진 위원 </b> 지금 거의 보면 최근 계속 그 정도 규모가 이월이 되고 있는 걸로 파악되는데요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그렇습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그 정도 기금을 우리 경기개발연구원이 보유할 특별한 이유가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이 기금 운용상황을 보시면 알겠지만 여기에서 상당한 정도의 이자수입이 있기 때문에, 물론 연구사업에도 도움이 될 뿐만 아니라. 또 기금을 가지고 있다는 게 어떻게 보면 연구원의 자립도라든가 이런 것을 평가하는 그런 잣대로 보기도 하고 그래서 많은 연구원이 자체 기금을 가지고 독립하겠다고 하는 의지를 가지고 기금을 적립하고 있습니다. 그런데 그런 차원에서 저희도 하고 있는데 최근에 와서 위원님들도 그런 지적이 많고 아까 지적하신 대로 이게 의미가 별로 없지 않느냐 하는 지적도 있고 또 최근에는 도에서 예산이 충분치 못해서 연구에 제약이 많고 그래서 작년에 위원님들 허락을 받고 저희가 10억을 연구사업비로 원용을 했습니다. 금년에도 어떻게 보면 계획 중에 있습니다만 다소간에 기금을 전용을 하지 않으면 안 되지 않을까 하는 생각을 하는데 좌우간 이게 어떻게 쓰는 게 가장 유용한 방법인지는 참 고민을 좀 더 해야 되지 않을까 하는 생각을 하고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 지금 현재 향후 260억에 달하는 기금을 특별하게 운용할 계획이 현재로서는 확실치가 않다는 말씀이네요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 금융자산을 운용해서 일단 수익을 내서 쓰는 걸로 하고 있고요.
</p>
<p><b>○ 박용진 위원 </b> 금융자산을 운용하는 건 당연한 거고요. 그 기금을 향후에 경기개발연구원에 어떤 발전을, 어떤 목적으로 사용하실 것에 대한 구체적인 플랜이 없지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 저희가 고민한 끝에 대체적으로 생각하는 것은 저희 연구원이 지금 건물이, 사옥이 사실 마땅한 게 없습니다. 과거에 쓰던 건물도 아주 협소해서 이리로 이사를 왔는데 여기도 사실은 경기도인재개발원에서 우리가 임대를 해서 사용하고 있기 때문에 연구원들의 입장에서는 연구원이 자체 연구건물을 가지고 있는 게 반듯하지 않겠느냐는 그런 의견들도 많고 그래서 이 기금을 가능하면 저희 연구 사옥을 매입하거나 건설하는 데 쓰려고 계획을 하고 있고 도하고도 그런 방향에서 얘기를 진행해 오고 있지만 아직 충분히 결론을 얻지 못했습니다. 
</p>
<p><b>○ 박용진 위원 </b> 영리를 추구하지 않고 어떤 연구가 목적이고 또 하나 경기도의 어떤 비전을 제시하는 경기개발연구원에서 기금을 부동산 쪽에 투자해서 운용하겠다는 그런 계획을 밝히시면 우리 도민들이 보실 때 어떠하겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아, 부동산……. 그걸 또 그렇게 볼 수도 있군요. 저는…….
</p>
<p><b>○ 박용진 위원 </b> 그렇게 볼 수가 있는 게 아니라 경기개발연구원이 과연 이 큰 기금을 가지고 매년 이러한 어마어마한 기금이 이월되는데 여기에 대한 구체적인 계획도 안 가지고 계시고 또 거기에 대한 계획을 말씀하시는 게 연구원의 어떤 긍지를 위해서 건물을 매입하겠다. 이런 계획은 사실 우리 도민들이 받아들이기에는 굉장히 좀 어이없거나 황당하거나 그런 느낌이 들 수가 있거든요. 연구원의 목적에 맞게끔 이 기금을 어떤 목적으로 쓰겠다는 구체적인 계획이 전혀 없지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 보시기보다는 지금 우리가 금융 자산을 운용하는 것 자체가 기금의 운용에 적합한 방법이라고 생각합니다. 
</p>
<p><b>○ 박용진 위원 </b> 그건 당연히 여유자금이 있으니까 운용하는 것이고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게 하기 위해서 기금을 쌓는 것이죠, 사실은. 그 기금에서 나오는 수익이 연구기금으로 다 충당할 수 있으면 그만큼 연구원이, 말하자면 조금 독자적이고 객관적인 목소리를 내는 데 좀 더 낫지 않겠느냐 하는 게 연구하는 사람들의 생각입니다, 일반적으로. 그래서…….
</p>
<p><b>○ 박용진 위원 </b> 현재는 그만큼 독자적이지 않기 때문에 연구원이 연구하는 데 있어서 독립적이지 않다 그런 의미로도 해석 가능한가요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런 의미라고 말씀드리는 게 아니고…….
</p>
<p><b>○ 박용진 위원 </b> 방금 그렇게 말씀하셨지 않습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구원이 모든 기관이든 개인이든 남한테 기금을 받고 돈을 받아서 일을 하게 되면 그게 어떤 면에서는 제약을 받을 수 있기 때문에 연구원들이 정말 그런 어떤, 뭐라고 할까, 감이 없이 독자적으로 객관적인 연구를 하려고 하면 독립된 기금을 통해서 연구기금이 충분히 나오면 좋다고 이렇게들 생각을 하지요. 그런 목적으로 기금을 가지고 있는 것이고 그 기금을 통해서 수익을 많이 낼 수 있도록 노력해서 그것을 연구기금으로 자꾸 편입하는 것이 사실은 기금을 적절히 운용하는 길이 아닌가 하는 생각을 하는 것입니다. 그런데 그 점에 대해서도 충분히 위원님들도 그렇고 충분히 수긍을 못하시는 분도 계신 거 저도 알고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 일단 시간이 없으니까 짧게 마무리하겠는데요. 현재 그러니까 우리 경기도로부터 출연 받는 매년 예산 그런 것들이 자칫 우리 연구원들의 연구에 있어 가지고 어떤 독립성이나 독자성 이런 것을 조금이라도 훼손할 가능성은 좀 있네요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 뭐 가능성이 없다고 할 수도 있고 있을 수도 있지요. 그러나 전반적으로 보면 연구원이 독자적인 기금을 가지고 하는 경우하고 뭔가 좀 다를 수도 있다는 생각도 듭니다.
</p>
<p><b>○ 박용진 위원 </b> 네, 알겠습니다. 그러면 일단 우리 원장님 말씀은 현재 연구원이 독자적으로 목소리를 내기 위해서 기금을 확충하고 있고, 그렇지요? 그래서 그 이자로써 전체 충당이 된다면 어떤 다른 외부기관이나 도의 어떤 영향에 흔들리지 않고 독자적인 연구를 할 수 있다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런 의미라기보다 매년 도의 예산이 늘고 줄고 하는 것에 따라서 예산이 계속 영향을 받습니다. 
</p>
<p><b>○ 박용진 위원 </b> 네, 좋습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그러니까 그런 것을 벗어나기 위해서는 우리가 자체적인 기금을 가지고 거기서 수익을 가지고 연구를 할 수 있으면 좋다는 의미지 그것을 꼭 그렇게 해석하기는 좀 무리가 있지 않은가 하는 생각이 듭니다. 
</p>
<p><b>○ 박용진 위원 </b> 네, 알겠습니다. 그러면 기금을 효율적으로 운용하기 위해서 지금 특별회계를 운용하고 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 지금 특별회계가 총 몇 개가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 수탁용역사업특별회계가 있고요. 그다음에 기금회계가 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 기금회계가 경기과학기술센터특별회계 그것을 말하는 겁니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니에요. 지금 지적하신 기금하고 그다음 수탁용역사업특별회계라고 해서 우리가 외부로부터 받는 수탁사업을 관리하는 특별회계를 가지고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 제1권 405페이지에 보면 경기과학기술센터특별회계라고 나와 있는데 이것은 어떤 거지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그것은 경기과학기술진흥원이 독립하기 이전에, 작년 독립하기 이전까지 그 부서가, 진흥원이 저희 연구원 부서였습니다. 부서로 있다가 그것을 우리 내부에서 상당히 독립적인 기능을 할 수 있는 하나의 테마의 독립적인 그런 기구로 만들면서 그것을 특별기금으로 해 가지고 그 진흥원 운영 예산을 그렇게 운영했었습니다. 그런데 이게 독립돼서 나감으로써 그 기금은 폐쇄가 됐고요. 그 기관은 독립이 돼서 경기과학기술진흥원으로 지금 운영되고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그러면 이것은 어쨌든 우리 경기개발연구원 소속이 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아닙니다. 소속이 아니고…….
</p>
<p><b>○ 박용진 위원 </b> 전혀 틀립니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 전혀 틀리고요.
</p>
<p><b>○ 박용진 위원 </b> 관리 자체도 경기개발연구원에서 하는 게 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아닙니다. 지금 그것은 독립된 기관이고요. 바이오센터하고 통합되면서 과학기술진흥원으로 발족이 됐는데 경투실 산하하고, 아마 위원회도 경제투자위원회 산하로 지금 관리가 되고 있다고 알고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 독립된 시점이 언제입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 작년 5월 7일이라고 합니다. 
</p>
<p style="padding-left:2.4em">    (「올해.」라고 하는 관계직원 있음)
</p>
<p style="padding-left:1.2em">  아, 금년. 죄송합니다. 
</p>
<p><b>○ 박용진 위원 </b> 그러면 작년까지는 우리 경기개발연구원에서 전체적으로 관리를 하고 있었지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 
</p>
<p><b>○ 박용진 위원 </b> 질문을 드리겠습니다. 작년 2009년도 12월 말일 자 재무제표를 보면 우리 전체 유동자산 중에서 현금 및 현금성자산에 무려 153억이 예치가 돼 있습니다. 보통 우리가 이런 자산을 운영할 때 현금 및 현금성자산이라고 하는 것은 말 그대로 현금 또는 은행권에 있는 이자가 거의 없는 보통예금 이런 거지요? 왜 이렇게 과다하게, 대부분의 전체 당좌예산 155억 중에서 153억을 다 현금으로 갖고 있었는지 그 이유를 말씀해 주십시오. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 센터 예산에…….
</p>
<p><b>○ 위원장 강득구 </b> 원장님 답변하시기 힘들면 실무담당자가 답변해도 좋습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 기관이……. 지금 제가 오래된 일이라서 100% 자신은 없습니다만 그 기관이 과학기술지원자금을 운영하면서 그것을 기업이라든가 아니면 연구컨소시엄에 자금을 나눠주는 기능을 하기 때문에 아마 그런 이유로 현금자산을 보유하고 있었던 게 아닌가 하는 그런 생각이 듭니다만 그것은 좀 더 정확하게 파악해서…….
</p>
<p><b>○ 위원장 강득구 </b> 잠깐만요. 실무담당자가 누구죠? 어느 분이시지요? 
</p>
<p><b>○ 박용진 위원 </b> 이 작성책임자가 강윤구 부장님으로 돼 있네요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 그러면 담당부장님 증언대로 나오셔 갖고요…….
</p>
<p><b>○ 재정지원부장 강윤구 </b> 재정지원과의 강윤구 부장입니다. 지금 경기과학기술센터에서 담당자가 와 있습니다. 그 부분은 특별회계로 완전히 계리가 달리됐기 때문에 제가 취합해서 작성은 했습니다만 그 예치가 어떻게 돼 있는지 그 사항을 파악하지 못했습니다. 담당자가 직접 답변을 드리도록 하면 안 될까 생각합니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다. 제가 나머지를 확인 못해서.
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 경기과학기술진흥원 경영지원실장 민형기입니다. 153억이 작년 말 결산할 적에 재무상태에 현금 및 현금성자산으로 들어가 있는데요. 그 내역을 주석2에 416페이지를 보시면 저희가 정기예금이나 이런 것으로 들어가 있습니다. 그런데 이렇게 저희가 현금이 연말에 있던 원인은 저희가 과학기술센터에서 기업들한테 과제를 선정해서 지원해야 되는 업무가 있습니다, 협약을 해서. 그런데 그게 저희가 예년 예산을 연초에 받아서 4월부터 하다 보면 하반기로 넘어가서 이게 다음연도로 이월되는 사업이 있기 때문에 그런 자금이 연말에 12월 30일 현재에서는 현금을 많이 보유하고 있던 그런 사항이었습니다. 
</p>
<p><b>○ 박용진 위원 </b> 우리 증인께서는 자금운영을 직접 하셨습니까? 
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 이때는 과학기술센터 차원에서 했는데 저희가 과학기술진흥원에 통합되면서 제가 이 관리업무를 맡고 있기 때문에 오늘 제가 왔습니다. 
</p>
<p><b>○ 박용진 위원 </b> 보통 어떤 기업이라도 자금을 운영하는 데 있어 가지고는 단기ㆍ중기ㆍ장기로 나누어서 운영을 합니다. 그런데 설사 어떤 자금집행계획이 있다 하더라도 이게 단기적으로 가는 자금이 있고 장기적으로 가는 자금이 있는데 월말에, 연말에, 그것도 거의 99%에 달하는 그런 자금이 전체 보통예금통장에 들어가 있다는 것은 이것은 누가 봐도 이해를 할 수가 없습니다. 아까 좌승희 원장님께서 말씀하셨듯이 기금을 효율적으로 운영해서 이자수입으로 연구원들의 자립을 돕겠다, 과연 그런 취지와 이런 기금운영의 효율성이 전혀 없는 이런 운영이 매치가 된다고 생각하십니까? 
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 과학기술센터특별회계 부분에서 말씀을 해주신 것 같은데요. 사실은 저희가 맡고 나서는 보통예금에 들어가 있는 자산 때문에 말씀해 주시는 것 같은데요. 보통예금에 대한 것을 저희가 조금 운영효율을 높이기 위해서는 자금지출을 계획한 것에 의해서 저희가 재정운용을 하기는 해야 되는데 그 부분에서 그때 당시에 조금 과정에 있었던 것 아닌가 하는 그런 생각이 들고 있습니다. 그래서 지금 현재 상태에서는 저희가 1개월 단위로라도 보통예금에 그냥 넣지 않고 될 수 있으면 저희가 이자수익을 발생시키기 위해서 1개월 단위, 3개월 단위, 6개월 단위, 자금수요에 따라서 1년 단위 이렇게 저희가 지금 현재는 운영하고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 잠시만요. 제가 지금 계산기가 없어 가지고 제 휴대폰으로 계산하고 있습니다. 150억에 달하는 금액의 하루 이자가 어느 정도 될 것 같습니까? 만약에 정기예금으로 넣어놓으면. 
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 저도 계산을 바로 할 수는 없는데요. 지금 연이율이 최고 경우가 한 4%까지, 기관에서 정기예금으로 1년 단위 예치하는 경우 한 4%까지 예치이자율을 받고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그러면 일단 여기서는 정확한 답변이 안 나올 것 같으니까 자료요청을 하겠습니다. 
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 이 보통예금에 들어 있던 기금 최근 3년 동안 평잔을 제출해 주십시오. 평잔이 어떻게 운영되고 있는가 현황을 제출해 주십시오. 
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 네. 그것은 저희가 자료를 해……. 이게 과학기술센터가 경기개발연구원…….
</p>
<p><b>○ 박용진 위원 </b> 그러니까 1년 평상시에 보통예금으로 들어 있던 기간 그리고 정기예금으로 운용된 기간 그것을 자료로 제출해 주십시오. 
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 네. 그러니까 제가 말씀드리는 것은 과학기술특별부설기관이 2008년도에 부설기관으로 편입돼 있었습니다. 그래서 저희가 2010년 5월 6일 날 과학기술진흥원 출범하면서 저희가 진흥원에서 인수를 받아서 지금 운용을 하고 있습니다. 그래서 지금 말씀하신 대로 지금 현재의 월별로 평잔을 내서 자료를 드리겠습니다. 
</p>
<p><b>○ 박용진 위원 </b> 네. 
</p>
<p><b>○ 경기과학기술진흥원경영지원실장 민형기 </b> 시간관계상 다음 질문드리겠습니다. 경기개발연구원이 생긴 게 1995년이지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 그 당시에 경기도와 그다음 각 시군 그다음에 민간기관으로부터 출연받은 게 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 민간기관이 어디 어디지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잠깐만요. 제가 자료를 좀 찾…….
</p>
<p><b>○ 박용진 위원 </b> 제가 말씀드리겠습니다. 민간기관이 그 당시에 경기은행하고 제일은행 두 군데였습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 경기, 제일. 네.
</p>
<p><b>○ 박용진 위원 </b> 각각…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 10억씩 출연했습니다. 
</p>
<p><b>○ 박용진 위원 </b> 네. 그 당시 95년도에 각각 경기은행에서 10억 그다음에 제일은행에서 10억씩 출연을 했습니다. 당시 그 출연목적이, 저희가 자료를 받았지만 출연목적이 어떤 거였지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 연구원이 기본적으로 경기도정은 물론이고 시군의 연구수요를 충족하기 위해서 생긴 거기 때문에 그런 차원에서 각 시군이 조금씩이라도 참여를 했다고 보고 민간 쪽에서는 또 경기도 내에 있는 금융기관이기 때문에 이런 정신에 동참한다는 의미에서 기금을 출연한 것으로 알고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그 정신에 동참한 출연사유가 제가 받은 자료를 보면 “경기도 정책 연구개발사업의 지원과 지역사회 환원”으로 돼 있습니다. 그래서 10억씩을 출연했습니다. 그런데 경기은행이 지금은 없어지고 경기은행이 한미은행에 합병된 후에 지금은 씨티은행이 돼 있고 제일은행은 SC제일은행이 돼 있습니다. 현재 우리 경기개발연구원이 운용하는 자금 중에 상당부분이 씨티은행과 제일은행에 집중돼 있습니다. 또한 당연직이사 중에도 제일은행과 씨티은행 지점장이 매년 당연직이사로 들어가 있습니다. 이 연관관계를 어떻게 설명하실 수 있겠습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 두 분이 우리 이사로 들어온 것은 실질적으로 기금을 기여했기 때문에 이사로 모신 것이고요. 그다음에 예금을 거기에 많이 했다는 것은 특별히 그런 연관관계 때문이기보다 이율을 항상 관심을 가지고 보면서 만일 그런 데에서 요청이 오거나 그래도 특정한 최고이율을 보장해 주지 않으면 저희가 예치를 안 합니다. 그래서 제가 분명히 말씀드릴 수 있는 것은 어떤 그런 연관관계 때문에 여기에 예치를 많이 했다고는…….
</p>
<p><b>○ 박용진 위원 </b> 원장님!
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 최고이율을 보장해 주는데 올해 작년의 일반회계 결산을 보면 총자산 당좌자산 42억 중에 33억은 씨티은행 보통예금에 들어가 있었어요. 이게 최고이율을 보장해 주는 은행에 예치한 겁니까? 
</p>
