<p><b>○ 김현삼 위원 </b> 최근에 대통령령으로, 가장 최근에 대통령령으로, 일종의 지방의회 의원 윤리강령 비슷한 게 대통령령으로 발표된 게 있어요. 그 내용을 보게 되면 의회 의원들 같은 경우에 하다못해 어떤 단체가 추진하는 세미나나 토론회에 참석해서 5만 원이 됐건 10만 원이 됐건 세미나 토론비를 받게 되는 경우에도 사전에 의회 의장한테 보고하도록 돼 있습니다. 그래서 그것을 지키지 않으면 대통령령을 위반한 것으로 해서 조사를 받도록 돼 있는 대통령령이 가장 최근에 발표된 적이 있어요. 그런 것처럼 공무원들의 복무규정 관련한 우리 사회 전체적인 분위기가 강화되고 있는 마당에 경기개발연구원 연구원이 연구원 이외의 다른 곳에서 수익을 창출한다, 창출하고 있다. 그리고 그것에 대해서 경기개발연구원이 별도의 규제를 하고 있지 않다. 이거 문제 아닙니까? 더군다나 자료에 보면 근무시간 중에도 있단 말이에요. 이건 심각한 모럴 해저드 아닌가요?
