<p><b>○ 경기개발연구원장 좌승희 </b> 위원님께서 지적하시는 취지는 제가 충분히 이해가 됩니다. 그런데 그동안 저희 인사관리제도에 의해서 그게 허용이 됐고 허용된 배경은 제가 생각하기에는 이게 무슨 수익을 위해서 강의를 한다기보다 강사료도 미미할 뿐만 아니라 연구의 연장선상에서 이렇게 해서…….
</p>
<p><b>○ 김현삼 위원 </b> 잠깐만요. 좌승희 원장님 관점에 상당한 문제가 있는데 두 가지를 지적을 하겠습니다. 첫 번째는 “얼마 되지 않는 금액이다.” 말씀을 하셨는데 여기 보면 6개월 사이에 150만 원, 200만 원 이렇게 수익이 발생한 연구원도 있어요. 그게 적은 금액인가요? 적은 금액 아닌 거죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그게 적다, 많다 하는 그런 차원이 아니라요. 제가 지금 드리고자 하는 말씀은…….
</p>
<p><b>○ 김현삼 위원 </b> 적은 건 아니죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 물론입니다. 제가 드리고자 하는 말씀은 아까 위원님들에 대한 코드 오브 콘덕트(code of conduct)에 대해서도 제가 충분히 이해가 되고요. 그런데 학계의 일반적인 관행이 또 있습니다. 이건 저는 모든 사회가 다 그렇게 가면 저도 과감하게 할 수 있는데 원칙에 제가 대부분 동의를 하지만 그동안 저희 연구원의 오래된 규정이 그렇게 돼 있고 모든…….
</p>
<p><b>○ 김현삼 위원 </b> 알겠습니다. 연구원의 오래된 관행이 그런 거라고 하니까…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 저도 그거를, 이건 또 다른 차원에서 얘기하면 우리 연구원 박사들이 나가서 보다 많이 활동하는 것이 그 연구원의 생각을 알리고 연구원의 위상도 높일 수 있고 여러 가지 자극도 되기 때문에 막지 말아야 된다는 차원에서 제가…….
</p>
<p><b>○ 김현삼 위원 </b> 맞습니다. 그러니까 제가 말씀드리려고 하는 건 뭐냐 하면 경기개발연구원에 소속된 연구원들이 외부기관에 나가서 여러 가지 형태의 활동을 하는 것에 대해서는 그건 좋은 현상이라고 생각합니다. 그런데 그 결과로 수입이 발생이 되잖아요. 그렇지 않습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 알겠습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그 결과로 발생되는 수입에 대해서는 이를테면 경기개발연구원에서 정규직으로 등록돼서 활동의 성과물로 급여를 받는데 별도의 수입이 창출되는 부분에 대해서는 경기개발연구원 내부에서 이와 관련된 엄격한 자체 복무규정이 준비될 필요가 있다. 마련될 필요가 있다라는 것을 제가 지적하려고 하는 겁니다. 어떻게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 점에 대해서는 저도 수긍합니다. 그런데 제도를 만드는 것 자체가…….
</p>
<p><b>○ 김현삼 위원 </b> 더군다나 제가 자꾸 중언합니다만 연구시간에, 그러니까 정식 근무시간에 나가서 강의를 한 연구원 분들도 다수가 있더라고요. 최소한 그런 경우는 피해야 되지 않겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그분들의 경우에는 그분들이 가지고 있는 연가라든가 휴가 날짜를 다 감안해서 허용을 하기 때문에 그런, 말하자면 왜 연구원 공식 일하는 시간을 썼느냐는 것은 사실은 여기서 다 해결이 될 수 있는데요.
</p>
<p><b>○ 김현삼 위원 </b> 제가 요청하도록 하겠습니다. 우리 경기개발연구원도 이를테면 공무원에 준하는 복무규정을 가질 필요가 있는 거죠, 맞죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 그래서 지금까지의 그것이 설령 관행이었다 하더라도 공무원 또는 준공무원에 달하는 복무규정이 강화되고 있는 추세를 반영해서 경기개발연구원이 외부강연료 등 수익에 따른 그런 것들이 발생했을 때 어떻게 조치를 취할 것인지에 대해서 우리 좌승희 원장, 지금까지는 설령 그것이 관행이었다 하더라도 그 개선방안에 대해서 한번 내부적으로 검토를 해보실 것을 부탁을 드리겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 저희가, 부원장이 이걸 관리를 쭉 해왔기 때문에 보충설명을 조금 드릴 수 있으면 좋겠다고 생각하는데 어떻습니까? 
</p>
<p><b>○ 김현삼 위원 </b> 제가 시간이 없어서…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 한 말씀만 드리면 이게 국민권익위원회에서 권고한 규정과 다 일관성 있게 저희가 계속 이것을 업데이트하고 해나가는데 아직까지는 그쪽에서도 이 문제에 대해서 공개적으로 문제 지적은 아직 없었던 걸로 알고 있습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 제가 다른 질문을 하려고 했는데…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 그런데 충분히 김 위원님의 취지는 알겠습니다.
</p>
<p><b>○ 김현삼 위원 </b> 또 말씀하시니까 제가 말씀하도록 하겠습니다. 국민권익위에서 그렇게 하지 말라고 이를테면 대통령령이 만들어졌다니까요. 만들어진 것을 제가 근거로 얘기하는 거예요. 그러니까 조응래 부원장님, 대답을 한번 해보세요. 
</p>
<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 저희는 임직원 행동강령 시행규칙이라고 해 가지고요. 대외활동에 있어서도 두 가지 종류로 나누고 있습니다. 그래서 대외활동 중에서 강의를 나가는 부분에 대해서는 한 번 나갈 때마다 0.5일 정도의 연가에서 그걸 빼도록 돼 있습니다. 그래서 그 시간이라든지 이런 부분들에 대해서는 다 정리를 하고 있고요. 대외활동과 관련해서 무슨 세미나 참석 발표라든지 토론 이 부분에 대해서는 대외활동 신청을 하도록 돼 있고 거기서부터 받는 금액이 어느 정도인지를 다 신고하도록 돼 있습니다. 그것이 국민권익위원회 같은 데서 그동안 절차적으로 얘기를 했던 그런 부분들이 되겠습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 네. 잘 알겠습니다. 그런데 제가 지금 말씀드리려고 하는 것은 뭐냐 하면 세미나나 토론회 이런 일회성 참석이 아니고 지속적으로 6개월 또는 1년, 2년 단위 외부강연을 나가는 경우들이 많이 있더라고요, 대학교에. 그래서 수입이 고정적으로 발생되는 경우가 많이 있습니다. 그래서 그런 부분에 대해서 경기개발연구원 내부에서 공무원 또는 준공무원에 준하는 그런 복무규정을 다시 한 번 검토해 주실 것을 부탁을 드리겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 충분히 취지에 대해서 공감합니다.
</p>
<p><b>○ 김현삼 위원 </b> 제가 오후에 질문을 드리도록 하고 한 가지만 더 질문하도록 하겠습니다. 얼마 전에 “GTX 빨대효과 없다.”라고 하는 외부 연구논문 발표하신 적 있으시죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 그 용역비가 얼마였습니까? 허재완 중앙대 교수가…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 50만 원이 용역비라고…….
</p>
<p><b>○ 김현삼 위원 </b> 얼마요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 50만 원이요. 원고료입니다.
</p>
<p><b>○ 김현삼 위원 </b> 원고료 50만 원으로 해서 “GTX 빨대효과가 없다.” 이렇게 발표하셨는데 저는 경기개발연구원이 갖고 있는 대내외적 위상에 비춰봤을 때 이런 연구논문은 안 하는 게 낫다 이런 생각을 갖고 있습니다. 이게 50만 원……. 제가 어떤 느낌을 갖냐 하면 GTX 관련해서 경기도의회 내에서 갑론을박이 있습니다. 갑론을박이 있는데 경기개발연구원이 성급하게 빨대효과가 없다라고 하는 것을 논리적으로 증명하기 위해서 허재완 교수한테 부탁을 한 것 아닌가 제가 그렇게 생각을 갖고 있는데 제가 자료를 보니까 결론을 도출하기 위한 아무런 자료조사나 어떤 분석이나 이런 게 없어요. 그래서 제 생각에는 이건 거의 칼럼수준, 칼럼수준을 크게 벗어나지 못하는 그런 연구발표였다 이렇게 보여지는데 좌승희 원장, 혹시 그 논문 보신 적 있나요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네?
</p>
<p><b>○ 김현삼 위원 </b> 그 논문을 보신 적 있으십니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 봤어요.
</p>
<p><b>○ 김현삼 위원 </b> 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그분이 우리 포럼에 와서 발표했던 내용이고 무슨 50만 원짜리 원고니까 요즘 그렇게 썩 50만 원이 학계에서는 별로 뭐하지 못합니다. 그 내용 자체도 말씀하신, 지적하신 그런 측면이 없지 않아 있다고 보는데요. 저는 어떻게 봤냐 하면 이게…….
</p>
<p><b>○ 김현삼 위원 </b> 아니, 본 위원이 주장하고 싶은 건 뭐냐 하면 GTX 빨대효과가 있을 수도 있고 없을 수도 있는데 이를테면 경기개발연구원 이름으로 어떤 논문을 발표할 때는 논문의 발표에 따른 충분한 근거자료가 제시가 되고 충분한 연구수행이 된 그런 결과로 발표가 돼야 되는데 제가 보니까, 죄송한 표현입니다만 이를테면 저라도 2~3일이면 쓰겠다 이런 생각이 제가 들었어요. 그래서 이게 50만 원, 50만 원이라고 하는 금액으로 빨대효과가 없다라고 하는 것을 이를테면 경기개발연구원 이름으로 대외적으로 홍보하기 위해서 급조된 그런 연구다 이런 느낌을 받았거든요. 이런 식의 연구결과, 이런 식의 연구관행은 없어야 되는 것 아니냐 이런 말씀을 드리고 싶은 거거든요. 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 김 위원님 말씀하신 그런 취지라면 정말 그렇게 하면 안 되겠죠. 저도 동감인데요. 이번 연구…….
</p>
<p><b>○ 김현삼 위원 </b> 50만 원짜리 연구용역이 그동안 있었습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 50만 원……. 그냥 주요 CEO REPORT라든가 이런 건 전부 다 50만 원짜리입니다, 외부에 하는 게.
</p>
<p><b>○ 김현삼 위원 </b> 아니, 그런데 이것이 하나의 독립된 자료로 발표가 됐더라고요. 하나의 책자로.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 포럼 때 했기 때문에 포럼자료로 나온 거죠. 나중에 그걸 우리가 필요하면 CEO REPORT로 쓰고 하는데 제가 이 사안은 이런 생각이 들었습니다. 학계에서 지금 무슨 논쟁이 있냐면 KTX 갖고 논쟁이 많아요. 지방하고 수도권의 문제인데. KTX가 생김으로써 지방이 전부 다 서울로 돼 가지고 수도권 주위의…….
</p>
<p><b>○ 김현삼 위원 </b> 죄송합니다. 말씀 중에 죄송한데 제가 지금 드리려고 하는 말씀의 핵심적인 내용은 뭐냐 하면 GTX 빨대효과 그 자체에 대한 논쟁을 하려고 하는 게 아니고 GTX 빨대효과가 없다라고 하는 것의 연구결과를 도출하려면 상당한 정도의 연구가 있어야 되고 해야 될 텐데 그 내용을 보니까 이건 뭐 칼럼 수준의 글이더라고요. 그래서 경기개발연구원이 GTX 빨대효과가 없다라고 하는 것을 증명해 보이기 위해서 급조한 그런 느낌이 드는 연구결과가 아니냐 이런 느낌이 드는 거죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 앞으로 그런……. 뭐라고 할까요…….
</p>
<p><b>○ 김현삼 위원 </b> 그래서 결과적으로 제가 오후에 다시 추가질문을 통해서 제 종합적인 결론을 내리겠습니다만 이를테면 경기도지사가 갖고 있는 생각들, 심지어는 “경기개발연구원이 김문수 경기도지사의 대권용 싱크탱크 아니냐?” 이런 일부의 평가도 있는 거죠. 그런 평가 들어보셨죠? 그런 평가가 있다는 거는 들어보셨죠? 주장이 있다라고 하는 것은 들어보셨잖아요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 낭설 못지않게 이렇게 돌아다니는 얘기는 듣고 있습니다.
</p>
<p><b>○ 김현삼 위원 </b> 낭설이든 뭐든 그런 얘기를 들어보셨죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 김현삼 위원 </b> 그래서 저는 ‘경기개발연구원이 김문수 지사의 정책을 거의 무비판적으로 옹호하기 위해서 경기개발연구원을 활용하고 있는 것 아니냐?’라고 하는 생각을 갖고 있고 대표적인 연구결과가 “GTX 빨대효과 없다.”라고 하는 50만 원짜리 연구논문이다 이런 생각을 갖는 거죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런 오해가 없도록 앞으로 저희가 특별히 주의를 하도록 하겠습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 본 위원이 시간이 없기 때문에…….
</p>
<p><b>○ 위원장 강득구 </b> 마무리 발언 해주시고요.
</p>
<p><b>○ 김현삼 위원 </b> 네. 이 정도에서 정리를 하고 오후에 다시 본 위원 추가질의를 통해서 더 질문드리도록 하겠습니다. 이상입니다.
</p>
<p><b>○ 위원장 강득구 </b> 김현삼 위원님 수고하셨습니다. 다음 임병택 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 임병택 위원 </b> 시흥 출신 임병택 위원입니다. 원장님, 우리 경기개발연구원의 설립목적이 무엇인지 알고 계십니까? 짧게 좀 얘기해 주세요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 경기도정을 뒷받침해서, 더 나아가면 경기도민의 복지 향상에 기여하는 게 제일 중요한 첫 번째 기능이라고 봅니다. 물론 그다음에 그것을 하기 위해서는 필요한 국가정책에 대한 대안도 내고 하는 것도 필요하겠고요.
</p>
<p><b>○ 임병택 위원 </b> 김문수 지사님의 싱크탱크라는, 세간의 낭설이라고 말씀하셨는데요. 그러한 평가에 대한 원장님의 소견은 어떠십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 별로 옳지 않다고 생각합니다. 지사님의 관심사항에 대해서 저희가 생각을 바로잡고 입장을 정할 수 있도록 경기도민의 입장에서 의견을 내고 이렇게 하는 건 합니다만 그렇다고 해서 경기지사의 수요를 충족하는 것이 꼭 대권하고 관련돼 있다고 관련짓기는 어렵지 않을까 하는 생각이 들고. 
</p>
<p><b>○ 임병택 위원 </b> 지난 저희 제5대……. 저희 경기도의회 첫 업무보고 시에 많은 위원님들이 경기개발연구원의 정치적 중립성과 도민의 삶의 질 향상을 위한 연구활동에 저희 연구원님들이 전념하실 수 있도록 원장님께서는 특별히 연구원들에게 정치적 주문을 말아 주십사, 그리고 또 경기개발연구원이 지켜 주십사라고 많은 위원님들이 그런 부탁의 말씀을 하셨습니다. 그럼에도 불구하고 전혀 달라지지 않았기 때문에 제가 지금부터 질문을 시작하려고 합니다. 
</p>
<p style="padding-left:1.2em">  이것은 저희 경기개발연구원의 연구원님들, 박사님들, 학자님들의 자존심과도 결부된 문제기 때문에 분명하게 답변해 주세요. 우리 원장님께서 솔선수범을 하셔야 됩니다. 그런데 저에게 주신 행정사무감사 요구자료 2권 975페이지를 보시면, 975페이지입니다. 14번 매경이코노미, 연구원 소개 및 원장 인터뷰 기획기사 1,350만 원이 지출됐습니다. 그렇죠? 경기개발연구원을 위한 광고죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 광고기사죠. 그 기사내용 검토해 보셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 검토했습니다만 인터뷰 내용하고는 조금 과장된 게 있다고 느꼈습니다. 
</p>
<p><b>○ 임병택 위원 </b> 1,350만 원이라는 광고비를 들이고 인터뷰를 하셨습니다. 광고예요. 단순한 기사가 아니고요, 광고. 광고기사입니다. 그렇게 된다면 당연히 우리 광고주가 검수를 하셔야죠. 이런 내용은 우리의 광고 목적에 어울리지 않기 때문에 빼 달라. 지금 그 내용이 뭐냐 하면 제목 자체가 “김문수 경기도지사 싱크탱크로 떠오른 경기개발연구원”, 9월 달에 이 기사가 나갔어요. “경기도지사 싱크탱크로 떠오른 경기개발연구원”. 그리고 후속되는 원장님의 인터뷰에 보시면 기자가 그렇게 묻습니다. “경기개발연구원이 김문수 지사의 싱크탱크로 각광을 받는 만큼 경기개발연구원 원장인 좌 원장과 김 지사 둘 사이의 스토리도 큰 관심의 대상이 되고 있습니다.” 여기에 대해서 원장님 가타부타 말씀이 없으시고 쭉 이야기를 하십니다. 원장님 스스로가, 저희 기획위원회 위원님들 첫 업무보고 자리에서 그렇게 신신당부를 드렸습니다. 경기개발연구원 설립목적에 맞게 정치적 중립성, 김문수 지사의 싱크탱크라는 오명, 원장님이 지켜 주십사라고 부탁을 드렸어요. 그럼에도 불구하고 1,350만 원이라는 세금을 들여서 광고를 하시면서 싱크탱크라는 게 마치 자랑스럽다는 양 이렇게 광고하는 이게 지금 상식적으로 이해가 되십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 지사의 싱크탱크라고 하는 것하고 지사의 정치적인 목적을 위한 싱크탱크라는 건 다르게 해석했습니다. 저희가 얘기하는 것은 경기도를 이끌어가는 도지사로서의, 소위 말하자면 경기도정을 뒷받침하는 싱크탱크라는 개념으로 이해를 해주시면 좋지 않을까 하는 생각…….
</p>
<p><b>○ 임병택 위원 </b> 이게 1,300만 원 광고를 들여서 우리가 돈을 주고 기사를 쓰게끔 한 거예요. 기자들이 와서 취재를 해간 게 아니고 우리가 광고를 한 겁니다. 안 그렇습니까? 1,350만 원의 광고를 한 거예요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은…….
</p>
<p><b>○ 임병택 위원 </b> 광고주의 허락 없이 이런 광고가 나가는, 이게 말이 됩니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 어쨌든 저는 싱크탱크라는 콘셉트가 과거에 모든 지사 시절에 다 그렇게 했다고 봐요. 그리고 도정이라는 게 결국은 지사의 생각을 가지고 이끌어가는 거기 때문에 그런 의미에서는 언론이나 이런 데서는 이게 경기도의 싱크탱크고 나아가면 도지사의 싱크탱크고 더 나아가면 의원님들의 싱크탱크라고도 할 수 있다고 봐요. 이것을 무슨 정치…….
</p>
<p><b>○ 임병택 위원 </b> 대권 이야기까지 나와 있기 때문에 그렇습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런 것이 아까 제가 말씀드린 대로 과도한 표현을…….
</p>
<p><b>○ 임병택 위원 </b> 그렇습니다. 왜, 대권 이야기가 나와 있어서 그래요, 대통령 후보. 이것은 저희 경기개발연구원 설립목적에도 맞지 않고요. 만약에 연구원들이 그런 정치적 편향성을 가지고 일을 하시면 당연히 해촉하시겠죠? 원장님, 특별히 주의를 하셔야 됩니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 그런 오해가 없도록…….
</p>
<p><b>○ 임병택 위원 </b> 아울러서 하나 더 여쭙겠습니다. 원장님, 이 인터뷰를 보시면 선임연구원……. 아, 초빙연구원들을 초빙해서 우리 경기개발연구원에 새로운 바람을 불러일으켰다라고 말씀하시죠? 그렇게 돼 있습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 일부…….
</p>
<p><b>○ 임병택 위원 </b> 초빙연구원. 연구원 활동을 위해서, 우리 경기도민의 삶의 질 향상을 위해서 연구하셔야 되는 초빙연구원. 그런데 어떤 분들이 초빙연구원으로 오고 가고 계시는지 아십니까, 원장님? 아시겠죠. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 압니다.
</p>
<p><b>○ 임병택 위원 </b> 김문수 지사님 최측근들이라고 불리는 분들이 와서 일하고 계세요. 한 달에 290만 원, 390만 원입니까? 한 달에.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 직급에 따라 다를 수 있습니다.
</p>
<p><b>○ 임병택 위원 </b> 직급에 따라 다르겠지만 안병도 초빙연구원님 그다음에 배진석 초빙연구원님, 맞죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 그리고 또 계세요. 이분들은, 특히 제가 왜 이 문제를 지적하냐 하면 단순히 이분들에게 월급만 주시는 게 아니에요. 안병도 회사는, 여론전문가라고 알려져 계시고 소위 말하는 지사님의 10인방 중의 한 명으로 세간에 알려져 있습니다. 그리고 현재 한나라당 당협위원장이에요. 지구당 위원장, 옛말로. 이분이 92년도에 한나라당 부천 오정구 당협위원장으로 한나라당에서 임명이 되셨어요. 그럼에도 불구하고 2010년 1월부터 다시 재계약이 됩니다, 석 달 동안. 초빙연구원의 신분으로 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이분이 그런 정치적인 자리를 가짐으로써 그 즉시 계약을 해약하도록 그렇게 했습니다. 
</p>
<p><b>○ 임병택 위원 </b> 아니, 2009년도 12월 달에 당협위원장이 되셨어요. 그런데 2010년 1월 달에 다시 재계약이 됩니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 3개월이 겹쳤다고 지금 제가 보고를 들었습니다. 그  점에 대해서는……. 저희가 아까 말씀하신 건 제가 충분히 이해를 하는데요, 어떤 취지의 말씀인지. 그런데 저희가 사람을 쓸 때는 항상 어떤 경우에도 그 사람이 연구원에서 할 일이 뭐냐, 연구원에 기여를 할 수 있느냐, 없느냐 하는 건 제가 제일 먼저 따지는 선발기준이기 때문에 아까 말씀하신 사람들도 그 나름대로의 연구원에 기여를 했고요. 위치가 약간 정치적인 포지션으로 가거나 그러면 이것은 연구원에 안 맞다고 해서 저희가 바로 조치를 했는데…….
</p>
<p><b>○ 임병택 위원 </b> 안병도 연구원께서 2008년도 9월부터 초빙연구원으로 계시면서 주요 연구실적이 경기도의 남북한 간 인도적 협력 방안 그리고 정치권 지방행정체제 개편안, 공공기관 고객만족도 조사 이런, 주요 연구실적이라고 합니다. 나중에 제가 자료를 요구할 텐데. 그런데 이분이, 또 저에게 주신 자료 여론조사 실시현황, 979페이지를 보시면 이분이 담당 박사로서 2008년도에, 6번은 리얼미터라는 대행업체에 했어요. 그런데 2009년도에 1번과 3번을 보시면 21세기리서치라는 대행업체를 통해서 1,400만 원 그리고 또 1,800만 원 두 가지 여론조사를 합니다. 안병도 초빙연구원과 21세기리서치 간의 관계를 아십니까? 안병도 초빙연구원이 사장이었어요, 21세기리서치. 자기가 우리 경기도민의 세금으로 우리 경기개발연구원 초빙연구원으로 와서 월급도 받으시면서 자기 회사에 이러한 여론조사까지도 발주를 합니다. 
