<p><b>○ 정재영 위원 </b> 성남 분당 출신의 정재영 위원입니다. 큰 틀에서 원론적인 것 한 두 가지만 질의를 하겠습니다. 대한민국을 움직이는 중심 브레인, 비전을 가지시고 경기개발연구원이 95년도 개원을 했습니다. 따라서 경기도에 대한 도정은 물론이고 각 분야에 대해서 여러 가지 장기적, 단기적인 연구보고서를 많이 작성해서 우리 경기도뿐만 아니라 대한민국의 싱크탱크 역할을 잘해 주고 있다고 저는 판단을 하고 있습니다. 특히 저희 위원들한테 감사하게 생각하는 것은 전에는 그런 일이 없었는데 요 근래에 CEO REPORT라든지 또 여러 가지 정책과제 연구보고서를 의원들한테 보내 주시니까 그것을 보고 굉장히 우리가 의정활동하는 데 도움이 많이 돼서 정말 경기개발연구원이 새로운 아이디어를 내서 잘해 주고 있다는 데 감사의 생각을 갖고 있었습니다. 
</p>
<p style="padding-left:1.2em">  큰 틀에서 질문을 하겠습니다. 지금 여러 위원님들이 보시기에도 그렇고 방금 전에도 존경하는 다른 위원님들께서 말씀 주셨는데 여러 가지 연구하는 과제가, 보고서가 김문수 도지사 입맛에 맞는 연구보고서만 만든다. 그리고 또 경기도가 정해 주는 방향을, 정해 주는 것에 대해서만 맞게끔 보고서를 만들어낸다 이런 부정적인 시각이 굉장히 많이 있습니다. 사실이 그렇습니까?
