<p><b>○ 경기개발연구원장 좌승희 </b> 크게 보면 수도권정책 문제와 관련해서 수도권규제 완화정책에 저희가 적극적으로 동참했고 그다음에 지방분권 문제에 대해서 저희가 적극적으로 선도를 했다고 생각합니다. 그래서 도 폐지 문제를 저희가 나서서 막는 데 기여를 했고 그다음에 도시ㆍ지역계획 분야에서는 그동안 경기도가 경기도 자체의 계획을 가질 수가 없었는데 저희가 그것을 계속 문제제기를 함으로써, 물론 지사님도 같이 목소리를 내셨습니다만 새롭게 우리가 2020 도 종합계획을 만들 수 있게 돼서 이번에 작업을 하고 있고요. 이런 게 어떻게 보면 큰 틀에서 연구원이 도정을 뒷받침할 뿐만 아니라 끌고 가는 모습이 아닌가 하는 생각을 합니다만 위원님들의 생각은 어떠실지 잘 모르겠습니다.
