<p><b>○ 경기개발연구원장 좌승희 </b> 계속해서, 아까 신 박사가 세 사람이라고 그랬지만 사실은 자치행정연구부라고 더 인원이 많은 부서가 있습니다. 그 부서가 사실은 의회 의정에 대한 얘기를 다 할 수 있고 또 해야 되는 그런 책임도 있고 그래서 제가 의정연구센터를 따로 깃발을 들기는 했지만 자치행정연구부가 의정을 다 지원하는 그런 역할을 하는 부서이고 그래서 저는 인력은 일만 있으면 충분히 할 수 있다고 봐요. 그리고 일부 박사들은 겸임발령을 통해 가지고 의정연구센터에서도 일도 하고 있고 그래서 그렇게 합니다만 그래도 인력이 충분치 않으면 저희가 계속해서 충원을 해서 하려고 계획을 하고 있습니다. 
