<p><b>○ 장호철 위원 </b> 아까 본 위원이 질의드린 게 LNG가스 포함해서, 왜 그랬냐면 원전은 지역주민들한테 학자금을 무료로 준다든가 이런 게 있어요. 그것을 좀 자세히 파악해야 되지만 우리 평택지역은 지원특별법으로 인해서 국비지원하고 도비 좀 주시는 것뿐이 없고 거기에 대한 복지 내지는 여러 가지 전반에 걸쳐서, 교육 문제라든가 지원을 특별히 받는 게 별로 없습니다. 그래서 이런 부분을 싱크탱크인 우리 경기개발연구원에서 대한민국 자체가 평택 이쪽의 분들이 우리 국가를 위해서 주민의 희생을 강요만 하는 게 아니라 이제는 수혜를 줄 수 있는 그런 연구를 하나 정책건의를 드리겠습니다. 
