<p style="padding-left:1.2em">  원장님께 여쭙겠습니다. 원장님은 언론에 나오는 걸 보면 “우리나라의 대표적인 보수경제학자다.” 이렇게 앞에 수식어가 붙는 경우가 많이 있습니다. 원장님이 원하셨든 아니셨든 그렇게 네이밍이 돼 있는 건 사실인 것 같습니다. 또 한국경제연구소장도 하신 것 이런 것도 작용하시는 것 같고요. 그런데 저는 평소에 이렇게 생각합니다. 전문가 분들의 한마디나 논문이 권위를 가지고 있기 때문에 여론을 형성하는 데 중요한 소재로 활용된다고 생각합니다. 그래서 그만큼 전문가 분들의 생각이나 이야기가 책임이 뒤따른다 이런 생각을 합니다. 그런 관점에서 경기개발원의 업무에 대해서 큰 틀에서 여쭤보고 싶습니다. 전문가들이라고 하면 대부분이 다 박사님들이시고 그러시니까요. 필요할 때마다 자료와 이론을 꺼내 쓸 수 있는 큰 파일박스와 같다 전 이런 생각을 좀 합니다. 많이 알고 계시니까요. 그런데 현안에 대해서 보면 전문가 분들도 왜 같은 현안에 대해서 의견이 다르고 갑론을박이 있습니까? 저는 그게 항상 의문이 있었습니다. 왜 그렇습니까? 원장님.
