<p><b>○ 경기개발연구원장 좌승희 </b> 어려운 질문이신데요. 저도 별로 아는 건 없지만 과학마저도, 최근에 제가 발견한 바에 의하면 세상을 보는 관점이라고 그러지요? 이게 하나의 세계관이라고 얘기할 수도 있고 이걸 좋게 얘기하면 이념이라고도 얘기합니다만 과학마저도 그런 배경을 다 가지고 있습니다. 그러니까 과학이라고 해서 다 진리라고 얘기하기에는 아직도 우리가 아는 것이 제한적이고 더구나 사회과학이나 이런 쪽은 또 더 그런 문제가 심각하기 때문에 전문가라고 하는 사람들의 의견이 다를 수밖에 없고요. 또 그게 어떻게 보면 당연한 게 아닌가 하는 생각이 들어서 그런 생각을 해봅니다. 
