<p><b>○ 권칠승 위원 </b> 그래서 보통 일반인들도 전문가들이 해놓은 말씀이나 이런 것들을 인용해서 이야기하기를 좋아하는 것 같습니다. 말싸움할 때도요. 대표적인 예가 우리나라가 유엔이 정한 물부족 국가다 이런 말이 있는데 전혀 근거가 없는 말이거든요, 이게. 누가 한 말인지조차도 전혀 규명이 안 되고 있는데 유엔이 했다고 하고 또 언론들이 좀 인용을 하니까 이게 권위를 가지면서 완전히 사실인 걸로 굳어져 있습니다. 그만큼 전문가들이 하시는 말씀이 중요하다라는 뜻입니다. 
