<p style="padding-left:1.2em">  얼마 전에 제가 주간지에서 봤는데요. 이동거리 100㎞당 사망자가 철도는 9명이고 비행기는 3명이랍니다. 그래서 비행기가 훨씬 안전한 교통수단으로 판단이 되는데요. 승객이 탑승한 1억 시간당 사망자는 철도가 7명이고 비행기가 24명이랍니다. 어떤 재료를, 어떤 데이터를 내놓느냐에 따라서 결론을 완전히 바꿀 수가 있습니다. 정말로 가치관이 다르고 이념이 다르다면 그것은 별개문제지만 이런 부분들도 있을 수 있다는 겁니다. 대부분의 학자 분들은 양심에 따라서 하시니까 사실 대부분의 이슈에 대해서는 이런 일이 있을 수가 없지요. 정말 양심에 따라서 하지만 정치적으로 좀 민감한 부분들에 대해서는 일반 사람들도 문제제기를 해볼 만한, 의혹을 가질 만한 부분들이 있을 것 같습니다. 그래서 그 부분에 대해서 좀 말씀을 드리고자 합니다. 
</p>
<p style="padding-left:1.2em">  정운찬 전 총리에게 편지를 쓰셨지요?
