<p><b>○ 경기개발연구원장 좌승희 </b> 그건 패배주의일 수 있다는 얘기죠. 저는 잠재성장률을 지금 현재는 7%라고 생각 안 합니다. 3% 대에 와 있다고 보는데.
</p>
<p><b>○ 권칠승 위원 </b> 그런데 이 7%가 당시 한나라당에서 주장하던 747 뭐 이런 거 해서, 이게 한나라당의 모토였습니다, 7% 성장. 그렇죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그렇습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 7% 성장할 수 있다고 대표적인 경제학자 분이 백업을 해주신 거죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 얘기해서 백업이라……. 그렇게 많은 사람이 저를 그렇게 신뢰하는지 저는 정말 권 위원님, 전 아주 그 말씀에 대해서 제가 그런데요. 좌우간 제가 말씀드린 거는 7%라는 걸 가지고 논쟁할 성질의 것은 아니라는 의미입니다. 국가가 어떤 목표를 내걸고 비전을 가지고 간다는 것이 중요한 것이지 그걸 달성할 수 있다고 제가 얘기해 본 적도 없어요.
</p>
<p><b>○ 권칠승 위원 </b> 그런데 그걸 부정하면 안 된다고 말씀하신 것은 뒤집어 놓으면 그 말하고 비슷하게 들립니다.
</p>
<p style="padding-left:1.2em">  그다음에 2008년 9월 달에 책을 내놓으신 것 있잖습니까? 2008년이 정확하지 않습니다. “진화를 넘어 차별화로”. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 거기에서 “이명박 정부가 해야 할 일이란 그동안 한국 경제의 성장 추세의 하락을 조장해 온 발전 역행적 정책들을 바꿈으로써 흐름을 반전시키는 데 있다. 그렇지만 그러한 정책적 전환이 당장 고성장으로 시현되리라고 기대해서는 안 된다.” 이렇게 말씀하셨죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그게 평소 생각입니다. 
</p>
<p><b>○ 권칠승 위원 </b> 앞에 것하고 어떻게 연관되는 겁니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 앞에 7%라고 말씀하신 부분이요?
</p>
<p><b>○ 권칠승 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 7% 얘기는 국가는 그런 목표를 내걸어서 할 수 있는데 그것의 실현 가능성에 대해서는 저는 한 번도 그게…….
</p>
<p><b>○ 권칠승 위원 </b> 그러면 대선이 있던 전에 그 말씀을 하셔야죠. 실현 가능성 있는 이야기를 하라고. 그게 맞는 거 아닌가요? 저는 순수하게 말씀을 드리는 겁니다. 2008년 9월 달은 대선이 끝난 이후입니다. 그리고 나서는 “그만큼 하기에는 좀 어려울 수도 있다. 그런 걸 기대하지 마라.” 이렇게 말씀을 하시면 원장님의 이 말씀을 어떻게 신뢰를 하겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄, 그 7%에 대해서는 제가 기억은 잘 안 납니다만 제가…….
</p>
<p><b>○ 권칠승 위원 </b> 기억은 못하시겠지만 기록에는 다 남아 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 얘기한 배경은 이런 것입니다. 잠재성장 능력을 증가시키고 그것을 하기 위해서 노력하는 것 자체에 대해서 문제를, 그러니까 말하자면 너무 부정적으로 보는 것은 그건 패배주의적인 생각일 수도 있다는 그런 의미이지 제가 7%를 단기간 안에 할 수 있다거나 그게 또 우리나라가 이 정도 성장단계에서 7%를 할 수 있다거나 하는 그런 의미를 담은 것이라고 저는 생각을 안 합니다. 평소에 전 그렇게 생각해 본 적도 없고요. 오해가 있었다면 제가…….
</p>
<p><b>○ 권칠승 위원 </b> 평상시에 거침없이 언론 인터뷰하시는 모습하고는 좀 다르셔서 실망스럽습니다. 그리고 원장님의 그런 부분들에 대해서 입장을 그렇게 정리를 하시니까 연구원에서 지금 나오는 자료들, 진짜 좋은 자료를 많이 보내 주셔서 제가 덕분에 요즘 공부를 많이 하고 있습니다. 거기에 보면 김은경 박사님이 쓰신 CEO REPORT인데요. 김은경 박사님이 말씀해 주셔도 됩니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> “행정기관 분산의 문제점과 정책적 시사점”이라는 게 있습니다. 올해 3월 달에 나왔습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 김은경 박사가 발언대에 좀…….
</p>
<p><b>○ 권칠승 위원 </b> 네. 김은경 박사님. 제가 잘 모르면서 구체적인 내용을 가지고 질문을 드리자니까 저도 사실 좀 부담이 굉장히 옵니다. 오는데 좀 말씀을 드려볼게요. 이게 3월 달에, 이때가 한참 세종시 원안이냐 아니면 수정안이냐를 가지고 시끄럽게 시작할 때였죠? 저는 어떤 정책에 대해서 문제점만 지적하기 시작하면 살아남을 수 있는 정책이 하나도 없다고 생각합니다. 일단 제목에 대해서 문제제기를 좀 하겠습니다. 
</p>
<p style="padding-left:1.2em">  “행정기관 분산의 문제점과 정책적 시사점” 이렇게 돼 있습니다. 일단 문제점만 보겠다고 하는 기본적인 관점을 가지고 계신 거죠?
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네. 인사부터 드리겠습니다. 안녕하십니까? 경기개발연구원 경제사회연구부장을 맡고 있는 김은경입니다. 네. 말씀하십시오. 질문하셔도 됩니다.
</p>
<p><b>○ 권칠승 위원 </b> 제목에 대해서요. “행정기관 분산의 문제점과 정책적 시사점” 이게 제목입니다.
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 문제점만 중점적으로 보겠다라는 관점이 있으신 겁니까? 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 그렇습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 제가……. 이건 마지막에 말씀을 드리고요. 직접 쓰셨을 테니까 자료를 안 가지고 계셔도 대충 이해를 하시리라고 보고…….
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네. 기억을 살리겠습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 요약본 제일 처음에 보면요. “세종시 문제는 국민들의 이해와 관계없이 정파적 이익을 실현하기 위한 정략적 쟁점으로 부각되면서 갈등과 대립을 극대화시켰다.” 이렇게 돼 있거든요. 그냥 깨놓고 얘기할게요. 한나라당, 민주당을 다 지칭하는 겁니까? 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 양쪽 다입니까? 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 그럼 뒤로 가서 보겠습니다. “문제제기”라는 데가 있습니다. “세종시 문제는 국민들의 이해와 관계없이 정파적 이익을 실현하기 위한 정략적 쟁점으로 부각되면서 갈등과 대립을 극대화시켰다.”고 돼 있거든요.
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 국민들의 이해하고 아무 관계가 없습니까? 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네. 그렇게……. 저 개인적인 견해입니다.
</p>
<p><b>○ 권칠승 위원 </b> 사실만 확인하겠습니다. 그다음에 “세종시 문제를 둘러싸고 객관적 논의가 불가능한 이유는 세종시 원안이 국가균형발전과 수도권 인구집중 해소에 미치는 분석적 연구가 없이 일방적인 정치적 주장에 근거하고 있다.” 이렇게 돼 있거든요. 분석적 연구를 제가 가져오면 어떻게 하실래요?
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 제가 못 갖고 있는 자료가 있다면 제가 그 부분을 수정해야겠지만 제가 조사한 한에 있어서는 분석적 자료는 못 봤습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 아주 쉽게…….
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 이전에, 그러니까 처음에 만들 때 그렇습니다.
</p>
<p><b>○ 권칠승 위원 </b> 엑세스될 수 있는 부분이 있습니다. 제가 나중에……. 제가 따지고 이런 게 아니고요. 김은경 박사님하고 나중에 사석에서라도 얘기를 해보고 싶은 겁니다. 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네. 알겠습니다.
</p>
<p><b>○ 권칠승 위원 </b> 그다음에요. “세계 어떤 나라도 역사적 계기 없이 대통령 선거과정에서 표몰이용 공약에 의거해 수도 이전을 도모하거나 행정기관을 분산시킨 사례가 없다.”.
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 저도 이런 사례가 있는지 없는지 잘 모르겠습니다. 그런데 “표몰이용”이라고 하는 거는 특정한 곳을 이야기하시는 거죠. “대통령 선거과정에서의 표몰이용 공약” 누군지 다 아는 거죠?
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 수도권의 반대가 자명할 텐데 이걸 표몰이용이라고 이렇게 재단하신 이유가 뭐죠?
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 그 당시 제가……. 저도 한국에 2002년에 귀국을 해서 그 당시에 있었는데요. 실제적으로 대한민국의 선거 구조에 대해서 제 개인적인 견해를 말씀드리면 결국은 캐스팅보드를 쥐고 있는 게 충청권이었고 그 부분에 있어서 아무래도 표몰이한 관점이 있지 않았나 생각을 하고 있습니다.
</p>
<p><b>○ 권칠승 위원 </b> 수도권에 있는 기관들이 나가면 수도권 주민들이 반발할 거 아닙니까? 정치권에 있는 사람들 박사는 아니어도 그 정도 생각은 합니다. 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 그건 이제 역관계의 문제겠죠. 그 당시 선거할 때 과연…….
</p>
<p><b>○ 권칠승 위원 </b> 그러니까요. 더하기 빼기가 있는 겁니다.  
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 수도권과 지방과 충청권을 어떻게 보는가의 문제라고 생각하는 겁니다.
</p>
<p><b>○ 권칠승 위원 </b> 그렇습니다. 정치공학적으로만 봐도 더하기 빼기가 있는 겁니다.
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 그렇습니다.
</p>
<p><b>○ 권칠승 위원 </b> “표몰이”라고 왜 이렇게 하셨죠? 근거를 말씀해 주셔야죠. 개인적인 생각이 아니고.
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 제 생각에는 그 당시에 수도권과 충청권을 제외한 여타 지방하고는 비슷한 것 같고요. 그런 의미에서 아까 말씀드렸던 충청권을 어떻게 할 것인가의 문제가 있었기 때문에 거기에 더 부사나 형용사를 붙인다면 “충청권 표몰이”는 될 수 있을 것 같습니다.
</p>
<p><b>○ 권칠승 위원 </b> 얼마든지 반론이 가능한 이야기입니다.
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네. 그럴 것 같습니다.
</p>
<p><b>○ 권칠승 위원 </b> 그다음에요. 제가 지금 김은경 박사님한테 뭐라고 하는 것 아닙니다. 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> (웃   음)
</p>
<p><b>○ 권칠승 위원 </b> 이렇게 보인다는 겁니다. 이렇게 보인다는 겁니다. 그리고 왜 이렇게 쓰셨는가에 대해서 제가 계속 의혹을 제기하는 겁니다. 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 그다음에 이런 부분이 있습니다. “세종시 원안이 2004년 10월 21일 신행정수도 이전특별법이 위헌판결을 받으면서 노무현 전 대통령의 공약을 실현하기 위한 정치적 미봉책으로 급조된 것이다.” 또 “충청도민의 표를 얻기 위한 공약으로 제기됐다.” 이런 것들이 있습니다. 그리고 그다음 페이지에 보면요. “만약 완전한 수도이전을 한다면 현재 수도권의 인구집중 완화에 다소 기여할 수도 있을 것임” 이렇게 돼 있습니다. 그러면 그때 위헌판결이 안 났어야 되네요?
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 만약에 정말로 분산을 하겠다 하면 제 생각에는 대통령부터 내려가셔야 된다고 생각을 합니다. 모두가 내려간다면.
</p>
<p><b>○ 권칠승 위원 </b> 그때 그렇게 주장했잖아요?
</p>
