</p>
<p><b>○ 경제사회연구부장 김은경 </b> 아니죠. 그건 다 갔을 때 얘기죠. 위원님께서 지금 문장을 왜곡하고 계신 건데 제가 말하고 싶었던 것은 완전하게 인구 분산을 하고 수도권 집중을 해소하고 싶었다면 사실은 정확하게 해야 될 것은 뭐냐? 실질적으로 완벽하게 수도가 내려가는 겁니다. 그런데 그게 헌법재판소에서 안 됐지 않습니까? 대통령 공약은 뭡니까? 어쨌거나 지켜야 되는 겁니다. 따라서 그 상황에서 할 수 있는 게 뭔가 생각했을 때는 노 대통령께서 그런 방법을 찾아서 했다고 말씀을 드리는 거고 저도 그렇게 알고 있고 그렇게 쓴 것뿐입니다. 
</p>
<p><b>○ 권칠승 위원 </b> 네. 그러니까 그렇게 가서는 안 된다라는 말씀을 하신 거죠, 결국에는. 이 REPORT를 통해서. 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 그거는 저의 견해입니다.
