<p><b>○ 경제사회연구부장 김은경 </b> 거기에 대해서 반대하신다면 위원님께서도 반대하신다는 의견을 쓰실 수 있는 거고 저는 연구원 리포트로써 쓴 거고 그 부분에 대해서는 나름대로 정당하게 평가를 받았습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 그러니까 제가 연구한 부분에 대해서요. 이 결론 자체에 대해서 김은경 박사님한테 뭐라고 이야기를 하는 게 아니라니까요.
