<p><b>○ 경제사회연구부장 김은경 </b> 네.
</p>
<p><b>○ 권칠승 위원 </b> 그다음에 “지역격차의 가장 중요한 지표가 되는 1인당 지역내총생산의 경우 충남이 2위이기 때문에 국가균형발전 취지에 맞지 않다.” 이런 내용도 있습니다. 그러면 GRDP가 제일 꼴찌인 지역으로 가야 된다는 겁니까? 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 실제로 지역격차를 해소한다고 했을 때 기본적으로 우리가 우선기조로 생각하는 것들이 각 지역의 차이 아니겠습니까? 그러면 가장 중요한 건 가장 잘사는 지역과 가장 못사는 지역을 비교해 보고 가장 못사는 지역을 우선 성장하게 하는 게 굉장히 중요한 정책목표라고 생각합니다. 
