</p>
<p><b>○ 권칠승 위원 </b> 제가 내용은 그 정도로 하겠습니다. 제가 원장님한테 진짜, 지금 시간이 다 됐다고 해서 그런데요. “작은 정부” 이렇게 주장을 하시면서 전임 정부 때도 말씀을 많이 하셨습니다. 지금은 왜 그런 부분에 대해서 말씀을 안 하시는지. 정말 정부가 작아졌는지. 언급을 하셔야 되는 것 아닌가요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 그렇게 역량이 큰 사람이 못 됩니다. 여기 와서 경기개발연구원 일하기도 바쁘고요. 중앙에 요즘 돌아가는 건 팔로우업도 못하고 그래서 그거 다……. 죄송합니다. 제가 문제 제기를 할 수 있었을 수도 있지만 그걸 잘 팔로우업을 못해서 그러고 있습니다.
</p>
<p><b>○ 권칠승 위원 </b> 제가 아무것도 모르는 그런 입장으로 보실 수도 있겠지만요, 공부를 많이 하신 분들은. 정부의 크기나 공무원 숫자라든가 정부의 권한이라든가 또 재정의 크기라든가 이런 식으로 볼 수 있는 것 아니겠습니까, 크게? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇죠. 그런데 제가 얘기하는 작은 정부는 꼭 그렇게 어떤 예산이나 뭐 이런 수치 이게 관련이 전혀 없진 않지만 정부가 지나치게 시장이나 민간에 개입하고 하는 그런 차원의 지적으로 저는 통상 얘기를 합니다. 재정의 규모라든가 복지 규모 이런 걸 따지기에 앞서서 정부가 과도하게 시장에 개입해서 규제하고 그런 것을 불식하는 것이 필요하다는 차원에서 제가 작은 정부 얘기를 해왔습니다. 
</p>
<p><b>○ 권칠승 위원 </b> 공무원들한테도 정치적인 중립을 강요해서는 안 된다는 게 제 신조입니다. 형식적으로도 강요해서는 안 된다고 생각합니다. 업무와 분리된 정치적인 행동은 얼마든지 보장해야 된다고 생각합니다. 그래서 그런 법안들도 준비하고 했었거든요. 그렇지만 운영을 하고 하는 데는 다양한 목소리들이 있고 또 비록 내심으로 지지하는 정파라고 하더라도 잘못하는 부분은 전문가로서 지적을 하시는 이런 부분들이 좀 아쉬움으로 많이 남습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래요…….
