</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 최근에……. 그러니까 우리 권 위원님이 제가 비판적인 얘기한 것은 별로 안 보신 것 같기도 합니다. 나중에 보여 올릴게요. 제가 지금 정부가 하는 것에 대해서도 문제 있는 건 적절한 타이밍에 기회가 오면 얘기를 하고 그럽니다만 제가 너무 정파적으로 얘기하고 있지 않느냐는 그 점에 대해서는 제가 조금 100% 수긍하기가 좀 어렵지만 또 그렇게 보일 수도 있겠다는 그런 생각을 하고요.
</p>
<p style="padding-left:1.2em">  그다음에 제가 개인적으로 생각하는 것이 자칫 원장이라고 하는 모자를 통해서 박사들한테 선입견을 주거나 박사들의 연구에 제약이 되지 않겠느냐는 그런 걱정을 하신 걸로 이해가 되는데 솔직히 말해서 제가 제 견해를 박사들한테 강요하거나 이렇게 좀, 뭐라고 할까요? 유도하거나 하는 거는 사실 별로 많지 않습니다. 솔직히 말해서 제가 모든 분야를 다 그렇게 관리하기도 어렵고. 그런데 저는 제 나름대로 기회가 될 때 이렇게 얘기하고 시간이 좀 있으면 잡문도 쓰고 그런 정도지 제가 연구원의 박사들의 연구방향을 체계적으로 어떻게 유도하거나 하는 그런 일은 생각해 본 적도 없고 아마 개인적으로 권 위원님이 나중에 다 물어보시면 알겠지만 박사들이 제가 제 의견을 하라고 했던 경우가 있다고 하면 제가 정말 권 위원님한테 사과를 드리거나 하겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 감사합니다. 다음 박승원 위원님.
