<p><b>○ 박승원 위원 </b> 반갑습니다. 광명 출신 박승원 위원입니다. 앞서 권칠승 위원님이 질문했던 부분과 관련해서 연장해서 조금만 더 말씀을 드릴게요. 저도 질문을 드리려고 했었던 부분이기는 합니다만 세종시와 관련해서 최근에는 발언을 안 하시는 건가요? 세종시 관련해서. 최근에는…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 발언을 안 하는 이유가 뭐냐 이거죠?
</p>
<p><b>○ 박승원 위원 </b> 발언을 현재는 안 하시고…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 안 하죠. 
</p>
<p><b>○ 박승원 위원 </b> 사실관계만 하나 확인을 하고 넘어갈게요. 올해 2월 18일 날 제가 신문에 난 걸 잠깐 봤는데 도청 공무원들 대상으로 강연을 진행하신 적 있으신가요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그랬을 수도……. 어딘가요?
</p>
<p><b>○ 박승원 위원 </b> 경기도에서 원장님께서 실국장님 회의에서 “부의 이동과 한국경제”를 주제로 강의…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 실국장 회의에서 했습니다. 
</p>
<p><b>○ 박승원 위원 </b> 그 자리에서 “김대중ㆍ노무현 정부는 경제적으로 실패한 정부”라는 말씀들을…….
