</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 그걸 명치적으로 했는지 잘 기억이 안 납니다. 그렇게 보도가 됐습니까? 
</p>
<p><b>○ 박승원 위원 </b> 네. DJ의 벤처 육성정책, 노무현의 10대 동력산업정책를 꼽으면서 “실패한 정책이다.”.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그것은 그렇게 크게 보시면 오해고요. 제가 그날 드린 말씀은 대한민국의 산업정책의 역사를 간략하게 정리해서 말씀을 올렸죠. 성공한 경우와 성공하지 않은 경우를 나눠서 얘기를 하는 과정에서 제가 보기에 그동안 박정희 대통령 시절에 수출진흥정책, 중화학공업 육성정책, 새마을운동 여러 가지 정책들이 있고 전두환 정부 들어와서 IT산업 육성정책 이런 정책들이 있고, 물론 박정희 대통령 시절에 영화산업 육성정책 이런 것도 있고 그랬습니다. 김대중 대통령 시절에 와서 벤처산업, 그다음 노무현 대통령 시절에 10대 동력산업 그런 게 있는데 그 전체 산업정책 과정을 쭉 살펴봤더니 상대적으로 성과가 미흡한 것이 벤처산업 육성정책과 10대 동력산업 육성정책이었다는 게 그때 발표였습니다. 설명이었습니다. 
</p>
