<p><b>○ 경기개발연구원장 좌승희 </b> 네, 인천발전연구원.
</p>
<p><b>○ 박승원 위원 </b> 경기개발연구원에서 공동으로 삼자가 함께 GTX 연구를 공동으로 추진하는 방식으로 한다든지 해야 이게 제대로 된 어떤 계획이 나오는 것이지 경기도가 일방적으로만 이렇게 추진하니까 “도지사가 이거 대권용이다.”라고 하는 도민들로부터 오해를 받고 있는 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 적절한 지적을 하셨는데요. 사실 저희가 그동안 시정개발연구원하고 인천발전연구원에 공동연구를 여러 차례 요청했습니다. 그러나 그쪽에서는 사실 상당히 소극적이었어요. 그러던 차에 이번에 수도권광역위원회에서 수도권인프라기획단을 만들었는데 바로 이 기획단이 앞으로 3개 시도의 의견을 종합해서 위원님이 말씀하신 대로 적절하게 GTX의 타당성과 향후 추진방안에 대한 연구의 결론을 내지 않을까 하는 생각을 하고 있습니다. 
</p>
<p><b>○ 박승원 위원 </b> GTX를 반대하는 의견도 꽤 많습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 알고 있습니다. 
</p>
<p><b>○ 박승원 위원 </b> 그런 얘기 들으셨지요? 빨대효과가 과연 있는가 그거 잠깐 봤는데 KTX를 예를 들어서 그렇게 말씀하셨던데 제 지역이 광명이거든요. KTX 생각만 하면 광명인 제 입장에서는 굉장히 울화통이 터지는 정책이라고 생각하는 점이 상당히 많은데 단순한 예 하나를 가지고 GTX 얘기하는 것은 적절하지 않다고 보고요. 그렇게 단세포적으로 바라보지 않고 제대로 할 수 있도록 경기개발연구원에서 제대로 원장님이 방향을 잡아갔으면 좋겠고요. 경기도가 GTX사업 진행하는 데 있어서 원장님께서는 정확히 틀어쥐시고 이게 일방적으로, 불합리하게 추진되지 않도록 방향점을 잡아줬으면 좋겠고, 12조 든다고 하잖아요? 그런데 20조까지 들 거라고들 상당히 많은 분들이 생각을 하고 있고 그 정도 많은 예산들이 들어가는데 경기도를 위해서 그 정도 예산을 가지고 할 수 있는 사업들이 굉장히 많지 않습니까? 나중에 자칫 잘못하면 김문수 지사의 발목을 잡을 수 있는 사업이 GTX사업이라고 생각하는데 자세한 것은 추후에 말씀을 나누더라도 이 부분과 관련해서 우리 원장님께서 정확한 방향을 가지시고 경기도가 가자는 대로 무조건 따라가지 마시고 개발원에 대한 원장님의 정확한 입장과 원칙을 가지시고 진행을 해주시면 좋겠습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 말씀하신 취지는 제가 잘 이해하겠는데요. 제가 그렇게 힘이 있지 못합니다. 제가 최선을 다해서 연구를 하고 제안하지만 이것은 이미 도 사업이기 때문에 위원님이 어느 정도 양해를 해주시리라 믿고요. 저는 저 나름대로 최선을 다하겠습니다. 
</p>
<p><b>○ 박승원 위원 </b> 의원들하고 논의를 많이 하시면 되잖아요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 감사합니다. 수고 많으셨습니다. 다음 안병원 위원님.
</p>
<p><b>○ 안병원 위원 </b> 반갑습니다. 김포 출신 안병원 위원입니다. 먼저 질의드리기 전에 저는 아까 동료 위원들하고 들어오면서 ‘아, 왜 이렇게 침침할까?’ 그런데 솔직히 얘기해서 저도 계속 들여다보면서 지금 굉장히 눈이 가물가물해졌어요. 그런데 불이 여기서 더 이상 안 들어온다고 그러더라고요. 그래서 왜 이렇게 했을까? 그리고 회의를 여기서 얼마나 하세요? 1년에. 상당히 많이 하실 텐데. 이런 컴컴한 데서 어떤 보안문제나 이런 게 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 많이 있습니다. 저도 평소에 어둡다고 생각을 하긴 했는데…….
</p>
<p><b>○ 안병원 위원 </b> 엄청나게 어둡고 나름대로 몇 시간씩 책자를 들여다보고 그러면 진짜 아주 까부라져요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다.
</p>
<p><b>○ 안병원 위원 </b> 기가 뺏겨나가는 것 같은 느낌이 들어요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 의도적으로 그런 건 아니니까 양해해 주시기 바랍니다.
</p>
<p style="padding-left:2.4em">    (웃   음)
</p>
<p><b>○ 안병원 위원 </b> 그렇지요. 그런데 제가 그것까지도 생각해 봤어요. 의도적으로 위원님들 기를 뺏는 거 아닌가 그런 생각도 했었습니다.
</p>
<p style="padding-left:1.2em">  우리 좌승희 원장님, 많은 분들이 “그릇이 우리 경기도에 있을 그릇이 아니다.” 이렇게 표현하시는 분들도 많아요. 그런데 계속 위원님들하고 질의응답하시면서 항상 자세를 낮추시는 그런 발언을 계속 하세요. 그런데 저희가 봤을 때는 굉장히 훌륭하신 분이고 또한 우리 경기도의 어떤 정책부터 우리 도민들 또 더 나가서 그것이 우리 대한민국의 어느 부분에 접목할 수 있는 그런 연구과제들을 많이 연구하시고 그러는 것 같은데 제가 7월 6일 자로 도의회에 들어와서 그때 업무보고할 때 첫 번째 잠깐 질의드렸던 사항이 우리 기구 및 인력인데 지금도 변함없이 많이 연구직이 부족한 것 같아요. 그때 원장님 말씀이 무슨 얘기냐면 “아무나 뽑을 수는 없는 사항이다.” 그런 말씀을 하셨고, 그래서 저는 지금도 현재 한 4개월이 지났는데도 지금 인원이 부족한 현황이고 또한 그 당시 제가 물어봤을 때도 연구위원님들의 연구수행 건건이 이런 것이 좀 부담이 가지 않느냐 이런 얘기를 했던 기억이 있습니다. 이 부분에서 먼저 말씀을 좀 해주시고.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 정말 특별히 드릴 말씀이 없네요. 변화가 없는 건 사실인데요. 그 사이에 한두 분야의 박사 충원을 위해서 저희가 공고도 내고 노력을 했는데 결과적으로는 마땅한 사람이 없다고 결론을 내렸습니다. 그래서 지적하신 말씀대로 바로 저희가 열심히 노력해서 하는 과정을 오픈해서 할 수밖에 없지 않을까 하는 생각이 들고요. 그렇습니다. 노력한 것은 아닌데요. 10월 달에 저희가 교통부에 한 분을 뽑았고요. 문화관광센터에 한 분이 또 이직을 하고 이렇게 했습니다. 그리고 추가로 저희가 뽑으려고 했던 분은 저희가 불행하게도 마땅한 분이 없어서 뽑지를 못하고 이렇게 해서 좌우간 뭔가 노력하고 있는데 계속해서 변화가 있고 이래서 위원님 기대만큼 충족을 못하고 있습니다.
</p>
<p><b>○ 안병원 위원 </b> 제가 질의드리는 이유가 우리 경기도 인구부터 모든 것이 대한민국에 선도적으로 갈 수 있는 그런 지역이거든요. 그런데 상당히 많은 부분에 연구과제도 내시고 그런 부분에는 말 그대로 교통부터 어떤 모든 부분인데 상당히 할 일이 많을 것이고 또 그것으로 연구함으로써 더 나아갈 수 있는 그런 많은 부분적인 것을 접목할 수 있는데도 이런 부분에서 나름대로 노력은 하시지만 왜 계속 이렇게 채워지지 않나. 그리고 저희가 생각할 때 바깥에서 보면 엄청나게 많은, 나름대로 외국에서 학위 받아서 오신 그런 박사님들도 많이 있고 또 그런 분들이 제대로 취직 못해서 정말 말 그대로 요새 백수 이런 얘기도 나옵니다만 상당히 많거든요, 제 주위에도. 그렇게 많은 자원에서도 마땅하게 우리 경기도에서 그렇게 뽑아 쓸 수 있는 인물들이 없나 여기에 대해서 의문점을 가졌었어요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 좌우간 결과가 그렇게 돼서요. 제가 또 말씀을 드리면 변명밖에 안 될 것 같은데 위원님 기대에 맞게 계속해서 저희가 필요한 분야를 충원하도록 노력을 해나가겠습니다. 
</p>
<p><b>○ 안병원 위원 </b> 나름대로 2010년도에도 아까 동료 위원께서 말씀하셨지만 한 150개 연구추진실적이 나왔어요. 나름대로 150개 했다고 그래서 그것이 경기도에 다 접목되는 것은 아닌 걸로 알고 있는데 지금 현재 정확하게, 지금 2010년도는 지나가지 않았습니다만 여기서 150개 중에서 그래도 골라서 지금 현재 접목해서 하는 그런 연구과제, 정책 같은 게 대표적으로 뭐가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아까도 그런 지적이 없지 않아 있었습니다만 저희가 2009년 연구과제 정책반영 성과분석이라고 해서 책자를 하나 냈는데요. 이것을 나중에 위원님한테 전해드리도록 하겠고요.
</p>
<p><b>○ 안병원 위원 </b> 여기 있는 것 같네요, 자료는. 제가 아직 못 봤습니다만.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 적어도 아주 직접적으로 저희가 연구한 것이 정책에 반영된 게 한 30~40% 가까이, 직접적으로 된 게 그 정도가 아닌가 싶고요. 그 외에는 거의 대부분이 도정하고 관련된 일이기 때문에 알게 모르게 저희 연구원 연구가 도정에 사용되고 있다고 생각합니다. 제가 왜 그것을 확인할 수 있냐면 제가 매주 국실장 회의에 참석을 해보면 국실에서 보고하는 많은 내용을 우리 연구원에서 하고 있다는 사실을 제가 계속 확인할 수 있기 때문에 이게 도정하고 저희 연구원이 아주 일체감을 가지고 서로 협력하고 있는 그런 관계가 지금 이루어지고 있지 않나 하는 그런 생각을 하게 됩니다. 
</p>
<p><b>○ 안병원 위원 </b> 150개 연구과제 중에서, 사업 중에서 도청에서 얘기해서 한 것하고 또 자율적으로 경기개발연구원에서 박사님들이 나름대로 연구한 그런 비율이 어느 정도나 되나요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 한 80% 정도가 도에서 아젠다를 받아서 하는 게 있고요. 한 20% 정도는 우리가 자체적으로 주제를 선별해서 하는 걸로 보시면 되겠습니다. 특히 보고자료에 10페이지입니다만 전체 150개 연구 중에서 21개의 기본과제를 하고 있는데 기본과제는 박사들이 직접 선정한 과제이고 정책연구과제의 상당한 부분은 도에서 요청이 돼서 들어온 거라고 보시면 되겠습니다. 
</p>
<p><b>○ 안병원 위원 </b> 제가 또 물어보는 것은 저는 기초에서 두 번 있었기 때문에 그래서 이렇게 왔는데 나름대로 31개 저희 기초가 있지 않습니까? 자체적으로 이런 연구기관을 갖고 있는 데가 없는 걸로 알고 있거든요. 그래서 나름대로 그 지역마다 교통문제부터 군사문제 또 환경문제 이런 것이 무지하게 어떤 문제점으로 제시되고 있는 상황에서 제가 인원 아까 얘기한 부분이 그런 것으로 인원이 좀 더 채워졌을 때 그런 지자체에서도 하는 그런 것을 좀 받아서, 나름대로 그런 것이 도까지 올라와서 도에서 하겠지만 또 못하는 경우도 있는 것으로 알고 있기 때문에 이런 것은 확실하게 채워서 더 늘릴 수 있는 방법은 늘려서 우리 경기도 구석구석에 다 골고루 그런 어려운 문제들이 잘 해결될 수 있도록 해야 되지 않느냐 그런 뜻에서 제가 질의를 드리는 사항이거든요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아주 적절한 지적이십니다. 그리고 이번에 민선5기가 새로 시작된 다음에 저희가 31개 시군의 수요를 보다 더 많이 감안해서 연구를 해야 되겠다 하는 그런 생각을 가지고 좌우간 여러 가지 노력을 하고 있습니다. 그런데 이렇게 해보면 시군이 연구아젠다를 독자적으로 확인해서 니드가, 필요성이 저희한테 오면 저희가 해나갈 수가 있는데 저희가 31개 시군을 다 다니면서 아젠다 발굴하기가 사실은 그렇게 쉽지 않았습니다. 앞으로 그 방향으로 노력도 더 강화할 생각이고요. 그리고 각 박사들이 지금은 조금 형식적이 됐습니다만 시군담당제도라는 게 사실은 있습니다. 그래서 해봤는데 시군에 박사님들이 가면 약간 그쪽에서 이방인이 온 것처럼 생각하는 경우도 있고 그래서 저희 쪽에서 노력을 하다가도 이게 약화되고 이런 경향이 있었습니다. 그런데 그렇지 않은 분야도, 아까 위원님께서 군사규제 그런 문제도 말씀하셨지만 연구원에 민군정책팀이 있어가지고, 이것은 31개 시군에 다 관련되는 거지요. 이런 쪽의 규제완화를 위해서, 특히 북부지역은 거의 매일 필드 서베이를 하면서 하고 있고요. 그래서 내년에는 저희가 지방 시군하고 더 적극적으로 하고 심포지엄도 필요하면 같이 해서 도와주는 그런 역할을 하도록 최선의 노력을 하겠습니다. 
</p>
<p><b>○ 안병원 위원 </b> 좋은 여건 다 갖고 있습니다, 여기에. 또 이것이 경기도청만을 위한 곳이 아니거든요. 나름대로 31개 시군구 거기에도 나름대로 다 포함된 부분이기 때문에 활용도에 대해서 더 신경을 써야 되실 거고 또한 아까 연구, 박사님들 나름대로 지역마다 포지션이 있다고 그러지만 대개 부시장급은 다 우리 도청의 국장급 이상 분들이기 때문에 어떤 그런 분들하고의 관계설정 또 그분들은 아실 거란 말이에요. 그래서 그분들한테 어떤 공문 이런 것으로 꼭 필요한 것 있으면 해야 되지 않느냐. 그런 것도 더 개발을 하셔서, 그만큼 또 힘드실 거예요, 분명하게. 그래서 그런 문제에 대해서 더 노력을 해주시기를 부탁드리겠습니다. 
</p>
<p style="padding-left:1.2em">  그리고 마지막으로 하나만 더 하겠습니다. 시간이 다 된 것 같은데. 올해 좌승희 원장께서 신년 인터뷰에 나름대로 이런 말씀을 하셨어요. “올해 연구원의 중점과제와 비전은?” 이렇게 물어봤을 때, 모 언론사에서. “현재 중앙이나 지방이나 제일 큰 문제는 일자리다.” 다 공감하고 있습니다. 경기가 어렵다 보니까 상당히 모든 것이 다 저하돼서 있는 그런 상황인데 우리 연구원님들의 그런 경기도형 일자리 창출모델을 개발한 사항이 있습니까? 그래서 그것이 이번 6ㆍ2 지방선거 때 김문수 도지사가 어떤 공약사항으로 거기까지 간 그런 부분이 있습니까? 
