<p><b>○ 위원장 강득구 </b> 감사합니다. 안병원 위원님을 끝으로 일단 위원님들의 본질문이 끝났습니다. 따라서 오전의 순서에 따라서 다 위원님들 말씀이 한 단락 정리가 됐습니다. 그러면 추가질문하는 시간을 갖겠습니다. 추가질문은 한 6분에서 7~8분 하는 걸로 하겠습니다.
