<p><b>○ 위원장 강득구 </b> 그다음에 “필요하면 국가정책에 대한 대안을 내놓는다.” 이 말에 대해서는 사실 저는 퀘스천마크입니다. 이 전제하에서 제가 한두 가지 질문하겠습니다. 그런데 먼저 김은경 부장님, 아주 소신에 찬 발언 좋습니다. 그리고 잘 들었습니다. 그렇지만 김은경 부장께서 어떻게 생각할지 몰라도, 웃지 말고 들으세요. 여기 계신 위원님들은 잘났건 못났건 경기도민의 대표입니다. 여기 계신 위원님들이 우리 김은경 부장님 입장에서 하찮게, 우습게 보일 수도 있지만 적어도 저 같은 사람은 다른 건 몰라도 도민의 대표라는 부분을 항상 유념하고 적어도 상임위 활동 하려고 그럽니다. 그런데 자리에서 권칠승 위원님이 얘기하신 다음에 우리 원장님한테는 인사하고 그냥 들어가셨잖아요? 물론 실수로 한 것일 수도 있지요. 그런데 저는 개인적으로 다시 한 번 얘기하지만 이 자리가 저희들이 잘나서 행정사무감사하는 것 아닙니까? 법적 회의입니다. 그리고 법적 대표성을 갖는 겁니다. 그런데 인사도 없이 그냥 들어가고 계속 웃고 이런 거는, 모르겠습니다. 제가 참 어떻게 보면 약간 소심하고 어떻게 보면 이런 얘기까지 해야 되나라고, 우리 경기개발연구원 분들이 속으로 어떻게 생각할지 몰라도 저는 그런 것은 아닌 것 같아요. 저는 개인적인 가치, 개인적인 소신 이런 거 다 존중하지만 적어도 형식이라는 부분들은 상호 배려하고 상호 존중해 줄 필요가 있다고 생각해요. 원장님, 어떻게 생각하세요?
