<p><b>○ 경기개발연구원장 좌승희 </b> 연구원에서 내는 보고서 어느 것도 연구원의 공식적인 견해라고 하지는 않습니다. 저는 그렇게 생각하지 않습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 그런데 예를 들면 언론매체에 기고한 글들을 보면, 예를 들면 조선일보나 한겨레나 이런 언론매체를 보면 기고한 글이 예를 들면 사시 내지는 지면을 제공한 언론사와 입장이 다를 때는 “이 글은 우리 논조와 입장이 다를 수도 있습니다.” 이렇게 대부분 다 써놓습니다. 그런데 CEO REPORT에서는 어느 것도 그렇게 쓴 게 없어요. “우리 연구원의 입장과 다를 수도 있습니다.”라는 문구가 없어요. 만약에 지금 원장님이 말씀하신 CEO REPORT가 경기개발연구원의 입장이 아니라면 굳이 발행할 필요가 없다라고 생각합니다. 그러면 다음 예산은 우리가 이 부분 삭감하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄요. 제가 드린 말씀은 여기에 일단 공식적인 견해가 아닐, 다를 수 있다는 것을 밝혔습니다. 밝혔고요.
</p>
<p><b>○ 위원장 강득구 </b> 아니, 그런데 지금 원장님이 아니라고 그랬잖아요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄, 그런 주장이라고 그럴까 그게 여기 보고서에 다 적혀 나가고 있고요.
</p>
<p><b>○ 위원장 강득구 </b> 제가 물어보는 것은…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇다고 해서 제가 연구원이 면책할 수 있다고 생각하지는 않습니다. 
</p>
<p><b>○ 위원장 강득구 </b> “입장과 다를 수 있다.”고 써 있는데 아니라고 그랬잖아요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 공식입장이 아니라고 다 여기에 적혀 있습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 그렇게 적혀 있어야 되는 거지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 그렇게 적혀 있어야 되는 거죠. 그런데 문제는 뭐냐면 경기개발연구원의 공식 간행물이기 때문에 현황과 이슈를 대하는 경기개발연구원이나 저자의 의견이 어떠했든 간에 중요한 것은 마지막 전결자가 부원장이고 그리고 주제 발굴도 연구책임자가 주제 발굴하는 경우가 있고 경기도에서 의뢰해 갖고 주제 발굴하는 경우가 있고 기획주제 발굴이 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 이것은 어쨌든 간에 경기개발연구원의 입장이 들어갈 수밖에 없어요, 현실적으로. 그래요, 안 그래요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇기 때문에 제가 공식적으로는 “경기개발연구원의 의견과 다를 수 있습니다.”라고 했지만 그렇다고 해서 우리 연구원이 완전히 면책할 수 있다고 생각하지는 않습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그렇지요. 그게 어떻게 보면 정확한 답변일 것 같습니다. 정리하겠습니다. 제가 두 가지 CEO REPORT 자료를 보니까 2009년 11월 달에 발행한 “학교급식 직영화 및 무상화 방식의 타당성 검토” 그리고 또 2010년 3월에 출판한 “헌법상 교육관련 조항” 둘 다 같은 분이 썼는데 이런 표현이 있습니다. 학교급식 직영화와 관련해서 “반시장주의자들이 직영 주장하는 어설픈 평등주의와 복지국가의 망령의 결정판” 그리고 또 헌법상 교육관련 조항에는 이런 내용이 있습니다. “이미 평준화정책이 교육 만학의 근원임.”. 물론 저는 우리 김은경 부장께서 소신 있게 얘기한 것처럼 저는 전문가들은 그렇게 할 수 있다고 생각을 해요. 그런데 문제는 뭐냐면 주제도 그렇고 마지막 출판사도 경기개발연구원 이름으로 나와 있는 거잖아요. 그래요, 안 그래요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 그렇습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 그러면 최소한 제가 경기개발연구원의 입장을 경청하고 존중하지만 이런 방식이, 이런 표현이 맞는 건가요? 적어도 경기개발연구원 이름으로 CEO REPORT가 나가는데 이렇게 거친 표현이.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그래서 제가 최종적으로 본다는 게 저희 연구원이 완전히 면책할 수가 없다고 보기 때문에 어떤 경우에는 출판을 보류하거나 출판을 일단 하더라도 배포를 하지 않고 마는 경우도 있습니다. 그래서 이게 정치적으로 파장이 있을 수 있는 것은 그래서 그 시기가 지난 다음에 필요한 시점에서 이것을 공개하도록 하는 경우도 있는데, 제가 다 점검을 못해서 이렇게 나갔을 경우도 있다고 생각을 합니다. 그래서 그런 경우가 차후에 안 생기도록 저희가 더 철저히 해야겠지요. 
</p>
<p><b>○ 위원장 강득구 </b> 그러니까 이겁니다. 우리는 예를 들면 연구내용을 발굴하고 그러는 건 어쨌거나 결국은, 마지막 부원장이 전결하지만 결국은 다 원장이 책임지고 경기개발연구원 이름으로 나오잖아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 그리고 이것에 대해서 당당에게 필자가 얘기할 수 있다고 생각해요. 그렇지만 이 부분에 대해서 마지막 책임은 원장과 부원장이 책임져야 된다라는 겁니다. 이것은 2년 후 상황이 어떻게 될지 모르겠지만 우리가 분명히 책임을 물을 겁니다. 그리고 우리가 할 수 있는 건 조례의 개정과 예산밖에 없어요. 이런 식으로 일방적으로 편향되게 한다고 그러면 이 부분에 대해서 누가 예산승인을 해주겠어요? 그렇습니까, 안 그렇습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 충분히 이해합니다. 
</p>
<p><b>○ 위원장 강득구 </b> 우리 경기개발연구원장께서 인터뷰한 걸 보니까 연구원 천국으로 만들어 주겠다고 그런 내용이 있었더라고요. 좋습니다. 연구원들이 좋은 시설에서, 잘 갖춰진 복리후생 이런 곳 속에서 연구할 수 있는 환경 만들어 주면 좋지요. 제가 올해, 편하게 말씀드립니다. 도의원 되고 기획위원장 되면서 이 자리에서, 그러니까 상임위원장 석에서 발언한 것 중에서 제일 후회하는 게 뭔 줄 아세요? 제가 여기에서 어떤 의미에서 사과드릴 수도 있지만 우리 연구원 중에 한 분이 다리 좀 이렇게 했다고……. 그런데 제가 사실은 좌승희 원장이, 제가 책자를 통해서 좌승희 원장을 봤을 때 이분이 상당히 보수 중에서 수구라고 생각했는데 이분이 서서 계속 얘기를 하시는데, 답변하시는데 앉아서 다리 꼬고 이런 모습들이 “야, 이게 보수 수구의 모습이냐.” 저는 그런 원장과 대치된 입장에서 그랬던 건데 사실은 연구원들은 좀 더 자유로운 분위기 속에서 창의적인 사고를 할 수 있게끔 만들어 주는 게 저희 같은 사람들의 임무 중의 하나라고 생각합니다. 그런 부분에 대해서는 공식적으로 제가 사과를 합니다. 
</p>
<p style="padding-left:1.2em">  왜 이런 말씀을 드리냐 하면 하여간 그런 환경 속에서 연구원들이 현안을 다양한 시각에서 검토할 수 있는 환경을 만들어 주고 창의적인 관점에서 대안을 모색할 수 있게 해주고 그리고 경기도 정책을 때로는 무조건 예를 들면 일방적으로 김문수 지사의 동의에서 그 논리를 맞춰가는 게 아니고 비판적 관점에서 얘기해도 신분이 보장될 때 경기개발연구원이 사실은 제 역할을 할 수 있는 겁니다. 그렇습니까, 안 그렇습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 충분히 이해합니다. 
</p>
<p><b>○ 위원장 강득구 </b> 그런데 우리 원장님은 아니라고 얘기하지만 대부분 내용들이 일편향이에요. 그러면 저희 입장에서는, 우리 의회 입장에서는 다양성이 존중돼야죠. 연구원들의 창의성들, 연구원들의 개별 가치 이런 걸 무시하는 게 아닙니다. 그런 것 100% 다 존중해 줘야죠. 그렇지만 다양성이 존중되고 다양성이 보장되고 이랬을 때 비로소 우리 연구원이 좀 더 큰 틀에서 균형적인 경기도의 미래를 준비할 수 있는 역할들을 하는 거지, 그런 것 아닙니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 충분히 이해하고요. 다 위원님 지적에 제가 동의합니다. 딱 한 가지만 제가 위원장님한테 드리고 싶은 얘기는요. 그렇다고 해서 예산을 깎자는 말씀보다는 우리가 좀 더 객관적으로 그리고…….
</p>
<p><b>○ 위원장 강득구 </b> 아니, 우리가, 경기개발연구원에서 극단적으로 나가면 우리가 할 수 있는 것도 극단적인 선택일 수밖에 없다라는 겁니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 옳은 말씀이에요. 제가 드리고 싶은 말씀은 앞으로 우리 기획위원회 위원님들도 아젠다를 저희들한테 주시고 필요에 따라서는 글을 써주셔도 좋습니다. 이렇게 해서 저희가 CEO REPORT를 보다 다양화하고, 아까 적절한 표현을 쓰셨는데, 그렇게 해서 이게 경기개발연구원의 인지도와 중요성을 높일 수 있는 그런 일종의 말하면 출판물로 이게 더 발전할 수 있도록 도와주시면 더 좋겠다는 말씀을 드리고자 하는 겁니다.
</p>
<p><b>○ 위원장 강득구 </b> 경기개발연구원이 궁극적으로, 예를 들면 김문수 지사가 잘하는 부분도 있고 못하는 부분도 있고 의회가 잘하는 부분도 있고 못하는 부분도 있고 그렇잖아요. 그렇죠? 그러니까 경기도의 도정 전반의 착시를 막아주는 레이더 역할을 해야 됩니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 맞습니다.
</p>
<p><b>○ 위원장 강득구 </b> 그게 궁극적인 지향점이 돼야 됩니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 제가 그런 관점에서 한 가지 더……. 여기 CEO REPORT가 있고 또 발행하는 정기간행물이 있죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> Policy Brief인가요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. Policy Brief라고 하는 게 있습니다.
</p>
<p><b>○ 위원장 강득구 </b> 거기 보니까 이런 얘기가 나왔더라고요. 중국 17기 5중전회 주요 논의사항과 시사점, 북한 제3차 당대표회의 분석과 전망 이런 내용들이 있더라고요. 그래요, 안 그래요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제목을 제가 놓쳤습니다. 죄송합니다.
</p>
<p><b>○ 위원장 강득구 </b> 자료에 보면 중국 제17기 5중전회 주요 논의사항과 시사점, 북한 제3차 당대표회의 분석과 전망 이런 것들이 있더라고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 위원장 강득구 </b> 그래서 제가, 이건 어떻게 보면 경기도를 벗어난 주제들이잖아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희 동북아연구센터가 대북관계를 주로 하되 그것과 관련된 동북아, 중국이죠. 대중관계까지 연구를 하는 책무를 받았습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 제가 서울시랑 인천의 사례를 한번 봤어요. 그랬더니 사례를 보니까 서울시와 인천시 같은 경우는 내용이 다르더라고요. 제가 보기에는 이 내용이 경기도가 다루기에는 적합하지 않아 보이는데 원장님은 동북아센터 얘기를 하시면서 지금 그럴 수도 있다는 것 아닙니까? 그죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그러니까 동북아센터는 말하자면 경기도 현안하고 많이 관련된 이슈를, 결국 다 연결돼 있는 이슈를 다루는 거죠. 
</p>
<p><b>○ 위원장 강득구 </b> 그런 부분도 있고 경기도와 연관된 부분, 연계된 부분 이런 부분들은 좀 긍정적으로 생각해요. 그런데 문제는 뭐냐 하면 현행 지방자치법 제3조2항에 보면 “특별시, 광역시도, 특별자치도는 정부의 직할로 두고…….”라고 정해져 있어요. 그리고 동법 제11조제1호를 보면 외교, 국방, 사법, 국세 등 국가의 존립에 필요한 사무는 처리할 수 없도록 규정돼 있어요. 중국 17기 5중전회나 예를 들면 북한 제3차 당대표 같은 문제는 외교와 국방의 문제란 말이에요. 이건 국가의 존립에 필요한 사무에 해당하기에 제가 보기엔 경기개발연구원이 나서기에는 좀 부적절하다고 봐요. 그런데 문제는 뭐냐 하면 제가 이 자료를 드렸는데…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다, 무슨 말씀인지.
</p>
<p><b>○ 위원장 강득구 </b> 경기도나 서울시, 인천시 개발연구원 운영에 관한 조례입니다. 그런데 사업에 보면, 여기 경기도만 사업에 2항에 보면 “국가, 주요현안 사항과 제도개선에 대한 조사ㆍ연구”라고 나와 있습니다. 서울시나 인천시는 그런 내용이 없어요. 경기도만 두고 있어요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은 의회……. 
</p>
<p><b>○ 위원장 강득구 </b> 그런데 이게 2008년도 12월 30일입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이것은 저희가 와서 보니까 수도권 규제 문제가 가장 첨예한 이슈였습니다. 얘기를 하다 보면 수도권 규제 문제가 국가문제 아니에요?
</p>
<p><b>○ 위원장 강득구 </b> 원장님 논리가 김문수 지사가 하는 논리랑 똑같아요. 그러니까 2008년 12월 30일인데 이 부분에 대해서 제가 입장이 다를 수도 있지만 저는 예를 들면 이것을 근거로 해서 경기개발연구원이 국가적 아젠다 이런 부분에 대해서 본격적으로 이슈화를 내걸고 이런 것 같은데 저는 그래서 이 “국가”라는 용어를 삭제하면 저는 이게 경기개발연구원의 본연의 목적 그리고 김문수 지사, 개인 김문수, 잠재적 대통령 후보 김문수가 아니고 도정을 이끌고 있는 도정책임자 김문수, 이 도정책임자 김문수에게 도정 철학을 그리고 공약을 제대로 실천할 수 있고 만들어갈 수 있도록 해주는 경기개발연구원 본연의 역할로 돌아갈 수 있다라고 생각을 해요. 그래서 개인적으로 저는 그렇게 생각합니다. 그래서 이거를 내가 한번 논의해서 이 단어를 없애야 되겠다 이런 생각을 합니다. 어쨌거나 저는 경기개발연구원이 국가로 범위를 넓혀서 조사ㆍ연구를 하는 게 과연 효율적이냐? 저는 효율적이지 않다고 생각하고 맞지도 않다라고 생각합니다. 제가 자료를 보여드렸지만…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 주신 자료를 저도 보고 있습니다. 
</p>
<p><b>○ 위원장 강득구 </b> KDI나 국토연구원, 심지어 한국교육개발원 같은 데는 교육 관련된 부분만 전문적으로 하는데도 불구하고 우리 경기개발연구원보다 훨씬 예산이 많아요, 연구 인원도 많고. 그래서 저는 우리 경기개발연구원이 국책연구원 역할까지 한다라는 건 사실 정체성에도 맞지 않고 본래, 본인이 말씀하셨잖아요. 설립취지가 경기도민의 삶의 질 향상 거기에 포커스를 맞춰야 되는 거라고 생각합니다. 
</p>
<p style="padding-left:1.2em">  지금 김문수 지사가 어디 가든지 항상 하는 얘기가 있습니다, 재정 악화. 또 우리 경기도의 가장 큰 문제 뉴타운 문제 또 다문화 가족. 또 김문수 지사가 항상 하는 얘기 있습니다. 육아서비스 확충, 교통시스템 문제 또 GTX 이런 다양한 해결과제가 있는데 굳이 국가문제까지 경기개발연구원에서 나름대로 고민하고 대안을 내놓는다! 제가 보기에는 현실적인 조건도 맞지 않고 정체성에도 맞지 않고 지향점에도 맞지 않습니다.
</p>
<p style="padding-left:1.2em">  그리고 실제로 연구원 5명 가운데 1명꼴 연구량이 연구원에 정해진 것보다 더 많은 걸로 알고 있습니다. 오지랖 넓게 여기저기 연구하는 사업을 이제는 좀 재조정을 해야 됩니다. 그래서 한정된 인력과 정해진 예산으로 효과를 거두려면 선택과 집중을 해야 됩니다. 그래서 우리 경기개발연구원이 서울시정개발연구원처럼 서울시에 대해서 고민하고 인천발전연구원처럼 인천시 문제에 집중하고 이래야지 저는 나름대로 훨씬 가시적인 성과물들이 나올 수 있다고 생각하고 본래 취지에 맞다고 생각합니다. 
</p>
<p style="padding-left:1.2em">  그래서 이번에 조례를 개정해서 경기개발연구원이 원래의 목적, 원래의 설립취지에 맞게 하기 위해서 조례를 개정하려고 하는데 원장님 생각은 어때요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 물론 이 조례는 기획위원회 위원님들의 도움으로 만들어진 거라고 알고 있습니다. 또한 바꾸시는 것도 여러분들이 바꾸신다면 바꿀 수 있다고 생각합니다. 
</p>
<p><b>○ 위원장 강득구 </b> 그렇죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그렇고요. 그러나 지금 제가 느끼는 것이 수도권은 이게 지방이라고 보기가 참 어렵습니다. 또 국가정책에 직접적인 영향을 받는 지역이고 제가 수도권 규제 완화 문제를 가지고 몇 년 고민을 하는 과정에서 느낀 것은 중앙의 국책연구원은 정부에 반하는 얘기를 할 수 없습니다. 혹시 여러분들 아시겠지만 수도권 규제완화 문제는 저희 연구원이 유일하게 그동안 주장했고 서울시정연구원도 별로 참여를 안 했어요. 말하자면 어부지리를 많이 얻은 셈이죠, 인천도 마찬가지고. 그래서 제가 이런 걸 하면서 느낌에 경기도 문제는 로컬문제로 자꾸 봐서는 답이 잘 안 나오겠다 하는 그런 고민을 했고 그런 과정에서 자연스럽게 이게 된 건데요.
</p>
<p><b>○ 위원장 강득구 </b> 우리가 경기도 문제를…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 조금만요. 그래서 이게 됐는데 만일 위원장님이 그런 생각이 강하시고 그렇게 해서 도에서 조례를 그렇게 만드신다면 저희가 따라가겠습니다. 그러나 경기도 문제를 하기 위해서 필요할 경우에는 우리가, 지금도 무슨 국가문제를 가지고 시간을 뺏기는 그런……. 그래서 도의 문제를 다루지 못할 정도로 시간을 쓰는 것도 아니고 국가문제는 많은 경우에 저희가 외부의 네트워크를 통해서 주로 하지 우리 박사들은 사실은 도정과 경기도 문제 때문에 여기에 신경 쓸 시간 사실 별로 없습니다. 그래서 이걸 어떻게 하면 외부의 네트워크를 활용해서 할 거냐 하는 차원에서 그동안 운영을 해왔습니다만 위원장님이나 위원님들이 이게 문제가 있다고 생각을 해서 만일 그것을 고치신다고 하면 저희야 어떻게 하겠습니까? 따라서 가는 수밖에 없지 않나 생각합니다.
</p>
<p><b>○ 위원장 강득구 </b> 원장님 말씀처럼, 말씀의 기조는 이런 것 같아요. 한국처럼 중앙정부 권한이 센 국가에서는 중앙을 모르고서는 지방정책을 연구할 수 없고 특히 수도권은 더하다 이런 거죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그런 측면이 없지 않아 있다 이런 생각입니다.
</p>
<p><b>○ 위원장 강득구 </b> 그렇다고 하더라도 우리는 경기도라는 틀거지 속에서 예를 들면 중앙정부의 정책이라든가 이런 부분들을 연계해서 고민해야 되는 거잖아요. 그죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그 점도 충분히 이해하겠습니다. 
