<p><b>○ 위원장 강득구 </b> 알겠습니다. 그러면 계속해서 추가질문을 시작하도록 하겠습니다. 김주삼 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김주삼 위원 </b> 군포 출신 김주삼 위원입니다. 어쨌든 경기개발연구원 행감 자리인데 어쨌든 우리 경기도나 상황에 따라서는 국가의 주요 의제에 대해서 이렇게 치열한 논쟁을 통해서 뭔가 각자의 견해들을 서로 나누고 그러는 자리가 참으로 좋습니다. 어떻게 정책감사를 하는 것 같은 그런 생각이 드네요. 어쨌든 저는 대단히 바람직하게 생각을 하고요. 
</p>
<p style="padding-left:1.2em">  아까 질의응답 과정에서 두 가지만 보충질의를 하겠습니다. 우리 원장님께서는 지금 현재 우리나라가 무엇으로 먹고산다고 생각하세요? 아니, 그냥 평소대로……. 그러니까 예를 들어 자동차 산업도 있고 예를 들어서 프랑스 같이 예술이나 문화를 팔아먹을 수도 없고…….
