<p><b>○ 김주삼 위원 </b> 네?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 기업 때문에 먹고산다고요.
</p>
<p><b>○ 김주삼 위원 </b> 그 기업의 근간이 되는 게 어쨌든 제가 얘기하는 것은 IT라고 생각하고 있거든요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> IT가 중요하고요. 그동안 우리가 키워온 산업이 있죠. 아까 자동차…….
