<p><b>○ 김주삼 위원 </b> 사실은 우리가 지난 2000년부터 10년 동안 우리가 주로 먹고사는 게 사실은 IT라고 저는 생각을 하고 그 부분은 일정 정도 동의를 하실 겁니다. 
