<p><b>○ 김주삼 위원 </b> 물론 그런 원리로 생각하면 단군할아버지 다 영향이죠.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> DJ 정부가 IT에 대한 센스는 상당히 있어서 그것을 아주 강조하고 묶고 해서 그걸…….
</p>
<p><b>○ 김주삼 위원 </b> 그렇죠. 결국은 박정희 대통령이 경제를 살렸지만 잘 아시겠지만 박정희 정권의 경제적인 플랜 어디서 만들었습니까? 장면 정부에서 만들었잖아요. 그 만든 것 그대로 박정희 대통령은 실행을 옮긴 거고.
