<p><b>○ 경기개발연구원장 좌승희 </b> 저는 박정희 대통령까지는 안 가고요…….
</p>
<p><b>○ 김주삼 위원 </b> 어쨌든 중요한 건…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 전두환 정부에서 뭔가 중요한 일이 있었다고 생각합니다. 
</p>
<p><b>○ 김주삼 위원 </b> 그렇죠. 그러니까 어떤 중요한 모티브를 잡아서 할 수 있는 게 정치하는 정권, 그 정권의 역할이라고 저는 봅니다. 그렇기 때문에 저는 동료 위원들 계속 얘기했지만 사실 김대중ㆍ노무현 정부의 경제적 실패를 얘기하시는 분들은 정말 저는 개인적으로 그렇게 생각합니다. 뭔가 균형 잡히지 않은 그런 경제논리가 아닌가 그런 생각이 듭니다. 
</p>
<p style="padding-left:1.2em">  그리고 위원장께서도 문제 제기를 했지만 어쨌든 저도 그 부분을 한번 짚으려고 했는데 지금 경기개발연구원의 주요 의제 중의 하나가 동북아 그래서 대중국ㆍ대북 문제. 그런데 현실적으로 대북문제라는 게 지금 여러 가지 연구목록도 내놓으셨는데 우리 경기도에서 대북문제에 대해서 주도적으로 할 수 있는 거 아무것도 없어요. 결국은 우리 위원들이 염려하는 건 결국 경기개발연구원이 또 다른 어떤 그림을 그리는 그런 게 아닌가 하는 부분에 대해서 염려를 합니다. 
</p>
<p style="padding-left:1.2em">  그리고 저도 지금 똑같이 서울시정개발연구원하고 비교를 해봤는데 사실 시정개발연구원에서 이런 동북아 문제, 대북 문제 그런……. 물론 개별적인 의제들은 나올 수 있었겠지만 전체적으로 이렇게 우리가 경기개발연구원에서 얘기하는 대로 3대 미션, 전략 이렇게까지는 나오지 않았어요. 제가 홈페이지 들어가서 확인해 보니까 거기는 순수하게 정말 말 그대로 서울시의 문제, 수도권의 문제 그런 부분들을 집중한 것 같아요. 그래서 저희 위원들이 얘기하는 부분은 원래 경기개발연구원의 고유 목적에 맞게 집중을 해달라 그런 의미입니다. 그러니까 그런 부분들을 좀 앞으로 함께 고민을 해서 그런 부분들이 반영이 됐으면 좋겠고요.
</p>
<p style="padding-left:1.2em">  그다음에 아까 REPORT에 대한 자부심이 우리 연구원께서 굉장히 많으신 것 같아서 참 보기에 좋았습니다. 어쨌든 학자적 양심에 따라서 본인의 결과물에 대해서 소신껏 얘기하고 도정에 반영되기를 바라고 안 되면 이런 표현이 어떨지 모르지만 나름에 따라서는 꼬라지도 낼 수 있고 저는 그게 바로 학자라고 보고 연구원들의 자세라고 봅니다. 그런 의미로 지금 제가 질문을 드리는 게 Policy Brief에 보면 이 Policy Brief는 정확하게 우리 경기개발연구원의 공식 견해죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네? 공식……. 
</p>
<p><b>○ 김주삼 위원 </b> CEO REPORT같이…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 같은 정신이라고 봐야 되겠습니다. 
</p>
<p><b>○ 김주삼 위원 </b> “이건 우리 견해가 아닐 수도 있다.” 그런 내용이 없어요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 들어가 있습니다, 앞에.
</p>
<p><b>○ 김주삼 위원 </b> 어디에 들어가 있어요? Policy Brief에 2009년 7월에 나온 것은 없습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 일부 안 들어간 게 있는 모양인데요. 
</p>
<p><b>○ 김주삼 위원 </b> 일부 안 들어간 건 그럼 맞네요. 공식견해고. 들어간 거는 공식견해가 아니고 개인적인 견해일 수도 있고.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇게까지……. Policy Brief가 나오게 된 배경이…….
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 조금 말하자면 하다 보니까…….
</p>
<p><b>○ 김주삼 위원 </b> 아니, 제가 견해다, 아니다 그걸 얘기하는 게 아니라 그만큼 우리 경기개발연구원에서 나름대로 연구결과물을 낸 송미영, 이기영, 백경오 박사님들의 합의에서 만들어낸 결과물이고 저는 이런 것들이 도정에 반영돼야 된다고 봅니다. 가장 대표적인 게 “4대강 살리기 사업과 후속사업 대응방안”이거든요. 이런 부분들이 반영돼야 하는데 실질적으로 반영이 지금 전혀 안 돼 있어요. 예를 들어서 이거하고 똑같은 4대강 살리기에 대해서 우리 경기도 비전기획관실에 나온 게 “한강살리기 사업에 의해” 한강살리기 사업 특강 자료입니다. 이거는……. 뭐 이거 보셨어요? 우리 원장님 보셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 비전기획관실에서 나온 건가요? 
</p>
<p><b>○ 김주삼 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 확실히…….
</p>
<p><b>○ 김주삼 위원 </b> “한강살리기 사업에 의해” 한강살리기 사업 특강 자료, 비전기획관.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 못 본 것 같은데요.
</p>
<p><b>○ 김주삼 위원 </b> 이 자료는 우리 경기개발연구원의 이 자료와 완전히 틀립니다. 전혀 틀려요. 그런데 제가 중요하게 여기서 말씀드리고 싶은 건 예를 들어서 어떤 정책에 대해서 그 정책이 이런, 아까 뭐 있죠? 가장 비근한 예로. 수도권, 세종시 문제 같은 경우 충분히 다른 견해를 가질 수 있습니다, 인문학적인 입장에서. 그런데 4대강 살리기 사업과 후속사업 대응방안은 과학을 통해서 얘기한 겁니다. 과학에 대해서는 이론이 있을 수가 없잖아요. 물론 새로운 가설을 놓고 새로운 학문적 입장을 얘기하는 게 아니고 기존에 모두가 공인되고 합의된 과학에 대해서는. 그런데 그 과학에 대해서 과학적 사실을 바탕으로 어떤 견해를 얘기했습니다. 이 부분에 대해서 유감스럽게도 김문수 도지사께서는 단 한마디로 거절을 했어요. 어떤 식으로 거절했냐 하면 제가 지난번 도정질문 때 김문수 지사께서 뭐라고 했냐 하면 “이 자료를 참고자료로 보는데 쓸 수도 있고 안 쓸 수도 있다.” 그리고 또 하나 재밌는 부분이……. 제가 그래서 이 자료에 의해서, 과학적으로 검증된 자료에 의해서 쭉 얘기를 드렸습니다. 예를 들어서 오염물질이 여주보 예정지에서 주입되면 보 건설 전에는 이포보 예정지에 BOD 기준으로 얼마까지……. 이거 전부 과학적 사실이거든요. 그런 부분을 쭉 말씀을 드리니까 단 한마디로 “그렇지 않습니다.” 그랬거든요. 이런 지사님의 견해에 대해서 우리 원장님, 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 고정보를 가정해서 한 거로……. 이게 아마…….
</p>
<p><b>○ 김주삼 위원 </b> 2009년 7월 달에 나온 거예요. 이거 보셨죠? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 보를 고정했을 때 생기는 문제를…….
</p>
<p><b>○ 김주삼 위원 </b> 이 견해에 대해 지사님이 단 한마디로 “그렇지 않다.” 얘기했을 때 우리 원장님 견해는 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그런데 이게 처음 나올 때 고정보라는 가정하에서 분석을 한 건데 그 이후에 보가 다 이동보로 바뀌었지 않나 싶어요.
</p>
<p><b>○ 김주삼 위원 </b> 이동보가요. 물만 좀 뚫어놓는 거, 물만 새나가게 하는 거예요. 그러니까 강약의 차이는 좀 있지만 같은 거예요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그러면서 이게 좀 기여를 했을 수도 있지 않을까요?
</p>
<p><b>○ 김주삼 위원 </b> 그렇죠. 기여를 했는데 중요한 것은 이런 과학적 사실에 대해서 김문수 지사는 그렇지 않다고 부정을 했거든요. 그러면 그 견해에 대해서 원장님 입장에서 어떠시냐고요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 위원님들이 연구원을 너무 높게 평가를 해주시는 게 아닌가.
</p>
<p><b>○ 김주삼 위원 </b> 아니요. 저는 평가가 아니라 사실만을 갖고 얘기하는 거예요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 애를 써서 하긴 하지만…….
</p>
<p><b>○ 김주삼 위원 </b> 혹시 송미영 박사 나와 계세요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 못 나왔을 텐데. 이기영 박사가 나와 있습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 아, 그래요? 이기영 박사님 나오셨어요? 
</p>
<p style="padding-left:1.2em">  제가 미리 전제로 말씀드립니다. 이거는 어떤 무슨 다른 목적이 있어서가 아니고 다만 우리 연구원들의 자신에 대한, 자신의 견해에 대한 확고한 신념이나 그런 걸 얘기하는 건데 이 연구결과에 대해서 우리 박사님께서는 확신을 가지고 계시는 거죠?
</p>
<p><b>○ 팔당물환경센터정책연구부장 이기영 </b> 팔당물환경센터 정책연구팀장 이기영입니다.
</p>
<p><b>○ 김주삼 위원 </b> 다른 건 얘기하지 마시고 이 내용에 대해서…….
</p>
<p><b>○ 팔당물환경센터정책연구부장 이기영 </b> 네. 그렇습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 들어가십시오. 됐습니다. 
</p>
<p style="padding-left:1.2em">  이렇게 저는 이런 확신을 가진 연구원들의 견해라는 건 단순한 인문적 견해로서 이럴 수도 있고 저럴 수도 있다가 아니라 과학을 바탕으로 한 견해거든요. 이런 견해조차도 김문수 지사께서는 본인의 생각하고 틀리다 그래서 그냥 일언지하에 아니라고 했을 때 우리 원장님의 입장이 어떠시냐고요? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 과학자가 아니라서요. 
</p>
<p><b>○ 김주삼 위원 </b> 이건 과학이 아니라 상식입니다. 과학자가 과학적으로 한 얘기 그걸 믿느냐, 아니면 김문수 지사는 정치인이십니다. 정치적 견해 그걸 믿느냐?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 아무리 과학이라고 해도 이 연구에는 몇 가지 가정이 들어가 있습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 틀릴 수도 있다는 얘기입니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 가정이 얼마나 현실적이냐에 따라서는 그 결과가 다를 수도 있죠. 
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 지금 그걸 얘기하는 게 아니고 연구원에서 나온 공식자료, 원장님의 책임하에 나온 겁니다, 결국은. 이렇게 내 책임하에 자료가 나왔는데 이 자료를 다른 기관에서 아니면 다른 누가 “그거 잘못된 거다.” 얘기했을 때 어떠시냐는 얘기예요. 꼭 이것뿐만이 아니고. 아까 어느 연구원 말씀대로 모독하는 거 아니에요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄요. 제가 드릴 수 있는 말씀은 연구는 연구한 사람이 책임하에, 아까 드린 대로 특별한 어떤 가정을 가지고 과학도 하는 것 아니겠어요? 그런데 그 가정이 현실적으로 맞느냐, 안 맞느냐 하는 건 논란의 여지가 또 있습니다. 그래서 여기의 경우에도 아까 말씀드린 대로 이동보냐, 아니냐 하는 그런 문제와 몇 가지 이런 게 있기 때문에…….
</p>
<p><b>○ 김주삼 위원 </b> 원장님, 제 정확한 질문의 의도는 그게 아니고요. 이거 내용이 맞다, 틀리다가 아니라…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 아니, 그렇게 질문을……. 제가 좀…….
</p>
<p><b>○ 김주삼 위원 </b> 제가 말씀드릴게요. 연구원에서 나온 자료입니다. 이거 연구하신 분들 이게 맞다고 확신을 갖고 계십니다. 원장님이 지금 같이 일하신 그 연구원께서.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그 연구의 기초가 된 가정하에서는 맞는 것이죠.
</p>
<p><b>○ 김주삼 위원 </b> 아니, 그러니까. 그런데 다른 사람이, 그건 꼭 김문수 지사라고 얘기 안 하겠습니다. 다른 제3자가 “이거 틀렸습니다.” 그럴 때 어떻게 하시겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄요. 제가 느낀 것은 지사님이 그 연구는 이러이러한 가정하에서 나왔기 때문에…….
</p>
<p><b>○ 김주삼 위원 </b> 그런 얘기 안 하고요. 그냥…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> “현실적으로 수용하기가 어렵습니다.” 했으면 훨씬 더…….
</p>
<p><b>○ 김주삼 위원 </b> “틀립니다. 그거는 그 사람 견해입니다.” 그렇게 얘기했어요. “그렇지 않습니다.”.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇다고 해서 제가 지사님이 이런 걸 다 보시라고 기대할 수는 없는 것이죠. 
</p>
<p><b>○ 김주삼 위원 </b> 하여튼 알겠습니다. 말씀, 의견 내기가 쉽지가 않지만 저는 여기서 제가 결론을 말씀드리면 아까 어느 연구원님께서 그렇게 자존심까지 상해 하면서 본인의 연구결과물을 자긍심을 갖고 지키려고 하는 이런 자세들 참 좋습니다. 그런데 그게 지사의 입맛에 맞는 것만 하지 마시고, 지사의 입맛에 틀리더라도 당당하게 지사님께 “그건 아닙니다. 지사님이 잘못 생각하신 겁니다. 정책을 바꿔야 됩니다.” 보완장치 여러 개 얘기했어요. 그런 것들 다 하셔야 된다고 말씀을 드려야 된다는 얘기예요. 그래야 우리 경기도가, 경기개발연구원의 본래의 역할이다 그런 얘기입니다. 그런 의미로 제가 말씀을 드렸습니다. 이상으로 질의 마치겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 감사합니다. 김주삼 위원님 수고하셨습니다. 지금 2시 20분 정도에 우리가 시작을 했는데 2시간 반 정도 시간이 지났습니다. 잠시 감사를 정회하고 15분 정도 쉬는 걸로. 그래도 되겠죠? 양해해 주신다 그러면. 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  네. 감사합니다. 잠시 정회를 하겠습니다. 
</p>
<p class=''ar''>(15시51분 감사중지)
</p>
<p class=''ar''>(16시09분 감사계속)
</p>
<p><b>○ 위원장 강득구 </b> 좌석을 정돈해 주시기 바랍니다. 그러면 감사를 계속하겠습니다. 
</p>
<p style="padding-left:1.2em">  먼저 김현삼 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 김현삼 위원 </b> 김현삼 위원입니다. 계속되는 행정사무감사에 좌승희 원장님을 비롯한 경기개발연구원 임직원 여러분께 감사드립니다.
</p>
<p style="padding-left:1.2em">  조금 전 정회시간에 김은경 박사님과 저희 위원들 간에 조금 전에 존경하는 권칠승 위원님께서 발언하신 주고받은 내용에 관한 오해가 해소되기도 하고 했습니다만 공식적인 행정사무감사 자리를 통해서 본 위원이 지적하지 않을 수가 없어서 말씀을 드리도록 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 죄송합니다만 목소리가 제가 잘 들리지 않아서요. 마이크가 좀…….
</p>
<p><b>○ 김현삼 위원 </b> 들리시나요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 
</p>
<p><b>○ 김현삼 위원 </b> 존경하는 권칠승 위원님께서 발언하실 때 김은경 경제사회연구부장께서 하셨던 발언 형식에 대해서 위원장님께서 문제 제기를 하셨습니다만 제가 좀 더 보충해야 되겠다 싶어서 말씀을 드리도록 하겠습니다. 
</p>
<p style="padding-left:1.2em">  경기개발 소속 연구원은 연구원으로서 당연히 아이덴티티가 있고 강한 프라이드를 갖고 있다라는 것에 대해서, 강한 프라이드를 갖는 거에 대해서 동의를 합니다. 그리고 그런 것들이 연구의 자율성과 창의성으로 이어져야 된다라고 저도 생각을 하는 거죠. 그런데 지금 이 자리는 천이백만 경기도민을 대신해서, 대의해서 저희 위원들이 경기도의 산하 출연기관을 감사하는 행정사무감사 자리입니다. 그런데 태도의 문제뿐만 아니라 답변하실 때 보면, 제가 몇 가지 써봤어요, 그분 발언하실 때. “저를 무시하는 발언이다.” 또는 “헌법재판소에서 답변할 사항이다.”, “생각이 틀릴 수 있지 않겠습니까?” 이런 발언들을 하신다는 말이에요. 좀 전에 말씀드렸던 것처럼 연구원으로서 본인의 소신과 철학에 대해서 당당하게 발언하는 태도에 대해서는 저는 뭐 전혀 나무랄 생각은 없고 당연히 그래야 한다고 생각하지만 그러나 이 자리는 사인과 사인 간에 대화가 오가는 자리가 아니고 좀 전에 말씀드렸던 것처럼 천이백만 경기도민을 대의하는 위원들이 공식적으로 질문하고 질문을 받는 그러한 자리입니다. 그런데 김은경 박사님 답변 태도에서 제가 조금 과할지 모르겠습니다만 조금은 고압적이고 위압적인 태도를 느꼈다라고 한다면 어쩌면 본 위원만 그랬을 수도 있을지 모르겠습니다만 그런 태도를 받았어요, 느낌을. 우리 김은경 박사님, 프랑스에서 공부 많이 하고 오셨는데 앞으로 그런 태도에 대해서는 지양을 해주시는 게 좋을 것 같다. 우리 권칠승 위원님과 두 분 간에 대화하시는 과정을 보면서 제가 그런 느낌을 받았다라고 하는 것을 말씀을 드립니다. 우리 김은경 박사님, 어떻습니까? 
</p>
<p><b>○ 경제사회연구부장 김은경 </b> 앞으로 조심하도록 하겠습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 네, 알겠습니다. 질문드리도록 하겠습니다. 연구원이 진행했던 수탁연구과제에 보면 “2009년도에 수원지역 공공기관 이전부지 활용방안에 관한 연구” 이렇게 얘기했습니다. 그래서 연구비로 1,368만 원짜리 연구가 있던데 그런데 1년 후에 어떤 연구가 진행이 됐냐면 성남ㆍ안산ㆍ과천지역 공공기관의 지방이전에 따른 부지활용방안연구 이렇게 돼 있거든요. 그래서 이게 지역만 달리하고 1년 사이에 똑같은 연구가 진행이 됐어요. 그리고 이것도 연구비로 1,365만 원 계약이 돼 있던데 보기에 따라서는 거의 비슷한 연구매뉴얼을 가지고 1년 사이에 지역만 달리해서 연구가 진행된, 이게 679페이지에 있습니다. 지역만 달리해서 똑같은 연구매뉴얼을 적용한 것 아니냐 이렇게 볼 수도 있거든요. 우리 원장님, 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 도의회에서 요청이 있었다고 지금 제가 들었는데요. 앞에 한 게 주제가, 제목이 뭐였지요? 제가 잘 못 들었습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 수원지역 공공기관 이전부지 활용방안에 관한 연구였고 그다음 년도에 진행된 게 성남ㆍ안산ㆍ과천지역 공공기관의 지방이전에 대한 부지활용방안연구 이렇게 돼 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 위치가 틀리면, 제가 테크니컬한 것이 돼서 도시ㆍ계획연구부장한테 대신 답변을 부탁해도 되겠습니까? 
</p>
<p><b>○ 김현삼 위원 </b> 네, 그렇게 하시지요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이상대 박사입니다.
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 도시ㆍ지역계획연구부장 이상대입니다. 제가 답변을 드리도록 하겠습니다. 전자는 위원님 말씀하신 것처럼 수원지역의 공공기관 이전부지에 대해서 한 거고 그다음에 후자는 성남ㆍ안산ㆍ과천지역의 공공기관 이전부지 활용방안에 대해서 연구를 한 것입니다. 그런데 이것은 다른 연구하고 달리 어떤 이론적인 연구라든지 그런 것들을 거치는 것이 아니라 바로 부지를 어떻게 어떤 용도로 그리고 어떤 계획으로 활용하는 게 좋을까라는 것을 연구한 것이기 때문에 제목이 비슷하다고 해서 연구내용을 공통적으로 쓰는 부분은 그렇게 많지는 않습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 네, 알겠습니다. 그런데 제가 보니까, 제가 그 두 자료를 봤는데 연구의 과정 전체를 보면 매뉴얼이 사실 비슷해요. 매뉴얼이 비슷해서 제가 볼 때는 도입되어지는, 결론부분에 있어서는 물론 상당히 지역의 특성을 고려한 연구니까 결론부분은 상당한 차이가 있을 수 있지만 과정 전체적으로는 결론을 도출하기 위한 기제들, 장치들 이런 것들은 거의 비슷하더라고요. 그래서 물론 본 위원의 오해일 수도 있습니다만 경기개발연구원이 연구를 진행할 때 매뉴얼 관리를 제대로 잘 했으면 좋겠다. 혹시라도 이게 경기도의회에서 제가 볼 때는 수탁한 걸로 보여지는데 가급적이면 예산의 낭비가 없도록 해야 되지 않겠는가. 그런 조언을, 의회 내 연구단체에다 조언을 해줬을 수도 있지 않았겠는가 그런 생각을 제가 해보게 되는 겁니다. 
</p>
<p style="padding-left:1.2em">  우리 이상대 연구원님, 기왕에 나오셨으니까 제가 질문 더 드리도록 하겠습니다. 얼마 전에 경기도의회 1층 대회의실에서 경기도종합발전계획 수립 연구에 관한 발표회 있었지요?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 그렇습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 그때 발표할 때 거기 참여했던 분들로부터 어떤 건의사항이나 또는 지적사항이 있었습니까? 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 그때 일곱 분의 의원님께서 지적을 하셨습니다. 그래서 주요 지적내용을 보면 경기도만의 어떤 정체성을 나타낼 수 있는 그런 계획이 됐으면 좋겠다라는 그런 주문을 주신 분도 있고 그다음에 시군과 협의를 강화했으면 좋겠다. 그다음에 또 교육청하고 협의를 진행해야 되지 않겠느냐 그런 의견도 있었습니다. 그리고 맨 마지막으로는 계획수립 승인을 서두르지 말고 도뿐만 아니라 다른 의견들을 많이 받아서 천천히 계획을 수립했으면 좋겠다는 그런 지적이 있었습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 그날 특히 그 지적했던 의원님들 말씀을 들으면서 제가 공감했던 것 중에 하나가 교육청과 아무런 협의 없이, 한 번도 협의가 없었지요? 이 연구과제를 수행하는 과정에서.
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 그렇습니다. 교육청하고는 그랬습니다.
</p>
<p><b>○ 김현삼 위원 </b> 한 번도 그 협의과정이 없이 2020 경기도종합계획이 수립되고 있는데 이게 끝나는 시점이 내년 2월 달인가요? 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 지금 일정으로 봐서는 저희들 계획안 자체는, 초안 자체는 저희들이 한 12월 초 정도 되면 끝을 내려고 합니다. 물론 초안이 끝났다는 거지 계속 또 위원님들, 특히 도시환경위원회 위원장님하고도 연찬회 같은 걸 하기로 했고요. 그다음에 아까 기획위원장님께도 말씀을 드렸습니다. 그리고 또 시군하고 이번 주 들어서도 계속 5차 협의 중에 있고요. 그리고 이 승인날짜는 국토부에 달려 있습니다. 국토부가 제 생각으로는 한 3, 4월 정도까지 갈 것으로 예상하고 있습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 그래서 저는 이게 우리 경기도 입장에서 보자면 경기도가 자체적으로 광역단위 계획을 처음 세우는 거지요, 법정계획을.
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 그렇습니다.
</p>
<p><b>○ 김현삼 위원 </b> 그래서 대단히 중요한 그런 연구과제라고 보여지는데 조금 전에 이상대 박사님께서 말씀하셨던 것처럼 연구과정에서, 이를테면 우리 경기도의 아이덴티티가 정확히 실렸느냐, 반영이 됐느냐 또는 31개 시군구와의 어떤 의견수렴과정, 의사수렴과정이 좀 미흡했다 또는 경기도교육청과의 협의과정이 전혀 없었다 이런 지적들에 대해서 그날 우리 이상대 박사께서 뭐라고 답변하셨냐면 “그런 과정을 거치겠다.” 이렇게 답변하셨는데 내년 3, 4월경, 그러니까 국토부로부터 최종 승인을 받는 시기가 내년 3, 4월이면 그렇게 많은 기간이 남아 있지 않은데 이런 지적됐던 내용들이 반영될 수 있나요?
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 네. 큰 문제는 없을 것 같습니다. 특히 교육청하고는 어떤 문제가 있었냐면 이게 도종합계획이 국토기본법에 의해서 수립되는 경기도의 최초 법정계획인데 국토기본법에 따르면 교육 부분은 사실 안 해도 됩니다. 그런데 경기도는 다른 도하고 다르기 때문에 저희들이 조금 차별화된 계획을 수립했으면 하는 생각을 가지고 있고 그래서 추가한 3개 중에 하나가 교육 부문입니다. 그런데 교육 부문 쪽에서 교육청하고 협의가 필요한 부분들은 주로 공교육 부분이라든지 그런 부분이 되겠습니다. 그래서 교육청하고는 이번 주에 얘기를 해서 아마 다음 주나 그 다음 주 정도면 협의회를 가질 수 있을 것 같습니다.
</p>
<p><b>○ 김현삼 위원 </b> 네. 그날 지적된 내용들이 시간이 별로 없기는 하지만 충분히 수렴되고 상호 의사소통되는 과정을 통해서 우리 경기도가 최초로 계획하고 있는 광역단위 종합발전계획이 정말 알차게, 더군다나 이게 보니까 연구비도 상당하더라고요. 한 6억 정도 되는 걸로 제가 얼핏 자료에서 봤는데 차질 없이 그리고 내용이 알차게 준비되어졌으면 하는 바람이고, 더불어서 그 과정에서 가능하다면 우리 기획위원회 위원님들한테도 한 번 더 의사수렴을 할 수 있는 그런 과정이 있을 수 있는지 내부적으로 검토해서 한번 그런 과정을 밟아보는 건 또 어떨까 이렇게 제가 제안을 드려봅니다. 
</p>
<p><b>○ 도시ㆍ지역계획연구부장 이상대 </b> 네, 그렇게 추진하도록 하겠습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 네, 수고하셨습니다. 짧게 마지막으로…….
</p>
<p><b>○ 위원장 강득구 </b> 네.
</p>
<p><b>○ 김현삼 위원 </b> 질문이라기보다는 제 의견에 대해서 말씀을 드리도록 하겠습니다. 경기개발연구원이 경기도 김문수 지사의 싱크탱크 아니냐라고 하는 논의가 계속되고 있는데요. 본 위원이 생각하기에 어쨌든 김문수 지사께서 대권을 추구하시는 정치인이다 보니까, 더군다나 좌승희 원장님과의 관계나 이런 걸로 봤을 때 적어도 김문수 지사가 경기도지사직을 수행하는 동안에는 계속해서 그런 의혹 내지는 그런, 어쩔 수 없을 것 같습니다. 그것은 천연이다 이렇게 생각이 드는데요. 다만 중요한 것은 그럼에도 불구하고 그렇지 않으려고 하는 노력이 있어야 된다 이렇게 보여지는데 조금 전에 존경하는 몇몇 위원님들께서 세종시 발언이랄지 또는 공무원 대상 교육할 때 DJ, 노무현 정부에 대한 일종의, 저희들이 보기에는 폄하발언들 이런 걸 쭉 보면서 우리 좌승희 원장님께서 가끔 글을 쓰시거나 또는 어디 가서 발표를 하실 때 어쩌면 그런 의혹들을 불러일으킬 만한 정치적 발언들, 정치적 수사가 짙은 그런 발언들을 하시는 것 아닌가. 그럼으로 인해서 오해가 더욱더 증폭되고 커지는 것 아닌가 이런 생각도 있는 거거든요. 그래서 향후에 어디 가셔서 발언을 하실 때 단정적인 어떤 정치적인 수사 이런 것들은 가급적이면 피해 주시는 게 세간의 그런 오해를 푸는 데 있어서 도움이 되겠다 이런 말씀을 드리고요.
</p>
<p style="padding-left:1.2em">  제가 경기개발연구원 홈페이지를 들어가서 보니까 첫 화면에 이번 달 행사 쭉 보니까, 첫 번째, 두 번째 행사를 클릭해서 보니까 전부 다 서울에서 행사가 열리더라고요. 첫 번째, 두 번째 행사명이 정확히 기억이 안 나는데 하여튼 경기개발연구원 화면 첫 페이지 들어가면 나와 있는 행사의 첫 번째, 두 번째가 전부 다 서울에서 열리는 것으로 돼 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 다문화가정의 문제, 서울대학교 호암에서 했습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 그래서 경기개발연구원에서 하는 행사가 왜 이렇게 서울에서 많이 열리는 건지, 이런 것 역시도 이를테면 충분히 경기도에서도 할 수 있는 주제라고 제가 생각이 드는데 서울에서 많이 행사가 열리다 보니까 이것 역시도 정치적 편향 내지는 오해를 불러일으킬 수 있는 그런 소지가 있다 이런 말씀도 드리고요.
</p>
<p style="padding-left:1.2em">  그다음에 비전을 보니까 “대한민국을 움직이는 중심 브레인” 제가 그래서 다른 지역을 찾아봤어요. 이를테면 서울시정개발연구원 같은 경우 보니까 “글로벌 경쟁력을 갖춘 도시종합 연구기관”이라고 해서 자기 비전을 세웠더라고요. 인천발전연구원 같은 경우를 보니까 “글로벌시대를 이끌어가는 정책연구기관” 이렇게 돼 있고. 제가 KDI를 봤습니다. KDI를 보니까 우리 경기개발연구원하고 비슷해요. 저희 경기개발연구원의 비전이 “대한민국을 움직이는 중심 브레인, GRI” 이렇게 돼 있는데 KDI, 이게 한국개발연구원인데 “국가발전을 선도하는 연구기관” 이렇게 돼 있어요. 조금 전에 존경하는 강득구 위원장님께서도 자료를 통해서 저희 경기개발연구원의 목표 이런 것들을 말씀하시면서 국가라고 하는 부분에 대해서 강조를 했었습니다만 ‘이게 과연 경기개발연구원의 비전으로서 맞는 거냐?’ 이런 생각이 드는 거거든요. 이게 대한민국을 움직이는, 이게 듣기에 따라서는 상당한 정치적 함의가 내포된 그런 의미로 충분히 받아들일 수 있고 해석이 가능한 그런 비전이라는 말이지요. 그런데 서울 같은 경우나 인천 같은 경우는 그야말로 서울시정, 인천시정에 초점을 두고 자기 비전을 세운 것을 보고 우리 경기개발연구원의 비전이 너무 국가적 목표에 초점이 가 있는 것 아닌가 이런 생각이 들었거든요. 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 답변을 드릴까요?
</p>
<p><b>○ 김현삼 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 경기도의 비전 중에 글로벌 인스피레이션(Global Inspiration)이라는 말이 있지요? 많은 사람이 “경기도가?” 그렇게 얘기는 하지만 전 괜찮은 비전이라고 봐요. 이것은 손학규 지사 때 만든 거지요. 김문수 지사가 지금 “경기도는 대한민국의 미래를 엽니다.” 이랬잖아요? 그리고 또 하나 더 나아가면 저는 다른 어느 지방연구원, 어느 국책연구원하고 비교해도 우리 연구원은 아주 독특하다고 봅니다. 천이백만 인구를 갖고 있는 모든 산업분야를 다 포괄하는 지역은 대한민국의 유일한 데가 경기도예요. 하나의 국가라고 봅니다. 그런 의미에서 저는 좀 더 크게 문제를 보고 국가의 장래까지도 생각하면서 해야지 이게 우리가 시정개발연구원을 뛰어넘고 정말…….
</p>
<p><b>○ 김현삼 위원 </b> 그런데 예를 들면 조금 전에 좌승희 원장께서 표현하신 그런 부분들을 이를테면 요즘 유행하는 네이밍으로 하면 “글로벌화된” 이렇게 표현할 수도 있는데 굳이 이것을 “대한민국”, 우리 헌법상에 국가 명칭이 대한민국 아닙니까? 그러다 보니까 이것이 그렇지 않아도 경기개발연구원의 위상과 역할에 관해서 정치적으로 많은 논란과 오해가 있는데 비전마저도 이를테면 “대한민국” 이렇게 딱 정형화해서 네이밍을 하니까 이게 오해를 불러일으킬 수 있는 소지가 있는 것 아니냐. 조금 전에 좌승희 원장께서 말씀하신 경기개발연구원의 목표, 취지 저는 충분히 동의가 됩니다. 그런데 그런 것을 예를 들면 “글로벌화된”, 제가 한 가지 사례를 드는 겁니다만 인천 같은 경우도 그렇고 서울 같은 경우도 그렇게 표현을 했어요. 충분히 그렇게도 표현을 할 수 있는데 굳이 이것을 정형화해서 “대한민국” 이렇게 표현을 하는 특별한 이유가 있냐 이거지요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 특별한 이유가 있는 게 아니라 이게 사실은 우리 박사들이 태스크포스를 만들어서 만들어 온 겁니다. 제가 이거 이름을 찍어주지 않았습니다. 박사들이 이렇게 하겠다고 그러니까 “OK. 아, 이거 멋있다.” 그래서 하자고 그랬는데 위원님 얘기를 들어 보니까 이것도 조금 그런 면이 없지 않아 있는데 우리 홈페이지에 가시면 영문으로 돼 있는 것이 정확합니다. “지역 성장과 국가 번영과 그리고 그것을 통해서 글로벌 파트너십을 추구한다.” 이래서 우리가 경기도가 항상 앞에 있는데 우리가 경기도에 있다고 만날 경기도 울타리에서만 박사들이 생각하는 것은 그런 나름대로 또 문제가 있잖아요. 그래서 박사들이 한번 크게 생각하자 해서 만들어온 비전을 수용해서 이렇게 한 건데 좌우간 오해의 소지가 있다고 하면 앞으로 플레이를 좀 덜해서, 죄송합니다. 오해의 소지가 없도록 최선을 다해보겠습니다. 
</p>
<p><b>○ 김현삼 위원 </b> 제 질문을 정리하도록 하겠습니다. 경기개발연구원의 설립목표는 어쨌든 경기도민의 삶의 질 향상과 경기도의 최고 행정책임자인 김문수 지사의 철학을 반영하는 연구과제를 수행해 내는 데 있다고 생각합니다. 그 부분을 저는 부정하지 않고요. 그러나 그것이 행여 어쨌든 현직 도지사가 대권후보로 거론되는 마당에 불필요한 오해는 없어야 되겠다 이런 생각을 갖고 있는 거고 그것이 경기개발연구원 연구원들이 자율성과 창의성을 갖고 상상력을 발휘해서 연구할 수 있는 연구 분위기를 만드는 길 아니냐. 그런 측면에서 봤을 때 네이밍 하나를 할 때도 가급적이면 그런 오해를 불러일으킬 수 있는 그런 소지들은 사전에 차단하는 게 좋다 이 말씀드리면서 아까 모두에 말씀을 드렸습니다만 우리 좌승희 원장님은 본인이 실제 그렇든 그렇지 않든 우리 김문수 지사의 심지어는 정치적 멘토로까지 표현되는 기사를 제가 본 적이 있는데 좌승희 원장님의 발언 하나하나가 세간의 이목과 집중을 받고 있습니다. 그런 측면에서 불필요한 오해를 불러일으킬 수 있는 정치적 수사나 이런 표현들은 가급적이면 자제했으면 좋겠다 이런 말씀을 드리면서 제 질문 끝마치도록 하겠습니다. 감사합니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네, 잘 알겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 김현삼 위원님 수고하셨습니다. 다음은 박승원 위원님 질의하실 차례인데 우리 권칠승 위원님이 신상발언 신청을 하셔 갖고요. 권칠승 위원님 신상발언을 듣고 그다음에 박승원 위원님 질의할 시간을 드리겠습니다.
</p>
<p><b>○ 권칠승 위원 </b> 화성 출신의 권칠승입니다. 아까 제가 김은경 박사님하고 이야기한 것 갖고 자꾸 얘기가 나와서 좀 정리하고 싶은 생각에서 제가 신상발언 요청을 위원장님께 드렸습니다.
</p>
