<p><b>○ 박승원 위원 </b> 제 자료 온 거 보니까 광명지역연구 해 가지고 조그만 소책자 왔는데 광명지역 담당하시는 분은 이양주 박사님인 것 같은데.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이양주 박사가 지난번에 했습니다.
</p>
<p><b>○ 박승원 위원 </b> 오셨어요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 여기 와 계십니다, 이양주 박사. 
</p>
<p style="padding-left:2.4em">    (경기개발연구원장, 환경정책연구부장을 향하여)
</p>
<p style="padding-left:1.2em">  이리 나오세요.
</p>
<p><b>○ 박승원 위원 </b> 광명의 웬만한 것은 많이 하셨죠? 제가 간략하게 쭉 훑어봤는데 광명지역에 대해서 상당히 내용을 다 꿰뚫고 계시더라고요.
</p>
<p><b>○ 환경정책연구부장 이양주 </b> 환경정책연구부장 이양주입니다. 광명지역 연구 책임을 맡았었습니다. 
</p>
<p><b>○ 박승원 위원 </b> 제가 잠깐 내용을 훑어봤는데 광명지역에 대해서는 전반적으로 내용을 정확하게 훑고 계시더라고요.
</p>
<p><b>○ 환경정책연구부장 이양주 </b> 저희가 광명지역 연구를 하기 전에 광명시 제1차 환경계획 연구책임을 제가 했었거든요. 그래서 광명에 대해서 많이 알고 있다고 자부합니다. 
</p>
<p><b>○ 박승원 위원 </b> 그때 한번 뵌 기억이 나고요. 최근에 제가 집에 온 자료를 보니까 상당히 의미가 있어서……. 제가 간략하게 말씀드릴게요. 내년도에 예산을 세울 수 있으면 더 좋고요. 각 지역별로 지역 담당 연구하는 박사님이 정해져 있으면 그 연구진들하고 지역의 의원들하고 간담회나 토론회 할 수 있는 이런 것들을 마련해 주셨으면 하는 걸 연구를 해주셨으면 좋겠고요. 그렇게 해서 그 지역의 의원들하고 연구진들하고 간담회 할 수 있게끔, 그래서 지역현안에 대해서 구체적으로 토론할 수 있는 기회를 만들었으면 좋겠습니다. 어떻습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 제가……. 
</p>
<p style="padding-left:2.4em">    (경기개발연구원장, 환경정책연구부장을 향하여)
</p>
<p style="padding-left:1.2em">  들어가세요.
</p>
<p><b>○ 박승원 위원 </b> 박사님, 고맙습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 31개 시군을 다 각각 못 가더라도 인근 시군을 묶어서 관련된, 말하자면 시군의 광역적인 사업도 있고 그럴 수 있으니까 그런 관심사항을 중심으로 해서 연구원이 가서 같이 토론회 하고 그런 것을 활성화해 볼까 그런 계획을 가지고 있는데요. 지금 말씀하신 그런 안을 포함해서 저희가 지역연구라든가 지역과 협력할 수 있는 방안을 모색하도록 하겠고요. 위원님들 모시고……. 당연히 하게 되면 그 지역 출신 의원님들은 모셔서 대화를 같이하도록 하겠습니다. 
</p>
<p><b>○ 박승원 위원 </b> 예산 검토 좀 해주시고요.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 예산이요. 예산 많이 주시면 더 좋은데 그게…….
</p>
<p><b>○ 박승원 위원 </b> 정리하겠습니다. 경기개발연구원이 제가 와서 보니까 상당히 위상이 큰데요. 경기도의 정체성을 확보할 수 있는 형태 그리고 삶의 질에 가깝게 다가설 수 있는 그런 정책연구가 됐으면 좋겠다는 바람을 많이 갖고 있습니다. 너무 큰 틀에서만 다루는 게 아닌가 이런 안타까움이 있어요. 그래서 도민의 삶의 질을 높일 수 있는 그런 연구ㆍ정책과제들을 많이 했으면 좋겠다는 말씀을 드리면서 마치도록 하겠습니다. 이상입니다. 
</p>
<p><b>○ 위원장 강득구 </b> 박승원 위원님 수고하셨습니다. 다음 박용진 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 박용진 위원 </b> 박용진 위원입니다. 일단 원장님께 간단히 여쭤보겠습니다. 원장님은 2005년부터 지금 여기 계셨죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 2006년이요.
</p>
<p><b>○ 박용진 위원 </b> 아, 2006년. 아까 휴게실에서 잠깐 보니까 역대 원장님 중에서는 가장 재임기간이 긴 것 같습니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니까? 그것은 인지를 못했습니다. 
</p>
<p><b>○ 박용진 위원 </b> 오전에도 질의를 했었는데요. 저희가 우리 연구원이 아무래도, 경기개발연구원이 경기도정에 대한 전체적인 정책연구가 목적이다 보니까 원장님을 비롯한 주요 실장님, 부장님들이 대부분 연구원 출신들이죠? 그러다 보니까 원장님께서 혹시, 그래도 원장님은 경기개발연구원 전체의 경영을 책임지고 있는 것 맞죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 물론이죠.
</p>
<p><b>○ 박용진 위원 </b> 지방자치단체출연 연구원의 설립 및 운영에 관한 법률에 보면 “시ㆍ도지사가 필요할 때는 경영평가를 위한 운영회를 둘 수가 있다.” 이렇게 돼 있는데, 평가위원회를. 현재 경기개발연구원은 그런 위원회가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리 연구원을 평가하는 위원회요?
</p>
<p><b>○ 박용진 위원 </b> 네.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그거는 우리 연구원이 도 산하 공공기관을 평가하고요. 우리 연구원은 도에서 서울대학 경영대학에다가 용역을 줘서 그 경영대학이 와서 우리를 평가하는 시스템으로 돼 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 아, 그럼 1년에 몇 차례씩, 한 차례씩…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 한 차례지만 계속 한 몇 달에 걸쳐서 연간 평가를…….
</p>
<p><b>○ 박용진 위원 </b> 주로 어떤 분야를 많이 평가합니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 여러 가지 저 개인적인 성과와 평가를 비롯해서 기관의 성과, 평가까지 다 합니다. 
</p>
<p><b>○ 박용진 위원 </b> 관리평가도 합니까? 관리적인 측면도 하고 있습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 물론이죠. 연구에 대한 거, 경영에 대한 거 전체적으로 해서 하고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 일단 오전에 제가 부탁했던 자료를 받았습니다. 특별회계에서 운영되고 있는 보통예금에 대해서, 그다음에 일반회계에서 운영되고 있는 보통예금 잔액을 받았는데 역시나 상당수 많은 금액이 보통예금으로 운영되고 있습니다. 물론 강윤구 부장께서 자료 주실 때 여러 가지 사유가 있었다고 하지만 사실 그런 사유로 충분히 해소가 안 될 정도로 많은 금액들이 이자 한 푼 받지 못하고 보통예금에서 운영되고 있는 이 점은 반드시 시정돼야 된다고 생각합니다. 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 보통예금이 입출금이 자유로워서 예비금으로 아마 일부 가지고 있는 것 아닌가 싶은데, 알겠습니다. 지금 말씀하신 대로 가능하면 금리가 많이 나오는 쪽으로 운영을 하되 연구원 운영상 보통예금에 해야 될 부분이 있으면 최소화하면서 저희가 위원님 말씀대로 효율화하도록 하겠습니다. 
</p>
<p><b>○ 박용진 위원 </b> 제가 지금 받은 자료에 의하면 평잔 기준으로 50억 이상 보통예금으로 있는 경우가 1년에 네 차례, 다섯 차례 됩니다. 그런 점은 충분히 시정을 해야 된다고 생각하고요.
</p>
<p style="padding-left:1.2em">  또 한 가지는 존경하는 김현삼 위원님께서 오전에 질의를 하셨는데 당연직이사 중에 현재 기획위원장인 강득구 위원장님은 이사직에서 빠졌는데 그 사유 혹시 파악되셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄요. 그게 법적으로 안 된다고 해서, 법이 뭐가 새롭게 만들어져서 되지…….
</p>
<p><b>○ 박용진 위원 </b> 그게 올해 그렇게 법이 개정된 겁니까? 작년에요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 작년 말인가요?
</p>
<p><b>○ 박용진 위원 </b> 지금 김대원 경기도의회 의원 같은 경우는 올해 3월 16일까지 임기가 있었습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 그렇습니다. 
</p>
<p><b>○ 박용진 위원 </b> 법이 언제 이렇게 바뀐 거죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지방자치법 제35조제5항에 의해서 “지방의회 의원은 해당 공공단체의 관리인이 될 수 없으므로…….” 이게 아마 가장 중요한…….
</p>
<p><b>○ 박용진 위원 </b> 그게 언제 개정이 됐습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 2010년 3월 29일입니다.
</p>
<p><b>○ 박용진 위원 </b> 2010년 3월 29일 날.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 그래서 그때까지만 하고 그 이후에는 선임을 안 하신 거네요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 못 했죠.
</p>
<p><b>○ 박용진 위원 </b> 그러면 현재 당연직이사가 전체 4명이네요. 원장님하고…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 지사님.
</p>
<p><b>○ 박용진 위원 </b> 원장님하고, 당연직이사가 원장님 그다음에 도의회 기획위원장은 빠졌고 그다음에 경기도 기획조정실장 그다음에 한국씨티은행 본부장, 제일은행 본부장 총 4명입니다. 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 우리 개발연구원이 처음 생기고 나서 씨티은행, 과거에 경기은행이었죠? 경기은행하고 그다음에 제일은행이 우리 연구원에 출연한 바가 있어서, 물론 그것이 중요한 이유가 된 것 같은데 그 이후로 우리가 경기은행이 한미은행으로 바뀌어서 현재 씨티은행이 됐고요. 그다음에 제일은행은 SC제일은행이 됐는데 그 두 은행의 지점장이 계속 당연직이사를 하고 있어요. 당연직이사 네 분 중에 무려 2명이 은행 출신 지점장이 이사직을 계속 돌아가면서 하고 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 맞습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 맞습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그리고 또한 뒤에 선임직이사 중에도 농협 경기지역본부장이 계속 임기가 끝날 때마다 계속 연임해서 하고 있습니다. 혹시 지방자치단체출연 연구원의 설립 및 운영에 관한 법률에 따르면 임원 제6조2항 “원장을 제외한 임원은 비상근으로 한다.” 이 조항이 있고요. 제9조에 보면 “당연직이사를 제외하고 임원의 임기는 각각 3년으로 하되 연임할 수 있다.” 이렇게 나와 있습니다. 그러면 농협 같은 경우에는 지금 사실 농협 경기지역본부장이 인사발령에 따라서 바뀌긴 하겠지만 바뀔 때마다 계속해서 선임직이사를 하고 있습니다. 이것은 사실 사람만 바뀔 뿐이지 계속하고 있다는 얘기거든요. 과연 이게 법률에 따른 임원 인사가 맞다고 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 확인 좀 해야 되겠습니다. 
</p>
<p><b>○ 박용진 위원 </b> 책 2권 684페이지에 나와 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 농협이 그동안 도금고 역할을 했던 모양입니다. 그래서 제가 오기 전부터 관행상 이게 이사로 선임돼서 해왔는데 그게 지금까지 계속되고 있는 상황인데, 그렇고요. 두 은행 본부장은 아까도 말씀 올렸지만 초기에 설립할 때 기금을 냈기 때문에 기금을 출연한 자로서 당연직이사로 선임을 한 게 아닌가 싶은데요. 이것의 타당성이나 이거는 저희가 다시 한 번 검토를 해봐야 되지 않을까 싶네요. 
</p>
<p><b>○ 박용진 위원 </b> 다시 검토 당연히 해야 되고요. 지금 95년도부터 선임돼서 지금까지 무려 15년~16년 동안 제가 판단하기에도, 아까도 지적을 했지만 그렇게 많은 기금이 정기예금 또는 100억 단위가 넘는 돈이 보통예금으로 운영되면서 이 은행들이 취할 수 있는 수익은 계속 취하고 있다고 봅니다. 안 그렇겠습니까? 
</p>
<p style="padding-left:1.2em">  제가 예를 들겠습니다. 지금 작년 결산서를 보면 우리 개발연구원이 가지고 있는 회계 일반회계자금은 씨티은행, 운용자금 거의 전액입니다. 퇴직기금 전액은 제일은행, 기금 전액은 농협ㆍ제일은행ㆍ씨티은행, 수탁용역특별회계는 씨티은행ㆍ농협, 경기과학기술센터특별회계는 전액 농협, 이 세 은행이 모든 자금을 다 독식하고 있습니다. 이것과 지금 현재 선임하고 있는 이사들 이 관계는 저는 분명히 연관 관계가 있다고 봅니다. 그래서 우리 원장님께서는 1년에 한 번씩 경영평가를 받고 있다고 했는데, 제가 이 자리에서 권고를 드리겠습니다. 이걸 받아들일지 모르겠습니다만 저는 이 선임직이사가 다시 한 번 고려되고 현재 은행 지점장이 이사로 돼 있는 부분은 전체 다 교체가 돼야 된다고 생각합니다. 어떻게 생각하십니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저희가 검토를 해보겠습니다. 지금 이 자리에서 확답하기가 제가……. 좀 더 정보를 확인해서 이게 민간기관으로서 기금을 출연을 한 기관인데 이 사람들을 이사회에서 제외했을 때 어떤 관계, 일이 있을지 파악을 해봐야 될 것 같고요.
</p>
<p><b>○ 박용진 위원 </b> 기금을 출연한 사유에 대해서 제가 자료를 요청했을 때 분명히 출연목적은 정책개발연구와 지역사회 환원으로 돼 있습니다. 그런데 이들 은행들에게 계속 밀어주기 식으로 예치를 하면 이게 과연 출연목적에 맞겠습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그것은 제가 보기에 잘못된 점이 있으면 시정하도록 바로 가서 하겠습니다. 그 점에 대해서는 제가 하는데 그렇다 하더라도 똑같은 조건이라고 하면 저희 기관에 출연한 은행에 예치하는 것이 그렇게 문제가 될 수 있다고 생각하지 않습니다, 다른 조건이 다 같다면.
</p>
<p><b>○ 박용진 위원 </b> 출연한 기관에 예치하는 거는 그쪽도 도와줬으니까 우리도 도와줄 수는 있죠. 하지만 그렇게 큰 금액이 이자 한 푼 없는 보통예금에 몇 달씩 잠자고 있는 건 안 되죠. 제가 볼 때는 그동안 15년 동안에 출연한 10억 그 몇 배에 해당하는 수익을 이미 안겨줬다고 생각을 합니다. 아마 계산을 해보시면 나올 수 있을 겁니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 지적하시는 점에 대해서 그런 개연성이 전혀 없는 게 아니기 때문에 제가 충분히 이해를 하고요. 제가 검토를 해서 시정해야 될 점이 있으면 바로 시정하도록 하겠습니다. 
</p>
<p><b>○ 박용진 위원 </b> 관리 쪽에서는 강세훈 처장님이 최고 책임자인 게 맞습니까? 개발연구원에 언제 오셨습니까? 
</p>
<p style="padding-left:2.4em">    (<b>○ 강세훈 사무처장</b> 좌석에서 - 금년 1월 달에 왔습니다.) 
</p>
<p style="padding-left:1.2em">  올해 오셨죠? 강윤구 부장님께서는 언제부터 계셨습니까? 
</p>
<p style="padding-left:2.4em">    (<b>○ 강윤구 재정지원부장</b> 좌석에서 - 95년도부터 있었습니다.)
</p>
<p style="padding-left:1.2em">  우리 개발연구원 초창기 때 계셨죠? 그러면 초창기 때 경기은행하고 제일은행이 출연을 할 때 그때도 계셨습니까? 
</p>
<p><b>○ 재정지원부장 강윤구 </b> 재정지원과 강윤구입니다. 보고드리겠습니다. 출연 당시에는 도에서 설립계획을 세워서 출연금을 넘겨줬기 때문에 그 당시에는 제가 그 일에 관여하지 않았습니다. 
</p>
<p><b>○ 박용진 위원 </b> 관여는 안 했더라도 거의 시점이 같죠? 
</p>
<p><b>○ 재정지원부장 강윤구 </b> 94년도에 출연을 받았기 때문에요. 저희는 95년에 제가 파견을 왔다가…….
</p>
<p><b>○ 박용진 위원 </b> 지금 그 이후부터 계속 재정지원과에 근무하고 계신 거죠?
</p>
<p><b>○ 재정지원부장 강윤구 </b> 네. 그렇습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그러면 그 관계를 누구보다 더 가장 잘 알고 계시겠네요?
</p>
<p><b>○ 재정지원부장 강윤구 </b> 네. 그렇습니다. 
</p>
<p><b>○ 박용진 위원 </b> 혹시 그 사이에 이 두 은행이 이사직에서 빠진 적이 있습니까? 
</p>
<p><b>○ 재정지원부장 강윤구 </b> 없습니다. 
</p>
<p><b>○ 박용진 위원 </b> 없죠?
</p>
<p><b>○ 재정지원부장 강윤구 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 원장님은 반드시 이 점 다시 한 번 검토를 해주시기 바랍니다. 
</p>
<p><b>○ 재정지원부장 강윤구 </b> 제가 한 가지만 설명을 드려도 될지.
</p>
<p><b>○ 박용진 위원 </b> 네.
</p>
<p><b>○ 재정지원부장 강윤구 </b> 사실 저희는 기금을 관리할 때 각 은행 제1금융권을 대상으로 금리 제안서를 받아서 최고 높은 데만 갑니다. 그래서 이사진이다 그래 가지고 단 한 번도 그쪽으로 간 예는 없습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그게 전혀 연관이 없을까요?
</p>
<p><b>○ 재정지원부장 강윤구 </b> 저희는 보통예금하고, 항시 입출금이 자유로운 보통예금은 운영경비라 그래서 그것은 저희는 지정 금융기관이라는 걸 쓰고 있지 않기 때문에 거기가 타당하지 않다 그러면 언제라도 옮길 수는 있는데 계속 거기가 주거래 은행이 되다 보니까 그쪽으로 보통예금을 운용하고 있습니다. 
</p>
<p><b>○ 박용진 위원 </b> 그런데 지방자치단체 연구원의 설립 및 운영에 관한 법률에도 분명히 나와 있습니다. “이사는 정관에 명시된 자와 원장이 학계, 산업계 등의 추천을 받아 이사회 의결을 거쳐 지방자치단체장이 임명하는 자가 된다.” 그런데 여기는 계속 은행만 이사를 하고 있습니다, 경기도 직원 빼놓고는.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 글쎄, 그 점에 대해서는 제가 아까도 말씀을 올렸지만 출연을 했던 기관이기도 하고 그동안 관행상 그렇게 해왔기 때문에 제가 왔을 때도 그랬고 제가 왔을 때 출연을 했으면 이사를 할 자격이 있지 않겠느냐는 상식적인 수준에서 생각을 했는데 지금 박 위원님 지적하신 그 점을 제가 염두에 두고 앞으로 오해의 소지가 없도록 할 뿐만 아니라 필요하면 시정 조치를 하도록 하겠습니다. 
</p>
<p><b>○ 박용진 위원 </b> 반드시 시정되고 반드시 교체돼야 된다고 저는 생각합니다. 한마디만 더 하겠습니다.
</p>
<p><b>○ 위원장 강득구 </b> 네.
</p>
<p><b>○ 박용진 위원 </b> 2006년 이후에 경기도로부터 의뢰받은 보고, 그러니까 연구 건수가 제가 받은 자료로는 265건이 됩니다. 그중에서 경기개발연구원도 목표로 삼고 있는, 또 우리 김문수 지사도, 또는 국정에서도 가장 강조를 하는 일자리 창출과 관련된 연구는 단 9건에 불과했습니다. 퍼센트로 따지면 3.3% 정도밖에 안 되는데요. 말로는 일자리 창출, 일자리 창출 강조하시면서 여기에 대한 연구는 실질적으로 연간 두 차례 정도밖에 안 되는 것 같습니다. 4년 동안 9건입니다. 이런 이유가 일자리 창출이 중요하지 않아서인지, 아니면 개발연구원이 다른 쪽에, 다른 연구 쪽에 너무 신경을 쓰다 보니까 이쪽을 소홀히 하신 건지, 어떤 특별한 이유가 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 특별한 이유는 없고요. 꼭 일자리 창출을 위해서 연구한다 그래서 꼭 제목에 일자리 얘기가 들어갈 필요는 없죠. 우리 경기도 안에 산업단지라든가 지역개발 이런 것들은 전부 다 일자리하고 관련이 있고 더구나 나아가서 외자유치 문제, 수도권 규제완화 문제가 다 일자리하고 관련 있는 것 아니겠어요? 그래서 제가 보기엔 우리가 하는 일 자체가 경기도 경제하고 다 직결이 돼 있기 때문에 일자리 문제와 직ㆍ간접적으로 연결이 돼 있다는 생각을 하고 있습니다. 
</p>
<p style="padding-left:1.2em">  그리고 최근에 와서 일자리 문제가 구체적으로 아젠다로 등장한 것은 2008년에 세계 금융위기가 생기면서 국가경제가 많이 어렵고 이렇게 하니까 각 시도에서도 비상대책을 강구한다 이렇게 하면서 일자리 문제가 아주 맨 앞에 부각돼서 그게 모든 프로젝트에 헤드라인으로 들어가고 그렇긴 했습니다만 저희가 하는 많은 일이 저는 직ㆍ간접적으로 다 일자리하고 관련이 있는 게 아닌가 이렇게 생각을 합니다. 
</p>
<p><b>○ 박용진 위원 </b> 일자리와 관련이 있다면 거기에 대한 연구를 많이 하면 할수록 일자리도 많이 늘어나게 되면 좋겠죠, 현실은 그렇지 않지만. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 늘어나고 있다고 믿습니다. 
</p>
<p><b>○ 박용진 위원 </b> 아, 그렇게 생각하세요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 우리가 계량적으로 어떤 연구 때문에, 어떤 프로젝트 때문에 얼마 늘어났느냐 하는 것은 그렇게 정확하게 말씀드릴 수 없지만 우리가 하는 많은 일이 결국 일자리 창출로 이어지는 게 아닌가 하는 게 제 개인적인 생각입니다.
</p>
<p><b>○ 박용진 위원 </b> 그런데 본 위원이 최근에 본 자료에 의하면, OECD 보고서에 의하면 우리나라가 OECD 국가 중에서 경제 성장률은 거의 최고인데 고용은 거의 하위권에 있습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 고용 증가율은.
</p>
<p><b>○ 박용진 위원 </b> 고용 증가율은 거의 하위권에 있습니다. 경기도도 예외는 아니고요. 더군다나 본 위원이 최근에 사회적인 이슈가 되고 있는 사회적 기업, 취약계층이나 여성, 노인 그런 취약계층을 위한 일자리를 늘리는 게 국가적인 큰 화두가 되고 있고 우리 이명박 정부도, 이명박 대통령도 강조를 하고 있고 김문수 지사도 여러 포럼에 나가서 이야기를 하고 있습니다. 그런데 제가 사회적 기업에 대한 어떤 연구자료를 찾아보려고 했더니 개발연구원에서는 찾을 수가 없더라고요. 혹시 그쪽에 대한 연구 진행되거나 앞으로 하실 의향은 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 이게 업무가요. 우리 경기도에 미래복지재단이라고 있고 또 가족여성개발원이라고 있어서 그런 쪽에 약간, 여성 쪽입니다만 가족여성개발원은. 복지라든가 사회적 기업에 대한 것은 복지재단 쪽에서도 많이 하고 우리 연구원은 아주 이쪽으로 하는 박사가 지금 한 사람이 있는데 이런 모든 기능이 통합돼서 아실지 모르지만 가족……. 가족여성연구원인가요? 복지재단하고 합쳐서 만든다 그래서 그 기능이 많이 그리로 가리라고 생각합니다. 그래서 저희가 사회적 기업 문제에 대해서는 사실 솔직히 말씀드려서 그렇게 역점을 두지 못했다고 말씀드리겠습니다. 
</p>
<p><b>○ 박용진 위원 </b> 앞으로 일자리 창출, 전체적인 큰 틀에서도 중요하지만 특히나 우리 사회에서 소외당하고 취약계층, 일을 하고 싶어도 일을 할 수 없는 그런 사람들이 많은 부분 고용의 현장으로, 일터 현장으로 나와야지만 우리 경기도 전체적으로 성장의 발판이 될 수 있지 않을까 그런 의미에서 말씀드린 거고요. 거기에 대해서도 좀 많은 관심을 가져주기를 기대해 보겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잘 알겠습니다. 
