<p><b>○ 위원장 강득구 </b> 박용진 위원님 수고하셨습니다. 다음 임병택 위원님 질의해 주시기 바랍니다. 
</p>
<p><b>○ 임병택 위원 </b> 임병택 위원입니다. 오전 질의에 이어서 원장님께 여쭙고 싶은 말씀이 있습니다. 어찌됐든 매경 기사와 인터뷰가 있는데요. 제가 다시 한 번 말씀드리지만 우리가 광고비로 1,350만 원이라는 광고비를 주고 어찌됐든 경기개발연구원을 알리는 차원의 기사입니다. 그러면 우리가 광고주인 거죠?  
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇습니다. 
</p>
<p><b>○ 임병택 위원 </b> 광고주 입장으로서 최종본 검토하셨습니까, 안 하셨습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 최종본을 제가 검토했다기보다 우리 홍보실에서 한번 검토는 했습니다. 그런데 제가……. 저는 인터뷰하고서 나중에 책이 나온 다음에 봤습니다. 그런데 저희가 조금 소홀했던 게 소위 경기도 김문수 지사의 싱크탱크라고 하는 부분에 대한 인식이었습니다, 사실은. 저희는 그것을 그렇게 대단한 정치적인 문제와 연결시켜서 생각을 평소에 못해서 우리가 늘 하는 경기도지사, 경기도 싱크탱크 그리고 늘 하던 얘기라서 그렇게 생각을 했는데 그 점에 대해서 저희가 스크리닝을 미흡하게 한 게 아닌가 하는 생각이 들어서 앞으로는 이런 일이 있을 경우에는 특별히 저희가 조심을 하도록 하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 어찌됐든 기사도 대권 이야기로 끝나고 인터뷰도 대권 이야기로 끝납니다. 이 내용이 그래요. 대권 이야기. 그 기사 중에, 저는 그 점은 오전에 지적했기 때문에, 그 부당성은 지적했기 때문에 다른 문제를 여쭤보고 싶어요. “수도권 규제완화가 경기지사로서 주장할 때는 환영받을 만한 정책이지만 대선을 준비하는 입장에서는 대놓고 얘기할 수 있는 사안이 아니라는 것. 실제 대선에 김 지사가 수도권 규제완화 정책을 들고 나갈 경우 역풍을 맞을 가능성도 존재한다. 좌승희 원장도 이를 잘 알고 있다. 그래서 김 지사에게 수도권 규제완화와 관련된 얘기를 김 지사 스스로 밖에서 대놓고 하지 말라. 그 얘기는 원장인 내가 하겠다고 조언한 것으로 알려졌다.” 이게 기사의 마지막 부분입니다.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알려졌다.
</p>
<p><b>○ 임병택 위원 </b> “알려졌다.”를 강조하시는 이유도 제가 알겠습니다. 그 전에 “이를 잘 알고 있다. 좌승희 원장도…….” 이런 내용도 있습니다. 어찌됐든 이게 약간 정책적인 질문일 수도 있는데 수도권 규제완화가 우리 전 국민들의, 우리 대한민국 절대 다수 아니면 과반수 이상의 지지를 받는 정책만은 아니에요. 그죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 수도권 규제완화 문제 자체가 정치적인 문제죠.
</p>
<p><b>○ 임병택 위원 </b> 네?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 수도권 규제완화 문제가 이미 정치 문제가 돼 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 우리 국민들의 찬성도, 저 또한 경기도에서 살면서 합리적인 규제 완화에 대한, 뭐 동의합니다. 과연 합리적인 완화가 어느 정도 수준이냐에 따라서는 원장님과 제 생각이 다를 수가 있어요. 또 진영으로서는 다를 수가 있지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 어찌됐든 수도권 규제 철폐와 관련된 지사님의 주장이 대한민국 국민들 다수의 지지를 얻지는 못하죠? 그죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그렇죠. 제가 그걸 저희 연구원에 와서 주장도 많이 하고 해봤는데 그걸 주장하면 주장할수록 국회에서는 일이 더 안 되고 그러더라고요. 그래서 사실은 제가 그런 식으로 무슨 정치적인 그런 걸 떠나서 이 문제는 공개적으로 떠들어서 될 일도 아니고 사실은 이건 여러 가지 기술적인, 아까 말씀하신 대안을 잘 만들어서 어프로치 하는 게 옳지 않겠느냐는 그런 생각을 가지고 되었어요, 저도. 
</p>
<p><b>○ 임병택 위원 </b> 그래서 저는 국토균형발전이라는 의제와 수도권 규제 철폐라는 의제가 늘 부딪히는 것 같습니다. 부딪히는데 합의점을 찾는 게 정치고 또 우리들이 앞으로 해야 될 일인데. 그러니까 저는 원장님께 여쭤……. 원장님은 워낙 학식이 높으신 것 저는 충분히 인정을 하고요. 또 그렇게……. 그런데 개인적으로는 왜 국민들이 그렇게 절대다수……. 절대다수까지는 아니지만 다수가 수도권 규제 철폐에 대해서 일방적인, 왜 그렇게 두려워하실까라는 부분도 잘 헤아려주셔야 될 거라고 봅니다. 
</p>
<p style="padding-left:1.2em">  원장님도 저기 지역에서 오셨고 저 또한 지역에서 수도권으로 와서 사는 입장에서는 지방에 사는, 저도 지방대 출신입니다. 지방대 출신들 두려움이 있어요, 지방 출신이라는 것에 대한, 내가 여기서 먹고 살 수 있느냐에 대한. 그래서 저는 좀 이기주의적인 발상을 넘어서는 뭐가 필요하지 않겠느냐라는 젊은 도의원으로서 원장님께 드리는 또 하나의 견해입니다. 김문수 지사님도 대권후보로 나오셨을 때 그걸 마음 놓고 얘기 못해요. 역풍 맞으니까.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그러시겠죠.
</p>
<p><b>○ 임병택 위원 </b> 그런 취지죠. 그래서 꼭 국토균형발전을 얘기하는 사람들이 무슨 부족한 사람들은 결코 아니라는 건 좀…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 저는 그렇게 생각 안 합니다. 좋은 뜻을 가지고 다 하고 있다고 생각을 하는데…….
</p>
<p><b>○ 임병택 위원 </b> 그리고 또 하나 질문하겠습니다. 어찌됐든 저희 도의원들이 국정감사 관련 자료를 요구했고 연구원에서는 최선을 다해 숨김없이 보고를 하셨지요?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 한다고 노력했습니다. 
</p>
<p><b>○ 임병택 위원 </b> 저에게 주신 자료 979페이지 여론조사 실시현황 및 대행업체 관련된 자료가 있어요. 이 내용은 맞겠죠?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네. 맞다고 제가 말씀드려야 되겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 이걸 한번 봐주시죠. 
</p>
<p style="padding-left:2.4em">    (임병택 위원, 경기개발연구원장에게 자료 전달)
</p>
<p style="padding-left:1.2em">  보고 계시죠? 첫 번째는 제안요청서 2009년도 10월 경기개발연구원 기획조정실 정책분석팀에서 31개 시군별 여론조사, 경기도 주요 도정시책 효과에 대한 31개 시군별 여론조사, 소요예산 2억 4,000만 원입니다. 
</p>
<p style="padding-left:1.2em">  그리고 두 번째 드렸던 것은 우리 경기개발연구원 홈페이지 입찰공고에 나와 있는 입찰공고 결과보기, 입찰명 : 경기도 주요 도정시책 효과에 대한 31개 시군별 여론조사, 입찰등록 마감 : 2009년10월 23일, 위탁업체 선정결과 : 주식회사 21세기리서치앤시스템 이진봉, 담당자는 안병도 박사세요. 경기개발연구원에서 저희 경기도의회에 제출한 공적인 자료에는 2009년도 여론조사 실시현황이 5건, 이 중에 안병도 박사가 21세기리서치에 의뢰한 건 2건, 리얼미터 1건, 2009년도의 예산총액이 1억 원이 안 돼요, 2009년도 예산의 총액이. 그런데 본 위원이, 제가 찾아낸 자료에 의하면 2억 4,000만 원짜리 예산이 또 따로 존재해요. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 제가 구체적인 게 아직 다 확인이 못 돼 가지고요. 부원장이 대신 설명을 드려도 되겠습니까?
</p>
<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 이 과제와 관련해서 두 가지의 연구가 이루어졌습니다. 그래서 첫 번째는 31개 시군별 여론조사가 1억 9,900만 원 정도로 해 가지고 도에서부터, 비전기획관실로부터 저희가 수탁과제로 받아 가지고 그렇게 진행했던 그 내용에 대해서 입찰공고가 나가서 업체를 선정한 그런 내용이 되겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 여론조사를 어디서 했습니까? 비전기획관실에서 했습니까? 
</p>
<p><b>○ 부원장 조응래 </b> 아니, 거기서는 저희한테 용역을 줬고요. 저희가 그것을 수행하는데 저희가 수탁과제가 오면 그것을 가장 잘 수행할 수 있는 연구부서를 배정합니다. 그런데 이것은 여론조사의 내용이었기 때문에 이 여론조사 부분은 도 전체에 대한 그런 여론조사였고, 그래서 기획조정실의 정책분석팀에 여론조사를 담당하고 있는 안병도 박사가 연구책임을 맡게 된 그런 내용이 되겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 어찌됐든 여기에는 안병도 박사가 경기도민 주관적 생활지표 설문조사라는 여론조사도 했지요?
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 1,400만 원짜리.
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 안병도 박사가 경기도 전체를 대상으로 한 여론조사를 했어요. 
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 보고하셨지요? 또 안병도 박사가 어찌됐든 경기개발연구원 이름을 달고 경기도민을 상대로 해서 여론조사를 한 거지요? 
</p>
<p><b>○ 부원장 조응래 </b> 안병도 박사가 그 당시에 저희 연구원의 초빙연구원으로 있었고요. 거기 있으면서 주로 담당했던 업무가 정책분석팀에서 여론조사부분을 담당했습니다. 그래서 저희가 하고 있는 여론조사가 꼭 도민에 대한 생활만족도 수준뿐만 아니라 저희가 행정사무감사 자료에 낸 여러 가지 조사들을 하는데 그러한 부분들에 있어서 주민기피시설 같은 경우는 전문분야이기 때문에 그것을 담당하는 박사하고 같이 협의를 해 가지고 여론조사항목은 어떻게 구성하고 이런 것들을 아이디어로 주는 그런 여론조사도 있고요. 본인이 직접 하는 그런 여론조사도 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 저는 했냐, 안 했냐 문제지요. 제가 한 장을 더 드렸잖아요? 경기개발연구원 이름으로 이 여론조사 결과가 책자까지도 나왔어요. 그죠?
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 우리 경기개발연구원 전자도서관에 이 책자까지도 올려져 있습니다. 그렇지요?
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 제가 오전에 질문을 드렸던 답변에 안병도 박사, 물론 김문수 지사와 특수관계인이기는 하지만 경기개발연구원에서 그분 전문분야인 여론조사를 준 게 소액이기 때문에 그 정도는 봐줘도 되지 않느냐라는 식의 답변이 있으셨어요. 
</p>
<p><b>○ 부원장 조응래 </b> 네. 그러니까 저희가 지금 저희 연구원 예산으로 하는 여론조사는 총액이 1억 정도의, 대충 보통 한 1,500만 원, 평균적으로요. 많이 드는 건 한 2,000만 원이 넘어가기도 하지만 보통 한 1,500만 원짜리 여론조사를 한 7, 8개를 매년 하기 때문에 그런 정도의 예산을 잡는데 이 케이스 같은 경우는 워낙 예산이 많이 드는 조사다 보니까 도에서부터 수탁과제로 그런 사업의 필요성이 있을 때 저희가 도에서 별도예산을 받아서…….
</p>
<p><b>○ 임병택 위원 </b> 받지요? 받으면 그 예산이 누구 예산이에요?
</p>
<p><b>○ 부원장 조응래 </b> 도에서부터 받은 예산이 되는 거지요.
</p>
<p><b>○ 임병택 위원 </b> 경기개발연구원 예산이잖아요.
