<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 세입, 어찌됐든.
</p>
<p><b>○ 부원장 조응래 </b> 특별회계로 관리하고 있습니다.
</p>
<p><b>○ 임병택 위원 </b> 그렇지요, 특별회계. 어찌됐든 수입 아니에요.
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 누구 돈이에요? 경기개발연구원 돈이지요?
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 경기개발연구원 돈 가지고 여론조사한 것 아니에요?
</p>
<p><b>○ 부원장 조응래 </b> 뭐 그렇다고 볼 수도 있는데 저희는 보통 저희 예산을 특별회계라고, 별도로 수탁사업에 대해서는 특별회계로 관리를 하고 있기 때문에 수탁사업의 특별회계라는 것은 발주처의…….
</p>
<p><b>○ 임병택 위원 </b> 그러면 특별회계 용역비 지출현황이 있어야 되지요?
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 있습니까? 있어요?
</p>
<p><b>○ 부원장 조응래 </b> 지출현황이요?
</p>
<p><b>○ 임병택 위원 </b> 네.
</p>
<p><b>○ 부원장 조응래 </b> 그것은 저희 자료…….
</p>
<p><b>○ 임병택 위원 </b> 특별회계 용역비 지출현황 및 대행업체라는 이 요구자료도 있어요. 여기에 대한 답변서도 주셨어요. 거기 있어요? 경기도의회와 도의원을 그렇게 대충 보시면 안 됩니다. 여기에 보세요. 바로 몇 페이지만 넘기면…….
</p>
<p><b>○ 부원장 조응래 </b> 페이지수를 조금 알려…….
</p>
<p><b>○ 임병택 위원 </b> 특별회계 용역비 지출현황 및 대행업체라는 바로 그 뒤편에 나와요. 2009년도 28건.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 잠깐 기다려주세요.
</p>
<p><b>○ 임병택 위원 </b> 990페이지를 한번 봐보세요, 990페이지. 2009년도 특별회계 용역비 지출현황입니다, 대행업체. 여기 어디에 21세기리서치가 있어요?
</p>
<p><b>○ 부원장 조응래 </b> 991페이지 17번 보시면 2009년도 경기도정 주요시책 고객만족도 실사용역이라고 해서…….
</p>
<p><b>○ 임병택 위원 </b> 제가 그 이야기 하실 줄 알았어요. 보세요. 업체명이 어디예요?
