<p><b>○ 임병택 위원 </b> 계약일자가 어디예요? 계약일자가 며칠이에요?
</p>
<p><b>○ 부원장 조응래 </b> 이게 8월 27일로 돼 있습니다. 
</p>
<p><b>○ 임병택 위원 </b> 그러면 이 과업지시서에 계약은 언제 하신 거예요? 우리 경기개발연구원 입찰공고 홈페이지에 여기는 10월 23일 아니에요. 회사도 달라요. 21세기리서치라는 회사하고, 리서치앤리서치라는 회사도 커요. 
</p>
<p><b>○ 부원장 조응래 </b> 제가 이것은 자료를 조금 확인하도록 하겠습니다. 자료 확인한 다음에 다시 답변하도록 하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 네. 부원장님 앉으세요. 저는 오전에 안병도 연구원이라는 선임연구원이 김문수 지사와의 특수관계인이시고 그분에게 여론조사가 21세기리서치라는 안병도 연구원이 사장으로 있던 여론조사 회사에게 간 것에 대한 도덕적인 문제를, 입장을 여쭸는데 원장님과 부원장님의 말씀이 “그 정도야”라는 취지셨어요. 저는 참으로 어이가 없었습니다. 국민세금 3,000만 원이 “그 정도야”라는 수준으로 과연 받아들여져야 될지. 그래서 제가 직접 과연 안병도 선임연구원이 그 정도 여론조사밖에 하지 않았나 홈페이지를 뒤지는데 이게 있습니다. 여기에 올려져 있어요. 그래서 여쭌 겁니다. 저는 이게, 오늘 부원장님께서는, 부원장님!
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 부원장님, 앉아서 말씀하십시오. 비전기획관으로부터 수탁과제라고 말씀을 하셨고 그렇게 말씀하셨습니다. 과연 그 말씀이 위증에 해당되는지 안 되는지는 차후 결과를 보고 위원회 차원에서 논의를 할 생각입니다. 일단 저는 어찌됐든 경기개발연구원 이름으로 안병도 박사께서 경기도민을 상대로 2억 4,000만 원짜리 여론조사를 했음에도 불구하고 저희 기획위원회 위원들에게는 잘못된 보고를 하신 겁니다. 저는 그 부분에 대해서 준엄하게 지적을 하고 싶은 거고요. 도덕성 문제, 도덕적으로도 나쁩니다. 도덕적으로도 나쁘기 때문에, 저는 앞으로 원장님께서 얼마가 될지 모르겠습니다. 치우치지 마시고 우리 경기개발연구원 운영해 주십시오. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 이상으로 제 질문은 마치겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그리고 아까 확인하지 못한 것은 나중에 저희가 따로 보고를 올리도록 하겠습니다. 
</p>
<p><b>○ 임병택 위원 </b> 네, 그렇게 해주십시오. 위증여부는 꼭 가리도록 하겠습니다. 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 네.
</p>
<p><b>○ 임병택 위원 </b> 이상입니다.
</p>
<p><b>○ 위원장 강득구 </b> 임병택 위원님 수고하셨습니다. 다음 이승철 위원님 질의해 주십시오. 
</p>
<p><b>○ 이승철 위원 </b> 수원 출신 이승철 위원입니다. 장시간 힘들게 지금 하고 계신 여러분들께 하여튼 죄송하다는 말씀을 드리면서요. 한두 가지만 제가 궁금한 점만 여쭤보도록 하겠습니다. 의정연구센터 신원득 박사님 계시지요?
</p>
<p style="padding-left:2.4em">    (<b>○ 신원득 의정연구센터장</b> 좌석에서 - 네.)
</p>
<p style="padding-left:1.2em">  센터장님, 잠깐. 여쭤볼 게 있어서.
</p>
<p><b>○ 의정연구센터장 신원득 </b> 의정연구센터장 신원득입니다.
</p>
<p><b>○ 이승철 위원 </b> 부원장님! 일은 나중에 하세요. 
</p>
<p><b>○ 부원장 조응래 </b> 네.
</p>
<p><b>○ 이승철 위원 </b> 도의회 및 도의원에 대한 의정활동 지원현황이 저한테 있거든요. 자료로 주신 거. 혹시 실질적으로 반영된 게 있습니까? 
</p>
<p><b>○ 의정연구센터장 신원득 </b> 예를 들면 저희들이 2008년도에 지방의원 의정비 제도의 적정성 검토의견 같은 경우는 우리 의정비심의위원회 백업자료로 제출돼 가지고 우리 경기도의회 의원님들의 의정비 가이드라인을 제시하는 데 상당히 유익한 점이 있었고요. 또 하나는 경기도의회 의회자료실 제고방안은 2009년도에 한 건데요. 그 당시에 경기도 본청 자료실하고 의회자료실하고의 통폐합 움직임이 있었는데 저희들이 경기도 입법정보능력을 제고하기 위해서 이런 자료실의 존치 필요성에 대해서 저희들이 자료를 제출해 가지고 저희들이 적극 확대 개편한다는 그런 의견을 냈습니다. 그래서 앞으로도 경기도의회 자료실이 중심이 돼 가지고 DB 구축이라든지 이런 것을 할 것을 강력히 추진한 바가 있습니다. 또 하나는 저희들이 계속 각 정책과제라든지 하면 결론적으로 나오는 것이 크게 두 가지입니다. 여러분들 아시겠지만 우리 의원님들의 정책보좌인력 충원이라든지 또 사무처 인사기구독립이라든지 이런 게 있는데요. 이것도 현재 저희가 파악하기로서는 국회 입법안으로 올라가 가지고 행정안전위원회 상임위원회에 계류 중인 것으로 알고 있습니다. 그래서 저희들은 이뿐만 아니라 이런 여러 가지를 저희뿐만 아니라 학회라든지 이런 데서 발표도 하고 해서 학자들 중심으로 여론몰이도 하는 경향이 있고 그렇습니다. 이상입니다.
</p>
<p><b>○ 이승철 위원 </b> 박사님, 의정비에 대한 가이드라인을 대충 제시하시고 그랬는데 사실은 제가 7대 때는 처음에 우리 의정비 받았을 때랑 지금 의정비가 굉장히 많이 내려온 상태거든요.
</p>
<p><b>○ 의정연구센터장 신원득 </b> 네, 그렇습니다.
</p>
<p><b>○ 이승철 위원 </b> 경기도의회가 다른 데보다도 많다 이렇게 해 갖고 굉장히 많이 사실 내려왔습니다. 실질적으로는 총액 대비 보면 총 1,200만 원 정도가 내려온 거거든요. 월 100만 원 정도씩 내려왔는데 가이드라인 다 하셨겠지만 그 당시에 어느 정도로 정하신 겁니까, 가이드라인.
</p>
<p><b>○ 의정연구센터장 신원득 </b> 그 당시에는 얼마에 해당되는 가이드라인을 제시한 게 아니고요. 현재 중앙정부에서 제시하고 있는 산식이 있습니다. 의정비 기초산식을 보면 인구하고 그다음에 재정자립도 이런 것을 3개의 변수를 놓고 있는데 저희들은 이 산식 자체가 문제가 있다. 앞으로 의정비 제도를 계속 이런 식으로 하는 것은 산식 자체를 바꾸지 않고서는 우리 경기도 같은 경우는 굉장히 피해가 많다 저는 이런 생각을 가지고 있기 때문에 이 제도 자체를 저는 전면적으로 바꿔야 된다 이런 생각을 하고 있습니다. 그 당시에 저희들이 올린 대안은 이런 산식 자체의 변수를 다양하게 구성하자 그렇게 올린 적이 있고 이게 그동안에 그럼에도 불구하고 위원님 말씀대로 경기도가 두 번째 시행할 때는 서울시보다 높았는데 그다음 시행할 때는 1,200만 원 깎여 가지고 지금은 서울시보다 낮게 돼 있습니다. 이런 문제는 저희가 기본적으로 생각할 때 우리나라의 의정비 제도가 보수제도가 아니다. 그래서 차기에 내년도 2011년도 사업계획에 나오지만 내년 초에 저는 의정비 제도에 대해서 근본적인 수술을 가하는 이런 제도적인 시안을 마련하려고 합니다. 무슨 얘기냐면 현재와 같은 산식에 의해서 하는 제도가 아니고 소위 말해서 우리가 유급제로 됐는데 유급제의 본질에 맞게 보수제도의 전면적인 개편을 해야 되지 않는가. 중앙정부에서 말하는 산식을 준다든지 의정비심의회를 구성해서 의정비를 심의한다든지 이것은 지방자치 정신에 훼손되는 문제다. 그렇기 때문에 아예 동일한 선거에 의해서 취임되는 정무직 공무원인 국회의원이나 혹은 지방자치단체장과 같이 연봉제로 한다든지 실질적인 보수개념에 맞는 그런 의정비 제도를 선택해야지 현재와 같은 의정비 제도는 지방자치의 근본취지에 맞지 않다 이렇게 생각하고 이런 본질적인 문제를 수술하기 위해서 내년도에 의정비 제도 해 가지고 저희가 정책과제로 수행할 예정입니다.
</p>
<p><b>○ 이승철 위원 </b> 이게 선출직 의원이다 보니까 저희들이 이번에도 의정비를 동결을 했습니다. 그래서 마음대로 의원들끼리 정할 수도 없고 그래서 굉장히 애로점이 많이 있습니다. 그리고 어느 누구도 그것을 나서서 이야기할 수 있는 경우도 없고요. 저희들이 급수를 따지면 선출직 도의원으로서의 급수에 맞는 의정비는 절대 아닙니다. 지금 굉장히 턱없이 부족하거든요. 그래서 그것에 대한 대안을 지금 말씀 주셨는데 꼭 좀 그것에 대한 대안을 마련해 주십사 하는 말씀을 드리고요.  
</p>
<p style="padding-left:1.2em">  또 하나 보좌인력에 대해서도 연구를 쭉 하셨는데 아시다시피 지금 국회에다가 전체 광역의원님들께서 나서서 보좌인력에 대해서 꼭 필요하다라는 당위성을 설명드리고 국회의원들께 입법돼서 그게 꼭 통과될 수 있도록 저희들이 지금 노력하고 있는데 모 의원께서도 만약에 우리 도의원들한테 보좌인력이 1명 온다고 그러면, 지금 인건비나 이런 것에 들어가는 금액만 가지고 말씀하시는데 만약 보좌인력을 저희들이 받아서 운영하게 되면 그만한 운영하는 데 있어서 혈세가 만약에 새는 곳이 있다고 그러면 그것을 충분히 줄일 수 있는, 말로는 5,000억 정도씩 줄일 수 있지 않겠냐라는 말까지 나올 정도로 저희 의원님들이 굉장히 원하고 있는 부분들입니다. 이 부분에 대해서도 좀 대안마련이나 그것 좀 해서 발표를 해주시기 바랍니다. 
</p>
<p><b>○ 의정연구센터장 신원득 </b> 참고로 의정보좌인력 같은 경우는 지금 저희 경기도나 서울시 같은 경우는 우리가 의원님들의 예산 심의과정에서 보면 전반적인 수정예산의 삭감예산 비율을 보면 우리 의정보좌인력을 예를 들면 행정7급으로 쓴다든지 할 경우에 굉장히 의원님들의 의정활동, 예산활동 내용에 비해서 굉장히 미미합니다, 사실. 예를 들면 우리가 1년에 예ㆍ결산하지만 거기에 대해서 우리가 수정하고 삭감하는 그중에서 예를 들면 1%만 차지한다 해도 의정보좌인력을 운영할 수 있다 이렇게 됩니다. 그래서 제가 그렇지 않아도 한 달 전에 우리 행정안전부의 선거의회과 계장, 과장하고 간담회가 있었는데 그분들하고 의정보좌인력이라든지 그다음에 사무처 임면권이라든지 이에 대해서 논의한 바가 있습니다. 그때 나온 얘기가 경기도하고 서울은 충분히 이해가 가는데 지금 재정자립도가 낮은 또 다른 자치단체에서는 좀 반대하기 때문에 여기에 대한 절충점을 찾아야 이게 해결되지 않느냐 이런 대화가 오고 갔습니다. 그래서 제 개인적인 생각으로는 조만간에 바람직한 결과가 나오지 않을까 이런 생각을 가지고 있습니다. 
</p>
