<p><b>○ 이승철 위원 </b> 제가 연구하신 것에 대해서는 저기 하는데 비상활주로, 지금 수원에 있는 비상활주로 여태 한 번도 사용한 적이 없는 비상활주로거든요. 그런데 그 비상활주로를 그냥 해지하는 게 아니라 비상활주로를 해지함과 동시에 비행장 안에다가 활주로를 또 만듭니다. 그 비용부담을 가지고 MOU가 예정이다 이렇게 얘기 하는 거거든요. 그런데 이것을 제시했다고 그러는데 방안제시는 좋은데 원장님께서 생각해 보실 때 비상활주로라고 그러면 비상활주로가 비행장에다 설치하면 비상활주로는라는 게 말 자체가 비상활주로, 그 비행장이 폭격이 됐을 경우에 다른 데에 비상활주로가 있거든요. 다른 데 타 비행장 보면 다 나와 있지만 반경 5㎞~20㎞ 이상 다 떨어져 있습니다. 그런데 이것을 군부대에서 안 해준다고 그래서 극약처방식으로 일단 주민들을 보호하기 위해서 사실은 이것을 채택한 거거든요. 그래서 했는데 결과적으로 이게 안으로 들어갔단 말입니다, 비상활주로라고 해 갖고.
