<p><b>○ 부원장 조응래 </b> 부원장 조응래입니다. 수원비행장 비상활주로 계획은 사실은 도에서도 약간의 논란은 있습니다. 그래서 당초에 시화호에 에어파크계획이 있기 때문에 거기에 비상활주로를 같이 건설하는 게 어떻겠느냐, 한 190억 정도가 소요되는데요. 그런데 지금 현재로서는 시화호에 만들려고 하는 에어파크가 인천공항 비행기 진입에 따른 공여계획 상충 이런 것들 때문에 지금 현재는 수원비행장에 비상활주로를 건설하는 것으로 지금 협의는 되고 있습니다. 그런데 과연 그게 바람직한 대안인지 그 부분에 대해서는 사실 저희가 별도로 검토하고 있는 게 있습니다. 그래서 도에다가는 허종준 초빙연구원께서 그러한 문제들 때문에 아무래도 수원비행장 안에다가 비상활주로를 만드는 게 좋겠다라는 그런 의견은 제시를 했는데 그 방안도 과연 190억을 어떻게 활용하는 게 좋을지는 조금 더 검토하고 있습니다. 
</p>
<p><b>○ 이승철 위원 </b> 제가 말씀드리는 거는 안에다가 비상활주로를 만들게 되는데 비용이 별로 얼마 안 들어가는 거라면 큰 문제가 아닌데요. 아시다시피 지금 거기 새로 깔아달라고 그러거든요, 부대에서. 그 비용이 지금 굉장히 많잖아요. 그것도 200억 정도 예산 하잖아요? 그러면 이거 깔고 나서 조금 이따 또 옮겨가는 건 말도 안 되잖아요. 
