<p><b>○ 부원장 조응래 </b> 일단은 지금 예산이 어떻게 편성이 될 건지 이 부분들은 저희가 조금 더 확인을 하고요. 지금 저희 생각에는 아직까지 약간의 시간은 있다라고 판단하고 있고 그래서 에어파크 건설의 문제라든지, 사실은 에어파크가 한 500억 정도 국비 포함해서 들어가는데 경기도에서 그 정도 190억을 들여서 비상활주로를 수원 기존 비행장 내에다 건설을 하는 게 좋을지, 아니면 제3의 장소를 만들어서 거기서 에어쇼도 하면서 에어파크를 만드는 게 좋을지는 지금 조금 검토를 하고 있습니다. 
