<p><b>○ 이승철 위원 </b> 기간이 좀 있으니까 제가 봤을 때 비상활주로를 지금까지 자주 사용을 해봤으면 문제가 틀린데 지금까지 수십 년간 한 번도 사용하지 않은 비상활주로를 계속, 옮기는 기간 안에 새로 만들어 놓고 또 옮긴다는 것은 진짜 예산낭비입니다. 그냥 사실 도민들을 위해서, 시민들을 위해서 잠깐 비상활주로를 접고 현재 있는 활주로를 사용하면서 돈을 거기다 투자하지 말고 그 돈으로는 지금 말씀하셨던 데다가 투자를 한다면 예산이 정확하게 쓰여진다고 보거든요. 그런데 지금 여기다 다시 하고 또 간다는 건 정말로 잘못된 예산이다라는 걸 연구하실 때 강력하게 말씀해 주십사 하는 말씀 드리겠습니다. 
