<p><b>○ 김주삼 위원 </b> 배려입니다. 북부지역에 대한 배려고 지금까지, 그러니까 경기도의 남부지역과 북부지역이 균형 있게 발전을 하자 그런 의미거든요. 김문수 지사께서 하시는 기본적인 배려가. 왜냐하면 교통건설국이 의정부로 옮겨감에 따른 직원들의 반발이 굉장히 만만치가 않았어요. 노조에서의 의견도. 그럼에도 불구하고 우리 기획 위원들이 거기에 찬성을 했고 의회에서 동의를 해준 것은 기본적으로 경기도 지역의 균형적 발전을 위해서 그렇게 한 거거든요, 큰 취지에 동의를 해서. 그런 의미로 세종시도 저는 그렇게 바라봐야 되지 않겠느냐.
