<p style="padding-left:1.2em">  저는 그래서 어차피 우리 사회는 지금 좌우의 어떤 논리싸움이나 좌우 대립으로 생각……. 정말 좌파의 어떤 정책도 좋으면 적극적으로 받아들이는 겁니다, 우리 사회가. 저는 그런데 우리 경기도만큼은……. 또 더 유감스러운 건 무상급식을 우리 김문수 지사께서 안 받아들이면서, 그렇게 사회주의 논리라고 하면서 반대하시면서 같은 논리의 무료예방접종계획은 지금 추진하고 계신단 말이에요. 그래서 원장님께서 연구원들하고 함께 무료예방접종계획 이런 논리들을 어쨌든 앞으로 이게 저희가……. 그런 논리로 무상급식도 함께 바라보시고 시각도 좀 교정해 주시고 그래야 됩니다. 이게 무상급식이 좌파논리라 그러면 무상교육도 다 좌파논리고요. 대한민국에 지금 좌파, 잘 아시겠지만 사회주의 좌파논리, 좌파정책 빼고 나면 실제 대한민국에 제대로 펼 정책 없습니다. 펴고 있는 정책. 어쨌든 자본주의의 부족한 점을 계속 사회주의 논리나 그런 걸로 메워가고 있잖아요. 그래서 사실은 핀란드나 노르웨이 같은 나라는 7만 불, 8만 불 그렇게 최선진국이 돼 있는 거고. 저는 그래서 앞으로 무상급식도 그렇게 접근을 해주셨으면 하는 바람입니다.
