<p><b>○ 김주삼 위원 </b> 글쎄요. 이게 보고가 됐습니까? 저희 위원회에요. 지난번 8월 달에 업무보고 할 때…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그때가 위원님들이 5기가 시작됐을 때는 이미 다 정리가 된 사안이라서…….
</p>
<p><b>○ 김주삼 위원 </b> 그럼 그전에 의회에 보고가 돼 있습니까? 
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 그때는 기획위원회에 다 동의를 받고 저희가…….
</p>
<p><b>○ 김주삼 위원 </b> 그럼 언제 보고를 했습니까? 동의를 했습니까?
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 작년에 이미 계획이 다 돼 가지고 기획위원회의 지지가 없었으면 저희가 할 수가 없었을 거라고 생각하는데요. 그때 이거 가지고 논란이 많았는데 결국 경투위원회에서 관리하는 걸로 해 가지고 그 산하기관으로 바뀌고 이렇게 됐습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 그러니까 그쪽으로 가는 건 방금 설명대로 조례에 의해서 갔는데 이런 내용들이 올해 4월 달에 갔으면 예를 들어서 뭐……. 좋습니다. 그 앞전, 그러니까 7대……. 들어가십시오. 위원님들에게 보고가 됐다고 그러시는데 그럼 그게 정확하게 어떤 형태로 보고가 됐는지 기억이 안 돼요? 이게 이렇게 중차대하게 몇백억 예산인데 그게 넘어가서 보고할 때 그런 정도는…….
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 작년에 행정사무감사 할 때 이미 계획이 다 보고가 됐었고요. 이사회…….
</p>
<p><b>○ 김주삼 위원 </b> 행정사무감사가 아니고 업무보고나 그럴 때 됐던 거겠죠. 감사 때 보고할 사항은 아니니까.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 좌우간 저희가 기획위원회에 보고를 다 했습니다. 좌우간 저희가, 저희 불찰이 있다면 5기가 시작됐을 때 저희가 이 문제를 지나간 일이라고 하지만 금년 사안이기 때문에 한번 보고를 올렸어야 됐는데 그걸 못했습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 자료를 검토하는 과정에서 이게 있어서 전혀 좀 생소하고 그래서 질문을 드렸는데, 좋습니다. 그러면 이 관련 자료를 서면으로 제출을 해주시기 바랍니다. 이게 언제 넘어갔는지.
</p>
<p><b>○ 경기개발연구원장 좌승희 </b> 알겠습니다. 
</p>
<p><b>○ 김주삼 위원 </b> 알겠습니다. 이상으로 마치겠습니다. 
</p>
<p><b>○ 위원장 강득구 </b> 감사합니다. 그러면 더 이상 질의하실 위원님 안 계시죠? 
</p>
<p style="padding-left:2.4em">    (「네.」하는 위원 있음)
</p>
<p style="padding-left:1.2em">  더 이상 질의하실 위원이 안 계시므로 오늘 경기개발연구원 소관에 대한 질의와 답변을 모두 마치겠습니다. 
</p>
<p style="padding-left:1.2em">  위원 여러분 그리고 좌승희 경기개발연구원장을 비롯한 임직원 여러분! 장시간 열의를 갖고 행정사무감사에 임해 주신 위원 여러분과 행정사무감사를 위한 자료준비와 위원님들의 질의에 성의껏 답변해 주신 연구원 좌승희 원장님을 비롯한 임직원 여러분께 감사드립니다. 
</p>
<p style="padding-left:1.2em">  제가 오늘 행정사무감사를 준비하면서 경기개발연구원이 경기도의 착시를 막아주는 레이더 역할을 해줬으면 좋겠다라는 얘기를 했습니다. 그런 기조로 행감 사회를 봤습니다. 우리 열한 분 위원님을 뽑아준 도민들도 폭로나 정쟁을 지양하고 경기도민의 입장에서 경기개발연구원의 여러 가지 현안을 우리 연구원 임직원들과 같이 고민하고 토론하면서 접점을 찾고 대안을 만들어서 그것이 궁극적으로 우리 경기도민의 삶의 질 향상에 조금이라도 도움이 됐으면 좋겠다라는 것이 소박한 바람일 겁니다. 아무쪼록 오늘 하루가 그런 하루였으면 좋겠습니다. 
</p>
<p style="padding-left:1.2em">  이상으로 오늘 경기개발연구원 감사를 모두 마치도록 하겠습니다. 수고하셨습니다. 
</p>
<p class=''ar''>(18시20분 감사종료)
</p>
<p><hr /></p>
